INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-237-2', 'doc-card-237', 'sec-card-237-2', 2, '۱. بنیان و منطق نظری نت‌نوگرافی «روش» را «بافت» «معنا» می‌داند: نه «ابزار» «تحلیل» بلکه «بافت» «تحلیل». رابرت کوزینتس (۲۰۰۲) در این چارچوب، «روش» را «بافت» «معرفت» تعریف کرد: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش».  بر اساس نت‌نوگرافی، «روش» «دیالکتیک» «نظریه» و «داده» است: «نظریه»، «بافت» «تحلیل» است و «داده»، «بافت» «نظریه». رابرت کوزینتس (۲۰۰۲) در این چارچوب، «روش» را «بافت» «اعتماد» تعریف کرد: «اعتماد» در «روش» «ساخته» می‌شود، نه در «نتیجه».  نت‌نوگرافی را می‌توان پاسخی به شکاف میان «روش» «کمّی» (تعمیم) و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش».', '04c960faa3c1fe8e44242264d9bc07a4f075acc55d683ff9a8adbe3195b19a09', 1094, 'ch-doc-card-237-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='04c960faa3c1fe8e44242264d9bc07a4f075acc55d683ff9a8adbe3195b19a09', token_count=1094, vector_point_id='ch-doc-card-237-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-237-3', 'doc-card-237', 'sec-card-237-2', 3, 'و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش». رابرت کوزینتس (۲۰۰۲) در این چارچوب، «روش» را «بافت» «بازی» تعریف کرد: «تحلیل»، «بازی» با «داده» است.  ۲. ساختارهای مفهومی • روش کمّی (Quantitative Method): «اندازه‌گیری» و «تعمیم»: «داده» «عددی» و «تحلیل» «آمار». • روش کیفی (Qualitative Method): «فهم» و «عمق»: «داده» «کیفی» و «تحلیل» «تفسیر». • روش ترکیبی (Mixed Methods): «ترکیب» «کمّی» و «کیفی»: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • پیمایش (Survey): «اندازه‌گیری» «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته». • تحلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن».', 'dd9f1a254f0a50f6bed0333a79d60d1bec649674ffa9cb255f4e852a41afb512', 1165, 'ch-doc-card-237-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='dd9f1a254f0a50f6bed0333a79d60d1bec649674ffa9cb255f4e852a41afb512', token_count=1165, vector_point_id='ch-doc-card-237-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-237-4', 'doc-card-237', 'sec-card-237-2', 4, 'حلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن». • نظریه داده بنیادین (Grounded Theory): «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود. • قوم‌نگاری (Ethnography): «فهم» «بافت»: «حضور» در «بافت» و «فهم» «معنا» در', 'f64d4e55a385372aa15bb9447a61043906433409a92a2985a2a7d0e0bc878019', 459, 'ch-doc-card-237-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f64d4e55a385372aa15bb9447a61043906433409a92a2985a2a7d0e0bc878019', token_count=459, vector_point_id='ch-doc-card-237-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-237-5', 'doc-card-237', 'sec-card-237-3', 5, 'مشاهده‌ی آنلاین؛ جامعه‌ی گفتمان؛ نمادها و آیین‌ها؛ افشای هویت پژوهشگر؛ اخلاق داده‌ی عمومی؛ اعتبار قوم‌نگارانه.', '68d83b3edeffc357f9665376f78a3bb1500df1272573de8202840b8982e1f271', 199, 'ch-doc-card-237-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='68d83b3edeffc357f9665376f78a3bb1500df1272573de8202840b8982e1f271', token_count=199, vector_point_id='ch-doc-card-237-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-237-6', 'doc-card-237', 'sec-card-237-4', 6, '«بافت». • اعتبار و قابلیت اطمینان (Validity and Reliability): «اعتماد» در «روش»: «اعتبار» و «قابلیت اطمینان»، «بافت» «اعتماد» است.  ۳. نمونه‌های تحلیلی «روش کمّی» در عمل: «نظرسنجی» از «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته»: «تعمیم» «نتیجه» به «دسته».  «روش کیفی» در عمل: «مصاحبه» «عمیق» از «دسته‌ی» «کوچک»: «فهم» «معنا» در «بافت» «مصاحبه»: «عمق» «تحلیل».  «پیمایش» در عمل: «پیمایش» «نظر» «مخاطب» از «محتوای» «رسانه»: «سؤال» و «پاسخ» در «بافت» «دسته»: «تعمیم» «نتیجه».  «تحلیل محتوا» در عمل: «تحلیل» «متن» «خبر» از «چارچوب» و «واژه»: «کد» و «فراوانی» در «بافت» «متن»: «تحلیل» «ساختار» «متن».', '2df1aea8fac438976f616adb8d3c65aa46c2c08593ddb674d06b54aacae15007', 1092, 'ch-doc-card-237-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2df1aea8fac438976f616adb8d3c65aa46c2c08593ddb674d06b54aacae15007', token_count=1092, vector_point_id='ch-doc-card-237-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-237-7', 'doc-card-237', 'sec-card-237-4', 7, 'ز «چارچوب» و «واژه»: «کد» و «فراوانی» در «بافت» «متن»: «تحلیل» «ساختار» «متن».  «نظریه داده بنیادین» در عمل: «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود: «تحلیل»، «بازی» با «داده» است.  «قوم‌نگاری» در عمل: «حضور» در «بافت» «مخاطب»: «فهم» «معنا» در «بافت» «مخاطب»: «عمق» «تحلیل» در «بافت» «بومی».  ۴. نقدها و چالش‌ها ۱. «کمّی» و «کیفی» «دیالکتیک»‌اند: «کمّی» «تعمیم» دارد اما «عمق» ندارد و «کیفی» «عمق» دارد اما «تعمیم» ندارد: «روش» «ترکیبی»، «بافت» «دیالکتیک» است. ۲. «روش» و «نظریه» در هم تنیده‌اند: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش»: «روش» «خنثی» وجود ندارد. ۳.', '17842b057ad0f8425860f241c60fd05a93e47f100d43e207106133f550b126e1', 1076, 'ch-doc-card-237-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='17842b057ad0f8425860f241c60fd05a93e47f100d43e207106133f550b126e1', token_count=1076, vector_point_id='ch-doc-card-237-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-237-8', 'doc-card-237', 'sec-card-237-4', 8, '«روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش»: «روش» «خنثی» وجود ندارد. ۳. «اعتبار» در «روش» «کیفی» «سنجش‌پذیر» نیست: «اعتماد» در «بافت» «تحلیل» «ساخته» می‌شود و «اندازه‌گیری» آن «دشواری» است. ۴. «پیمایش» و «بافت»: «سؤال» در «پیمایش»، «بافت» «تحلیل» است: «سؤال» «بافت» «پاسخ» را «تعیین» می‌کند: «ر', 'fd90868d4d812309680cd540e5e01e35295be937b00e6267a1c97fd5b9be4b8d', 547, 'ch-doc-card-237-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fd90868d4d812309680cd540e5e01e35295be937b00e6267a1c97fd5b9be4b8d', token_count=547, vector_point_id='ch-doc-card-237-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-237-9', 'doc-card-237', 'sec-card-237-5', 9, 'مطالعه‌ی انجمن‌های طرفداران یک برند یا گروه‌های سلامت آنلاین برای فهم هنجارها و زبان مشترک.', '3916b7158daf76a56aac932e3957022b67463dcecf7d59edcb35938da8b4eafd', 165, 'ch-doc-card-237-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3916b7158daf76a56aac932e3957022b67463dcecf7d59edcb35938da8b4eafd', token_count=165, vector_point_id='ch-doc-card-237-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-237-10', 'doc-card-237', 'sec-card-237-6', 10, 'مرز میان محتوای عمومی و خصوصی در بسترهای آنلاین مبهم است. هویت کاربران اغلب ناشناخته است و تعمیم یافته‌ها محدود می‌ماند.', '4ce945fb4bb248191c3b4a3977b8efd7d5ecd0b2e451b6d66c761c1668d49edd', 218, 'ch-doc-card-237-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4ce945fb4bb248191c3b4a3977b8efd7d5ecd0b2e451b6d66c761c1668d49edd', token_count=218, vector_point_id='ch-doc-card-237-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-237-11', 'doc-card-237', 'sec-card-237-10', 11, 'کتاب «روش پژوهش در ارتباطات» (بیر و همکاران، ۲۰۰۸)؛ کتاب «تحلیل محتوا» (هایرینگ، ۱۹۶۷)؛ کتاب «نظریه داده بنیادین» (گلایزر و استرأس، ۱۹۶۷)؛ کتاب «قوم‌نگاری و فرهنگ» (انول، ۱۹۸۴).', 'f40602f4e73937c5ab57d913729cc1b6482b7e5ff6a6c5988096f450bd7988a5', 321, 'ch-doc-card-237-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f40602f4e73937c5ab57d913729cc1b6482b7e5ff6a6c5988096f450bd7988a5', token_count=321, vector_point_id='ch-doc-card-237-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-238-0', 'doc-card-238', NULL, 0, 'این مطالعه نشان داد که تغییر در نمایش پست‌های هیجانی در خوراک خبری کاربران، احساسات نوشته‌شده‌ی خودِ آنان را تغییر می‌دهد. آزمایش بدون رضایت آگاهانه انجام شد و بحث‌های گسترده‌ای درباره‌ی مشروعیت اخلاقی و مرز مداخله‌ی پلتفرم‌ها به‌وجود آورد.', 'fa940373d5d7b07cdfad84e7e2c6ef1e7eb7659f4a9146729600f4a52513c8e7', 436, 'ch-doc-card-238-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fa940373d5d7b07cdfad84e7e2c6ef1e7eb7659f4a9146729600f4a52513c8e7', token_count=436, vector_point_id='ch-doc-card-238-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-238-1', 'doc-card-238', 'sec-card-238-1', 1, 'روش‌شناسی آزمایشی / اخلاق پژوهش  این مطالعه نشان داد که تغییر در نمایش پست‌های هیجانی در خوراک خبری کاربران، احساسات نوشته‌شده‌ی خودِ آنان را تغییر می‌دهد. آزمایش بدون رضایت آگاهانه انجام شد و بحث‌های گسترده‌ای درباره‌ی مشروعیت اخلاقی و مرز مداخله‌ی پلتفرم‌ها به‌وجود آورد.', '05a08851e10e945e6d85cdd11ae2bfd9c50028b09318f2bd9a7054e96ff9c79a', 496, 'ch-doc-card-238-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='05a08851e10e945e6d85cdd11ae2bfd9c50028b09318f2bd9a7054e96ff9c79a', token_count=496, vector_point_id='ch-doc-card-238-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-238-2', 'doc-card-238', 'sec-card-238-2', 2, '۱. بنیان و منطق نظری سرایت هیجانی و اخلاق آزمایش‌های پلتفرمی «روش» را «بافت» «معنا» می‌داند: نه «ابزار» «تحلیل» بلکه «بافت» «تحلیل». آدام کرامر (۲۰۱۴) در این چارچوب، «روش» را «بافت» «معرفت» تعریف کرد: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش».  بر اساس سرایت هیجانی و اخلاق آزمایش‌های پلتفرمی، «روش» «دیالکتیک» «نظریه» و «داده» است: «نظریه»، «بافت» «تحلیل» است و «داده»، «بافت» «نظریه». آدام کرامر (۲۰۱۴) در این چارچوب، «روش» را «بافت» «اعتماد» تعریف کرد: «اعتماد» در «روش» «ساخته» می‌شود، نه در «نتیجه».', '478e7692cfd144bb8dc626048f167fe17f7210a9ceefaf607a1a3ea666028e1a', 930, 'ch-doc-card-238-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='478e7692cfd144bb8dc626048f167fe17f7210a9ceefaf607a1a3ea666028e1a', token_count=930, vector_point_id='ch-doc-card-238-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-238-3', 'doc-card-238', 'sec-card-238-2', 3, 'را «بافت» «اعتماد» تعریف کرد: «اعتماد» در «روش» «ساخته» می‌شود، نه در «نتیجه».  سرایت هیجانی و اخلاق آزمایش‌های پلتفرمی را می‌توان پاسخی به شکاف میان «روش» «کمّی» (تعمیم) و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش». آدام کرامر (۲۰۱۴) در این چارچوب، «روش» را «بافت» «بازی» تعریف کرد: «تحلیل»، «بازی» با «داده» است.  ۲. ساختارهای مفهومی • روش کمّی (Quantitative Method): «اندازه‌گیری» و «تعمیم»: «داده» «عددی» و «تحلیل» «آمار». • روش کیفی (Qualitative Method): «فهم» و «عمق»: «داده» «کیفی» و «تحلیل» «تفسیر». • روش ترکیبی (Mixed Methods): «ترکیب» «کمّی» و «کیفی»: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند.', 'e0790925efc5ef9d9f951fad9d4835c2693383d2c902ead84505fac29d6d9cff', 1167, 'ch-doc-card-238-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e0790925efc5ef9d9f951fad9d4835c2693383d2c902ead84505fac29d6d9cff', token_count=1167, vector_point_id='ch-doc-card-238-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-238-4', 'doc-card-238', 'sec-card-238-2', 4, 'thods): «ترکیب» «کمّی» و «کیفی»: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • پیمایش (Survey): «اندازه‌گیری» «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته». • تحلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن». • نظریه داده بنیادین (Grounded Theory): «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود. • قوم‌نگاری (Ethnography): «فهم»', '38eaa6f3506cc057d4fca8b6c86e8689a95b9b0a9825d360f8d239d0befb7893', 685, 'ch-doc-card-238-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='38eaa6f3506cc057d4fca8b6c86e8689a95b9b0a9825d360f8d239d0befb7893', token_count=685, vector_point_id='ch-doc-card-238-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-238-5', 'doc-card-238', 'sec-card-238-3', 5, 'سرایت هیجانی؛ آزمایش میدانی بزرگ‌مقیاس؛ رضایت آگاهانه؛ حساسیت داده‌ها؛ مسئولیت پلتفرم؛ شفافیت پژوهش.', '283c72dbcb7e820dcebab485cefb3172a8b5c49e93b69d180f0ce961968b684d', 181, 'ch-doc-card-238-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='283c72dbcb7e820dcebab485cefb3172a8b5c49e93b69d180f0ce961968b684d', token_count=181, vector_point_id='ch-doc-card-238-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-238-6', 'doc-card-238', 'sec-card-238-4', 6, '«بافت»: «حضور» در «بافت» و «فهم» «معنا» در «بافت». • اعتبار و قابلیت اطمینان (Validity and Reliability): «اعتماد» در «روش»: «اعتبار» و «قابلیت اطمینان»، «بافت» «اعتماد» است.  ۳. نمونه‌های تحلیلی «روش کمّی» در عمل: «نظرسنجی» از «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته»: «تعمیم» «نتیجه» به «دسته».  «روش کیفی» در عمل: «مصاحبه» «عمیق» از «دسته‌ی» «کوچک»: «فهم» «معنا» در «بافت» «مصاحبه»: «عمق» «تحلیل».  «پیمایش» در عمل: «پیمایش» «نظر» «مخاطب» از «محتوای» «رسانه»: «سؤال» و «پاسخ» در «بافت» «دسته»: «تعمیم» «نتیجه».  «تحلیل محتوا» در عمل: «تحلیل» «متن» «خبر» از «چارچوب» و «واژه»: «کد» و «فراوانی» در «بافت» «متن»: «تحلیل» «ساختار» «متن».', '32acade018a924acc1113b657862e06a72012c76f5de3c776d9e9cac4f58eaf2', 1170, 'ch-doc-card-238-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='32acade018a924acc1113b657862e06a72012c76f5de3c776d9e9cac4f58eaf2', token_count=1170, vector_point_id='ch-doc-card-238-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-238-7', 'doc-card-238', 'sec-card-238-4', 7, 'ز «چارچوب» و «واژه»: «کد» و «فراوانی» در «بافت» «متن»: «تحلیل» «ساختار» «متن».  «نظریه داده بنیادین» در عمل: «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود: «تحلیل»، «بازی» با «داده» است.  «قوم‌نگاری» در عمل: «حضور» در «بافت» «مخاطب»: «فهم» «معنا» در «بافت» «مخاطب»: «عمق» «تحلیل» در «بافت» «بومی».  ۴. نقدها و چالش‌ها ۱. «کمّی» و «کیفی» «دیالکتیک»‌اند: «کمّی» «تعمیم» دارد اما «عمق» ندارد و «کیفی» «عمق» دارد اما «تعمیم» ندارد: «روش» «ترکیبی»، «بافت» «دیالکتیک» است. ۲. «روش» و «نظریه» در هم تنیده‌اند: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش»: «روش» «خنثی» وجود ندارد. ۳.', '17842b057ad0f8425860f241c60fd05a93e47f100d43e207106133f550b126e1', 1076, 'ch-doc-card-238-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='17842b057ad0f8425860f241c60fd05a93e47f100d43e207106133f550b126e1', token_count=1076, vector_point_id='ch-doc-card-238-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-238-8', 'doc-card-238', 'sec-card-238-4', 8, '«روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش»: «روش» «خنثی» وجود ندارد. ۳. «اعتبار» در «روش» «کیفی» «سنجش‌پذیر» نیست: «اعتماد» در «بافت» «تحلیل» «ساخته» می‌شود و «اندازه‌گیری» آن «دشواری» است. ۴. «پیمایش» و «بافت»: «سؤال» در «پیمایش»، «بافت» «تحلیل» است: «سؤال» «بافت» «پاسخ» را «تعیین» می‌', '4b2f438cc212f31f4e371b28abc79c6f9a5880b4a287390c122a64b9cacf7c18', 534, 'ch-doc-card-238-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4b2f438cc212f31f4e371b28abc79c6f9a5880b4a287390c122a64b9cacf7c18', token_count=534, vector_point_id='ch-doc-card-238-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-238-9', 'doc-card-238', 'sec-card-238-5', 9, 'استفاده‌ی پلتفرم‌ها از آزمایش‌های A/B بدون اطلاع کاربران و پرسش درباره‌ی حد مجاز مداخله‌ی آن‌ها.', '2dd3cf4f88345662cac3aac98b3d8da7b542352a20a3b80283b6fbb44d02340e', 174, 'ch-doc-card-238-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2dd3cf4f88345662cac3aac98b3d8da7b542352a20a3b80283b6fbb44d02340e', token_count=174, vector_point_id='ch-doc-card-238-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-238-10', 'doc-card-238', 'sec-card-238-6', 10, 'اندازه‌ی اثر کوچک بود و تفسیر آن درباره‌ی «سرایت» مورد اختلاف است. همچنین تعمیم این یافته به همه‌ی بسترها دشوار است.', '729bcb7f047175555df9657f1c7eda1259142e1c0a43e4e1581ba4ad79506593', 210, 'ch-doc-card-238-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='729bcb7f047175555df9657f1c7eda1259142e1c0a43e4e1581ba4ad79506593', token_count=210, vector_point_id='ch-doc-card-238-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-238-11', 'doc-card-238', 'sec-card-238-10', 11, 'کتاب «روش پژوهش در ارتباطات» (بیر و همکاران، ۲۰۰۸)؛ کتاب «تحلیل محتوا» (هایرینگ، ۱۹۶۷)؛ کتاب «نظریه داده بنیادین» (گلایزر و استرأس، ۱۹۶۷)؛ کتاب «قوم‌نگاری و فرهنگ» (انول، ۱۹۸۴).', 'f40602f4e73937c5ab57d913729cc1b6482b7e5ff6a6c5988096f450bd7988a5', 321, 'ch-doc-card-238-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f40602f4e73937c5ab57d913729cc1b6482b7e5ff6a6c5988096f450bd7988a5', token_count=321, vector_point_id='ch-doc-card-238-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-239-0', 'doc-card-239', NULL, 0, 'جان کرسول می‌گوید پژوهش ترکیبی داده‌های کمی و کیفی را در یک طرح منسجم به کار می‌گیرد تا هر روش نقاط ضعف دیگری را جبران کند. ترتیب اجرا (همزمان، متوالی یا تحول‌گرا) و نقطه‌ی تلفیق یافته‌ها، منطق کل پژوهش را تعیین می‌کند.', '560aba2ac8d99522b2dd3ac5eda7e87a70c42929726a385fe64c5cc1516c8f35', 398, 'ch-doc-card-239-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='560aba2ac8d99522b2dd3ac5eda7e87a70c42929726a385fe64c5cc1516c8f35', token_count=398, vector_point_id='ch-doc-card-239-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-239-1', 'doc-card-239', 'sec-card-239-1', 1, 'روش‌شناسی پژوهش / طرح‌های ترکیبی  پژوهش ترکیبی داده‌های کمی و کیفی را در یک طرح منسجم به کار می‌گیرد تا هر روش نقاط ضعف دیگری را جبران کند. ترتیب اجرا (همزمان، متوالی یا تحول‌گرا) و نقطه‌ی تلفیق یافته‌ها تعیین‌کننده‌ی منطق پژوهش است.', 'd7a90a4ddebb6798490178b5c29686c3b150b4e3372343908296f9d12188c0fb', 423, 'ch-doc-card-239-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d7a90a4ddebb6798490178b5c29686c3b150b4e3372343908296f9d12188c0fb', token_count=423, vector_point_id='ch-doc-card-239-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-239-2', 'doc-card-239', 'sec-card-239-2', 2, '۱. بنیان و منطق نظری روش‌های ترکیبی «روش» را «بافت» «معنا» می‌داند: نه «ابزار» «تحلیل» بلکه «بافت» «تحلیل». جان کرسول (۲۰۰۷) در این چارچوب، «روش» را «بافت» «معرفت» تعریف کرد: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش».  بر اساس روش‌های ترکیبی، «روش» «دیالکتیک» «نظریه» و «داده» است: «نظریه»، «بافت» «تحلیل» است و «داده»، «بافت» «نظریه». جان کرسول (۲۰۰۷) در این چارچوب، «روش» را «بافت» «اعتماد» تعریف کرد: «اعتماد» در «روش» «ساخته» می‌شود، نه در «نتیجه».  روش‌های ترکیبی را می‌توان پاسخی به شکاف میان «روش» «کمّی» (تعمیم) و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش».', 'e31ed23395624124006787d623b5297096d4e8590896500c4caadc2e793cfd32', 1101, 'ch-doc-card-239-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e31ed23395624124006787d623b5297096d4e8590896500c4caadc2e793cfd32', token_count=1101, vector_point_id='ch-doc-card-239-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-239-3', 'doc-card-239', 'sec-card-239-2', 3, 'و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش». جان کرسول (۲۰۰۷) در این چارچوب، «روش» را «بافت» «بازی» تعریف کرد: «تحلیل»، «بازی» با «داده» است.  ۲. ساختارهای مفهومی • روش کمّی (Quantitative Method): «اندازه‌گیری» و «تعمیم»: «داده» «عددی» و «تحلیل» «آمار». • روش کیفی (Qualitative Method): «فهم» و «عمق»: «داده» «کیفی» و «تحلیل» «تفسیر». • روش ترکیبی (Mixed Methods): «ترکیب» «کمّی» و «کیفی»: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • پیمایش (Survey): «اندازه‌گیری» «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته». • تحلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن».', 'eedad3b95fd54559d98e04c37fbba16ffed854a3c63ff0e9eb1f03380808e328', 1158, 'ch-doc-card-239-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='eedad3b95fd54559d98e04c37fbba16ffed854a3c63ff0e9eb1f03380808e328', token_count=1158, vector_point_id='ch-doc-card-239-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-239-4', 'doc-card-239', 'sec-card-239-2', 4, 'حلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن». • نظریه داده بنیادین (Grounded Theory): «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود. • قوم‌نگاری (Ethnography): «فهم» «بافت»: «حضور» در «بافت» و «فهم» «معنا» در', 'f64d4e55a385372aa15bb9447a61043906433409a92a2985a2a7d0e0bc878019', 459, 'ch-doc-card-239-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f64d4e55a385372aa15bb9447a61043906433409a92a2985a2a7d0e0bc878019', token_count=459, vector_point_id='ch-doc-card-239-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-239-5', 'doc-card-239', 'sec-card-239-3', 5, 'طرح همزمان یا متوالی؛ نقطه‌ی تلفیق؛ اولویت کمی یا کیفی؛ ارتباط با پرسش پژوهش؛ یکپارچگی تفسیری.', 'd90c02423eacde72a24ba794ccebd4ee03ebcdeaff7d1dffa4cae9bf745ea4c2', 170, 'ch-doc-card-239-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d90c02423eacde72a24ba794ccebd4ee03ebcdeaff7d1dffa4cae9bf745ea4c2', token_count=170, vector_point_id='ch-doc-card-239-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-239-6', 'doc-card-239', 'sec-card-239-4', 6, '«بافت». • اعتبار و قابلیت اطمینان (Validity and Reliability): «اعتماد» در «روش»: «اعتبار» و «قابلیت اطمینان»، «بافت» «اعتماد» است.  ۳. نمونه‌های تحلیلی «روش کمّی» در عمل: «نظرسنجی» از «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته»: «تعمیم» «نتیجه» به «دسته».  «روش کیفی» در عمل: «مصاحبه» «عمیق» از «دسته‌ی» «کوچک»: «فهم» «معنا» در «بافت» «مصاحبه»: «عمق» «تحلیل».  «پیمایش» در عمل: «پیمایش» «نظر» «مخاطب» از «محتوای» «رسانه»: «سؤال» و «پاسخ» در «بافت» «دسته»: «تعمیم» «نتیجه».  «تحلیل محتوا» در عمل: «تحلیل» «متن» «خبر» از «چارچوب» و «واژه»: «کد» و «فراوانی» در «بافت» «متن»: «تحلیل» «ساختار» «متن».', '2df1aea8fac438976f616adb8d3c65aa46c2c08593ddb674d06b54aacae15007', 1092, 'ch-doc-card-239-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2df1aea8fac438976f616adb8d3c65aa46c2c08593ddb674d06b54aacae15007', token_count=1092, vector_point_id='ch-doc-card-239-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-239-7', 'doc-card-239', 'sec-card-239-4', 7, 'ز «چارچوب» و «واژه»: «کد» و «فراوانی» در «بافت» «متن»: «تحلیل» «ساختار» «متن».  «نظریه داده بنیادین» در عمل: «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود: «تحلیل»، «بازی» با «داده» است.  «قوم‌نگاری» در عمل: «حضور» در «بافت» «مخاطب»: «فهم» «معنا» در «بافت» «مخاطب»: «عمق» «تحلیل» در «بافت» «بومی».  ۴. نقدها و چالش‌ها ۱. «کمّی» و «کیفی» «دیالکتیک»‌اند: «کمّی» «تعمیم» دارد اما «عمق» ندارد و «کیفی» «عمق» دارد اما «تعمیم» ندارد: «روش» «ترکیبی»، «بافت» «دیالکتیک» است. ۲. «روش» و «نظریه» در هم تنیده‌اند: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش»: «روش» «خنثی» وجود ندارد. ۳.', '17842b057ad0f8425860f241c60fd05a93e47f100d43e207106133f550b126e1', 1076, 'ch-doc-card-239-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='17842b057ad0f8425860f241c60fd05a93e47f100d43e207106133f550b126e1', token_count=1076, vector_point_id='ch-doc-card-239-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-239-8', 'doc-card-239', 'sec-card-239-4', 8, '«روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش»: «روش» «خنثی» وجود ندارد. ۳. «اعتبار» در «روش» «کیفی» «سنجش‌پذیر» نیست: «اعتماد» در «بافت» «تحلیل» «ساخته» می‌شود و «اندازه‌گیری» آن «دشواری» است. ۴. «پیمایش» و «بافت»: «سؤال» در «پیمایش»، «بافت» «تحلیل» است: «سؤال» «بافت» «پاسخ» را «تعیین» می‌کند: «روش', '42e7876739a1888a3d6cdf5b6fa40632afe25246c0b627707e9fa75a58cbcb8c', 550, 'ch-doc-card-239-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='42e7876739a1888a3d6cdf5b6fa40632afe25246c0b627707e9fa75a58cbcb8c', token_count=550, vector_point_id='ch-doc-card-239-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-239-9', 'doc-card-239', 'sec-card-239-5', 9, 'ترکیب تحلیل محتوای کمی روزنامه‌ها با مصاحبه‌ی عمیق با سردبیران برای فهم علت تغییر الگوی پوشش خبری.', '1aa62bd17315687e3ea825bce2e9670d9854369ed85a1649ef483a5ee7bf5e13', 178, 'ch-doc-card-239-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1aa62bd17315687e3ea825bce2e9670d9854369ed85a1649ef483a5ee7bf5e13', token_count=178, vector_point_id='ch-doc-card-239-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-239-10', 'doc-card-239', 'sec-card-239-6', 10, 'تلفیق واقعی دو پارادایم معرفتی دشوار است و پژوهش‌ها اغلب تنها در ظاهر ترکیبی‌اند. زمان و منابع بیشتری لازم دارد.', '4c5fa2e4814e75488d0eeb9a1e8af9f41de7bc85b846d54aa2d1b2cf674354a9', 203, 'ch-doc-card-239-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4c5fa2e4814e75488d0eeb9a1e8af9f41de7bc85b846d54aa2d1b2cf674354a9', token_count=203, vector_point_id='ch-doc-card-239-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-239-11', 'doc-card-239', 'sec-card-239-10', 11, 'کتاب «روش پژوهش در ارتباطات» (بیر و همکاران، ۲۰۰۸)؛ کتاب «تحلیل محتوا» (هایرینگ، ۱۹۶۷)؛ کتاب «نظریه داده بنیادین» (گلایزر و استرأس، ۱۹۶۷)؛ کتاب «قوم‌نگاری و فرهنگ» (انول، ۱۹۸۴).', 'f40602f4e73937c5ab57d913729cc1b6482b7e5ff6a6c5988096f450bd7988a5', 321, 'ch-doc-card-239-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f40602f4e73937c5ab57d913729cc1b6482b7e5ff6a6c5988096f450bd7988a5', token_count=321, vector_point_id='ch-doc-card-239-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-24-0', 'doc-card-24', NULL, 0, 'انگیزه فرد برای حفاظت از خود از دو ارزیابی ناشی می‌شود: ارزیابی تهدید (شدت و آسیب‌پذیری) و ارزیابی مقابله (اثربخشی راه‌حل و خودکارآمدی). پیام ترس‌آور زمانی کارآمد است که با راه‌حل قابل‌اجرا همراه باشد.', 'b05d93059805b9dd116ed54a258e5df78fbbc3e75cbb5193b6c790f4eb5b5fb9', 365, 'ch-doc-card-24-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b05d93059805b9dd116ed54a258e5df78fbbc3e75cbb5193b6c790f4eb5b5fb9', token_count=365, vector_point_id='ch-doc-card-24-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-24-1', 'doc-card-24', 'sec-card-24-1', 1, 'ارتباطات سلامت / روانشناسی سلامت / جاذبه‌های ترس  انگیزه فرد برای حفاظت از خود از دو ارزیابی ناشی می‌شود: ارزیابی تهدید (شدت و آسیب‌پذیری) و ارزیابی مقابله (اثربخشی راه‌حل و خودکارآمدی). پیام ترس‌آور زمانی کارآمد است که با راه‌حل قابل‌اجرا همراه باشد.', 'a955b768cad8ae03d1a3daba2f4c046023cf1c9259bb7522da01511867243476', 456, 'ch-doc-card-24-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a955b768cad8ae03d1a3daba2f4c046023cf1c9259bb7522da01511867243476', token_count=456, vector_point_id='ch-doc-card-24-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-24-2', 'doc-card-24', 'sec-card-24-2', 2, '۱. بنیان و منطق نظری ادعای محوری نظریه انگیزش محافظت این است که مواجهه با پیام‌های رسانه‌ای می‌تواند ازطریق سازوکارهای روان‌شناختی و شناختی مشخص، باورها، نگرش‌ها و رفتارهای مخاطب را دگرگون کند. رونالد راجرز . مرتبط: مدل فرایند موازی گسترده EPPM (۱۹۷۵) کوشید دقیقاً مشخص کند کدام سازوکارها در عمل هستند و تحت چه شرایطی اثر رخ می‌دهد. در این سنت، اثر رسانه جادو نیست؛ فرایندی منظم است که شرایط مرزی آن — پیام، منبع، کانال و مخاطب — قابل شناسایی و آزمون است.  بر اساس نظریه انگیزش محافظت، اثرات رسانه یکدست و همگانی نیست، بلکه محدود و مشروط است. رونالد راجرز .', 'ac55f776f871a10dac59b57435e7667d2f7cae86c009b7208bb14a11885a4189', 1012, 'ch-doc-card-24-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ac55f776f871a10dac59b57435e7667d2f7cae86c009b7208bb14a11885a4189', token_count=1012, vector_point_id='ch-doc-card-24-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-24-3', 'doc-card-24', 'sec-card-24-2', 3, 'محافظت، اثرات رسانه یکدست و همگانی نیست، بلکه محدود و مشروط است. رونالد راجرز . مرتبط: مدل فرایند موازی گسترده EPPM (۱۹۷۵) تأکید کرد که فرد پیام را انفعالی دریافت نمی‌کند، بلکه بر اساس باورهای پیشین، انگیزه و اطلاعات در دسترس آن را پردازش می‌کند. قوت اثر رسانه به تناسب میان پیام و شرایط شناختی و انگیزشی مخاطب بستگی دارد و در بیشتر موارد، اثر در سطح «درباره‌ی چه چیزی فکر کنیم» و «چگونه به آن بنگریم» رخ می‌دهد، نه در سطح «به چه چیزی باور داشته باشیم».  نظریه انگیزش محافظت اثرات رسانه را فرایندی روان‌شناختی-اجتماعی می‌داند که در آن پیام، منبع و بستر اجتماعی با هم بر مخاطب اثر می‌گذارند. رونالد راجرز .', '55b56cf6d76506e3923ebac1fc5d5e0ac553ae5e82aeec16274fa278333125cd', 1100, 'ch-doc-card-24-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='55b56cf6d76506e3923ebac1fc5d5e0ac553ae5e82aeec16274fa278333125cd', token_count=1100, vector_point_id='ch-doc-card-24-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-24-4', 'doc-card-24', 'sec-card-24-2', 4, 'که در آن پیام، منبع و بستر اجتماعی با هم بر مخاطب اثر می‌گذارند. رونالد راجرز . مرتبط: مدل فرایند موازی گسترده EPPM (۱۹۷۵) مسیر شناختی و عاطفی که پیام از ادراک به تغییر نگرش را طی می‌کند تحلیل کرد و بر این نکته تأکید داشت که در فرایند اقناع، مقاومت، پادواژه‌سازی و بستر اجتماعی هم‌سنگِ خودِ محتوا اهمیت دارند.  ۲. ساختارهای مفهومی • مواجهه‌ی گزینشی (Selective Exposure): گرایشی که فرد را به انتخاب پیام‌های هم‌سو با باورهای پیشین خود سوق می‌دهد. • پردازش شناختی (Cognitive Processing): عمق پردازش ذهنی پیام و نقش آن در ماندگاری تغییر نگرش. • اعتبار منبع (Source Credibility): ادراک تخصص و اطمینان‌پذیری فرستنده و اثر آن بر اقناع.', '3018623ddc0de24cfa534f0d2957c93e3f1f4f4f195acb75f91bb61b8c264c90', 1143, 'ch-doc-card-24-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3018623ddc0de24cfa534f0d2957c93e3f1f4f4f195acb75f91bb61b8c264c90', token_count=1143, vector_point_id='ch-doc-card-24-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-24-5', 'doc-card-24', 'sec-card-24-2', 5, 'نبع (Source Credibility): ادراک تخصص و اطمینان‌پذیری فرستنده و اثر آن بر اقناع. • ترس‌افکنی (Fear Appeals): پیام‌هایی که ترس برانگیخت و اثر آن‌ها مشروط به ادراک کارآمدی راه‌حل است. • دانش اقناع (Persuasion Knowledge): آگاهی مخاطب از ماهیت اقناعی پیام و بیدار شدن مقاومت در برابر آن. • جریان دوشعویه (Two-Step Flow): انتقال اثر رسانه به مخاطبان ازطریق رهبران افکار و شبکه‌های بین‌فرد', '38f29850cd6f0fc2696171e7643341c4801c02460b780c2992d72a4847c1cadc', 694, 'ch-doc-card-24-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='38f29850cd6f0fc2696171e7643341c4801c02460b780c2992d72a4847c1cadc', token_count=694, vector_point_id='ch-doc-card-24-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-24-6', 'doc-card-24', 'sec-card-24-3', 6, 'شدت درک‌شده (Severity)؛ آسیب‌پذیری درک‌شده (Vulnerability)؛ پاداش درونی و بیرونی رفتار ناسالم؛ اثربخشی پاسخ (Response Efficacy)؛ خودکارآمدی (Self-Efficacy)؛ هزینه پاسخ (Response Cost). در EPPM: کنترل خطر (Danger Control) در برابر کنترل ترس (Fear Control).', '6aa7883dce10d534b138b098dda56c0467d7a0b41df58358a8452169ffced7a5', 463, 'ch-doc-card-24-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6aa7883dce10d534b138b098dda56c0467d7a0b41df58358a8452169ffced7a5', token_count=463, vector_point_id='ch-doc-card-24-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-24-7', 'doc-card-24', 'sec-card-24-4', 7, 'ی. • وابستگی به رسانه (Media Dependency): درجه‌ای که مخاطب در شرایط مشخص به رسانه به‌عنوان منبع جهت‌یابی تکیه می‌کند. • قوت نگرش (Attitude Strength): میزان پایداری و مقاومت یک نگرش در برابر تغییر توسط پیام‌های جدید.  ۳. نمونه‌های تحلیلی در یک کمپین واکسیناسیون، انتخاب منبع قابل‌اعتماد (پزشک به‌جای مقام رسمی) و تأکید بر کارآمدی راه‌حل به‌جای ترس‌افکنی ساده، کاربرد عملی سازوکارهای اعتبار منبع و شرایط ترس‌افکنی است.  در انتخابات، نامزدهایی که هفته‌ها بر رویدادهای خبری و ترندهای شبکه‌های اجتماعی سلطه دارند، کوشش نمی‌کنند رأی‌دهندگان «به چه چیزی باور کنند»، بلکه موضوعی را به صدر دستور ذهنی رای‌دهندگان می‌برند؛ استراتژی‌ای مبتنی بر بُعد شناختی اثر رسانه.', 'dfdd064746fd5873b07fe2169a73361758cadb6bf9d674a10bc2010380576682', 1192, 'ch-doc-card-24-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='dfdd064746fd5873b07fe2169a73361758cadb6bf9d674a10bc2010380576682', token_count=1192, vector_point_id='ch-doc-card-24-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-24-8', 'doc-card-24', 'sec-card-24-4', 8, 'در دستور ذهنی رای‌دهندگان می‌برند؛ استراتژی‌ای مبتنی بر بُعد شناختی اثر رسانه.  فردی که باور دارد «اقتصاد خوب است»، هنگام مواجهه با ویدیویی وایرال از گران‌شدن، ابتدا تفسیرهای هم‌سو با باور خود را می‌جستجو و سپس نگرشش را تعدیل می‌کند؛ نمونه‌ای که در آن باورهای پیشین و پردازش گزینشی جهت اثر را تعیین می‌کند.  در شبکه‌های اجتماعی، پیام سیاسی که لایک و شریک‌کردن فراوان می‌گیرد، «اثبات اجتماعی» می‌سازد که اثر اقناعی آن را بر مخاطبان مردد بزرگ‌تر می‌کند، حتی اگر محتوایش تازه نباشد.', 'bbab35ee938ed96b483a4633717efec32374d1d5ed025e10195c38faf1581057', 870, 'ch-doc-card-24-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bbab35ee938ed96b483a4633717efec32374d1d5ed025e10195c38faf1581057', token_count=870, vector_point_id='ch-doc-card-24-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-24-9', 'doc-card-24', 'sec-card-24-4', 9, 'ه اثر اقناعی آن را بر مخاطبان مردد بزرگ‌تر می‌کند، حتی اگر محتوایش تازه نباشد.  جوانی که مستند تغییر اقلیم می‌بیند ممکن است نگرشی کوتاه‌مدت بگیرد، اما اگر محیط اجتماعی او — خانواده، دوستان، محل کار — همان نگرش را نپذیرد، اثر در عرض چند هفته می‌خوابد؛ نمونه‌ی کلاسیک مشروط بودن اثر رسانه به بستر اجتماعی.  وقتی یک سلبریتی یک محصول را تأیید می‌کند، مخاطب بیشتر ازطریق دلبستگی عاطفی و ادراک شباهت با منبع تحت تأثیر قرار می‌گیرد تا ازطریق منطق استدلال؛ سازوکاری که در مسیر محیطی پردازش فعال می‌شود.  ۴. نقدها و چالش‌ها ۱.', '2d158f16533ebcad1ca08ee412b4fe2e26db1f6b380959af168a76b744ba6259', 939, 'ch-doc-card-24-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2d158f16533ebcad1ca08ee412b4fe2e26db1f6b380959af168a76b744ba6259', token_count=939, vector_point_id='ch-doc-card-24-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-24-10', 'doc-card-24', 'sec-card-24-4', 10, 'ق استدلال؛ سازوکاری که در مسیر محیطی پردازش فعال می‌شود.  ۴. نقدها و چالش‌ها ۱. مسئله اندازه‌ی اثر: آزمایش‌های آزمایشگاهی اغلب اثرهای کوچک و کوتاه‌مدت نشان می‌دهند، درحالی‌که در شرایط میدانی واقعی (مانند انتخابات) اثرها بزرگ‌تر و ماندگارتر به نظر می‌رسند؛ جمع‌بندی این دو مجموعه یافته دشوار است. ۲. جهت علیت: اثبات اینکه رسانه نگرش را تغییر داده است — نه اینکه فرد بر اساس نگرش پیشین رسانه‌اش را انتخاب کرده — به‌دلیل مواجهه‌ی گزینشی بسیار دشوار است. ۳. فرهنگی‌بودن نمونه‌ها: بیشتر یافته‌های کلاسیک از نمونه‌های غربی و ف', '7c3b1b306e1572f962c74dc5d8272e172f04845aa478ef007ce6dfeb72e91374', 945, 'ch-doc-card-24-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7c3b1b306e1572f962c74dc5d8272e172f04845aa478ef007ce6dfeb72e91374', token_count=945, vector_point_id='ch-doc-card-24-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-24-11', 'doc-card-24', 'sec-card-24-5', 11, 'کمپین‌های امنیت سایبری («رمز دومرحله‌ای را فعال کنید»)، پیام‌های ضد دخانیات و کمپین‌های سلامت. پیام ترساندن بدون ارائه گام عملی و قابل‌انجام، به انکار یا اجتناب منجر می‌شود.', 'd632d4583158c46c6bd40532127566e08d45c692c9ea4d8e0b54e0cb8692c59c', 314, 'ch-doc-card-24-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d632d4583158c46c6bd40532127566e08d45c692c9ea4d8e0b54e0cb8692c59c', token_count=314, vector_point_id='ch-doc-card-24-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-24-12', 'doc-card-24', 'sec-card-24-6', 12, 'شکاف قصد-رفتار؛ فراتحلیل‌ها (Floyd و همکاران ۲۰۰۰؛ Milne، Sheeran و Orbell ۲۰۰۰) اثر معنادار نشان می‌دهند ولی اثر ارزیابی تهدید معمولاً ضعیف‌تر از ارزیابی مقابله است. بیشتر شواهد خودگزارشی و کوتاه‌مدت است.', '63e2332757afae6535a7f0cfe076d12cdc207b0d485c9a9cbb4a93c67a9d8ea9', 372, 'ch-doc-card-24-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='63e2332757afae6535a7f0cfe076d12cdc207b0d485c9a9cbb4a93c67a9d8ea9', token_count=372, vector_point_id='ch-doc-card-24-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-24-13', 'doc-card-24', 'sec-card-24-10', 13, 'کتاب «نگرش‌ها و تغییر نگرش» (جان پتی، ۲۰۰۲)؛ کتاب «تأثیر: روان‌شناسی اقناع» (رابرت سیالدینی، ۱۹۸۴)؛ کتاب «اثرات رسانه‌های جمعی» (هوولاند، جانیز و کلی، ۱۹۵۳)؛ استناد مبنا: Petty & Cacioppo (1986) بر مدل قابلیت بسط.', '0553ef2ff323c489b3735af97eb1e64def88c12148bfd7f5935b714a6e4b0818', 387, 'ch-doc-card-24-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0553ef2ff323c489b3735af97eb1e64def88c12148bfd7f5935b714a6e4b0818', token_count=387, vector_point_id='ch-doc-card-24-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-240-0', 'doc-card-240', NULL, 0, 'چاکرباتی استدلال می‌کند که مفاهیم مدرن مانند دولت، عقلانیت و تاریخ‌نگاری پیشرفت، از تجربه‌ی اروپایی برآمده‌اند اما جهانی‌شده‌اند. او پیشنهاد می‌دهد این مفاهیم «ولایتی» شوند تا تجربه‌های تاریخی متفاوت مثل تاریخ جنوب آسیا بتوانند با منطق خودشان فهمیده شوند.', 'ef863a23bc047885fd8b35212e5814e5eb87504268f1c40abb562bcbf641b08b', 463, 'ch-doc-card-240-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ef863a23bc047885fd8b35212e5814e5eb87504268f1c40abb562bcbf641b08b', token_count=463, vector_point_id='ch-doc-card-240-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-240-1', 'doc-card-240', 'sec-card-240-1', 1, 'نظریه‌ی پسااستعماری / تاریخ‌نگاری و مطالعات رسانه  چاکرباتی استدلال می‌کند که مفاهیم مدرن مانند دولت، عقلانیت و تاریخ‌نگاری پیشرفت، از تجربه‌ی اروپایی برآمده‌اند اما جهانی‌شده‌اند. او پیشنهاد می‌دهد این مفاهیم «ولایتی» شوند تا تجربه‌های تاریخی متفاوت مثل تاریخ جنوب آسیا بتوانند با منطق خودشان فهمیده شوند.', '3eabeaf52e7c07cb4dad6768d7b81e75e4a2a0267a6965add7a0fb1faa352d1a', 556, 'ch-doc-card-240-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3eabeaf52e7c07cb4dad6768d7b81e75e4a2a0267a6965add7a0fb1faa352d1a', token_count=556, vector_point_id='ch-doc-card-240-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-240-2', 'doc-card-240', 'sec-card-240-2', 2, '۱. بنیان و منطق نظری ولایتی کردن اروپا «روش» را «بافت» «معنا» می‌داند: نه «ابزار» «تحلیل» بلکه «بافت» «تحلیل». دیپش چاکرباتی (۲۰۰۰) در این چارچوب، «روش» را «بافت» «معرفت» تعریف کرد: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش».  بر اساس ولایتی کردن اروپا، «روش» «دیالکتیک» «نظریه» و «داده» است: «نظریه»، «بافت» «تحلیل» است و «داده»، «بافت» «نظریه». دیپش چاکرباتی (۲۰۰۰) در این چارچوب، «روش» را «بافت» «اعتماد» تعریف کرد: «اعتماد» در «روش» «ساخته» می‌شود، نه در «نتیجه».  ولایتی کردن اروپا را می‌توان پاسخی به شکاف میان «روش» «کمّی» (تعمیم) و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش».', '3541bd59dc8aca2966459ca5497da1d7d94e3b933ef04493c8099bfc38f06de4', 1132, 'ch-doc-card-240-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3541bd59dc8aca2966459ca5497da1d7d94e3b933ef04493c8099bfc38f06de4', token_count=1132, vector_point_id='ch-doc-card-240-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-240-3', 'doc-card-240', 'sec-card-240-2', 3, 'و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش». دیپش چاکرباتی (۲۰۰۰) در این چارچوب، «روش» را «بافت» «بازی» تعریف کرد: «تحلیل»، «بازی» با «داده» است.  ۲. ساختارهای مفهومی • روش کمّی (Quantitative Method): «اندازه‌گیری» و «تعمیم»: «داده» «عددی» و «تحلیل» «آمار». • روش کیفی (Qualitative Method): «فهم» و «عمق»: «داده» «کیفی» و «تحلیل» «تفسیر». • روش ترکیبی (Mixed Methods): «ترکیب» «کمّی» و «کیفی»: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • پیمایش (Survey): «اندازه‌گیری» «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته». • تحلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن».', 'b9b3962883132becf6feffef5352daad4ebfccded2b98a116570966febdc37fb', 1165, 'ch-doc-card-240-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b9b3962883132becf6feffef5352daad4ebfccded2b98a116570966febdc37fb', token_count=1165, vector_point_id='ch-doc-card-240-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-240-4', 'doc-card-240', 'sec-card-240-2', 4, 'حلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن». • نظریه داده بنیادین (Grounded Theory): «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود. • قوم‌نگاری (Ethnography): «فهم» «بافت»: «حضور» در «بافت» و «فه', 'd3adfe1b2767fadb07d32621efbbcab91b3a144b390427e8e354cf43a27f1340', 438, 'ch-doc-card-240-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d3adfe1b2767fadb07d32621efbbcab91b3a144b390427e8e354cf43a27f1340', token_count=438, vector_point_id='ch-doc-card-240-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-240-5', 'doc-card-240', 'sec-card-240-3', 5, 'تاریخ‌گرایی (Historicism)؛ تفاوت تاریخی؛ مفاهیم جهان‌شمول؛ ترجمه‌ناپذیری تجربه؛ دولت مدرن؛ عقلانیت غربی.', '68810f139e1cac6f186298417dcc5669bd570f80853ff849a9d9ed37c241e43f', 189, 'ch-doc-card-240-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='68810f139e1cac6f186298417dcc5669bd570f80853ff849a9d9ed37c241e43f', token_count=189, vector_point_id='ch-doc-card-240-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-240-6', 'doc-card-240', 'sec-card-240-4', 6, 'م» «معنا» در «بافت». • اعتبار و قابلیت اطمینان (Validity and Reliability): «اعتماد» در «روش»: «اعتبار» و «قابلیت اطمینان»، «بافت» «اعتماد» است.  ۳. نمونه‌های تحلیلی «روش کمّی» در عمل: «نظرسنجی» از «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته»: «تعمیم» «نتیجه» به «دسته».  «روش کیفی» در عمل: «مصاحبه» «عمیق» از «دسته‌ی» «کوچک»: «فهم» «معنا» در «بافت» «مصاحبه»: «عمق» «تحلیل».  «پیمایش» در عمل: «پیمایش» «نظر» «مخاطب» از «محتوای» «رسانه»: «سؤال» و «پاسخ» در «بافت» «دسته»: «تعمیم» «نتیجه».  «تحلیل محتوا» در عمل: «تحلیل» «متن» «خبر» از «چارچوب» و «واژه»: «کد» و «فراوانی» در «بافت» «متن»: «تحلیل» «ساختار» «متن».', 'f683f568db9cd81a72f34da1ca103ebb1d3ede97925a0ce1ade672bbcebd1c35', 1116, 'ch-doc-card-240-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f683f568db9cd81a72f34da1ca103ebb1d3ede97925a0ce1ade672bbcebd1c35', token_count=1116, vector_point_id='ch-doc-card-240-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-240-7', 'doc-card-240', 'sec-card-240-4', 7, 'ز «چارچوب» و «واژه»: «کد» و «فراوانی» در «بافت» «متن»: «تحلیل» «ساختار» «متن».  «نظریه داده بنیادین» در عمل: «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود: «تحلیل»، «بازی» با «داده» است.  «قوم‌نگاری» در عمل: «حضور» در «بافت» «مخاطب»: «فهم» «معنا» در «بافت» «مخاطب»: «عمق» «تحلیل» در «بافت» «بومی».  ۴. نقدها و چالش‌ها ۱. «کمّی» و «کیفی» «دیالکتیک»‌اند: «کمّی» «تعمیم» دارد اما «عمق» ندارد و «کیفی» «عمق» دارد اما «تعمیم» ندارد: «روش» «ترکیبی»، «بافت» «دیالکتیک» است. ۲. «روش» و «نظریه» در هم تنیده‌اند: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش»: «روش» «خنثی» وجود ندارد. ۳.', '17842b057ad0f8425860f241c60fd05a93e47f100d43e207106133f550b126e1', 1076, 'ch-doc-card-240-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='17842b057ad0f8425860f241c60fd05a93e47f100d43e207106133f550b126e1', token_count=1076, vector_point_id='ch-doc-card-240-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-240-8', 'doc-card-240', 'sec-card-240-4', 8, '«روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش»: «روش» «خنثی» وجود ندارد. ۳. «اعتبار» در «روش» «کیفی» «سنجش‌پذیر» نیست: «اعتماد» در «بافت» «تحلیل» «ساخته» می‌شود و «اندازه‌گیری» آن «دشواری» است. ۴. «پیمایش» و «بافت»: «سؤال» در «پیمایش»، «بافت» «تحلیل» است: «سؤال» «بافت» «پاسخ» را «تعیین» می‌کند:', '280e67c4bbdb9012c36b674e708f8afa625998809e3cc47beeb1014dd38f5215', 541, 'ch-doc-card-240-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='280e67c4bbdb9012c36b674e708f8afa625998809e3cc47beeb1014dd38f5215', token_count=541, vector_point_id='ch-doc-card-240-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-240-9', 'doc-card-240', 'sec-card-240-5', 9, 'بررسی اینکه مفاهیم «حوزه‌ی عمومی» یا «آزادی مطبوعات» چگونه در جوامع غیراروپایی معنای متفاوتی پیدا می‌کنند.', '30e4abddf2b5dcd2fe3d0ad668b1f79a6b3bee411dfbb6b7881e2aa83fe9545d', 192, 'ch-doc-card-240-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='30e4abddf2b5dcd2fe3d0ad668b1f79a6b3bee411dfbb6b7881e2aa83fe9545d', token_count=192, vector_point_id='ch-doc-card-240-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-240-10', 'doc-card-240', 'sec-card-240-6', 10, 'این رویکرد گاهی به نسبی‌گرایی کشیده می‌شود و ممکن است امکان مقایسه‌ی میان‌فرهنگی را دشوار کند. منتقدان همچنین آن را انتزاعی و کم‌توجه به تحلیل نهادی دانسته‌اند.', 'dc9d8fc7ea07d7cc3a2dc67ea0b0fcd07b3babd0a0e88158f7889bd2771bfbc6', 290, 'ch-doc-card-240-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='dc9d8fc7ea07d7cc3a2dc67ea0b0fcd07b3babd0a0e88158f7889bd2771bfbc6', token_count=290, vector_point_id='ch-doc-card-240-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-240-11', 'doc-card-240', 'sec-card-240-10', 11, 'کتاب «روش پژوهش در ارتباطات» (بیر و همکاران، ۲۰۰۸)؛ کتاب «تحلیل محتوا» (هایرینگ، ۱۹۶۷)؛ کتاب «نظریه داده بنیادین» (گلایزر و استرأس، ۱۹۶۷)؛ کتاب «قوم‌نگاری و فرهنگ» (انول، ۱۹۸۴).', 'f40602f4e73937c5ab57d913729cc1b6482b7e5ff6a6c5988096f450bd7988a5', 321, 'ch-doc-card-240-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f40602f4e73937c5ab57d913729cc1b6482b7e5ff6a6c5988096f450bd7988a5', token_count=321, vector_point_id='ch-doc-card-240-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-241-0', 'doc-card-241', NULL, 0, 'رسانه‌ها در میزان انتقال «حضور» طرف مقابل، یعنی برجستگی او به‌عنوان یک انسان در تعامل، با هم تفاوت دارند. هرچه نشانه‌های غیرکلامی (چهره، لحن، نگاه) کمتر منتقل شود، حضور اجتماعی کمتر است و رسانه برای وظایف حساس میان‌فردی مانند مذاکره یا حل تعارض مناسب‌تر نیست. این نظریه پایه‌ی …', '1736f5af3ac24563c9124b0dc812644ecb103508af75a80a9ecf3a05651ff613', 505, 'ch-doc-card-241-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1736f5af3ac24563c9124b0dc812644ecb103508af75a80a9ecf3a05651ff613', token_count=505, vector_point_id='ch-doc-card-241-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-241-1', 'doc-card-241', 'sec-card-241-1', 1, 'ارتباطات با واسطه‌ی رایانه / روان‌شناسی اجتماعی ارتباطات  رسانه‌ها در میزان انتقال «حضور» طرف مقابل، یعنی برجستگی او به‌عنوان یک انسان در تعامل، با هم تفاوت دارند. هرچه نشانه‌های غیرکلامی (چهره، لحن، نگاه) کمتر منتقل شود، حضور اجتماعی کمتر است و رسانه برای وظایف حساس میان‌فردی مانند مذاکره یا حل تعارض مناسب‌تر نیست. این نظریه پایه‌ی رویکردهای «حذف نشانه‌ها» (Cues-Filtered-Out) در پژوهش‌های بعدی شد.', '4bd429b3af025ccd18d4caa80493d947d1d772f23de1a4da0accc3c17c1966e1', 729, 'ch-doc-card-241-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4bd429b3af025ccd18d4caa80493d947d1d772f23de1a4da0accc3c17c1966e1', token_count=729, vector_point_id='ch-doc-card-241-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-241-2', 'doc-card-241', 'sec-card-241-2', 2, '۱. بنیان و منطق نظری نظریه‌ی حضور اجتماعی «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». جان شورت (۱۹۷۶) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس نظریه‌ی حضور اجتماعی، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. جان شورت (۱۹۷۶) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', '125163b0a107b3d24fb9f3411f622aae674ca6b251eda096870a63247795d9ab', 949, 'ch-doc-card-241-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='125163b0a107b3d24fb9f3411f622aae674ca6b251eda096870a63247795d9ab', token_count=949, vector_point_id='ch-doc-card-241-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-241-3', 'doc-card-241', 'sec-card-241-2', 3, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  نظریه‌ی حضور اجتماعی را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. جان شورت (۱۹۷۶) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.  ۲. ساختارهای مفهومی • ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند.', '75c5c63ad03d819ada7b2bc38ef5b58fd6aec09dd7103e2feaa8ae67ac40bf16', 1123, 'ch-doc-card-241-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='75c5c63ad03d819ada7b2bc38ef5b58fd6aec09dd7103e2feaa8ae67ac40bf16', token_count=1123, vector_point_id='ch-doc-card-241-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-241-4', 'doc-card-241', 'sec-card-241-2', 4, ': «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. • تعارض و مذاکره (Conflict an', '7dbb1fe6d0013cbbc371fe7d15860e13a08aba722e10027aa84aff54a9eb9bd9', 807, 'ch-doc-card-241-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7dbb1fe6d0013cbbc371fe7d15860e13a08aba722e10027aa84aff54a9eb9bd9', token_count=807, vector_point_id='ch-doc-card-241-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-241-5', 'doc-card-241', 'sec-card-241-3', 5, 'حضور اجتماعی؛ صمیمیت (Intimacy)؛ بی‌واسطگی (Immediacy)؛ نشانه‌های غیرکلامی؛ نوع وظیفه‌ی ارتباطی.', '8e86c5e4d721c9c90dda43c4585b677aac89d3cb614b6c63ea40b6ec76235219', 174, 'ch-doc-card-241-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8e86c5e4d721c9c90dda43c4585b677aac89d3cb614b6c63ea40b6ec76235219', token_count=174, vector_point_id='ch-doc-card-241-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-241-6', 'doc-card-241', 'sec-card-241-4', 6, 'd Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است. • بافت‌محوری (Contextualism): «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • قدرت و نقش (Power and Role): «توان» در «ارتباط»: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  ۳. نمونه‌های تحلیلی «ارتباط میان‌فردی» در عمل: «گفت‌وگو» بین «دوستان» «معنا» «ساخته» می‌شود: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  «ارتباط سازمانی» در عمل: «جلسه» «سازمانی»، «بافت» «توان» است: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  «ارتباط بین‌فرهنگی» در عمل: «مذاکره» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است و «فهم» «فرهنگ» دیگر، «توان» است.', 'ee6fd57a183a39a64d98872dc9391bf9256a524dbb696d962357f0a0da7a206e', 1207, 'ch-doc-card-241-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ee6fd57a183a39a64d98872dc9391bf9256a524dbb696d962357f0a0da7a206e', token_count=1207, vector_point_id='ch-doc-card-241-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-241-7', 'doc-card-241', 'sec-card-241-4', 7, 'فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است و «فهم» «فرهنگ» دیگر، «توان» است.  «هوش فرهنگی» در عمل: «مذاکره‌گر» با «هوش فرهنگی» «بافت» «دیگر» را «فهم» می‌کند: «ارتباط» در «بافت» «بین‌فرهنگی»، «توان» است.  «تعارض و مذاکره» در عمل: «مذاکره» «حل» «تعارض» است: «ارتباط» در «تعارض»، «بافت» «حل» است.  «بافت‌محوری» در عمل: «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» (فرهنگ) و «بافت» «کوچک» (گفت‌وگو) در هم تنیده‌اند.  ۴. نقدها و چالش‌ها ۱. «میان‌فردی» و «بافت»: «ارتباط» «میان‌فردی» در «بافت» «توان» است: «توان» در «گفت‌وگو» عمل می‌کند و «میان‌فردی»، «میان‌ساختاری» است. ۲.', '4f66e19cee71c86691f4a1c87800cc8ea0d26c39a8114664a1b1dd7d40e29bf6', 1040, 'ch-doc-card-241-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4f66e19cee71c86691f4a1c87800cc8ea0d26c39a8114664a1b1dd7d40e29bf6', token_count=1040, vector_point_id='ch-doc-card-241-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-241-8', 'doc-card-241', 'sec-card-241-4', 8, 'توان» است: «توان» در «گفت‌وگو» عمل می‌کند و «میان‌فردی»، «میان‌ساختاری» است. ۲. «فرهنگ سازمانی» و «قدرت»: «فرهنگ» در سازمان، «قدرت» است: «فرهنگ» «رقابت»، «فشار» می‌سازد و «ارتباط» را «بازتولید» می‌کند. ۳. «هوش فرهنگی» و «استعمار»: «هوش فرهنگی» می‌تواند «تثبیت» «فرهنگ» دیگر باشد: «فهم» «فرهنگ» دیگر، «آزادی» نیست، «توان» است. ۴. «ارتباط بین‌فرهنگی»', '6c647848070ba3c8ef29f6e649ccfc6ffe6d00173cfcbba82cfe75d7937d7386', 632, 'ch-doc-card-241-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6c647848070ba3c8ef29f6e649ccfc6ffe6d00173cfcbba82cfe75d7937d7386', token_count=632, vector_point_id='ch-doc-card-241-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-241-9', 'doc-card-241', 'sec-card-241-5', 9, 'انتخاب میان تماس تصویری و پیام متنی برای ارائه‌ی بازخورد عملکرد به کارکنان دورکار؛ ادعاهای شرکت‌های واقعیت مجازی درباره‌ی ایجاد «حس حضور» در جلسات کاری.', '6cf0481ad1b0652754d9800df8639f8e777096a9a96698dfbbeab041b8778c8c', 276, 'ch-doc-card-241-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6cf0481ad1b0652754d9800df8639f8e777096a9a96698dfbbeab041b8778c8c', token_count=276, vector_point_id='ch-doc-card-241-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-241-10', 'doc-card-241', 'sec-card-241-6', 10, 'حضور اجتماعی را ویژگی ثابت رسانه می‌داند و به جبرگرایی فناورانه نزدیک می‌شود. پژوهش‌های بعدی نشان دادند کاربران با گذشت زمان و با راهبردهای زبانی کمبود نشانه‌ها را جبران می‌کنند (نک. MC-243).', '3fcad2635dc61f5f230c912b8b8ea5d00492a693fe2f1e9b58213a254bee2843', 347, 'ch-doc-card-241-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3fcad2635dc61f5f230c912b8b8ea5d00492a693fe2f1e9b58213a254bee2843', token_count=347, vector_point_id='ch-doc-card-241-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-241-11', 'doc-card-241', 'sec-card-241-10', 11, 'استناد علمی مبنا (APA 7): Lombard & Ditton (1997)', '821b8ebf753d8c081805a3f6c5f2629f6cc2262467574638214bc9979cd180a6', 89, 'ch-doc-card-241-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='821b8ebf753d8c081805a3f6c5f2629f6cc2262467574638214bc9979cd180a6', token_count=89, vector_point_id='ch-doc-card-241-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-242-0', 'doc-card-242', NULL, 0, 'رسانه‌ها بر اساس توانایی‌شان در رفع ابهام (Equivocality) رتبه‌بندی می‌شوند. معیارهای غنا عبارت‌اند از بازخورد فوری، تعدد نشانه‌ها، تنوع زبانی و تمرکز شخصی؛ گفت‌وگوی رودررو غنی‌ترین و اسناد عددی کم‌غناترین است. اثربخشی مدیریتی زمانی بیشتر است که غنای رسانه با میزان ابهام پیام …', 'ad34431509c88e02cd03946b2a04662e585dd8eeeb0ca1b1cf7b76e5f5b0734a', 503, 'ch-doc-card-242-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ad34431509c88e02cd03946b2a04662e585dd8eeeb0ca1b1cf7b76e5f5b0734a', token_count=503, vector_point_id='ch-doc-card-242-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-242-1', 'doc-card-242', 'sec-card-242-1', 1, 'ارتباطات سازمانی / نظام‌های اطلاعاتی مدیریت  رسانه‌ها بر اساس توانایی‌شان در رفع ابهام (Equivocality) رتبه‌بندی می‌شوند. معیارهای غنا عبارت‌اند از بازخورد فوری، تعدد نشانه‌ها، تنوع زبانی و تمرکز شخصی؛ گفت‌وگوی رودررو غنی‌ترین و اسناد عددی کم‌غناترین است. اثربخشی مدیریتی زمانی بیشتر است که غنای رسانه با میزان ابهام پیام تناسب داشته باشد.', '087beb65e1c8170b053510f9b00f8ea43058b1ff5055dc608e0587a71b5159e3', 614, 'ch-doc-card-242-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='087beb65e1c8170b053510f9b00f8ea43058b1ff5055dc608e0587a71b5159e3', token_count=614, vector_point_id='ch-doc-card-242-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-242-2', 'doc-card-242', 'sec-card-242-2', 2, '۱. بنیان و منطق نظری نظریه‌ی غنای رسانه «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». ریچارد دفت (۱۹۸۴) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس نظریه‌ی غنای رسانه، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. ریچارد دفت (۱۹۸۴) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', '10e4fc3db30b3b3519ee3c8d1b1b6780b38b679715aa3451ad706a0a32b504b2', 949, 'ch-doc-card-242-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='10e4fc3db30b3b3519ee3c8d1b1b6780b38b679715aa3451ad706a0a32b504b2', token_count=949, vector_point_id='ch-doc-card-242-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-242-3', 'doc-card-242', 'sec-card-242-2', 3, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  نظریه‌ی غنای رسانه را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. ریچارد دفت (۱۹۸۴) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.  ۲. ساختارهای مفهومی • ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند.', 'dcd0e02f2612d793d2e47787bf864c6018075c546259bad0a79fc6c017bd719d', 1123, 'ch-doc-card-242-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='dcd0e02f2612d793d2e47787bf864c6018075c546259bad0a79fc6c017bd719d', token_count=1123, vector_point_id='ch-doc-card-242-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-242-4', 'doc-card-242', 'sec-card-242-2', 4, ': «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. • تعارض و مذاکره (Conflict a', '4ed52f15496ee2f5471f9e325a363118b1699edc0bccfa97f3f958508168089e', 805, 'ch-doc-card-242-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4ed52f15496ee2f5471f9e325a363118b1699edc0bccfa97f3f958508168089e', token_count=805, vector_point_id='ch-doc-card-242-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-242-5', 'doc-card-242', 'sec-card-242-3', 5, 'غنای رسانه؛ ابهام (چندمعنایی) در برابر عدم قطعیت (کمبود اطلاعات)؛ بازخورد فوری؛ تعدد نشانه‌ها؛ تناسب رسانه و وظیفه.', 'fc4ffcd76a2609912d34ad9df856201dc36e654e88b3f5b7adfdf610984e9067', 209, 'ch-doc-card-242-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fc4ffcd76a2609912d34ad9df856201dc36e654e88b3f5b7adfdf610984e9067', token_count=209, vector_point_id='ch-doc-card-242-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
