INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-366-11', 'doc-card-366', 'sec-card-366-5', 11, '«فرزشت» در عمل: «ویراستار» با «انتخاب» «کد» از بین «۵۰ خبر»، «نشان» می‌دهد که «چه خبر» است: «انتخاب» خود، «چارچوب» است.  «چارچوب‌بندی» در عمل: وقتی «بحران» اقتصادی «به‌عنوان» «کم‌کاری دولت» چارچوب می‌شود، «معنا» از «پیش» ساخته شده است: «نحوه‌ی» ارائه، «واقعیت» می‌سازد.  «روزنامه‌نگاری تحقیقی» در عمل: «گزارش» از «فساد» در «نهاد دولتی»، «نظارت» بر «قدرت» است: «زمان» (ماه‌ها)، «منابع» (سند، فرد) و «ریسک» (حقوقی) دارد.  «روزنامه‌نگاری شهروندی» در عمل: «گزارش» «مستقیم» از «تظاهرات» در «شبکه‌های اجتماعی»، «سرعت» و «حضور» دارد اما «دقت» و «اصول» آن «نامشخص» است: «اعتبار»، «چالش» اصلی است.', 'b2c55244c9ae0c0feda5d024ded4915f9b6f6b729f8c3bd555483dfe3c90f2dc', 1069, 'ch-doc-card-366-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b2c55244c9ae0c0feda5d024ded4915f9b6f6b729f8c3bd555483dfe3c90f2dc', token_count=1069, vector_point_id='ch-doc-card-366-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-366-12', 'doc-card-366', 'sec-card-366-5', 12, '» و «حضور» دارد اما «دقت» و «اصول» آن «نامشخص» است: «اعتبار»، «چالش» اصلی است.  «اعتبار» در «بحران»: وقتی «رسانه‌ای» «خطا» می‌کند، «اعتراف» و «اصلاح»، «اعتبار» را «حفظ» می‌کند: «پاسخگویی»، «ابزار» «بازتولید» «اعتماد» است.  «استقلال» در عمل: «رسانه‌ای» که «مالکیت» آن «وابسته» به «نهاد سیاسی» است، «استقلال» ندارد و «خبر» آن، «تبلیغ» است: «مالکیت»، «استقلال» را «تعیین» می‌کند.', 'e0b1690251c049b893c626adb63cd3cf326bf236cb1c2caa7253b80c7476a21f', 683, 'ch-doc-card-366-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e0b1690251c049b893c626adb63cd3cf326bf236cb1c2caa7253b80c7476a21f', token_count=683, vector_point_id='ch-doc-card-366-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-366-13', 'doc-card-366', 'sec-card-366-6', 13, '۱. «اصول حرفه‌ای» «ارزش‌ها» هستند: «دقت» و «استقلال» «سنجش‌پذیر» نیستند و «اعتبار» به «خودارزیابی» تقلیل می‌یابد. ۲. «نظارت بر قدرت» در عمل «وابسته» است: «روزنامه‌نگاری تحقیقی» در «بافت‌های دولتی» «محدود» است و «نظارت» به «گزارش» تقلیل می‌یابد. ۳. «روزنامه‌نگاری شهروندی» و «اعتبار»: «مرز» بین «حرفه‌ای» و «شهروند» «کمرنگ» شده و «اعتبار» «بازسازی» نشده است: «هر کسی» «خبر» می‌سازد و «اعتبار»، «چالش» اصلی است. ۴. «فرزشت» و «ساختاری»: «فرزشت» صرفا «ویراستار» نیست: «مالکیت»، «بازار» و «الگوریتم» هم «فرزشت» می‌کنند: «ساختار»، «فرزشت» است. ۵. «چارچوب‌بندی» و «ایدئولوژی»: «چارچوب» همیشه «ایدئولوژیک» است و «خبر» «خنثی» وج', '49923e96ddebc7dddf52f59107a3f58238bdb3fc5b7d6f4ff863d5cb3d2e1b1e', 1125, 'ch-doc-card-366-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='49923e96ddebc7dddf52f59107a3f58238bdb3fc5b7d6f4ff863d5cb3d2e1b1e', token_count=1125, vector_point_id='ch-doc-card-366-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-366-14', 'doc-card-366', 'sec-card-366-7', 14, 'ود ندارد: «تحلیل» «چارچوب»، «نقد» «ایدئولوژی» می‌شود. ۶. «اعتبار» و «بازار»: «اعتبار» حرفه‌ای در «بازار» «رقابت» با «سرعت» و «محتوای» «فرهنگ عامه» است: «اعتبار» در برابر «سرعت»، «بازنده» است؟ ۷. «استقلال» در «اقتصاد داده» «بازتعریف» می‌شود: «درآمد» از «داده» و «تبلیغات» است و «استقلال» در «اقتصاد» «تعیین» می‌شود. ۸. «روزنامه‌نگاری تحقیقی» و «ریسک»: «تحقیقی» بودن «ریسک» دارد (حقوقی، امنیتی) و «حرفه‌ای» در «بافت‌های» «محدود»، «تحت فشار» است. ۹. «اعتماد عمومی» و «قطبی‌شدن»: «اعتماد» در «عصر دیجیتال» «قطبی» شده است: «مخاطب» به «رسانه‌ای» اعتماد می‌کند که «دیدگاه» او را «تأیید» می‌کند: «اعتماد»، «ایدئولوژیک» شده است.', 'e4437e49466e4a43a0f7175079c19355bd32c7f8439115aab07f59a9d7399c67', 1125, 'ch-doc-card-366-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e4437e49466e4a43a0f7175079c19355bd32c7f8439115aab07f59a9d7399c67', token_count=1125, vector_point_id='ch-doc-card-366-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-366-15', 'doc-card-366', 'sec-card-366-10', 15, 'کتاب «خبر چیست؟» (تورنر، ۱۹۷۹)؛ کتاب «روزنامه‌نگاری و اقتدار» (گارسیا، ۱۹۸۸)؛ کتاب «روزنامه‌نگاری تحقیقی» (آلن و همکاران، ۲۰۰۱)؛ کتاب «روزنامه‌نگاری شهروندی» (گراس و همکاران، ۲۰۰۹).', '6c486eeff52ca4898cccc820904163927b9bdcdde1030afa231f7fbffd16c26b', 329, 'ch-doc-card-366-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6c486eeff52ca4898cccc820904163927b9bdcdde1030afa231f7fbffd16c26b', token_count=329, vector_point_id='ch-doc-card-366-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-367-0', 'doc-card-367', NULL, 0, 'در دورۀ پیشاپروپی، پ.ت. بارنوم تبلیغات را «فناوری دروغ» و نمایشی اغراق‌آمیز می‌دانست: انتشارات یکسویه‌ای با جنجال‌آفرینی و دراماتیک‌سازی، که هدفشان فروش بدون تعهدی به صحت و حقیقت کامل بود.', '6a5b7cb73f07a3cb46081a916b5769f8ca80512f0ea0ccf4a8c8163521dd99c0', 341, 'ch-doc-card-367-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6a5b7cb73f07a3cb46081a916b5769f8ca80512f0ea0ccf4a8c8163521dd99c0', token_count=341, vector_point_id='ch-doc-card-367-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-367-1', 'doc-card-367', 'sec-card-367-1', 1, 'ارتباطات بین‌فرهنگی، سازمانی و میان‌فردی  ارتباطات یکسویه به مثابه تبلیغ نمایشی و پروپاگاندای تجاری، با توسل به جنجال‌آفرینی بدون تعهد به حقیقت کامل.', '6dd17e8249112c516a2ac87787a9b0c6cfc80388b16da2b47ac650abeefb12e0', 270, 'ch-doc-card-367-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6dd17e8249112c516a2ac87787a9b0c6cfc80388b16da2b47ac650abeefb12e0', token_count=270, vector_point_id='ch-doc-card-367-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-367-2', 'doc-card-367', 'sec-card-367-2', 2, '۱. بنیان و منطق نظری مدل مطبوعاتی و اغراق نمایشی «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». فینیاس تی. بارنوم در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس مدل مطبوعاتی و اغراق نمایشی، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. فینیاس تی. بارنوم در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', '7be3d2affffb1fb0bd000f3c6c1df1670638c001ab8c0ff01b0c8d7df603a4dc', 981, 'ch-doc-card-367-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7be3d2affffb1fb0bd000f3c6c1df1670638c001ab8c0ff01b0c8d7df603a4dc', token_count=981, vector_point_id='ch-doc-card-367-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-367-3', 'doc-card-367', 'sec-card-367-2', 3, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  مدل مطبوعاتی و اغراق نمایشی را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. فینیاس تی. بارنوم در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.  ۲. ساختارهای مفهومی • ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند.', 'e3267c017838ca56e6d5423e88b7c1b45a8811a878d06c16e1b05c25a15ade57', 1140, 'ch-doc-card-367-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e3267c017838ca56e6d5423e88b7c1b45a8811a878d06c16e1b05c25a15ade57', token_count=1140, vector_point_id='ch-doc-card-367-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-367-4', 'doc-card-367', 'sec-card-367-2', 4, ': «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. • تعارض و مذا', '81511bcafa2d2277bcbd4a4938446573ee61c0ea458ac74f10d0ead032f639a8', 778, 'ch-doc-card-367-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='81511bcafa2d2277bcbd4a4938446573ee61c0ea458ac74f10d0ead032f639a8', token_count=778, vector_point_id='ch-doc-card-367-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-367-5', 'doc-card-367', 'sec-card-367-3', 5, '• ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. • تعارض و مذاکره (Conflict and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است.', 'bf50a19f3fa6a4558d5edbd42200280c7f4b92c377964c4e6187e1ed0133db26', 1230, 'ch-doc-card-367-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bf50a19f3fa6a4558d5edbd42200280c7f4b92c377964c4e6187e1ed0133db26', token_count=1230, vector_point_id='ch-doc-card-367-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-367-6', 'doc-card-367', 'sec-card-367-3', 6, 'flict and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است. • بافت‌محوری (Contextualism): «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • قدرت و نقش (Power and Role): «توان» در «ارتباط»: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.', 'b64e4de88dbaf207aea343dd750d2b2d8bd0b257fd13137445296eaa2c40c444', 527, 'ch-doc-card-367-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b64e4de88dbaf207aea343dd750d2b2d8bd0b257fd13137445296eaa2c40c444', token_count=527, vector_point_id='ch-doc-card-367-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-367-7', 'doc-card-367', 'sec-card-367-4', 7, 'کره (Conflict and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است. • بافت‌محوری (Contextualism): «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • قدرت و نقش (Power and Role): «توان» در «ارتباط»: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  ۳. نمونه‌های تحلیلی «ارتباط میان‌فردی» در عمل: «گفت‌وگو» بین «دوستان» «معنا» «ساخته» می‌شود: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  «ارتباط سازمانی» در عمل: «جلسه» «سازمانی»، «بافت» «توان» است: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.', 'dcb3a5f3df8e26f6d493577acad838e712aa300a95215335a5f590722d3628d4', 1014, 'ch-doc-card-367-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='dcb3a5f3df8e26f6d493577acad838e712aa300a95215335a5f590722d3628d4', token_count=1014, vector_point_id='ch-doc-card-367-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-367-8', 'doc-card-367', 'sec-card-367-4', 8, 'سازمانی»، «بافت» «توان» است: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  «ارتباط بین‌فرهنگی» در عمل: «مذاکره» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است و «فهم» «فرهنگ» دیگر، «توان» است.  «هوش فرهنگی» در عمل: «مذاکره‌گر» با «هوش فرهنگی» «بافت» «دیگر» را «فهم» می‌کند: «ارتباط» در «بافت» «بین‌فرهنگی»، «توان» است.  «تعارض و مذاکره» در عمل: «مذاکره» «حل» «تعارض» است: «ارتباط» در «تعارض»، «بافت» «حل» است.  «بافت‌محوری» در عمل: «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» (فرهنگ) و «بافت» «کوچک» (گفت‌وگو) در هم تنیده‌اند.  ۴. نقدها و چالش‌ها ۱.', '37eda6dbe33a68cb291ccc8be06afd1d48eaf537275730581dd4e2a6fec25095', 1018, 'ch-doc-card-367-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='37eda6dbe33a68cb291ccc8be06afd1d48eaf537275730581dd4e2a6fec25095', token_count=1018, vector_point_id='ch-doc-card-367-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-367-9', 'doc-card-367', 'sec-card-367-4', 9, 'بزرگ» (فرهنگ) و «بافت» «کوچک» (گفت‌وگو) در هم تنیده‌اند.  ۴. نقدها و چالش‌ها ۱. «میان‌فردی» و «بافت»: «ارتباط» «میان‌فردی» در «بافت» «توان» است: «توان» در «گفت‌وگو» عمل می‌کند و «میان‌فردی»، «میان‌ساختاری» است. ۲. «فرهنگ سازمانی» و «قدرت»: «فرهنگ» در سازمان، «قدرت» است: «فرهنگ» «رقابت»، «فشار» می‌سازد و «ارتباط» را «بازتولید» می‌کند. ۳. «هوش فرهنگی» و «استعمار»: «هوش فرهنگی» می‌تواند «تثبیت» «فرهنگ» دیگر باشد: «فهم» «فرهنگ» دیگر، «آزادی» نیست، «توان» است. ۴. «ارتباط بین‌فره', '1c09be933e610939b03474ff20252b68a90f5705bacbc2bc690ec7ab4a685fd7', 869, 'ch-doc-card-367-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1c09be933e610939b03474ff20252b68a90f5705bacbc2bc690ec7ab4a685fd7', token_count=869, vector_point_id='ch-doc-card-367-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-367-10', 'doc-card-367', 'sec-card-367-5', 10, '«ارتباط میان‌فردی» در عمل: «گفت‌وگو» بین «دوستان» «معنا» «ساخته» می‌شود: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  «ارتباط سازمانی» در عمل: «جلسه» «سازمانی»، «بافت» «توان» است: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  «ارتباط بین‌فرهنگی» در عمل: «مذاکره» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است و «فهم» «فرهنگ» دیگر، «توان» است.  «هوش فرهنگی» در عمل: «مذاکره‌گر» با «هوش فرهنگی» «بافت» «دیگر» را «فهم» می‌کند: «ارتباط» در «بافت» «بین‌فرهنگی»، «توان» است.  «تعارض و مذاکره» در عمل: «مذاکره» «حل» «تعارض» است: «ارتباط» در «تعارض»، «بافت» «حل» است.', '6bf4912c61268e9f65d68aec8a8d0992a53f96d0f18bf9e19d75cf9dcd421de5', 1049, 'ch-doc-card-367-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6bf4912c61268e9f65d68aec8a8d0992a53f96d0f18bf9e19d75cf9dcd421de5', token_count=1049, vector_point_id='ch-doc-card-367-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-367-11', 'doc-card-367', 'sec-card-367-5', 11, 'اکره» در عمل: «مذاکره» «حل» «تعارض» است: «ارتباط» در «تعارض»، «بافت» «حل» است.  «بافت‌محوری» در عمل: «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» (فرهنگ) و «بافت» «کوچک» (گفت‌وگو) در هم تنیده‌اند.', '70e3ddf05c8eaea9d7529c749dddc708444781f2934e78b2fabb313171dbc2bc', 359, 'ch-doc-card-367-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='70e3ddf05c8eaea9d7529c749dddc708444781f2934e78b2fabb313171dbc2bc', token_count=359, vector_point_id='ch-doc-card-367-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-367-12', 'doc-card-367', 'sec-card-367-6', 12, '۱. «میان‌فردی» و «بافت»: «ارتباط» «میان‌فردی» در «بافت» «توان» است: «توان» در «گفت‌وگو» عمل می‌کند و «میان‌فردی»، «میان‌ساختاری» است. ۲. «فرهنگ سازمانی» و «قدرت»: «فرهنگ» در سازمان، «قدرت» است: «فرهنگ» «رقابت»، «فشار» می‌سازد و «ارتباط» را «بازتولید» می‌کند. ۳. «هوش فرهنگی» و «استعمار»: «هوش فرهنگی» می‌تواند «تثبیت» «فرهنگ» دیگر باشد: «فهم» «فرهنگ» دیگر، «آزادی» نیست، «توان» است. ۴. «ارتباط بین‌فرهنگی» و «دوگانه»: «فرهنگ» «دوگانه» نیست: «تنوع» داخل «فرهنگ» به‌قدری «بزرگ» است که «دوگانه» «افسانه» است. ۵. «مذاکره» و «توان»: «مذاکره» در «توان» «نامتقارن»، «حل» «تعارض» نیست', 'c23b7447826b60647458a2d7d01fc71144cc1a740dda9a9d6c4cef757a8dc3a2', 1047, 'ch-doc-card-367-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c23b7447826b60647458a2d7d01fc71144cc1a740dda9a9d6c4cef757a8dc3a2', token_count=1047, vector_point_id='ch-doc-card-367-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-367-13', 'doc-card-367', 'sec-card-367-7', 13, ': «توان»، «مذاکره» را «بازتولید» می‌کند. ۶. «بافت‌محوری» و «تعمیم»: «معنا» در «بافت» «ساخته» می‌شود اما «بافت» «تعمیم» «پذیر» نیست: «بافت» «بومی» است و «تحلیل»، «بومی» لازم دارد. ۷. «ارتباط سازمانی» و «ساختار»: «ارتباط» در «ساختار» «سازمانی»، «بازتولید» «توان» است: «ساختار»، «ارتباط» است. ۸. «ارتباط» و «رسانه»: «ارتباط» «میان‌فردی» و «سازمانی» در «عصر دیجیتال»، «رسانه» «دیجیتال» «بازتعریف» می‌شود: «بافت» «دیجیتال»، «ارتباط» را «بازتولید» می‌کند. ۹. «هوش فرهنگی» و «بافت»: «هوش فرهنگی» در «بافت» «دیجیتال»، «بازتعریف» می‌شود: «بافت» «دیجیتال»، «فرهنگ» را «بازتولید» می‌کند.', '6bdec743a480fb86611d0cdb02061e889fbe8f7dd8911f02a030608c0f3c2be5', 1047, 'ch-doc-card-367-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6bdec743a480fb86611d0cdb02061e889fbe8f7dd8911f02a030608c0f3c2be5', token_count=1047, vector_point_id='ch-doc-card-367-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-367-14', 'doc-card-367', 'sec-card-367-10', 14, 'کتاب «ارتباط میان‌فردی» (آدلمن و همکاران، ۱۹۹۸)؛ کتاب «ارتباط سازمانی» (مکنزی و همکاران، ۲۰۰۵)؛ کتاب «ارتباط بین‌فرهنگی» (لومبونگ و همکاران، ۲۰۰۳)؛ کتاب «هوش فرهنگی» (رابن و همکاران، ۲۰۰۷).', '956a1e981812fd0aee168d40ca4cfc0e60c304bdfcef5b69be87a8e90e1ab9e3', 343, 'ch-doc-card-367-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='956a1e981812fd0aee168d40ca4cfc0e60c304bdfcef5b69be87a8e90e1ab9e3', token_count=343, vector_point_id='ch-doc-card-367-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-368-0', 'doc-card-368', NULL, 0, 'آیوی لی با اعلام‌نامه ۱۹۰۶ خود روابط عمومی را از «فناوری دروغ» بارنوم به اصل «اطلاع‌رسانی صادقانه» جابه‌جا کرد: سازمان‌ها باید با افشای واقع‌نمایانه‌ی اطلاعات، حسن‌نیت عمومی را جلب کنند، نه آنکه حقایق را دستکاری نمایند.', '3ac40b8766da4f5eb25ea2cff4778ac976532b0f1c129820a2e7e9dec6cf1e15', 398, 'ch-doc-card-368-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3ac40b8766da4f5eb25ea2cff4778ac976532b0f1c129820a2e7e9dec6cf1e15', token_count=398, vector_point_id='ch-doc-card-368-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-368-1', 'doc-card-368', 'sec-card-368-1', 1, 'ارتباطات بین‌فرهنگی، سازمانی و میان‌فردی  ارتباطات یکسویه واقع‌نما با رویکرد اطلاع‌رسانی شفاف سازمانی برای جلب حسن‌نیت مردم، بدون دستکاری عمدی حقایق.', '064d6eb4d481e6cce4030c00de0bb9333b1c6acdb476e9ed5859a767d099c9b8', 270, 'ch-doc-card-368-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='064d6eb4d481e6cce4030c00de0bb9333b1c6acdb476e9ed5859a767d099c9b8', token_count=270, vector_point_id='ch-doc-card-368-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-368-2', 'doc-card-368', 'sec-card-368-2', 2, '۱. بنیان و منطق نظری مدل انتشار صادقانه اطلاعات «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». آیوی لی (۱۹۰۶) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس مدل انتشار صادقانه اطلاعات، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. آیوی لی (۱۹۰۶) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', 'cb3339412ee2d15f35f8d97aa8c97062d7e824459b40fefd59b35aaa6c257e7d', 967, 'ch-doc-card-368-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cb3339412ee2d15f35f8d97aa8c97062d7e824459b40fefd59b35aaa6c257e7d', token_count=967, vector_point_id='ch-doc-card-368-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-368-3', 'doc-card-368', 'sec-card-368-2', 3, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  مدل انتشار صادقانه اطلاعات را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. آیوی لی (۱۹۰۶) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.  ۲. ساختارهای مفهومی • ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند.', 'a21b8de5ed7600df433111423f2d9bc38485cfe2b026028f5f769d0bca9b857d', 1132, 'ch-doc-card-368-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a21b8de5ed7600df433111423f2d9bc38485cfe2b026028f5f769d0bca9b857d', token_count=1132, vector_point_id='ch-doc-card-368-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-368-4', 'doc-card-368', 'sec-card-368-2', 4, ': «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. • تعارض و مذاکره (Con', 'a007ccc0420429baa072b802c8742c1f45f8ce3f165728b0147e2732a119457b', 792, 'ch-doc-card-368-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a007ccc0420429baa072b802c8742c1f45f8ce3f165728b0147e2732a119457b', token_count=792, vector_point_id='ch-doc-card-368-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-368-5', 'doc-card-368', 'sec-card-368-3', 5, '• ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. • تعارض و مذاکره (Conflict and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است.', 'bf50a19f3fa6a4558d5edbd42200280c7f4b92c377964c4e6187e1ed0133db26', 1230, 'ch-doc-card-368-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bf50a19f3fa6a4558d5edbd42200280c7f4b92c377964c4e6187e1ed0133db26', token_count=1230, vector_point_id='ch-doc-card-368-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-368-6', 'doc-card-368', 'sec-card-368-3', 6, 'flict and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است. • بافت‌محوری (Contextualism): «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • قدرت و نقش (Power and Role): «توان» در «ارتباط»: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.', 'b64e4de88dbaf207aea343dd750d2b2d8bd0b257fd13137445296eaa2c40c444', 527, 'ch-doc-card-368-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b64e4de88dbaf207aea343dd750d2b2d8bd0b257fd13137445296eaa2c40c444', token_count=527, vector_point_id='ch-doc-card-368-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-368-7', 'doc-card-368', 'sec-card-368-4', 7, 'flict and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است. • بافت‌محوری (Contextualism): «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • قدرت و نقش (Power and Role): «توان» در «ارتباط»: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  ۳. نمونه‌های تحلیلی «ارتباط میان‌فردی» در عمل: «گفت‌وگو» بین «دوستان» «معنا» «ساخته» می‌شود: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  «ارتباط سازمانی» در عمل: «جلسه» «سازمانی»، «بافت» «توان» است: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  «ارتباط بین‌فرهنگی» در عمل: «مذاکره» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است و «فهم» «فرهنگ» دیگر، «توان» است.', 'f4b06b3ba0c171027cf87b7b2346605680aabbcf1e8210a4638e4094ceb0b04a', 1221, 'ch-doc-card-368-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f4b06b3ba0c171027cf87b7b2346605680aabbcf1e8210a4638e4094ceb0b04a', token_count=1221, vector_point_id='ch-doc-card-368-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-368-8', 'doc-card-368', 'sec-card-368-4', 8, 'فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است و «فهم» «فرهنگ» دیگر، «توان» است.  «هوش فرهنگی» در عمل: «مذاکره‌گر» با «هوش فرهنگی» «بافت» «دیگر» را «فهم» می‌کند: «ارتباط» در «بافت» «بین‌فرهنگی»، «توان» است.  «تعارض و مذاکره» در عمل: «مذاکره» «حل» «تعارض» است: «ارتباط» در «تعارض»، «بافت» «حل» است.  «بافت‌محوری» در عمل: «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» (فرهنگ) و «بافت» «کوچک» (گفت‌وگو) در هم تنیده‌اند.  ۴. نقدها و چالش‌ها ۱. «میان‌فردی» و «بافت»: «ارتباط» «میان‌فردی» در «بافت» «توان» است: «توان» در «گفت‌وگو» عمل می‌کند و «میان‌فردی»، «میان‌ساختاری» است. ۲.', '4f66e19cee71c86691f4a1c87800cc8ea0d26c39a8114664a1b1dd7d40e29bf6', 1040, 'ch-doc-card-368-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4f66e19cee71c86691f4a1c87800cc8ea0d26c39a8114664a1b1dd7d40e29bf6', token_count=1040, vector_point_id='ch-doc-card-368-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
