INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-368-12', 'doc-card-368', 'sec-card-368-6', 12, '۱. «میان‌فردی» و «بافت»: «ارتباط» «میان‌فردی» در «بافت» «توان» است: «توان» در «گفت‌وگو» عمل می‌کند و «میان‌فردی»، «میان‌ساختاری» است. ۲. «فرهنگ سازمانی» و «قدرت»: «فرهنگ» در سازمان، «قدرت» است: «فرهنگ» «رقابت»، «فشار» می‌سازد و «ارتباط» را «بازتولید» می‌کند. ۳. «هوش فرهنگی» و «استعمار»: «هوش فرهنگی» می‌تواند «تثبیت» «فرهنگ» دیگر باشد: «فهم» «فرهنگ» دیگر، «آزادی» نیست، «توان» است. ۴. «ارتباط بین‌فرهنگی» و «دوگانه»: «فرهنگ» «دوگانه» نیست: «تنوع» داخل «فرهنگ» به‌قدری «بزرگ» است که «دوگانه» «افسانه» است. ۵. «مذاکره» و «توان»: «مذاکره» در «توان» «نامتقارن»، «حل» «تعارض» نیست', 'c23b7447826b60647458a2d7d01fc71144cc1a740dda9a9d6c4cef757a8dc3a2', 1047, 'ch-doc-card-368-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c23b7447826b60647458a2d7d01fc71144cc1a740dda9a9d6c4cef757a8dc3a2', token_count=1047, vector_point_id='ch-doc-card-368-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-368-13', 'doc-card-368', 'sec-card-368-7', 13, ': «توان»، «مذاکره» را «بازتولید» می‌کند. ۶. «بافت‌محوری» و «تعمیم»: «معنا» در «بافت» «ساخته» می‌شود اما «بافت» «تعمیم» «پذیر» نیست: «بافت» «بومی» است و «تحلیل»، «بومی» لازم دارد. ۷. «ارتباط سازمانی» و «ساختار»: «ارتباط» در «ساختار» «سازمانی»، «بازتولید» «توان» است: «ساختار»، «ارتباط» است. ۸. «ارتباط» و «رسانه»: «ارتباط» «میان‌فردی» و «سازمانی» در «عصر دیجیتال»، «رسانه» «دیجیتال» «بازتعریف» می‌شود: «بافت» «دیجیتال»، «ارتباط» را «بازتولید» می‌کند. ۹. «هوش فرهنگی» و «بافت»: «هوش فرهنگی» در «بافت» «دیجیتال»، «بازتعریف» می‌شود: «بافت» «دیجیتال»، «فرهنگ» را «بازتولید» می‌کند.', '6bdec743a480fb86611d0cdb02061e889fbe8f7dd8911f02a030608c0f3c2be5', 1047, 'ch-doc-card-368-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6bdec743a480fb86611d0cdb02061e889fbe8f7dd8911f02a030608c0f3c2be5', token_count=1047, vector_point_id='ch-doc-card-368-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-368-14', 'doc-card-368', 'sec-card-368-10', 14, 'کتاب «ارتباط میان‌فردی» (آدلمن و همکاران، ۱۹۹۸)؛ کتاب «ارتباط سازمانی» (مکنزی و همکاران، ۲۰۰۵)؛ کتاب «ارتباط بین‌فرهنگی» (لومبونگ و همکاران، ۲۰۰۳)؛ کتاب «هوش فرهنگی» (رابن و همکاران، ۲۰۰۷).', '956a1e981812fd0aee168d40ca4cfc0e60c304bdfcef5b69be87a8e90e1ab9e3', 343, 'ch-doc-card-368-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='956a1e981812fd0aee168d40ca4cfc0e60c304bdfcef5b69be87a8e90e1ab9e3', token_count=343, vector_point_id='ch-doc-card-368-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-369-0', 'doc-card-369', NULL, 0, 'برنیز در کتاب «مهندسی رضایت» (1947) کاربرد علم روان‌شناسی فرویدی و جامعه‌شناسی را برای شکل‌دهی ساختاریافته به تمایلات، باورها و آرای ناخودآگاه توده‌ها، به‌منظور خدمت به اهداف دولت‌ها و سازمان‌های بزرگ، به رسمیت می‌شناخت.', 'cb08d2035e9c821af98e9b1d9967f00d90afd6b823c3633bf2bcdb822bfcd65b', 399, 'ch-doc-card-369-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cb08d2035e9c821af98e9b1d9967f00d90afd6b823c3633bf2bcdb822bfcd65b', token_count=399, vector_point_id='ch-doc-card-369-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-369-1', 'doc-card-369', 'sec-card-369-1', 1, 'ارتباطات بین‌فرهنگی، سازمانی و میان‌فردی  کاربرد روان‌شناسی فرویدی و جامعه‌شناسی برای شکل‌دهی ساختاریافته به تمایلات و آرای ناخودآگاه عمومی جهت خدمت به اهداف سازمان‌ها و دولت‌ها.', '3ae70a4f756fcac230244b5e39bac9d6781f2d97eab6d5c54d4642cd31c1ddc0', 323, 'ch-doc-card-369-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3ae70a4f756fcac230244b5e39bac9d6781f2d97eab6d5c54d4642cd31c1ddc0', token_count=323, vector_point_id='ch-doc-card-369-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-369-2', 'doc-card-369', 'sec-card-369-2', 2, '۱. بنیان و منطق نظری مهندسی رضایت «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». ادوارد برنیز (۱۹۴۷) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس مهندسی رضایت، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. ادوارد برنیز (۱۹۴۷) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', '90e7d5313c84a4e07b5c52fc35b100a99f6080ca4b7f7dfac889fd7de8bc907f', 934, 'ch-doc-card-369-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='90e7d5313c84a4e07b5c52fc35b100a99f6080ca4b7f7dfac889fd7de8bc907f', token_count=934, vector_point_id='ch-doc-card-369-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-369-3', 'doc-card-369', 'sec-card-369-2', 3, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  مهندسی رضایت را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. ادوارد برنیز (۱۹۴۷) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.  ۲. ساختارهای مفهومی • ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند.', 'cf9974f5f4053cd8fa3ab2544e5b590dc277822f2e3e59cbd4198fbff488cabd', 1116, 'ch-doc-card-369-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cf9974f5f4053cd8fa3ab2544e5b590dc277822f2e3e59cbd4198fbff488cabd', token_count=1116, vector_point_id='ch-doc-card-369-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-369-4', 'doc-card-369', 'sec-card-369-2', 4, ': «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. • تعارض و مذاکره (Conflict and Neg', '2f91ce8f9790c7796c899b1f0ca3291b9a55b8c1ff6285aab667f843a8e4560c', 816, 'ch-doc-card-369-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2f91ce8f9790c7796c899b1f0ca3291b9a55b8c1ff6285aab667f843a8e4560c', token_count=816, vector_point_id='ch-doc-card-369-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-369-5', 'doc-card-369', 'sec-card-369-3', 5, '• ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. • تعارض و مذاکره (Conflict and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است.', 'bf50a19f3fa6a4558d5edbd42200280c7f4b92c377964c4e6187e1ed0133db26', 1230, 'ch-doc-card-369-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bf50a19f3fa6a4558d5edbd42200280c7f4b92c377964c4e6187e1ed0133db26', token_count=1230, vector_point_id='ch-doc-card-369-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-369-6', 'doc-card-369', 'sec-card-369-3', 6, 'flict and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است. • بافت‌محوری (Contextualism): «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • قدرت و نقش (Power and Role): «توان» در «ارتباط»: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.', 'b64e4de88dbaf207aea343dd750d2b2d8bd0b257fd13137445296eaa2c40c444', 527, 'ch-doc-card-369-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b64e4de88dbaf207aea343dd750d2b2d8bd0b257fd13137445296eaa2c40c444', token_count=527, vector_point_id='ch-doc-card-369-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-369-7', 'doc-card-369', 'sec-card-369-4', 7, 'otiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است. • بافت‌محوری (Contextualism): «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • قدرت و نقش (Power and Role): «توان» در «ارتباط»: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  ۳. نمونه‌های تحلیلی «ارتباط میان‌فردی» در عمل: «گفت‌وگو» بین «دوستان» «معنا» «ساخته» می‌شود: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  «ارتباط سازمانی» در عمل: «جلسه» «سازمانی»، «بافت» «توان» است: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  «ارتباط بین‌فرهنگی» در عمل: «مذاکره» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است و «فهم» «فرهنگ» دیگر، «توان» است.', '0627e13d418336fa92556b1cc3ac7f281fe5f51dabf194169a75e1674b17ecf5', 1198, 'ch-doc-card-369-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0627e13d418336fa92556b1cc3ac7f281fe5f51dabf194169a75e1674b17ecf5', token_count=1198, vector_point_id='ch-doc-card-369-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-369-8', 'doc-card-369', 'sec-card-369-4', 8, 'فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است و «فهم» «فرهنگ» دیگر، «توان» است.  «هوش فرهنگی» در عمل: «مذاکره‌گر» با «هوش فرهنگی» «بافت» «دیگر» را «فهم» می‌کند: «ارتباط» در «بافت» «بین‌فرهنگی»، «توان» است.  «تعارض و مذاکره» در عمل: «مذاکره» «حل» «تعارض» است: «ارتباط» در «تعارض»، «بافت» «حل» است.  «بافت‌محوری» در عمل: «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» (فرهنگ) و «بافت» «کوچک» (گفت‌وگو) در هم تنیده‌اند.  ۴. نقدها و چالش‌ها ۱. «میان‌فردی» و «بافت»: «ارتباط» «میان‌فردی» در «بافت» «توان» است: «توان» در «گفت‌وگو» عمل می‌کند و «میان‌فردی»، «میان‌ساختاری» است. ۲.', '4f66e19cee71c86691f4a1c87800cc8ea0d26c39a8114664a1b1dd7d40e29bf6', 1040, 'ch-doc-card-369-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4f66e19cee71c86691f4a1c87800cc8ea0d26c39a8114664a1b1dd7d40e29bf6', token_count=1040, vector_point_id='ch-doc-card-369-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-369-9', 'doc-card-369', 'sec-card-369-4', 9, 'توان» است: «توان» در «گفت‌وگو» عمل می‌کند و «میان‌فردی»، «میان‌ساختاری» است. ۲. «فرهنگ سازمانی» و «قدرت»: «فرهنگ» در سازمان، «قدرت» است: «فرهنگ» «رقابت»، «فشار» می‌سازد و «ارتباط» را «بازتولید» می‌کند. ۳. «هوش فرهنگی» و «استعمار»: «هوش فرهنگی» می‌تواند «تثبیت» «فرهنگ» دیگر باشد: «فهم» «فرهنگ» دیگر، «آزادی» نیست، «توان» است. ۴. «ارتباط بین‌فرهنگی', 'ea54a0193629983c3429e33546f041bf031b56095e889fe0073209482e30c8a1', 630, 'ch-doc-card-369-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ea54a0193629983c3429e33546f041bf031b56095e889fe0073209482e30c8a1', token_count=630, vector_point_id='ch-doc-card-369-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-369-10', 'doc-card-369', 'sec-card-369-5', 10, '«ارتباط میان‌فردی» در عمل: «گفت‌وگو» بین «دوستان» «معنا» «ساخته» می‌شود: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  «ارتباط سازمانی» در عمل: «جلسه» «سازمانی»، «بافت» «توان» است: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  «ارتباط بین‌فرهنگی» در عمل: «مذاکره» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است و «فهم» «فرهنگ» دیگر، «توان» است.  «هوش فرهنگی» در عمل: «مذاکره‌گر» با «هوش فرهنگی» «بافت» «دیگر» را «فهم» می‌کند: «ارتباط» در «بافت» «بین‌فرهنگی»، «توان» است.  «تعارض و مذاکره» در عمل: «مذاکره» «حل» «تعارض» است: «ارتباط» در «تعارض»، «بافت» «حل» است.', '6bf4912c61268e9f65d68aec8a8d0992a53f96d0f18bf9e19d75cf9dcd421de5', 1049, 'ch-doc-card-369-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6bf4912c61268e9f65d68aec8a8d0992a53f96d0f18bf9e19d75cf9dcd421de5', token_count=1049, vector_point_id='ch-doc-card-369-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-369-11', 'doc-card-369', 'sec-card-369-5', 11, 'اکره» در عمل: «مذاکره» «حل» «تعارض» است: «ارتباط» در «تعارض»، «بافت» «حل» است.  «بافت‌محوری» در عمل: «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» (فرهنگ) و «بافت» «کوچک» (گفت‌وگو) در هم تنیده‌اند.', '70e3ddf05c8eaea9d7529c749dddc708444781f2934e78b2fabb313171dbc2bc', 359, 'ch-doc-card-369-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='70e3ddf05c8eaea9d7529c749dddc708444781f2934e78b2fabb313171dbc2bc', token_count=359, vector_point_id='ch-doc-card-369-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-369-12', 'doc-card-369', 'sec-card-369-6', 12, '۱. «میان‌فردی» و «بافت»: «ارتباط» «میان‌فردی» در «بافت» «توان» است: «توان» در «گفت‌وگو» عمل می‌کند و «میان‌فردی»، «میان‌ساختاری» است. ۲. «فرهنگ سازمانی» و «قدرت»: «فرهنگ» در سازمان، «قدرت» است: «فرهنگ» «رقابت»، «فشار» می‌سازد و «ارتباط» را «بازتولید» می‌کند. ۳. «هوش فرهنگی» و «استعمار»: «هوش فرهنگی» می‌تواند «تثبیت» «فرهنگ» دیگر باشد: «فهم» «فرهنگ» دیگر، «آزادی» نیست، «توان» است. ۴. «ارتباط بین‌فرهنگی» و «دوگانه»: «فرهنگ» «دوگانه» نیست: «تنوع» داخل «فرهنگ» به‌قدری «بزرگ» است که «دوگانه» «افسانه» است. ۵. «مذاکره» و «توان»: «مذاکره» در «توان» «نامتقارن»، «حل» «تعارض» نیست', 'c23b7447826b60647458a2d7d01fc71144cc1a740dda9a9d6c4cef757a8dc3a2', 1047, 'ch-doc-card-369-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c23b7447826b60647458a2d7d01fc71144cc1a740dda9a9d6c4cef757a8dc3a2', token_count=1047, vector_point_id='ch-doc-card-369-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-369-13', 'doc-card-369', 'sec-card-369-7', 13, ': «توان»، «مذاکره» را «بازتولید» می‌کند. ۶. «بافت‌محوری» و «تعمیم»: «معنا» در «بافت» «ساخته» می‌شود اما «بافت» «تعمیم» «پذیر» نیست: «بافت» «بومی» است و «تحلیل»، «بومی» لازم دارد. ۷. «ارتباط سازمانی» و «ساختار»: «ارتباط» در «ساختار» «سازمانی»، «بازتولید» «توان» است: «ساختار»، «ارتباط» است. ۸. «ارتباط» و «رسانه»: «ارتباط» «میان‌فردی» و «سازمانی» در «عصر دیجیتال»، «رسانه» «دیجیتال» «بازتعریف» می‌شود: «بافت» «دیجیتال»، «ارتباط» را «بازتولید» می‌کند. ۹. «هوش فرهنگی» و «بافت»: «هوش فرهنگی» در «بافت» «دیجیتال»، «بازتعریف» می‌شود: «بافت» «دیجیتال»، «فرهنگ» را «بازتولید» می‌کند.', '6bdec743a480fb86611d0cdb02061e889fbe8f7dd8911f02a030608c0f3c2be5', 1047, 'ch-doc-card-369-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6bdec743a480fb86611d0cdb02061e889fbe8f7dd8911f02a030608c0f3c2be5', token_count=1047, vector_point_id='ch-doc-card-369-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-369-14', 'doc-card-369', 'sec-card-369-10', 14, 'کتاب «ارتباط میان‌فردی» (آدلمن و همکاران، ۱۹۹۸)؛ کتاب «ارتباط سازمانی» (مکنزی و همکاران، ۲۰۰۵)؛ کتاب «ارتباط بین‌فرهنگی» (لومبونگ و همکاران، ۲۰۰۳)؛ کتاب «هوش فرهنگی» (رابن و همکاران، ۲۰۰۷).', '956a1e981812fd0aee168d40ca4cfc0e60c304bdfcef5b69be87a8e90e1ab9e3', 343, 'ch-doc-card-369-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='956a1e981812fd0aee168d40ca4cfc0e60c304bdfcef5b69be87a8e90e1ab9e3', token_count=343, vector_point_id='ch-doc-card-369-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-37-0', 'doc-card-37', NULL, 0, 'با کاهش هزینه ذخیره و توزیع، فروش مجموعه بزرگی از محتواهای کم‌فروش (تخصصی) می‌تواند هم‌ارز یا بیشتر از فروش معدودی محصول پرفروش (Blockbuster) شود. توزیع فروش از «سر» (Head) به «دم» (Tail) گسترش می‌یابد.', '2f7394446541fee4260eaef408e5a98d43fa28c91c468525a8ee2647b176a29d', 367, 'ch-doc-card-37-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2f7394446541fee4260eaef408e5a98d43fa28c91c468525a8ee2647b176a29d', token_count=367, vector_point_id='ch-doc-card-37-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-37-1', 'doc-card-37', 'sec-card-37-1', 1, 'اقتصاد توزیع دیجیتال / بازاریابی  با کاهش هزینه ذخیره و توزیع، فروش مجموعه بزرگی از محتواهای کم‌فروش (تخصصی) می‌تواند هم‌ارز یا بیشتر از فروش معدودی محصول پرفروش (Blockbuster) شود. توزیع فروش از «سر» (Head) به «دم» (Tail) گسترش می‌یابد.', 'dd2a92bb8be98856cf50f33dc3fef4560c5326c719208df3b79571f694eafa49', 429, 'ch-doc-card-37-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='dd2a92bb8be98856cf50f33dc3fef4560c5326c719208df3b79571f694eafa49', token_count=429, vector_point_id='ch-doc-card-37-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-37-2', 'doc-card-37', 'sec-card-37-2', 2, '۱. بنیان و منطق نظری دم بلند رسانه را به‌مثابه سازمان‌های استراتژیکی می‌داند که تحت ساختار بازار، الگوی مالکیت و انگیزه‌های اقتصادی شکل می‌گیرند. کریس اندرسون (۲۰۰۴) استدلال کرد که برای فهم رسانه باید فراتر از محتوای پیام برویم و شرایط اقتصادی و سازمانی تولید محتوا را تحلیل کنیم: چه کسی کانال‌ها را مالک است، درآمدها از کجا تأمین می‌شوند و رقابت چه محدودیت‌هایی بر سازمان‌ها تحمیل می‌کند. در این چارچوب، تصمیمات محتوایی نتیجه‌ی تلاقی منطق بازار و استراتژی سازمانی است.  بر اساس دم بلند، تولید محتوای رسانه‌ای فرایندی بازاری است که در آن سرمایه، نیروی کار و مخاطبان میان سازمان‌های متعدد در رقابت توزیع می‌شوند.', 'ca4ba1318e99685bd75083d94b2985c79f274788e31ed6504149db8c9f8c8cc8', 1110, 'ch-doc-card-37-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ca4ba1318e99685bd75083d94b2985c79f274788e31ed6504149db8c9f8c8cc8', token_count=1110, vector_point_id='ch-doc-card-37-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-37-3', 'doc-card-37', 'sec-card-37-2', 3, 'در آن سرمایه، نیروی کار و مخاطبان میان سازمان‌های متعدد در رقابت توزیع می‌شوند. این چارچوب که به کریس اندرسون نسبت داده می‌شود (۲۰۰۴)، ساختار مالکیت، رقابت و مقیاس در اقتصاد رسانه را تحلیل می‌کند تا نشان دهد چگونه انگیزه‌های سازمانی بر جریان محتوا شکل می‌دهند. پیش از آنکه بپرسیم پیام رسانه چگونه اثر می‌گذارد، باید بپرسیم این پیام‌ها در چه شرایط اقتصادی و در اختیار چه کسانی تولید می‌شوند.  دم بلند رسانه را به‌عنوان صنعتی استراتژیک در بازارهای دوسویّه‌ی مخاطب و تبلیغ‌دهنده (و در عصر دیجیتال، پلتفرم) می‌داند.', '93dc100cdbe06703eb25d55d83c6a4db096f5ee54c469c2ae26000ed53ffc7f5', 929, 'ch-doc-card-37-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='93dc100cdbe06703eb25d55d83c6a4db096f5ee54c469c2ae26000ed53ffc7f5', token_count=929, vector_point_id='ch-doc-card-37-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-37-4', 'doc-card-37', 'sec-card-37-2', 4, 'ک در بازارهای دوسویّه‌ی مخاطب و تبلیغ‌دهنده (و در عصر دیجیتال، پلتفرم) می‌داند. کریس اندرسون (۲۰۰۴) تأکید کرد که مدل کسب‌وکار — اشتراک، تبلیغات یا درآمدزایی از داده — ماهیت رابطه‌ی سازمان رسانه‌ای با مخاطب را تعیین می‌کند و در نتیجه ساختار محتوا را شکل می‌دهد. این رویکرد اقتصاد رسانه را در دل اقتصاد سازمان‌های صنعتی و مدیریت استراتژیک جای می‌دهد.  ۲. ساختارهای مفهومی • تمرکز مالکیت رسانه‌ای (Media Ownership Concentration): میزان تجمّع کانال‌های رسانه‌ای در دستان معدودی از مالکان و پیامدهای آن بر تنوع محتوا. • مدل کسب‌وکار (Business Model): سازوکار مشخصی که سازمان رسانه‌ای از طریق آن درآمد می‌آورد: تبلیغات، اشتراک، سرپرستی یا فروش داده.', '0963e3ff1f5949dfa1fb3ae91d3bae508effcd9f331dab0f66ac6215d914a773', 1169, 'ch-doc-card-37-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0963e3ff1f5949dfa1fb3ae91d3bae508effcd9f331dab0f66ac6215d914a773', token_count=1169, vector_point_id='ch-doc-card-37-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-37-5', 'doc-card-37', 'sec-card-37-2', 5, 'ازمان رسانه‌ای از طریق آن درآمد می‌آورد: تبلیغات، اشتراک، سرپرستی یا فروش داده. • بهای مقیاس (Economies of Scale): کاهش هزینه‌ی واحد تولید با افزایش حجم، که به سود سازمان‌های بزرگ است. • بازار دوسویه (Two-Sided Market): بازارهایی با دو گروه کاربر مکمّل (مانند مخاطب و تبلیغ‌دهنده) که ارزش هر گروه به دیگری وابسته است. • اثر شبکه‌ای (Network Effect): پدیده‌ای که در آن ارزش یک پلتفرم برای هر کاربر با افزایش تعداد کاربران دیگر بیشتر می‌شود. • استراتژی رقابتی (Competitive Strategy): انتخاب‌هایی که سازمان برای کسب م', '72c1627c1e8b194daab7df83d818d231bcd2dd47a335313a4369ca2b0e91723c', 934, 'ch-doc-card-37-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='72c1627c1e8b194daab7df83d818d231bcd2dd47a335313a4369ca2b0e91723c', token_count=934, vector_point_id='ch-doc-card-37-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-37-6', 'doc-card-37', 'sec-card-37-3', 6, 'هزینه توزیع و ذخیره؛ توصیه‌گر و فیلتر؛ محتوای تخصصی (Niche)؛ توزیع توانی (Power Law)؛ پرفروش‌ها (Blockbusters).', 'c0f7dbb1b99e62257141d9b5f4456acf44477c73e39b68028da4a646182a0903', 201, 'ch-doc-card-37-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c0f7dbb1b99e62257141d9b5f4456acf44477c73e39b68028da4a646182a0903', token_count=201, vector_point_id='ch-doc-card-37-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-37-7', 'doc-card-37', 'sec-card-37-4', 7, 'زیت پایدار در برابر رقبای بازار انجام می‌دهد. • سرمایه انسانی (Human Capital): دانش، مهارت و تجربه‌ی نیروی کار به‌عنوان منبع ارزش‌آفرینی در سازمان. • صنعت خلاق (Creative Industry): صنایعی که محصول اصلی آن‌ها محتوای فرهنگی و خلاق است و با عدم‌قطعیت بالای تقاضا روبه‌روند.  ۳. نمونه‌های تحلیلی در تمرکز روزافزون صنعت پخش، خرید یک استودیوی تولید بزرگ توسط یک پلتفرم استریم نمونه‌ای از استراتژی عمودی در خدمت بهای مقیاس است: هدف، کاهش وابستگی به محتوای بیرونی و هم‌زمان بزرگ‌تر کردن پایگاه مخاطب و داده است.', '3b3f97fd1ef2a6110ed720b9ae68d949679287009feeab44fa1875e64d3eb0a4', 914, 'ch-doc-card-37-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3b3f97fd1ef2a6110ed720b9ae68d949679287009feeab44fa1875e64d3eb0a4', token_count=914, vector_point_id='ch-doc-card-37-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-37-8', 'doc-card-37', 'sec-card-37-4', 8, 'کاهش وابستگی به محتوای بیرونی و هم‌زمان بزرگ‌تر کردن پایگاه مخاطب و داده است.  در مطبوعات، گروه‌های روزنامه‌ای که فعالیت خود را به تلویزیون و فضای دیجیتال گسترش داده و درآمدها را فراتر از تبلیغات متنوع کرده‌اند، نمونه‌ی استراتژی تنوع‌بخشی برای حفظ بقا در بازاری رو به افول هستند.  وقتی یک خبرگزاری بزرگ از مدل درآمدی تبلیغاتی به مدل اشتراک‌دار می‌رود، در عمل تعریف خود از رابطه با مخاطب را بازنویسی می‌کند: مخاطب دیگر کالایی نیست که به تبلیغ‌دهنده فروخته شود، بلکه مشتری است؛ این جابه‌جایی اولویت‌های محتوایی و پاسخگویی رسانه را تغییر می‌دهد.', '7962f055ca9621273d405f50ace39e9b642498ed52576f204fef3813280de916', 985, 'ch-doc-card-37-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7962f055ca9621273d405f50ace39e9b642498ed52576f204fef3813280de916', token_count=985, vector_point_id='ch-doc-card-37-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-37-9', 'doc-card-37', 'sec-card-37-4', 9, 'مشتری است؛ این جابه‌جایی اولویت‌های محتوایی و پاسخگویی رسانه را تغییر می‌دهد.  یک روزنامه‌ی محلی کوچک با اتکا به یارانه‌های جمعی و نشریات خبری پولی، در برابر منطق مقیاس پلتفرم‌ها مقاومت می‌کند؛ استراتژی‌ای که واکنشی است به ناتوانی سازمان‌های کوچک در رقابت مستقیم برای توجه.  رقابت پلتفرم‌های محتوا بر «محتوای انحصاری» نمونه‌ای از منطق بازار دوسویه است: از یک سو تولیدکنندگانی که محتوا و داده ارائه می‌دهند و از سوی دیگر مخاطبانی که توجه خود را عرضه می‌کنند؛ پلتفرم با کاهش هزینه‌ی تعامل میان این دو سمت سود می‌برد.', '8fe1d2c1ead92aa527938e4b4b9215a3b3082d18171de50a26ab3ac792fdf228', 934, 'ch-doc-card-37-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8fe1d2c1ead92aa527938e4b4b9215a3b3082d18171de50a26ab3ac792fdf228', token_count=934, vector_point_id='ch-doc-card-37-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-37-10', 'doc-card-37', 'sec-card-37-4', 10, 'خود را عرضه می‌کنند؛ پلتفرم با کاهش هزینه‌ی تعامل میان این دو سمت سود می‌برد.  در صنعت رسانه، ورود شرکت‌های تولیدی از دل شبکه‌های پخش و مذاکره‌ی آن‌ها بر سر سهم درآمدها، نمونه‌ای عملی است از تبدیل سرمایه‌ی انسانی و خلاق به قدرت چانه‌زنی در بازار.  ۴. نقدها و چالش‌ها ۱. تقلیل رسانه به منطق بازار: این چارچوب گرایش دارد بُعد فرهنگی و سیاسی محتوا را به‌عنوان اثرات فرعی بازار در نظر بگیرد و کارکرد عمومی و اجتماعی رسانه را دست‌کم بگیرد. ۲. ساختار متغیر در عصر دیجیتال: مدل‌های کلاسیک ساختار بازار و رقابت (تمرکز، مانع ورود) با واقعیت خدمات رایگان، بازارهای دوسویه و پلتفرمی‌شدن هم‌خوانی کامل ندارند. ۳.', '16e2183fba65a3c9cac340321daba91b844b5cf8ea0abe27bde047ce784c0211', 1090, 'ch-doc-card-37-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='16e2183fba65a3c9cac340321daba91b844b5cf8ea0abe27bde047ce784c0211', token_count=1090, vector_point_id='ch-doc-card-37-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-37-11', 'doc-card-37', 'sec-card-37-4', 11, 'با واقعیت خدمات رایگان، بازارهای دوسویه و پلتفرمی‌شدن هم‌خوانی کامل ندارند. ۳. دشواری سنجش: مفاهیمی مانند «توجه» و «ارزش مخاطب» در عصر پلتفرم معیارهای اندازه‌گیری معتبر و استانداردی ندارند و م', 'ea22e6be30130e77e0dd5cf6d2675d057766f2c17e43a0de846eaa1a2425c583', 349, 'ch-doc-card-37-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ea22e6be30130e77e0dd5cf6d2675d057766f2c17e43a0de846eaa1a2425c583', token_count=349, vector_point_id='ch-doc-card-37-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-37-12', 'doc-card-37', 'sec-card-37-5', 12, 'پادکست‌های تخصصی، کتابخانه‌های بزرگ استریم، و محتوای مستقل. تحلیل کنید الگوریتم توصیه‌گر چگونه فروش دم را فعال یا به نفع پرفروش‌ها سوگیرانه می‌کند.', '93da2a04f2bc4565ccf50dcfd1a8cc28e05f24d396424ec52b24cde401f5772e', 267, 'ch-doc-card-37-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='93da2a04f2bc4565ccf50dcfd1a8cc28e05f24d396424ec52b24cde401f5772e', token_count=267, vector_point_id='ch-doc-card-37-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-37-13', 'doc-card-37', 'sec-card-37-6', 13, 'الینبرگ (Elberse، ۲۰۰۸) نشان داد درآمد عمدتاً همچنان در سر متمرکز است و دم «سنگین‌تر و نازک‌تر» می‌شود. ادعای اندرسون در عمل بیش از حد خوش‌بینانه ارزیابی شده است.', '853a26da5b346714c838ca5bca57b8f672f08b273f83343725d4a0256d287eec', 294, 'ch-doc-card-37-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='853a26da5b346714c838ca5bca57b8f672f08b273f83343725d4a0256d287eec', token_count=294, vector_point_id='ch-doc-card-37-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-37-14', 'doc-card-37', 'sec-card-37-10', 14, 'استناد علمی مبنا (APA 7): Anderson (2006)', 'b92f2041a84f43144afa7f4f374aa85ca100824c56fbf04960ceb593bf8533b2', 74, 'ch-doc-card-37-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b92f2041a84f43144afa7f4f374aa85ca100824c56fbf04960ceb593bf8533b2', token_count=74, vector_point_id='ch-doc-card-37-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-370-0', 'doc-card-370', NULL, 0, 'هچ و سندبرگ در «مکانیزم‌های اجماع» (1988) پنج فیلتر ساختاری — مالکیت شرکتی، اتکا به درآمد آگهی، اتکا به منابع رسمی، حملات هماهنگ انتقادی و ایدئولوژی ضدیت مشترک — را شناسایی می‌کنند که اذهان عمومی را در جهت منافع سلطه‌گران شکل می‌دهند.', 'b9b7bc1c38e78a2cf54894c417269cab4f248ef519394f241390fdc4ce045b9c', 425, 'ch-doc-card-370-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b9b7bc1c38e78a2cf54894c417269cab4f248ef519394f241390fdc4ce045b9c', token_count=425, vector_point_id='ch-doc-card-370-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-370-1', 'doc-card-370', 'sec-card-370-1', 1, 'ارتباطات بین‌فرهنگی، سازمانی و میان‌فردی  پنج فیلتر ساختاری رسانه‌های جمعی برای دستکاری اذهان: مالکیت کمپانی‌ها، اتکا به آگهی‌ها، استفاده از منابع رسمی، حملات هماهنگ انتقادی و ایدئولوژی ضدیت مشترک.', 'b9020ab9ff06d38b5a05a4f1ada734db709e0578dc3e6aa9759b1af9348faac2', 358, 'ch-doc-card-370-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b9020ab9ff06d38b5a05a4f1ada734db709e0578dc3e6aa9759b1af9348faac2', token_count=358, vector_point_id='ch-doc-card-370-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-370-2', 'doc-card-370', 'sec-card-370-2', 2, '۱. بنیان و منطق نظری پروپاگاندا و دستکاری افکار عمومی «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». ادوارد برنیز (۱۹۲۸) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس پروپاگاندا و دستکاری افکار عمومی، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. ادوارد برنیز (۱۹۲۸) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', 'c34d178b2348501ab8a1cbdcc66b07893311f6f565d7f07b3a5781ac6ab89482', 1007, 'ch-doc-card-370-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c34d178b2348501ab8a1cbdcc66b07893311f6f565d7f07b3a5781ac6ab89482', token_count=1007, vector_point_id='ch-doc-card-370-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-370-3', 'doc-card-370', 'sec-card-370-2', 3, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  پروپاگاندا و دستکاری افکار عمومی را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. ادوارد برنیز (۱۹۲۸) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.  ۲. ساختارهای مفهومی • ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند.', 'fa997b39883192d59eaf1fecae7ecf6a5b61ddf3d23c73f1d1d95e57671ce276', 1152, 'ch-doc-card-370-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fa997b39883192d59eaf1fecae7ecf6a5b61ddf3d23c73f1d1d95e57671ce276', token_count=1152, vector_point_id='ch-doc-card-370-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-370-4', 'doc-card-370', 'sec-card-370-2', 4, ': «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. •', 'c5afb1f90a14836a649ab460cbe79a34f6dab51faf77e2a8e089ea67b95f71fb', 756, 'ch-doc-card-370-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c5afb1f90a14836a649ab460cbe79a34f6dab51faf77e2a8e089ea67b95f71fb', token_count=756, vector_point_id='ch-doc-card-370-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-370-5', 'doc-card-370', 'sec-card-370-3', 5, '• ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. • تعارض و مذاکره (Conflict and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است.', 'bf50a19f3fa6a4558d5edbd42200280c7f4b92c377964c4e6187e1ed0133db26', 1230, 'ch-doc-card-370-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bf50a19f3fa6a4558d5edbd42200280c7f4b92c377964c4e6187e1ed0133db26', token_count=1230, vector_point_id='ch-doc-card-370-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-370-6', 'doc-card-370', 'sec-card-370-3', 6, 'flict and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است. • بافت‌محوری (Contextualism): «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • قدرت و نقش (Power and Role): «توان» در «ارتباط»: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.', 'b64e4de88dbaf207aea343dd750d2b2d8bd0b257fd13137445296eaa2c40c444', 527, 'ch-doc-card-370-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b64e4de88dbaf207aea343dd750d2b2d8bd0b257fd13137445296eaa2c40c444', token_count=527, vector_point_id='ch-doc-card-370-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-370-7', 'doc-card-370', 'sec-card-370-4', 7, 'تعارض و مذاکره (Conflict and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است. • بافت‌محوری (Contextualism): «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • قدرت و نقش (Power and Role): «توان» در «ارتباط»: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  ۳. نمونه‌های تحلیلی «ارتباط میان‌فردی» در عمل: «گفت‌وگو» بین «دوستان» «معنا» «ساخته» می‌شود: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  «ارتباط سازمانی» در عمل: «جلسه» «سازمانی»، «بافت» «توان» است: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.', 'e9b227f11bbc53723ae52db22e14c70cc08ee74c1a4655a95ca3d0ca78b84212', 1034, 'ch-doc-card-370-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e9b227f11bbc53723ae52db22e14c70cc08ee74c1a4655a95ca3d0ca78b84212', token_count=1034, vector_point_id='ch-doc-card-370-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-370-8', 'doc-card-370', 'sec-card-370-4', 8, 'سازمانی»، «بافت» «توان» است: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  «ارتباط بین‌فرهنگی» در عمل: «مذاکره» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است و «فهم» «فرهنگ» دیگر، «توان» است.  «هوش فرهنگی» در عمل: «مذاکره‌گر» با «هوش فرهنگی» «بافت» «دیگر» را «فهم» می‌کند: «ارتباط» در «بافت» «بین‌فرهنگی»، «توان» است.  «تعارض و مذاکره» در عمل: «مذاکره» «حل» «تعارض» است: «ارتباط» در «تعارض»، «بافت» «حل» است.  «بافت‌محوری» در عمل: «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» (فرهنگ) و «بافت» «کوچک» (گفت‌وگو) در هم تنیده‌اند.  ۴. نقدها و چالش‌ها ۱.', '37eda6dbe33a68cb291ccc8be06afd1d48eaf537275730581dd4e2a6fec25095', 1018, 'ch-doc-card-370-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='37eda6dbe33a68cb291ccc8be06afd1d48eaf537275730581dd4e2a6fec25095', token_count=1018, vector_point_id='ch-doc-card-370-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-370-9', 'doc-card-370', 'sec-card-370-4', 9, 'بزرگ» (فرهنگ) و «بافت» «کوچک» (گفت‌وگو) در هم تنیده‌اند.  ۴. نقدها و چالش‌ها ۱. «میان‌فردی» و «بافت»: «ارتباط» «میان‌فردی» در «بافت» «توان» است: «توان» در «گفت‌وگو» عمل می‌کند و «میان‌فردی»، «میان‌ساختاری» است. ۲. «فرهنگ سازمانی» و «قدرت»: «فرهنگ» در سازمان، «قدرت» است: «فرهنگ» «رقابت»، «فشار» می‌سازد و «ارتباط» را «بازتولید» می‌کند. ۳. «هوش فرهنگی» و «استعمار»: «هوش فرهنگی» می‌تواند «تثبیت» «فرهنگ» دیگر باشد: «فهم» «فرهنگ» دیگر، «آزادی» نیست، «توان» است. ۴. «ارتباط بین', '3977cfd07fcc1d49c720800d2be1ea622dfa5416e8deac226c68dd692bdb8895', 861, 'ch-doc-card-370-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3977cfd07fcc1d49c720800d2be1ea622dfa5416e8deac226c68dd692bdb8895', token_count=861, vector_point_id='ch-doc-card-370-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
