INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-379-10', 'doc-card-379', 'sec-card-379-5', 10, '«ارتباط میان‌فردی» در عمل: «گفت‌وگو» بین «دوستان» «معنا» «ساخته» می‌شود: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  «ارتباط سازمانی» در عمل: «جلسه» «سازمانی»، «بافت» «توان» است: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  «ارتباط بین‌فرهنگی» در عمل: «مذاکره» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است و «فهم» «فرهنگ» دیگر، «توان» است.  «هوش فرهنگی» در عمل: «مذاکره‌گر» با «هوش فرهنگی» «بافت» «دیگر» را «فهم» می‌کند: «ارتباط» در «بافت» «بین‌فرهنگی»، «توان» است.  «تعارض و مذاکره» در عمل: «مذاکره» «حل» «تعارض» است: «ارتباط» در «تعارض»، «بافت» «حل» است.', '6bf4912c61268e9f65d68aec8a8d0992a53f96d0f18bf9e19d75cf9dcd421de5', 1049, 'ch-doc-card-379-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6bf4912c61268e9f65d68aec8a8d0992a53f96d0f18bf9e19d75cf9dcd421de5', token_count=1049, vector_point_id='ch-doc-card-379-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-379-11', 'doc-card-379', 'sec-card-379-5', 11, 'اکره» در عمل: «مذاکره» «حل» «تعارض» است: «ارتباط» در «تعارض»، «بافت» «حل» است.  «بافت‌محوری» در عمل: «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» (فرهنگ) و «بافت» «کوچک» (گفت‌وگو) در هم تنیده‌اند.', '70e3ddf05c8eaea9d7529c749dddc708444781f2934e78b2fabb313171dbc2bc', 359, 'ch-doc-card-379-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='70e3ddf05c8eaea9d7529c749dddc708444781f2934e78b2fabb313171dbc2bc', token_count=359, vector_point_id='ch-doc-card-379-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-379-12', 'doc-card-379', 'sec-card-379-6', 12, '۱. «میان‌فردی» و «بافت»: «ارتباط» «میان‌فردی» در «بافت» «توان» است: «توان» در «گفت‌وگو» عمل می‌کند و «میان‌فردی»، «میان‌ساختاری» است. ۲. «فرهنگ سازمانی» و «قدرت»: «فرهنگ» در سازمان، «قدرت» است: «فرهنگ» «رقابت»، «فشار» می‌سازد و «ارتباط» را «بازتولید» می‌کند. ۳. «هوش فرهنگی» و «استعمار»: «هوش فرهنگی» می‌تواند «تثبیت» «فرهنگ» دیگر باشد: «فهم» «فرهنگ» دیگر، «آزادی» نیست، «توان» است. ۴. «ارتباط بین‌فرهنگی» و «دوگانه»: «فرهنگ» «دوگانه» نیست: «تنوع» داخل «فرهنگ» به‌قدری «بزرگ» است که «دوگانه» «افسانه» است. ۵. «مذاکره» و «توان»: «مذاکره» در «توان» «نامتقارن»، «حل» «تعارض» نیست', 'c23b7447826b60647458a2d7d01fc71144cc1a740dda9a9d6c4cef757a8dc3a2', 1047, 'ch-doc-card-379-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c23b7447826b60647458a2d7d01fc71144cc1a740dda9a9d6c4cef757a8dc3a2', token_count=1047, vector_point_id='ch-doc-card-379-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-379-13', 'doc-card-379', 'sec-card-379-7', 13, ': «توان»، «مذاکره» را «بازتولید» می‌کند. ۶. «بافت‌محوری» و «تعمیم»: «معنا» در «بافت» «ساخته» می‌شود اما «بافت» «تعمیم» «پذیر» نیست: «بافت» «بومی» است و «تحلیل»، «بومی» لازم دارد. ۷. «ارتباط سازمانی» و «ساختار»: «ارتباط» در «ساختار» «سازمانی»، «بازتولید» «توان» است: «ساختار»، «ارتباط» است. ۸. «ارتباط» و «رسانه»: «ارتباط» «میان‌فردی» و «سازمانی» در «عصر دیجیتال»، «رسانه» «دیجیتال» «بازتعریف» می‌شود: «بافت» «دیجیتال»، «ارتباط» را «بازتولید» می‌کند. ۹. «هوش فرهنگی» و «بافت»: «هوش فرهنگی» در «بافت» «دیجیتال»، «بازتعریف» می‌شود: «بافت» «دیجیتال»، «فرهنگ» را «بازتولید» می‌کند.', '6bdec743a480fb86611d0cdb02061e889fbe8f7dd8911f02a030608c0f3c2be5', 1047, 'ch-doc-card-379-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6bdec743a480fb86611d0cdb02061e889fbe8f7dd8911f02a030608c0f3c2be5', token_count=1047, vector_point_id='ch-doc-card-379-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-379-14', 'doc-card-379', 'sec-card-379-10', 14, 'کتاب «ارتباط میان‌فردی» (آدلمن و همکاران، ۱۹۹۸)؛ کتاب «ارتباط سازمانی» (مکنزی و همکاران، ۲۰۰۵)؛ کتاب «ارتباط بین‌فرهنگی» (لومبونگ و همکاران، ۲۰۰۳)؛ کتاب «هوش فرهنگی» (رابن و همکاران، ۲۰۰۷).', '956a1e981812fd0aee168d40ca4cfc0e60c304bdfcef5b69be87a8e90e1ab9e3', 343, 'ch-doc-card-379-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='956a1e981812fd0aee168d40ca4cfc0e60c304bdfcef5b69be87a8e90e1ab9e3', token_count=343, vector_point_id='ch-doc-card-379-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-38-0', 'doc-card-38', NULL, 0, 'اقتصاد سیاسی رسانه محتوای رسانه را محصول ساختار مالکیت، منابع مالی و روابط قدرت می‌داند. هرمن و چومسکی پنج «فیلتر» (مالکیت، تبلیغات، منابع خبر، فشار و نقد، و ایدئولوژی دشمن مشترک) را نام می‌برند که جریان خبر را شکل می‌دهند.', 'e465dfc554db59bc7a04eba570afd63927631b0fb139e5627edf79c9be3a5e36', 405, 'ch-doc-card-38-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e465dfc554db59bc7a04eba570afd63927631b0fb139e5627edf79c9be3a5e36', token_count=405, vector_point_id='ch-doc-card-38-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-38-1', 'doc-card-38', 'sec-card-38-1', 1, 'نظریه انتقادی / اقتصاد سیاسی ارتباطات  محتوای رسانه از ساختار مالکیت، منابع تأمین مالی و روابط قدرت متأثر است. در مدل پروپاگاندا پنج «فیلتر» (مالکیت، تبلیغات، منابع خبر، فشار و نقد، و ایدئولوژی دشمن مشترک) خبر را شکل می‌دهند.', '6e3079f8bc709c98b444b66b93114953444788c2a4648388a3fee46c3b39abd0', 409, 'ch-doc-card-38-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6e3079f8bc709c98b444b66b93114953444788c2a4648388a3fee46c3b39abd0', token_count=409, vector_point_id='ch-doc-card-38-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-38-2', 'doc-card-38', 'sec-card-38-2', 2, '۱. بنیان و منطق نظری اقتصاد سیاسی رسانه رسانه را به‌مثابه سازمان‌های استراتژیکی می‌داند که تحت ساختار بازار، الگوی مالکیت و انگیزه‌های اقتصادی شکل می‌گیرند. هرمن (۱۹۸۸) استدلال کرد که برای فهم رسانه باید فراتر از محتوای پیام برویم و شرایط اقتصادی و سازمانی تولید محتوا را تحلیل کنیم: چه کسی کانال‌ها را مالک است، درآمدها از کجا تأمین می‌شوند و رقابت چه محدودیت‌هایی بر سازمان‌ها تحمیل می‌کند. در این چارچوب، تصمیمات محتوایی نتیجه‌ی تلاقی منطق بازار و استراتژی سازمانی است.  بر اساس اقتصاد سیاسی رسانه، تولید محتوای رسانه‌ای فرایندی بازاری است که در آن سرمایه، نیروی کار و مخاطبان میان سازمان‌های متعدد در رقابت توزیع می‌شوند.', 'a3775ea8c822a7c1169dc050ebc1808baa4bf0941573d03edf6096f1d8ec483f', 1136, 'ch-doc-card-38-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a3775ea8c822a7c1169dc050ebc1808baa4bf0941573d03edf6096f1d8ec483f', token_count=1136, vector_point_id='ch-doc-card-38-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-38-3', 'doc-card-38', 'sec-card-38-2', 3, 'در آن سرمایه، نیروی کار و مخاطبان میان سازمان‌های متعدد در رقابت توزیع می‌شوند. این چارچوب که به هرمن نسبت داده می‌شود (۱۹۸۸)، ساختار مالکیت، رقابت و مقیاس در اقتصاد رسانه را تحلیل می‌کند تا نشان دهد چگونه انگیزه‌های سازمانی بر جریان محتوا شکل می‌دهند. پیش از آنکه بپرسیم پیام رسانه چگونه اثر می‌گذارد، باید بپرسیم این پیام‌ها در چه شرایط اقتصادی و در اختیار چه کسانی تولید می‌شوند.  اقتصاد سیاسی رسانه رسانه را به‌عنوان صنعتی استراتژیک در بازارهای دوسویّه‌ی مخاطب و تبلیغ‌دهنده (و در عصر دیجیتال، پلتفرم) می‌داند.', '51fe871591b8f4c2c6db7de0848bbd84455380e7e3de519e9fb37ac3ee0b403e', 934, 'ch-doc-card-38-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='51fe871591b8f4c2c6db7de0848bbd84455380e7e3de519e9fb37ac3ee0b403e', token_count=934, vector_point_id='ch-doc-card-38-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-38-4', 'doc-card-38', 'sec-card-38-2', 4, 'ک در بازارهای دوسویّه‌ی مخاطب و تبلیغ‌دهنده (و در عصر دیجیتال، پلتفرم) می‌داند. هرمن (۱۹۸۸) تأکید کرد که مدل کسب‌وکار — اشتراک، تبلیغات یا درآمدزایی از داده — ماهیت رابطه‌ی سازمان رسانه‌ای با مخاطب را تعیین می‌کند و در نتیجه ساختار محتوا را شکل می‌دهد. این رویکرد اقتصاد رسانه را در دل اقتصاد سازمان‌های صنعتی و مدیریت استراتژیک جای می‌دهد.  ۲. ساختارهای مفهومی • تمرکز مالکیت رسانه‌ای (Media Ownership Concentration): میزان تجمّع کانال‌های رسانه‌ای در دستان معدودی از مالکان و پیامدهای آن بر تنوع محتوا. • مدل کسب‌وکار (Business Model): سازوکار مشخصی که سازمان رسانه‌ای از طریق آن درآمد می‌آورد: تبلیغات، اشتراک، سرپرستی یا فروش داده.', '38621400b43f40c9dfeb0d62eb879e5788bc60e0e875839aa49cc4303d6411de', 1154, 'ch-doc-card-38-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='38621400b43f40c9dfeb0d62eb879e5788bc60e0e875839aa49cc4303d6411de', token_count=1154, vector_point_id='ch-doc-card-38-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-38-5', 'doc-card-38', 'sec-card-38-2', 5, 'ازمان رسانه‌ای از طریق آن درآمد می‌آورد: تبلیغات، اشتراک، سرپرستی یا فروش داده. • بهای مقیاس (Economies of Scale): کاهش هزینه‌ی واحد تولید با افزایش حجم، که به سود سازمان‌های بزرگ است. • بازار دوسویه (Two-Sided Market): بازارهایی با دو گروه کاربر مکمّل (مانند مخاطب و تبلیغ‌دهنده) که ارزش هر گروه به دیگری وابسته است. • اثر شبکه‌ای (Network Effect): پدیده‌ای که در آن ارزش یک پلتفرم برای هر کاربر با افزایش تعداد کاربران دیگر بیشتر می‌شود. • استراتژی رقابتی (Competitive Strategy): انتخاب‌هایی که سازمان برای کسب', '065c8f768873e64bd1c431c2e48d0cda573ca2fe213f9e978049e1eb1d4d327e', 930, 'ch-doc-card-38-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='065c8f768873e64bd1c431c2e48d0cda573ca2fe213f9e978049e1eb1d4d327e', token_count=930, vector_point_id='ch-doc-card-38-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-38-6', 'doc-card-38', 'sec-card-38-3', 6, 'پنج فیلتر هرمن و چامسکی؛ کالایی‌سازی (Commodification)؛ فضامندی (Spatialization)؛ ساختاربندی (Structuration)؛ کار مخاطب (Audience Labour)؛ سرمایه‌داری نظارتی (Zuboff، ۲۰۱۹).', '4c86c9638ca1f3f87277419501fa836f2c5049c65d9642d93df530220d9d18a9', 314, 'ch-doc-card-38-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4c86c9638ca1f3f87277419501fa836f2c5049c65d9642d93df530220d9d18a9', token_count=314, vector_point_id='ch-doc-card-38-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-38-7', 'doc-card-38', 'sec-card-38-4', 7, 'مزیت پایدار در برابر رقبای بازار انجام می‌دهد. • سرمایه انسانی (Human Capital): دانش، مهارت و تجربه‌ی نیروی کار به‌عنوان منبع ارزش‌آفرینی در سازمان. • صنعت خلاق (Creative Industry): صنایعی که محصول اصلی آن‌ها محتوای فرهنگی و خلاق است و با عدم‌قطعیت بالای تقاضا روبه‌روند.  ۳. نمونه‌های تحلیلی در تمرکز روزافزون صنعت پخش، خرید یک استودیوی تولید بزرگ توسط یک پلتفرم استریم نمونه‌ای از استراتژی عمودی در خدمت بهای مقیاس است: هدف، کاهش وابستگی به محتوای بیرونی و هم‌زمان بزرگ‌تر کردن پایگاه مخاطب و داده است.', 'b5fec855253e2ae05ed9c87e5c8bbede1d8669e8ea20a6ca648c6726e9db64b0', 916, 'ch-doc-card-38-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b5fec855253e2ae05ed9c87e5c8bbede1d8669e8ea20a6ca648c6726e9db64b0', token_count=916, vector_point_id='ch-doc-card-38-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-38-8', 'doc-card-38', 'sec-card-38-4', 8, 'کاهش وابستگی به محتوای بیرونی و هم‌زمان بزرگ‌تر کردن پایگاه مخاطب و داده است.  در مطبوعات، گروه‌های روزنامه‌ای که فعالیت خود را به تلویزیون و فضای دیجیتال گسترش داده و درآمدها را فراتر از تبلیغات متنوع کرده‌اند، نمونه‌ی استراتژی تنوع‌بخشی برای حفظ بقا در بازاری رو به افول هستند.  وقتی یک خبرگزاری بزرگ از مدل درآمدی تبلیغاتی به مدل اشتراک‌دار می‌رود، در عمل تعریف خود از رابطه با مخاطب را بازنویسی می‌کند: مخاطب دیگر کالایی نیست که به تبلیغ‌دهنده فروخته شود، بلکه مشتری است؛ این جابه‌جایی اولویت‌های محتوایی و پاسخگویی رسانه را تغییر می‌دهد.', '7962f055ca9621273d405f50ace39e9b642498ed52576f204fef3813280de916', 985, 'ch-doc-card-38-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7962f055ca9621273d405f50ace39e9b642498ed52576f204fef3813280de916', token_count=985, vector_point_id='ch-doc-card-38-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-38-9', 'doc-card-38', 'sec-card-38-4', 9, 'مشتری است؛ این جابه‌جایی اولویت‌های محتوایی و پاسخگویی رسانه را تغییر می‌دهد.  یک روزنامه‌ی محلی کوچک با اتکا به یارانه‌های جمعی و نشریات خبری پولی، در برابر منطق مقیاس پلتفرم‌ها مقاومت می‌کند؛ استراتژی‌ای که واکنشی است به ناتوانی سازمان‌های کوچک در رقابت مستقیم برای توجه.  رقابت پلتفرم‌های محتوا بر «محتوای انحصاری» نمونه‌ای از منطق بازار دوسویه است: از یک سو تولیدکنندگانی که محتوا و داده ارائه می‌دهند و از سوی دیگر مخاطبانی که توجه خود را عرضه می‌کنند؛ پلتفرم با کاهش هزینه‌ی تعامل میان این دو سمت سود می‌برد.', '8fe1d2c1ead92aa527938e4b4b9215a3b3082d18171de50a26ab3ac792fdf228', 934, 'ch-doc-card-38-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8fe1d2c1ead92aa527938e4b4b9215a3b3082d18171de50a26ab3ac792fdf228', token_count=934, vector_point_id='ch-doc-card-38-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-38-10', 'doc-card-38', 'sec-card-38-4', 10, 'خود را عرضه می‌کنند؛ پلتفرم با کاهش هزینه‌ی تعامل میان این دو سمت سود می‌برد.  در صنعت رسانه، ورود شرکت‌های تولیدی از دل شبکه‌های پخش و مذاکره‌ی آن‌ها بر سر سهم درآمدها، نمونه‌ای عملی است از تبدیل سرمایه‌ی انسانی و خلاق به قدرت چانه‌زنی در بازار.  ۴. نقدها و چالش‌ها ۱. تقلیل رسانه به منطق بازار: این چارچوب گرایش دارد بُعد فرهنگی و سیاسی محتوا را به‌عنوان اثرات فرعی بازار در نظر بگیرد و کارکرد عمومی و اجتماعی رسانه را دست‌کم بگیرد. ۲. ساختار متغیر در عصر دیجیتال: مدل‌های کلاسیک ساختار بازار و رقابت (تمرکز، مانع ورود) با واقعیت خدمات رایگان، بازارهای دوسویه و پلتفرمی‌شدن هم‌خوانی کامل ندارند. ۳.', '16e2183fba65a3c9cac340321daba91b844b5cf8ea0abe27bde047ce784c0211', 1090, 'ch-doc-card-38-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='16e2183fba65a3c9cac340321daba91b844b5cf8ea0abe27bde047ce784c0211', token_count=1090, vector_point_id='ch-doc-card-38-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-38-11', 'doc-card-38', 'sec-card-38-4', 11, 'با واقعیت خدمات رایگان، بازارهای دوسویه و پلتفرمی‌شدن هم‌خوانی کامل ندارند. ۳. دشواری سنجش: مفاهیمی مانند «توجه» و «ارزش مخاطب» در عصر پلتفرم معیارهای اندازه‌گیری معتبر و استانداردی ندارند و مقایسه', '57eb3da4d48c75c310fb40ae4860a125dfb9d475eb26c3b4a007ca61c04b67de', 358, 'ch-doc-card-38-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='57eb3da4d48c75c310fb40ae4860a125dfb9d475eb26c3b4a007ca61c04b67de', token_count=358, vector_point_id='ch-doc-card-38-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-38-12', 'doc-card-38', 'sec-card-38-5', 12, 'تحلیل اینکه وابستگی مالی به آگهی‌دهندگان، یا مالکیت یک بنگاه خبری توسط گروه‌های بزرگ، بر انتخاب موضوع و قاب‌بندی اثر می‌گذارد. همچنین، داده‌های کاربران به‌عنوان کالا در مدل پلتفرمی.', '64e8d5b131c0f8b8061010992c783ff669d08683126edd37ce54e041fdeec440', 329, 'ch-doc-card-38-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='64e8d5b131c0f8b8061010992c783ff669d08683126edd37ce54e041fdeec440', token_count=329, vector_point_id='ch-doc-card-38-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-38-13', 'doc-card-38', 'sec-card-38-6', 13, 'مدل پروپاگاندا با تعیین‌گرایی ساختاری مورد نقد است و عاملیت روزنامه‌نگاران و مخاطبان را کم‌اهمیت می‌گیرد. اثبات علّی تأثیر مالکیت بر محتوا دشوار است و مدل بیشتر برای رسانه‌های آمریکایی طراحی شده است.', '1035c6141e3760f884b78389510261baab5047932486ce4cb2ead72e523ab8a4', 361, 'ch-doc-card-38-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1035c6141e3760f884b78389510261baab5047932486ce4cb2ead72e523ab8a4', token_count=361, vector_point_id='ch-doc-card-38-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-38-14', 'doc-card-38', 'sec-card-38-10', 14, 'استناد علمی مبنا (APA 7): Smythe (1977); Mosco (1996)', '8ec85d3b1763279f184e36cfd26040c8320349d3da1c5c0aa392b6348abd9038', 96, 'ch-doc-card-38-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8ec85d3b1763279f184e36cfd26040c8320349d3da1c5c0aa392b6348abd9038', token_count=96, vector_point_id='ch-doc-card-38-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-380-0', 'doc-card-380', NULL, 0, 'رویکردی که روابط عمومی، تبلیغات، بازاریابی و ارتباطات داخلی را در یک برنامه راهبردی واحد یکپارچه می‌کند تا پیام‌های هم‌راستا در خدمت مأموریت و بقای سازمان تولید شوند؛ هالاهان هم‌راستایی عملیاتی این رشته‌ها را بر هم‌پوشانی صرف ترجیح می‌دهد.', 'b4b2f4d782a3548dd5da9e5411f038e5f84bdad1fd6a3fe453d5c172a54ef0f1', 434, 'ch-doc-card-380-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b4b2f4d782a3548dd5da9e5411f038e5f84bdad1fd6a3fe453d5c172a54ef0f1', token_count=434, vector_point_id='ch-doc-card-380-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-380-1', 'doc-card-380', 'sec-card-380-1', 1, 'ارتباطات بین‌فرهنگی، سازمانی و میان‌فردی  تجمیع و هم‌راستاسازی رشته‌های روابط عمومی، تبلیغات، بازاریابی و ارتباطات داخلی برای پیشبرد مأموریت کلی و اهداف بقای سازمان.', '8ebcf7d1c81f8054fd708aa04c0c64c4eb2fe9738b99ced11ce1457880cd3cbe', 300, 'ch-doc-card-380-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8ebcf7d1c81f8054fd708aa04c0c64c4eb2fe9738b99ced11ce1457880cd3cbe', token_count=300, vector_point_id='ch-doc-card-380-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-380-2', 'doc-card-380', 'sec-card-380-2', 2, '۱. بنیان و منطق نظری ارتباطات استراتژیک «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». کرک هالاهان (۲۰۰۷) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس ارتباطات استراتژیک، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. کرک هالاهان (۲۰۰۷) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', 'abb90ffb48cc7092b0651d0cf594056bd4472b3b1ffd559b4e478c2d39384ea9', 952, 'ch-doc-card-380-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='abb90ffb48cc7092b0651d0cf594056bd4472b3b1ffd559b4e478c2d39384ea9', token_count=952, vector_point_id='ch-doc-card-380-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-380-3', 'doc-card-380', 'sec-card-380-2', 3, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  ارتباطات استراتژیک را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. کرک هالاهان (۲۰۰۷) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.  ۲. ساختارهای مفهومی • ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند.', 'ff57e7b4eb460a39c5c59c9ab3ce742e87d9c59e08bf9a640b0a9425bc5d8115', 1125, 'ch-doc-card-380-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ff57e7b4eb460a39c5c59c9ab3ce742e87d9c59e08bf9a640b0a9425bc5d8115', token_count=1125, vector_point_id='ch-doc-card-380-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-380-4', 'doc-card-380', 'sec-card-380-2', 4, ': «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. • تعارض و مذاکره (Conflict', 'fc027e099a654f68114534fa40d1a97900d33dd8a78874e69ec4c8770bea550b', 801, 'ch-doc-card-380-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fc027e099a654f68114534fa40d1a97900d33dd8a78874e69ec4c8770bea550b', token_count=801, vector_point_id='ch-doc-card-380-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-380-5', 'doc-card-380', 'sec-card-380-3', 5, '• ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. • تعارض و مذاکره (Conflict and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است.', 'bf50a19f3fa6a4558d5edbd42200280c7f4b92c377964c4e6187e1ed0133db26', 1230, 'ch-doc-card-380-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bf50a19f3fa6a4558d5edbd42200280c7f4b92c377964c4e6187e1ed0133db26', token_count=1230, vector_point_id='ch-doc-card-380-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-380-6', 'doc-card-380', 'sec-card-380-3', 6, 'flict and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است. • بافت‌محوری (Contextualism): «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • قدرت و نقش (Power and Role): «توان» در «ارتباط»: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.', 'b64e4de88dbaf207aea343dd750d2b2d8bd0b257fd13137445296eaa2c40c444', 527, 'ch-doc-card-380-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b64e4de88dbaf207aea343dd750d2b2d8bd0b257fd13137445296eaa2c40c444', token_count=527, vector_point_id='ch-doc-card-380-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-380-7', 'doc-card-380', 'sec-card-380-4', 7, 'and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است. • بافت‌محوری (Contextualism): «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • قدرت و نقش (Power and Role): «توان» در «ارتباط»: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  ۳. نمونه‌های تحلیلی «ارتباط میان‌فردی» در عمل: «گفت‌وگو» بین «دوستان» «معنا» «ساخته» می‌شود: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  «ارتباط سازمانی» در عمل: «جلسه» «سازمانی»، «بافت» «توان» است: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  «ارتباط بین‌فرهنگی» در عمل: «مذاکره» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است و «فهم» «فرهنگ» دیگر، «توان» است.', '763d1ed12346c549d4f265a9c96555b3aea102c860d161313b0220a599d5a8b6', 1210, 'ch-doc-card-380-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='763d1ed12346c549d4f265a9c96555b3aea102c860d161313b0220a599d5a8b6', token_count=1210, vector_point_id='ch-doc-card-380-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
