INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-380-13', 'doc-card-380', 'sec-card-380-7', 13, ': «توان»، «مذاکره» را «بازتولید» می‌کند. ۶. «بافت‌محوری» و «تعمیم»: «معنا» در «بافت» «ساخته» می‌شود اما «بافت» «تعمیم» «پذیر» نیست: «بافت» «بومی» است و «تحلیل»، «بومی» لازم دارد. ۷. «ارتباط سازمانی» و «ساختار»: «ارتباط» در «ساختار» «سازمانی»، «بازتولید» «توان» است: «ساختار»، «ارتباط» است. ۸. «ارتباط» و «رسانه»: «ارتباط» «میان‌فردی» و «سازمانی» در «عصر دیجیتال»، «رسانه» «دیجیتال» «بازتعریف» می‌شود: «بافت» «دیجیتال»، «ارتباط» را «بازتولید» می‌کند. ۹. «هوش فرهنگی» و «بافت»: «هوش فرهنگی» در «بافت» «دیجیتال»، «بازتعریف» می‌شود: «بافت» «دیجیتال»، «فرهنگ» را «بازتولید» می‌کند.', '6bdec743a480fb86611d0cdb02061e889fbe8f7dd8911f02a030608c0f3c2be5', 1047, 'ch-doc-card-380-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6bdec743a480fb86611d0cdb02061e889fbe8f7dd8911f02a030608c0f3c2be5', token_count=1047, vector_point_id='ch-doc-card-380-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-380-14', 'doc-card-380', 'sec-card-380-10', 14, 'کتاب «ارتباط میان‌فردی» (آدلمن و همکاران، ۱۹۹۸)؛ کتاب «ارتباط سازمانی» (مکنزی و همکاران، ۲۰۰۵)؛ کتاب «ارتباط بین‌فرهنگی» (لومبونگ و همکاران، ۲۰۰۳)؛ کتاب «هوش فرهنگی» (رابن و همکاران، ۲۰۰۷).', '956a1e981812fd0aee168d40ca4cfc0e60c304bdfcef5b69be87a8e90e1ab9e3', 343, 'ch-doc-card-380-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='956a1e981812fd0aee168d40ca4cfc0e60c304bdfcef5b69be87a8e90e1ab9e3', token_count=343, vector_point_id='ch-doc-card-380-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-381-0', 'doc-card-381', NULL, 0, 'توصیف رسانه و پلتفرم‌های دیجیتال به‌مثابه بازارهای دوسویه که دو گروه مکمل یعنی مخاطبان (که به محتوای رایگان یا ارزان نیاز دارند) و تبلیغ‌دهندگان (که توجه و داده مخاطبان را می‌خرند) را به هم می‌پیوندند و بهای متقاطع آن‌ها را تعیین می‌کنند.', '971ff22b82cb1057ea8badacbbc5360f357732c7deca93f9c66c70c2b39c074d', 432, 'ch-doc-card-381-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='971ff22b82cb1057ea8badacbbc5360f357732c7deca93f9c66c70c2b39c074d', token_count=432, vector_point_id='ch-doc-card-381-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-381-1', 'doc-card-381', 'sec-card-381-1', 1, 'مدیریت و اقتصاد رسانه  ماهیت پلتفرم‌های رسانه‌ای در پیوند زدن دو بخش متقاطع بازار؛ مخاطبانی که اغلب محتوای رایگان یا ارزان می‌خواهند و تبلیغ‌دهندگانی که توجه و داده‌های آن مخاطبان را می‌خرند.', '5e6529aff1516224ea2f51e4e9c5b5f90053e0b460873e160964175148a0f3eb', 347, 'ch-doc-card-381-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5e6529aff1516224ea2f51e4e9c5b5f90053e0b460873e160964175148a0f3eb', token_count=347, vector_point_id='ch-doc-card-381-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-381-2', 'doc-card-381', 'sec-card-381-2', 2, '۱. بنیان و منطق نظری اقتصاد بازارهای دوسویه رسانه رسانه را به‌مثابه سازمان‌های استراتژیکی می‌داند که تحت ساختار بازار، الگوی مالکیت و انگیزه‌های اقتصادی شکل می‌گیرند. ژان شارل روشه (۲۰۰۳) استدلال کرد که برای فهم رسانه باید فراتر از محتوای پیام برویم و شرایط اقتصادی و سازمانی تولید محتوا را تحلیل کنیم: چه کسی کانال‌ها را مالک است، درآمدها از کجا تأمین می‌شوند و رقابت چه محدودیت‌هایی بر سازمان‌ها تحمیل می‌کند. در این چارچوب، تصمیمات محتوایی نتیجه‌ی تلاقی منطق بازار و استراتژی سازمانی است.  بر اساس اقتصاد بازارهای دوسویه رسانه، تولید محتوای رسانه‌ای فرایندی بازاری است که در آن سرمایه، نیروی کار و مخاطبان میان سازمان‌های متعدد در رقابت توزیع می‌شوند.', 'ec93fd2c5a404db6855312e2eb9c64724ed62555dce615ca3c84ab9d7408c50e', 1189, 'ch-doc-card-381-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ec93fd2c5a404db6855312e2eb9c64724ed62555dce615ca3c84ab9d7408c50e', token_count=1189, vector_point_id='ch-doc-card-381-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-381-3', 'doc-card-381', 'sec-card-381-2', 3, 'در آن سرمایه، نیروی کار و مخاطبان میان سازمان‌های متعدد در رقابت توزیع می‌شوند. این چارچوب که به ژان شارل روشه نسبت داده می‌شود (۲۰۰۳)، ساختار مالکیت، رقابت و مقیاس در اقتصاد رسانه را تحلیل می‌کند تا نشان دهد چگونه انگیزه‌های سازمانی بر جریان محتوا شکل می‌دهند. پیش از آنکه بپرسیم پیام رسانه چگونه اثر می‌گذارد، باید بپرسیم این پیام‌ها در چه شرایط اقتصادی و در اختیار چه کسانی تولید می‌شوند.  اقتصاد بازارهای دوسویه رسانه رسانه را به‌عنوان صنعتی استراتژیک در بازارهای دوسویّه‌ی مخاطب و تبلیغ‌دهنده (و در عصر دیجیتال، پلتفرم) می‌داند.', '238f2a01dfa42134d03653a54e5e01b288654866cd39abe244408e0ff6063196', 969, 'ch-doc-card-381-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='238f2a01dfa42134d03653a54e5e01b288654866cd39abe244408e0ff6063196', token_count=969, vector_point_id='ch-doc-card-381-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-381-4', 'doc-card-381', 'sec-card-381-2', 4, 'ک در بازارهای دوسویّه‌ی مخاطب و تبلیغ‌دهنده (و در عصر دیجیتال، پلتفرم) می‌داند. ژان شارل روشه (۲۰۰۳) تأکید کرد که مدل کسب‌وکار — اشتراک، تبلیغات یا درآمدزایی از داده — ماهیت رابطه‌ی سازمان رسانه‌ای با مخاطب را تعیین می‌کند و در نتیجه ساختار محتوا را شکل می‌دهد. این رویکرد اقتصاد رسانه را در دل اقتصاد سازمان‌های صنعتی و مدیریت استراتژیک جای می‌دهد.  ۲. ساختارهای مفهومی • تمرکز مالکیت رسانه‌ای (Media Ownership Concentration): میزان تجمّع کانال‌های رسانه‌ای در دستان معدودی از مالکان و پیامدهای آن بر تنوع محتوا. • مدل کسب‌وکار (Business Model): سازوکار مشخصی که سازمان رسانه‌ای از طریق آن درآمد می‌آورد: تبلیغات، اشتراک، سرپرستی یا فروش داده.', '5abbc0a922f40a7d472515127203742ed7989ae997e6a5dde3ca26564816dfc2', 1170, 'ch-doc-card-381-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5abbc0a922f40a7d472515127203742ed7989ae997e6a5dde3ca26564816dfc2', token_count=1170, vector_point_id='ch-doc-card-381-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-381-5', 'doc-card-381', 'sec-card-381-2', 5, 'ازمان رسانه‌ای از طریق آن درآمد می‌آورد: تبلیغات، اشتراک، سرپرستی یا فروش داده. • بهای مقیاس (Economies of Scale): کاهش هزینه‌ی واحد تولید با افزایش حجم، که به سود سازمان‌های بزرگ است. • بازار دوسویه (Two-Sided Market): بازارهایی با دو گروه کاربر مکمّل (مانند مخاطب و تبلیغ‌دهنده) که ارزش هر گروه به دیگری وابسته است. • اثر شبکه‌ای (Network Effect): پدیده‌ای که در آن ارزش یک پلتفرم برای هر کاربر با افزایش تعداد کاربران دیگر بیشتر می‌شود. • استراتژی رقابتی (Competitive Strate', '1833badbc9d3995d7c9ccc3f0e97e89e0fb26abf88330ac52c048089b7f5d110', 867, 'ch-doc-card-381-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1833badbc9d3995d7c9ccc3f0e97e89e0fb26abf88330ac52c048089b7f5d110', token_count=867, vector_point_id='ch-doc-card-381-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-381-6', 'doc-card-381', 'sec-card-381-3', 6, '• تمرکز مالکیت رسانه‌ای (Media Ownership Concentration): میزان تجمّع کانال‌های رسانه‌ای در دستان معدودی از مالکان و پیامدهای آن بر تنوع محتوا. • مدل کسب‌وکار (Business Model): سازوکار مشخصی که سازمان رسانه‌ای از طریق آن درآمد می‌آورد: تبلیغات، اشتراک، سرپرستی یا فروش داده. • بهای مقیاس (Economies of Scale): کاهش هزینه‌ی واحد تولید با افزایش حجم، که به سود سازمان‌های بزرگ است. • بازار دوسویه (Two-Sided Market): بازارهایی با دو گروه کاربر مکمّل (مانند مخاطب و تبلیغ‌دهنده) که ارزش هر گروه به دیگری وابسته است. • اثر شبکه‌ای (Network Effect): پدیده‌ای که در آن ارزش یک پلتفرم برای هر کاربر با افزایش تعداد کاربران دیگر بیشتر می‌شود.', '18c830a35a69cca3cf585500a97db1199d0fb935ebf98426b10ddd7d00f08657', 1150, 'ch-doc-card-381-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='18c830a35a69cca3cf585500a97db1199d0fb935ebf98426b10ddd7d00f08657', token_count=1150, vector_point_id='ch-doc-card-381-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-381-7', 'doc-card-381', 'sec-card-381-3', 7, 'ه در آن ارزش یک پلتفرم برای هر کاربر با افزایش تعداد کاربران دیگر بیشتر می‌شود. • استراتژی رقابتی (Competitive Strategy): انتخاب‌هایی که سازمان برای کسب مزیت پایدار در برابر رقبای بازار انجام می‌دهد. • سرمایه انسانی (Human Capital): دانش، مهارت و تجربه‌ی نیروی کار به‌عنوان منبع ارزش‌آفرینی در سازمان. • صنعت خلاق (Creative Industry): صنایعی که محصول اصلی آن‌ها محتوای فرهنگی و خلاق است و با عدم‌قطعیت بالای تقاضا روبه‌روند.', '64ca56101f7d16bbf3c703df65c2cf4099d183f4b84137bd95dd308f1b27716d', 770, 'ch-doc-card-381-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='64ca56101f7d16bbf3c703df65c2cf4099d183f4b84137bd95dd308f1b27716d', token_count=770, vector_point_id='ch-doc-card-381-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-381-8', 'doc-card-381', 'sec-card-381-4', 8, 'gy): انتخاب‌هایی که سازمان برای کسب مزیت پایدار در برابر رقبای بازار انجام می‌دهد. • سرمایه انسانی (Human Capital): دانش، مهارت و تجربه‌ی نیروی کار به‌عنوان منبع ارزش‌آفرینی در سازمان. • صنعت خلاق (Creative Industry): صنایعی که محصول اصلی آن‌ها محتوای فرهنگی و خلاق است و با عدم‌قطعیت بالای تقاضا روبه‌روند.  ۳. نمونه‌های تحلیلی در تمرکز روزافزون صنعت پخش، خرید یک استودیوی تولید بزرگ توسط یک پلتفرم استریم نمونه‌ای از استراتژی عمودی در خدمت بهای مقیاس است: هدف، کاهش وابستگی به محتوای بیرونی و هم‌زمان بزرگ‌تر کردن پایگاه مخاطب و داده است.', '1536fa134dc17d4ce0d016bc47297adb0b966bc4147b5ccf09300a53fa25bce1', 981, 'ch-doc-card-381-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1536fa134dc17d4ce0d016bc47297adb0b966bc4147b5ccf09300a53fa25bce1', token_count=981, vector_point_id='ch-doc-card-381-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-381-9', 'doc-card-381', 'sec-card-381-4', 9, 'کاهش وابستگی به محتوای بیرونی و هم‌زمان بزرگ‌تر کردن پایگاه مخاطب و داده است.  در مطبوعات، گروه‌های روزنامه‌ای که فعالیت خود را به تلویزیون و فضای دیجیتال گسترش داده و درآمدها را فراتر از تبلیغات متنوع کرده‌اند، نمونه‌ی استراتژی تنوع‌بخشی برای حفظ بقا در بازاری رو به افول هستند.  وقتی یک خبرگزاری بزرگ از مدل درآمدی تبلیغاتی به مدل اشتراک‌دار می‌رود، در عمل تعریف خود از رابطه با مخاطب را بازنویسی می‌کند: مخاطب دیگر کالایی نیست که به تبلیغ‌دهنده فروخته شود، بلکه مشتری است؛ این جابه‌جایی اولویت‌های محتوایی و پاسخگویی رسانه را تغییر می‌دهد.', '7962f055ca9621273d405f50ace39e9b642498ed52576f204fef3813280de916', 985, 'ch-doc-card-381-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7962f055ca9621273d405f50ace39e9b642498ed52576f204fef3813280de916', token_count=985, vector_point_id='ch-doc-card-381-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-381-10', 'doc-card-381', 'sec-card-381-4', 10, 'مشتری است؛ این جابه‌جایی اولویت‌های محتوایی و پاسخگویی رسانه را تغییر می‌دهد.  یک روزنامه‌ی محلی کوچک با اتکا به یارانه‌های جمعی و نشریات خبری پولی، در برابر منطق مقیاس پلتفرم‌ها مقاومت می‌کند؛ استراتژی‌ای که واکنشی است به ناتوانی سازمان‌های کوچک در رقابت مستقیم برای توجه.  رقابت پلتفرم‌های محتوا بر «محتوای انحصاری» نمونه‌ای از منطق بازار دوسویه است: از یک سو تولیدکنندگانی که محتوا و داده ارائه می‌دهند و از سوی دیگر مخاطبانی که توجه خود را عرضه می‌کنند؛ پلتفرم با کاهش هزینه‌ی تعامل میان این دو سمت سود می‌برد.', '8fe1d2c1ead92aa527938e4b4b9215a3b3082d18171de50a26ab3ac792fdf228', 934, 'ch-doc-card-381-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8fe1d2c1ead92aa527938e4b4b9215a3b3082d18171de50a26ab3ac792fdf228', token_count=934, vector_point_id='ch-doc-card-381-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-381-11', 'doc-card-381', 'sec-card-381-4', 11, 'خود را عرضه می‌کنند؛ پلتفرم با کاهش هزینه‌ی تعامل میان این دو سمت سود می‌برد.  در صنعت رسانه، ورود شرکت‌های تولیدی از دل شبکه‌های پخش و مذاکره‌ی آن‌ها بر سر سهم درآمدها، نمونه‌ای عملی است از تبدیل سرمایه‌ی انسانی و خلاق به قدرت چانه‌زنی در بازار.  ۴. نقدها و چالش‌ها ۱. تقلیل رسانه به منطق بازار: این چارچوب گرایش دارد بُعد فرهنگی و سیاسی محتوا را به‌عنوان اثرات فرعی بازار در نظر بگیرد و کارکرد عمومی و اجتماعی رسانه را دست‌کم بگیرد. ۲. ساختار متغیر در عصر دیجیتال: مدل‌های کلاسیک ساختار بازار و رقابت (تمرکز، مانع ورود) با واقعیت خدمات رایگان، بازارهای دوسویه و پلتفرمی‌شدن هم‌خوانی کامل ندارند. ۳.', '16e2183fba65a3c9cac340321daba91b844b5cf8ea0abe27bde047ce784c0211', 1090, 'ch-doc-card-381-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='16e2183fba65a3c9cac340321daba91b844b5cf8ea0abe27bde047ce784c0211', token_count=1090, vector_point_id='ch-doc-card-381-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-381-12', 'doc-card-381', 'sec-card-381-4', 12, 'با واقعیت خدمات رایگان، بازارهای دوسویه و پلتفرمی‌شدن هم‌خوانی کامل ندارند. ۳. دشواری سنجش: مفاهیمی مانند «توجه» و «ارزش مخاطب» در عصر پلتفرم معیارهای اندازه‌گیری معتبر و استانداردی ند', '68107c6c463792c96f39a7d149a378da952f3bab99f5ea4892f9b902b9e0c653', 334, 'ch-doc-card-381-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='68107c6c463792c96f39a7d149a378da952f3bab99f5ea4892f9b902b9e0c653', token_count=334, vector_point_id='ch-doc-card-381-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-381-13', 'doc-card-381', 'sec-card-381-5', 13, 'در تمرکز روزافزون صنعت پخش، خرید یک استودیوی تولید بزرگ توسط یک پلتفرم استریم نمونه‌ای از استراتژی عمودی در خدمت بهای مقیاس است: هدف، کاهش وابستگی به محتوای بیرونی و هم‌زمان بزرگ‌تر کردن پایگاه مخاطب و داده است.  در مطبوعات، گروه‌های روزنامه‌ای که فعالیت خود را به تلویزیون و فضای دیجیتال گسترش داده و درآمدها را فراتر از تبلیغات متنوع کرده‌اند، نمونه‌ی استراتژی تنوع‌بخشی برای حفظ بقا در بازاری رو به افول هستند.  وقتی یک خبرگزاری بزرگ از مدل درآمدی تبلیغاتی به مدل اشتراک‌دار می‌رود، در عمل تعریف خود از رابطه با مخاطب را بازنویسی می‌کند: مخاطب دیگر کالایی نیست که به تبلیغ‌دهنده فروخته شود، بلکه مشتری است؛ این جابه‌جایی اولویت‌های محتوایی و پاسخگویی رسانه را تغییر می‌دهد.', '65e35e25122f6221b48c6dc4873fb2785c3b4733ea902cf35bf66afba957b56c', 1229, 'ch-doc-card-381-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='65e35e25122f6221b48c6dc4873fb2785c3b4733ea902cf35bf66afba957b56c', token_count=1229, vector_point_id='ch-doc-card-381-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-381-14', 'doc-card-381', 'sec-card-381-5', 14, 'مشتری است؛ این جابه‌جایی اولویت‌های محتوایی و پاسخگویی رسانه را تغییر می‌دهد.  یک روزنامه‌ی محلی کوچک با اتکا به یارانه‌های جمعی و نشریات خبری پولی، در برابر منطق مقیاس پلتفرم‌ها مقاومت می‌کند؛ استراتژی‌ای که واکنشی است به ناتوانی سازمان‌های کوچک در رقابت مستقیم برای توجه.  رقابت پلتفرم‌های محتوا بر «محتوای انحصاری» نمونه‌ای از منطق بازار دوسویه است: از یک سو تولیدکنندگانی که محتوا و داده ارائه می‌دهند و از سوی دیگر مخاطبانی که توجه خود را عرضه می‌کنند؛ پلتفرم با کاهش هزینه‌ی تعامل میان این دو سمت سود می‌برد.', '8fe1d2c1ead92aa527938e4b4b9215a3b3082d18171de50a26ab3ac792fdf228', 934, 'ch-doc-card-381-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8fe1d2c1ead92aa527938e4b4b9215a3b3082d18171de50a26ab3ac792fdf228', token_count=934, vector_point_id='ch-doc-card-381-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-381-15', 'doc-card-381', 'sec-card-381-5', 15, 'خود را عرضه می‌کنند؛ پلتفرم با کاهش هزینه‌ی تعامل میان این دو سمت سود می‌برد.  در صنعت رسانه، ورود شرکت‌های تولیدی از دل شبکه‌های پخش و مذاکره‌ی آن‌ها بر سر سهم درآمدها، نمونه‌ای عملی است از تبدیل سرمایه‌ی انسانی و خلاق به قدرت چانه‌زنی در بازار.', '1886a68ffdfd556efe2d43df3b96dcd0f7fcaa78483e27a70552920f3cbfb6d5', 447, 'ch-doc-card-381-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1886a68ffdfd556efe2d43df3b96dcd0f7fcaa78483e27a70552920f3cbfb6d5', token_count=447, vector_point_id='ch-doc-card-381-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-381-16', 'doc-card-381', 'sec-card-381-6', 16, '۱. تقلیل رسانه به منطق بازار: این چارچوب گرایش دارد بُعد فرهنگی و سیاسی محتوا را به‌عنوان اثرات فرعی بازار در نظر بگیرد و کارکرد عمومی و اجتماعی رسانه را دست‌کم بگیرد. ۲. ساختار متغیر در عصر دیجیتال: مدل‌های کلاسیک ساختار بازار و رقابت (تمرکز، مانع ورود) با واقعیت خدمات رایگان، بازارهای دوسویه و پلتفرمی‌شدن هم‌خوانی کامل ندارند. ۳. دشواری سنجش: مفاهیمی مانند «توجه» و «ارزش مخاطب» در عصر پلتفرم معیارهای اندازه‌گیری معتبر و استانداردی ندارند و مقایسه‌های تجربی دشوار می‌مانند. ۴. غفلت از کار: تمرکز بر سرمایه و مالکیت می‌تواند تصویری بسازد که در آن محتوا محصول مرموز «بازار» است، درحالی‌که کار، مهارت و بی‌پایداری نیروی کار رسانه در این تصویر محو می‌شود. ۵.', '3d914242f484cf62d945fbd3e7fdf99e51e6c55793df106919346faf18ed15d4', 1198, 'ch-doc-card-381-16', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3d914242f484cf62d945fbd3e7fdf99e51e6c55793df106919346faf18ed15d4', token_count=1198, vector_point_id='ch-doc-card-381-16', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-381-17', 'doc-card-381', 'sec-card-381-6', 17, '، درحالی‌که کار، مهارت و بی‌پایداری نیروی کار رسانه در این تصویر محو می‌شود. ۵. غرب‌مندی مدل‌ها: بیشتر یافته‌ها و نمونه‌ها از بازارهای آمریکا و اروپا گرفته شده‌اند و کاربرد آن‌ها', '5e66c44622c3727d6e16782f9af81e5ef5d8dce84c877de33025b848006921a4', 323, 'ch-doc-card-381-17', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5e66c44622c3727d6e16782f9af81e5ef5d8dce84c877de33025b848006921a4', token_count=323, vector_point_id='ch-doc-card-381-17', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-381-18', 'doc-card-381', 'sec-card-381-7', 18, 'در اقتصادهای رسانه‌ای با ساختار متفاوت دولت، بازار و مالکیت زیر سؤال می‌رود. ۶. تأخیر زمانی مدل‌ها: مدل‌های اقتصادی اغلب تفسیرگر ادغام‌ها و بحران‌های گذشته‌اند و در پیش‌بینی دگرگونی‌های ساختاری مانند ظهور پلتفرم‌ها ضعیف عمل کرده‌اند. ۷. فرض یکدستی سازمان رسانه‌ای: چارچوب اغلب سازمان رسانه را بازیگری واحد استراتژیک می‌پندارد، درحالی‌که در عمل از واحدهایی با منافع و منطق‌های رقابتی داخلی تشکیل شده است. ۸. نادیده‌گرفتن تنظیم‌گری و سیاست عمومی: رقابت بازار در خلأ کار نمی‌کند؛ مجوزها، قوانین مالکیت و یارانه‌های عمومی ساختار بازار رسانه را شکل می‌دهند و مدل‌های محض اقتصادی این متغیرها را نادیده می‌گیرند. ۹.', '86f61585f82822b47b47594ceff67799a9a66d7a98bade188348da261adfa63d', 1105, 'ch-doc-card-381-18', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='86f61585f82822b47b47594ceff67799a9a66d7a98bade188348da261adfa63d', token_count=1105, vector_point_id='ch-doc-card-381-18', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-381-19', 'doc-card-381', 'sec-card-381-7', 19, 'ر رسانه را شکل می‌دهند و مدل‌های محض اقتصادی این متغیرها را نادیده می‌گیرند. ۹. سنجش ارزش بلندمدت: شاخص‌های مالی کوتاه‌مدت، ارزش برند، اعتبار عمومی و کارکرد فرهنگی رسانه را نمی‌سنجند و تصویر ناقصی از عملکرد سازمان ارائه می‌دهند.', '9b39b885b2b96d755cff97eeba7a1d1c8fa5c3bb2dd5c504454e42b9c907b888', 414, 'ch-doc-card-381-19', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9b39b885b2b96d755cff97eeba7a1d1c8fa5c3bb2dd5c504454e42b9c907b888', token_count=414, vector_point_id='ch-doc-card-381-19', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-381-20', 'doc-card-381', 'sec-card-381-10', 20, 'کتاب «اقتصاد رسانه» (ریچارد هاردوود، ۲۰۱۰)؛ کتاب «انقلاب پلتفرمی» (پarker، وان آلستاین و چوداری، ۲۰۱۶)؛ کتاب «صنایع فرهنگی» (دیوید هسمندهال، ۲۰۰۲)؛ استناد مبنا: Rochet & Tirole (2003) بر بازارهای دوسویه.', '2efe013f44cc9e6c640f0ec3c5d85d71a0c3438be40fbf8e3fff258b56a68c32', 369, 'ch-doc-card-381-20', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2efe013f44cc9e6c640f0ec3c5d85d71a0c3438be40fbf8e3fff258b56a68c32', token_count=369, vector_point_id='ch-doc-card-381-20', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-382-0', 'doc-card-382', NULL, 0, 'در نظام سرمایه‌داری انحصاری، مهم‌ترین کالای تولیدشده توسط رسانه‌های تجاری محتوا نیست، بلکه خود «مخاطب» است. رسانه‌ها مخاطبان را تولید کرده و زمان، توجه و آگاهی آن‌ها را بسته‌بندی کرده و به آگهی‌دهندگان می‌فروشند.', 'b70977fb179927215133aa84093de9b32d38804c95ce6e65a5b3e9c4f4ce3e1a', 385, 'ch-doc-card-382-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b70977fb179927215133aa84093de9b32d38804c95ce6e65a5b3e9c4f4ce3e1a', token_count=385, vector_point_id='ch-doc-card-382-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-382-1', 'doc-card-382', 'sec-card-382-1', 1, 'اقتصاد سیاسی ارتباطات / مارکسیسم ساختارگرا  در نظام سرمایه‌داری انحصاری، مهم‌ترین کالای تولیدشده توسط رسانه‌های تجاری محتوا نیست، بلکه خود «مخاطب» است. رسانه‌ها مخاطبان را تولید کرده و زمان، توجه و آگاهی آن‌ها را بسته‌بندی کرده و به آگهی‌دهندگان می‌فروشند.', 'f28c1d2bf0fa9ec209b2a5bfa3c467bda1d5ecda3e305aace7492cca60edf525', 465, 'ch-doc-card-382-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f28c1d2bf0fa9ec209b2a5bfa3c467bda1d5ecda3e305aace7492cca60edf525', token_count=465, vector_point_id='ch-doc-card-382-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-382-2', 'doc-card-382', 'sec-card-382-2', 2, '۱. بنیان و منطق نظری کالایی‌شدن مخاطب رسانه را در دل ساختارهای اقتصادی و سیاسی می‌خواند: رسانه نه فقط «ابزار ارتباط» بلکه «صنعتی» است که در آن توجه، داده و محتوا، کالاهای قابل‌خریدوفروش‌اند. دالاس اسمایت (۱۹۷۷) نشان داد که منطق بازار، از تولید محتوا تا توزیع آن، شکل‌دهنده‌ی بنیادین رسانه‌ی معاصر است و پرسش «چه کسی برای چه کسی و به چه قیمتی تولید می‌کند؟» را در مرکز تحلیل قرار داد.  بر اساس کالایی‌شدن مخاطب، رابطه‌ی مخاطب و رسانه در عصر دیجیتال «دستِ دوسویه» است: رسانه مخاطب را به تبلیغ‌دهنده می‌فروشد و در عوض، مخاطب «توجه» و «داده» خود را به‌عنوان کالای رایگان عرضه می‌کند.', '121047ae7cc46503bcb5b09c59a7d2643eda83b9ab13a70b9dd3e76215ed9f65', 1052, 'ch-doc-card-382-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='121047ae7cc46503bcb5b09c59a7d2643eda83b9ab13a70b9dd3e76215ed9f65', token_count=1052, vector_point_id='ch-doc-card-382-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-382-3', 'doc-card-382', 'sec-card-382-2', 3, 'فروشد و در عوض، مخاطب «توجه» و «داده» خود را به‌عنوان کالای رایگان عرضه می‌کند. دالاس اسمایت (۱۹۷۷) این سازوکار را به‌عنوان بنیاد اقتصاد رسانه‌ی معاصر تحلیل کرد و نشان داد که «ارزش» مخاطب، نه در مصرف محتوا، بلکه در تولید داده و توجه است.  کالایی‌شدن مخاطب رسانه را به‌عنوان «زیرساخت سرمایه‌داری» می‌خواند: رسانه هم‌زمان ابزار تولید معنا، ابزار تولید سود و ابزار تولید ایدئولوژی است. دالاس اسمایت (۱۹۷۷) در این چارچوب، نشان داد که چگونه ساختار مالکیت، تمرکز سرمایه و منطق رقابتی بازار، نه فقط «چه چیزی» بلکه «چگونه» تولید می‌شود را تعیین می‌کند.  ۲. ساختارهای مفهومی • کالایی‌شدن مخاطب (Audience Commodity): تبدیل توجه مخاطب به کالایی که رسانه به تبلیغ‌دهنده می‌فروشد.', 'c00ef2959811b866ecea42e263ec0f75a843ca960f97c59249fd8e14392409ea', 1212, 'ch-doc-card-382-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c00ef2959811b866ecea42e263ec0f75a843ca960f97c59249fd8e14392409ea', token_count=1212, vector_point_id='ch-doc-card-382-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-382-4', 'doc-card-382', 'sec-card-382-2', 4, 'dience Commodity): تبدیل توجه مخاطب به کالایی که رسانه به تبلیغ‌دهنده می‌فروشد. • اقتصاد توجه (Attention Economy): رقابت برون‌مرزی برای جلب و حفظ توجه مخاطب به‌عنوان منبع ارزش‌آفرینی. • تمرکز مالکیت (Ownership Concentration): تجمّع کانال‌های رسانه‌ای در دستان معدودی از بازیگران اقتصادی. • مدل کسب‌وکار رسانه‌ای (Media Business Model): سازوکارهای درآمدزایی — تبلیغات، اشتراک، داده، سرپرستی — و تعارض میان آن‌ها. • سرمایه نمادین رسانه‌ای (Symbolic Capital): اعتبار، اعتماد و قدرت تفسیری که رسانه به‌عنوان «خبررسان معتبر» کسب می‌کند. • تخریب خلاق (Creative Destruction): فرایند ورود فناوری و با', 'e01eaba6ff78721c5813db8458545eef49870830b62c4adfba53efbf7bee7a64', 1076, 'ch-doc-card-382-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e01eaba6ff78721c5813db8458545eef49870830b62c4adfba53efbf7bee7a64', token_count=1076, vector_point_id='ch-doc-card-382-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-382-5', 'doc-card-382', 'sec-card-382-3', 5, 'نقطه کور مارکسیسم غربی (Blindspot of Western Marxism)، کارِ مخاطب (Audience Labor - تماشای تبلیغات به عنوان کار بدون دستمزد)، زمان توجه.', 'a2cb95a014f62bf79aa5bcc1733d6de523e6e205957821e40f41f4ebfe0457f1', 247, 'ch-doc-card-382-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a2cb95a014f62bf79aa5bcc1733d6de523e6e205957821e40f41f4ebfe0457f1', token_count=247, vector_point_id='ch-doc-card-382-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-382-6', 'doc-card-382', 'sec-card-382-4', 6, 'زیگران تازه که ساختار رقابتی صنعت را دگرگون می‌کند. • بهای مقیاس (Economies of Scale): کاهش هزینه‌ی واحد تولید با افزایش حجم؛ نفع‌دهنده‌ی اصلی سازمان‌های بزرگ. • دوسویه‌ای بازار (Two-Sided Market): ساختار بازارهایی که ارزش هر سمت (مخاطب/تبلیغ‌دهنده) به سمت دیگر وابسته است.  ۳. نمونه‌های تحلیلی وقتی یک شبکه‌ی اجتماعی «رایگان» است، در عمل «توجه» و «داده» شما را به تبلیغ‌دهنده می‌فروشد: شما «محصول» هستید، نه «مشتری».  تمرکز مالکیت رسانه‌ای در دستان چند شرکت بزرگ، تنوع محتوایی را کاهش می‌دهد: وقتی یک شرکت هم تلویزیون، هم استریم و هم شبکه‌ی اجتماعی را دارد، «رقابت» در عمل به «تنوع درونی» تقلیل می‌یابد.', '37ad33325c159f148abaf96ff7b3fe397903225b0fa8e4a4755cda1144689e69', 1098, 'ch-doc-card-382-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='37ad33325c159f148abaf96ff7b3fe397903225b0fa8e4a4755cda1144689e69', token_count=1098, vector_point_id='ch-doc-card-382-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-382-7', 'doc-card-382', 'sec-card-382-4', 7, 'ریم و هم شبکه‌ی اجتماعی را دارد، «رقابت» در عمل به «تنوع درونی» تقلیل می‌یابد.  وقتی یک پلتفرم استریم برای جذب اشتراک‌دار، «محتوای انحصاری» تولید می‌کند، در عمل «بهای مقیاس» و «تخریب خلاق» هم‌زمان در جریان است: تولید داخلی، هزینه‌ی خرید را کاهش می‌دهد و ساختار رقابتی صنعت پخش را دگرگون می‌کند.  «اقتصاد توجه» به این معناست که هر اپلیکیشنی که وقت شما را «گیر» می‌کند، در واقع «توجه» شما را به‌عنوان کالایی نادر در بازار رقابتی فروخته است.  وقتی یک رسانه‌ی محلی از مدل تبلیغات به مدل اشتراک‌دار می‌رود، در عمل «سرمایه نمادین» (اعتماد مخاطب) را به «سرمایه اقتصادی» (اشتراک) تبدیل می‌کند.', '4ed1e8c9f1df4bf9be445eb21f70d94a66b5dd4351054db834172278093b5a3b', 1063, 'ch-doc-card-382-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4ed1e8c9f1df4bf9be445eb21f70d94a66b5dd4351054db834172278093b5a3b', token_count=1063, vector_point_id='ch-doc-card-382-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-382-8', 'doc-card-382', 'sec-card-382-4', 8, 'ل «سرمایه نمادین» (اعتماد مخاطب) را به «سرمایه اقتصادی» (اشتراک) تبدیل می‌کند.  «دوسویه‌ای بازار» در پلتفرم‌ها به این معناست که هرچه کاربر بیشتری داشته باشید، تولیدکننده‌ی محتوای بیشتری جذب می‌شود و بالعکس — یک «چرخه‌ی مثبت» که برنده را بزرگ‌تر و بزرگ‌تر می‌کند.  ۴. نقدها و چالش‌ها ۱. تقلیل رسانه به منطق بازار: چارچوب اقتصاد رسانه گاه بُعد فرهنگی، سیاسی و اجتماعی رسانه را به «اثرات فرعی» بازار تقلیل می‌دهد و کارکرد عمومی آن را دست‌کم می‌گیرد. ۲. مدل‌های کلاسیک در برابر پلتفرم: مفاهیمی مانند «تمرکز» و «بهای مقیاس» که در اقتصاد مطبوعات و تلویزیون ساخته شده‌اند، در اقتصاد پلتفرم و داده نیازمند بازتعریف‌اند. ۳. دشواری سنجش «توجه»: واحد بنیادین', 'f0d6d2d1b8a42e57201fa5011280b247223419cf7a5e3a5c1115d75cdf8cf5dd', 1176, 'ch-doc-card-382-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f0d6d2d1b8a42e57201fa5011280b247223419cf7a5e3a5c1115d75cdf8cf5dd', token_count=1176, vector_point_id='ch-doc-card-382-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-382-9', 'doc-card-382', 'sec-card-382-5', 9, 'تحلیل مدل‌های درآمدی تلویزیون تجاری رایگان و امروزه پلتفرم‌های کلان تبلیغاتی نظیر گوگل، متا و اینستاگرام که داده و توجه کاربر را می‌فروشند.', 'ab497021c9bc9a995922be2771c9fae4bc0fd140448f301878cddb8508919b5f', 252, 'ch-doc-card-382-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ab497021c9bc9a995922be2771c9fae4bc0fd140448f301878cddb8508919b5f', token_count=252, vector_point_id='ch-doc-card-382-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-382-10', 'doc-card-382', 'sec-card-382-6', 10, 'گراهام مرداک انتقاد کرد که این رویکرد تقلیل‌گرایانه و بیش‌از‌حد اقتصادی است و استقلال نسبی رسانه‌ها، اهمیت ایدئولوژیک محتوا و نقش دولت را نادیده می‌گیرد.', '09a1d6e5cc6362ad58e53a678c37a00067d82eb15b7f905a080609e57c46f750', 278, 'ch-doc-card-382-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='09a1d6e5cc6362ad58e53a678c37a00067d82eb15b7f905a080609e57c46f750', token_count=278, vector_point_id='ch-doc-card-382-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-382-11', 'doc-card-382', 'sec-card-382-10', 11, 'مقاله بنیادین «ارتباطات: نقطه کور مارکسیسم غربی» (دالاس اسمایت، ۱۹۷۷).', '4aa1eb0efccd626359e9a6084552e0e2cac4cec8aafc34b0fe1527f199b8cf1c', 127, 'ch-doc-card-382-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4aa1eb0efccd626359e9a6084552e0e2cac4cec8aafc34b0fe1527f199b8cf1c', token_count=127, vector_point_id='ch-doc-card-382-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-383-0', 'doc-card-383', NULL, 0, 'تحلیل تاریخی تیم وو از تبدیل توجه شهروندان به کالای تجاری؛ صنعت رسانه از پوسترهای قرن هجدهم تا شبکه‌های دیجیتال، آگاهی و زمان خصوصی مردم را شکار کرده و به تبلیغ‌دهندگان واگذار می‌کند تا اقتصاد رسانه بر فروش توجه بنا شود.', 'd149a236e8cf6592ec046e3491cc5ae9d77867e26f60b12851da9838bf2c1943', 399, 'ch-doc-card-383-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d149a236e8cf6592ec046e3491cc5ae9d77867e26f60b12851da9838bf2c1943', token_count=399, vector_point_id='ch-doc-card-383-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-383-1', 'doc-card-383', 'sec-card-383-1', 1, 'مدیریت و اقتصاد رسانه  تاریخچه شیوه‌های صنعتی رسانه‌ها از چاپ پوستر تا شبکه‌های مدرن برای شکار آگاهی و زمان خصوصی شهروندان و واگذاری آن به منافع مالی.', 'ec812d89d9b74276d729d108cb21228a9e3bf7bffd41488fd42e26f777f9e0bc', 272, 'ch-doc-card-383-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ec812d89d9b74276d729d108cb21228a9e3bf7bffd41488fd42e26f777f9e0bc', token_count=272, vector_point_id='ch-doc-card-383-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-383-2', 'doc-card-383', 'sec-card-383-2', 2, '۱. بنیان و منطق نظری تاجران توجه رسانه را به‌مثابه سازمان‌های استراتژیکی می‌داند که تحت ساختار بازار، الگوی مالکیت و انگیزه‌های اقتصادی شکل می‌گیرند. تیم وو (۲۰۱۶) استدلال کرد که برای فهم رسانه باید فراتر از محتوای پیام برویم و شرایط اقتصادی و سازمانی تولید محتوا را تحلیل کنیم: چه کسی کانال‌ها را مالک است، درآمدها از کجا تأمین می‌شوند و رقابت چه محدودیت‌هایی بر سازمان‌ها تحمیل می‌کند. در این چارچوب، تصمیمات محتوایی نتیجه‌ی تلاقی منطق بازار و استراتژی سازمانی است.  بر اساس تاجران توجه، تولید محتوای رسانه‌ای فرایندی بازاری است که در آن سرمایه، نیروی کار و مخاطبان میان سازمان‌های متعدد در رقابت توزیع می‌شوند.', '88a3c4c386a58a458a689d0765198b2071c48b02476db3a91187dcb62664a00d', 1114, 'ch-doc-card-383-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='88a3c4c386a58a458a689d0765198b2071c48b02476db3a91187dcb62664a00d', token_count=1114, vector_point_id='ch-doc-card-383-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-383-3', 'doc-card-383', 'sec-card-383-2', 3, 'در آن سرمایه، نیروی کار و مخاطبان میان سازمان‌های متعدد در رقابت توزیع می‌شوند. این چارچوب که به تیم وو نسبت داده می‌شود (۲۰۱۶)، ساختار مالکیت، رقابت و مقیاس در اقتصاد رسانه را تحلیل می‌کند تا نشان دهد چگونه انگیزه‌های سازمانی بر جریان محتوا شکل می‌دهند. پیش از آنکه بپرسیم پیام رسانه چگونه اثر می‌گذارد، باید بپرسیم این پیام‌ها در چه شرایط اقتصادی و در اختیار چه کسانی تولید می‌شوند.  تاجران توجه رسانه را به‌عنوان صنعتی استراتژیک در بازارهای دوسویّه‌ی مخاطب و تبلیغ‌دهنده (و در عصر دیجیتال، پلتفرم) می‌داند.', '8eaff48d712bee38e034477982295d80984adc6a58e64b234f400c47e9b5b032', 925, 'ch-doc-card-383-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8eaff48d712bee38e034477982295d80984adc6a58e64b234f400c47e9b5b032', token_count=925, vector_point_id='ch-doc-card-383-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-383-4', 'doc-card-383', 'sec-card-383-2', 4, 'ک در بازارهای دوسویّه‌ی مخاطب و تبلیغ‌دهنده (و در عصر دیجیتال، پلتفرم) می‌داند. تیم وو (۲۰۱۶) تأکید کرد که مدل کسب‌وکار — اشتراک، تبلیغات یا درآمدزایی از داده — ماهیت رابطه‌ی سازمان رسانه‌ای با مخاطب را تعیین می‌کند و در نتیجه ساختار محتوا را شکل می‌دهد. این رویکرد اقتصاد رسانه را در دل اقتصاد سازمان‌های صنعتی و مدیریت استراتژیک جای می‌دهد.  ۲. ساختارهای مفهومی • تمرکز مالکیت رسانه‌ای (Media Ownership Concentration): میزان تجمّع کانال‌های رسانه‌ای در دستان معدودی از مالکان و پیامدهای آن بر تنوع محتوا. • مدل کسب‌وکار (Business Model): سازوکار مشخصی که سازمان رسانه‌ای از طریق آن درآمد می‌آورد: تبلیغات، اشتراک، سرپرستی یا فروش داده.', 'aecfda24d9abff18f336ee82ba5b1c8feb258a1a9c89601c3d36f8e42fb635c1', 1158, 'ch-doc-card-383-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='aecfda24d9abff18f336ee82ba5b1c8feb258a1a9c89601c3d36f8e42fb635c1', token_count=1158, vector_point_id='ch-doc-card-383-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-383-5', 'doc-card-383', 'sec-card-383-2', 5, 'ازمان رسانه‌ای از طریق آن درآمد می‌آورد: تبلیغات، اشتراک، سرپرستی یا فروش داده. • بهای مقیاس (Economies of Scale): کاهش هزینه‌ی واحد تولید با افزایش حجم، که به سود سازمان‌های بزرگ است. • بازار دوسویه (Two-Sided Market): بازارهایی با دو گروه کاربر مکمّل (مانند مخاطب و تبلیغ‌دهنده) که ارزش هر گروه به دیگری وابسته است. • اثر شبکه‌ای (Network Effect): پدیده‌ای که در آن ارزش یک پلتفرم برای هر کاربر با افزایش تعداد کاربران دیگر بیشتر می‌شود. • استراتژی رقابتی (Competitive Strategy): انتخاب‌هایی که سازمان برای کسب مزیت پ', '9b6d6b673470449af30167a356219f9cee66ae1f6eda6f198ded50c1e5f031f6', 943, 'ch-doc-card-383-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9b6d6b673470449af30167a356219f9cee66ae1f6eda6f198ded50c1e5f031f6', token_count=943, vector_point_id='ch-doc-card-383-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-383-6', 'doc-card-383', 'sec-card-383-3', 6, '• تمرکز مالکیت رسانه‌ای (Media Ownership Concentration): میزان تجمّع کانال‌های رسانه‌ای در دستان معدودی از مالکان و پیامدهای آن بر تنوع محتوا. • مدل کسب‌وکار (Business Model): سازوکار مشخصی که سازمان رسانه‌ای از طریق آن درآمد می‌آورد: تبلیغات، اشتراک، سرپرستی یا فروش داده. • بهای مقیاس (Economies of Scale): کاهش هزینه‌ی واحد تولید با افزایش حجم، که به سود سازمان‌های بزرگ است. • بازار دوسویه (Two-Sided Market): بازارهایی با دو گروه کاربر مکمّل (مانند مخاطب و تبلیغ‌دهنده) که ارزش هر گروه به دیگری وابسته است. • اثر شبکه‌ای (Network Effect): پدیده‌ای که در آن ارزش یک پلتفرم برای هر کاربر با افزایش تعداد کاربران دیگر بیشتر می‌شود.', '18c830a35a69cca3cf585500a97db1199d0fb935ebf98426b10ddd7d00f08657', 1150, 'ch-doc-card-383-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='18c830a35a69cca3cf585500a97db1199d0fb935ebf98426b10ddd7d00f08657', token_count=1150, vector_point_id='ch-doc-card-383-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-383-7', 'doc-card-383', 'sec-card-383-3', 7, 'ه در آن ارزش یک پلتفرم برای هر کاربر با افزایش تعداد کاربران دیگر بیشتر می‌شود. • استراتژی رقابتی (Competitive Strategy): انتخاب‌هایی که سازمان برای کسب مزیت پایدار در برابر رقبای بازار انجام می‌دهد. • سرمایه انسانی (Human Capital): دانش، مهارت و تجربه‌ی نیروی کار به‌عنوان منبع ارزش‌آفرینی در سازمان. • صنعت خلاق (Creative Industry): صنایعی که محصول اصلی آن‌ها محتوای فرهنگی و خلاق است و با عدم‌قطعیت بالای تقاضا روبه‌روند.', '64ca56101f7d16bbf3c703df65c2cf4099d183f4b84137bd95dd308f1b27716d', 770, 'ch-doc-card-383-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='64ca56101f7d16bbf3c703df65c2cf4099d183f4b84137bd95dd308f1b27716d', token_count=770, vector_point_id='ch-doc-card-383-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-383-8', 'doc-card-383', 'sec-card-383-4', 8, 'ایدار در برابر رقبای بازار انجام می‌دهد. • سرمایه انسانی (Human Capital): دانش، مهارت و تجربه‌ی نیروی کار به‌عنوان منبع ارزش‌آفرینی در سازمان. • صنعت خلاق (Creative Industry): صنایعی که محصول اصلی آن‌ها محتوای فرهنگی و خلاق است و با عدم‌قطعیت بالای تقاضا روبه‌روند.  ۳. نمونه‌های تحلیلی در تمرکز روزافزون صنعت پخش، خرید یک استودیوی تولید بزرگ توسط یک پلتفرم استریم نمونه‌ای از استراتژی عمودی در خدمت بهای مقیاس است: هدف، کاهش وابستگی به محتوای بیرونی و هم‌زمان بزرگ‌تر کردن پایگاه مخاطب و داده است.', '1f23e91c40668e22be69c329a6d149c18bdf36a853f580162e24a1b2fd4bae96', 905, 'ch-doc-card-383-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1f23e91c40668e22be69c329a6d149c18bdf36a853f580162e24a1b2fd4bae96', token_count=905, vector_point_id='ch-doc-card-383-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-383-9', 'doc-card-383', 'sec-card-383-4', 9, 'کاهش وابستگی به محتوای بیرونی و هم‌زمان بزرگ‌تر کردن پایگاه مخاطب و داده است.  در مطبوعات، گروه‌های روزنامه‌ای که فعالیت خود را به تلویزیون و فضای دیجیتال گسترش داده و درآمدها را فراتر از تبلیغات متنوع کرده‌اند، نمونه‌ی استراتژی تنوع‌بخشی برای حفظ بقا در بازاری رو به افول هستند.  وقتی یک خبرگزاری بزرگ از مدل درآمدی تبلیغاتی به مدل اشتراک‌دار می‌رود، در عمل تعریف خود از رابطه با مخاطب را بازنویسی می‌کند: مخاطب دیگر کالایی نیست که به تبلیغ‌دهنده فروخته شود، بلکه مشتری است؛ این جابه‌جایی اولویت‌های محتوایی و پاسخگویی رسانه را تغییر می‌دهد.', '7962f055ca9621273d405f50ace39e9b642498ed52576f204fef3813280de916', 985, 'ch-doc-card-383-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7962f055ca9621273d405f50ace39e9b642498ed52576f204fef3813280de916', token_count=985, vector_point_id='ch-doc-card-383-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-383-10', 'doc-card-383', 'sec-card-383-4', 10, 'مشتری است؛ این جابه‌جایی اولویت‌های محتوایی و پاسخگویی رسانه را تغییر می‌دهد.  یک روزنامه‌ی محلی کوچک با اتکا به یارانه‌های جمعی و نشریات خبری پولی، در برابر منطق مقیاس پلتفرم‌ها مقاومت می‌کند؛ استراتژی‌ای که واکنشی است به ناتوانی سازمان‌های کوچک در رقابت مستقیم برای توجه.  رقابت پلتفرم‌های محتوا بر «محتوای انحصاری» نمونه‌ای از منطق بازار دوسویه است: از یک سو تولیدکنندگانی که محتوا و داده ارائه می‌دهند و از سوی دیگر مخاطبانی که توجه خود را عرضه می‌کنند؛ پلتفرم با کاهش هزینه‌ی تعامل میان این دو سمت سود می‌برد.', '8fe1d2c1ead92aa527938e4b4b9215a3b3082d18171de50a26ab3ac792fdf228', 934, 'ch-doc-card-383-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8fe1d2c1ead92aa527938e4b4b9215a3b3082d18171de50a26ab3ac792fdf228', token_count=934, vector_point_id='ch-doc-card-383-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-383-11', 'doc-card-383', 'sec-card-383-4', 11, 'خود را عرضه می‌کنند؛ پلتفرم با کاهش هزینه‌ی تعامل میان این دو سمت سود می‌برد.  در صنعت رسانه، ورود شرکت‌های تولیدی از دل شبکه‌های پخش و مذاکره‌ی آن‌ها بر سر سهم درآمدها، نمونه‌ای عملی است از تبدیل سرمایه‌ی انسانی و خلاق به قدرت چانه‌زنی در بازار.  ۴. نقدها و چالش‌ها ۱. تقلیل رسانه به منطق بازار: این چارچوب گرایش دارد بُعد فرهنگی و سیاسی محتوا را به‌عنوان اثرات فرعی بازار در نظر بگیرد و کارکرد عمومی و اجتماعی رسانه را دست‌کم بگیرد. ۲. ساختار متغیر در عصر دیجیتال: مدل‌های کلاسیک ساختار بازار و رقابت (تمرکز، مانع ورود) با واقعیت خدمات رایگان، بازارهای دوسویه و پلتفرمی‌شدن هم‌خوانی کامل ندارند. ۳.', '16e2183fba65a3c9cac340321daba91b844b5cf8ea0abe27bde047ce784c0211', 1090, 'ch-doc-card-383-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='16e2183fba65a3c9cac340321daba91b844b5cf8ea0abe27bde047ce784c0211', token_count=1090, vector_point_id='ch-doc-card-383-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-383-12', 'doc-card-383', 'sec-card-383-4', 12, 'با واقعیت خدمات رایگان، بازارهای دوسویه و پلتفرمی‌شدن هم‌خوانی کامل ندارند. ۳. دشواری سنجش: مفاهیمی مانند «توجه» و «ارزش مخاطب» در عصر پلتفرم معیارهای اندازه‌گیری معتبر و استانداردی ندارند و مقایسه', '57eb3da4d48c75c310fb40ae4860a125dfb9d475eb26c3b4a007ca61c04b67de', 358, 'ch-doc-card-383-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='57eb3da4d48c75c310fb40ae4860a125dfb9d475eb26c3b4a007ca61c04b67de', token_count=358, vector_point_id='ch-doc-card-383-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-383-13', 'doc-card-383', 'sec-card-383-5', 13, 'در تمرکز روزافزون صنعت پخش، خرید یک استودیوی تولید بزرگ توسط یک پلتفرم استریم نمونه‌ای از استراتژی عمودی در خدمت بهای مقیاس است: هدف، کاهش وابستگی به محتوای بیرونی و هم‌زمان بزرگ‌تر کردن پایگاه مخاطب و داده است.  در مطبوعات، گروه‌های روزنامه‌ای که فعالیت خود را به تلویزیون و فضای دیجیتال گسترش داده و درآمدها را فراتر از تبلیغات متنوع کرده‌اند، نمونه‌ی استراتژی تنوع‌بخشی برای حفظ بقا در بازاری رو به افول هستند.  وقتی یک خبرگزاری بزرگ از مدل درآمدی تبلیغاتی به مدل اشتراک‌دار می‌رود، در عمل تعریف خود از رابطه با مخاطب را بازنویسی می‌کند: مخاطب دیگر کالایی نیست که به تبلیغ‌دهنده فروخته شود، بلکه مشتری است؛ این جابه‌جایی اولویت‌های محتوایی و پاسخگویی رسانه را تغییر می‌دهد.', '65e35e25122f6221b48c6dc4873fb2785c3b4733ea902cf35bf66afba957b56c', 1229, 'ch-doc-card-383-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='65e35e25122f6221b48c6dc4873fb2785c3b4733ea902cf35bf66afba957b56c', token_count=1229, vector_point_id='ch-doc-card-383-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
