INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-391-6', 'doc-card-391', 'sec-card-391-3', 6, '«پاره‌وقت» و «پروژه‌ای» در رسانه؛ «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده است. • ریسک شغلی (Job Insecurity): «ناپایداری» کار رسانه‌ای؛ «مسابقه» و «فشار» در «عصر دیجیتال»، «ریسک» را «افزایش» داده است. • نقش حرفه‌ای (Professional Role): «نقش» روزنامه‌نگار، ویراستار، کارگردان، مدیر؛ «نقش‌ها»، «ساختار» کار را «تعیین» می‌کنند. • توسعه شغلی (Career Development): «مسیر» شغلی و «آموزش» مداوم؛ «توان» حرفه‌ای، «بازتولید» روزانه نیاز دارد.', '6b0e6d8e71d49df86b71221030f14b943240b5f58c4de60c1f73c41d0770e7ab', 785, 'ch-doc-card-391-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6b0e6d8e71d49df86b71221030f14b943240b5f58c4de60c1f73c41d0770e7ab', token_count=785, vector_point_id='ch-doc-card-391-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-391-7', 'doc-card-391', 'sec-card-391-4', 7, 'security): «ناپایداری» کار رسانه‌ای؛ «مسابقه» و «فشار» در «عصر دیجیتال»، «ریسک» را «افزایش» داده است. • نقش حرفه‌ای (Professional Role): «نقش» روزنامه‌نگار، ویراستار، کارگردان، مدیر؛ «نقش‌ها»، «ساختار» کار را «تعیین» می‌کنند. • توسعه شغلی (Career Development): «مسیر» شغلی و «آموزش» مداوم؛ «توان» حرفه‌ای، «بازتولید» روزانه نیاز دارد.  ۳. نمونه‌های تحلیلی «حرفه‌ای‌سازی» در عمل: «روزنامه‌نگار» با «دوره» و «اصول» «حرفه‌ای» می‌شود: «اعتبار» از «آموزش» و «اصول» ساخته می‌شود.  «ساختار سازمانی» در عمل: «سلسله‌مراتب» در «تلفظ» (گزارشگر، ویراستار، مدیر) «رفتار» کارکنان را «تعیین» می‌کند: «سلسله‌مراتب»، «نقش» است.', 'f965c0f258f4c4c1dd2dd27abd17ccb5e5c58df5b9d94ca2b7b97348768af0a7', 1109, 'ch-doc-card-391-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f965c0f258f4c4c1dd2dd27abd17ccb5e5c58df5b9d94ca2b7b97348768af0a7', token_count=1109, vector_point_id='ch-doc-card-391-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
