INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-440-12', 'doc-card-440', 'sec-card-440-6', 12, '۱. «بازی» و «استثمار»: «بازی» در «صنعت» «سرگرمی»، «کار» است: «مخاطب» «بازی» می‌کند و «صنعت» «سود» می‌برد: «استثمار» در «بازی» پنهان است. ۲. «میم» و «ایدئولوژی»: «میم» «مقاومت» است اما «بازتولید» «ایدئولوژی» هم: «طنز»، «نقد» نیست، «بازی» است. ۳. «فرهنگ دیجیتال» و «اعتیاد»: «مشارکت» «دیجیتال» می‌تواند «اعتیاد» باشد: «بازی» و «اعتیاد» مرز «کمرنگ» دارد. ۴. «صنعت سرگرمی» و «تنوع»: «صنعت» «استاندارد» می‌کند و «تنوع» را «محو» می‌کند: «سود»، «تنوع» را «حذف» می‌کند. ۵. «بازی‌سازی» و «انگیزه»: «بازی‌سازی» «رفتار» را «بازتولید» می‌کند اما «ا', '2e4941d52959e89db7bc7e9d3006bc9777ecfe2ae344d44bf4db263bfdfd463e', 974, 'ch-doc-card-440-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2e4941d52959e89db7bc7e9d3006bc9777ecfe2ae344d44bf4db263bfdfd463e', token_count=974, vector_point_id='ch-doc-card-440-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-440-13', 'doc-card-440', 'sec-card-440-7', 13, 'نگیزه» «داخلی» را «محو» می‌کند: «پاداش»، «بازی» را «کار» می‌کند. ۶. «فرهنگ همگرا» و «نظارت»: «مخاطب» «تولید» می‌کند و «صنعت» «بازتولید» می‌کند: «نظارت» بر «مخاطب»، «حاکمیت» است. ۷. «فرهنگ عامه دیجیتال» و «اعتبار»: «محتوای» «مخاطب» «ساخته»، «اعتبار» ندارد: «مرز» بین «حرفه‌ای» و «مخاطب»، «بازتعریف» لازم دارد. ۸. «بازی» و «واقعیت»: «بازی» در «بافت» دیجیتال، «واقعیت» است: «مرز» بین «بازی» و «واقعیت»، «محو» شده است. ۹. «فرهنگ دیجیتال» و «نسل»: «فرهنگ» دیجیتال، «نسل» است اما «همه» «نسل‌ها» در آن «حاضر»‌اند: «مرز» «نسل»، «کمرنگ» شده است.', '0b0c3f05ea135af8deed6fc16c6361ab3920d24bdf5ebb22d4b4a264efdf1ab2', 974, 'ch-doc-card-440-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0b0c3f05ea135af8deed6fc16c6361ab3920d24bdf5ebb22d4b4a264efdf1ab2', token_count=974, vector_point_id='ch-doc-card-440-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-440-14', 'doc-card-440', 'sec-card-440-10', 14, 'کتاب «فرهنگ همگرا» (جَنکینز، ۲۰۰۶)؛ کتاب «بازی و فرهنگ» (سوسا، ۱۹۵۵)؛ کتاب «صنعت فرهنگ» (آدورنو و هورکهایمر، ۱۹۴۴)؛ کتاب «فرهنگ دیجیتال» (منرو و همکاران، ۲۰۰۴).', '373e57c2c2351d10cec24f7b867cae52e67956b87e6039750582abd935eddb22', 290, 'ch-doc-card-440-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='373e57c2c2351d10cec24f7b867cae52e67956b87e6039750582abd935eddb22', token_count=290, vector_point_id='ch-doc-card-440-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-441-0', 'doc-card-441', NULL, 0, 'گودیکانست (۱۹۹۳) اثربخشی ارتباط میان‌فرهنگی با غریبه را مشروط به توانایی فرد در مهار هم‌زمان اضطراب عاطفی و عدم‌قطعیت شناختی می‌داند؛ افزایش هر یک، ادراک ذهنی را تشدید و کیفیت پیام‌دهی را کاهش می‌دهد.', '1f24e7304235c888a2f691fe1f041889a7ac4f288a4a7b2afa3a84748d8b2b32', 363, 'ch-doc-card-441-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1f24e7304235c888a2f691fe1f041889a7ac4f288a4a7b2afa3a84748d8b2b32', token_count=363, vector_point_id='ch-doc-card-441-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-441-1', 'doc-card-441', 'sec-card-441-1', 1, 'بازی، سرگرمی و فرهنگ دیجیتال  اثربخشی ارتباط میان‌فرهنگی با غریبه‌ها مشروط به مهارت فرد در مهار سطح اضطراب عاطفی و عدم قطعیت شناختی خود است.', 'cac7b04d9d6d84ae9b44a254f9b8cfebcb9d988249ec67c96accb9f6e74c9133', 254, 'ch-doc-card-441-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cac7b04d9d6d84ae9b44a254f9b8cfebcb9d988249ec67c96accb9f6e74c9133', token_count=254, vector_point_id='ch-doc-card-441-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-441-2', 'doc-card-441', 'sec-card-441-2', 2, '۱. بنیان و منطق نظری مدیریت اضطراب / عدم قطعیت «بازی» را «فعالیت» معنادار در «بافت» دیجیتال می‌داند: نه «فرار» از واقعیت بلکه «بازی» با «معنا». ویلیام گودیکانست (۱۹۹۳) در این چارچوب، «فرهنگ» را نه «محصول» «صنعت» بلکه «فعالیت» مخاطب تعریف کرد: «بازی»، «زبان» «نسل» دیجیتال است.  بر اساس مدیریت اضطراب / عدم قطعیت، «سرگرمی» «صنعت» است اما «فرهنگ» «فعالیت» مخاطب است: «صنعت» «محتوا» تولید می‌کند و «مخاطب» «معنا» بازتولید می‌کند. ویلیام گودیکانست (۱۹۹۳) در این چارچوب، «فرهنگ دیجیتال» را «فضا» «تولید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.', '5315e13d4cf32d8b3af923c3081a138e7ca42cb8a2fae9a92e8d5335fcd95338', 1041, 'ch-doc-card-441-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5315e13d4cf32d8b3af923c3081a138e7ca42cb8a2fae9a92e8d5335fcd95338', token_count=1041, vector_point_id='ch-doc-card-441-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-441-3', 'doc-card-441', 'sec-card-441-2', 3, 'ید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  مدیریت اضطراب / عدم قطعیت را می‌توان پاسخی به شکاف میان «نقد» «صنعت فرهنگ» (فرانکفورت) و «مطالعات فرهنگی» (مقاومت مخاطب) دانست: «بازی» و «سرگرمی» هم «بازتولید» «ایدئولوژی» است و هم «مقاومت» مخاطب. ویلیام گودیکانست (۱۹۹۳) در این چارچوب، «فرهنگ دیجیتال» را «میدان» «دیالکتیک» «صنعت» و «مخاطب» تعریف کرد.  ۲. ساختارهای مفهومی • بازی و فرهنگ (Play and Culture): «بازی» به‌عنوان «زبان» «نسل» دیجیتال: «معنا» در «بازی» ساخته می‌شود. • فرهنگ دیجیتال (Digital Culture): «بافت» «فرهنگی» «نسل» دیجیتال: «بازی»، «بازی»، «میم» و «ریپلای»، «زبان» این «بافت»‌اند.', 'ead6b35e7df74e9479241f6b33863035fbd215ee5a2760e3a42e6119b43e91d0', 1143, 'ch-doc-card-441-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ead6b35e7df74e9479241f6b33863035fbd215ee5a2760e3a42e6119b43e91d0', token_count=1143, vector_point_id='ch-doc-card-441-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
