INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-442-7', 'doc-card-442', 'sec-card-442-4', 7, '«واحد» «فرهنگی» که «تولید» و «تکرار» «اجتماعی» دارد: «میم»، «زبان» «فرهنگ» دیجیتال است. • بازی‌سازی (Gamification): «بازی» در «بافت» «غیربازی»: «رقابت»، «پاداش» و «نقش»، «رفتار» را «بازتولید» می‌کنند. • فرهنگ همگرا (Convergent Culture): «همگرایی» «محتوا»، «پلتفرم» و «مخاطب»: «مخاطب»، «محتوا» را «بازتولید» می‌کند.  ۳. نمونه‌های تحلیلی «بازی» در «فرهنگ» دیجیتال: «بازی‌های» «ویدیویی»، «بافت» «فرهنگی» «نسل» دیجیتال «ساخته»‌اند: «زبان»، «نماد» و «بازی» «بازی»، «زبان» «فرهنگ» است.  «میم» در عمل: «میم» «وایرال» «تولید» و «تکرار» «اجتماعی» دارد: «میم»، «زبان» «فرهنگ» دیجیتال است و «معنا» در «تکرار» ساخته می‌شود.', '5957941efd978ed7252744fb167ab8556e5a0a13e17b7f3f9d270ecfb5da9f4c', 1110, 'ch-doc-card-442-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5957941efd978ed7252744fb167ab8556e5a0a13e17b7f3f9d270ecfb5da9f4c', token_count=1110, vector_point_id='ch-doc-card-442-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-442-8', 'doc-card-442', 'sec-card-442-4', 8, 'اعی» دارد: «میم»، «زبان» «فرهنگ» دیجیتال است و «معنا» در «تکرار» ساخته می‌شود.  «صنعت سرگرمی» در «عصر دیجیتال»: «پلتفرم‌های» استریمینگ «محتوا» را «استاندارد» می‌کنند: «سود»، «تکرار» و «استاندارد»، «منطق» «صنعت» است.  «فرهنگ همگرا» در عمل: «مخاطب» «سریال» «محتوا» «بازتولید» می‌کند (ریپلای، مم، کاسپلی): «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  «بازی‌سازی» در «آموزش»: «بازی» در «بافت» «آموزش» (پاداش، نقش، رقابت) «رفتار» را «بازتولید» می‌کند: «بازی»، «ابزار» «رفتار» است.  «فرهنگ عامه دیجیتال» در عمل: «محتوای» «مخاطب» «ساخته» (ویدیو، مم، پادکست) «زبان» «فرهنگ» است: «مخاطب»، «تولیدکننده» «فرهنگ» است.  ۴. نقدها و چالش‌ها ۱.', '03da41571ec881f8dd1edc161fa020f1225fcc95e29ee7212ee2e7fcab523fef', 1174, 'ch-doc-card-442-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='03da41571ec881f8dd1edc161fa020f1225fcc95e29ee7212ee2e7fcab523fef', token_count=1174, vector_point_id='ch-doc-card-442-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-442-9', 'doc-card-442', 'sec-card-442-4', 9, ') «زبان» «فرهنگ» است: «مخاطب»، «تولیدکننده» «فرهنگ» است.  ۴. نقدها و چالش‌ها ۱. «بازی» و «استثمار»: «بازی» در «صنعت» «سرگرمی»، «کار» است: «مخاطب» «بازی» می‌کند و «صنعت» «سود» می‌برد: «استثمار» در «بازی» پنهان است. ۲. «میم» و «ایدئولوژی»: «میم» «مقاومت» است اما «بازتولید» «ایدئولوژی» هم: «طنز»، «نقد» نیست، «بازی» است. ۳. «فرهنگ دیجیتال» و «اعتیاد»: «مشارکت» «دیجیتال» می‌تو', 'c9b7a2b98b29d4d964e15158080b78477703ab406e528160b7f98c21902613fd', 680, 'ch-doc-card-442-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c9b7a2b98b29d4d964e15158080b78477703ab406e528160b7f98c21902613fd', token_count=680, vector_point_id='ch-doc-card-442-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
