INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-442-11', 'doc-card-442', 'sec-card-442-5', 11, 'ای، مم، کاسپلی): «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  «بازی‌سازی» در «آموزش»: «بازی» در «بافت» «آموزش» (پاداش، نقش، رقابت) «رفتار» را «بازتولید» می‌کند: «بازی»، «ابزار» «رفتار» است.  «فرهنگ عامه دیجیتال» در عمل: «محتوای» «مخاطب» «ساخته» (ویدیو، مم، پادکست) «زبان» «فرهنگ» است: «مخاطب»، «تولیدکننده» «فرهنگ» است.', 'e2641dc1819daaca840a57098fa60cd466dc20ba934bb2ffe6eeb8441b790705', 612, 'ch-doc-card-442-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e2641dc1819daaca840a57098fa60cd466dc20ba934bb2ffe6eeb8441b790705', token_count=612, vector_point_id='ch-doc-card-442-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-442-12', 'doc-card-442', 'sec-card-442-6', 12, '۱. «بازی» و «استثمار»: «بازی» در «صنعت» «سرگرمی»، «کار» است: «مخاطب» «بازی» می‌کند و «صنعت» «سود» می‌برد: «استثمار» در «بازی» پنهان است. ۲. «میم» و «ایدئولوژی»: «میم» «مقاومت» است اما «بازتولید» «ایدئولوژی» هم: «طنز»، «نقد» نیست، «بازی» است. ۳. «فرهنگ دیجیتال» و «اعتیاد»: «مشارکت» «دیجیتال» می‌تواند «اعتیاد» باشد: «بازی» و «اعتیاد» مرز «کمرنگ» دارد. ۴. «صنعت سرگرمی» و «تنوع»: «صنعت» «استاندارد» می‌کند و «تنوع» را «محو» می‌کند: «سود»، «تنوع» را «حذف» می‌کند. ۵. «بازی‌سازی» و «انگیزه»: «بازی‌سازی» «رفتار» را «بازتولید» می‌کند اما «ا', '2e4941d52959e89db7bc7e9d3006bc9777ecfe2ae344d44bf4db263bfdfd463e', 974, 'ch-doc-card-442-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2e4941d52959e89db7bc7e9d3006bc9777ecfe2ae344d44bf4db263bfdfd463e', token_count=974, vector_point_id='ch-doc-card-442-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-442-13', 'doc-card-442', 'sec-card-442-7', 13, 'نگیزه» «داخلی» را «محو» می‌کند: «پاداش»، «بازی» را «کار» می‌کند. ۶. «فرهنگ همگرا» و «نظارت»: «مخاطب» «تولید» می‌کند و «صنعت» «بازتولید» می‌کند: «نظارت» بر «مخاطب»، «حاکمیت» است. ۷. «فرهنگ عامه دیجیتال» و «اعتبار»: «محتوای» «مخاطب» «ساخته»، «اعتبار» ندارد: «مرز» بین «حرفه‌ای» و «مخاطب»، «بازتعریف» لازم دارد. ۸. «بازی» و «واقعیت»: «بازی» در «بافت» دیجیتال، «واقعیت» است: «مرز» بین «بازی» و «واقعیت»، «محو» شده است. ۹. «فرهنگ دیجیتال» و «نسل»: «فرهنگ» دیجیتال، «نسل» است اما «همه» «نسل‌ها» در آن «حاضر»‌اند: «مرز» «نسل»، «کمرنگ» شده است.', '0b0c3f05ea135af8deed6fc16c6361ab3920d24bdf5ebb22d4b4a264efdf1ab2', 974, 'ch-doc-card-442-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0b0c3f05ea135af8deed6fc16c6361ab3920d24bdf5ebb22d4b4a264efdf1ab2', token_count=974, vector_point_id='ch-doc-card-442-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-442-14', 'doc-card-442', 'sec-card-442-10', 14, 'کتاب «فرهنگ همگرا» (جَنکینز، ۲۰۰۶)؛ کتاب «بازی و فرهنگ» (سوسا، ۱۹۵۵)؛ کتاب «صنعت فرهنگ» (آدورنو و هورکهایمر، ۱۹۴۴)؛ کتاب «فرهنگ دیجیتال» (منرو و همکاران، ۲۰۰۴).', '373e57c2c2351d10cec24f7b867cae52e67956b87e6039750582abd935eddb22', 290, 'ch-doc-card-442-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='373e57c2c2351d10cec24f7b867cae52e67956b87e6039750582abd935eddb22', token_count=290, vector_point_id='ch-doc-card-442-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-443-0', 'doc-card-443', NULL, 0, 'هارت‌ساک (۱۹۸۳) در epistemology of standpoint می‌گوید گروه‌های حاشیه‌ای و فرودست جامعه، به‌خاطر موقعیتشان، ادراک عمیق‌تر و کم‌سوگیرانه‌تری از سازوکارهای قدرت دارند؛ نقطه‌دید از موقعیت اجتماعی و تجربه زیسته شکل می‌گیرد.', '97a9baf3ff91139a217d6bbf96759d652aee039a0cfdbab7182a300899afa537', 396, 'ch-doc-card-443-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='97a9baf3ff91139a217d6bbf96759d652aee039a0cfdbab7182a300899afa537', token_count=396, vector_point_id='ch-doc-card-443-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-443-1', 'doc-card-443', 'sec-card-443-1', 1, 'بازی، سرگرمی و فرهنگ دیجیتال  معرفت‌شناسی موضع‌مند؛ گروه‌های به حاشیه رانده‌شده و فرودست جامعه، ادراک عمیق‌تر و کم‌سوگیرانه‌تری از سازوکارهای قدرت نسبت به نخبگان برخوردار دارند.', '34aefff19d129d5076a6ef3cd22be82e1c88dc94978080bbcabce4ecc54e1f2e', 321, 'ch-doc-card-443-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='34aefff19d129d5076a6ef3cd22be82e1c88dc94978080bbcabce4ecc54e1f2e', token_count=321, vector_point_id='ch-doc-card-443-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-443-2', 'doc-card-443', 'sec-card-443-2', 2, '۱. بنیان و منطق نظری نظریه نقطه دیدگاه «بازی» را «فعالیت» معنادار در «بافت» دیجیتال می‌داند: نه «فرار» از واقعیت بلکه «بازی» با «معنا». نانسی هارت‌ساک (۱۹۸۳) در این چارچوب، «فرهنگ» را نه «محصول» «صنعت» بلکه «فعالیت» مخاطب تعریف کرد: «بازی»، «زبان» «نسل» دیجیتال است.  بر اساس نظریه نقطه دیدگاه، «سرگرمی» «صنعت» است اما «فرهنگ» «فعالیت» مخاطب است: «صنعت» «محتوا» تولید می‌کند و «مخاطب» «معنا» بازتولید می‌کند. نانسی هارت‌ساک (۱۹۸۳) در این چارچوب، «فرهنگ دیجیتال» را «فضا» «تولید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.', 'de31fb5612e3f19624943c8d4f13d7948687fb90c2e3ea79c0d469334ec8f2e7', 1005, 'ch-doc-card-443-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='de31fb5612e3f19624943c8d4f13d7948687fb90c2e3ea79c0d469334ec8f2e7', token_count=1005, vector_point_id='ch-doc-card-443-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-443-3', 'doc-card-443', 'sec-card-443-2', 3, 'ید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  نظریه نقطه دیدگاه را می‌توان پاسخی به شکاف میان «نقد» «صنعت فرهنگ» (فرانکفورت) و «مطالعات فرهنگی» (مقاومت مخاطب) دانست: «بازی» و «سرگرمی» هم «بازتولید» «ایدئولوژی» است و هم «مقاومت» مخاطب. نانسی هارت‌ساک (۱۹۸۳) در این چارچوب، «فرهنگ دیجیتال» را «میدان» «دیالکتیک» «صنعت» و «مخاطب» تعریف کرد.  ۲. ساختارهای مفهومی • بازی و فرهنگ (Play and Culture): «بازی» به‌عنوان «زبان» «نسل» دیجیتال: «معنا» در «بازی» ساخته می‌شود. • فرهنگ دیجیتال (Digital Culture): «بافت» «فرهنگی» «نسل» دیجیتال: «بازی»، «بازی»، «میم» و «ریپلای»، «زبان» این «بافت»‌اند.', 'a499270bb8316c1ab234df8c81f6fdac57e266559f57ee618ac76f0775282504', 1125, 'ch-doc-card-443-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a499270bb8316c1ab234df8c81f6fdac57e266559f57ee618ac76f0775282504', token_count=1125, vector_point_id='ch-doc-card-443-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
