INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-443-14', 'doc-card-443', 'sec-card-443-10', 14, 'کتاب «فرهنگ همگرا» (جَنکینز، ۲۰۰۶)؛ کتاب «بازی و فرهنگ» (سوسا، ۱۹۵۵)؛ کتاب «صنعت فرهنگ» (آدورنو و هورکهایمر، ۱۹۴۴)؛ کتاب «فرهنگ دیجیتال» (منرو و همکاران، ۲۰۰۴).', '373e57c2c2351d10cec24f7b867cae52e67956b87e6039750582abd935eddb22', 290, 'ch-doc-card-443-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='373e57c2c2351d10cec24f7b867cae52e67956b87e6039750582abd935eddb22', token_count=290, vector_point_id='ch-doc-card-443-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-444-0', 'doc-card-444', NULL, 0, 'آردنر (۱۹۷۵) استدلال می‌کند زبان و ساختار ارتباطی جامعه عمدتا توسط مردان و طبقات مسلط ساخته شده و گروه‌های حاشیه‌ای برای شنیده‌شدن، تجربه‌های خود را به زبان مسلط ترجمه می‌کنند؛ گفتمان مسلط صدای خاموش‌شدگان را پیش از بیان بازنویسی می‌کند.', '222871b1fca6273045155572725d8ea72b3a0368f3425b0cb29224d54195e947', 430, 'ch-doc-card-444-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='222871b1fca6273045155572725d8ea72b3a0368f3425b0cb29224d54195e947', token_count=430, vector_point_id='ch-doc-card-444-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-444-1', 'doc-card-444', 'sec-card-444-1', 1, 'بازی، سرگرمی و فرهنگ دیجیتال  زبان و ساختار ارتباطی جامعه توسط مردان/طبقات مسلط ساخته شده است؛ گروه‌های در حاشیه برای رساندن صدای خود مجبورند تجربه خویش را به زبان مسلط ترجمه کنند.', '49ae5b147d45b8e051796ba1c692176699f36a5f97604e763ed3760b721aa080', 327, 'ch-doc-card-444-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='49ae5b147d45b8e051796ba1c692176699f36a5f97604e763ed3760b721aa080', token_count=327, vector_point_id='ch-doc-card-444-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-444-2', 'doc-card-444', 'sec-card-444-2', 2, '۱. بنیان و منطق نظری نظریه گروه خاموش «بازی» را «فعالیت» معنادار در «بافت» دیجیتال می‌داند: نه «فرار» از واقعیت بلکه «بازی» با «معنا». ادوین آردنر (۱۹۷۵) در این چارچوب، «فرهنگ» را نه «محصول» «صنعت» بلکه «فعالیت» مخاطب تعریف کرد: «بازی»، «زبان» «نسل» دیجیتال است.  بر اساس نظریه گروه خاموش، «سرگرمی» «صنعت» است اما «فرهنگ» «فعالیت» مخاطب است: «صنعت» «محتوا» تولید می‌کند و «مخاطب» «معنا» بازتولید می‌کند. ادوین آردنر (۱۹۷۵) در این چارچوب، «فرهنگ دیجیتال» را «فضا» «تولید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.', 'c061730fcabeb771352c7f9bca680d09100be155f2a894b7653aaf4e03960e4a', 990, 'ch-doc-card-444-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c061730fcabeb771352c7f9bca680d09100be155f2a894b7653aaf4e03960e4a', token_count=990, vector_point_id='ch-doc-card-444-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-444-3', 'doc-card-444', 'sec-card-444-2', 3, 'ید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  نظریه گروه خاموش را می‌توان پاسخی به شکاف میان «نقد» «صنعت فرهنگ» (فرانکفورت) و «مطالعات فرهنگی» (مقاومت مخاطب) دانست: «بازی» و «سرگرمی» هم «بازتولید» «ایدئولوژی» است و هم «مقاومت» مخاطب. ادوین آردنر (۱۹۷۵) در این چارچوب، «فرهنگ دیجیتال» را «میدان» «دیالکتیک» «صنعت» و «مخاطب» تعریف کرد.  ۲. ساختارهای مفهومی • بازی و فرهنگ (Play and Culture): «بازی» به‌عنوان «زبان» «نسل» دیجیتال: «معنا» در «بازی» ساخته می‌شود. • فرهنگ دیجیتال (Digital Culture): «بافت» «فرهنگی» «نسل» دیجیتال: «بازی»، «بازی»، «میم» و «ریپلای»، «زبان» این «بافت»‌اند.', 'ccce1f871c518ecb18d8e1915f37ac822d776456a2cb71e2e60ca67f50db986d', 1118, 'ch-doc-card-444-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ccce1f871c518ecb18d8e1915f37ac822d776456a2cb71e2e60ca67f50db986d', token_count=1118, vector_point_id='ch-doc-card-444-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
