INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-444-10', 'doc-card-444', 'sec-card-444-5', 10, '«بازی» در «فرهنگ» دیجیتال: «بازی‌های» «ویدیویی»، «بافت» «فرهنگی» «نسل» دیجیتال «ساخته»‌اند: «زبان»، «نماد» و «بازی» «بازی»، «زبان» «فرهنگ» است.  «میم» در عمل: «میم» «وایرال» «تولید» و «تکرار» «اجتماعی» دارد: «میم»، «زبان» «فرهنگ» دیجیتال است و «معنا» در «تکرار» ساخته می‌شود.  «صنعت سرگرمی» در «عصر دیجیتال»: «پلتفرم‌های» استریمینگ «محتوا» را «استاندارد» می‌کنند: «سود»، «تکرار» و «استاندارد»، «منطق» «صنعت» است.  «فرهنگ همگرا» در عمل: «مخاطب» «سریال» «محتوا» «بازتولید» می‌کند (ریپلای، مم، کاسپلی): «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.', 'a9931917823f99e9f8ac7f33f2911c5aa9fdb2368cefdde2b8c38d4cc298153e', 1019, 'ch-doc-card-444-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a9931917823f99e9f8ac7f33f2911c5aa9fdb2368cefdde2b8c38d4cc298153e', token_count=1019, vector_point_id='ch-doc-card-444-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-444-11', 'doc-card-444', 'sec-card-444-5', 11, 'ای، مم، کاسپلی): «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  «بازی‌سازی» در «آموزش»: «بازی» در «بافت» «آموزش» (پاداش، نقش، رقابت) «رفتار» را «بازتولید» می‌کند: «بازی»، «ابزار» «رفتار» است.  «فرهنگ عامه دیجیتال» در عمل: «محتوای» «مخاطب» «ساخته» (ویدیو، مم، پادکست) «زبان» «فرهنگ» است: «مخاطب»، «تولیدکننده» «فرهنگ» است.', 'e2641dc1819daaca840a57098fa60cd466dc20ba934bb2ffe6eeb8441b790705', 612, 'ch-doc-card-444-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e2641dc1819daaca840a57098fa60cd466dc20ba934bb2ffe6eeb8441b790705', token_count=612, vector_point_id='ch-doc-card-444-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-444-12', 'doc-card-444', 'sec-card-444-6', 12, '۱. «بازی» و «استثمار»: «بازی» در «صنعت» «سرگرمی»، «کار» است: «مخاطب» «بازی» می‌کند و «صنعت» «سود» می‌برد: «استثمار» در «بازی» پنهان است. ۲. «میم» و «ایدئولوژی»: «میم» «مقاومت» است اما «بازتولید» «ایدئولوژی» هم: «طنز»، «نقد» نیست، «بازی» است. ۳. «فرهنگ دیجیتال» و «اعتیاد»: «مشارکت» «دیجیتال» می‌تواند «اعتیاد» باشد: «بازی» و «اعتیاد» مرز «کمرنگ» دارد. ۴. «صنعت سرگرمی» و «تنوع»: «صنعت» «استاندارد» می‌کند و «تنوع» را «محو» می‌کند: «سود»، «تنوع» را «حذف» می‌کند. ۵. «بازی‌سازی» و «انگیزه»: «بازی‌سازی» «رفتار» را «بازتولید» می‌کند اما «ا', '2e4941d52959e89db7bc7e9d3006bc9777ecfe2ae344d44bf4db263bfdfd463e', 974, 'ch-doc-card-444-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2e4941d52959e89db7bc7e9d3006bc9777ecfe2ae344d44bf4db263bfdfd463e', token_count=974, vector_point_id='ch-doc-card-444-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-444-13', 'doc-card-444', 'sec-card-444-7', 13, 'نگیزه» «داخلی» را «محو» می‌کند: «پاداش»، «بازی» را «کار» می‌کند. ۶. «فرهنگ همگرا» و «نظارت»: «مخاطب» «تولید» می‌کند و «صنعت» «بازتولید» می‌کند: «نظارت» بر «مخاطب»، «حاکمیت» است. ۷. «فرهنگ عامه دیجیتال» و «اعتبار»: «محتوای» «مخاطب» «ساخته»، «اعتبار» ندارد: «مرز» بین «حرفه‌ای» و «مخاطب»، «بازتعریف» لازم دارد. ۸. «بازی» و «واقعیت»: «بازی» در «بافت» دیجیتال، «واقعیت» است: «مرز» بین «بازی» و «واقعیت»، «محو» شده است. ۹. «فرهنگ دیجیتال» و «نسل»: «فرهنگ» دیجیتال، «نسل» است اما «همه» «نسل‌ها» در آن «حاضر»‌اند: «مرز» «نسل»، «کمرنگ» شده است.', '0b0c3f05ea135af8deed6fc16c6361ab3920d24bdf5ebb22d4b4a264efdf1ab2', 974, 'ch-doc-card-444-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0b0c3f05ea135af8deed6fc16c6361ab3920d24bdf5ebb22d4b4a264efdf1ab2', token_count=974, vector_point_id='ch-doc-card-444-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-444-14', 'doc-card-444', 'sec-card-444-10', 14, 'کتاب «فرهنگ همگرا» (جَنکینز، ۲۰۰۶)؛ کتاب «بازی و فرهنگ» (سوسا، ۱۹۵۵)؛ کتاب «صنعت فرهنگ» (آدورنو و هورکهایمر، ۱۹۴۴)؛ کتاب «فرهنگ دیجیتال» (منرو و همکاران، ۲۰۰۴).', '373e57c2c2351d10cec24f7b867cae52e67956b87e6039750582abd935eddb22', 290, 'ch-doc-card-444-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='373e57c2c2351d10cec24f7b867cae52e67956b87e6039750582abd935eddb22', token_count=290, vector_point_id='ch-doc-card-444-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-445-0', 'doc-card-445', NULL, 0, 'اوربه (۱۹۹۸) در co-cultural theory الگویهای رفتاری اعضای خرده‌فرهنگ‌های غیرمسلط را تبیین می‌کند: آمیختگی، انطباق و جدایی‌طلبی، هر کدام در قالب رفتارهای پرخاشگرانه، قاطع یا منفعل در مواجهه با فرهنگ مسلط.', 'f958bc2f741d6fc9fa3ad766d78cb05c0fd51f2d2c0e0acb96a7c796de8cd7a0', 367, 'ch-doc-card-445-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f958bc2f741d6fc9fa3ad766d78cb05c0fd51f2d2c0e0acb96a7c796de8cd7a0', token_count=367, vector_point_id='ch-doc-card-445-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-445-1', 'doc-card-445', 'sec-card-445-1', 1, 'بازی، سرگرمی و فرهنگ دیجیتال  شیوه‌هایی که اعضای خرده‌فرهنگ‌های غیرمسلط (اقلیت‌ها) در مواجهه با فرهنگ مسلط برمی‌گزینند (آمیختگی، انطباق، یا جدایی‌طلبی در قالب رفتارهای پرخاشگرانه، قاطع یا منفعل).', 'c5ee510f4f8de18b1845c349c37493dd4d91091833dc16d6b25ae95c6ea17d65', 354, 'ch-doc-card-445-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c5ee510f4f8de18b1845c349c37493dd4d91091833dc16d6b25ae95c6ea17d65', token_count=354, vector_point_id='ch-doc-card-445-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-445-2', 'doc-card-445', 'sec-card-445-2', 2, '۱. بنیان و منطق نظری نظریه هم‌فرهنگی «بازی» را «فعالیت» معنادار در «بافت» دیجیتال می‌داند: نه «فرار» از واقعیت بلکه «بازی» با «معنا». مارک اوربه (۱۹۹۸) در این چارچوب، «فرهنگ» را نه «محصول» «صنعت» بلکه «فعالیت» مخاطب تعریف کرد: «بازی»، «زبان» «نسل» دیجیتال است.  بر اساس نظریه هم‌فرهنگی، «سرگرمی» «صنعت» است اما «فرهنگ» «فعالیت» مخاطب است: «صنعت» «محتوا» تولید می‌کند و «مخاطب» «معنا» بازتولید می‌کند. مارک اوربه (۱۹۹۸) در این چارچوب، «فرهنگ دیجیتال» را «فضا» «تولید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.', '894882dd4fefd1e44f31b4117fb1f6bc62afe33861f962c36f786761d187e8a9', 983, 'ch-doc-card-445-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='894882dd4fefd1e44f31b4117fb1f6bc62afe33861f962c36f786761d187e8a9', token_count=983, vector_point_id='ch-doc-card-445-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-445-3', 'doc-card-445', 'sec-card-445-2', 3, 'ید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  نظریه هم‌فرهنگی را می‌توان پاسخی به شکاف میان «نقد» «صنعت فرهنگ» (فرانکفورت) و «مطالعات فرهنگی» (مقاومت مخاطب) دانست: «بازی» و «سرگرمی» هم «بازتولید» «ایدئولوژی» است و هم «مقاومت» مخاطب. مارک اوربه (۱۹۹۸) در این چارچوب، «فرهنگ دیجیتال» را «میدان» «دیالکتیک» «صنعت» و «مخاطب» تعریف کرد.  ۲. ساختارهای مفهومی • بازی و فرهنگ (Play and Culture): «بازی» به‌عنوان «زبان» «نسل» دیجیتال: «معنا» در «بازی» ساخته می‌شود. • فرهنگ دیجیتال (Digital Culture): «بافت» «فرهنگی» «نسل» دیجیتال: «بازی»، «بازی»، «میم» و «ریپلای»، «زبان» این «بافت»‌اند.', '6f701312b812c318e3e913c2217352c6693e7ace29f8990c2de75ee418747a33', 1114, 'ch-doc-card-445-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6f701312b812c318e3e913c2217352c6693e7ace29f8990c2de75ee418747a33', token_count=1114, vector_point_id='ch-doc-card-445-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-445-4', 'doc-card-445', 'sec-card-445-2', 4, 'فرهنگی» «نسل» دیجیتال: «بازی»، «بازی»، «میم» و «ریپلای»، «زبان» این «بافت»‌اند. • صنعت سرگرمی (Entertainment Industry): «صنعت» «تولید» «محتوای» سرگرمی: «سود»، «تکرار» و «استاندارد»، «منطق» «صنعت» است. • فرهنگ عامه دیجیتال (Digital Pop Culture): «فرهنگ» «عامه» در «بافت» دیجیتال: «محتوا» «مخاطب» «ساخته»، «زبان» «فرهنگ» است. • تعامل و مشارکت (Interaction and Participation): «مخاطب» در «بافت» دیجیتال «مشارکت» می‌کند: «بازی» و «بازی»، «مشارکت» است. • مم (Meme): «واحد» «ف', '9bc76747bfbaf82878d0d3a7b1a10cf3e5ead03089b5f4127d67c6e8f7ed0dd6', 854, 'ch-doc-card-445-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9bc76747bfbaf82878d0d3a7b1a10cf3e5ead03089b5f4127d67c6e8f7ed0dd6', token_count=854, vector_point_id='ch-doc-card-445-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-445-5', 'doc-card-445', 'sec-card-445-3', 5, '• بازی و فرهنگ (Play and Culture): «بازی» به‌عنوان «زبان» «نسل» دیجیتال: «معنا» در «بازی» ساخته می‌شود. • فرهنگ دیجیتال (Digital Culture): «بافت» «فرهنگی» «نسل» دیجیتال: «بازی»، «بازی»، «میم» و «ریپلای»، «زبان» این «بافت»‌اند. • صنعت سرگرمی (Entertainment Industry): «صنعت» «تولید» «محتوای» سرگرمی: «سود»، «تکرار» و «استاندارد»، «منطق» «صنعت» است. • فرهنگ عامه دیجیتال (Digital Pop Culture): «فرهنگ» «عامه» در «بافت» دیجیتال: «محتوا» «مخاطب» «ساخته»، «زبان» «فرهنگ» است. • تعامل و مشارکت (Interaction and Participation): «مخاطب» در «بافت» دیجیتال «مشارکت» می‌کند: «بازی» و «بازی»، «مشارکت» است.', '3568aba6d13f485a22c8484a9dc926175664929f5d61008ea007723802e07e96', 1080, 'ch-doc-card-445-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3568aba6d13f485a22c8484a9dc926175664929f5d61008ea007723802e07e96', token_count=1080, vector_point_id='ch-doc-card-445-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-445-6', 'doc-card-445', 'sec-card-445-3', 6, 'ion): «مخاطب» در «بافت» دیجیتال «مشارکت» می‌کند: «بازی» و «بازی»، «مشارکت» است. • مم (Meme): «واحد» «فرهنگی» که «تولید» و «تکرار» «اجتماعی» دارد: «میم»، «زبان» «فرهنگ» دیجیتال است. • بازی‌سازی (Gamification): «بازی» در «بافت» «غیربازی»: «رقابت»، «پاداش» و «نقش»، «رفتار» را «بازتولید» می‌کنند. • فرهنگ همگرا (Convergent Culture): «همگرایی» «محتوا»، «پلتفرم» و «مخاطب»: «مخاطب»، «محتوا» را «بازتولید» می‌کند.', '79600879f394647bd0c6ffef7dc41a0d3d538c41b1e8a58f2ad128ade359a45b', 739, 'ch-doc-card-445-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='79600879f394647bd0c6ffef7dc41a0d3d538c41b1e8a58f2ad128ade359a45b', token_count=739, vector_point_id='ch-doc-card-445-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-445-7', 'doc-card-445', 'sec-card-445-4', 7, 'رهنگی» که «تولید» و «تکرار» «اجتماعی» دارد: «میم»، «زبان» «فرهنگ» دیجیتال است. • بازی‌سازی (Gamification): «بازی» در «بافت» «غیربازی»: «رقابت»، «پاداش» و «نقش»، «رفتار» را «بازتولید» می‌کنند. • فرهنگ همگرا (Convergent Culture): «همگرایی» «محتوا»، «پلتفرم» و «مخاطب»: «مخاطب»، «محتوا» را «بازتولید» می‌کند.  ۳. نمونه‌های تحلیلی «بازی» در «فرهنگ» دیجیتال: «بازی‌های» «ویدیویی»، «بافت» «فرهنگی» «نسل» دیجیتال «ساخته»‌اند: «زبان»، «نماد» و «بازی» «بازی»، «زبان» «فرهنگ» است.  «میم» در عمل: «میم» «وایرال» «تولید» و «تکرار» «اجتماعی» دارد: «میم»، «زبان» «فرهنگ» دیجیتال است و «معنا» در «تکرار» ساخته می‌شود.', 'b8f63db3642a678f153e0ba41896debb9c5fe741e1962be58998293a6ce8fcca', 1094, 'ch-doc-card-445-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b8f63db3642a678f153e0ba41896debb9c5fe741e1962be58998293a6ce8fcca', token_count=1094, vector_point_id='ch-doc-card-445-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-445-8', 'doc-card-445', 'sec-card-445-4', 8, 'اعی» دارد: «میم»، «زبان» «فرهنگ» دیجیتال است و «معنا» در «تکرار» ساخته می‌شود.  «صنعت سرگرمی» در «عصر دیجیتال»: «پلتفرم‌های» استریمینگ «محتوا» را «استاندارد» می‌کنند: «سود»، «تکرار» و «استاندارد»، «منطق» «صنعت» است.  «فرهنگ همگرا» در عمل: «مخاطب» «سریال» «محتوا» «بازتولید» می‌کند (ریپلای، مم، کاسپلی): «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  «بازی‌سازی» در «آموزش»: «بازی» در «بافت» «آموزش» (پاداش، نقش، رقابت) «رفتار» را «بازتولید» می‌کند: «بازی»، «ابزار» «رفتار» است.  «فرهنگ عامه دیجیتال» در عمل: «محتوای» «مخاطب» «ساخته» (ویدیو، مم، پادکست) «زبان» «فرهنگ» است: «مخاطب»، «تولیدکننده» «فرهنگ» است.  ۴. نقدها و چالش‌ها ۱.', '03da41571ec881f8dd1edc161fa020f1225fcc95e29ee7212ee2e7fcab523fef', 1174, 'ch-doc-card-445-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='03da41571ec881f8dd1edc161fa020f1225fcc95e29ee7212ee2e7fcab523fef', token_count=1174, vector_point_id='ch-doc-card-445-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-445-9', 'doc-card-445', 'sec-card-445-4', 9, ') «زبان» «فرهنگ» است: «مخاطب»، «تولیدکننده» «فرهنگ» است.  ۴. نقدها و چالش‌ها ۱. «بازی» و «استثمار»: «بازی» در «صنعت» «سرگرمی»، «کار» است: «مخاطب» «بازی» می‌کند و «صنعت» «سود» می‌برد: «استثمار» در «بازی» پنهان است. ۲. «میم» و «ایدئولوژی»: «میم» «مقاومت» است اما «بازتولید» «ایدئولوژی» هم: «طنز»، «نقد» نیست، «بازی» است. ۳. «فرهنگ دیجیتال» و «اعتیاد»: «مشارکت» «دیجیتال» می‌تواند', 'f3af8af270e4c2204163521d03f64bcc51885b4214270ee1142cfed5e8c9affd', 685, 'ch-doc-card-445-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f3af8af270e4c2204163521d03f64bcc51885b4214270ee1142cfed5e8c9affd', token_count=685, vector_point_id='ch-doc-card-445-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
