INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-446-14', 'doc-card-446', 'sec-card-446-10', 14, 'کتاب «فرهنگ همگرا» (جَنکینز، ۲۰۰۶)؛ کتاب «بازی و فرهنگ» (سوسا، ۱۹۵۵)؛ کتاب «صنعت فرهنگ» (آدورنو و هورکهایمر، ۱۹۴۴)؛ کتاب «فرهنگ دیجیتال» (منرو و همکاران، ۲۰۰۴).', '373e57c2c2351d10cec24f7b867cae52e67956b87e6039750582abd935eddb22', 290, 'ch-doc-card-446-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='373e57c2c2351d10cec24f7b867cae52e67956b87e6039750582abd935eddb22', token_count=290, vector_point_id='ch-doc-card-446-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-447-0', 'doc-card-447', NULL, 0, 'سازمان‌ها ساختار از پیش داده‌شده نیستند، بلکه محصول فرایند حس‌سازی (sensemaking) اعضا‌اند: با سخن‌گفتن و کنش، ابهام محیطی را کم و نظم می‌سازند. بافت دیجیتال هم فضایی است که مخاطبان از طریق میم و مشارکت، معنا را بازتولید می‌کنند.', '5e11ca52e3e2aebd22db8a2e7f2110cba296e8ddd46f7d24507213e3d3ca6228', 414, 'ch-doc-card-447-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5e11ca52e3e2aebd22db8a2e7f2110cba296e8ddd46f7d24507213e3d3ca6228', token_count=414, vector_point_id='ch-doc-card-447-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-447-1', 'doc-card-447', 'sec-card-447-1', 1, 'بازی، سرگرمی و فرهنگ دیجیتال  سازمان‌ها ساختارهای صلب از پیش داده شده نیستند، بلکه از طریق سخن‌گفتن و کنش مداوم اعضا برای زدودن ابهامات محیطی، معنا و نظم را برمی‌سازند («چگونه بفهمم چه فکر می‌کنم تا وقتی نشنوم چه می‌گویم؟»).', '03773448ac271d8148368c897c214f3d88401438c4249b2ff6ad1f761f31a6cb', 407, 'ch-doc-card-447-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='03773448ac271d8148368c897c214f3d88401438c4249b2ff6ad1f761f31a6cb', token_count=407, vector_point_id='ch-doc-card-447-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-447-2', 'doc-card-447', 'sec-card-447-2', 2, '۱. بنیان و منطق نظری نظریه حس‌سازی و تولید معنا در سازمان «بازی» را «فعالیت» معنادار در «بافت» دیجیتال می‌داند: نه «فرار» از واقعیت بلکه «بازی» با «معنا». کارل ویک (۱۹۷۹) در این چارچوب، «فرهنگ» را نه «محصول» «صنعت» بلکه «فعالیت» مخاطب تعریف کرد: «بازی»، «زبان» «نسل» دیجیتال است.  بر اساس نظریه حس‌سازی و تولید معنا در سازمان، «سرگرمی» «صنعت» است اما «فرهنگ» «فعالیت» مخاطب است: «صنعت» «محتوا» تولید می‌کند و «مخاطب» «معنا» بازتولید می‌کند. کارل ویک (۱۹۷۹) در این چارچوب، «فرهنگ دیجیتال» را «فضا» «تولید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.', 'ac7c39628dd8268a0200f27be5a3d975bd58e217c458b231070c08afad86ef1d', 1052, 'ch-doc-card-447-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ac7c39628dd8268a0200f27be5a3d975bd58e217c458b231070c08afad86ef1d', token_count=1052, vector_point_id='ch-doc-card-447-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-447-3', 'doc-card-447', 'sec-card-447-2', 3, 'ید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  نظریه حس‌سازی و تولید معنا در سازمان را می‌توان پاسخی به شکاف میان «نقد» «صنعت فرهنگ» (فرانکفورت) و «مطالعات فرهنگی» (مقاومت مخاطب) دانست: «بازی» و «سرگرمی» هم «بازتولید» «ایدئولوژی» است و هم «مقاومت» مخاطب. کارل ویک (۱۹۷۹) در این چارچوب، «فرهنگ دیجیتال» را «میدان» «دیالکتیک» «صنعت» و «مخاطب» تعریف کرد.  ۲. ساختارهای مفهومی • بازی و فرهنگ (Play and Culture): «بازی» به‌عنوان «زبان» «نسل» دیجیتال: «معنا» در «بازی» ساخته می‌شود. • فرهنگ دیجیتال (Digital Culture): «بافت» «فرهنگی» «نسل» دیجیتال: «بازی»، «بازی»، «میم» و «ریپلای»، «زبان» این «بافت»‌اند.', '70e7980100a461aac7bc21c123dab63d1af3677e96fc0a2063b0cf55fdccf870', 1149, 'ch-doc-card-447-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='70e7980100a461aac7bc21c123dab63d1af3677e96fc0a2063b0cf55fdccf870', token_count=1149, vector_point_id='ch-doc-card-447-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-447-4', 'doc-card-447', 'sec-card-447-2', 4, 'فرهنگی» «نسل» دیجیتال: «بازی»، «بازی»، «میم» و «ریپلای»، «زبان» این «بافت»‌اند. • صنعت سرگرمی (Entertainment Industry): «صنعت» «تولید» «محتوای» سرگرمی: «سود»، «تکرار» و «استاندارد»، «منطق» «صنعت» است. • فرهنگ عامه دیجیتال (Digital Pop Culture): «فرهنگ» «عامه» در «بافت» دیجیتال: «محتوا» «مخاطب» «ساخته»، «زبان» «فرهنگ» است. • تعامل و مشارکت (Interaction and Participation): «مخاطب» در «بافت» دیجیتال «مشارکت» می‌کند: «بازی» و «بازی»، «مشار', 'bcc2eb512ca16cfc130747491c22607223d04cface1785327bf949636bd67c9e', 798, 'ch-doc-card-447-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bcc2eb512ca16cfc130747491c22607223d04cface1785327bf949636bd67c9e', token_count=798, vector_point_id='ch-doc-card-447-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
