INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-447-7', 'doc-card-447', 'sec-card-447-4', 7, 'کت» است. • مم (Meme): «واحد» «فرهنگی» که «تولید» و «تکرار» «اجتماعی» دارد: «میم»، «زبان» «فرهنگ» دیجیتال است. • بازی‌سازی (Gamification): «بازی» در «بافت» «غیربازی»: «رقابت»، «پاداش» و «نقش»، «رفتار» را «بازتولید» می‌کنند. • فرهنگ همگرا (Convergent Culture): «همگرایی» «محتوا»، «پلتفرم» و «مخاطب»: «مخاطب»، «محتوا» را «بازتولید» می‌کند.  ۳. نمونه‌های تحلیلی «بازی» در «فرهنگ» دیجیتال: «بازی‌های» «ویدیویی»، «بافت» «فرهنگی» «نسل» دیجیتال «ساخته»‌اند: «زبان»، «نماد» و «بازی» «بازی»، «زبان» «فرهنگ» است.  «میم» در عمل: «میم» «وایرال» «تولید» و «تکرار» «اجتماعی» دارد: «میم»، «زبان» «فرهنگ» دیجیتال است و «معنا» در «تکرار» ساخته می‌شود.', 'ff228051ec57355dbe193a089014351b2eea9903b91bf6a2fc50a2e917843244', 1150, 'ch-doc-card-447-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ff228051ec57355dbe193a089014351b2eea9903b91bf6a2fc50a2e917843244', token_count=1150, vector_point_id='ch-doc-card-447-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
