INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-447-12', 'doc-card-447', 'sec-card-447-6', 12, '۱. «بازی» و «استثمار»: «بازی» در «صنعت» «سرگرمی»، «کار» است: «مخاطب» «بازی» می‌کند و «صنعت» «سود» می‌برد: «استثمار» در «بازی» پنهان است. ۲. «میم» و «ایدئولوژی»: «میم» «مقاومت» است اما «بازتولید» «ایدئولوژی» هم: «طنز»، «نقد» نیست، «بازی» است. ۳. «فرهنگ دیجیتال» و «اعتیاد»: «مشارکت» «دیجیتال» می‌تواند «اعتیاد» باشد: «بازی» و «اعتیاد» مرز «کمرنگ» دارد. ۴. «صنعت سرگرمی» و «تنوع»: «صنعت» «استاندارد» می‌کند و «تنوع» را «محو» می‌کند: «سود»، «تنوع» را «حذف» می‌کند. ۵. «بازی‌سازی» و «انگیزه»: «بازی‌سازی» «رفتار» را «بازتولید» می‌کند اما «ا', '2e4941d52959e89db7bc7e9d3006bc9777ecfe2ae344d44bf4db263bfdfd463e', 974, 'ch-doc-card-447-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2e4941d52959e89db7bc7e9d3006bc9777ecfe2ae344d44bf4db263bfdfd463e', token_count=974, vector_point_id='ch-doc-card-447-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-447-13', 'doc-card-447', 'sec-card-447-7', 13, 'نگیزه» «داخلی» را «محو» می‌کند: «پاداش»، «بازی» را «کار» می‌کند. ۶. «فرهنگ همگرا» و «نظارت»: «مخاطب» «تولید» می‌کند و «صنعت» «بازتولید» می‌کند: «نظارت» بر «مخاطب»، «حاکمیت» است. ۷. «فرهنگ عامه دیجیتال» و «اعتبار»: «محتوای» «مخاطب» «ساخته»، «اعتبار» ندارد: «مرز» بین «حرفه‌ای» و «مخاطب»، «بازتعریف» لازم دارد. ۸. «بازی» و «واقعیت»: «بازی» در «بافت» دیجیتال، «واقعیت» است: «مرز» بین «بازی» و «واقعیت»، «محو» شده است. ۹. «فرهنگ دیجیتال» و «نسل»: «فرهنگ» دیجیتال، «نسل» است اما «همه» «نسل‌ها» در آن «حاضر»‌اند: «مرز» «نسل»، «کمرنگ» شده است.', '0b0c3f05ea135af8deed6fc16c6361ab3920d24bdf5ebb22d4b4a264efdf1ab2', 974, 'ch-doc-card-447-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0b0c3f05ea135af8deed6fc16c6361ab3920d24bdf5ebb22d4b4a264efdf1ab2', token_count=974, vector_point_id='ch-doc-card-447-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-447-14', 'doc-card-447', 'sec-card-447-10', 14, 'کتاب «فرهنگ همگرا» (جَنکینز، ۲۰۰۶)؛ کتاب «بازی و فرهنگ» (سوسا، ۱۹۵۵)؛ کتاب «صنعت فرهنگ» (آدورنو و هورکهایمر، ۱۹۴۴)؛ کتاب «فرهنگ دیجیتال» (منرو و همکاران، ۲۰۰۴).', '373e57c2c2351d10cec24f7b867cae52e67956b87e6039750582abd935eddb22', 290, 'ch-doc-card-447-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='373e57c2c2351d10cec24f7b867cae52e67956b87e6039750582abd935eddb22', token_count=290, vector_point_id='ch-doc-card-447-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-448-0', 'doc-card-448', NULL, 0, 'انگیختگی فیزیولوژیک برانگیخته‌شده از محرک رسانه‌ای (خشم، ترس یا هیجان) بلافاصله فرونمی‌نشیند؛ انرژی باقی‌مانده آن به محرک بعدی منتقل می‌شود و شدت پاسخ احساسی به آن را می‌افزاید. این سازوکار، لذت مخاطب از محتوای پرتنش را تبیین می‌کند.', '94437d7f0eecba2e38ee1e97eb59502eebb6cfad10d83625ce62a4368f777434', 423, 'ch-doc-card-448-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='94437d7f0eecba2e38ee1e97eb59502eebb6cfad10d83625ce62a4368f777434', token_count=423, vector_point_id='ch-doc-card-448-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-448-1', 'doc-card-448', 'sec-card-448-1', 1, 'بازی، سرگرمی و فرهنگ دیجیتال  انگیختگی فیزیولوژیک ناشی از یک محرک خشم، ترس یا هیجان اولیه رسانه‌ای بلافاصله از بین نمی‌رود، بلکه انرژی آن روی پاسخ احساسی به محرک بعدی انباشته و تخلیه می‌شود.', '744cd1aa374a3fc12573aa5f914a5737f685ee0daa6f2dfa687dbac68924189a', 345, 'ch-doc-card-448-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='744cd1aa374a3fc12573aa5f914a5737f685ee0daa6f2dfa687dbac68924189a', token_count=345, vector_point_id='ch-doc-card-448-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-448-2', 'doc-card-448', 'sec-card-448-2', 2, '۱. بنیان و منطق نظری نظریه انتقال انگیختگی «بازی» را «فعالیت» معنادار در «بافت» دیجیتال می‌داند: نه «فرار» از واقعیت بلکه «بازی» با «معنا». دولف زیلمان (۱۹۷۱) در این چارچوب، «فرهنگ» را نه «محصول» «صنعت» بلکه «فعالیت» مخاطب تعریف کرد: «بازی»، «زبان» «نسل» دیجیتال است.  بر اساس نظریه انتقال انگیختگی، «سرگرمی» «صنعت» است اما «فرهنگ» «فعالیت» مخاطب است: «صنعت» «محتوا» تولید می‌کند و «مخاطب» «معنا» بازتولید می‌کند. دولف زیلمان (۱۹۷۱) در این چارچوب، «فرهنگ دیجیتال» را «فضا» «تولید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.', 'd76d31e5b96f312c0c097a29829da72dd0db25791b9687fa1d14e88d60da7ee1', 1009, 'ch-doc-card-448-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d76d31e5b96f312c0c097a29829da72dd0db25791b9687fa1d14e88d60da7ee1', token_count=1009, vector_point_id='ch-doc-card-448-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-448-3', 'doc-card-448', 'sec-card-448-2', 3, 'ید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  نظریه انتقال انگیختگی را می‌توان پاسخی به شکاف میان «نقد» «صنعت فرهنگ» (فرانکفورت) و «مطالعات فرهنگی» (مقاومت مخاطب) دانست: «بازی» و «سرگرمی» هم «بازتولید» «ایدئولوژی» است و هم «مقاومت» مخاطب. دولف زیلمان (۱۹۷۱) در این چارچوب، «فرهنگ دیجیتال» را «میدان» «دیالکتیک» «صنعت» و «مخاطب» تعریف کرد.  ۲. ساختارهای مفهومی • بازی و فرهنگ (Play and Culture): «بازی» به‌عنوان «زبان» «نسل» دیجیتال: «معنا» در «بازی» ساخته می‌شود. • فرهنگ دیجیتال (Digital Culture): «بافت» «فرهنگی» «نسل» دیجیتال: «بازی»، «بازی»، «میم» و «ریپلای»، «زبان» این «بافت»‌اند.', 'b9c510d9ad0de3c7791e266829d5595f31c18816654db117a29ae79afe2cb8a2', 1127, 'ch-doc-card-448-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b9c510d9ad0de3c7791e266829d5595f31c18816654db117a29ae79afe2cb8a2', token_count=1127, vector_point_id='ch-doc-card-448-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-448-4', 'doc-card-448', 'sec-card-448-2', 4, 'فرهنگی» «نسل» دیجیتال: «بازی»، «بازی»، «میم» و «ریپلای»، «زبان» این «بافت»‌اند. • صنعت سرگرمی (Entertainment Industry): «صنعت» «تولید» «محتوای» سرگرمی: «سود»، «تکرار» و «استاندارد»، «منطق» «صنعت» است. • فرهنگ عامه دیجیتال (Digital Pop Culture): «فرهنگ» «عامه» در «بافت» دیجیتال: «محتوا» «مخاطب» «ساخته»، «زبان» «فرهنگ» است. • تعامل و مشارکت (Interaction and Participation): «مخاطب» در «بافت» دیجیتال «مشارکت» می‌کند: «بازی» و «بازی»، «مشارکت» است. • مم (Meme', 'e2e5284193ad21b928a611a2fbfd9da3728fc7c2a0e5df5e3d50a5d6a1e022b3', 832, 'ch-doc-card-448-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e2e5284193ad21b928a611a2fbfd9da3728fc7c2a0e5df5e3d50a5d6a1e022b3', token_count=832, vector_point_id='ch-doc-card-448-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-448-5', 'doc-card-448', 'sec-card-448-3', 5, '• بازی و فرهنگ (Play and Culture): «بازی» به‌عنوان «زبان» «نسل» دیجیتال: «معنا» در «بازی» ساخته می‌شود. • فرهنگ دیجیتال (Digital Culture): «بافت» «فرهنگی» «نسل» دیجیتال: «بازی»، «بازی»، «میم» و «ریپلای»، «زبان» این «بافت»‌اند. • صنعت سرگرمی (Entertainment Industry): «صنعت» «تولید» «محتوای» سرگرمی: «سود»، «تکرار» و «استاندارد»، «منطق» «صنعت» است. • فرهنگ عامه دیجیتال (Digital Pop Culture): «فرهنگ» «عامه» در «بافت» دیجیتال: «محتوا» «مخاطب» «ساخته»، «زبان» «فرهنگ» است. • تعامل و مشارکت (Interaction and Participation): «مخاطب» در «بافت» دیجیتال «مشارکت» می‌کند: «بازی» و «بازی»، «مشارکت» است.', '3568aba6d13f485a22c8484a9dc926175664929f5d61008ea007723802e07e96', 1080, 'ch-doc-card-448-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3568aba6d13f485a22c8484a9dc926175664929f5d61008ea007723802e07e96', token_count=1080, vector_point_id='ch-doc-card-448-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-448-6', 'doc-card-448', 'sec-card-448-3', 6, 'ion): «مخاطب» در «بافت» دیجیتال «مشارکت» می‌کند: «بازی» و «بازی»، «مشارکت» است. • مم (Meme): «واحد» «فرهنگی» که «تولید» و «تکرار» «اجتماعی» دارد: «میم»، «زبان» «فرهنگ» دیجیتال است. • بازی‌سازی (Gamification): «بازی» در «بافت» «غیربازی»: «رقابت»، «پاداش» و «نقش»، «رفتار» را «بازتولید» می‌کنند. • فرهنگ همگرا (Convergent Culture): «همگرایی» «محتوا»، «پلتفرم» و «مخاطب»: «مخاطب»، «محتوا» را «بازتولید» می‌کند.', '79600879f394647bd0c6ffef7dc41a0d3d538c41b1e8a58f2ad128ade359a45b', 739, 'ch-doc-card-448-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='79600879f394647bd0c6ffef7dc41a0d3d538c41b1e8a58f2ad128ade359a45b', token_count=739, vector_point_id='ch-doc-card-448-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-448-7', 'doc-card-448', 'sec-card-448-4', 7, '): «واحد» «فرهنگی» که «تولید» و «تکرار» «اجتماعی» دارد: «میم»، «زبان» «فرهنگ» دیجیتال است. • بازی‌سازی (Gamification): «بازی» در «بافت» «غیربازی»: «رقابت»، «پاداش» و «نقش»، «رفتار» را «بازتولید» می‌کنند. • فرهنگ همگرا (Convergent Culture): «همگرایی» «محتوا»، «پلتفرم» و «مخاطب»: «مخاطب»، «محتوا» را «بازتولید» می‌کند.  ۳. نمونه‌های تحلیلی «بازی» در «فرهنگ» دیجیتال: «بازی‌های» «ویدیویی»، «بافت» «فرهنگی» «نسل» دیجیتال «ساخته»‌اند: «زبان»، «نماد» و «بازی» «بازی»، «زبان» «فرهنگ» است.  «میم» در عمل: «میم» «وایرال» «تولید» و «تکرار» «اجتماعی» دارد: «میم»، «زبان» «فرهنگ» دیجیتال است و «معنا» در «تکرار» ساخته می‌شود.', '2fffd79b80e59fc323af907b9d17e8616fd722a9b4784e90583f090ee717f143', 1116, 'ch-doc-card-448-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2fffd79b80e59fc323af907b9d17e8616fd722a9b4784e90583f090ee717f143', token_count=1116, vector_point_id='ch-doc-card-448-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-448-8', 'doc-card-448', 'sec-card-448-4', 8, 'اعی» دارد: «میم»، «زبان» «فرهنگ» دیجیتال است و «معنا» در «تکرار» ساخته می‌شود.  «صنعت سرگرمی» در «عصر دیجیتال»: «پلتفرم‌های» استریمینگ «محتوا» را «استاندارد» می‌کنند: «سود»، «تکرار» و «استاندارد»، «منطق» «صنعت» است.  «فرهنگ همگرا» در عمل: «مخاطب» «سریال» «محتوا» «بازتولید» می‌کند (ریپلای، مم، کاسپلی): «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  «بازی‌سازی» در «آموزش»: «بازی» در «بافت» «آموزش» (پاداش، نقش، رقابت) «رفتار» را «بازتولید» می‌کند: «بازی»، «ابزار» «رفتار» است.  «فرهنگ عامه دیجیتال» در عمل: «محتوای» «مخاطب» «ساخته» (ویدیو، مم، پادکست) «زبان» «فرهنگ» است: «مخاطب»، «تولیدکننده» «فرهنگ» است.  ۴. نقدها و چالش‌ها ۱.', '03da41571ec881f8dd1edc161fa020f1225fcc95e29ee7212ee2e7fcab523fef', 1174, 'ch-doc-card-448-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='03da41571ec881f8dd1edc161fa020f1225fcc95e29ee7212ee2e7fcab523fef', token_count=1174, vector_point_id='ch-doc-card-448-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-448-9', 'doc-card-448', 'sec-card-448-4', 9, ') «زبان» «فرهنگ» است: «مخاطب»، «تولیدکننده» «فرهنگ» است.  ۴. نقدها و چالش‌ها ۱. «بازی» و «استثمار»: «بازی» در «صنعت» «سرگرمی»، «کار» است: «مخاطب» «بازی» می‌کند و «صنعت» «سود» می‌برد: «استثمار» در «بازی» پنهان است. ۲. «میم» و «ایدئولوژی»: «میم» «مقاومت» است اما «بازتولید» «ایدئولوژی» هم: «طنز»، «نقد» نیست، «بازی» است. ۳. «فرهنگ دیجیتال» و «اعتیاد»: «مشارکت» «دیجیتال» می‌تو', 'c9b7a2b98b29d4d964e15158080b78477703ab406e528160b7f98c21902613fd', 680, 'ch-doc-card-448-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c9b7a2b98b29d4d964e15158080b78477703ab406e528160b7f98c21902613fd', token_count=680, vector_point_id='ch-doc-card-448-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
