INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-452-0', 'doc-card-452', NULL, 0, 'لذت مخاطب از تماشای درام، مشروط به برقراری «عدالت خلقی» است: شخصیت نیکوکار باید پاداش بگیرد و شخصیت شرور یا ضدقهرمان، مجازات شود. نقض همین انتظار، تجربهٔ تماشایی مخاطب را خدشه‌دار می‌کند.', '660ce7026660d68c3398868ea6f7b6367a7fd562e4f72b4df79cd88d08bbe967', 340, 'ch-doc-card-452-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='660ce7026660d68c3398868ea6f7b6367a7fd562e4f72b4df79cd88d08bbe967', token_count=340, vector_point_id='ch-doc-card-452-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-452-1', 'doc-card-452', 'sec-card-452-1', 1, 'بازی، سرگرمی و فرهنگ دیجیتال  لذت مخاطب از تماشای فیلم یا درام مشروط بر آن است که به شخصیت مثبت پاداش داده شود و شخصیت شرور و ضدقهرمان با مجازات روبرو گردد.', 'bc486773ddd5081483da6661c8c3ccb301d15ce846f8bcd9786b0fb301f5222a', 283, 'ch-doc-card-452-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bc486773ddd5081483da6661c8c3ccb301d15ce846f8bcd9786b0fb301f5222a', token_count=283, vector_point_id='ch-doc-card-452-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-452-2', 'doc-card-452', 'sec-card-452-2', 2, '۱. بنیان و منطق نظری نظریه تمایلات خلقی-دراماتیک «بازی» را «فعالیت» معنادار در «بافت» دیجیتال می‌داند: نه «فرار» از واقعیت بلکه «بازی» با «معنا». دولف زیلمان (۱۹۷۶) در این چارچوب، «فرهنگ» را نه «محصول» «صنعت» بلکه «فعالیت» مخاطب تعریف کرد: «بازی»، «زبان» «نسل» دیجیتال است.  بر اساس نظریه تمایلات خلقی-دراماتیک، «سرگرمی» «صنعت» است اما «فرهنگ» «فعالیت» مخاطب است: «صنعت» «محتوا» تولید می‌کند و «مخاطب» «معنا» بازتولید می‌کند. دولف زیلمان (۱۹۷۶) در این چارچوب، «فرهنگ دیجیتال» را «فضا» «تولید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.', '246fcfea6396e797425f470819e5471b39e39a9479291ae816c28df6e82c6cf0', 1030, 'ch-doc-card-452-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='246fcfea6396e797425f470819e5471b39e39a9479291ae816c28df6e82c6cf0', token_count=1030, vector_point_id='ch-doc-card-452-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-452-3', 'doc-card-452', 'sec-card-452-2', 3, 'ید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  نظریه تمایلات خلقی-دراماتیک را می‌توان پاسخی به شکاف میان «نقد» «صنعت فرهنگ» (فرانکفورت) و «مطالعات فرهنگی» (مقاومت مخاطب) دانست: «بازی» و «سرگرمی» هم «بازتولید» «ایدئولوژی» است و هم «مقاومت» مخاطب. دولف زیلمان (۱۹۷۶) در این چارچوب، «فرهنگ دیجیتال» را «میدان» «دیالکتیک» «صنعت» و «مخاطب» تعریف کرد.  ۲. ساختارهای مفهومی • بازی و فرهنگ (Play and Culture): «بازی» به‌عنوان «زبان» «نسل» دیجیتال: «معنا» در «بازی» ساخته می‌شود. • فرهنگ دیجیتال (Digital Culture): «بافت» «فرهنگی» «نسل» دیجیتال: «بازی»، «بازی»، «میم» و «ریپلای»، «زبان» این «بافت»‌اند.', '98c3550223e8457a7279607d137ca308b85c8e621737b20ae9e24566bd5ffb56', 1138, 'ch-doc-card-452-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='98c3550223e8457a7279607d137ca308b85c8e621737b20ae9e24566bd5ffb56', token_count=1138, vector_point_id='ch-doc-card-452-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
