INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-452-13', 'doc-card-452', 'sec-card-452-7', 13, 'نگیزه» «داخلی» را «محو» می‌کند: «پاداش»، «بازی» را «کار» می‌کند. ۶. «فرهنگ همگرا» و «نظارت»: «مخاطب» «تولید» می‌کند و «صنعت» «بازتولید» می‌کند: «نظارت» بر «مخاطب»، «حاکمیت» است. ۷. «فرهنگ عامه دیجیتال» و «اعتبار»: «محتوای» «مخاطب» «ساخته»، «اعتبار» ندارد: «مرز» بین «حرفه‌ای» و «مخاطب»، «بازتعریف» لازم دارد. ۸. «بازی» و «واقعیت»: «بازی» در «بافت» دیجیتال، «واقعیت» است: «مرز» بین «بازی» و «واقعیت»، «محو» شده است. ۹. «فرهنگ دیجیتال» و «نسل»: «فرهنگ» دیجیتال، «نسل» است اما «همه» «نسل‌ها» در آن «حاضر»‌اند: «مرز» «نسل»، «کمرنگ» شده است.', '0b0c3f05ea135af8deed6fc16c6361ab3920d24bdf5ebb22d4b4a264efdf1ab2', 974, 'ch-doc-card-452-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0b0c3f05ea135af8deed6fc16c6361ab3920d24bdf5ebb22d4b4a264efdf1ab2', token_count=974, vector_point_id='ch-doc-card-452-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-452-14', 'doc-card-452', 'sec-card-452-10', 14, 'کتاب «فرهنگ همگرا» (جَنکینز، ۲۰۰۶)؛ کتاب «بازی و فرهنگ» (سوسا، ۱۹۵۵)؛ کتاب «صنعت فرهنگ» (آدورنو و هورکهایمر، ۱۹۴۴)؛ کتاب «فرهنگ دیجیتال» (منرو و همکاران، ۲۰۰۴).', '373e57c2c2351d10cec24f7b867cae52e67956b87e6039750582abd935eddb22', 290, 'ch-doc-card-452-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='373e57c2c2351d10cec24f7b867cae52e67956b87e6039750582abd935eddb22', token_count=290, vector_point_id='ch-doc-card-452-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-453-0', 'doc-card-453', NULL, 0, 'تلاقی مصرف رسانه‌ای در عصر دیجیتال: رسانه‌های قدیم و جدید، محتوای شرکتی و مردمی و انواع کانال در هم می‌آمیزند. محتوا چندبستری میان پلتفرم‌ها سفر می‌کند و مخاطب با مشارکت در معناسازی، بازتولیدکنندهٔ آن می‌شود.', '1e68bfe06664297fa1fe760d265c31e71d94e65cbeb9c571de125456ecefe617', 378, 'ch-doc-card-453-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1e68bfe06664297fa1fe760d265c31e71d94e65cbeb9c571de125456ecefe617', token_count=378, vector_point_id='ch-doc-card-453-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-453-1', 'doc-card-453', 'sec-card-453-1', 1, 'بازی، سرگرمی و فرهنگ دیجیتال  تلاقی مصرف رسانه‌ای؛ جایی که رسانه‌های قدیم و جدید به هم پیوند می‌خورند، رسانه‌های شرکتی و مردمی تلاقی می‌کنند و محتوا به شکلی چندبستری در میان انواع کانال‌ها سفر می‌کند.', '607cd83b23a985a7707c49d5c213efff4580c451ccf580d9612d0c1ae76d15e7', 363, 'ch-doc-card-453-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='607cd83b23a985a7707c49d5c213efff4580c451ccf580d9612d0c1ae76d15e7', token_count=363, vector_point_id='ch-doc-card-453-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-453-2', 'doc-card-453', 'sec-card-453-2', 2, '۱. بنیان و منطق نظری فرهنگ همگرایی «بازی» را «فعالیت» معنادار در «بافت» دیجیتال می‌داند: نه «فرار» از واقعیت بلکه «بازی» با «معنا». هنری جنکینز (۲۰۰۶) در این چارچوب، «فرهنگ» را نه «محصول» «صنعت» بلکه «فعالیت» مخاطب تعریف کرد: «بازی»، «زبان» «نسل» دیجیتال است.  بر اساس فرهنگ همگرایی، «سرگرمی» «صنعت» است اما «فرهنگ» «فعالیت» مخاطب است: «صنعت» «محتوا» تولید می‌کند و «مخاطب» «معنا» بازتولید می‌کند. هنری جنکینز (۲۰۰۶) در این چارچوب، «فرهنگ دیجیتال» را «فضا» «تولید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.', '1fd786ad519fbde0e96a059c90182c903efe93791727daafad02046cd8b3f4f7', 979, 'ch-doc-card-453-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1fd786ad519fbde0e96a059c90182c903efe93791727daafad02046cd8b3f4f7', token_count=979, vector_point_id='ch-doc-card-453-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-453-3', 'doc-card-453', 'sec-card-453-2', 3, 'ید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  فرهنگ همگرایی را می‌توان پاسخی به شکاف میان «نقد» «صنعت فرهنگ» (فرانکفورت) و «مطالعات فرهنگی» (مقاومت مخاطب) دانست: «بازی» و «سرگرمی» هم «بازتولید» «ایدئولوژی» است و هم «مقاومت» مخاطب. هنری جنکینز (۲۰۰۶) در این چارچوب، «فرهنگ دیجیتال» را «میدان» «دیالکتیک» «صنعت» و «مخاطب» تعریف کرد.  ۲. ساختارهای مفهومی • بازی و فرهنگ (Play and Culture): «بازی» به‌عنوان «زبان» «نسل» دیجیتال: «معنا» در «بازی» ساخته می‌شود. • فرهنگ دیجیتال (Digital Culture): «بافت» «فرهنگی» «نسل» دیجیتال: «بازی»، «بازی»، «میم» و «ریپلای»، «زبان» این «بافت»‌اند.', '654b73b9d2c1bafbcc77843865c044f133dd7db216095310e47099b8e6c8b0c8', 1112, 'ch-doc-card-453-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='654b73b9d2c1bafbcc77843865c044f133dd7db216095310e47099b8e6c8b0c8', token_count=1112, vector_point_id='ch-doc-card-453-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
