INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-453-10', 'doc-card-453', 'sec-card-453-5', 10, '«بازی» در «فرهنگ» دیجیتال: «بازی‌های» «ویدیویی»، «بافت» «فرهنگی» «نسل» دیجیتال «ساخته»‌اند: «زبان»، «نماد» و «بازی» «بازی»، «زبان» «فرهنگ» است.  «میم» در عمل: «میم» «وایرال» «تولید» و «تکرار» «اجتماعی» دارد: «میم»، «زبان» «فرهنگ» دیجیتال است و «معنا» در «تکرار» ساخته می‌شود.  «صنعت سرگرمی» در «عصر دیجیتال»: «پلتفرم‌های» استریمینگ «محتوا» را «استاندارد» می‌کنند: «سود»، «تکرار» و «استاندارد»، «منطق» «صنعت» است.  «فرهنگ همگرا» در عمل: «مخاطب» «سریال» «محتوا» «بازتولید» می‌کند (ریپلای، مم، کاسپلی): «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.', 'a9931917823f99e9f8ac7f33f2911c5aa9fdb2368cefdde2b8c38d4cc298153e', 1019, 'ch-doc-card-453-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a9931917823f99e9f8ac7f33f2911c5aa9fdb2368cefdde2b8c38d4cc298153e', token_count=1019, vector_point_id='ch-doc-card-453-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-453-11', 'doc-card-453', 'sec-card-453-5', 11, 'ای، مم، کاسپلی): «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  «بازی‌سازی» در «آموزش»: «بازی» در «بافت» «آموزش» (پاداش، نقش، رقابت) «رفتار» را «بازتولید» می‌کند: «بازی»، «ابزار» «رفتار» است.  «فرهنگ عامه دیجیتال» در عمل: «محتوای» «مخاطب» «ساخته» (ویدیو، مم، پادکست) «زبان» «فرهنگ» است: «مخاطب»، «تولیدکننده» «فرهنگ» است.', 'e2641dc1819daaca840a57098fa60cd466dc20ba934bb2ffe6eeb8441b790705', 612, 'ch-doc-card-453-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e2641dc1819daaca840a57098fa60cd466dc20ba934bb2ffe6eeb8441b790705', token_count=612, vector_point_id='ch-doc-card-453-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-453-12', 'doc-card-453', 'sec-card-453-6', 12, '۱. «بازی» و «استثمار»: «بازی» در «صنعت» «سرگرمی»، «کار» است: «مخاطب» «بازی» می‌کند و «صنعت» «سود» می‌برد: «استثمار» در «بازی» پنهان است. ۲. «میم» و «ایدئولوژی»: «میم» «مقاومت» است اما «بازتولید» «ایدئولوژی» هم: «طنز»، «نقد» نیست، «بازی» است. ۳. «فرهنگ دیجیتال» و «اعتیاد»: «مشارکت» «دیجیتال» می‌تواند «اعتیاد» باشد: «بازی» و «اعتیاد» مرز «کمرنگ» دارد. ۴. «صنعت سرگرمی» و «تنوع»: «صنعت» «استاندارد» می‌کند و «تنوع» را «محو» می‌کند: «سود»، «تنوع» را «حذف» می‌کند. ۵. «بازی‌سازی» و «انگیزه»: «بازی‌سازی» «رفتار» را «بازتولید» می‌کند اما «ا', '2e4941d52959e89db7bc7e9d3006bc9777ecfe2ae344d44bf4db263bfdfd463e', 974, 'ch-doc-card-453-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2e4941d52959e89db7bc7e9d3006bc9777ecfe2ae344d44bf4db263bfdfd463e', token_count=974, vector_point_id='ch-doc-card-453-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-453-13', 'doc-card-453', 'sec-card-453-7', 13, 'نگیزه» «داخلی» را «محو» می‌کند: «پاداش»، «بازی» را «کار» می‌کند. ۶. «فرهنگ همگرا» و «نظارت»: «مخاطب» «تولید» می‌کند و «صنعت» «بازتولید» می‌کند: «نظارت» بر «مخاطب»، «حاکمیت» است. ۷. «فرهنگ عامه دیجیتال» و «اعتبار»: «محتوای» «مخاطب» «ساخته»، «اعتبار» ندارد: «مرز» بین «حرفه‌ای» و «مخاطب»، «بازتعریف» لازم دارد. ۸. «بازی» و «واقعیت»: «بازی» در «بافت» دیجیتال، «واقعیت» است: «مرز» بین «بازی» و «واقعیت»، «محو» شده است. ۹. «فرهنگ دیجیتال» و «نسل»: «فرهنگ» دیجیتال، «نسل» است اما «همه» «نسل‌ها» در آن «حاضر»‌اند: «مرز» «نسل»، «کمرنگ» شده است.', '0b0c3f05ea135af8deed6fc16c6361ab3920d24bdf5ebb22d4b4a264efdf1ab2', 974, 'ch-doc-card-453-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0b0c3f05ea135af8deed6fc16c6361ab3920d24bdf5ebb22d4b4a264efdf1ab2', token_count=974, vector_point_id='ch-doc-card-453-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-453-14', 'doc-card-453', 'sec-card-453-10', 14, 'کتاب «فرهنگ همگرا» (جَنکینز، ۲۰۰۶)؛ کتاب «بازی و فرهنگ» (سوسا، ۱۹۵۵)؛ کتاب «صنعت فرهنگ» (آدورنو و هورکهایمر، ۱۹۴۴)؛ کتاب «فرهنگ دیجیتال» (منرو و همکاران، ۲۰۰۴).', '373e57c2c2351d10cec24f7b867cae52e67956b87e6039750582abd935eddb22', 290, 'ch-doc-card-453-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='373e57c2c2351d10cec24f7b867cae52e67956b87e6039750582abd935eddb22', token_count=290, vector_point_id='ch-doc-card-453-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-454-0', 'doc-card-454', NULL, 0, '«پخش‌پذیری» (broadcastability) جایگزین استعارهٔ منفعلِ «ویروسی شدن» است: مخاطبان محتوا را آگاهانه و برای معنادهی بازنشر می‌کنند. این مفهوم، عاملیت مخاطب را در شبکه‌ها تأکید و پدیده را از پخش تصادفی به عمل ارتباطی آگاهانه بدل می‌کند.', 'c58b0ecf2b7cd88160a05f5b1882198133492de36daa8a8d2910e94ff88764a0', 421, 'ch-doc-card-454-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c58b0ecf2b7cd88160a05f5b1882198133492de36daa8a8d2910e94ff88764a0', token_count=421, vector_point_id='ch-doc-card-454-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-454-1', 'doc-card-454', 'sec-card-454-1', 1, 'بازی، سرگرمی و فرهنگ دیجیتال  جایگزینی استعاره مهندسی و منفعل «ویروسی شدن محتوا» با مفهوم «پخش‌پذیری»؛ مخاطبان محتواها را آگاهانه، با هدف معنادهی و تولید ارتباط بازنشر و تغییر شکل می‌دهند.', '1c97538cf945997cb0067b12a501aa963141f163cbe54206270d84c63f954590', 341, 'ch-doc-card-454-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1c97538cf945997cb0067b12a501aa963141f163cbe54206270d84c63f954590', token_count=341, vector_point_id='ch-doc-card-454-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-454-2', 'doc-card-454', 'sec-card-454-2', 2, '۱. بنیان و منطق نظری رسانه‌های پخش‌پذیر «بازی» را «فعالیت» معنادار در «بافت» دیجیتال می‌داند: نه «فرار» از واقعیت بلکه «بازی» با «معنا». هنری جنکینز (۲۰۱۳) در این چارچوب، «فرهنگ» را نه «محصول» «صنعت» بلکه «فعالیت» مخاطب تعریف کرد: «بازی»، «زبان» «نسل» دیجیتال است.  بر اساس رسانه‌های پخش‌پذیر، «سرگرمی» «صنعت» است اما «فرهنگ» «فعالیت» مخاطب است: «صنعت» «محتوا» تولید می‌کند و «مخاطب» «معنا» بازتولید می‌کند. هنری جنکینز (۲۰۱۳) در این چارچوب، «فرهنگ دیجیتال» را «فضا» «تولید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.', 'c680e5981ce44bccc6ee09e211b0fe127a2190b3f18a7913e16e3b1545641cdd', 998, 'ch-doc-card-454-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c680e5981ce44bccc6ee09e211b0fe127a2190b3f18a7913e16e3b1545641cdd', token_count=998, vector_point_id='ch-doc-card-454-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-454-3', 'doc-card-454', 'sec-card-454-2', 3, 'ید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  رسانه‌های پخش‌پذیر را می‌توان پاسخی به شکاف میان «نقد» «صنعت فرهنگ» (فرانکفورت) و «مطالعات فرهنگی» (مقاومت مخاطب) دانست: «بازی» و «سرگرمی» هم «بازتولید» «ایدئولوژی» است و هم «مقاومت» مخاطب. هنری جنکینز (۲۰۱۳) در این چارچوب، «فرهنگ دیجیتال» را «میدان» «دیالکتیک» «صنعت» و «مخاطب» تعریف کرد.  ۲. ساختارهای مفهومی • بازی و فرهنگ (Play and Culture): «بازی» به‌عنوان «زبان» «نسل» دیجیتال: «معنا» در «بازی» ساخته می‌شود. • فرهنگ دیجیتال (Digital Culture): «بافت» «فرهنگی» «نسل» دیجیتال: «بازی»، «بازی»، «میم» و «ریپلای»، «زبان» این «بافت»‌اند.', '71600fc7a0c8477479284a4863887871cd340a61c86ad3e6124a4eb224d53af9', 1121, 'ch-doc-card-454-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='71600fc7a0c8477479284a4863887871cd340a61c86ad3e6124a4eb224d53af9', token_count=1121, vector_point_id='ch-doc-card-454-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-454-4', 'doc-card-454', 'sec-card-454-2', 4, 'فرهنگی» «نسل» دیجیتال: «بازی»، «بازی»، «میم» و «ریپلای»، «زبان» این «بافت»‌اند. • صنعت سرگرمی (Entertainment Industry): «صنعت» «تولید» «محتوای» سرگرمی: «سود»، «تکرار» و «استاندارد»، «منطق» «صنعت» است. • فرهنگ عامه دیجیتال (Digital Pop Culture): «فرهنگ» «عامه» در «بافت» دیجیتال: «محتوا» «مخاطب» «ساخته»، «زبان» «فرهنگ» است. • تعامل و مشارکت (Interaction and Participation): «مخاطب» در «بافت» دیجیتال «مشارکت» می‌کند: «بازی» و «بازی»، «مشارکت» است. • مم (Meme): «و', '1f64bce7afa1f21b4d0fe89ac345056f215925161c44d401dd06b5a1b9d57eef', 841, 'ch-doc-card-454-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1f64bce7afa1f21b4d0fe89ac345056f215925161c44d401dd06b5a1b9d57eef', token_count=841, vector_point_id='ch-doc-card-454-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-454-5', 'doc-card-454', 'sec-card-454-3', 5, '• بازی و فرهنگ (Play and Culture): «بازی» به‌عنوان «زبان» «نسل» دیجیتال: «معنا» در «بازی» ساخته می‌شود. • فرهنگ دیجیتال (Digital Culture): «بافت» «فرهنگی» «نسل» دیجیتال: «بازی»، «بازی»، «میم» و «ریپلای»، «زبان» این «بافت»‌اند. • صنعت سرگرمی (Entertainment Industry): «صنعت» «تولید» «محتوای» سرگرمی: «سود»، «تکرار» و «استاندارد»، «منطق» «صنعت» است. • فرهنگ عامه دیجیتال (Digital Pop Culture): «فرهنگ» «عامه» در «بافت» دیجیتال: «محتوا» «مخاطب» «ساخته»، «زبان» «فرهنگ» است. • تعامل و مشارکت (Interaction and Participation): «مخاطب» در «بافت» دیجیتال «مشارکت» می‌کند: «بازی» و «بازی»، «مشارکت» است.', '3568aba6d13f485a22c8484a9dc926175664929f5d61008ea007723802e07e96', 1080, 'ch-doc-card-454-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3568aba6d13f485a22c8484a9dc926175664929f5d61008ea007723802e07e96', token_count=1080, vector_point_id='ch-doc-card-454-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-454-6', 'doc-card-454', 'sec-card-454-3', 6, 'ion): «مخاطب» در «بافت» دیجیتال «مشارکت» می‌کند: «بازی» و «بازی»، «مشارکت» است. • مم (Meme): «واحد» «فرهنگی» که «تولید» و «تکرار» «اجتماعی» دارد: «میم»، «زبان» «فرهنگ» دیجیتال است. • بازی‌سازی (Gamification): «بازی» در «بافت» «غیربازی»: «رقابت»، «پاداش» و «نقش»، «رفتار» را «بازتولید» می‌کنند. • فرهنگ همگرا (Convergent Culture): «همگرایی» «محتوا»، «پلتفرم» و «مخاطب»: «مخاطب»، «محتوا» را «بازتولید» می‌کند.', '79600879f394647bd0c6ffef7dc41a0d3d538c41b1e8a58f2ad128ade359a45b', 739, 'ch-doc-card-454-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='79600879f394647bd0c6ffef7dc41a0d3d538c41b1e8a58f2ad128ade359a45b', token_count=739, vector_point_id='ch-doc-card-454-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-454-7', 'doc-card-454', 'sec-card-454-4', 7, 'احد» «فرهنگی» که «تولید» و «تکرار» «اجتماعی» دارد: «میم»، «زبان» «فرهنگ» دیجیتال است. • بازی‌سازی (Gamification): «بازی» در «بافت» «غیربازی»: «رقابت»، «پاداش» و «نقش»، «رفتار» را «بازتولید» می‌کنند. • فرهنگ همگرا (Convergent Culture): «همگرایی» «محتوا»، «پلتفرم» و «مخاطب»: «مخاطب»، «محتوا» را «بازتولید» می‌کند.  ۳. نمونه‌های تحلیلی «بازی» در «فرهنگ» دیجیتال: «بازی‌های» «ویدیویی»، «بافت» «فرهنگی» «نسل» دیجیتال «ساخته»‌اند: «زبان»، «نماد» و «بازی» «بازی»، «زبان» «فرهنگ» است.  «میم» در عمل: «میم» «وایرال» «تولید» و «تکرار» «اجتماعی» دارد: «میم»، «زبان» «فرهنگ» دیجیتال است و «معنا» در «تکرار» ساخته می‌شود.', 'e604488105fcaf7d7de008fc00096aaf07bce11f3049926e9006e0475357d2a5', 1107, 'ch-doc-card-454-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e604488105fcaf7d7de008fc00096aaf07bce11f3049926e9006e0475357d2a5', token_count=1107, vector_point_id='ch-doc-card-454-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-454-8', 'doc-card-454', 'sec-card-454-4', 8, 'اعی» دارد: «میم»، «زبان» «فرهنگ» دیجیتال است و «معنا» در «تکرار» ساخته می‌شود.  «صنعت سرگرمی» در «عصر دیجیتال»: «پلتفرم‌های» استریمینگ «محتوا» را «استاندارد» می‌کنند: «سود»، «تکرار» و «استاندارد»، «منطق» «صنعت» است.  «فرهنگ همگرا» در عمل: «مخاطب» «سریال» «محتوا» «بازتولید» می‌کند (ریپلای، مم، کاسپلی): «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  «بازی‌سازی» در «آموزش»: «بازی» در «بافت» «آموزش» (پاداش، نقش، رقابت) «رفتار» را «بازتولید» می‌کند: «بازی»، «ابزار» «رفتار» است.  «فرهنگ عامه دیجیتال» در عمل: «محتوای» «مخاطب» «ساخته» (ویدیو، مم، پادکست) «زبان» «فرهنگ» است: «مخاطب»، «تولیدکننده» «فرهنگ» است.  ۴. نقدها و چالش‌ها ۱.', '03da41571ec881f8dd1edc161fa020f1225fcc95e29ee7212ee2e7fcab523fef', 1174, 'ch-doc-card-454-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='03da41571ec881f8dd1edc161fa020f1225fcc95e29ee7212ee2e7fcab523fef', token_count=1174, vector_point_id='ch-doc-card-454-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-454-9', 'doc-card-454', 'sec-card-454-4', 9, ') «زبان» «فرهنگ» است: «مخاطب»، «تولیدکننده» «فرهنگ» است.  ۴. نقدها و چالش‌ها ۱. «بازی» و «استثمار»: «بازی» در «صنعت» «سرگرمی»، «کار» است: «مخاطب» «بازی» می‌کند و «صنعت» «سود» می‌برد: «استثمار» در «بازی» پنهان است. ۲. «میم» و «ایدئولوژی»: «میم» «مقاومت» است اما «بازتولید» «ایدئولوژی» هم: «طنز»، «نقد» نیست، «بازی» است. ۳. «فرهنگ دیجیتال» و «اعتیاد»: «مشارکت» «دیجیتال» می‌توا', '226aed6af5feedf2e58a947dc368090bfaed7268a809799a9ac68dd4a43088a3', 681, 'ch-doc-card-454-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='226aed6af5feedf2e58a947dc368090bfaed7268a809799a9ac68dd4a43088a3', token_count=681, vector_point_id='ch-doc-card-454-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
