INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-454-12', 'doc-card-454', 'sec-card-454-6', 12, '۱. «بازی» و «استثمار»: «بازی» در «صنعت» «سرگرمی»، «کار» است: «مخاطب» «بازی» می‌کند و «صنعت» «سود» می‌برد: «استثمار» در «بازی» پنهان است. ۲. «میم» و «ایدئولوژی»: «میم» «مقاومت» است اما «بازتولید» «ایدئولوژی» هم: «طنز»، «نقد» نیست، «بازی» است. ۳. «فرهنگ دیجیتال» و «اعتیاد»: «مشارکت» «دیجیتال» می‌تواند «اعتیاد» باشد: «بازی» و «اعتیاد» مرز «کمرنگ» دارد. ۴. «صنعت سرگرمی» و «تنوع»: «صنعت» «استاندارد» می‌کند و «تنوع» را «محو» می‌کند: «سود»، «تنوع» را «حذف» می‌کند. ۵. «بازی‌سازی» و «انگیزه»: «بازی‌سازی» «رفتار» را «بازتولید» می‌کند اما «ا', '2e4941d52959e89db7bc7e9d3006bc9777ecfe2ae344d44bf4db263bfdfd463e', 974, 'ch-doc-card-454-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2e4941d52959e89db7bc7e9d3006bc9777ecfe2ae344d44bf4db263bfdfd463e', token_count=974, vector_point_id='ch-doc-card-454-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-454-13', 'doc-card-454', 'sec-card-454-7', 13, 'نگیزه» «داخلی» را «محو» می‌کند: «پاداش»، «بازی» را «کار» می‌کند. ۶. «فرهنگ همگرا» و «نظارت»: «مخاطب» «تولید» می‌کند و «صنعت» «بازتولید» می‌کند: «نظارت» بر «مخاطب»، «حاکمیت» است. ۷. «فرهنگ عامه دیجیتال» و «اعتبار»: «محتوای» «مخاطب» «ساخته»، «اعتبار» ندارد: «مرز» بین «حرفه‌ای» و «مخاطب»، «بازتعریف» لازم دارد. ۸. «بازی» و «واقعیت»: «بازی» در «بافت» دیجیتال، «واقعیت» است: «مرز» بین «بازی» و «واقعیت»، «محو» شده است. ۹. «فرهنگ دیجیتال» و «نسل»: «فرهنگ» دیجیتال، «نسل» است اما «همه» «نسل‌ها» در آن «حاضر»‌اند: «مرز» «نسل»، «کمرنگ» شده است.', '0b0c3f05ea135af8deed6fc16c6361ab3920d24bdf5ebb22d4b4a264efdf1ab2', 974, 'ch-doc-card-454-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0b0c3f05ea135af8deed6fc16c6361ab3920d24bdf5ebb22d4b4a264efdf1ab2', token_count=974, vector_point_id='ch-doc-card-454-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-454-14', 'doc-card-454', 'sec-card-454-10', 14, 'کتاب «فرهنگ همگرا» (جَنکینز، ۲۰۰۶)؛ کتاب «بازی و فرهنگ» (سوسا، ۱۹۵۵)؛ کتاب «صنعت فرهنگ» (آدورنو و هورکهایمر، ۱۹۴۴)؛ کتاب «فرهنگ دیجیتال» (منرو و همکاران، ۲۰۰۴).', '373e57c2c2351d10cec24f7b867cae52e67956b87e6039750582abd935eddb22', 290, 'ch-doc-card-454-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='373e57c2c2351d10cec24f7b867cae52e67956b87e6039750582abd935eddb22', token_count=290, vector_point_id='ch-doc-card-454-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-455-0', 'doc-card-455', NULL, 0, 'گسترش یک روایت یکپارچهٔ کلان در پلتفرم‌های رسانه‌ای متمایز (فیلم، بازی، کمیک‌بوک، رمان) است؛ هر می‌دیوم بر اساس توان ساختاری‌اش سهمی یکتا به جهان داستانی می‌افزاید و تکه‌های پراکنده با هم، روایتی منسجم می‌سازند.', '81a25c638e2c9e34894f0afa87158fe2106eecfd49a2f2905ab20527ca7e5bf4', 383, 'ch-doc-card-455-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='81a25c638e2c9e34894f0afa87158fe2106eecfd49a2f2905ab20527ca7e5bf4', token_count=383, vector_point_id='ch-doc-card-455-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-455-1', 'doc-card-455', 'sec-card-455-1', 1, 'بازی، سرگرمی و فرهنگ دیجیتال  روایت یک داستان کلان و یکپارچه در پلتفرم‌های متمایز رسانه‌ای (فیلم، بازی رایانه‌ای، کمیک‌بوک و رمان)، که هر مدیوم بر اساس توانایی ساختاری‌اش سهمی یکتا به آن جهان داستانی می‌افزاید.', 'b2f9d9c44957d25a8147a23badfbc081b295a765a878ff2356580e0e681cfdb2', 381, 'ch-doc-card-455-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b2f9d9c44957d25a8147a23badfbc081b295a765a878ff2356580e0e681cfdb2', token_count=381, vector_point_id='ch-doc-card-455-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-455-2', 'doc-card-455', 'sec-card-455-2', 2, '۱. بنیان و منطق نظری روایت‌گری فرا-رسانه‌ای «بازی» را «فعالیت» معنادار در «بافت» دیجیتال می‌داند: نه «فرار» از واقعیت بلکه «بازی» با «معنا». هنری جنکینز (۲۰۰۳) در این چارچوب، «فرهنگ» را نه «محصول» «صنعت» بلکه «فعالیت» مخاطب تعریف کرد: «بازی»، «زبان» «نسل» دیجیتال است.  بر اساس روایت‌گری فرا-رسانه‌ای، «سرگرمی» «صنعت» است اما «فرهنگ» «فعالیت» مخاطب است: «صنعت» «محتوا» تولید می‌کند و «مخاطب» «معنا» بازتولید می‌کند. هنری جنکینز (۲۰۰۳) در این چارچوب، «فرهنگ دیجیتال» را «فضا» «تولید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.', '13f77ac7c5b89a622546fc09ef1b625e434bc482696726fff80235a9435133a2', 1012, 'ch-doc-card-455-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='13f77ac7c5b89a622546fc09ef1b625e434bc482696726fff80235a9435133a2', token_count=1012, vector_point_id='ch-doc-card-455-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-455-3', 'doc-card-455', 'sec-card-455-2', 3, 'ید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  روایت‌گری فرا-رسانه‌ای را می‌توان پاسخی به شکاف میان «نقد» «صنعت فرهنگ» (فرانکفورت) و «مطالعات فرهنگی» (مقاومت مخاطب) دانست: «بازی» و «سرگرمی» هم «بازتولید» «ایدئولوژی» است و هم «مقاومت» مخاطب. هنری جنکینز (۲۰۰۳) در این چارچوب، «فرهنگ دیجیتال» را «میدان» «دیالکتیک» «صنعت» و «مخاطب» تعریف کرد.  ۲. ساختارهای مفهومی • بازی و فرهنگ (Play and Culture): «بازی» به‌عنوان «زبان» «نسل» دیجیتال: «معنا» در «بازی» ساخته می‌شود. • فرهنگ دیجیتال (Digital Culture): «بافت» «فرهنگی» «نسل» دیجیتال: «بازی»، «بازی»، «میم» و «ریپلای»، «زبان» این «بافت»‌اند.', 'f63ad913e6892abd5906436706aebfc8ba39b679d0aad9881b5d5cd2f205f482', 1129, 'ch-doc-card-455-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f63ad913e6892abd5906436706aebfc8ba39b679d0aad9881b5d5cd2f205f482', token_count=1129, vector_point_id='ch-doc-card-455-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
