INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-456-0', 'doc-card-456', NULL, 0, 'مصرف رسانه‌ای فراتر از جستجوی ابزارمند اطلاعات، نوعی بازی ذهنی آزاد و لذت‌محور است. مخاطب، برای رهایی از درگیری‌های تحمیلیِ «جهان کار»، به رسانه پناه می‌برد و آن را به‌مثابهٔ فضایی آزاد و بازی‌گونه تجربه می‌کند.', 'ab2fb62130b29262ed921252d240c6e60c16e843cdce38e9c0903251ee62d632', 383, 'ch-doc-card-456-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ab2fb62130b29262ed921252d240c6e60c16e843cdce38e9c0903251ee62d632', token_count=383, vector_point_id='ch-doc-card-456-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-456-1', 'doc-card-456', 'sec-card-456-1', 1, 'بازی، سرگرمی و فرهنگ دیجیتال  مصرف رسانه‌ای بیش از آنکه حاصل جستجوی اطلاعات و کارکردگرایی ابزاری باشد، نوعی بازی ذهنی آزاد، لذت‌محور و رهایی‌بخش از درگیری‌های تحمیلی جهان کار است.', '8d2d63b2ba5f65718b0483dd6a0445adb869a169817342d2dc88b2113e74e8b1', 325, 'ch-doc-card-456-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8d2d63b2ba5f65718b0483dd6a0445adb869a169817342d2dc88b2113e74e8b1', token_count=325, vector_point_id='ch-doc-card-456-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-456-2', 'doc-card-456', 'sec-card-456-2', 2, '۱. بنیان و منطق نظری نظریه بازی در فرهنگ و ارتباطات «بازی» را «فعالیت» معنادار در «بافت» دیجیتال می‌داند: نه «فرار» از واقعیت بلکه «بازی» با «معنا». ویلیام استفنسون (۱۹۶۷) در این چارچوب، «فرهنگ» را نه «محصول» «صنعت» بلکه «فعالیت» مخاطب تعریف کرد: «بازی»، «زبان» «نسل» دیجیتال است.  بر اساس نظریه بازی در فرهنگ و ارتباطات، «سرگرمی» «صنعت» است اما «فرهنگ» «فعالیت» مخاطب است: «صنعت» «محتوا» تولید می‌کند و «مخاطب» «معنا» بازتولید می‌کند. ویلیام استفنسون (۱۹۶۷) در این چارچوب، «فرهنگ دیجیتال» را «فضا» «تولید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.', 'ef3bc5af8034140de482d729d201a083ede1b85686695a862929ddc635a61c38', 1056, 'ch-doc-card-456-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ef3bc5af8034140de482d729d201a083ede1b85686695a862929ddc635a61c38', token_count=1056, vector_point_id='ch-doc-card-456-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
