INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-456-8', 'doc-card-456', 'sec-card-456-4', 8, 'اعی» دارد: «میم»، «زبان» «فرهنگ» دیجیتال است و «معنا» در «تکرار» ساخته می‌شود.  «صنعت سرگرمی» در «عصر دیجیتال»: «پلتفرم‌های» استریمینگ «محتوا» را «استاندارد» می‌کنند: «سود»، «تکرار» و «استاندارد»، «منطق» «صنعت» است.  «فرهنگ همگرا» در عمل: «مخاطب» «سریال» «محتوا» «بازتولید» می‌کند (ریپلای، مم، کاسپلی): «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  «بازی‌سازی» در «آموزش»: «بازی» در «بافت» «آموزش» (پاداش، نقش، رقابت) «رفتار» را «بازتولید» می‌کند: «بازی»، «ابزار» «رفتار» است.  «فرهنگ عامه دیجیتال» در عمل: «محتوای» «مخاطب» «ساخته» (ویدیو، مم، پادکست) «زبان» «فرهنگ» است: «مخاطب»، «تولیدکننده» «فرهنگ» است.  ۴. نقدها و چالش‌ها ۱.', '03da41571ec881f8dd1edc161fa020f1225fcc95e29ee7212ee2e7fcab523fef', 1174, 'ch-doc-card-456-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='03da41571ec881f8dd1edc161fa020f1225fcc95e29ee7212ee2e7fcab523fef', token_count=1174, vector_point_id='ch-doc-card-456-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
