INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-483-11', 'doc-card-483', 'sec-card-483-6', 11, '۱. «کمّی» و «کیفی» «دیالکتیک»‌اند: «کمّی» «تعمیم» دارد اما «عمق» ندارد و «کیفی» «عمق» دارد اما «تعمیم» ندارد: «روش» «ترکیبی»، «بافت» «دیالکتیک» است. ۲. «روش» و «نظریه» در هم تنیده‌اند: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش»: «روش» «خنثی» وجود ندارد. ۳. «اعتبار» در «روش» «کیفی» «سنجش‌پذیر» نیست: «اعتماد» در «بافت» «تحلیل» «ساخته» می‌شود و «اندازه‌گیری» آن «دشواری» است. ۴. «پیمایش» و «بافت»: «سؤال» در «پیمایش»، «بافت» «تحلیل» است: «سؤال» «بافت» «پاسخ» را «تعیین» می‌کند: «روش»، «بافت» «معنا» است. ۵. «تحلیل محتوا» و «ایدئولوژی»: «تحلیل» «متن» همیشه «ایدئولوژیک» است: «کد» و «فر', 'daddb583cd0633a2e558a3fe0d94268b91303a459fd83142997af0bb4d306082', 1072, 'ch-doc-card-483-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='daddb583cd0633a2e558a3fe0d94268b91303a459fd83142997af0bb4d306082', token_count=1072, vector_point_id='ch-doc-card-483-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-483-12', 'doc-card-483', 'sec-card-483-7', 12, 'اوانی»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «ایدئولوژی» می‌شود. ۶. «قوم‌نگاری» و «بافت»: «حضور» در «بافت»، «بافت» «تحلیل» را «بازتولید» می‌کند: «تحلیل‌گر»، «بافت» «تحلیل» است. ۷. «روش» در «عصر دیجیتال» «بازتعریف» می‌شود: «داده» «دیجیتال» (داده‌کاوی، تحلیل شبکه) «روش» تازه‌ای تولید می‌کند که «بافت» «تحلیل» را «بازتعریف» می‌کند. ۸. «نظریه داده بنیادین» و «بافت»: «نظریه» از «داده» «ساخته» می‌شود اما «بافت» «داده»، «نظریه» را «تعیین» می‌کند: «بافت»، «نظریه» است. ۹. «روش» و «اعتبار»: «اعتبار» در «روش» «ساخته» می‌شود: «اعتماد» به «روش»، «اعتماد» به «نتیجه» است: «روش»، «بافت» «اعتبار» است.', '1dfa81db7c8df8c9c1993f81fca908972365a222a9570aa9405bc4e6981b4ca4', 1072, 'ch-doc-card-483-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1dfa81db7c8df8c9c1993f81fca908972365a222a9570aa9405bc4e6981b4ca4', token_count=1072, vector_point_id='ch-doc-card-483-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-483-13', 'doc-card-483', 'sec-card-483-10', 13, 'کتاب «روش پژوهش در ارتباطات» (بیر و همکاران، ۲۰۰۸)؛ کتاب «تحلیل محتوا» (هایرینگ، ۱۹۶۷)؛ کتاب «نظریه داده بنیادین» (گلایزر و استرأس، ۱۹۶۷)؛ کتاب «قوم‌نگاری و فرهنگ» (انول، ۱۹۸۴).', 'f40602f4e73937c5ab57d913729cc1b6482b7e5ff6a6c5988096f450bd7988a5', 321, 'ch-doc-card-483-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f40602f4e73937c5ab57d913729cc1b6482b7e5ff6a6c5988096f450bd7988a5', token_count=321, vector_point_id='ch-doc-card-483-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-484-0', 'doc-card-484', NULL, 0, 'روشی تحلیل متون خبری بر پایه‌ی ساختار روایت و روایت‌شناسی پراپ که واحدهای روایی، شخصیت‌ها و عمل‌ها را شناسایی می‌کند؛ نشان می‌دهد روایت چگونه انتخاب و ترتیب شده تا جهان را به‌شکل خاصی بازسازی کند و چه ارزش‌هایی در پس ساختار روایی نهفته است.', 'cc6187cedb96125b6473a821d61256075bea0a11cb936932c703539142d5ccab', 436, 'ch-doc-card-484-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cc6187cedb96125b6473a821d61256075bea0a11cb936932c703539142d5ccab', token_count=436, vector_point_id='ch-doc-card-484-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
