INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-484-2', 'doc-card-484', 'sec-card-484-2', 2, '۱. بنیان و منطق نظری تحلیل روایت «روش» را «بافت» «معنا» می‌داند: نه «ابزار» «تحلیل» بلکه «بافت» «تحلیل». پراپ (۱۹۲۸) در این چارچوب، «روش» را «بافت» «معرفت» تعریف کرد: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش».  بر اساس تحلیل روایت، «روش» «دیالکتیک» «نظریه» و «داده» است: «نظریه»، «بافت» «تحلیل» است و «داده»، «بافت» «نظریه». پراپ (۱۹۲۸) در این چارچوب، «روش» را «بافت» «اعتماد» تعریف کرد: «اعتماد» در «روش» «ساخته» می‌شود، نه در «نتیجه».  تحلیل روایت را می‌توان پاسخی به شکاف میان «روش» «کمّی» (تعمیم) و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش». پراپ (۱۹۲۸) در این چارچوب، «روش» را «بافت» «بازی» تعریف کرد: «تحلیل»، «بازی» با «داده» است.', 'b4bb224977ad80a05aa1ef6d8e6f820ce070bf7c28eb2dfadfde8501823bc347', 1234, 'ch-doc-card-484-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b4bb224977ad80a05aa1ef6d8e6f820ce070bf7c28eb2dfadfde8501823bc347', token_count=1234, vector_point_id='ch-doc-card-484-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-484-3', 'doc-card-484', 'sec-card-484-2', 3, 'در این چارچوب، «روش» را «بافت» «بازی» تعریف کرد: «تحلیل»، «بازی» با «داده» است.  ۲. ساختارهای مفهومی • روش کمّی (Quantitative Method): «اندازه‌گیری» و «تعمیم»: «داده» «عددی» و «تحلیل» «آمار». • روش کیفی (Qualitative Method): «فهم» و «عمق»: «داده» «کیفی» و «تحلیل» «تفسیر». • روش ترکیبی (Mixed Methods): «ترکیب» «کمّی» و «کیفی»: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • پیمایش (Survey): «اندازه‌گیری» «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته». • تحلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن». • نظریه داده بنیادین (Grounded Theory): «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود.', '4d8345888ecefaa4b662a84afb588b05efa92f1c910ed29f6b5776ed4003946f', 1161, 'ch-doc-card-484-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4d8345888ecefaa4b662a84afb588b05efa92f1c910ed29f6b5776ed4003946f', token_count=1161, vector_point_id='ch-doc-card-484-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-484-4', 'doc-card-484', 'sec-card-484-2', 4, 'ین (Grounded Theory): «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود. • قوم‌نگاری (Ethnography): «فهم» «بافت»: «حضور» در «بافت» و «فهم» «معنا» در «بافت». • اعتبا', '2c46863e9e724353a01c4a520a77935bec6e8adefc8c7690d8437439e53056c3', 310, 'ch-doc-card-484-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2c46863e9e724353a01c4a520a77935bec6e8adefc8c7690d8437439e53056c3', token_count=310, vector_point_id='ch-doc-card-484-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
