INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-511-12', 'doc-card-511', 'sec-card-511-5', 12, '«توان» حرفه‌ای را «حفظ» می‌کند: «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی رسانه است.  «ریسک شغلی» در «عصر دیجیتال»: «مسابقه» برای «نکست» و «فشار» «سرعت»، «کار» رسانه‌ای را «پراکنده» و «ناپایدار» کرده است: «استقلال» حرفه‌ای «تحت فشار» است.', '714b07ad4f7a51079e90fad97f6ce548775ccc75495317d26370de2f83c7510d', 419, 'ch-doc-card-511-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='714b07ad4f7a51079e90fad97f6ce548775ccc75495317d26370de2f83c7510d', token_count=419, vector_point_id='ch-doc-card-511-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-511-13', 'doc-card-511', 'sec-card-511-6', 13, '۱. «حرفه‌ای‌سازی» به «نقش‌پردازی» تقلیل می‌یابد: «اصول» به «نقش» تبدیل می‌شوند و «کار» به «نقش‌بازی»: «اعتبار» بدون «عمل» «معنا» ندارد. ۲. «ساختار سازمانی» در «عصر دیجیتال» «بازتعریف» می‌شود: «سلسله‌مراتب» کلاسیک در «پلتفرم‌ها» «عمل» نمی‌کند و «ساختار» «شبکه‌ای»، «بازتعریف» لازم دارد. ۳. «منابع انسانی» و «داده»: «ارزیابی» کارکنان با «داده» و «الگوریتم»، «حرفه‌ای‌بودن» را «ابزاری» می‌کند: «توان» به «داده» تبدیل می‌شود. ۴. «کار پراکنده» و «اعتبار»: «مستقل» «حرفه‌ای» نیست و «اعتبار» ندارد: «مرز» بین «حرفه‌ای» و «مستقل»، «بازتعریف» لازم دارد. ۵. «فرهنگ سازمانی» و «قدرت»: «فرهنگ» در «سلسله‌مراتب»، «قدرت» است: «فرهنگ»', '2b6e87c0375f44acac0dbf50743587916b51216784afad745c61db32777925b4', 1125, 'ch-doc-card-511-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2b6e87c0375f44acac0dbf50743587916b51216784afad745c61db32777925b4', token_count=1125, vector_point_id='ch-doc-card-511-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-511-14', 'doc-card-511', 'sec-card-511-7', 14, '«رقابت»، «فشار» می‌سازد و «کار» را «استثمار» می‌کند. ۶. «توسعه شغلی» و «بازار»: «مسیر» شغلی در «بازار» «رقابت» «تعیین» می‌شود: «توان» حرفه‌ای «بازتولید» نمی‌شود و «کار» به «رقابت» تقلیل می‌یابد. ۷. «ریسک شغلی» در «بافت‌های دولتی» «عمیق‌تر» است: «فشار» «سیاسی» بر «کار» رسانه‌ای، «ریسک» را «افزایش» می‌دهد و «استقلال» حرفه‌ای «تحت فشار» است. ۸. «مدیریت منابع انسانی» و «حقوق»: «حقوق» کارکنان رسانه‌ای در «بازار» «رقابت» «تعیین» می‌شود: «سرمایه‌ی انسانی» «استثمار» می‌شود. ۹. «ساختار» و «نقش» در «عصر الگوریتم» «بازتعریف» می‌شوند: «الگوریتم»، «نقش» «کارکنان» را «تعیین» می‌کند و «ساختار» «سازمانی»، «بازتعریف» لازم دارد.', '59813802a8fd8b584b7cf5aaf1f17e5f784c089429ecd008c4916c8e5915090b', 1123, 'ch-doc-card-511-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='59813802a8fd8b584b7cf5aaf1f17e5f784c089429ecd008c4916c8e5915090b', token_count=1123, vector_point_id='ch-doc-card-511-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-511-15', 'doc-card-511', 'sec-card-511-10', 15, 'کتاب «حرفه‌ای‌سازی رسانه» (گارتنر و همکاران، ۱۹۸۶)؛ کتاب «سازمان رسانه‌ای» (تاکت و همکاران، ۱۹۹۰)؛ کتاب «کار پراکنده و رسانه» (بویل و همکاران، ۲۰۱۵)؛ کتاب «منابع انسانی در رسانه» (مورگان، ۲۰۰۴).', 'd88d82e7ec3cb842cb7f0755a7adc74d63d4eaf63470e287fa072ada619a6ae9', 352, 'ch-doc-card-511-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d88d82e7ec3cb842cb7f0755a7adc74d63d4eaf63470e287fa072ada619a6ae9', token_count=352, vector_point_id='ch-doc-card-511-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-512-0', 'doc-card-512', NULL, 0, 'تولیدگر کار رسانه‌ای را «حرفه‌ای‌سازی» (professionalization) می‌داند: رسانه، «نهاد» است و «حرفه‌ای» بودن، «اعتبار» می‌سازد. تافلر (۱۹۸۰) در این چارچوب، «کار رسانه‌ای» را از «پیشه» به «حرفه» ارتقا داد: «اصول»، «نقش» و «نقش‌های» سازمانی، «ساختار» کار را «تعیین» می‌کنند. بر اساس …', '634e9aff96dac6640f083dae415bacdb1ff165de433fefdc077322c1387b543f', 505, 'ch-doc-card-512-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='634e9aff96dac6640f083dae415bacdb1ff165de433fefdc077322c1387b543f', token_count=505, vector_point_id='ch-doc-card-512-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-512-1', 'doc-card-512', 'sec-card-512-1', 1, 'منابع انسانی و کار رسانه‌ای  تولیدگر کار رسانه‌ای را «حرفه‌ای‌سازی» (professionalization) می‌داند: رسانه، «نهاد» است و «حرفه‌ای» بودن، «اعتبار» می‌سازد. تافلر (۱۹۸۰) در این چارچوب، «کار رسانه‌ای» را از «پیشه» به «حرفه» ارتقا داد: «اصول»، «نقش» و «نقش‌های» سازمانی، «ساختار» کار را «تعیین» می‌کنند.  بر اساس تولیدگر، «سازمان رسانه‌ای» با «ساختار» و «فرهنگ» سازمانی «کار» را «بازتولید» می‌کند: «سلسله‌مراتب»، «نقش‌ها» و «فرهنگ» سازمانی، «رفتار» کارکنان را «شکل» می‌دهند. تافلر (۱۹۸۰) در این چارچوب، «منابع انسانی» را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.', '1c831071cea1081dfa15ac0d4108a4d87d443d361cf6b49e4a429cacd0656075', 1070, 'ch-doc-card-512-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1c831071cea1081dfa15ac0d4108a4d87d443d361cf6b49e4a429cacd0656075', token_count=1070, vector_point_id='ch-doc-card-512-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-512-2', 'doc-card-512', 'sec-card-512-1', 2, 'را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.  تولیدگر را می‌توان پاسخی به شکاف میان «سازمان کلاسیک» (سلسله‌مراتبی) و «سازمان دیجیتال» (شبکه‌ای) دانست: در «عصر دیجیتال»، «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده و «کار» رسانه‌ای به «کار پراکنده» (gig) تبدیل شده است. تافلر (۱۹۸۰) در این چارچوب، «کار» را نه «پاره‌ای» از «سازمان» بلکه «جریان» در «بازار» تعریف کرد.', '740b986ff544546f3c164f4f8a87a5068d4a6ef0cc0ecb8da59829020537fcff', 714, 'ch-doc-card-512-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='740b986ff544546f3c164f4f8a87a5068d4a6ef0cc0ecb8da59829020537fcff', token_count=714, vector_point_id='ch-doc-card-512-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-512-3', 'doc-card-512', 'sec-card-512-2', 3, '۱. بنیان و منطق نظری تولیدگر کار رسانه‌ای را «حرفه‌ای‌سازی» (professionalization) می‌داند: رسانه، «نهاد» است و «حرفه‌ای» بودن، «اعتبار» می‌سازد. تافلر (۱۹۸۰) در این چارچوب، «کار رسانه‌ای» را از «پیشه» به «حرفه» ارتقا داد: «اصول»، «نقش» و «نقش‌های» سازمانی، «ساختار» کار را «تعیین» می‌کنند.  بر اساس تولیدگر، «سازمان رسانه‌ای» با «ساختار» و «فرهنگ» سازمانی «کار» را «بازتولید» می‌کند: «سلسله‌مراتب»، «نقش‌ها» و «فرهنگ» سازمانی، «رفتار» کارکنان را «شکل» می‌دهند. تافلر (۱۹۸۰) در این چارچوب، «منابع انسانی» را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.', '7f462139bf6ffd8c64bbe60a5fd7e1a3ed7639746a909172fba4e0f71f727090', 1056, 'ch-doc-card-512-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7f462139bf6ffd8c64bbe60a5fd7e1a3ed7639746a909172fba4e0f71f727090', token_count=1056, vector_point_id='ch-doc-card-512-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-512-4', 'doc-card-512', 'sec-card-512-2', 4, 'را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.  تولیدگر را می‌توان پاسخی به شکاف میان «سازمان کلاسیک» (سلسله‌مراتبی) و «سازمان دیجیتال» (شبکه‌ای) دانست: در «عصر دیجیتال»، «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده و «کار» رسانه‌ای به «کار پراکنده» (gig) تبدیل شده است. تافلر (۱۹۸۰) در این چارچوب، «کار» را نه «پاره‌ای» از «سازمان» بلکه «جریان» در «بازار» تعریف کرد.  ۲. ساختارهای مفهومی • حرفه‌ای‌سازی (Professionalization): فرایند «حرفه‌ای» شدن کار رسانه‌ای: «اصول»، «نقش» و «نقش‌های» سازمانی؛ «اعتبار» و «استقلال».', 'a318886024b867495151793c8afc427c51c992751ad204fc5c3b2974e44b6120', 989, 'ch-doc-card-512-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a318886024b867495151793c8afc427c51c992751ad204fc5c3b2974e44b6120', token_count=989, vector_point_id='ch-doc-card-512-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-512-5', 'doc-card-512', 'sec-card-512-2', 5, '‌ای» شدن کار رسانه‌ای: «اصول»، «نقش» و «نقش‌های» سازمانی؛ «اعتبار» و «استقلال». • ساختار سازمانی (Organizational Structure): «سلسله‌مراتب»، «نقش‌ها» و «مسئولیت‌ها» در رسانه؛ «ساختار»، «رفتار» کارکنان را «شکل» می‌دهد. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها»، «باورها» و «نمادها» در رسانه؛ «فرهنگ»، «رفتار» را «بازتولید» می‌کند. • مدیریت منابع انسانی (HR Management): «جذب»، «آموزش»، «ارزیابی» و «حفظ» «توان» حرفه‌ای؛ «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی است. • کار پراکنده (Gig Work): «کار» «مستقل»، «پاره‌وقت» و «پروژه‌ای» در رسانه؛ «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده است. • ریسک شغلی (Job Insecurity): «ناپایداری» کار', '9eaca32f0311ed7d35e430fec3ecadf490d4537b2da392cff4b1af5e874f522d', 1150, 'ch-doc-card-512-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9eaca32f0311ed7d35e430fec3ecadf490d4537b2da392cff4b1af5e874f522d', token_count=1150, vector_point_id='ch-doc-card-512-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-512-6', 'doc-card-512', 'sec-card-512-3', 6, '• حرفه‌ای‌سازی (Professionalization): فرایند «حرفه‌ای» شدن کار رسانه‌ای: «اصول»، «نقش» و «نقش‌های» سازمانی؛ «اعتبار» و «استقلال». • ساختار سازمانی (Organizational Structure): «سلسله‌مراتب»، «نقش‌ها» و «مسئولیت‌ها» در رسانه؛ «ساختار»، «رفتار» کارکنان را «شکل» می‌دهد. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها»، «باورها» و «نمادها» در رسانه؛ «فرهنگ»، «رفتار» را «بازتولید» می‌کند. • مدیریت منابع انسانی (HR Management): «جذب»، «آموزش»، «ارزیابی» و «حفظ» «توان» حرفه‌ای؛ «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی است. • کار پراکنده (Gig Work): «کار» «مستقل»، «پاره‌وقت» و «پروژه‌ای» در رسانه؛ «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده است.', '8ed776a62c1398c2193e6cdfcbb731d44985ab6f4f5d05b39d5fcf428dc75fd7', 1158, 'ch-doc-card-512-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8ed776a62c1398c2193e6cdfcbb731d44985ab6f4f5d05b39d5fcf428dc75fd7', token_count=1158, vector_point_id='ch-doc-card-512-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-512-7', 'doc-card-512', 'sec-card-512-3', 7, '«پاره‌وقت» و «پروژه‌ای» در رسانه؛ «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده است. • ریسک شغلی (Job Insecurity): «ناپایداری» کار رسانه‌ای؛ «مسابقه» و «فشار» در «عصر دیجیتال»، «ریسک» را «افزایش» داده است. • نقش حرفه‌ای (Professional Role): «نقش» روزنامه‌نگار، ویراستار، کارگردان، مدیر؛ «نقش‌ها»، «ساختار» کار را «تعیین» می‌کنند. • توسعه شغلی (Career Development): «مسیر» شغلی و «آموزش» مداوم؛ «توان» حرفه‌ای، «بازتولید» روزانه نیاز دارد.', '6b0e6d8e71d49df86b71221030f14b943240b5f58c4de60c1f73c41d0770e7ab', 785, 'ch-doc-card-512-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6b0e6d8e71d49df86b71221030f14b943240b5f58c4de60c1f73c41d0770e7ab', token_count=785, vector_point_id='ch-doc-card-512-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-512-8', 'doc-card-512', 'sec-card-512-4', 8, 'رسانه‌ای؛ «مسابقه» و «فشار» در «عصر دیجیتال»، «ریسک» را «افزایش» داده است. • نقش حرفه‌ای (Professional Role): «نقش» روزنامه‌نگار، ویراستار، کارگردان، مدیر؛ «نقش‌ها»، «ساختار» کار را «تعیین» می‌کنند. • توسعه شغلی (Career Development): «مسیر» شغلی و «آموزش» مداوم؛ «توان» حرفه‌ای، «بازتولید» روزانه نیاز دارد.  ۳. نمونه‌های تحلیلی «حرفه‌ای‌سازی» در عمل: «روزنامه‌نگار» با «دوره» و «اصول» «حرفه‌ای» می‌شود: «اعتبار» از «آموزش» و «اصول» ساخته می‌شود.  «ساختار سازمانی» در عمل: «سلسله‌مراتب» در «تلفظ» (گزارشگر، ویراستار، مدیر) «رفتار» کارکنان را «تعیین» می‌کند: «سلسله‌مراتب»، «نقش» است.', '8b1f94b32ba0807bb089d08dbfea4097933cf4eff7a866ff7dd18cdb0b780eac', 1060, 'ch-doc-card-512-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8b1f94b32ba0807bb089d08dbfea4097933cf4eff7a866ff7dd18cdb0b780eac', token_count=1060, vector_point_id='ch-doc-card-512-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-512-9', 'doc-card-512', 'sec-card-512-4', 9, '، ویراستار، مدیر) «رفتار» کارکنان را «تعیین» می‌کند: «سلسله‌مراتب»، «نقش» است.  «کار پراکنده» در عمل: «مستقل» در «شبکه‌های اجتماعی» «محتوا» می‌سازد: «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده و «ریسک شغلی» «افزایش» یافته است.  «فرهنگ سازمانی» در عمل: «فرهنگ» «رقابت» در «رسانه‌ای» و «فرهنگ» «همکاری» در «رسانه‌ای» دیگر، «رفتار» کارکنان را «بازتولید» می‌کند: «فرهنگ»، «ساختار» است.  «مدیریت منابع انسانی» در عمل: «آموزش» «مداوم» «توان» حرفه‌ای را «حفظ» می‌کند: «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی رسانه است.  «ریسک شغلی» در «عصر دیجیتال»: «مسابقه» برای «نکست» و «فشار» «سرعت»، «کار» رسانه‌ای را «پراکنده» و «ناپایدار» کرده است: «استقلال» حرفه‌ای «تحت فشار» است.  ۴. نقدها و چالش‌ها ۱.', 'd93efc58fc5f7db9a37ef54a7de73693fc1e2f66801cdd0367735073346c4011', 1234, 'ch-doc-card-512-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d93efc58fc5f7db9a37ef54a7de73693fc1e2f66801cdd0367735073346c4011', token_count=1234, vector_point_id='ch-doc-card-512-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-512-10', 'doc-card-512', 'sec-card-512-4', 10, 'و «ناپایدار» کرده است: «استقلال» حرفه‌ای «تحت فشار» است.  ۴. نقدها و چالش‌ها ۱. «حرفه‌ای‌سازی» به «نقش‌پردازی» تقلیل می‌یابد: «اصول» به «نقش» تبدیل می‌شوند و «کار» به «نقش‌بازی»: «اعتبار» بدون «عمل» «معنا» ندارد. ۲. «ساختار سازمانی» در «عصر دیجیتال» «بازتعریف» می‌شود: «سلسله‌مراتب» کلاسیک در «پلتفرم‌ها» «عمل» نمی‌کند و «ساختار» «شبکه‌ای»، «بازتعریف» لازم دارد. ۳. «منابع انسانی» و «داده»: «ارزیابی» کارکنان با «داده» و «الگوریتم»، «حرفه‌ای‌بودن» را «ابزاری» می‌کند: «توان» به «داده» تبدیل می‌شود.', '06b4bca038c1ef94c11da8deb2d41d3e076a0f55c0530bedd1e13e5f403e9c5d', 905, 'ch-doc-card-512-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='06b4bca038c1ef94c11da8deb2d41d3e076a0f55c0530bedd1e13e5f403e9c5d', token_count=905, vector_point_id='ch-doc-card-512-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-512-11', 'doc-card-512', 'sec-card-512-5', 11, '«حرفه‌ای‌سازی» در عمل: «روزنامه‌نگار» با «دوره» و «اصول» «حرفه‌ای» می‌شود: «اعتبار» از «آموزش» و «اصول» ساخته می‌شود.  «ساختار سازمانی» در عمل: «سلسله‌مراتب» در «تلفظ» (گزارشگر، ویراستار، مدیر) «رفتار» کارکنان را «تعیین» می‌کند: «سلسله‌مراتب»، «نقش» است.  «کار پراکنده» در عمل: «مستقل» در «شبکه‌های اجتماعی» «محتوا» می‌سازد: «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده و «ریسک شغلی» «افزایش» یافته است.  «فرهنگ سازمانی» در عمل: «فرهنگ» «رقابت» در «رسانه‌ای» و «فرهنگ» «همکاری» در «رسانه‌ای» دیگر، «رفتار» کارکنان را «بازتولید» می‌کند: «فرهنگ»، «ساختار» است.  «مدیریت منابع انسانی» در عمل: «آموزش» «مداوم» «توان» حرفه‌ای را «حفظ» می‌کند: «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی رسانه است.', '6a68e2945ec469e28fc56bba76efd3d7d13bcbee407858fe8e6060d48d54e96b', 1232, 'ch-doc-card-512-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6a68e2945ec469e28fc56bba76efd3d7d13bcbee407858fe8e6060d48d54e96b', token_count=1232, vector_point_id='ch-doc-card-512-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-512-12', 'doc-card-512', 'sec-card-512-5', 12, '«توان» حرفه‌ای را «حفظ» می‌کند: «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی رسانه است.  «ریسک شغلی» در «عصر دیجیتال»: «مسابقه» برای «نکست» و «فشار» «سرعت»، «کار» رسانه‌ای را «پراکنده» و «ناپایدار» کرده است: «استقلال» حرفه‌ای «تحت فشار» است.', '714b07ad4f7a51079e90fad97f6ce548775ccc75495317d26370de2f83c7510d', 419, 'ch-doc-card-512-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='714b07ad4f7a51079e90fad97f6ce548775ccc75495317d26370de2f83c7510d', token_count=419, vector_point_id='ch-doc-card-512-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-512-13', 'doc-card-512', 'sec-card-512-6', 13, '۱. «حرفه‌ای‌سازی» به «نقش‌پردازی» تقلیل می‌یابد: «اصول» به «نقش» تبدیل می‌شوند و «کار» به «نقش‌بازی»: «اعتبار» بدون «عمل» «معنا» ندارد. ۲. «ساختار سازمانی» در «عصر دیجیتال» «بازتعریف» می‌شود: «سلسله‌مراتب» کلاسیک در «پلتفرم‌ها» «عمل» نمی‌کند و «ساختار» «شبکه‌ای»، «بازتعریف» لازم دارد. ۳. «منابع انسانی» و «داده»: «ارزیابی» کارکنان با «داده» و «الگوریتم»، «حرفه‌ای‌بودن» را «ابزاری» می‌کند: «توان» به «داده» تبدیل می‌شود. ۴. «کار پراکنده» و «اعتبار»: «مستقل» «حرفه‌ای» نیست و «اعتبار» ندارد: «مرز» بین «حرفه‌ای» و «مستقل»، «بازتعریف» لازم دارد. ۵. «فرهنگ سازمانی» و «قدرت»: «فرهنگ» در «سلسله‌مراتب»، «قدرت» است: «فرهنگ»', '2b6e87c0375f44acac0dbf50743587916b51216784afad745c61db32777925b4', 1125, 'ch-doc-card-512-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2b6e87c0375f44acac0dbf50743587916b51216784afad745c61db32777925b4', token_count=1125, vector_point_id='ch-doc-card-512-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-512-14', 'doc-card-512', 'sec-card-512-7', 14, '«رقابت»، «فشار» می‌سازد و «کار» را «استثمار» می‌کند. ۶. «توسعه شغلی» و «بازار»: «مسیر» شغلی در «بازار» «رقابت» «تعیین» می‌شود: «توان» حرفه‌ای «بازتولید» نمی‌شود و «کار» به «رقابت» تقلیل می‌یابد. ۷. «ریسک شغلی» در «بافت‌های دولتی» «عمیق‌تر» است: «فشار» «سیاسی» بر «کار» رسانه‌ای، «ریسک» را «افزایش» می‌دهد و «استقلال» حرفه‌ای «تحت فشار» است. ۸. «مدیریت منابع انسانی» و «حقوق»: «حقوق» کارکنان رسانه‌ای در «بازار» «رقابت» «تعیین» می‌شود: «سرمایه‌ی انسانی» «استثمار» می‌شود. ۹. «ساختار» و «نقش» در «عصر الگوریتم» «بازتعریف» می‌شوند: «الگوریتم»، «نقش» «کارکنان» را «تعیین» می‌کند و «ساختار» «سازمانی»، «بازتعریف» لازم دارد.', '59813802a8fd8b584b7cf5aaf1f17e5f784c089429ecd008c4916c8e5915090b', 1123, 'ch-doc-card-512-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='59813802a8fd8b584b7cf5aaf1f17e5f784c089429ecd008c4916c8e5915090b', token_count=1123, vector_point_id='ch-doc-card-512-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-512-15', 'doc-card-512', 'sec-card-512-10', 15, 'کتاب «حرفه‌ای‌سازی رسانه» (گارتنر و همکاران، ۱۹۸۶)؛ کتاب «سازمان رسانه‌ای» (تاکت و همکاران، ۱۹۹۰)؛ کتاب «کار پراکنده و رسانه» (بویل و همکاران، ۲۰۱۵)؛ کتاب «منابع انسانی در رسانه» (مورگان، ۲۰۰۴).', 'd88d82e7ec3cb842cb7f0755a7adc74d63d4eaf63470e287fa072ada619a6ae9', 352, 'ch-doc-card-512-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d88d82e7ec3cb842cb7f0755a7adc74d63d4eaf63470e287fa072ada619a6ae9', token_count=352, vector_point_id='ch-doc-card-512-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-513-0', 'doc-card-513', NULL, 0, 'نظریه نظام جهانی اطلاعات (یونسکو، دهه ۱۹۷۰) توزیع ناعادلانه جریان اطلاعات در سطح جهانی را می‌کاود؛ قدرت بر رسانه از سه مسیر مالکیت، محتوا و فرمت عمل می‌کند و نظم رسانه‌ای کلان را به میدان سیاسی مشروعیت‌سازی تبدیل می‌سازد.', '88124d6d5c2bfe6e8be30e234cf051a355301f9fcd09bd80be0826c35b221029', 401, 'ch-doc-card-513-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='88124d6d5c2bfe6e8be30e234cf051a355301f9fcd09bd80be0826c35b221029', token_count=401, vector_point_id='ch-doc-card-513-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-513-1', 'doc-card-513', 'sec-card-513-1', 1, 'قدرت، سیاست و حاکمیت رسانه  نظم نوین ارتباطات.', '95599f8cd3cf7b4936300740b56d5fc88e5bf70a8032adc086512840f8d5adf0', 83, 'ch-doc-card-513-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='95599f8cd3cf7b4936300740b56d5fc88e5bf70a8032adc086512840f8d5adf0', token_count=83, vector_point_id='ch-doc-card-513-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-513-2', 'doc-card-513', 'sec-card-513-2', 2, '۱. بنیان و منطق نظری نظریه نظام جهانی اطلاعات رسانه را «سازوکار حاکمیت» می‌داند: نه صرفاَ «ابزار» دولت، بلکه «زمینه‌ی» قدرت، رقابت و مشروعیت‌سازی. یونسکو (۱۹۷۰) نشان داد که «قدرت» بر رسانه از سه مسیر عمل می‌کند: «مالکیت» (چه کسی مالک است)، «محتوا» (چه چیزی گفته می‌شود) و «فرمت» (چگونه گفته می‌شود). این چارچوب در سطح کلان تحلیل، رسانه را از «ابزار» به «نهاد سیاسی» ارتقا می‌دهد.  بر اساس نظریه نظام جهانی اطلاعات، «حاکمیت رسانه» یعنی «مدیریت جریان معنا» در سطح کلان: «سیاست‌گذاری رسانه‌ای»، «قانون» و «نظم‌های» خودتنظیمی، «قواعد بازی» را تعیین می‌کنند. یونسکو (۱۹۷۰) در این چارچوب، «نظم رسانه‌ای» را نه «پایان» بلکه «نقطه‌ی آغاز» تحلیل قرار داد: نظم، میدان نبرد سیاسی است.', '606266846e686914b3962df7bebb3c36367d081a5a91fa57fbe21612c9c06dcd', 1223, 'ch-doc-card-513-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='606266846e686914b3962df7bebb3c36367d081a5a91fa57fbe21612c9c06dcd', token_count=1223, vector_point_id='ch-doc-card-513-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-513-3', 'doc-card-513', 'sec-card-513-2', 3, 'ی» را نه «پایان» بلکه «نقطه‌ی آغاز» تحلیل قرار داد: نظم، میدان نبرد سیاسی است.  نظریه نظام جهانی اطلاعات را می‌توان پاسخی به شکاف میان «نظریه‌ی وابستگی» (رسانه، بازتاب قدرت) و «نظریه‌ی استقلال» (رسانه، حواله‌گر قدرت) دانست: قدرت، نه «بازتاب» بلکه «بازتولید» است. یونسکو (۱۹۷۰) در این چارچوب، «قدرت رسانه» را «دوسویه» خواند: رسانه هم «تحت تأثیر» قدرت است و هم «تولیدکننده» آن.  ۲. ساختارهای مفهومی • قدرت بر رسانه (Power over Media): «مالکیت»، «فروشگاه» و «نظم» که «محتوا» را از پیش تعیین می‌کنند؛ پرسش «چه کسی تصمیم می‌گیرد؟» در کانون است. • قدرت رسانه (Power of Media): توانایی رسانه در «تدوین» واقعیت، «مشروعیت‌سازی» و «نهادسازی»؛ رسانه، «قدرت نرم» تولید می‌کند.', 'b42de0ab0fbc21c242792653df9f4d8f5fad8a275a5393a40e4073ad15b6e44d', 1207, 'ch-doc-card-513-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b42de0ab0fbc21c242792653df9f4d8f5fad8a275a5393a40e4073ad15b6e44d', token_count=1207, vector_point_id='ch-doc-card-513-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-513-4', 'doc-card-513', 'sec-card-513-2', 4, 'در «تدوین» واقعیت، «مشروعیت‌سازی» و «نهادسازی»؛ رسانه، «قدرت نرم» تولید می‌کند. • نظم رسانه‌ای (Media Regulation): «قواعد بازی» رسانه: «قانون»، «نظم‌های» خودتنظیمی و «نظم‌های» دولتی؛ هر «نظم»، انتخاب سیاسی است. • سیاست‌گذاری رسانه‌ای (Media Policy): فرایند «تصمیم‌گیری» درباره‌ی «ساختار»، «مالکیت» و «محتوای» رسانه؛ «نهادها» و «گروه‌های» فشار در کانون‌اند. • مالکیت رسانه‌ای (Media Ownership): «ساختار» مالکیت (تمرکز/تعدد)', 'e7ac9c8824278b555e4af0535daba7f0f61606f33a9270e62fa7d7b574aad167', 767, 'ch-doc-card-513-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e7ac9c8824278b555e4af0535daba7f0f61606f33a9270e62fa7d7b574aad167', token_count=767, vector_point_id='ch-doc-card-513-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-513-5', 'doc-card-513', 'sec-card-513-3', 5, '• قدرت بر رسانه (Power over Media): «مالکیت»، «فروشگاه» و «نظم» که «محتوا» را از پیش تعیین می‌کنند؛ پرسش «چه کسی تصمیم می‌گیرد؟» در کانون است. • قدرت رسانه (Power of Media): توانایی رسانه در «تدوین» واقعیت، «مشروعیت‌سازی» و «نهادسازی»؛ رسانه، «قدرت نرم» تولید می‌کند. • نظم رسانه‌ای (Media Regulation): «قواعد بازی» رسانه: «قانون»، «نظم‌های» خودتنظیمی و «نظم‌های» دولتی؛ هر «نظم»، انتخاب سیاسی است. • سیاست‌گذاری رسانه‌ای (Media Policy): فرایند «تصمیم‌گیری» درباره‌ی «ساختار»، «مالکیت» و «محتوای» رسانه؛ «نهادها» و «گروه‌های» فشار در کانون‌اند.', '9c13d9d60f70428338de8f419e6539e1b79fa830e8c2a96fa764fb8e452094ba', 989, 'ch-doc-card-513-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9c13d9d60f70428338de8f419e6539e1b79fa830e8c2a96fa764fb8e452094ba', token_count=989, vector_point_id='ch-doc-card-513-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-513-6', 'doc-card-513', 'sec-card-513-3', 6, 'ی «ساختار»، «مالکیت» و «محتوای» رسانه؛ «نهادها» و «گروه‌های» فشار در کانون‌اند. • مالکیت رسانه‌ای (Media Ownership): «ساختار» مالکیت (تمرکز/تعدد) که «محتوا» را از پیش شکل می‌دهد؛ «مالکیت» و «اقتصاد» در هم تنیده‌اند. • مشروعیت‌سازی (Legitimation): رسانه با «گزارش» و «بازنمایی»، «حاکمیت» را «مشروع» می‌نمایاند؛ «تصویر» و «زبان»، ابزار «مشروعیت‌سازی»‌اند. • حاکمیت رسانه‌ای (Media Governance): «مدیریت کلان» رسانه: «نهادها»، «قوانین»، «نظم‌ها» و «نهادسازی» که «جریان معنا» را «تنظیم» می‌کنند. • رقابت رسانه‌ای (Media Competition): «رقابت» بین نهادهای رسانه‌ای برای «دسته‌ی» هدف، «سرمایه» و «اعتبار»؛ «رقابت» و «تمرکز» در «موازنه»‌اند.', 'e14293519f380356fbb4aacac333490eee67597b70dc853348070a5b60a65d3e', 1149, 'ch-doc-card-513-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e14293519f380356fbb4aacac333490eee67597b70dc853348070a5b60a65d3e', token_count=1149, vector_point_id='ch-doc-card-513-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-513-7', 'doc-card-513', 'sec-card-513-4', 7, 'که «محتوا» را از پیش شکل می‌دهد؛ «مالکیت» و «اقتصاد» در هم تنیده‌اند. • مشروعیت‌سازی (Legitimation): رسانه با «گزارش» و «بازنمایی»، «حاکمیت» را «مشروع» می‌نمایاند؛ «تصویر» و «زبان»، ابزار «مشروعیت‌سازی»‌اند. • حاکمیت رسانه‌ای (Media Governance): «مدیریت کلان» رسانه: «نهادها»، «قوانین»، «نظم‌ها» و «نهادسازی» که «جریان معنا» را «تنظیم» می‌کنند. • رقابت رسانه‌ای (Media Competition): «رقابت» بین نهادهای رسانه‌ای برای «دسته‌ی» هدف، «سرمایه» و «اعتبار»؛ «رقابت» و «تمرکز» در «موازنه»‌اند.  ۳. نمونه‌های تحلیلی وقتی «رسانه‌ای» از «انتخابات» گزارش می‌دهد، «موضوعات» و «زبان» آن، «مشروعیت‌سازی» است: «نحوه‌ی» گزارش، «حاکمیت» را «طبیعی» می‌نمایاند.', 'c296067bf6c51aa7ddf19ec25d633c1c0508a784dba2e8f892744e1606ba4de1', 1167, 'ch-doc-card-513-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c296067bf6c51aa7ddf19ec25d633c1c0508a784dba2e8f892744e1606ba4de1', token_count=1167, vector_point_id='ch-doc-card-513-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-513-8', 'doc-card-513', 'sec-card-513-4', 8, '«زبان» آن، «مشروعیت‌سازی» است: «نحوه‌ی» گزارش، «حاکمیت» را «طبیعی» می‌نمایاند.  «مالکیت رسانه‌ای» در عمل: وقتی یک «گروه اقتصادی» «رسانه» می‌خرد، «محتوا» از «پیش» شکل می‌گیرد؛ «مالکیت» و «اقتصاد» در هم تنیده‌اند.  «نظم رسانه‌ای» در «ایران» به «قانون» و «نظم دولتی» تقلیل نمی‌یابد: «نظم‌های» خودتنظیمی (کمیته‌های رسانه‌ای) و «نظم‌های» فرهنگی (سلیقه‌ی حاکم) هم در کانون‌اند.  «سیاست‌گذاری رسانه‌ای» در «اتحادیه اروپا» با «قانون خدمات رسانه‌ای» و «حریم خصوصی» تعریف می‌شود و «رقابت» بین «پلتفرم‌ها» و «رسانه‌های» سنتی، «موضوع» اصلی است.  «قدرت رسانه» در «بحران» به «تدوین» واقعیت تبدیل می‌شود: «نحوه‌ی» گزارش «بحران»، «واکنش» عمومی را «تعیین» می‌کند.', '057050f37b71e01990190aaf59926ad717dcacae89e107146383712e8573e87e', 1174, 'ch-doc-card-513-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='057050f37b71e01990190aaf59926ad717dcacae89e107146383712e8573e87e', token_count=1174, vector_point_id='ch-doc-card-513-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-513-9', 'doc-card-513', 'sec-card-513-4', 9, 'واقعیت تبدیل می‌شود: «نحوه‌ی» گزارش «بحران»، «واکنش» عمومی را «تعیین» می‌کند.  «حاکمیت رسانه‌ای» در «عصر دیجیتال» با «پلتفرم‌ها» «بازتعریف» می‌شود: «الگوریتم» و «داده»، «نظم» تازه‌ای از «حاکمیت» تولید می‌کنند که «قانون» سنتی، «توصیف» نمی‌کند.  ۴. نقدها و چالش‌ها ۱. «قدرت بر رسانه» و «قدرت رسانه» مرز «کمرنگ» دارند: «تدوین» و «تلقین» در هم تنیده‌اند و «سنجش» مستقل آن‌ها دشوار است. ۲. «نظم رسانه‌ای» به «قانون» تقلیل می‌یابد: «نظم‌های» خودتنظیمی، «فرهنگی» و «اقتصادی» اغل', '3fac4a43baf9cb53b1d731569a5786524f95935d8bad041f13a4c208f0ae4375', 856, 'ch-doc-card-513-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3fac4a43baf9cb53b1d731569a5786524f95935d8bad041f13a4c208f0ae4375', token_count=856, vector_point_id='ch-doc-card-513-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-513-10', 'doc-card-513', 'sec-card-513-5', 10, 'وقتی «رسانه‌ای» از «انتخابات» گزارش می‌دهد، «موضوعات» و «زبان» آن، «مشروعیت‌سازی» است: «نحوه‌ی» گزارش، «حاکمیت» را «طبیعی» می‌نمایاند.  «مالکیت رسانه‌ای» در عمل: وقتی یک «گروه اقتصادی» «رسانه» می‌خرد، «محتوا» از «پیش» شکل می‌گیرد؛ «مالکیت» و «اقتصاد» در هم تنیده‌اند.  «نظم رسانه‌ای» در «ایران» به «قانون» و «نظم دولتی» تقلیل نمی‌یابد: «نظم‌های» خودتنظیمی (کمیته‌های رسانه‌ای) و «نظم‌های» فرهنگی (سلیقه‌ی حاکم) هم در کانون‌اند.  «سیاست‌گذاری رسانه‌ای» در «اتحادیه اروپا» با «قانون خدمات رسانه‌ای» و «حریم خصوصی» تعریف می‌شود و «رقابت» بین «پلتفرم‌ها» و «رسانه‌های» سنتی، «موضوع» اصلی است.', '7c50682f15810007e46a9d561f490fced23d4f2c46a9a4ca16577fdc14239d48', 1069, 'ch-doc-card-513-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7c50682f15810007e46a9d561f490fced23d4f2c46a9a4ca16577fdc14239d48', token_count=1069, vector_point_id='ch-doc-card-513-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-513-11', 'doc-card-513', 'sec-card-513-5', 11, '» تعریف می‌شود و «رقابت» بین «پلتفرم‌ها» و «رسانه‌های» سنتی، «موضوع» اصلی است.  «قدرت رسانه» در «بحران» به «تدوین» واقعیت تبدیل می‌شود: «نحوه‌ی» گزارش «بحران»، «واکنش» عمومی را «تعیین» می‌کند.  «حاکمیت رسانه‌ای» در «عصر دیجیتال» با «پلتفرم‌ها» «بازتعریف» می‌شود: «الگوریتم» و «داده»، «نظم» تازه‌ای از «حاکمیت» تولید می‌کنند که «قانون» سنتی، «توصیف» نمی‌کند.', '1fa66ac8dd596d4449515b08a71d6c7b64a2df21ee3498bae7353f59043c34c4', 649, 'ch-doc-card-513-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1fa66ac8dd596d4449515b08a71d6c7b64a2df21ee3498bae7353f59043c34c4', token_count=649, vector_point_id='ch-doc-card-513-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-513-12', 'doc-card-513', 'sec-card-513-6', 12, '۱. «قدرت بر رسانه» و «قدرت رسانه» مرز «کمرنگ» دارند: «تدوین» و «تلقین» در هم تنیده‌اند و «سنجش» مستقل آن‌ها دشوار است. ۲. «نظم رسانه‌ای» به «قانون» تقلیل می‌یابد: «نظم‌های» خودتنظیمی، «فرهنگی» و «اقتصادی» اغلب نادیده گرفته می‌شوند. ۳. «مالکیت» در «عصر دیجیتال» «بازتعریف» می‌شود: «مالکیت» پلتفرم، «مالکیت» سنتی نیست و «اقتصاد داده» و «الگوریتم»، «ساختار» تازه‌ای تولید می‌کنند. ۴. «مشروعیت‌سازی» مفهوم «غیرقابل انکار» است: نشان دادن «مشروعیت‌سازی» در عمل، «تفسیر» نیاز دارد و «داده» به‌کلی، «تأیید» نمی‌کند. ۵. «رقابت رسانه‌ای» در «بافت‌های دولتی» «محدود» اس', '812da107625645cc46b32ecb992a477b60ad1e6db3cbfda988f18d1c5dd53aea', 1014, 'ch-doc-card-513-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='812da107625645cc46b32ecb992a477b60ad1e6db3cbfda988f18d1c5dd53aea', token_count=1014, vector_point_id='ch-doc-card-513-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-513-13', 'doc-card-513', 'sec-card-513-7', 13, 'ت: «رقابت» به «تقابل» بین «رسانه‌های دولتی» و «غیروادبی» تقلیل می‌یابد. ۶. «حاکمیت رسانه‌ای» و «نظارت» در هم تنیده‌اند: «نظم» و «نظارت» مرز «کمرنگ» دارند و «نظم» می‌تواند «ابزار» «نظارت» شود. ۷. «قدرت» و «اقتصاد» از هم جدا نمی‌شوند: «قدرت» رسانه، بدون «اقتصاد» «توصیف» نمی‌شود و «اقتصاد» رسانه، بدون «قدرت» «بازسازی» نمی‌شود. ۸. «نظم» و «حاکمیت» مرز «نامشخص» دارند: «نظم رسانه‌ای» می‌تواند «ابزار» «حاکمیت» باشد و «حاکمیت»، «نظم» را «بازتولید» می‌کند. ۹. «الگوریتم» و «حاکمیت» «بازتعریف» می‌شوند: «قدرت» در «الگوریتم» پنهان است و «نظم» سنتی، «توصیف» نمی‌کند.', 'c4884d28f520e4268fde03d624764b7796c6e5d841f492f3cfe3f8f445ca5862', 1014, 'ch-doc-card-513-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c4884d28f520e4268fde03d624764b7796c6e5d841f492f3cfe3f8f445ca5862', token_count=1014, vector_point_id='ch-doc-card-513-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-513-14', 'doc-card-513', 'sec-card-513-10', 14, 'کتاب «قدرت و رسانه» (مورگن و همکاران، ۱۹۹۸)؛ کتاب «نظم رسانه‌ای» (نیکلسون و همکاران، ۲۰۰۴)؛ کتاب «سیاست‌گذاری رسانه‌ای» (بن و همکاران، ۲۰۰۲)؛ کتاب «اقتصادسیاست رسانه» (گورینگ و پاول، ۱۹۹۴).', '3936fe241b543d42170763c866dd088d055f4ed4434b7cf1089f51425607d1ae', 343, 'ch-doc-card-513-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3936fe241b543d42170763c866dd088d055f4ed4434b7cf1089f51425607d1ae', token_count=343, vector_point_id='ch-doc-card-513-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-514-0', 'doc-card-514', NULL, 0, 'این حوزه رسانه را نهاد سیاسی‌ای می‌بیند که با مالکیت، نظم‌گذاری و باز تولید معنا، مشروعیت‌سازی و رقابت سیاسی را شکل می‌دهد؛ پرسش محوری آن رابطه دوسویّه قدرت و رسانه در نظام‌های دموکراتیک است.', 'bad00c86cf89b8ce68e902eca9fe1795c44047e26add98efe1823b030b9e4477', 347, 'ch-doc-card-514-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bad00c86cf89b8ce68e902eca9fe1795c44047e26add98efe1823b030b9e4477', token_count=347, vector_point_id='ch-doc-card-514-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-514-1', 'doc-card-514', 'sec-card-514-1', 1, 'قدرت، سیاست و حاکمیت رسانه  نظریههای دموکراسی مشورتی و رسانهای.', '01f85321715f28fe2c8d52f4d5a066b2c61b768cd9a89e792e1cbe18df794dc4', 114, 'ch-doc-card-514-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='01f85321715f28fe2c8d52f4d5a066b2c61b768cd9a89e792e1cbe18df794dc4', token_count=114, vector_point_id='ch-doc-card-514-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-514-2', 'doc-card-514', 'sec-card-514-2', 2, '۱. بنیان و منطق نظری رسانه و دموکراسی رسانه را «سازوکار حاکمیت» می‌داند: نه صرفاَ «ابزار» دولت، بلکه «زمینه‌ی» قدرت، رقابت و مشروعیت‌سازی. نظریه‌پردازان نشان داد که «قدرت» بر رسانه از سه مسیر عمل می‌کند: «مالکیت» (چه کسی مالک است)، «محتوا» (چه چیزی گفته می‌شود) و «فرمت» (چگونه گفته می‌شود). این چارچوب در سطح کلان تحلیل، رسانه را از «ابزار» به «نهاد سیاسی» ارتقا می‌دهد.  بر اساس رسانه و دموکراسی، «حاکمیت رسانه» یعنی «مدیریت جریان معنا» در سطح کلان: «سیاست‌گذاری رسانه‌ای»، «قانون» و «نظم‌های» خودتنظیمی، «قواعد بازی» را تعیین می‌کنند. نظریه‌پردازان در این چارچوب، «نظم رسانه‌ای» را نه «پایان» بلکه «نقطه‌ی آغاز» تحلیل قرار داد: نظم، میدان نبرد سیاسی است.', '65c8f420acf18a655429310c50f50d68216416eb47fd55b4107ebdff978c9989', 1194, 'ch-doc-card-514-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='65c8f420acf18a655429310c50f50d68216416eb47fd55b4107ebdff978c9989', token_count=1194, vector_point_id='ch-doc-card-514-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-514-3', 'doc-card-514', 'sec-card-514-2', 3, 'ی» را نه «پایان» بلکه «نقطه‌ی آغاز» تحلیل قرار داد: نظم، میدان نبرد سیاسی است.  رسانه و دموکراسی را می‌توان پاسخی به شکاف میان «نظریه‌ی وابستگی» (رسانه، بازتاب قدرت) و «نظریه‌ی استقلال» (رسانه، حواله‌گر قدرت) دانست: قدرت، نه «بازتاب» بلکه «بازتولید» است. نظریه‌پردازان در این چارچوب، «قدرت رسانه» را «دوسویه» خواند: رسانه هم «تحت تأثیر» قدرت است و هم «تولیدکننده» آن.  ۲. ساختارهای مفهومی • قدرت بر رسانه (Power over Media): «مالکیت»، «فروشگاه» و «نظم» که «محتوا» را از پیش تعیین می‌کنند؛ پرسش «چه کسی تصمیم می‌گیرد؟» در کانون است. • قدرت رسانه (Power of Media): توانایی رسانه در «تدوین» واقعیت، «مشروعیت‌سازی» و «نهادسازی»؛ رسانه، «قدرت نرم» تولید می‌کند.', 'e0f8db419ace2dadbe06b83d3dc1dd00a4d7fa27631d1d9dafb3cb7daded80b0', 1192, 'ch-doc-card-514-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e0f8db419ace2dadbe06b83d3dc1dd00a4d7fa27631d1d9dafb3cb7daded80b0', token_count=1192, vector_point_id='ch-doc-card-514-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-514-4', 'doc-card-514', 'sec-card-514-2', 4, 'در «تدوین» واقعیت، «مشروعیت‌سازی» و «نهادسازی»؛ رسانه، «قدرت نرم» تولید می‌کند. • نظم رسانه‌ای (Media Regulation): «قواعد بازی» رسانه: «قانون»، «نظم‌های» خودتنظیمی و «نظم‌های» دولتی؛ هر «نظم»، انتخاب سیاسی است. • سیاست‌گذاری رسانه‌ای (Media Policy): فرایند «تصمیم‌گیری» درباره‌ی «ساختار»، «مالکیت» و «محتوای» رسانه؛ «نهادها» و «گروه‌های» فشار در کانون‌اند. • مالکیت رسانه‌ای (Media Ownership): «ساختار» مالکیت (تمرکز/تعدد) که «محتوا» را', '0423e57c29d39b0669fee33330a811c9ab2e48d7283814b7ac67cea747190e5f', 792, 'ch-doc-card-514-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0423e57c29d39b0669fee33330a811c9ab2e48d7283814b7ac67cea747190e5f', token_count=792, vector_point_id='ch-doc-card-514-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-514-5', 'doc-card-514', 'sec-card-514-3', 5, '• قدرت بر رسانه (Power over Media): «مالکیت»، «فروشگاه» و «نظم» که «محتوا» را از پیش تعیین می‌کنند؛ پرسش «چه کسی تصمیم می‌گیرد؟» در کانون است. • قدرت رسانه (Power of Media): توانایی رسانه در «تدوین» واقعیت، «مشروعیت‌سازی» و «نهادسازی»؛ رسانه، «قدرت نرم» تولید می‌کند. • نظم رسانه‌ای (Media Regulation): «قواعد بازی» رسانه: «قانون»، «نظم‌های» خودتنظیمی و «نظم‌های» دولتی؛ هر «نظم»، انتخاب سیاسی است. • سیاست‌گذاری رسانه‌ای (Media Policy): فرایند «تصمیم‌گیری» درباره‌ی «ساختار»، «مالکیت» و «محتوای» رسانه؛ «نهادها» و «گروه‌های» فشار در کانون‌اند.', '9c13d9d60f70428338de8f419e6539e1b79fa830e8c2a96fa764fb8e452094ba', 989, 'ch-doc-card-514-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9c13d9d60f70428338de8f419e6539e1b79fa830e8c2a96fa764fb8e452094ba', token_count=989, vector_point_id='ch-doc-card-514-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-514-6', 'doc-card-514', 'sec-card-514-3', 6, 'ی «ساختار»، «مالکیت» و «محتوای» رسانه؛ «نهادها» و «گروه‌های» فشار در کانون‌اند. • مالکیت رسانه‌ای (Media Ownership): «ساختار» مالکیت (تمرکز/تعدد) که «محتوا» را از پیش شکل می‌دهد؛ «مالکیت» و «اقتصاد» در هم تنیده‌اند. • مشروعیت‌سازی (Legitimation): رسانه با «گزارش» و «بازنمایی»، «حاکمیت» را «مشروع» می‌نمایاند؛ «تصویر» و «زبان»، ابزار «مشروعیت‌سازی»‌اند. • حاکمیت رسانه‌ای (Media Governance): «مدیریت کلان» رسانه: «نهادها»، «قوانین»، «نظم‌ها» و «نهادسازی» که «جریان معنا» را «تنظیم» می‌کنند. • رقابت رسانه‌ای (Media Competition): «رقابت» بین نهادهای رسانه‌ای برای «دسته‌ی» هدف، «سرمایه» و «اعتبار»؛ «رقابت» و «تمرکز» در «موازنه»‌اند.', 'e14293519f380356fbb4aacac333490eee67597b70dc853348070a5b60a65d3e', 1149, 'ch-doc-card-514-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e14293519f380356fbb4aacac333490eee67597b70dc853348070a5b60a65d3e', token_count=1149, vector_point_id='ch-doc-card-514-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-514-7', 'doc-card-514', 'sec-card-514-4', 7, 'از پیش شکل می‌دهد؛ «مالکیت» و «اقتصاد» در هم تنیده‌اند. • مشروعیت‌سازی (Legitimation): رسانه با «گزارش» و «بازنمایی»، «حاکمیت» را «مشروع» می‌نمایاند؛ «تصویر» و «زبان»، ابزار «مشروعیت‌سازی»‌اند. • حاکمیت رسانه‌ای (Media Governance): «مدیریت کلان» رسانه: «نهادها»، «قوانین»، «نظم‌ها» و «نهادسازی» که «جریان معنا» را «تنظیم» می‌کنند. • رقابت رسانه‌ای (Media Competition): «رقابت» بین نهادهای رسانه‌ای برای «دسته‌ی» هدف، «سرمایه» و «اعتبار»؛ «رقابت» و «تمرکز» در «موازنه»‌اند.  ۳. نمونه‌های تحلیلی وقتی «رسانه‌ای» از «انتخابات» گزارش می‌دهد، «موضوعات» و «زبان» آن، «مشروعیت‌سازی» است: «نحوه‌ی» گزارش، «حاکمیت» را «طبیعی» می‌نمایاند.', '919d8acb8a13824de08922d0a73d694306b4088aee8246dc413d492692df878e', 1141, 'ch-doc-card-514-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='919d8acb8a13824de08922d0a73d694306b4088aee8246dc413d492692df878e', token_count=1141, vector_point_id='ch-doc-card-514-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-514-8', 'doc-card-514', 'sec-card-514-4', 8, '«زبان» آن، «مشروعیت‌سازی» است: «نحوه‌ی» گزارش، «حاکمیت» را «طبیعی» می‌نمایاند.  «مالکیت رسانه‌ای» در عمل: وقتی یک «گروه اقتصادی» «رسانه» می‌خرد، «محتوا» از «پیش» شکل می‌گیرد؛ «مالکیت» و «اقتصاد» در هم تنیده‌اند.  «نظم رسانه‌ای» در «ایران» به «قانون» و «نظم دولتی» تقلیل نمی‌یابد: «نظم‌های» خودتنظیمی (کمیته‌های رسانه‌ای) و «نظم‌های» فرهنگی (سلیقه‌ی حاکم) هم در کانون‌اند.  «سیاست‌گذاری رسانه‌ای» در «اتحادیه اروپا» با «قانون خدمات رسانه‌ای» و «حریم خصوصی» تعریف می‌شود و «رقابت» بین «پلتفرم‌ها» و «رسانه‌های» سنتی، «موضوع» اصلی است.  «قدرت رسانه» در «بحران» به «تدوین» واقعیت تبدیل می‌شود: «نحوه‌ی» گزارش «بحران»، «واکنش» عمومی را «تعیین» می‌کند.', '057050f37b71e01990190aaf59926ad717dcacae89e107146383712e8573e87e', 1174, 'ch-doc-card-514-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='057050f37b71e01990190aaf59926ad717dcacae89e107146383712e8573e87e', token_count=1174, vector_point_id='ch-doc-card-514-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-514-9', 'doc-card-514', 'sec-card-514-4', 9, 'واقعیت تبدیل می‌شود: «نحوه‌ی» گزارش «بحران»، «واکنش» عمومی را «تعیین» می‌کند.  «حاکمیت رسانه‌ای» در «عصر دیجیتال» با «پلتفرم‌ها» «بازتعریف» می‌شود: «الگوریتم» و «داده»، «نظم» تازه‌ای از «حاکمیت» تولید می‌کنند که «قانون» سنتی، «توصیف» نمی‌کند.  ۴. نقدها و چالش‌ها ۱. «قدرت بر رسانه» و «قدرت رسانه» مرز «کمرنگ» دارند: «تدوین» و «تلقین» در هم تنیده‌اند و «سنجش» مستقل آن‌ها دشوار است. ۲. «نظم رسانه‌ای» به «قانون» تقلیل می‌یابد: «نظم‌های» خودتنظیمی، «فرهنگی» و «اقتصادی» اغلب ن', '1061d39c712c35a5c161960953bc6fb37a0c1b149c4555327293fa2a387af2ab', 861, 'ch-doc-card-514-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1061d39c712c35a5c161960953bc6fb37a0c1b149c4555327293fa2a387af2ab', token_count=861, vector_point_id='ch-doc-card-514-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-514-10', 'doc-card-514', 'sec-card-514-5', 10, 'وقتی «رسانه‌ای» از «انتخابات» گزارش می‌دهد، «موضوعات» و «زبان» آن، «مشروعیت‌سازی» است: «نحوه‌ی» گزارش، «حاکمیت» را «طبیعی» می‌نمایاند.  «مالکیت رسانه‌ای» در عمل: وقتی یک «گروه اقتصادی» «رسانه» می‌خرد، «محتوا» از «پیش» شکل می‌گیرد؛ «مالکیت» و «اقتصاد» در هم تنیده‌اند.  «نظم رسانه‌ای» در «ایران» به «قانون» و «نظم دولتی» تقلیل نمی‌یابد: «نظم‌های» خودتنظیمی (کمیته‌های رسانه‌ای) و «نظم‌های» فرهنگی (سلیقه‌ی حاکم) هم در کانون‌اند.  «سیاست‌گذاری رسانه‌ای» در «اتحادیه اروپا» با «قانون خدمات رسانه‌ای» و «حریم خصوصی» تعریف می‌شود و «رقابت» بین «پلتفرم‌ها» و «رسانه‌های» سنتی، «موضوع» اصلی است.', '7c50682f15810007e46a9d561f490fced23d4f2c46a9a4ca16577fdc14239d48', 1069, 'ch-doc-card-514-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7c50682f15810007e46a9d561f490fced23d4f2c46a9a4ca16577fdc14239d48', token_count=1069, vector_point_id='ch-doc-card-514-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-514-11', 'doc-card-514', 'sec-card-514-5', 11, '» تعریف می‌شود و «رقابت» بین «پلتفرم‌ها» و «رسانه‌های» سنتی، «موضوع» اصلی است.  «قدرت رسانه» در «بحران» به «تدوین» واقعیت تبدیل می‌شود: «نحوه‌ی» گزارش «بحران»، «واکنش» عمومی را «تعیین» می‌کند.  «حاکمیت رسانه‌ای» در «عصر دیجیتال» با «پلتفرم‌ها» «بازتعریف» می‌شود: «الگوریتم» و «داده»، «نظم» تازه‌ای از «حاکمیت» تولید می‌کنند که «قانون» سنتی، «توصیف» نمی‌کند.', '1fa66ac8dd596d4449515b08a71d6c7b64a2df21ee3498bae7353f59043c34c4', 649, 'ch-doc-card-514-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1fa66ac8dd596d4449515b08a71d6c7b64a2df21ee3498bae7353f59043c34c4', token_count=649, vector_point_id='ch-doc-card-514-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-514-12', 'doc-card-514', 'sec-card-514-6', 12, '۱. «قدرت بر رسانه» و «قدرت رسانه» مرز «کمرنگ» دارند: «تدوین» و «تلقین» در هم تنیده‌اند و «سنجش» مستقل آن‌ها دشوار است. ۲. «نظم رسانه‌ای» به «قانون» تقلیل می‌یابد: «نظم‌های» خودتنظیمی، «فرهنگی» و «اقتصادی» اغلب نادیده گرفته می‌شوند. ۳. «مالکیت» در «عصر دیجیتال» «بازتعریف» می‌شود: «مالکیت» پلتفرم، «مالکیت» سنتی نیست و «اقتصاد داده» و «الگوریتم»، «ساختار» تازه‌ای تولید می‌کنند. ۴. «مشروعیت‌سازی» مفهوم «غیرقابل انکار» است: نشان دادن «مشروعیت‌سازی» در عمل، «تفسیر» نیاز دارد و «داده» به‌کلی، «تأیید» نمی‌کند. ۵. «رقابت رسانه‌ای» در «بافت‌های دولتی» «محدود» اس', '812da107625645cc46b32ecb992a477b60ad1e6db3cbfda988f18d1c5dd53aea', 1014, 'ch-doc-card-514-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='812da107625645cc46b32ecb992a477b60ad1e6db3cbfda988f18d1c5dd53aea', token_count=1014, vector_point_id='ch-doc-card-514-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-514-13', 'doc-card-514', 'sec-card-514-7', 13, 'ت: «رقابت» به «تقابل» بین «رسانه‌های دولتی» و «غیروادبی» تقلیل می‌یابد. ۶. «حاکمیت رسانه‌ای» و «نظارت» در هم تنیده‌اند: «نظم» و «نظارت» مرز «کمرنگ» دارند و «نظم» می‌تواند «ابزار» «نظارت» شود. ۷. «قدرت» و «اقتصاد» از هم جدا نمی‌شوند: «قدرت» رسانه، بدون «اقتصاد» «توصیف» نمی‌شود و «اقتصاد» رسانه، بدون «قدرت» «بازسازی» نمی‌شود. ۸. «نظم» و «حاکمیت» مرز «نامشخص» دارند: «نظم رسانه‌ای» می‌تواند «ابزار» «حاکمیت» باشد و «حاکمیت»، «نظم» را «بازتولید» می‌کند. ۹. «الگوریتم» و «حاکمیت» «بازتعریف» می‌شوند: «قدرت» در «الگوریتم» پنهان است و «نظم» سنتی، «توصیف» نمی‌کند.', 'c4884d28f520e4268fde03d624764b7796c6e5d841f492f3cfe3f8f445ca5862', 1014, 'ch-doc-card-514-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c4884d28f520e4268fde03d624764b7796c6e5d841f492f3cfe3f8f445ca5862', token_count=1014, vector_point_id='ch-doc-card-514-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-514-14', 'doc-card-514', 'sec-card-514-10', 14, 'کتاب «قدرت و رسانه» (مورگن و همکاران، ۱۹۹۸)؛ کتاب «نظم رسانه‌ای» (نیکلسون و همکاران، ۲۰۰۴)؛ کتاب «سیاست‌گذاری رسانه‌ای» (بن و همکاران، ۲۰۰۲)؛ کتاب «اقتصادسیاست رسانه» (گورینگ و پاول، ۱۹۹۴).', '3936fe241b543d42170763c866dd088d055f4ed4434b7cf1089f51425607d1ae', 343, 'ch-doc-card-514-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3936fe241b543d42170763c866dd088d055f4ed4434b7cf1089f51425607d1ae', token_count=343, vector_point_id='ch-doc-card-514-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-515-0', 'doc-card-515', NULL, 0, 'قطعیت تکنولوژیک (مکلوهان) فناوری را عنصر فعالی‌ساز و دگرساز نظم اجتماعی می‌داند؛ طراحی زیرساخت و امکان‌پذیری (affordance) الگوریتمی، نه صرفا محتوای عبوری، رفتار و ساختار قدرت را بازنشانی می‌کند.', '074e188bf897349b458622642e7a04b539f1dad0b41cb0dbaf77abcd22ad8789', 352, 'ch-doc-card-515-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='074e188bf897349b458622642e7a04b539f1dad0b41cb0dbaf77abcd22ad8789', token_count=352, vector_point_id='ch-doc-card-515-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-515-1', 'doc-card-515', 'sec-card-515-1', 1, 'اینترنت، پلتفرم و فناوری  فناوری محرک اصلی تغییرsocial.', '4154f0b58f38f7a15edf4fa21abe6ab0c5f224d5aa0dc707949d3f1d7f58acf7', 99, 'ch-doc-card-515-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4154f0b58f38f7a15edf4fa21abe6ab0c5f224d5aa0dc707949d3f1d7f58acf7', token_count=99, vector_point_id='ch-doc-card-515-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-515-2', 'doc-card-515', 'sec-card-515-2', 2, '۱. بنیان و منطق نظری قطعیت تکنولوژیک اینترنت و پلتفرم‌های دیجیتال را محیط رسانه‌ای تازه‌ای می‌داند که منطق ارتباط، تولید و تبادل را دگرگون کرده است. مکلوهان استدلال کرد که در عصر شبکه، واحد تحلیل دیگر پیام یا کانال نیست، بلکه پلتفرم است: زیرساخت فنی-اقتصادی که کاربران، محتوا و سرمایه را به هم وصل می‌کند. در این چارچوب، خودِ طراحی زیرساخت — پروتکل، کارکرد و الگوریتم — رفتار اجتماعی را شکل می‌دهد، نه صرفاَ محتوای عبوری.  بر اساس قطعیت تکنولوژیک، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است. مکلوهان فرایندی را تحلیل کرد که فناوری تازه، از ورود و پذیرش، به زندگی روزمره می‌آمیزد، نقش‌ها و روابط را بازنشانی می‌کند و سرانجام «طبیعی» به نظر می‌رسد.', '08759809648a35a5f684a08dec33778744c1bf2a58cc75cd074fabcbeffb79a9', 1229, 'ch-doc-card-515-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='08759809648a35a5f684a08dec33778744c1bf2a58cc75cd074fabcbeffb79a9', token_count=1229, vector_point_id='ch-doc-card-515-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-515-3', 'doc-card-515', 'sec-card-515-2', 3, 'ره می‌آمیزد، نقش‌ها و روابط را بازنشانی می‌کند و سرانجام «طبیعی» به نظر می‌رسد. ادعای محوری این است که هر نوسازی فناورانه با یک بازنشانی نظم اجتماعی همراه است و مطالعه‌ی فناوری را نمی‌توان از مطالعه‌ی قدرت، اقتصاد و فرهنگ جدا کرد.  قطعیت تکنولوژیک پلتفرم را بوم‌زمینه‌ای چندوجهی می‌داند که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند. مکلوهان تأکید کرد که پلتفرم هم‌زمان فناوری، بازار و شیوه‌ی حکمرانی است و قدرت آن از کنترل بر «قوانین بازی» — چشم‌اندازی، دسترسی و معامله — می‌آید. این رویکرد، تحلیل پلتفرم را در تقاطع جامعه‌شناسی فناوری، اقتصاد و حکمرانی جای می‌دهد.  ۲.', '30ac16ece5ada658f7f6e1d205d58ab229a5ac71edefb490b5dee51a98d50761', 1092, 'ch-doc-card-515-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='30ac16ece5ada658f7f6e1d205d58ab229a5ac71edefb490b5dee51a98d50761', token_count=1092, vector_point_id='ch-doc-card-515-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-515-4', 'doc-card-515', 'sec-card-515-2', 4, '، تحلیل پلتفرم را در تقاطع جامعه‌شناسی فناوری، اقتصاد و حکمرانی جای می‌دهد.  ۲. ساختارهای مفهومی • پلتفرم (Platform): زیرساخت دیجیتالی که بازیگران متعدد را گرد هم می‌آورد و تعامل آن‌ها را میانجی می‌کند. • کارکرد/امکان (Affordance): قابلیت‌های کنشی که طراحی فناوری به کاربر پیشنهاد می‌دهد و عادت‌های او را شکل می‌دهد. • اثر شبکه‌ای (Network Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود. • حکمرانی الگوریتمی (Algorithmic Governance): فرایندی که الگوریتم‌ها درباره‌ی چشم‌اندازی، اولویت‌بندی و دسترسی تصمیم می‌گیرند. • زیرساخت دیجیتال (Digital Infrastructure): لایه‌ی فنی پایینی (سرور، پروتکل، شبکه) که خدمات بر آن ساخته می‌شوند. • پذیرش', '15d2e9750ec9ca4ac3dd754353a42020ccf6116c78ce4c011ab779cc0f1658c8', 1212, 'ch-doc-card-515-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='15d2e9750ec9ca4ac3dd754353a42020ccf6116c78ce4c011ab779cc0f1658c8', token_count=1212, vector_point_id='ch-doc-card-515-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-515-5', 'doc-card-515', 'sec-card-515-3', 5, '• پلتفرم (Platform): زیرساخت دیجیتالی که بازیگران متعدد را گرد هم می‌آورد و تعامل آن‌ها را میانجی می‌کند. • کارکرد/امکان (Affordance): قابلیت‌های کنشی که طراحی فناوری به کاربر پیشنهاد می‌دهد و عادت‌های او را شکل می‌دهد. • اثر شبکه‌ای (Network Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود. • حکمرانی الگوریتمی (Algorithmic Governance): فرایندی که الگوریتم‌ها درباره‌ی چشم‌اندازی، اولویت‌بندی و دسترسی تصمیم می‌گیرند. • زیرساخت دیجیتال (Digital Infrastructure): لایه‌ی فنی پایینی (سرور، پروتکل، شبکه) که خدمات بر آن ساخته می‌شوند. • پذیرش (Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن.', '3c61d5d146cf756011fcb316faa0502d957ac65ac19e581e862b4f675e0dc33f', 1167, 'ch-doc-card-515-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3c61d5d146cf756011fcb316faa0502d957ac65ac19e581e862b4f675e0dc33f', token_count=1167, vector_point_id='ch-doc-card-515-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-515-6', 'doc-card-515', 'sec-card-515-3', 6, '• پذیرش (Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن. • شکاف دیجیتال (Digital Divide): نابرابری ساختاری در دسترسی به فناوری دیجیتال، استفاده از آن و بهره‌مندی از آن. • پلتفرمی‌شدن (Platformization): فرایند گسترش منطق و ارزش‌های پلتفرم به حوزه‌های دیگر زندگی اجتماعی.', '058868170e5dcb763251870b437b68e333b102c73b1c8f9ac8c3bbac174cd0e9', 530, 'ch-doc-card-515-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='058868170e5dcb763251870b437b68e333b102c73b1c8f9ac8c3bbac174cd0e9', token_count=530, vector_point_id='ch-doc-card-515-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-515-7', 'doc-card-515', 'sec-card-515-4', 7, '(Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن. • شکاف دیجیتال (Digital Divide): نابرابری ساختاری در دسترسی به فناوری دیجیتال، استفاده از آن و بهره‌مندی از آن. • پلتفرمی‌شدن (Platformization): فرایند گسترش منطق و ارزش‌های پلتفرم به حوزه‌های دیگر زندگی اجتماعی.  ۳. نمونه‌های تحلیلی ظهور پلتفرم‌های ویدیویی کوتاه امروز کمتر به کیفیت محتوای تولیدی بازمی‌گردد و بیشتر به طراحی فید الگوریتمی: فید با کارکرد «اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.', 'a4b2a59f26f3ac49c4934554c27c2132526de6fc9dc05ee5f6c80be0169596c5', 919, 'ch-doc-card-515-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a4b2a59f26f3ac49c4934554c27c2132526de6fc9dc05ee5f6c80be0169596c5', token_count=919, vector_point_id='ch-doc-card-515-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-515-8', 'doc-card-515', 'sec-card-515-4', 8, 'اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.  حکمرانی پلتفرم‌های بزرگ — نظارت بر محتوا، تعلیق حساب، اولویت‌بندی در جست‌وجو — در عمل نوعی قدرت شبه‌قضایی بر میلیاردها کاربر است که بدون شفافیت و پاسخگویی معیارهای دولتی اعمال می‌شود.  گوشی‌های هوشمند در عرض چند سال عادات ارتباط اجتماعی، خبرخوانی و خرید را تغییر داده‌اند؛ نمونه‌ی کلاسیکی از اینکه چگونه پذیرش یک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.  جابه‌جایی بسیاری از خدمات عمومی و تجاری به اپلیکیشن‌ها نمونه‌ای از پلتفرمی‌شدن است: منطق امتیازدهی، حساب کاربری و داده وارد حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).', 'cdb4fa11f8d231ff735dedf288a7c9d18381c00e6e762e0b8aaca4fe3338ad00', 1223, 'ch-doc-card-515-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cdb4fa11f8d231ff735dedf288a7c9d18381c00e6e762e0b8aaca4fe3338ad00', token_count=1223, vector_point_id='ch-doc-card-515-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-515-9', 'doc-card-515', 'sec-card-515-4', 9, 'حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).  رقابت صنعت استریم بر «محتوای انحصاری» استراتژی است برای بهره‌گیری از اثر شبکه‌ای: تمرکز مخاطب روی یک پلتفرم، ارزش آن را هم برای کاربران و هم برای تولیدکنندگان بزرگ‌تر می‌کند.  شکاف دیجیتال تنها درباره‌ی دسترسی به اینترنت نیست: تفاوت میان جوانی شهری که محتوا تولید می‌کند و مسنی روستایی که مصرف‌کننده‌ی منفعل است، نشان می‌دهد شکاف در سطح مهارت، زبان و قدرت اقتصادی نیز کار می‌کند.  ۴. نقدها و چالش‌ها ۱. ریسک جبرگرایی فناورانه: چارچوب «طراحی فناوری رفتار را شکل می‌دهد» می‌تواند به غفلت از انتخاب‌های اجتماعی، سیاسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲.', '4c8a35b8d7922ea06254566270f4f2631332f3bdcde0a1e3f70b05a02715fca1', 1218, 'ch-doc-card-515-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4c8a35b8d7922ea06254566270f4f2631332f3bdcde0a1e3f70b05a02715fca1', token_count=1218, vector_point_id='ch-doc-card-515-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-515-10', 'doc-card-515', 'sec-card-515-4', 10, 'اسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲. ناهمگنی مفهوم پلتفرم: واژه‌ی پلتفرم از سیستم‌عامل تا بازار آنلاین را پوشش می‌دهد و نتیجه‌گیری', '8ea8ec4f2dd3fb016da07c90ab96fef9e6b77b3b524f2dc5e4c669dc654e142a', 314, 'ch-doc-card-515-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8ea8ec4f2dd3fb016da07c90ab96fef9e6b77b3b524f2dc5e4c669dc654e142a', token_count=314, vector_point_id='ch-doc-card-515-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-515-11', 'doc-card-515', 'sec-card-515-5', 11, 'ظهور پلتفرم‌های ویدیویی کوتاه امروز کمتر به کیفیت محتوای تولیدی بازمی‌گردد و بیشتر به طراحی فید الگوریتمی: فید با کارکرد «اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.  حکمرانی پلتفرم‌های بزرگ — نظارت بر محتوا، تعلیق حساب، اولویت‌بندی در جست‌وجو — در عمل نوعی قدرت شبه‌قضایی بر میلیاردها کاربر است که بدون شفافیت و پاسخگویی معیارهای دولتی اعمال می‌شود.  گوشی‌های هوشمند در عرض چند سال عادات ارتباط اجتماعی، خبرخوانی و خرید را تغییر داده‌اند؛ نمونه‌ی کلاسیکی از اینکه چگونه پذیرش یک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.', '636ba3dc6888936f1a685d93cce595caa0f4a53f230bfe4d00f0a25d7ebcf916', 1074, 'ch-doc-card-515-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='636ba3dc6888936f1a685d93cce595caa0f4a53f230bfe4d00f0a25d7ebcf916', token_count=1074, vector_point_id='ch-doc-card-515-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-515-12', 'doc-card-515', 'sec-card-515-5', 12, 'ک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.  جابه‌جایی بسیاری از خدمات عمومی و تجاری به اپلیکیشن‌ها نمونه‌ای از پلتفرمی‌شدن است: منطق امتیازدهی، حساب کاربری و داده وارد حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).  رقابت صنعت استریم بر «محتوای انحصاری» استراتژی است برای بهره‌گیری از اثر شبکه‌ای: تمرکز مخاطب روی یک پلتفرم، ارزش آن را هم برای کاربران و هم برای تولیدکنندگان بزرگ‌تر می‌کند.  شکاف دیجیتال تنها درباره‌ی دسترسی به اینترنت نیست: تفاوت میان جوانی شهری که محتوا تولید می‌کند و مسنی روستایی که مصرف‌کننده‌ی منفعل است، نشان می‌دهد شکاف در سطح مهارت، زبان و قدرت اقتصادی نیز کار می‌کند.', 'e3f0eb156fbda3efdb1f2e84350a04d71dda4dc87fff0d4186a864617a061e62', 1205, 'ch-doc-card-515-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e3f0eb156fbda3efdb1f2e84350a04d71dda4dc87fff0d4186a864617a061e62', token_count=1205, vector_point_id='ch-doc-card-515-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-515-13', 'doc-card-515', 'sec-card-515-6', 13, '۱. ریسک جبرگرایی فناورانه: چارچوب «طراحی فناوری رفتار را شکل می‌دهد» می‌تواند به غفلت از انتخاب‌های اجتماعی، سیاسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲. ناهمگنی مفهوم پلتفرم: واژه‌ی پلتفرم از سیستم‌عامل تا بازار آنلاین را پوشش می‌دهد و نتیجه‌گیری‌های کلی از یک نوع، لازم نیست به نوع دیگر بربخشد. ۳. غرب‌مندی پژوهش: بیشتر مطالعات کلاسیک بر بستر آمریکایی تمرکز دارند و ویژگی‌های رشد پلتفرم در مناطق دیگر (از جمله جنوب جهانی) کمتر پوشش داده شده است. ۴. سرعت تغییر: سرعت دگرگونی فناوری از سرعت تولید تئوری سریع‌تر است و بسیاری از مدل‌ها پیش از آنکه آزمون شوند، کهنه می‌شوند. ۵. جعبه‌ی سیاه الگوریتم: مبهم‌بودن الگوریتم‌ه', '34971c15146ca17ec874cd3416b1e60d2d48b22da945b7fc7a7d255e541f719c', 1189, 'ch-doc-card-515-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='34971c15146ca17ec874cd3416b1e60d2d48b22da945b7fc7a7d255e541f719c', token_count=1189, vector_point_id='ch-doc-card-515-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-515-14', 'doc-card-515', 'sec-card-515-7', 14, 'ایی که ادعاهای چارچوب بر آن‌ها استوار است، آزمون مستقل ادعاها را دشوار می‌کند. ۶. غفلت از شرایط مادی: تمرکز بر منطق «شبکه» می‌تواند تصویر بسازد که فناوری دیجیتال «بی‌وزن» است، درحالی‌که به مراکز داده‌ی پرمصرف انرژی، استخراج منابع و نیروی کار وابسته است. ۷. ابهام مرز «طراحی» و «رفتار»: اثبات اینکه رفتاری خاص محصول یک کارکرد است — نه نتیجه‌ی عادات اجتماعی و هنجارهای پیشین — بسیار دشوار است. ۸. مسئله‌ی قدرت: چارچوب گاه «حکمرانی» پلتفرم را توصیف می‌کند بدون آنکه ساختار مالکیت و منافع سیاسی پشت آن را عمیق تحلیل کند. ۹. تعمیم میان‌فرهنگی: پذیرش و اهلی‌سازی فناوری در فرهنگ‌ها به‌شدت متفاوت است و مدل ساخته‌شده در یک بستر، در بستر دیگر گمراه‌کننده می‌شود.', '1dca1cba3657dc9eb15a7fb9271b08cd7e5efc3b4e0380a2aa2f7eb41074c6f3', 1189, 'ch-doc-card-515-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1dca1cba3657dc9eb15a7fb9271b08cd7e5efc3b4e0380a2aa2f7eb41074c6f3', token_count=1189, vector_point_id='ch-doc-card-515-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-515-15', 'doc-card-515', 'sec-card-515-10', 15, 'کتاب «سرمایه‌داری پلتفرمی» (نیک سرنیک، ۲۰۱۷)؛ کتاب «عصر دوم رسانه» (یوهان وان‌دایک، ۲۰۰۵)؛ کتاب «انقلاب پلتفرمی» (پarker، وان آلستاین و چوداری، ۲۰۱۶)؛ استناد مبنا: Castells (2010) بر جامعه‌ی شبکه‌ای.', '0a3c1c145bb3103ffd193cce634d5d1dee4ff4a554a19424194c0f1d290155bf', 361, 'ch-doc-card-515-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0a3c1c145bb3103ffd193cce634d5d1dee4ff4a554a19424194c0f1d290155bf', token_count=361, vector_point_id='ch-doc-card-515-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-516-0', 'doc-card-516', NULL, 0, 'نظریه واسطه‌ای (مایروویتز، ۱۹۸۵) می‌گوید خودِ رسانه و زیرساخت فنی آن، نه محتوای عبوری، ساختار اجتماعی، شناخت و روابط را دگرگون می‌سازد؛ هر نوسازی فناورانه با بازنشانی نظم اجتماعی همراه است.', '039b38b6cdb3ec8805ac962691e70423d0835358165764e5c03d4dbd457783fb', 343, 'ch-doc-card-516-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='039b38b6cdb3ec8805ac962691e70423d0835358165764e5c03d4dbd457783fb', token_count=343, vector_point_id='ch-doc-card-516-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-516-1', 'doc-card-516', 'sec-card-516-1', 1, 'اینترنت، پلتفرم و فناوری  رسانه صحنه اجتماعی را دگرگون میکند.', 'dd437e7c8a84f5243c427149105bdd9ff757515890dcaf4cb54dcc9a0b615020', 110, 'ch-doc-card-516-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='dd437e7c8a84f5243c427149105bdd9ff757515890dcaf4cb54dcc9a0b615020', token_count=110, vector_point_id='ch-doc-card-516-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-516-2', 'doc-card-516', 'sec-card-516-2', 2, '۱. بنیان و منطق نظری نظریه رسانه بهعنوان واسطه اینترنت و پلتفرم‌های دیجیتال را محیط رسانه‌ای تازه‌ای می‌داند که منطق ارتباط، تولید و تبادل را دگرگون کرده است. مایروویتز (۱۹۸۵) استدلال کرد که در عصر شبکه، واحد تحلیل دیگر پیام یا کانال نیست، بلکه پلتفرم است: زیرساخت فنی-اقتصادی که کاربران، محتوا و سرمایه را به هم وصل می‌کند. در این چارچوب، خودِ طراحی زیرساخت — پروتکل، کارکرد و الگوریتم — رفتار اجتماعی را شکل می‌دهد، نه صرفاَ محتوای عبوری.  بر اساس نظریه رسانه بهعنوان واسطه، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است.', '9f3d86293cd7ad5a8cdc44ee7cf499a50fbc43b8086e885b25015407806d06d5', 999, 'ch-doc-card-516-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9f3d86293cd7ad5a8cdc44ee7cf499a50fbc43b8086e885b25015407806d06d5', token_count=999, vector_point_id='ch-doc-card-516-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-516-3', 'doc-card-516', 'sec-card-516-2', 3, 'اسطه، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است. مایروویتز (۱۹۸۵) فرایندی را تحلیل کرد که فناوری تازه، از ورود و پذیرش، به زندگی روزمره می‌آمیزد، نقش‌ها و روابط را بازنشانی می‌کند و سرانجام «طبیعی» به نظر می‌رسد. ادعای محوری این است که هر نوسازی فناورانه با یک بازنشانی نظم اجتماعی همراه است و مطالعه‌ی فناوری را نمی‌توان از مطالعه‌ی قدرت، اقتصاد و فرهنگ جدا کرد.  نظریه رسانه بهعنوان واسطه پلتفرم را بوم‌زمینه‌ای چندوجهی می‌داند که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند.', '6c0a4c905c75d7854aaabe58af20e9ad2a1da59368d78e3c65f0fc51c268d4a2', 978, 'ch-doc-card-516-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6c0a4c905c75d7854aaabe58af20e9ad2a1da59368d78e3c65f0fc51c268d4a2', token_count=978, vector_point_id='ch-doc-card-516-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-516-4', 'doc-card-516', 'sec-card-516-2', 4, 'د که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند. مایروویتز (۱۹۸۵) تأکید کرد که پلتفرم هم‌زمان فناوری، بازار و شیوه‌ی حکمرانی است و قدرت آن از کنترل بر «قوانین بازی» — چشم‌اندازی، دسترسی و معامله — می‌آید. این رویکرد، تحلیل پلتفرم را در تقاطع جامعه‌شناسی فناوری، اقتصاد و حکمرانی جای می‌دهد.  ۲. ساختارهای مفهومی • پلتفرم (Platform): زیرساخت دیجیتالی که بازیگران متعدد را گرد هم می‌آورد و تعامل آن‌ها را میانجی می‌کند. • کارکرد/امکان (Affordance): قابلیت‌های کنشی که طراحی فناوری به کاربر پیشنهاد می‌دهد و عادت‌های او را شکل می‌دهد. • اثر شبکه‌ای (Network Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود.', '1307143e5cb9ee6e03e299c81a172be722b32516801a4127600d2fe9447f7b77', 1209, 'ch-doc-card-516-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1307143e5cb9ee6e03e299c81a172be722b32516801a4127600d2fe9447f7b77', token_count=1209, vector_point_id='ch-doc-card-516-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-516-5', 'doc-card-516', 'sec-card-516-2', 5, 'Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود. • حکمرانی الگوریتمی (Algorithmic Governance): فرایندی که الگوریتم‌ها درباره‌ی چشم‌اندازی، اولویت‌بندی و دسترسی تصمیم می‌گیرند. • زیرساخت دیجیتال (Digital Infrastructure): لایه‌ی فنی پایینی (سرور، پروتکل، شبکه) که', 'bfa22c8ae3bfdb15b3b3d8d27a7c8998e07d6f86b64d6f3f431267817223312e', 530, 'ch-doc-card-516-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bfa22c8ae3bfdb15b3b3d8d27a7c8998e07d6f86b64d6f3f431267817223312e', token_count=530, vector_point_id='ch-doc-card-516-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-516-6', 'doc-card-516', 'sec-card-516-3', 6, '• پلتفرم (Platform): زیرساخت دیجیتالی که بازیگران متعدد را گرد هم می‌آورد و تعامل آن‌ها را میانجی می‌کند. • کارکرد/امکان (Affordance): قابلیت‌های کنشی که طراحی فناوری به کاربر پیشنهاد می‌دهد و عادت‌های او را شکل می‌دهد. • اثر شبکه‌ای (Network Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود. • حکمرانی الگوریتمی (Algorithmic Governance): فرایندی که الگوریتم‌ها درباره‌ی چشم‌اندازی، اولویت‌بندی و دسترسی تصمیم می‌گیرند. • زیرساخت دیجیتال (Digital Infrastructure): لایه‌ی فنی پایینی (سرور، پروتکل، شبکه) که خدمات بر آن ساخته می‌شوند. • پذیرش (Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن.', '3c61d5d146cf756011fcb316faa0502d957ac65ac19e581e862b4f675e0dc33f', 1167, 'ch-doc-card-516-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3c61d5d146cf756011fcb316faa0502d957ac65ac19e581e862b4f675e0dc33f', token_count=1167, vector_point_id='ch-doc-card-516-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-516-7', 'doc-card-516', 'sec-card-516-3', 7, '• پذیرش (Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن. • شکاف دیجیتال (Digital Divide): نابرابری ساختاری در دسترسی به فناوری دیجیتال، استفاده از آن و بهره‌مندی از آن. • پلتفرمی‌شدن (Platformization): فرایند گسترش منطق و ارزش‌های پلتفرم به حوزه‌های دیگر زندگی اجتماعی.', '058868170e5dcb763251870b437b68e333b102c73b1c8f9ac8c3bbac174cd0e9', 530, 'ch-doc-card-516-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='058868170e5dcb763251870b437b68e333b102c73b1c8f9ac8c3bbac174cd0e9', token_count=530, vector_point_id='ch-doc-card-516-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-516-8', 'doc-card-516', 'sec-card-516-4', 8, 'خدمات بر آن ساخته می‌شوند. • پذیرش (Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن. • شکاف دیجیتال (Digital Divide): نابرابری ساختاری در دسترسی به فناوری دیجیتال، استفاده از آن و بهره‌مندی از آن. • پلتفرمی‌شدن (Platformization): فرایند گسترش منطق و ارزش‌های پلتفرم به حوزه‌های دیگر زندگی اجتماعی.  ۳. نمونه‌های تحلیلی ظهور پلتفرم‌های ویدیویی کوتاه امروز کمتر به کیفیت محتوای تولیدی بازمی‌گردد و بیشتر به طراحی فید الگوریتمی: فید با کارکرد «اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.', '14469e748c607a6a296022f2025cfdb73d82b3f36e76d9119f437c3fd5d79c91', 983, 'ch-doc-card-516-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='14469e748c607a6a296022f2025cfdb73d82b3f36e76d9119f437c3fd5d79c91', token_count=983, vector_point_id='ch-doc-card-516-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-516-9', 'doc-card-516', 'sec-card-516-4', 9, 'اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.  حکمرانی پلتفرم‌های بزرگ — نظارت بر محتوا، تعلیق حساب، اولویت‌بندی در جست‌وجو — در عمل نوعی قدرت شبه‌قضایی بر میلیاردها کاربر است که بدون شفافیت و پاسخگویی معیارهای دولتی اعمال می‌شود.  گوشی‌های هوشمند در عرض چند سال عادات ارتباط اجتماعی، خبرخوانی و خرید را تغییر داده‌اند؛ نمونه‌ی کلاسیکی از اینکه چگونه پذیرش یک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.  جابه‌جایی بسیاری از خدمات عمومی و تجاری به اپلیکیشن‌ها نمونه‌ای از پلتفرمی‌شدن است: منطق امتیازدهی، حساب کاربری و داده وارد حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).', 'cdb4fa11f8d231ff735dedf288a7c9d18381c00e6e762e0b8aaca4fe3338ad00', 1223, 'ch-doc-card-516-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cdb4fa11f8d231ff735dedf288a7c9d18381c00e6e762e0b8aaca4fe3338ad00', token_count=1223, vector_point_id='ch-doc-card-516-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-516-10', 'doc-card-516', 'sec-card-516-4', 10, 'حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).  رقابت صنعت استریم بر «محتوای انحصاری» استراتژی است برای بهره‌گیری از اثر شبکه‌ای: تمرکز مخاطب روی یک پلتفرم، ارزش آن را هم برای کاربران و هم برای تولیدکنندگان بزرگ‌تر می‌کند.  شکاف دیجیتال تنها درباره‌ی دسترسی به اینترنت نیست: تفاوت میان جوانی شهری که محتوا تولید می‌کند و مسنی روستایی که مصرف‌کننده‌ی منفعل است، نشان می‌دهد شکاف در سطح مهارت، زبان و قدرت اقتصادی نیز کار می‌کند.  ۴. نقدها و چالش‌ها ۱. ریسک جبرگرایی فناورانه: چارچوب «طراحی فناوری رفتار را شکل می‌دهد» می‌تواند به غفلت از انتخاب‌های اجتماعی، سیاسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲.', '4c8a35b8d7922ea06254566270f4f2631332f3bdcde0a1e3f70b05a02715fca1', 1218, 'ch-doc-card-516-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4c8a35b8d7922ea06254566270f4f2631332f3bdcde0a1e3f70b05a02715fca1', token_count=1218, vector_point_id='ch-doc-card-516-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-516-11', 'doc-card-516', 'sec-card-516-4', 11, 'اسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲. ناهمگنی مفهوم پلتفرم: واژه‌ی پلتفرم از سیستم‌عامل تا بازار آنلاین را پوشش می‌دهد', '87fee42a9ee29312dc8fed5c8bfcde236971278084c7a5fd843110e8e180df2a', 290, 'ch-doc-card-516-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='87fee42a9ee29312dc8fed5c8bfcde236971278084c7a5fd843110e8e180df2a', token_count=290, vector_point_id='ch-doc-card-516-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-516-12', 'doc-card-516', 'sec-card-516-5', 12, 'ظهور پلتفرم‌های ویدیویی کوتاه امروز کمتر به کیفیت محتوای تولیدی بازمی‌گردد و بیشتر به طراحی فید الگوریتمی: فید با کارکرد «اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.  حکمرانی پلتفرم‌های بزرگ — نظارت بر محتوا، تعلیق حساب، اولویت‌بندی در جست‌وجو — در عمل نوعی قدرت شبه‌قضایی بر میلیاردها کاربر است که بدون شفافیت و پاسخگویی معیارهای دولتی اعمال می‌شود.  گوشی‌های هوشمند در عرض چند سال عادات ارتباط اجتماعی، خبرخوانی و خرید را تغییر داده‌اند؛ نمونه‌ی کلاسیکی از اینکه چگونه پذیرش یک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.', '636ba3dc6888936f1a685d93cce595caa0f4a53f230bfe4d00f0a25d7ebcf916', 1074, 'ch-doc-card-516-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='636ba3dc6888936f1a685d93cce595caa0f4a53f230bfe4d00f0a25d7ebcf916', token_count=1074, vector_point_id='ch-doc-card-516-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-516-13', 'doc-card-516', 'sec-card-516-5', 13, 'ک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.  جابه‌جایی بسیاری از خدمات عمومی و تجاری به اپلیکیشن‌ها نمونه‌ای از پلتفرمی‌شدن است: منطق امتیازدهی، حساب کاربری و داده وارد حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).  رقابت صنعت استریم بر «محتوای انحصاری» استراتژی است برای بهره‌گیری از اثر شبکه‌ای: تمرکز مخاطب روی یک پلتفرم، ارزش آن را هم برای کاربران و هم برای تولیدکنندگان بزرگ‌تر می‌کند.  شکاف دیجیتال تنها درباره‌ی دسترسی به اینترنت نیست: تفاوت میان جوانی شهری که محتوا تولید می‌کند و مسنی روستایی که مصرف‌کننده‌ی منفعل است، نشان می‌دهد شکاف در سطح مهارت، زبان و قدرت اقتصادی نیز کار می‌کند.', 'e3f0eb156fbda3efdb1f2e84350a04d71dda4dc87fff0d4186a864617a061e62', 1205, 'ch-doc-card-516-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e3f0eb156fbda3efdb1f2e84350a04d71dda4dc87fff0d4186a864617a061e62', token_count=1205, vector_point_id='ch-doc-card-516-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-516-14', 'doc-card-516', 'sec-card-516-6', 14, '۱. ریسک جبرگرایی فناورانه: چارچوب «طراحی فناوری رفتار را شکل می‌دهد» می‌تواند به غفلت از انتخاب‌های اجتماعی، سیاسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲. ناهمگنی مفهوم پلتفرم: واژه‌ی پلتفرم از سیستم‌عامل تا بازار آنلاین را پوشش می‌دهد و نتیجه‌گیری‌های کلی از یک نوع، لازم نیست به نوع دیگر بربخشد. ۳. غرب‌مندی پژوهش: بیشتر مطالعات کلاسیک بر بستر آمریکایی تمرکز دارند و ویژگی‌های رشد پلتفرم در مناطق دیگر (از جمله جنوب جهانی) کمتر پوشش داده شده است. ۴. سرعت تغییر: سرعت دگرگونی فناوری از سرعت تولید تئوری سریع‌تر است و بسیاری از مدل‌ها پیش از آنکه آزمون شوند، کهنه می‌شوند. ۵. جعبه‌ی سیاه الگوریتم: مبهم‌بودن الگوریتم‌ه', '34971c15146ca17ec874cd3416b1e60d2d48b22da945b7fc7a7d255e541f719c', 1189, 'ch-doc-card-516-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='34971c15146ca17ec874cd3416b1e60d2d48b22da945b7fc7a7d255e541f719c', token_count=1189, vector_point_id='ch-doc-card-516-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-516-15', 'doc-card-516', 'sec-card-516-7', 15, 'ایی که ادعاهای چارچوب بر آن‌ها استوار است، آزمون مستقل ادعاها را دشوار می‌کند. ۶. غفلت از شرایط مادی: تمرکز بر منطق «شبکه» می‌تواند تصویر بسازد که فناوری دیجیتال «بی‌وزن» است، درحالی‌که به مراکز داده‌ی پرمصرف انرژی، استخراج منابع و نیروی کار وابسته است. ۷. ابهام مرز «طراحی» و «رفتار»: اثبات اینکه رفتاری خاص محصول یک کارکرد است — نه نتیجه‌ی عادات اجتماعی و هنجارهای پیشین — بسیار دشوار است. ۸. مسئله‌ی قدرت: چارچوب گاه «حکمرانی» پلتفرم را توصیف می‌کند بدون آنکه ساختار مالکیت و منافع سیاسی پشت آن را عمیق تحلیل کند. ۹. تعمیم میان‌فرهنگی: پذیرش و اهلی‌سازی فناوری در فرهنگ‌ها به‌شدت متفاوت است و مدل ساخته‌شده در یک بستر، در بستر دیگر گمراه‌کننده می‌شود.', '1dca1cba3657dc9eb15a7fb9271b08cd7e5efc3b4e0380a2aa2f7eb41074c6f3', 1189, 'ch-doc-card-516-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1dca1cba3657dc9eb15a7fb9271b08cd7e5efc3b4e0380a2aa2f7eb41074c6f3', token_count=1189, vector_point_id='ch-doc-card-516-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-516-16', 'doc-card-516', 'sec-card-516-10', 16, 'کتاب «سرمایه‌داری پلتفرمی» (نیک سرنیک، ۲۰۱۷)؛ کتاب «عصر دوم رسانه» (یوهان وان‌دایک، ۲۰۰۵)؛ کتاب «انقلاب پلتفرمی» (پarker، وان آلستاین و چوداری، ۲۰۱۶)؛ استناد مبنا: Castells (2010) بر جامعه‌ی شبکه‌ای.', '0a3c1c145bb3103ffd193cce634d5d1dee4ff4a554a19424194c0f1d290155bf', 361, 'ch-doc-card-516-16', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0a3c1c145bb3103ffd193cce634d5d1dee4ff4a554a19424194c0f1d290155bf', token_count=361, vector_point_id='ch-doc-card-516-16', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-517-0', 'doc-card-517', NULL, 0, 'UTAUT (ونکاتش، ۲۰۰۳) مدل یکپارچه‌ای برای پیش‌بینی پذیرش و استفاده از فناوری است که چهار عامل — انتظار سود، انتظار کارایی، تأثیر اجتماعی و تسهیل‌کننده‌های حمایتی — را به‌عنوان تعیین‌کنندگان نیت و رفتار کاربر معرفی می‌کند.', 'c263ae267ed5293cb51295b42e3c47ec2888d8e4566eac97979c7adca4ad5bc1', 399, 'ch-doc-card-517-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c263ae267ed5293cb51295b42e3c47ec2888d8e4566eac97979c7adca4ad5bc1', token_count=399, vector_point_id='ch-doc-card-517-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-517-1', 'doc-card-517', 'sec-card-517-1', 1, 'اینترنت، پلتفرم و فناوری  پیشبینهای پذیرش فناوری.', '66ac04e1c8fbbd8a89a0e383d26f1a21bfee5b710ceac796fd8fcb123a690be6', 89, 'ch-doc-card-517-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='66ac04e1c8fbbd8a89a0e383d26f1a21bfee5b710ceac796fd8fcb123a690be6', token_count=89, vector_point_id='ch-doc-card-517-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-517-2', 'doc-card-517', 'sec-card-517-2', 2, '۱. بنیان و منطق نظری UTAUT اینترنت و پلتفرم‌های دیجیتال را محیط رسانه‌ای تازه‌ای می‌داند که منطق ارتباط، تولید و تبادل را دگرگون کرده است. ونکاتش (۲۰۰۳) استدلال کرد که در عصر شبکه، واحد تحلیل دیگر پیام یا کانال نیست، بلکه پلتفرم است: زیرساخت فنی-اقتصادی که کاربران، محتوا و سرمایه را به هم وصل می‌کند. در این چارچوب، خودِ طراحی زیرساخت — پروتکل، کارکرد و الگوریتم — رفتار اجتماعی را شکل می‌دهد، نه صرفاَ محتوای عبوری.  بر اساس UTAUT، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است. ونکاتش (۲۰۰۳) فرایندی را تحلیل کرد که فناوری تازه، از ورود و پذیرش، به زندگی روزمره می‌آمیزد، نقش‌ها و روابط را بازنشانی می‌کند و سرانجام «طبیعی» به نظر می‌رسد.', 'f8d9916b71e2aa6317d9450d547a88da4561fe7fc97c9d8b60d282dc930fe08f', 1214, 'ch-doc-card-517-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f8d9916b71e2aa6317d9450d547a88da4561fe7fc97c9d8b60d282dc930fe08f', token_count=1214, vector_point_id='ch-doc-card-517-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-517-3', 'doc-card-517', 'sec-card-517-2', 3, 'ره می‌آمیزد، نقش‌ها و روابط را بازنشانی می‌کند و سرانجام «طبیعی» به نظر می‌رسد. ادعای محوری این است که هر نوسازی فناورانه با یک بازنشانی نظم اجتماعی همراه است و مطالعه‌ی فناوری را نمی‌توان از مطالعه‌ی قدرت، اقتصاد و فرهنگ جدا کرد.  UTAUT پلتفرم را بوم‌زمینه‌ای چندوجهی می‌داند که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند. ونکاتش (۲۰۰۳) تأکید کرد که پلتفرم هم‌زمان فناوری، بازار و شیوه‌ی حکمرانی است و قدرت آن از کنترل بر «قوانین بازی» — چشم‌اندازی، دسترسی و معامله — می‌آید. این رویکرد، تحلیل پلتفرم را در تقاطع جامعه‌شناسی فناوری، اقتصاد و حکمرانی جای می‌دهد.  ۲.', '4188c18425b0217128e45c66f34f291a96e793e1e5bc6eeb7b1e6b32269b337f', 1085, 'ch-doc-card-517-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4188c18425b0217128e45c66f34f291a96e793e1e5bc6eeb7b1e6b32269b337f', token_count=1085, vector_point_id='ch-doc-card-517-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-517-4', 'doc-card-517', 'sec-card-517-2', 4, '، تحلیل پلتفرم را در تقاطع جامعه‌شناسی فناوری، اقتصاد و حکمرانی جای می‌دهد.  ۲. ساختارهای مفهومی • پلتفرم (Platform): زیرساخت دیجیتالی که بازیگران متعدد را گرد هم می‌آورد و تعامل آن‌ها را میانجی می‌کند. • کارکرد/امکان (Affordance): قابلیت‌های کنشی که طراحی فناوری به کاربر پیشنهاد می‌دهد و عادت‌های او را شکل می‌دهد. • اثر شبکه‌ای (Network Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود. • حکمرانی الگوریتمی (Algorithmic Governance): فرایندی که الگوریتم‌ها درباره‌ی چشم‌اندازی، اولویت‌بندی و دسترسی تصمیم می‌گیرند. • زیرساخت دیجیتال (Digital Infrastructure): لایه‌ی فنی پایینی (سرور، پروتکل، شبکه) که خدمات بر آن ساخته می‌شوند. • پذیرش (Adop', 'f03a63f69a01cde4babe243ee24a4f857c4c2afe6f2ed5c3a6db0f7cd4389752', 1223, 'ch-doc-card-517-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f03a63f69a01cde4babe243ee24a4f857c4c2afe6f2ed5c3a6db0f7cd4389752', token_count=1223, vector_point_id='ch-doc-card-517-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-517-5', 'doc-card-517', 'sec-card-517-3', 5, '• پلتفرم (Platform): زیرساخت دیجیتالی که بازیگران متعدد را گرد هم می‌آورد و تعامل آن‌ها را میانجی می‌کند. • کارکرد/امکان (Affordance): قابلیت‌های کنشی که طراحی فناوری به کاربر پیشنهاد می‌دهد و عادت‌های او را شکل می‌دهد. • اثر شبکه‌ای (Network Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود. • حکمرانی الگوریتمی (Algorithmic Governance): فرایندی که الگوریتم‌ها درباره‌ی چشم‌اندازی، اولویت‌بندی و دسترسی تصمیم می‌گیرند. • زیرساخت دیجیتال (Digital Infrastructure): لایه‌ی فنی پایینی (سرور، پروتکل، شبکه) که خدمات بر آن ساخته می‌شوند. • پذیرش (Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن.', '3c61d5d146cf756011fcb316faa0502d957ac65ac19e581e862b4f675e0dc33f', 1167, 'ch-doc-card-517-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3c61d5d146cf756011fcb316faa0502d957ac65ac19e581e862b4f675e0dc33f', token_count=1167, vector_point_id='ch-doc-card-517-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-517-6', 'doc-card-517', 'sec-card-517-3', 6, '• پذیرش (Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن. • شکاف دیجیتال (Digital Divide): نابرابری ساختاری در دسترسی به فناوری دیجیتال، استفاده از آن و بهره‌مندی از آن. • پلتفرمی‌شدن (Platformization): فرایند گسترش منطق و ارزش‌های پلتفرم به حوزه‌های دیگر زندگی اجتماعی.', '058868170e5dcb763251870b437b68e333b102c73b1c8f9ac8c3bbac174cd0e9', 530, 'ch-doc-card-517-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='058868170e5dcb763251870b437b68e333b102c73b1c8f9ac8c3bbac174cd0e9', token_count=530, vector_point_id='ch-doc-card-517-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-517-7', 'doc-card-517', 'sec-card-517-4', 7, 'tion): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن. • شکاف دیجیتال (Digital Divide): نابرابری ساختاری در دسترسی به فناوری دیجیتال، استفاده از آن و بهره‌مندی از آن. • پلتفرمی‌شدن (Platformization): فرایند گسترش منطق و ارزش‌های پلتفرم به حوزه‌های دیگر زندگی اجتماعی.  ۳. نمونه‌های تحلیلی ظهور پلتفرم‌های ویدیویی کوتاه امروز کمتر به کیفیت محتوای تولیدی بازمی‌گردد و بیشتر به طراحی فید الگوریتمی: فید با کارکرد «اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.', '1e654299c8edb321d372483e95dba29500899ab20153d3c31bb1e93f2cb23def', 910, 'ch-doc-card-517-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1e654299c8edb321d372483e95dba29500899ab20153d3c31bb1e93f2cb23def', token_count=910, vector_point_id='ch-doc-card-517-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-517-8', 'doc-card-517', 'sec-card-517-4', 8, 'اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.  حکمرانی پلتفرم‌های بزرگ — نظارت بر محتوا، تعلیق حساب، اولویت‌بندی در جست‌وجو — در عمل نوعی قدرت شبه‌قضایی بر میلیاردها کاربر است که بدون شفافیت و پاسخگویی معیارهای دولتی اعمال می‌شود.  گوشی‌های هوشمند در عرض چند سال عادات ارتباط اجتماعی، خبرخوانی و خرید را تغییر داده‌اند؛ نمونه‌ی کلاسیکی از اینکه چگونه پذیرش یک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.  جابه‌جایی بسیاری از خدمات عمومی و تجاری به اپلیکیشن‌ها نمونه‌ای از پلتفرمی‌شدن است: منطق امتیازدهی، حساب کاربری و داده وارد حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).', 'cdb4fa11f8d231ff735dedf288a7c9d18381c00e6e762e0b8aaca4fe3338ad00', 1223, 'ch-doc-card-517-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cdb4fa11f8d231ff735dedf288a7c9d18381c00e6e762e0b8aaca4fe3338ad00', token_count=1223, vector_point_id='ch-doc-card-517-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-517-9', 'doc-card-517', 'sec-card-517-4', 9, 'حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).  رقابت صنعت استریم بر «محتوای انحصاری» استراتژی است برای بهره‌گیری از اثر شبکه‌ای: تمرکز مخاطب روی یک پلتفرم، ارزش آن را هم برای کاربران و هم برای تولیدکنندگان بزرگ‌تر می‌کند.  شکاف دیجیتال تنها درباره‌ی دسترسی به اینترنت نیست: تفاوت میان جوانی شهری که محتوا تولید می‌کند و مسنی روستایی که مصرف‌کننده‌ی منفعل است، نشان می‌دهد شکاف در سطح مهارت، زبان و قدرت اقتصادی نیز کار می‌کند.  ۴. نقدها و چالش‌ها ۱. ریسک جبرگرایی فناورانه: چارچوب «طراحی فناوری رفتار را شکل می‌دهد» می‌تواند به غفلت از انتخاب‌های اجتماعی، سیاسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲.', '4c8a35b8d7922ea06254566270f4f2631332f3bdcde0a1e3f70b05a02715fca1', 1218, 'ch-doc-card-517-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4c8a35b8d7922ea06254566270f4f2631332f3bdcde0a1e3f70b05a02715fca1', token_count=1218, vector_point_id='ch-doc-card-517-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-517-10', 'doc-card-517', 'sec-card-517-4', 10, 'اسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲. ناهمگنی مفهوم پلتفرم: واژه‌ی پلتفرم از سیستم‌عامل تا بازار آنلاین را پوشش می‌دهد و نتیجه‌گی', '98e133aa685b7880f98a13d59efba72912f62da9155431d4f95f78f71cd13915', 310, 'ch-doc-card-517-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='98e133aa685b7880f98a13d59efba72912f62da9155431d4f95f78f71cd13915', token_count=310, vector_point_id='ch-doc-card-517-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-517-11', 'doc-card-517', 'sec-card-517-5', 11, 'ظهور پلتفرم‌های ویدیویی کوتاه امروز کمتر به کیفیت محتوای تولیدی بازمی‌گردد و بیشتر به طراحی فید الگوریتمی: فید با کارکرد «اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.  حکمرانی پلتفرم‌های بزرگ — نظارت بر محتوا، تعلیق حساب، اولویت‌بندی در جست‌وجو — در عمل نوعی قدرت شبه‌قضایی بر میلیاردها کاربر است که بدون شفافیت و پاسخگویی معیارهای دولتی اعمال می‌شود.  گوشی‌های هوشمند در عرض چند سال عادات ارتباط اجتماعی، خبرخوانی و خرید را تغییر داده‌اند؛ نمونه‌ی کلاسیکی از اینکه چگونه پذیرش یک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.', '636ba3dc6888936f1a685d93cce595caa0f4a53f230bfe4d00f0a25d7ebcf916', 1074, 'ch-doc-card-517-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='636ba3dc6888936f1a685d93cce595caa0f4a53f230bfe4d00f0a25d7ebcf916', token_count=1074, vector_point_id='ch-doc-card-517-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-517-12', 'doc-card-517', 'sec-card-517-5', 12, 'ک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.  جابه‌جایی بسیاری از خدمات عمومی و تجاری به اپلیکیشن‌ها نمونه‌ای از پلتفرمی‌شدن است: منطق امتیازدهی، حساب کاربری و داده وارد حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).  رقابت صنعت استریم بر «محتوای انحصاری» استراتژی است برای بهره‌گیری از اثر شبکه‌ای: تمرکز مخاطب روی یک پلتفرم، ارزش آن را هم برای کاربران و هم برای تولیدکنندگان بزرگ‌تر می‌کند.  شکاف دیجیتال تنها درباره‌ی دسترسی به اینترنت نیست: تفاوت میان جوانی شهری که محتوا تولید می‌کند و مسنی روستایی که مصرف‌کننده‌ی منفعل است، نشان می‌دهد شکاف در سطح مهارت، زبان و قدرت اقتصادی نیز کار می‌کند.', 'e3f0eb156fbda3efdb1f2e84350a04d71dda4dc87fff0d4186a864617a061e62', 1205, 'ch-doc-card-517-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e3f0eb156fbda3efdb1f2e84350a04d71dda4dc87fff0d4186a864617a061e62', token_count=1205, vector_point_id='ch-doc-card-517-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-517-13', 'doc-card-517', 'sec-card-517-6', 13, '۱. ریسک جبرگرایی فناورانه: چارچوب «طراحی فناوری رفتار را شکل می‌دهد» می‌تواند به غفلت از انتخاب‌های اجتماعی، سیاسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲. ناهمگنی مفهوم پلتفرم: واژه‌ی پلتفرم از سیستم‌عامل تا بازار آنلاین را پوشش می‌دهد و نتیجه‌گیری‌های کلی از یک نوع، لازم نیست به نوع دیگر بربخشد. ۳. غرب‌مندی پژوهش: بیشتر مطالعات کلاسیک بر بستر آمریکایی تمرکز دارند و ویژگی‌های رشد پلتفرم در مناطق دیگر (از جمله جنوب جهانی) کمتر پوشش داده شده است. ۴. سرعت تغییر: سرعت دگرگونی فناوری از سرعت تولید تئوری سریع‌تر است و بسیاری از مدل‌ها پیش از آنکه آزمون شوند، کهنه می‌شوند. ۵. جعبه‌ی سیاه الگوریتم: مبهم‌بودن الگوریتم‌ه', '34971c15146ca17ec874cd3416b1e60d2d48b22da945b7fc7a7d255e541f719c', 1189, 'ch-doc-card-517-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='34971c15146ca17ec874cd3416b1e60d2d48b22da945b7fc7a7d255e541f719c', token_count=1189, vector_point_id='ch-doc-card-517-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-517-14', 'doc-card-517', 'sec-card-517-7', 14, 'ایی که ادعاهای چارچوب بر آن‌ها استوار است، آزمون مستقل ادعاها را دشوار می‌کند. ۶. غفلت از شرایط مادی: تمرکز بر منطق «شبکه» می‌تواند تصویر بسازد که فناوری دیجیتال «بی‌وزن» است، درحالی‌که به مراکز داده‌ی پرمصرف انرژی، استخراج منابع و نیروی کار وابسته است. ۷. ابهام مرز «طراحی» و «رفتار»: اثبات اینکه رفتاری خاص محصول یک کارکرد است — نه نتیجه‌ی عادات اجتماعی و هنجارهای پیشین — بسیار دشوار است. ۸. مسئله‌ی قدرت: چارچوب گاه «حکمرانی» پلتفرم را توصیف می‌کند بدون آنکه ساختار مالکیت و منافع سیاسی پشت آن را عمیق تحلیل کند. ۹. تعمیم میان‌فرهنگی: پذیرش و اهلی‌سازی فناوری در فرهنگ‌ها به‌شدت متفاوت است و مدل ساخته‌شده در یک بستر، در بستر دیگر گمراه‌کننده می‌شود.', '1dca1cba3657dc9eb15a7fb9271b08cd7e5efc3b4e0380a2aa2f7eb41074c6f3', 1189, 'ch-doc-card-517-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1dca1cba3657dc9eb15a7fb9271b08cd7e5efc3b4e0380a2aa2f7eb41074c6f3', token_count=1189, vector_point_id='ch-doc-card-517-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-517-15', 'doc-card-517', 'sec-card-517-10', 15, 'کتاب «سرمایه‌داری پلتفرمی» (نیک سرنیک، ۲۰۱۷)؛ کتاب «عصر دوم رسانه» (یوهان وان‌دایک، ۲۰۰۵)؛ کتاب «انقلاب پلتفرمی» (پarker، وان آلستاین و چوداری، ۲۰۱۶)؛ استناد مبنا: Castells (2010) بر جامعه‌ی شبکه‌ای.', '0a3c1c145bb3103ffd193cce634d5d1dee4ff4a554a19424194c0f1d290155bf', 361, 'ch-doc-card-517-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0a3c1c145bb3103ffd193cce634d5d1dee4ff4a554a19424194c0f1d290155bf', token_count=361, vector_point_id='ch-doc-card-517-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-518-0', 'doc-card-518', NULL, 0, 'نظریه کارکردها/امکانات اینترنت و پلتفرم‌های دیجیتال را محیط رسانه‌ای تازه‌ای می‌داند که منطق ارتباط، تولید و تبادل را دگرگون کرده است. گیبسون (۱۹۷۹) استدلال کرد که در عصر شبکه، واحد تحلیل دیگر پیام یا کانال نیست، بلکه پلتفرم است: زیرساخت فنی-اقتصادی که کاربران، محتوا و سرمایه را …', 'a854b1a0537a333b8ccdb99af0837363eca2f000a7f12c0337137885c226ea16', 510, 'ch-doc-card-518-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a854b1a0537a333b8ccdb99af0837363eca2f000a7f12c0337137885c226ea16', token_count=510, vector_point_id='ch-doc-card-518-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-518-1', 'doc-card-518', 'sec-card-518-1', 1, 'اینترنت، پلتفرم و فناوری  نظریه کارکردها/امکانات اینترنت و پلتفرم‌های دیجیتال را محیط رسانه‌ای تازه‌ای می‌داند که منطق ارتباط، تولید و تبادل را دگرگون کرده است. گیبسون (۱۹۷۹) استدلال کرد که در عصر شبکه، واحد تحلیل دیگر پیام یا کانال نیست، بلکه پلتفرم است: زیرساخت فنی-اقتصادی که کاربران، محتوا و سرمایه را به هم وصل می‌کند. در این چارچوب، خودِ طراحی زیرساخت — پروتکل، کارکرد و الگوریتم — رفتار اجتماعی را شکل می‌دهد، نه صرفاَ محتوای عبوری.  بر اساس نظریه کارکردها/امکانات، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است.', 'f0177c6c0ec678858dc9c618a1b13de055c046e9f5c8c162cef622f598cba1c4', 992, 'ch-doc-card-518-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f0177c6c0ec678858dc9c618a1b13de055c046e9f5c8c162cef622f598cba1c4', token_count=992, vector_point_id='ch-doc-card-518-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-518-2', 'doc-card-518', 'sec-card-518-1', 2, 'انات، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است. گیبسون (۱۹۷۹) فرایندی را تحلیل کرد که فناوری تازه، از ورود و پذیرش، به زندگی روزمره می‌آمیزد، نقش‌ها و روابط را بازنشانی می‌کند و سرانجام «طبیعی» به نظر می‌رسد. ادعای محوری این است که هر نوسازی فناورانه با یک بازنشانی نظم اجتماعی همراه است و مطالعه‌ی فناوری را نمی‌توان از مطالعه‌ی قدرت، اقتصاد و فرهنگ جدا کرد.  نظریه کارکردها/امکانات پلتفرم را بوم‌زمینه‌ای چندوجهی می‌داند که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند.', '9924b86fca6a8abab2a0e1b8612e090cef6c0e51e4347b559a2a68aee31a66ef', 967, 'ch-doc-card-518-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9924b86fca6a8abab2a0e1b8612e090cef6c0e51e4347b559a2a68aee31a66ef', token_count=967, vector_point_id='ch-doc-card-518-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-518-3', 'doc-card-518', 'sec-card-518-1', 3, 'د که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند. گیبسون (۱۹۷۹) تأکید کرد که پلتفرم هم‌زمان فناوری، بازار و شیوه‌ی حکمرانی است و قدرت آن از کنترل بر «قوانین بازی» — چشم‌اندازی، دسترسی و معامله — می‌آید. این رویکرد، تحلیل پلتفرم را در تقاطع جامعه‌شناسی فناوری، اقتصاد و حکمرانی جای می‌دهد.', '9895811c8298a78b0a394358b3984ef38c41c8e66ffb920255d1ce320fc317ec', 578, 'ch-doc-card-518-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9895811c8298a78b0a394358b3984ef38c41c8e66ffb920255d1ce320fc317ec', token_count=578, vector_point_id='ch-doc-card-518-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-518-4', 'doc-card-518', 'sec-card-518-2', 4, '۱. بنیان و منطق نظری نظریه کارکردها/امکانات اینترنت و پلتفرم‌های دیجیتال را محیط رسانه‌ای تازه‌ای می‌داند که منطق ارتباط، تولید و تبادل را دگرگون کرده است. گیبسون (۱۹۷۹) استدلال کرد که در عصر شبکه، واحد تحلیل دیگر پیام یا کانال نیست، بلکه پلتفرم است: زیرساخت فنی-اقتصادی که کاربران، محتوا و سرمایه را به هم وصل می‌کند. در این چارچوب، خودِ طراحی زیرساخت — پروتکل، کارکرد و الگوریتم — رفتار اجتماعی را شکل می‌دهد، نه صرفاَ محتوای عبوری.  بر اساس نظریه کارکردها/امکانات، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است.', 'b4cc7a196a6e1f13e851a5463356ad405eff51c7ab3775c52b15fae01d66678c', 983, 'ch-doc-card-518-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b4cc7a196a6e1f13e851a5463356ad405eff51c7ab3775c52b15fae01d66678c', token_count=983, vector_point_id='ch-doc-card-518-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-518-5', 'doc-card-518', 'sec-card-518-2', 5, 'انات، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است. گیبسون (۱۹۷۹) فرایندی را تحلیل کرد که فناوری تازه، از ورود و پذیرش، به زندگی روزمره می‌آمیزد، نقش‌ها و روابط را بازنشانی می‌کند و سرانجام «طبیعی» به نظر می‌رسد. ادعای محوری این است که هر نوسازی فناورانه با یک بازنشانی نظم اجتماعی همراه است و مطالعه‌ی فناوری را نمی‌توان از مطالعه‌ی قدرت، اقتصاد و فرهنگ جدا کرد.  نظریه کارکردها/امکانات پلتفرم را بوم‌زمینه‌ای چندوجهی می‌داند که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند.', '9924b86fca6a8abab2a0e1b8612e090cef6c0e51e4347b559a2a68aee31a66ef', 967, 'ch-doc-card-518-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9924b86fca6a8abab2a0e1b8612e090cef6c0e51e4347b559a2a68aee31a66ef', token_count=967, vector_point_id='ch-doc-card-518-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-518-6', 'doc-card-518', 'sec-card-518-2', 6, 'د که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند. گیبسون (۱۹۷۹) تأکید کرد که پلتفرم هم‌زمان فناوری، بازار و شیوه‌ی حکمرانی است و قدرت آن از کنترل بر «قوانین بازی» — چشم‌اندازی، دسترسی و معامله — می‌آید. این رویکرد، تحلیل پلتفرم را در تقاطع جامعه‌شناسی فناوری، اقتصاد و حکمرانی جای می‌دهد.  ۲. ساختارهای مفهومی • پلتفرم (Platform): زیرساخت دیجیتالی که بازیگران متعدد را گرد هم می‌آورد و تعامل آن‌ها را میانجی می‌کند. • کارکرد/امکان (Affordance): قابلیت‌های کنشی که طراحی فناوری به کاربر پیشنهاد می‌دهد و عادت‌های او را شکل می‌دهد. • اثر شبکه‌ای (Network Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود.', '0b275092235c2fc6f40cd1b84e0adc0a2f8f826b21d6926d7dd490b74f919716', 1203, 'ch-doc-card-518-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0b275092235c2fc6f40cd1b84e0adc0a2f8f826b21d6926d7dd490b74f919716', token_count=1203, vector_point_id='ch-doc-card-518-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-518-7', 'doc-card-518', 'sec-card-518-2', 7, 'Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود. • حکمرانی الگوریتمی (Algorithmic Governance): فرایندی که الگوریتم‌ها درباره‌ی چشم‌اندازی، اولویت‌بندی و دسترسی تصمیم می‌گیرند. • زیرساخت دیجیتال (Digital Infrastructure): لایه‌ی فنی پایینی (سرور، پروتکل، شبکه) که خدمات بر آن', '2f89d86c2af0309b0fe070e9839d37989cd329b46da46a66b2cc56ee193b4db4', 552, 'ch-doc-card-518-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2f89d86c2af0309b0fe070e9839d37989cd329b46da46a66b2cc56ee193b4db4', token_count=552, vector_point_id='ch-doc-card-518-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-518-8', 'doc-card-518', 'sec-card-518-3', 8, '• پلتفرم (Platform): زیرساخت دیجیتالی که بازیگران متعدد را گرد هم می‌آورد و تعامل آن‌ها را میانجی می‌کند. • کارکرد/امکان (Affordance): قابلیت‌های کنشی که طراحی فناوری به کاربر پیشنهاد می‌دهد و عادت‌های او را شکل می‌دهد. • اثر شبکه‌ای (Network Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود. • حکمرانی الگوریتمی (Algorithmic Governance): فرایندی که الگوریتم‌ها درباره‌ی چشم‌اندازی، اولویت‌بندی و دسترسی تصمیم می‌گیرند. • زیرساخت دیجیتال (Digital Infrastructure): لایه‌ی فنی پایینی (سرور، پروتکل، شبکه) که خدمات بر آن ساخته می‌شوند. • پذیرش (Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن.', '3c61d5d146cf756011fcb316faa0502d957ac65ac19e581e862b4f675e0dc33f', 1167, 'ch-doc-card-518-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3c61d5d146cf756011fcb316faa0502d957ac65ac19e581e862b4f675e0dc33f', token_count=1167, vector_point_id='ch-doc-card-518-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-518-9', 'doc-card-518', 'sec-card-518-3', 9, '• پذیرش (Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن. • شکاف دیجیتال (Digital Divide): نابرابری ساختاری در دسترسی به فناوری دیجیتال، استفاده از آن و بهره‌مندی از آن. • پلتفرمی‌شدن (Platformization): فرایند گسترش منطق و ارزش‌های پلتفرم به حوزه‌های دیگر زندگی اجتماعی.', '058868170e5dcb763251870b437b68e333b102c73b1c8f9ac8c3bbac174cd0e9', 530, 'ch-doc-card-518-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='058868170e5dcb763251870b437b68e333b102c73b1c8f9ac8c3bbac174cd0e9', token_count=530, vector_point_id='ch-doc-card-518-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-518-10', 'doc-card-518', 'sec-card-518-4', 10, 'ساخته می‌شوند. • پذیرش (Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن. • شکاف دیجیتال (Digital Divide): نابرابری ساختاری در دسترسی به فناوری دیجیتال، استفاده از آن و بهره‌مندی از آن. • پلتفرمی‌شدن (Platformization): فرایند گسترش منطق و ارزش‌های پلتفرم به حوزه‌های دیگر زندگی اجتماعی.  ۳. نمونه‌های تحلیلی ظهور پلتفرم‌های ویدیویی کوتاه امروز کمتر به کیفیت محتوای تولیدی بازمی‌گردد و بیشتر به طراحی فید الگوریتمی: فید با کارکرد «اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.', '21ff71070856c2210718131a8f306abe8764a43265888f3ed141800981cf8634', 961, 'ch-doc-card-518-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='21ff71070856c2210718131a8f306abe8764a43265888f3ed141800981cf8634', token_count=961, vector_point_id='ch-doc-card-518-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-518-11', 'doc-card-518', 'sec-card-518-4', 11, 'اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.  حکمرانی پلتفرم‌های بزرگ — نظارت بر محتوا، تعلیق حساب، اولویت‌بندی در جست‌وجو — در عمل نوعی قدرت شبه‌قضایی بر میلیاردها کاربر است که بدون شفافیت و پاسخگویی معیارهای دولتی اعمال می‌شود.  گوشی‌های هوشمند در عرض چند سال عادات ارتباط اجتماعی، خبرخوانی و خرید را تغییر داده‌اند؛ نمونه‌ی کلاسیکی از اینکه چگونه پذیرش یک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.  جابه‌جایی بسیاری از خدمات عمومی و تجاری به اپلیکیشن‌ها نمونه‌ای از پلتفرمی‌شدن است: منطق امتیازدهی، حساب کاربری و داده وارد حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).', 'cdb4fa11f8d231ff735dedf288a7c9d18381c00e6e762e0b8aaca4fe3338ad00', 1223, 'ch-doc-card-518-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cdb4fa11f8d231ff735dedf288a7c9d18381c00e6e762e0b8aaca4fe3338ad00', token_count=1223, vector_point_id='ch-doc-card-518-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-518-12', 'doc-card-518', 'sec-card-518-4', 12, 'حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).  رقابت صنعت استریم بر «محتوای انحصاری» استراتژی است برای بهره‌گیری از اثر شبکه‌ای: تمرکز مخاطب روی یک پلتفرم، ارزش آن را هم برای کاربران و هم برای تولیدکنندگان بزرگ‌تر می‌کند.  شکاف دیجیتال تنها درباره‌ی دسترسی به اینترنت نیست: تفاوت میان جوانی شهری که محتوا تولید می‌کند و مسنی روستایی که مصرف‌کننده‌ی منفعل است، نشان می‌دهد شکاف در سطح مهارت، زبان و قدرت اقتصادی نیز کار می‌کند.  ۴. نقدها و چالش‌ها ۱. ریسک جبرگرایی فناورانه: چارچوب «طراحی فناوری رفتار را شکل می‌دهد» می‌تواند به غفلت از انتخاب‌های اجتماعی، سیاسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲.', '4c8a35b8d7922ea06254566270f4f2631332f3bdcde0a1e3f70b05a02715fca1', 1218, 'ch-doc-card-518-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4c8a35b8d7922ea06254566270f4f2631332f3bdcde0a1e3f70b05a02715fca1', token_count=1218, vector_point_id='ch-doc-card-518-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-518-13', 'doc-card-518', 'sec-card-518-4', 13, 'اسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲. ناهمگنی مفهوم پلتفرم: واژه‌ی پلتفرم از سیستم‌عامل تا بازار آنلاین را پوشش می‌دهد و نت', 'ce9ab3ee0e82a82aa7e089f6a560175f1f18427755d5d22dc5ce9baa9fae358a', 300, 'ch-doc-card-518-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ce9ab3ee0e82a82aa7e089f6a560175f1f18427755d5d22dc5ce9baa9fae358a', token_count=300, vector_point_id='ch-doc-card-518-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-518-14', 'doc-card-518', 'sec-card-518-5', 14, 'ظهور پلتفرم‌های ویدیویی کوتاه امروز کمتر به کیفیت محتوای تولیدی بازمی‌گردد و بیشتر به طراحی فید الگوریتمی: فید با کارکرد «اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.  حکمرانی پلتفرم‌های بزرگ — نظارت بر محتوا، تعلیق حساب، اولویت‌بندی در جست‌وجو — در عمل نوعی قدرت شبه‌قضایی بر میلیاردها کاربر است که بدون شفافیت و پاسخگویی معیارهای دولتی اعمال می‌شود.  گوشی‌های هوشمند در عرض چند سال عادات ارتباط اجتماعی، خبرخوانی و خرید را تغییر داده‌اند؛ نمونه‌ی کلاسیکی از اینکه چگونه پذیرش یک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.', '636ba3dc6888936f1a685d93cce595caa0f4a53f230bfe4d00f0a25d7ebcf916', 1074, 'ch-doc-card-518-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='636ba3dc6888936f1a685d93cce595caa0f4a53f230bfe4d00f0a25d7ebcf916', token_count=1074, vector_point_id='ch-doc-card-518-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-518-15', 'doc-card-518', 'sec-card-518-5', 15, 'ک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.  جابه‌جایی بسیاری از خدمات عمومی و تجاری به اپلیکیشن‌ها نمونه‌ای از پلتفرمی‌شدن است: منطق امتیازدهی، حساب کاربری و داده وارد حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).  رقابت صنعت استریم بر «محتوای انحصاری» استراتژی است برای بهره‌گیری از اثر شبکه‌ای: تمرکز مخاطب روی یک پلتفرم، ارزش آن را هم برای کاربران و هم برای تولیدکنندگان بزرگ‌تر می‌کند.  شکاف دیجیتال تنها درباره‌ی دسترسی به اینترنت نیست: تفاوت میان جوانی شهری که محتوا تولید می‌کند و مسنی روستایی که مصرف‌کننده‌ی منفعل است، نشان می‌دهد شکاف در سطح مهارت، زبان و قدرت اقتصادی نیز کار می‌کند.', 'e3f0eb156fbda3efdb1f2e84350a04d71dda4dc87fff0d4186a864617a061e62', 1205, 'ch-doc-card-518-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e3f0eb156fbda3efdb1f2e84350a04d71dda4dc87fff0d4186a864617a061e62', token_count=1205, vector_point_id='ch-doc-card-518-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-518-16', 'doc-card-518', 'sec-card-518-6', 16, '۱. ریسک جبرگرایی فناورانه: چارچوب «طراحی فناوری رفتار را شکل می‌دهد» می‌تواند به غفلت از انتخاب‌های اجتماعی، سیاسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲. ناهمگنی مفهوم پلتفرم: واژه‌ی پلتفرم از سیستم‌عامل تا بازار آنلاین را پوشش می‌دهد و نتیجه‌گیری‌های کلی از یک نوع، لازم نیست به نوع دیگر بربخشد. ۳. غرب‌مندی پژوهش: بیشتر مطالعات کلاسیک بر بستر آمریکایی تمرکز دارند و ویژگی‌های رشد پلتفرم در مناطق دیگر (از جمله جنوب جهانی) کمتر پوشش داده شده است. ۴. سرعت تغییر: سرعت دگرگونی فناوری از سرعت تولید تئوری سریع‌تر است و بسیاری از مدل‌ها پیش از آنکه آزمون شوند، کهنه می‌شوند. ۵. جعبه‌ی سیاه الگوریتم: مبهم‌بودن الگوریتم‌ه', '34971c15146ca17ec874cd3416b1e60d2d48b22da945b7fc7a7d255e541f719c', 1189, 'ch-doc-card-518-16', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='34971c15146ca17ec874cd3416b1e60d2d48b22da945b7fc7a7d255e541f719c', token_count=1189, vector_point_id='ch-doc-card-518-16', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-518-17', 'doc-card-518', 'sec-card-518-7', 17, 'ایی که ادعاهای چارچوب بر آن‌ها استوار است، آزمون مستقل ادعاها را دشوار می‌کند. ۶. غفلت از شرایط مادی: تمرکز بر منطق «شبکه» می‌تواند تصویر بسازد که فناوری دیجیتال «بی‌وزن» است، درحالی‌که به مراکز داده‌ی پرمصرف انرژی، استخراج منابع و نیروی کار وابسته است. ۷. ابهام مرز «طراحی» و «رفتار»: اثبات اینکه رفتاری خاص محصول یک کارکرد است — نه نتیجه‌ی عادات اجتماعی و هنجارهای پیشین — بسیار دشوار است. ۸. مسئله‌ی قدرت: چارچوب گاه «حکمرانی» پلتفرم را توصیف می‌کند بدون آنکه ساختار مالکیت و منافع سیاسی پشت آن را عمیق تحلیل کند. ۹. تعمیم میان‌فرهنگی: پذیرش و اهلی‌سازی فناوری در فرهنگ‌ها به‌شدت متفاوت است و مدل ساخته‌شده در یک بستر، در بستر دیگر گمراه‌کننده می‌شود.', '1dca1cba3657dc9eb15a7fb9271b08cd7e5efc3b4e0380a2aa2f7eb41074c6f3', 1189, 'ch-doc-card-518-17', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1dca1cba3657dc9eb15a7fb9271b08cd7e5efc3b4e0380a2aa2f7eb41074c6f3', token_count=1189, vector_point_id='ch-doc-card-518-17', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-518-18', 'doc-card-518', 'sec-card-518-10', 18, 'کتاب «سرمایه‌داری پلتفرمی» (نیک سرنیک، ۲۰۱۷)؛ کتاب «عصر دوم رسانه» (یوهان وان‌دایک، ۲۰۰۵)؛ کتاب «انقلاب پلتفرمی» (پarker، وان آلستاین و چوداری، ۲۰۱۶)؛ استناد مبنا: Castells (2010) بر جامعه‌ی شبکه‌ای.', '0a3c1c145bb3103ffd193cce634d5d1dee4ff4a554a19424194c0f1d290155bf', 361, 'ch-doc-card-518-18', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0a3c1c145bb3103ffd193cce634d5d1dee4ff4a554a19424194c0f1d290155bf', token_count=361, vector_point_id='ch-doc-card-518-18', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-519-0', 'doc-card-519', NULL, 0, 'نظریه وب بهعنوان محیط اینترنت و پلتفرم‌های دیجیتال را محیط رسانه‌ای تازه‌ای می‌داند که منطق ارتباط، تولید و تبادل را دگرگون کرده است. برنرز-لی (۱۹۸۹) استدلال کرد که در عصر شبکه، واحد تحلیل دیگر پیام یا کانال نیست، بلکه پلتفرم است: زیرساخت فنی-اقتصادی که کاربران، محتوا و سرمایه …', 'f75e59749cb35c8b4023734fb8a936b71491d26097d0fe858b10a259dcd6493d', 507, 'ch-doc-card-519-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f75e59749cb35c8b4023734fb8a936b71491d26097d0fe858b10a259dcd6493d', token_count=507, vector_point_id='ch-doc-card-519-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-519-1', 'doc-card-519', 'sec-card-519-1', 1, 'اینترنت، پلتفرم و فناوری  نظریه وب بهعنوان محیط اینترنت و پلتفرم‌های دیجیتال را محیط رسانه‌ای تازه‌ای می‌داند که منطق ارتباط، تولید و تبادل را دگرگون کرده است. برنرز-لی (۱۹۸۹) استدلال کرد که در عصر شبکه، واحد تحلیل دیگر پیام یا کانال نیست، بلکه پلتفرم است: زیرساخت فنی-اقتصادی که کاربران، محتوا و سرمایه را به هم وصل می‌کند. در این چارچوب، خودِ طراحی زیرساخت — پروتکل، کارکرد و الگوریتم — رفتار اجتماعی را شکل می‌دهد، نه صرفاَ محتوای عبوری.  بر اساس نظریه وب بهعنوان محیط، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است.', '245196ed84379b708c5cc2afa4ac548bbadfa35407290e9e4f480741db2835a1', 992, 'ch-doc-card-519-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='245196ed84379b708c5cc2afa4ac548bbadfa35407290e9e4f480741db2835a1', token_count=992, vector_point_id='ch-doc-card-519-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-519-2', 'doc-card-519', 'sec-card-519-1', 2, 'محیط، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است. برنرز-لی (۱۹۸۹) فرایندی را تحلیل کرد که فناوری تازه، از ورود و پذیرش، به زندگی روزمره می‌آمیزد، نقش‌ها و روابط را بازنشانی می‌کند و سرانجام «طبیعی» به نظر می‌رسد. ادعای محوری این است که هر نوسازی فناورانه با یک بازنشانی نظم اجتماعی همراه است و مطالعه‌ی فناوری را نمی‌توان از مطالعه‌ی قدرت، اقتصاد و فرهنگ جدا کرد.  نظریه وب بهعنوان محیط پلتفرم را بوم‌زمینه‌ای چندوجهی می‌داند که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند.', 'e09afb84db268420b62a10fd52e18b1d1bf28d76f712625dcaf526dcd6cedf1d', 969, 'ch-doc-card-519-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e09afb84db268420b62a10fd52e18b1d1bf28d76f712625dcaf526dcd6cedf1d', token_count=969, vector_point_id='ch-doc-card-519-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-519-3', 'doc-card-519', 'sec-card-519-1', 3, 'د که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند. برنرز-لی (۱۹۸۹) تأکید کرد که پلتفرم هم‌زمان فناوری، بازار و شیوه‌ی حکمرانی است و قدرت آن از کنترل بر «قوانین بازی» — چشم‌اندازی، دسترسی و معامله — می‌آید. این رویکرد، تحلیل پلتفرم را در تقاطع جامعه‌شناسی فناوری، اقتصاد و حکمرانی جای می‌دهد.', '5d7480fbf3144006c45b47daaaac47384eca080930e1fad8b72f4a1eec04daee', 581, 'ch-doc-card-519-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5d7480fbf3144006c45b47daaaac47384eca080930e1fad8b72f4a1eec04daee', token_count=581, vector_point_id='ch-doc-card-519-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-519-4', 'doc-card-519', 'sec-card-519-2', 4, '۱. بنیان و منطق نظری نظریه وب بهعنوان محیط اینترنت و پلتفرم‌های دیجیتال را محیط رسانه‌ای تازه‌ای می‌داند که منطق ارتباط، تولید و تبادل را دگرگون کرده است. برنرز-لی (۱۹۸۹) استدلال کرد که در عصر شبکه، واحد تحلیل دیگر پیام یا کانال نیست، بلکه پلتفرم است: زیرساخت فنی-اقتصادی که کاربران، محتوا و سرمایه را به هم وصل می‌کند. در این چارچوب، خودِ طراحی زیرساخت — پروتکل، کارکرد و الگوریتم — رفتار اجتماعی را شکل می‌دهد، نه صرفاَ محتوای عبوری.  بر اساس نظریه وب بهعنوان محیط، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است.', 'f83655682fad0ec07817d39468e70b362f53f647e773db7cf3ee731fbb665227', 983, 'ch-doc-card-519-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f83655682fad0ec07817d39468e70b362f53f647e773db7cf3ee731fbb665227', token_count=983, vector_point_id='ch-doc-card-519-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-519-5', 'doc-card-519', 'sec-card-519-2', 5, 'محیط، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است. برنرز-لی (۱۹۸۹) فرایندی را تحلیل کرد که فناوری تازه، از ورود و پذیرش، به زندگی روزمره می‌آمیزد، نقش‌ها و روابط را بازنشانی می‌کند و سرانجام «طبیعی» به نظر می‌رسد. ادعای محوری این است که هر نوسازی فناورانه با یک بازنشانی نظم اجتماعی همراه است و مطالعه‌ی فناوری را نمی‌توان از مطالعه‌ی قدرت، اقتصاد و فرهنگ جدا کرد.  نظریه وب بهعنوان محیط پلتفرم را بوم‌زمینه‌ای چندوجهی می‌داند که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند.', 'e09afb84db268420b62a10fd52e18b1d1bf28d76f712625dcaf526dcd6cedf1d', 969, 'ch-doc-card-519-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e09afb84db268420b62a10fd52e18b1d1bf28d76f712625dcaf526dcd6cedf1d', token_count=969, vector_point_id='ch-doc-card-519-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-519-6', 'doc-card-519', 'sec-card-519-2', 6, 'د که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند. برنرز-لی (۱۹۸۹) تأکید کرد که پلتفرم هم‌زمان فناوری، بازار و شیوه‌ی حکمرانی است و قدرت آن از کنترل بر «قوانین بازی» — چشم‌اندازی، دسترسی و معامله — می‌آید. این رویکرد، تحلیل پلتفرم را در تقاطع جامعه‌شناسی فناوری، اقتصاد و حکمرانی جای می‌دهد.  ۲. ساختارهای مفهومی • پلتفرم (Platform): زیرساخت دیجیتالی که بازیگران متعدد را گرد هم می‌آورد و تعامل آن‌ها را میانجی می‌کند. • کارکرد/امکان (Affordance): قابلیت‌های کنشی که طراحی فناوری به کاربر پیشنهاد می‌دهد و عادت‌های او را شکل می‌دهد. • اثر شبکه‌ای (Network Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود.', '603451b47480d1a6769ff166ed0cc06fa18dbd70d5f750e757ccc087bbb2d63f', 1207, 'ch-doc-card-519-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='603451b47480d1a6769ff166ed0cc06fa18dbd70d5f750e757ccc087bbb2d63f', token_count=1207, vector_point_id='ch-doc-card-519-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-519-7', 'doc-card-519', 'sec-card-519-2', 7, 'Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود. • حکمرانی الگوریتمی (Algorithmic Governance): فرایندی که الگوریتم‌ها درباره‌ی چشم‌اندازی، اولویت‌بندی و دسترسی تصمیم می‌گیرند. • زیرساخت دیجیتال (Digital Infrastructure): لایه‌ی فنی پایینی (سرور، پروتکل، شبکه) که خدمات بر', '710e89ff8688fff416317d8337857a6ede6761f27670b8d33223f92ee5a06c52', 547, 'ch-doc-card-519-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='710e89ff8688fff416317d8337857a6ede6761f27670b8d33223f92ee5a06c52', token_count=547, vector_point_id='ch-doc-card-519-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-519-8', 'doc-card-519', 'sec-card-519-3', 8, '• پلتفرم (Platform): زیرساخت دیجیتالی که بازیگران متعدد را گرد هم می‌آورد و تعامل آن‌ها را میانجی می‌کند. • کارکرد/امکان (Affordance): قابلیت‌های کنشی که طراحی فناوری به کاربر پیشنهاد می‌دهد و عادت‌های او را شکل می‌دهد. • اثر شبکه‌ای (Network Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود. • حکمرانی الگوریتمی (Algorithmic Governance): فرایندی که الگوریتم‌ها درباره‌ی چشم‌اندازی، اولویت‌بندی و دسترسی تصمیم می‌گیرند. • زیرساخت دیجیتال (Digital Infrastructure): لایه‌ی فنی پایینی (سرور، پروتکل، شبکه) که خدمات بر آن ساخته می‌شوند. • پذیرش (Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن.', '3c61d5d146cf756011fcb316faa0502d957ac65ac19e581e862b4f675e0dc33f', 1167, 'ch-doc-card-519-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3c61d5d146cf756011fcb316faa0502d957ac65ac19e581e862b4f675e0dc33f', token_count=1167, vector_point_id='ch-doc-card-519-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-519-9', 'doc-card-519', 'sec-card-519-3', 9, '• پذیرش (Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن. • شکاف دیجیتال (Digital Divide): نابرابری ساختاری در دسترسی به فناوری دیجیتال، استفاده از آن و بهره‌مندی از آن. • پلتفرمی‌شدن (Platformization): فرایند گسترش منطق و ارزش‌های پلتفرم به حوزه‌های دیگر زندگی اجتماعی.', '058868170e5dcb763251870b437b68e333b102c73b1c8f9ac8c3bbac174cd0e9', 530, 'ch-doc-card-519-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='058868170e5dcb763251870b437b68e333b102c73b1c8f9ac8c3bbac174cd0e9', token_count=530, vector_point_id='ch-doc-card-519-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-519-10', 'doc-card-519', 'sec-card-519-4', 10, 'آن ساخته می‌شوند. • پذیرش (Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن. • شکاف دیجیتال (Digital Divide): نابرابری ساختاری در دسترسی به فناوری دیجیتال، استفاده از آن و بهره‌مندی از آن. • پلتفرمی‌شدن (Platformization): فرایند گسترش منطق و ارزش‌های پلتفرم به حوزه‌های دیگر زندگی اجتماعی.  ۳. نمونه‌های تحلیلی ظهور پلتفرم‌های ویدیویی کوتاه امروز کمتر به کیفیت محتوای تولیدی بازمی‌گردد و بیشتر به طراحی فید الگوریتمی: فید با کارکرد «اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.', '522936bcbc855d7dd996a3826201023f777b2b86db032d507dfcee39b9d38d68', 967, 'ch-doc-card-519-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='522936bcbc855d7dd996a3826201023f777b2b86db032d507dfcee39b9d38d68', token_count=967, vector_point_id='ch-doc-card-519-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-519-11', 'doc-card-519', 'sec-card-519-4', 11, 'اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.  حکمرانی پلتفرم‌های بزرگ — نظارت بر محتوا، تعلیق حساب، اولویت‌بندی در جست‌وجو — در عمل نوعی قدرت شبه‌قضایی بر میلیاردها کاربر است که بدون شفافیت و پاسخگویی معیارهای دولتی اعمال می‌شود.  گوشی‌های هوشمند در عرض چند سال عادات ارتباط اجتماعی، خبرخوانی و خرید را تغییر داده‌اند؛ نمونه‌ی کلاسیکی از اینکه چگونه پذیرش یک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.  جابه‌جایی بسیاری از خدمات عمومی و تجاری به اپلیکیشن‌ها نمونه‌ای از پلتفرمی‌شدن است: منطق امتیازدهی، حساب کاربری و داده وارد حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).', 'cdb4fa11f8d231ff735dedf288a7c9d18381c00e6e762e0b8aaca4fe3338ad00', 1223, 'ch-doc-card-519-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cdb4fa11f8d231ff735dedf288a7c9d18381c00e6e762e0b8aaca4fe3338ad00', token_count=1223, vector_point_id='ch-doc-card-519-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-519-12', 'doc-card-519', 'sec-card-519-4', 12, 'حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).  رقابت صنعت استریم بر «محتوای انحصاری» استراتژی است برای بهره‌گیری از اثر شبکه‌ای: تمرکز مخاطب روی یک پلتفرم، ارزش آن را هم برای کاربران و هم برای تولیدکنندگان بزرگ‌تر می‌کند.  شکاف دیجیتال تنها درباره‌ی دسترسی به اینترنت نیست: تفاوت میان جوانی شهری که محتوا تولید می‌کند و مسنی روستایی که مصرف‌کننده‌ی منفعل است، نشان می‌دهد شکاف در سطح مهارت، زبان و قدرت اقتصادی نیز کار می‌کند.  ۴. نقدها و چالش‌ها ۱. ریسک جبرگرایی فناورانه: چارچوب «طراحی فناوری رفتار را شکل می‌دهد» می‌تواند به غفلت از انتخاب‌های اجتماعی، سیاسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲.', '4c8a35b8d7922ea06254566270f4f2631332f3bdcde0a1e3f70b05a02715fca1', 1218, 'ch-doc-card-519-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4c8a35b8d7922ea06254566270f4f2631332f3bdcde0a1e3f70b05a02715fca1', token_count=1218, vector_point_id='ch-doc-card-519-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-519-13', 'doc-card-519', 'sec-card-519-4', 13, 'اسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲. ناهمگنی مفهوم پلتفرم: واژه‌ی پلتفرم از سیستم‌عامل تا بازار آنلاین را پوشش می‌دهد و', '4d3dad8d01ffd7409db88e5cb54796654384fdba5167ac8a648b41a4d136a2c1', 294, 'ch-doc-card-519-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4d3dad8d01ffd7409db88e5cb54796654384fdba5167ac8a648b41a4d136a2c1', token_count=294, vector_point_id='ch-doc-card-519-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-519-14', 'doc-card-519', 'sec-card-519-5', 14, 'ظهور پلتفرم‌های ویدیویی کوتاه امروز کمتر به کیفیت محتوای تولیدی بازمی‌گردد و بیشتر به طراحی فید الگوریتمی: فید با کارکرد «اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.  حکمرانی پلتفرم‌های بزرگ — نظارت بر محتوا، تعلیق حساب، اولویت‌بندی در جست‌وجو — در عمل نوعی قدرت شبه‌قضایی بر میلیاردها کاربر است که بدون شفافیت و پاسخگویی معیارهای دولتی اعمال می‌شود.  گوشی‌های هوشمند در عرض چند سال عادات ارتباط اجتماعی، خبرخوانی و خرید را تغییر داده‌اند؛ نمونه‌ی کلاسیکی از اینکه چگونه پذیرش یک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.', '636ba3dc6888936f1a685d93cce595caa0f4a53f230bfe4d00f0a25d7ebcf916', 1074, 'ch-doc-card-519-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='636ba3dc6888936f1a685d93cce595caa0f4a53f230bfe4d00f0a25d7ebcf916', token_count=1074, vector_point_id='ch-doc-card-519-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-519-15', 'doc-card-519', 'sec-card-519-5', 15, 'ک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.  جابه‌جایی بسیاری از خدمات عمومی و تجاری به اپلیکیشن‌ها نمونه‌ای از پلتفرمی‌شدن است: منطق امتیازدهی، حساب کاربری و داده وارد حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).  رقابت صنعت استریم بر «محتوای انحصاری» استراتژی است برای بهره‌گیری از اثر شبکه‌ای: تمرکز مخاطب روی یک پلتفرم، ارزش آن را هم برای کاربران و هم برای تولیدکنندگان بزرگ‌تر می‌کند.  شکاف دیجیتال تنها درباره‌ی دسترسی به اینترنت نیست: تفاوت میان جوانی شهری که محتوا تولید می‌کند و مسنی روستایی که مصرف‌کننده‌ی منفعل است، نشان می‌دهد شکاف در سطح مهارت، زبان و قدرت اقتصادی نیز کار می‌کند.', 'e3f0eb156fbda3efdb1f2e84350a04d71dda4dc87fff0d4186a864617a061e62', 1205, 'ch-doc-card-519-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e3f0eb156fbda3efdb1f2e84350a04d71dda4dc87fff0d4186a864617a061e62', token_count=1205, vector_point_id='ch-doc-card-519-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-519-16', 'doc-card-519', 'sec-card-519-6', 16, '۱. ریسک جبرگرایی فناورانه: چارچوب «طراحی فناوری رفتار را شکل می‌دهد» می‌تواند به غفلت از انتخاب‌های اجتماعی، سیاسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲. ناهمگنی مفهوم پلتفرم: واژه‌ی پلتفرم از سیستم‌عامل تا بازار آنلاین را پوشش می‌دهد و نتیجه‌گیری‌های کلی از یک نوع، لازم نیست به نوع دیگر بربخشد. ۳. غرب‌مندی پژوهش: بیشتر مطالعات کلاسیک بر بستر آمریکایی تمرکز دارند و ویژگی‌های رشد پلتفرم در مناطق دیگر (از جمله جنوب جهانی) کمتر پوشش داده شده است. ۴. سرعت تغییر: سرعت دگرگونی فناوری از سرعت تولید تئوری سریع‌تر است و بسیاری از مدل‌ها پیش از آنکه آزمون شوند، کهنه می‌شوند. ۵. جعبه‌ی سیاه الگوریتم: مبهم‌بودن الگوریتم‌ه', '34971c15146ca17ec874cd3416b1e60d2d48b22da945b7fc7a7d255e541f719c', 1189, 'ch-doc-card-519-16', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='34971c15146ca17ec874cd3416b1e60d2d48b22da945b7fc7a7d255e541f719c', token_count=1189, vector_point_id='ch-doc-card-519-16', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-519-17', 'doc-card-519', 'sec-card-519-7', 17, 'ایی که ادعاهای چارچوب بر آن‌ها استوار است، آزمون مستقل ادعاها را دشوار می‌کند. ۶. غفلت از شرایط مادی: تمرکز بر منطق «شبکه» می‌تواند تصویر بسازد که فناوری دیجیتال «بی‌وزن» است، درحالی‌که به مراکز داده‌ی پرمصرف انرژی، استخراج منابع و نیروی کار وابسته است. ۷. ابهام مرز «طراحی» و «رفتار»: اثبات اینکه رفتاری خاص محصول یک کارکرد است — نه نتیجه‌ی عادات اجتماعی و هنجارهای پیشین — بسیار دشوار است. ۸. مسئله‌ی قدرت: چارچوب گاه «حکمرانی» پلتفرم را توصیف می‌کند بدون آنکه ساختار مالکیت و منافع سیاسی پشت آن را عمیق تحلیل کند. ۹. تعمیم میان‌فرهنگی: پذیرش و اهلی‌سازی فناوری در فرهنگ‌ها به‌شدت متفاوت است و مدل ساخته‌شده در یک بستر، در بستر دیگر گمراه‌کننده می‌شود.', '1dca1cba3657dc9eb15a7fb9271b08cd7e5efc3b4e0380a2aa2f7eb41074c6f3', 1189, 'ch-doc-card-519-17', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1dca1cba3657dc9eb15a7fb9271b08cd7e5efc3b4e0380a2aa2f7eb41074c6f3', token_count=1189, vector_point_id='ch-doc-card-519-17', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-519-18', 'doc-card-519', 'sec-card-519-10', 18, 'کتاب «سرمایه‌داری پلتفرمی» (نیک سرنیک، ۲۰۱۷)؛ کتاب «عصر دوم رسانه» (یوهان وان‌دایک، ۲۰۰۵)؛ کتاب «انقلاب پلتفرمی» (پarker، وان آلستاین و چوداری، ۲۰۱۶)؛ استناد مبنا: Castells (2010) بر جامعه‌ی شبکه‌ای.', '0a3c1c145bb3103ffd193cce634d5d1dee4ff4a554a19424194c0f1d290155bf', 361, 'ch-doc-card-519-18', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0a3c1c145bb3103ffd193cce634d5d1dee4ff4a554a19424194c0f1d290155bf', token_count=361, vector_point_id='ch-doc-card-519-18', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-52-0', 'doc-card-52', NULL, 0, 'جریان اطلاعات باید با هنجارهای بافت اجتماعی خود هم‌خوان باشد. یک اطلاع ممکن است در بافت پزشکی مجاز و در بافت تبلیغاتی نقض حریم باشد. بنابراین ارزیابی اخلاقی باید بر «نوع جریان» (گیرنده، فرستنده، موضوع، اصول انتقال) متمرکز باشد، نه صرفاً بر «محرمانه یا عمومی بودن» اطلاع.', '588334243c06423f9d7f01513ace26971458a15b33b0a5239608547ab8fee870', 490, 'ch-doc-card-52-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='588334243c06423f9d7f01513ace26971458a15b33b0a5239608547ab8fee870', token_count=490, vector_point_id='ch-doc-card-52-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-52-1', 'doc-card-52', 'sec-card-52-1', 1, 'فلسفه فناوری / اخلاق اطلاعات  جریان اطلاعات باید با هنجارهای بافت اجتماعی خود هم‌خوان باشد. یک اطلاع ممکن است در بافت پزشکی مجاز و در بافت تبلیغاتی نقض حریم باشد. بنابراین ارزیابی اخلاقی باید بر «نوع جریان» (گیرنده، فرستنده، موضوع، اصول انتقال) متمرکز باشد، نه صرفاً بر «محرمانه یا عمومی بودن» اطلاع.', 'efeae9fb318578806b33e0beb05f48638be2d1c3891bc57f735e221edeb7a87f', 545, 'ch-doc-card-52-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='efeae9fb318578806b33e0beb05f48638be2d1c3891bc57f735e221edeb7a87f', token_count=545, vector_point_id='ch-doc-card-52-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-52-2', 'doc-card-52', 'sec-card-52-2', 2, '۱. بنیان و منطق نظری یکپارچگی بافتاری رسانه را در «چارچوب اخلاقی» و «قانونی» تحلیل می‌کند: «تصویر»، «گزارش» و «بازنمایی»، «مسئولیت» دارند. هلن نیسنبام (۲۰۰۴) در این چارچوب، «اخلاق رسانه» را نه «قانون» بلکه «مبارزه» بر سر «ارزش‌ها» تعریف کرد: «مسئولیت» رسانه، فراتر از «قانون»، در «ارزش‌ها» و «نمادها» عمل می‌کند.  بر اساس یکپارچگی بافتاری، «قانون» و «اخلاق» «مرز» دارند: «قانون»، «حداقل» است و «اخلاق»، «حداکثر». هلن نیسنبام (۲۰۰۴) در این چارچوب، «قانون رسانه» را «چارچوب» «نظام» خواند: «قانون»، «قواعد بازی» را «تعیین» می‌کند و «اخلاق»، «ارزش‌ها» را «بازتولید» می‌کند.', '35fb89ee4c3fa73416f88058b0150373fea998c1518e97a35d6de1fdf84304e3', 1034, 'ch-doc-card-52-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='35fb89ee4c3fa73416f88058b0150373fea998c1518e97a35d6de1fdf84304e3', token_count=1034, vector_point_id='ch-doc-card-52-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-52-3', 'doc-card-52', 'sec-card-52-2', 3, 'ون»، «قواعد بازی» را «تعیین» می‌کند و «اخلاق»، «ارزش‌ها» را «بازتولید» می‌کند.  یکپارچگی بافتاری را می‌توان پاسخی به شکاف میان «قانون» (تک‌گویی) و «اخلاق» (چندگویی) دانست: «قانون»، «حداقل» است و «اخلاق»، «بازنگری» مداوم. هلن نیسنبام (۲۰۰۴) در این چارچوب، «مسئولیت» رسانه را در برابر «مخاطب» و «جامعه» تعریف کرد — نه صرفاَ «رعایت قانون».  ۲. ساختارهای مفهومی • اخلاق رسانه (Media Ethics): «مسئولیت» رسانه در برابر «مخاطب» و «جامعه»؛ فراتر از «قانون»، در «ارزش‌ها» عمل می‌کند. • قانون رسانه (Media Law): «قواعد» «نظام» درباره‌ی «فعالیت» رسانه: «حداقل» «مجاز» است و «نظم» را «بازتولید» می‌کند.', 'd5ddb5470d1bea5b7f6bc3347dab2f7f2b865d59e3f3a98ab33beeaf089cbee1', 1072, 'ch-doc-card-52-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d5ddb5470d1bea5b7f6bc3347dab2f7f2b865d59e3f3a98ab33beeaf089cbee1', token_count=1072, vector_point_id='ch-doc-card-52-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-52-4', 'doc-card-52', 'sec-card-52-2', 4, 'نظام» درباره‌ی «فعالیت» رسانه: «حداقل» «مجاز» است و «نظم» را «بازتولید» می‌کند. • مسئولیت (Accountability): «پاسخگویی» رسانه به «مخاطب» و «جامعه»؛ «مسئولیت»، «بازتولید» روزانه نیاز دارد. • حریم خصوصی (Privacy): «حق» فرد بر «کنترل» اطلاعات شخصی؛ در «اقتصاد داده»، «داده» شخصی «سرمایه» است. • آزادی بیان (Freedom of Expression): «حق» فرد و «رسانه» بر «گفتن»؛ «آزادی» و «مسئولیت» در «موازنه»‌اند. • کد اخلاقی (Ethical Code): «اصول» «حرفه‌ای» رسانه: «دقت»، «استقلال»، «پاسخگوی', '75ef186a0f4b45d1253d245f2a8219511fa1d9af44d88ec1f1951979c7c00c65', 858, 'ch-doc-card-52-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='75ef186a0f4b45d1253d245f2a8219511fa1d9af44d88ec1f1951979c7c00c65', token_count=858, vector_point_id='ch-doc-card-52-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-52-5', 'doc-card-52', 'sec-card-52-3', 5, 'بافت (Context)؛ هنجارهای جریان اطلاعات (Informational Norms)؛ فرستنده، گیرنده و موضوع اطلاع؛ اصول انتقال (Transmission Principles)؛ تمایز عمومی/خصوصی به‌عنوان تقسیم‌بندی ناکافی.', '3db2eed599640f3a1319997376cd33ab3fc6183ab686d9fceaec9060827c2b6c', 321, 'ch-doc-card-52-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3db2eed599640f3a1319997376cd33ab3fc6183ab686d9fceaec9060827c2b6c', token_count=321, vector_point_id='ch-doc-card-52-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-52-6', 'doc-card-52', 'sec-card-52-4', 6, 'ی»، «عدالت»؛ «کد»، «چارچوب» «اخلاق» است. • نظارت اخلاقی (Ethical Oversight): «نهادها» و «نظم‌ها» که «اخلاق» را «بازتولید» می‌کنند: «کمیته‌های» اخلاق، «نظم‌های» خودتنظیمی. • آسیب به مخاطب (Harm to Audience): «تصویر» و «گزارش» می‌تواند «آسیب» بزند: «حداقل آسیب»، «اصل» «اخلاق» است.  ۳. نمونه‌های تحلیلی «اخلاق رسانه» در عمل: وقتی «رسانه‌ای» «خبر» «غیرواقعی» را «گزارش» می‌کند، «مسئولیت» دارد: «اعتبار» از «دقت» ساخته می‌شود و «خطا»، «اعتبار» را «خورده» می‌کند.  «قانون رسانه» در عمل: «قانون» «حق تکثیر» و «حریم خصوصی»، «حداقل» «مجاز» است: «رعایت» «قانون»، «مجاز» است اما «کافی» نیست.', '315f719d01d388b41998a77c652cfb31ce4c5f6d1ffee890c359f444aa1cdfea', 1056, 'ch-doc-card-52-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='315f719d01d388b41998a77c652cfb31ce4c5f6d1ffee890c359f444aa1cdfea', token_count=1056, vector_point_id='ch-doc-card-52-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-52-7', 'doc-card-52', 'sec-card-52-4', 7, '«حریم خصوصی»، «حداقل» «مجاز» است: «رعایت» «قانون»، «مجاز» است اما «کافی» نیست.  «حریم خصوصی» در «عصر دیجیتال»: «داده» شخصی «سرمایه» است و «نظارت» بر آن، «حاکمیت» است: «حق» فرد بر «کنترل» «داده»، «چالش» اصلی «عصر دیجیتال» است.  «آزادی بیان» و «مسئولیت»: «آزادی» «گفتن» و «مسئولیت» «گفتن» در «موازنه»‌اند: «گفتن» بدون «مسئولیت»، «آسیب» است.  «کد اخلاقی» در عمل: «کد» «حرفه‌ای» (دقت، استقلال، پاسخگویی) «چارچوب» «اخلاق» است: «رعایت» «کد»، «مجاز» است اما «کافی» نیست: «اخلاق»، «بازنگری» مداوم است.  «آسیب به مخاطب» در عمل: «تصویر» از «ضحايا» و «فاجعه‌ها»، «آسیب» «دوباره» است: «حداقل آسیب»، «اصل» «اخلاق» است و «تصویر»، «مسئولیت» دارد.  ۴. نقدها و چالش‌ها ۱.', '35cbc51af4e67818699ae73b86e1834cbbbcfe6b287fcfe26b119332977fbf51', 1189, 'ch-doc-card-52-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='35cbc51af4e67818699ae73b86e1834cbbbcfe6b287fcfe26b119332977fbf51', token_count=1189, vector_point_id='ch-doc-card-52-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-52-8', 'doc-card-52', 'sec-card-52-4', 8, 'داقل آسیب»، «اصل» «اخلاق» است و «تصویر»، «مسئولیت» دارد.  ۴. نقدها و چالش‌ها ۱. «اخلاق» به «کد» تقلیل می‌یابد: «رعایت» «کد»، «مجاز» است اما «کافی» نیست: «اخلاق»، «بازنگری» مداوم است و «کد»، «ثابت» است. ۲. «قانون» و «اخلاق» مرز «کمرنگ» دارند: «قانون»، «حداقل» است و «اخلاق»، «حداکثر» است: «مرز» بین آن‌ها «بازتعریف» لازم دارد. ۳. «مسئولیت» در «عصر دیجیتال» «بازتعریف» می‌شود: «مسئولیت» «پلتفرم» و', 'bb17ffd1138fe049397aa7a6912ee3c0af02df57f7d01cedcc9a4d2cbdd20a30', 718, 'ch-doc-card-52-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bb17ffd1138fe049397aa7a6912ee3c0af02df57f7d01cedcc9a4d2cbdd20a30', token_count=718, vector_point_id='ch-doc-card-52-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-52-9', 'doc-card-52', 'sec-card-52-5', 9, 'انتشار نمرات دانش‌آموزان در پلتفرم مدرسه برای والدین هم‌کلاسی‌ها مجاز است، اما همان اطلاعات در شبکه‌های اجتماعی یا برای تبلیغ پلتفرم‌های آموزشی نقض جریان بافتاری محسوب می‌شود.', '130ca3a11603d7f7950327cd4f369b330afa6e1bd0f2abd48c9325f5d463f4eb', 318, 'ch-doc-card-52-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='130ca3a11603d7f7950327cd4f369b330afa6e1bd0f2abd48c9325f5d463f4eb', token_count=318, vector_point_id='ch-doc-card-52-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-52-10', 'doc-card-52', 'sec-card-52-6', 10, 'تعیین هنجارهای بافتی برای هر بافت می‌تواند ذهنی و نیازمند داوری تجربی باشد. همچنین در فضای دیجیتال، تعداد بافت‌ها و جریان‌ها بسیار زیاد است و اجرای عملی این چارچوب برای طراحان سیاست پیچیده است.', '677967cfd6eee604fe53066f83a78a9ff94479f46167feac9ab7f7edc034aeb2', 350, 'ch-doc-card-52-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='677967cfd6eee604fe53066f83a78a9ff94479f46167feac9ab7f7edc034aeb2', token_count=350, vector_point_id='ch-doc-card-52-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-52-11', 'doc-card-52', 'sec-card-52-10', 11, 'استناد علمی مبنا (APA 7): Nissenbaum (2004)', 'de86acf93a2d4427576b42bfaa0d3f8aad4f9104d8a1b6f2d2492def958a85ee', 78, 'ch-doc-card-52-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='de86acf93a2d4427576b42bfaa0d3f8aad4f9104d8a1b6f2d2492def958a85ee', token_count=78, vector_point_id='ch-doc-card-52-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-520-0', 'doc-card-520', NULL, 0, 'واقعیت مجازی اینترنت و پلتفرم‌های دیجیتال را محیط رسانه‌ای تازه‌ای می‌داند که منطق ارتباط، تولید و تبادل را دگرگون کرده است. هاوارد رینگولد (۱۹۹۱) استدلال کرد که در عصر شبکه، واحد تحلیل دیگر پیام یا کانال نیست، بلکه پلتفرم است: زیرساخت فنی-اقتصادی که کاربران، محتوا و سرمایه را …', 'fabe85291f7fc9d47c994990b679cab317d473702283e5b45a6c697b0ea927bd', 507, 'ch-doc-card-520-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fabe85291f7fc9d47c994990b679cab317d473702283e5b45a6c697b0ea927bd', token_count=507, vector_point_id='ch-doc-card-520-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-520-1', 'doc-card-520', 'sec-card-520-1', 1, 'اینترنت، پلتفرم و فناوری  واقعیت مجازی اینترنت و پلتفرم‌های دیجیتال را محیط رسانه‌ای تازه‌ای می‌داند که منطق ارتباط، تولید و تبادل را دگرگون کرده است. هاوارد رینگولد (۱۹۹۱) استدلال کرد که در عصر شبکه، واحد تحلیل دیگر پیام یا کانال نیست، بلکه پلتفرم است: زیرساخت فنی-اقتصادی که کاربران، محتوا و سرمایه را به هم وصل می‌کند. در این چارچوب، خودِ طراحی زیرساخت — پروتکل، کارکرد و الگوریتم — رفتار اجتماعی را شکل می‌دهد، نه صرفاَ محتوای عبوری.  بر اساس واقعیت مجازی، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است.', '883dca36eec0bf5effbcf64ba8236f95df04206b834a4ab772e741e64aa6a434', 970, 'ch-doc-card-520-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='883dca36eec0bf5effbcf64ba8236f95df04206b834a4ab772e741e64aa6a434', token_count=970, vector_point_id='ch-doc-card-520-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-520-2', 'doc-card-520', 'sec-card-520-1', 2, 'جازی، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است. هاوارد رینگولد (۱۹۹۱) فرایندی را تحلیل کرد که فناوری تازه، از ورود و پذیرش، به زندگی روزمره می‌آمیزد، نقش‌ها و روابط را بازنشانی می‌کند و سرانجام «طبیعی» به نظر می‌رسد. ادعای محوری این است که هر نوسازی فناورانه با یک بازنشانی نظم اجتماعی همراه است و مطالعه‌ی فناوری را نمی‌توان از مطالعه‌ی قدرت، اقتصاد و فرهنگ جدا کرد.  واقعیت مجازی پلتفرم را بوم‌زمینه‌ای چندوجهی می‌داند که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند.', '9cd9008c465bb4e0eab42e7b243e0fc2da5d17d59582479e51eac9302ab4969b', 963, 'ch-doc-card-520-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9cd9008c465bb4e0eab42e7b243e0fc2da5d17d59582479e51eac9302ab4969b', token_count=963, vector_point_id='ch-doc-card-520-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-520-3', 'doc-card-520', 'sec-card-520-1', 3, 'د که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند. هاوارد رینگولد (۱۹۹۱) تأکید کرد که پلتفرم هم‌زمان فناوری، بازار و شیوه‌ی حکمرانی است و قدرت آن از کنترل بر «قوانین بازی» — چشم‌اندازی، دسترسی و معامله — می‌آید. این رویکرد، تحلیل پلتفرم را در تقاطع جامعه‌شناسی فناوری، اقتصاد و حکمرانی جای می‌دهد.', '565603ba7152c408e4b03b9a025042a63d16805e938537746b4915def3a240ee', 592, 'ch-doc-card-520-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='565603ba7152c408e4b03b9a025042a63d16805e938537746b4915def3a240ee', token_count=592, vector_point_id='ch-doc-card-520-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-520-4', 'doc-card-520', 'sec-card-520-2', 4, '۱. بنیان و منطق نظری واقعیت مجازی اینترنت و پلتفرم‌های دیجیتال را محیط رسانه‌ای تازه‌ای می‌داند که منطق ارتباط، تولید و تبادل را دگرگون کرده است. هاوارد رینگولد (۱۹۹۱) استدلال کرد که در عصر شبکه، واحد تحلیل دیگر پیام یا کانال نیست، بلکه پلتفرم است: زیرساخت فنی-اقتصادی که کاربران، محتوا و سرمایه را به هم وصل می‌کند. در این چارچوب، خودِ طراحی زیرساخت — پروتکل، کارکرد و الگوریتم — رفتار اجتماعی را شکل می‌دهد، نه صرفاَ محتوای عبوری.  بر اساس واقعیت مجازی، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است.', '29d4e7bd338cff5a0e5712110765604d3485c88f0de8f6ea694e6a71b7d637ae', 961, 'ch-doc-card-520-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='29d4e7bd338cff5a0e5712110765604d3485c88f0de8f6ea694e6a71b7d637ae', token_count=961, vector_point_id='ch-doc-card-520-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-520-5', 'doc-card-520', 'sec-card-520-2', 5, 'جازی، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است. هاوارد رینگولد (۱۹۹۱) فرایندی را تحلیل کرد که فناوری تازه، از ورود و پذیرش، به زندگی روزمره می‌آمیزد، نقش‌ها و روابط را بازنشانی می‌کند و سرانجام «طبیعی» به نظر می‌رسد. ادعای محوری این است که هر نوسازی فناورانه با یک بازنشانی نظم اجتماعی همراه است و مطالعه‌ی فناوری را نمی‌توان از مطالعه‌ی قدرت، اقتصاد و فرهنگ جدا کرد.  واقعیت مجازی پلتفرم را بوم‌زمینه‌ای چندوجهی می‌داند که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند.', '9cd9008c465bb4e0eab42e7b243e0fc2da5d17d59582479e51eac9302ab4969b', 963, 'ch-doc-card-520-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9cd9008c465bb4e0eab42e7b243e0fc2da5d17d59582479e51eac9302ab4969b', token_count=963, vector_point_id='ch-doc-card-520-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-520-6', 'doc-card-520', 'sec-card-520-2', 6, 'د که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند. هاوارد رینگولد (۱۹۹۱) تأکید کرد که پلتفرم هم‌زمان فناوری، بازار و شیوه‌ی حکمرانی است و قدرت آن از کنترل بر «قوانین بازی» — چشم‌اندازی، دسترسی و معامله — می‌آید. این رویکرد، تحلیل پلتفرم را در تقاطع جامعه‌شناسی فناوری، اقتصاد و حکمرانی جای می‌دهد.  ۲. ساختارهای مفهومی • پلتفرم (Platform): زیرساخت دیجیتالی که بازیگران متعدد را گرد هم می‌آورد و تعامل آن‌ها را میانجی می‌کند. • کارکرد/امکان (Affordance): قابلیت‌های کنشی که طراحی فناوری به کاربر پیشنهاد می‌دهد و عادت‌های او را شکل می‌دهد. • اثر شبکه‌ای (Network Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود.', '10097e4af08dc3b289256417f083c284aa9c44f94b010308edfc500f227261e3', 1218, 'ch-doc-card-520-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='10097e4af08dc3b289256417f083c284aa9c44f94b010308edfc500f227261e3', token_count=1218, vector_point_id='ch-doc-card-520-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-520-7', 'doc-card-520', 'sec-card-520-2', 7, 'Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود. • حکمرانی الگوریتمی (Algorithmic Governance): فرایندی که الگوریتم‌ها درباره‌ی چشم‌اندازی، اولویت‌بندی و دسترسی تصمیم می‌گیرند. • زیرساخت دیجیتال (Digital Infrastructure): لایه‌ی فنی پایینی (سرور، پروتکل، شبکه) که خدمات بر آن', '2f89d86c2af0309b0fe070e9839d37989cd329b46da46a66b2cc56ee193b4db4', 552, 'ch-doc-card-520-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2f89d86c2af0309b0fe070e9839d37989cd329b46da46a66b2cc56ee193b4db4', token_count=552, vector_point_id='ch-doc-card-520-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-520-8', 'doc-card-520', 'sec-card-520-3', 8, '• پلتفرم (Platform): زیرساخت دیجیتالی که بازیگران متعدد را گرد هم می‌آورد و تعامل آن‌ها را میانجی می‌کند. • کارکرد/امکان (Affordance): قابلیت‌های کنشی که طراحی فناوری به کاربر پیشنهاد می‌دهد و عادت‌های او را شکل می‌دهد. • اثر شبکه‌ای (Network Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود. • حکمرانی الگوریتمی (Algorithmic Governance): فرایندی که الگوریتم‌ها درباره‌ی چشم‌اندازی، اولویت‌بندی و دسترسی تصمیم می‌گیرند. • زیرساخت دیجیتال (Digital Infrastructure): لایه‌ی فنی پایینی (سرور، پروتکل، شبکه) که خدمات بر آن ساخته می‌شوند. • پذیرش (Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن.', '3c61d5d146cf756011fcb316faa0502d957ac65ac19e581e862b4f675e0dc33f', 1167, 'ch-doc-card-520-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3c61d5d146cf756011fcb316faa0502d957ac65ac19e581e862b4f675e0dc33f', token_count=1167, vector_point_id='ch-doc-card-520-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-520-9', 'doc-card-520', 'sec-card-520-3', 9, '• پذیرش (Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن. • شکاف دیجیتال (Digital Divide): نابرابری ساختاری در دسترسی به فناوری دیجیتال، استفاده از آن و بهره‌مندی از آن. • پلتفرمی‌شدن (Platformization): فرایند گسترش منطق و ارزش‌های پلتفرم به حوزه‌های دیگر زندگی اجتماعی.', '058868170e5dcb763251870b437b68e333b102c73b1c8f9ac8c3bbac174cd0e9', 530, 'ch-doc-card-520-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='058868170e5dcb763251870b437b68e333b102c73b1c8f9ac8c3bbac174cd0e9', token_count=530, vector_point_id='ch-doc-card-520-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-520-10', 'doc-card-520', 'sec-card-520-4', 10, 'ساخته می‌شوند. • پذیرش (Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن. • شکاف دیجیتال (Digital Divide): نابرابری ساختاری در دسترسی به فناوری دیجیتال، استفاده از آن و بهره‌مندی از آن. • پلتفرمی‌شدن (Platformization): فرایند گسترش منطق و ارزش‌های پلتفرم به حوزه‌های دیگر زندگی اجتماعی.  ۳. نمونه‌های تحلیلی ظهور پلتفرم‌های ویدیویی کوتاه امروز کمتر به کیفیت محتوای تولیدی بازمی‌گردد و بیشتر به طراحی فید الگوریتمی: فید با کارکرد «اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.', '21ff71070856c2210718131a8f306abe8764a43265888f3ed141800981cf8634', 961, 'ch-doc-card-520-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='21ff71070856c2210718131a8f306abe8764a43265888f3ed141800981cf8634', token_count=961, vector_point_id='ch-doc-card-520-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-520-11', 'doc-card-520', 'sec-card-520-4', 11, 'اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.  حکمرانی پلتفرم‌های بزرگ — نظارت بر محتوا، تعلیق حساب، اولویت‌بندی در جست‌وجو — در عمل نوعی قدرت شبه‌قضایی بر میلیاردها کاربر است که بدون شفافیت و پاسخگویی معیارهای دولتی اعمال می‌شود.  گوشی‌های هوشمند در عرض چند سال عادات ارتباط اجتماعی، خبرخوانی و خرید را تغییر داده‌اند؛ نمونه‌ی کلاسیکی از اینکه چگونه پذیرش یک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.  جابه‌جایی بسیاری از خدمات عمومی و تجاری به اپلیکیشن‌ها نمونه‌ای از پلتفرمی‌شدن است: منطق امتیازدهی، حساب کاربری و داده وارد حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).', 'cdb4fa11f8d231ff735dedf288a7c9d18381c00e6e762e0b8aaca4fe3338ad00', 1223, 'ch-doc-card-520-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cdb4fa11f8d231ff735dedf288a7c9d18381c00e6e762e0b8aaca4fe3338ad00', token_count=1223, vector_point_id='ch-doc-card-520-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-520-12', 'doc-card-520', 'sec-card-520-4', 12, 'حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).  رقابت صنعت استریم بر «محتوای انحصاری» استراتژی است برای بهره‌گیری از اثر شبکه‌ای: تمرکز مخاطب روی یک پلتفرم، ارزش آن را هم برای کاربران و هم برای تولیدکنندگان بزرگ‌تر می‌کند.  شکاف دیجیتال تنها درباره‌ی دسترسی به اینترنت نیست: تفاوت میان جوانی شهری که محتوا تولید می‌کند و مسنی روستایی که مصرف‌کننده‌ی منفعل است، نشان می‌دهد شکاف در سطح مهارت، زبان و قدرت اقتصادی نیز کار می‌کند.  ۴. نقدها و چالش‌ها ۱. ریسک جبرگرایی فناورانه: چارچوب «طراحی فناوری رفتار را شکل می‌دهد» می‌تواند به غفلت از انتخاب‌های اجتماعی، سیاسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲.', '4c8a35b8d7922ea06254566270f4f2631332f3bdcde0a1e3f70b05a02715fca1', 1218, 'ch-doc-card-520-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4c8a35b8d7922ea06254566270f4f2631332f3bdcde0a1e3f70b05a02715fca1', token_count=1218, vector_point_id='ch-doc-card-520-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-520-13', 'doc-card-520', 'sec-card-520-4', 13, 'اسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲. ناهمگنی مفهوم پلتفرم: واژه‌ی پلتفرم از سیستم‌عامل تا بازار آنلاین را پوشش می‌دهد', '87fee42a9ee29312dc8fed5c8bfcde236971278084c7a5fd843110e8e180df2a', 290, 'ch-doc-card-520-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='87fee42a9ee29312dc8fed5c8bfcde236971278084c7a5fd843110e8e180df2a', token_count=290, vector_point_id='ch-doc-card-520-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-520-14', 'doc-card-520', 'sec-card-520-5', 14, 'ظهور پلتفرم‌های ویدیویی کوتاه امروز کمتر به کیفیت محتوای تولیدی بازمی‌گردد و بیشتر به طراحی فید الگوریتمی: فید با کارکرد «اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.  حکمرانی پلتفرم‌های بزرگ — نظارت بر محتوا، تعلیق حساب، اولویت‌بندی در جست‌وجو — در عمل نوعی قدرت شبه‌قضایی بر میلیاردها کاربر است که بدون شفافیت و پاسخگویی معیارهای دولتی اعمال می‌شود.  گوشی‌های هوشمند در عرض چند سال عادات ارتباط اجتماعی، خبرخوانی و خرید را تغییر داده‌اند؛ نمونه‌ی کلاسیکی از اینکه چگونه پذیرش یک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.', '636ba3dc6888936f1a685d93cce595caa0f4a53f230bfe4d00f0a25d7ebcf916', 1074, 'ch-doc-card-520-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='636ba3dc6888936f1a685d93cce595caa0f4a53f230bfe4d00f0a25d7ebcf916', token_count=1074, vector_point_id='ch-doc-card-520-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-520-15', 'doc-card-520', 'sec-card-520-5', 15, 'ک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.  جابه‌جایی بسیاری از خدمات عمومی و تجاری به اپلیکیشن‌ها نمونه‌ای از پلتفرمی‌شدن است: منطق امتیازدهی، حساب کاربری و داده وارد حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).  رقابت صنعت استریم بر «محتوای انحصاری» استراتژی است برای بهره‌گیری از اثر شبکه‌ای: تمرکز مخاطب روی یک پلتفرم، ارزش آن را هم برای کاربران و هم برای تولیدکنندگان بزرگ‌تر می‌کند.  شکاف دیجیتال تنها درباره‌ی دسترسی به اینترنت نیست: تفاوت میان جوانی شهری که محتوا تولید می‌کند و مسنی روستایی که مصرف‌کننده‌ی منفعل است، نشان می‌دهد شکاف در سطح مهارت، زبان و قدرت اقتصادی نیز کار می‌کند.', 'e3f0eb156fbda3efdb1f2e84350a04d71dda4dc87fff0d4186a864617a061e62', 1205, 'ch-doc-card-520-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e3f0eb156fbda3efdb1f2e84350a04d71dda4dc87fff0d4186a864617a061e62', token_count=1205, vector_point_id='ch-doc-card-520-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-520-16', 'doc-card-520', 'sec-card-520-6', 16, '۱. ریسک جبرگرایی فناورانه: چارچوب «طراحی فناوری رفتار را شکل می‌دهد» می‌تواند به غفلت از انتخاب‌های اجتماعی، سیاسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲. ناهمگنی مفهوم پلتفرم: واژه‌ی پلتفرم از سیستم‌عامل تا بازار آنلاین را پوشش می‌دهد و نتیجه‌گیری‌های کلی از یک نوع، لازم نیست به نوع دیگر بربخشد. ۳. غرب‌مندی پژوهش: بیشتر مطالعات کلاسیک بر بستر آمریکایی تمرکز دارند و ویژگی‌های رشد پلتفرم در مناطق دیگر (از جمله جنوب جهانی) کمتر پوشش داده شده است. ۴. سرعت تغییر: سرعت دگرگونی فناوری از سرعت تولید تئوری سریع‌تر است و بسیاری از مدل‌ها پیش از آنکه آزمون شوند، کهنه می‌شوند. ۵. جعبه‌ی سیاه الگوریتم: مبهم‌بودن الگوریتم‌ه', '34971c15146ca17ec874cd3416b1e60d2d48b22da945b7fc7a7d255e541f719c', 1189, 'ch-doc-card-520-16', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='34971c15146ca17ec874cd3416b1e60d2d48b22da945b7fc7a7d255e541f719c', token_count=1189, vector_point_id='ch-doc-card-520-16', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-520-17', 'doc-card-520', 'sec-card-520-7', 17, 'ایی که ادعاهای چارچوب بر آن‌ها استوار است، آزمون مستقل ادعاها را دشوار می‌کند. ۶. غفلت از شرایط مادی: تمرکز بر منطق «شبکه» می‌تواند تصویر بسازد که فناوری دیجیتال «بی‌وزن» است، درحالی‌که به مراکز داده‌ی پرمصرف انرژی، استخراج منابع و نیروی کار وابسته است. ۷. ابهام مرز «طراحی» و «رفتار»: اثبات اینکه رفتاری خاص محصول یک کارکرد است — نه نتیجه‌ی عادات اجتماعی و هنجارهای پیشین — بسیار دشوار است. ۸. مسئله‌ی قدرت: چارچوب گاه «حکمرانی» پلتفرم را توصیف می‌کند بدون آنکه ساختار مالکیت و منافع سیاسی پشت آن را عمیق تحلیل کند. ۹. تعمیم میان‌فرهنگی: پذیرش و اهلی‌سازی فناوری در فرهنگ‌ها به‌شدت متفاوت است و مدل ساخته‌شده در یک بستر، در بستر دیگر گمراه‌کننده می‌شود.', '1dca1cba3657dc9eb15a7fb9271b08cd7e5efc3b4e0380a2aa2f7eb41074c6f3', 1189, 'ch-doc-card-520-17', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1dca1cba3657dc9eb15a7fb9271b08cd7e5efc3b4e0380a2aa2f7eb41074c6f3', token_count=1189, vector_point_id='ch-doc-card-520-17', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-520-18', 'doc-card-520', 'sec-card-520-10', 18, 'کتاب «سرمایه‌داری پلتفرمی» (نیک سرنیک، ۲۰۱۷)؛ کتاب «عصر دوم رسانه» (یوهان وان‌دایک، ۲۰۰۵)؛ کتاب «انقلاب پلتفرمی» (پarker، وان آلستاین و چوداری، ۲۰۱۶)؛ استناد مبنا: Castells (2010) بر جامعه‌ی شبکه‌ای.', '0a3c1c145bb3103ffd193cce634d5d1dee4ff4a554a19424194c0f1d290155bf', 361, 'ch-doc-card-520-18', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0a3c1c145bb3103ffd193cce634d5d1dee4ff4a554a19424194c0f1d290155bf', token_count=361, vector_point_id='ch-doc-card-520-18', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-521-0', 'doc-card-521', NULL, 0, 'شبکههای بیدرجه «شبکه» را «ساختار» روابط می‌داند: نه «محتوا» بلکه «ارتباط» در کانون است. باراباشی (۱۹۹۹) در این چارچوب، «رفتار» را نه «ویژگی» فرد بلکه «محصول» «موقعیت» در شبکه تعریف کرد: «چه کسی» به «چه کسی» وصل است، «رفتار» را «شکل» می‌دهد. بر اساس شبکههای بیدرجه، «شبکه‌های …', '80a01dc6ab3364e6d0e569d4af37154ecb19f57c7c0ee3a71ea00152156bb75e', 501, 'ch-doc-card-521-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='80a01dc6ab3364e6d0e569d4af37154ecb19f57c7c0ee3a71ea00152156bb75e', token_count=501, vector_point_id='ch-doc-card-521-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-521-1', 'doc-card-521', 'sec-card-521-1', 1, 'شبکه‌های اجتماعی و نظریه شبکه  شبکههای بیدرجه «شبکه» را «ساختار» روابط می‌داند: نه «محتوا» بلکه «ارتباط» در کانون است. باراباشی (۱۹۹۹) در این چارچوب، «رفتار» را نه «ویژگی» فرد بلکه «محصول» «موقعیت» در شبکه تعریف کرد: «چه کسی» به «چه کسی» وصل است، «رفتار» را «شکل» می‌دهد.  بر اساس شبکههای بیدرجه، «شبکه‌های اجتماعی» «میدان» تولید «معنا»، «اعتبار» و «قدرت»‌اند: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت» در شبکه، «ارزش» دارد. باراباشی (۱۹۹۹) در این چارچوب، «رسانه» را نه «پخش‌کننده» بلکه «میانجی» شبکه خواند: «رسانه»، «موقعیت» شبکه‌ای مخاطب را «بازتولید» می‌کند.', '9d48e626720a9757625d54e75a3ee871c0e42cfcfab544915804b2a661c6dbba', 1023, 'ch-doc-card-521-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9d48e626720a9757625d54e75a3ee871c0e42cfcfab544915804b2a661c6dbba', token_count=1023, vector_point_id='ch-doc-card-521-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-521-2', 'doc-card-521', 'sec-card-521-1', 2, 'لکه «میانجی» شبکه خواند: «رسانه»، «موقعیت» شبکه‌ای مخاطب را «بازتولید» می‌کند.  شبکههای بیدرجه را می‌توان پاسخی به شکاف میان «تحلیل فرد» و «تحلیل ساختار» دانست: «رفتار»، «محصول» «شبکه» است و «تغییر»، «تغییر» «موقعیت» است. باراباشی (۱۹۹۹) در این چارچوب، «شبکه» را نه «ابزار» بلکه «بافت» تعریف کرد: «بافت» شبکه‌ای، «هویت» و «رفتار» را «بازتولید» می‌کند.', '93380407889b5313851918b12d4aa9a3941f65a03d61fbbc34656d230ac6ef25', 638, 'ch-doc-card-521-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='93380407889b5313851918b12d4aa9a3941f65a03d61fbbc34656d230ac6ef25', token_count=638, vector_point_id='ch-doc-card-521-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-521-3', 'doc-card-521', 'sec-card-521-2', 3, '۱. بنیان و منطق نظری شبکههای بیدرجه «شبکه» را «ساختار» روابط می‌داند: نه «محتوا» بلکه «ارتباط» در کانون است. باراباشی (۱۹۹۹) در این چارچوب، «رفتار» را نه «ویژگی» فرد بلکه «محصول» «موقعیت» در شبکه تعریف کرد: «چه کسی» به «چه کسی» وصل است، «رفتار» را «شکل» می‌دهد.  بر اساس شبکههای بیدرجه، «شبکه‌های اجتماعی» «میدان» تولید «معنا»، «اعتبار» و «قدرت»‌اند: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت» در شبکه، «ارزش» دارد. باراباشی (۱۹۹۹) در این چارچوب، «رسانه» را نه «پخش‌کننده» بلکه «میانجی» شبکه خواند: «رسانه»، «موقعیت» شبکه‌ای مخاطب را «بازتولید» می‌کند.', 'd5b95b3a2087b67c6885c2f54c24a6d2dc27ac677ed163533a33493989e86d61', 1005, 'ch-doc-card-521-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d5b95b3a2087b67c6885c2f54c24a6d2dc27ac677ed163533a33493989e86d61', token_count=1005, vector_point_id='ch-doc-card-521-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-521-4', 'doc-card-521', 'sec-card-521-2', 4, 'لکه «میانجی» شبکه خواند: «رسانه»، «موقعیت» شبکه‌ای مخاطب را «بازتولید» می‌کند.  شبکههای بیدرجه را می‌توان پاسخی به شکاف میان «تحلیل فرد» و «تحلیل ساختار» دانست: «رفتار»، «محصول» «شبکه» است و «تغییر»، «تغییر» «موقعیت» است. باراباشی (۱۹۹۹) در این چارچوب، «شبکه» را نه «ابزار» بلکه «بافت» تعریف کرد: «بافت» شبکه‌ای، «هویت» و «رفتار» را «بازتولید» می‌کند.  ۲. ساختارهای مفهومی • ساختار شبکه (Network Structure): «الگو» روابط بین «گره‌ها» (فرد، رسانه، نهاد)؛ «ساختار»، «رفتار» را «شکل» می‌دهد. • گره و پیوند (Node and Tie): «گره» (فرد، رسانه) و «پیوند» (ارتباط)؛ «پیوند» «جریان» «معنا» و «سرمایه» است.', 'ab5dc02aa5c3359dd8d20ea700489765d94742c29dd8e0a92c62420771f3cdde', 1083, 'ch-doc-card-521-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ab5dc02aa5c3359dd8d20ea700489765d94742c29dd8e0a92c62420771f3cdde', token_count=1083, vector_point_id='ch-doc-card-521-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-521-5', 'doc-card-521', 'sec-card-521-2', 5, ': «گره» (فرد، رسانه) و «پیوند» (ارتباط)؛ «پیوند» «جریان» «معنا» و «سرمایه» است. • سرمایه شبکه‌ای (Network Capital): «ارزش» «موقعیت» در شبکه؛ «ارتباط» «اجتماعی»، «سرمایه» است. • اثر شبکه‌ای (Network Effect): «بزرگ‌تر» شدن «ارزش» شبکه با «افزایش» «عضو»؛ «محصول» و «بازار» یکجا می‌شوند. • حلقه اجتماعی (Social Loop): «جریان» «محتوا» در «حلقه»‌های «اجتماعی»: «اشتراک‌گذاری» و «تایید»، «اعتبار» می‌سازد. • تأثیرگر (Influencer): «گره» «کلیدی» در شبکه که «محتوا» را «بازتولید» می‌کند؛ «اعت', 'a24a61b555f0ca728b120925949bc43a9dcd53e64b8404f682a625b1da2373d8', 876, 'ch-doc-card-521-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a24a61b555f0ca728b120925949bc43a9dcd53e64b8404f682a625b1da2373d8', token_count=876, vector_point_id='ch-doc-card-521-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-521-6', 'doc-card-521', 'sec-card-521-3', 6, '• ساختار شبکه (Network Structure): «الگو» روابط بین «گره‌ها» (فرد، رسانه، نهاد)؛ «ساختار»، «رفتار» را «شکل» می‌دهد. • گره و پیوند (Node and Tie): «گره» (فرد، رسانه) و «پیوند» (ارتباط)؛ «پیوند» «جریان» «معنا» و «سرمایه» است. • سرمایه شبکه‌ای (Network Capital): «ارزش» «موقعیت» در شبکه؛ «ارتباط» «اجتماعی»، «سرمایه» است. • اثر شبکه‌ای (Network Effect): «بزرگ‌تر» شدن «ارزش» شبکه با «افزایش» «عضو»؛ «محصول» و «بازار» یکجا می‌شوند. • حلقه اجتماعی (Social Loop): «جریان» «محتوا» در «حلقه»‌های «اجتماعی»: «اشتراک‌گذاری» و «تایید»، «اعتبار» می‌سازد. • تأثیرگر (Influencer): «گره» «کلیدی» در شبکه که «محتوا» را «بازتولید» می‌کند؛ «اعتبار» شخصی، «سرمایه» شبکه‌ای است.', '5ba5c7db967fcca10a31d3ceb7258cda8b6d048d4e341937c83e9ac983bd32af', 1196, 'ch-doc-card-521-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5ba5c7db967fcca10a31d3ceb7258cda8b6d048d4e341937c83e9ac983bd32af', token_count=1196, vector_point_id='ch-doc-card-521-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-521-7', 'doc-card-521', 'sec-card-521-3', 7, '» در شبکه که «محتوا» را «بازتولید» می‌کند؛ «اعتبار» شخصی، «سرمایه» شبکه‌ای است. • بافت شبکه‌ای (Networked Context): «بافت» که در آن «رفتار» و «هویت» «بازتولید» می‌شوند؛ «بافت»، «ساختار» است. • جریان اطلاعات (Information Flow): «جریان» «محتوا» در شبکه: «مسیر»، «سرعت» و «حجم» «جریان»، «بازتولید» «معنا» است.', 'db9ec0e0560590ef7363df458568a4fad133d94601ef21aab6b9272fe7a76b3e', 556, 'ch-doc-card-521-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='db9ec0e0560590ef7363df458568a4fad133d94601ef21aab6b9272fe7a76b3e', token_count=556, vector_point_id='ch-doc-card-521-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-521-8', 'doc-card-521', 'sec-card-521-4', 8, 'بار» شخصی، «سرمایه» شبکه‌ای است. • بافت شبکه‌ای (Networked Context): «بافت» که در آن «رفتار» و «هویت» «بازتولید» می‌شوند؛ «بافت»، «ساختار» است. • جریان اطلاعات (Information Flow): «جریان» «محتوا» در شبکه: «مسیر»، «سرعت» و «حجم» «جریان»، «بازتولید» «معنا» است.  ۳. نمونه‌های تحلیلی «ساختار شبکه» در عمل: وقتی «خبر» در «شبکه‌ی اجتماعی» «گسترش» می‌یابد، «مسیر» آن از «گره»‌های «کلیدی» (تأثیرگرها) است: «ساختار»، «جریان» را «تعیین» می‌کند.  «سرمایه شبکه‌ای» در عمل: «اعتبار» یک «تأثیرگر» از «موقعیت» او در شبکه است: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت»، «ارزش» دارد.', 'ff2a840adddb903fef76f1ce8efad872ec1f452f01907cadadbe578d60d2cedb', 1034, 'ch-doc-card-521-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ff2a840adddb903fef76f1ce8efad872ec1f452f01907cadadbe578d60d2cedb', token_count=1034, vector_point_id='ch-doc-card-521-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-521-9', 'doc-card-521', 'sec-card-521-4', 9, 'عیت» او در شبکه است: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت»، «ارزش» دارد.  «اثر شبکه‌ای» در «فیسبوک»: هر «عضو» جدیدی که «می‌آید»، «ارزش» شبکه را برای «همه» «بالاتر» می‌برد: «محصول» و «بازار» یکجا می‌شوند.  «حلقه اجتماعی» در عمل: «اشتراک‌گذاری» یک «خبر» در «حلقه» «دوستان»، «اعتبار» «اجتماعی» می‌سازد: «تایید» «اجتماعی»، «جریان» را «بازتولید» می‌کند.  «تأثیرگر» در «اینستاگرام»: «اعتبار» شخصی «تأثیرگر»، «سرمایه» شبکه‌ای است: «محتوا» او از «موقعیت» او در شبکه «جریان» می‌یابد.  «بافت شبکه‌ای» در عمل: «هویت» «دیجیتال» یک «کاربر» در «بافت» شبکه «بازتولید» می‌شود: «رفتار» و «هویت»، «محصول» «ساختار» است.  ۴. نقدها و چالش‌ها ۱.', '399c48d251f87ea37c6ae3f34383931c054216b738810f83e6b5bec01decfea5', 1143, 'ch-doc-card-521-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='399c48d251f87ea37c6ae3f34383931c054216b738810f83e6b5bec01decfea5', token_count=1143, vector_point_id='ch-doc-card-521-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-521-10', 'doc-card-521', 'sec-card-521-4', 10, 'ازتولید» می‌شود: «رفتار» و «هویت»، «محصول» «ساختار» است.  ۴. نقدها و چالش‌ها ۱. «شبکه» و «محتوا» از هم جدا نمی‌شوند: «تحلیل» صرف «ساختار»، «محتوا» را «محو» می‌کند: «محتوا» و «ساختار» در هم تنیده‌اند. ۲. «سرمایه شبکه‌ای» «سنجش‌پذیر» نیست: «ارزش» «موقعیت» در شبکه، «شاخص» واحد ندارد و «اندازه‌گیری» آن «دشواری» است. ۳. «اثر شبکه‌ای» «نامتقارن» است: «بزرگ‌تر» شدن شبکه، «ارزش» را «افزایش» می‌دهد اما «ارزش»، «توزیع» نمی‌شود: «مرکز» «بیش', '54aeabd7c783720e18c11751af96d10367256011421db1df878180d4ec8bfb9f', 787, 'ch-doc-card-521-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='54aeabd7c783720e18c11751af96d10367256011421db1df878180d4ec8bfb9f', token_count=787, vector_point_id='ch-doc-card-521-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-521-11', 'doc-card-521', 'sec-card-521-5', 11, '«ساختار شبکه» در عمل: وقتی «خبر» در «شبکه‌ی اجتماعی» «گسترش» می‌یابد، «مسیر» آن از «گره»‌های «کلیدی» (تأثیرگرها) است: «ساختار»، «جریان» را «تعیین» می‌کند.  «سرمایه شبکه‌ای» در عمل: «اعتبار» یک «تأثیرگر» از «موقعیت» او در شبکه است: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت»، «ارزش» دارد.  «اثر شبکه‌ای» در «فیسبوک»: هر «عضو» جدیدی که «می‌آید»، «ارزش» شبکه را برای «همه» «بالاتر» می‌برد: «محصول» و «بازار» یکجا می‌شوند.  «حلقه اجتماعی» در عمل: «اشتراک‌گذاری» یک «خبر» در «حلقه» «دوستان»، «اعتبار» «اجتماعی» می‌سازد: «تایید» «اجتماعی»، «جریان» را «بازتولید» می‌کند.', '591acce302984742f99aaeba653caba140e13292a9114cff4d0b46b06ec2c4c4', 1025, 'ch-doc-card-521-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='591acce302984742f99aaeba653caba140e13292a9114cff4d0b46b06ec2c4c4', token_count=1025, vector_point_id='ch-doc-card-521-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-521-12', 'doc-card-521', 'sec-card-521-5', 12, '، «اعتبار» «اجتماعی» می‌سازد: «تایید» «اجتماعی»، «جریان» را «بازتولید» می‌کند.  «تأثیرگر» در «اینستاگرام»: «اعتبار» شخصی «تأثیرگر»، «سرمایه» شبکه‌ای است: «محتوا» او از «موقعیت» او در شبکه «جریان» می‌یابد.  «بافت شبکه‌ای» در عمل: «هویت» «دیجیتال» یک «کاربر» در «بافت» شبکه «بازتولید» می‌شود: «رفتار» و «هویت»، «محصول» «ساختار» است.', '0c44daa6ebe289aae8e69427d12b93abf90fe4b3ec723e137ecbd2f9cc00d196', 600, 'ch-doc-card-521-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0c44daa6ebe289aae8e69427d12b93abf90fe4b3ec723e137ecbd2f9cc00d196', token_count=600, vector_point_id='ch-doc-card-521-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-521-13', 'doc-card-521', 'sec-card-521-6', 13, '۱. «شبکه» و «محتوا» از هم جدا نمی‌شوند: «تحلیل» صرف «ساختار»، «محتوا» را «محو» می‌کند: «محتوا» و «ساختار» در هم تنیده‌اند. ۲. «سرمایه شبکه‌ای» «سنجش‌پذیر» نیست: «ارزش» «موقعیت» در شبکه، «شاخص» واحد ندارد و «اندازه‌گیری» آن «دشواری» است. ۳. «اثر شبکه‌ای» «نامتقارن» است: «بزرگ‌تر» شدن شبکه، «ارزش» را «افزایش» می‌دهد اما «ارزش»، «توزیع» نمی‌شود: «مرکز» «بیشتر» برد می‌کند. ۴. «تأثیرگر» و «اعتبار»: «اعتبار» تأثیرگر، «بازتولید» «الگوریتم» است: «موقعیت» در شبکه، «تعیین» «الگوریتم» است و «اعتبار»، «ابزاری» می‌شود. ۵. «حلقه اجتماعی» و «فیلتربابل»: «حلقه»‌های «اجتماعی»، «محتوا» ر', '3469caf12f747583e95a176220b927f46875cb1fc71098e9c56dbd3919e2b726', 1047, 'ch-doc-card-521-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3469caf12f747583e95a176220b927f46875cb1fc71098e9c56dbd3919e2b726', token_count=1047, vector_point_id='ch-doc-card-521-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-521-14', 'doc-card-521', 'sec-card-521-7', 14, 'ا «بازتولید» می‌کنند اما «تنوع» را «محو» می‌کنند: «حلقه»، «بابل» می‌شود. ۶. «جریان اطلاعات» و «نظارت»: «جریان» «محتوا» در شبکه، «داده» تولید می‌کند و «نظارت» بر «جریان»، «حاکمیت» است. ۷. «بافت شبکه‌ای» و «هویت»: «هویت» «دیجیتال» در «بافت» شبکه «بازتولید» می‌شود اما «هویت» «آفلاین» «محو» نمی‌شود: «دیالکتیک» «آنلاین» و «آفلاین»، «بازتعریف» لازم دارد. ۸. «شبکه» و «قدرت» در هم تنیده‌اند: «موقعیت» در شبکه، «قدرت» است و «ساختار» شبکه، «قدرت» را «بازتولید» می‌کند. ۹. «شبکه» در «عصر الگوریتم» «بازتعریف» می‌شود: «الگوریتم»، «جریان» را «تعیین» می‌کند و «شبکه»، «الگوریتمی» می‌شود.', 'df3f6cb886d894882a05992b88970ab96b64f2de5b7a800d087e2677b0d75af9', 1047, 'ch-doc-card-521-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='df3f6cb886d894882a05992b88970ab96b64f2de5b7a800d087e2677b0d75af9', token_count=1047, vector_point_id='ch-doc-card-521-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-521-15', 'doc-card-521', 'sec-card-521-10', 15, 'کتاب «ساختار اجتماعی» (بدر، ۱۹۸۳)؛ کتاب «اثر شبکه‌ای» (کارلوس و همکاران، ۲۰۱۰)؛ کتاب «شبکه‌های اجتماعی و رسانه» (والگرن و همکاران، ۲۰۰۵)؛ کتاب «سرمایه شبکه‌ای» (بیر و همکاران، ۲۰۰۸).', '267bd487cac492d7d744a11d37965dbb6cf9ee51653f69e0213ee5c59013a532', 330, 'ch-doc-card-521-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='267bd487cac492d7d744a11d37965dbb6cf9ee51653f69e0213ee5c59013a532', token_count=330, vector_point_id='ch-doc-card-521-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-522-0', 'doc-card-522', NULL, 0, 'همسانی (لازارسفلد) می‌گوید افراد بر اساس شباهت‌های اجتماعی، فرهنگی و اقتصادی به یکدیگر پیوند می‌خورند؛ این سازوکار، جریان اطلاعات در شبکه‌های اجتماعی را محدود و حلقه‌های هم‌اندیش (echo chamber) را تقویت می‌سازد.', '9f1734979156331821ab51592c3d213fc81d5e27e7268d889b06e30554980ba7', 383, 'ch-doc-card-522-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9f1734979156331821ab51592c3d213fc81d5e27e7268d889b06e30554980ba7', token_count=383, vector_point_id='ch-doc-card-522-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-522-1', 'doc-card-522', 'sec-card-522-1', 1, 'شبکه‌های اجتماعی و نظریه شبکه  شبیهها با شبیهها پیوند میگیرند.', '059cd8a724dd7a2e714808169adf9ce18b54ec3e8554a6fb8e2ada4e36e14a72', 112, 'ch-doc-card-522-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='059cd8a724dd7a2e714808169adf9ce18b54ec3e8554a6fb8e2ada4e36e14a72', token_count=112, vector_point_id='ch-doc-card-522-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-522-2', 'doc-card-522', 'sec-card-522-2', 2, '۱. بنیان و منطق نظری همسانی «شبکه» را «ساختار» روابط می‌داند: نه «محتوا» بلکه «ارتباط» در کانون است. لازارسفلد (۱۹۵۴) در این چارچوب، «رفتار» را نه «ویژگی» فرد بلکه «محصول» «موقعیت» در شبکه تعریف کرد: «چه کسی» به «چه کسی» وصل است، «رفتار» را «شکل» می‌دهد.  بر اساس همسانی، «شبکه‌های اجتماعی» «میدان» تولید «معنا»، «اعتبار» و «قدرت»‌اند: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت» در شبکه، «ارزش» دارد. لازارسفلد (۱۹۵۴) در این چارچوب، «رسانه» را نه «پخش‌کننده» بلکه «میانجی» شبکه خواند: «رسانه»، «موقعیت» شبکه‌ای مخاطب را «بازتولید» می‌کند.  همسانی را می‌توان پاسخی به شکاف میان «تحلیل فرد» و «تحلیل ساختار» دانست: «رفتار»، «محصول» «شبکه» است و «تغییر»، «تغییر» «موقعیت» است.', '55f7bbb97e275fd0dd80a2493c6d9f9a9fa2192e1559cd0399ab9f7cea8a8a7f', 1225, 'ch-doc-card-522-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='55f7bbb97e275fd0dd80a2493c6d9f9a9fa2192e1559cd0399ab9f7cea8a8a7f', token_count=1225, vector_point_id='ch-doc-card-522-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-522-3', 'doc-card-522', 'sec-card-522-2', 3, 'لیل ساختار» دانست: «رفتار»، «محصول» «شبکه» است و «تغییر»، «تغییر» «موقعیت» است. لازارسفلد (۱۹۵۴) در این چارچوب، «شبکه» را نه «ابزار» بلکه «بافت» تعریف کرد: «بافت» شبکه‌ای، «هویت» و «رفتار» را «بازتولید» می‌کند.  ۲. ساختارهای مفهومی • ساختار شبکه (Network Structure): «الگو» روابط بین «گره‌ها» (فرد، رسانه، نهاد)؛ «ساختار»، «رفتار» را «شکل» می‌دهد. • گره و پیوند (Node and Tie): «گره» (فرد، رسانه) و «پیوند» (ارتباط)؛ «پیوند» «جریان» «معنا» و «سرمایه» است. • سرمایه شبکه‌ای (Network Capital): «ارزش» «موقعیت» در شبکه؛ «ارتباط» «اجتماعی»، «سرمایه» است. • اثر شبکه‌ای (Network Effect): «بزرگ‌تر» شدن «ارزش» شبکه با «افزایش» «عضو»؛ «محصول» و «بازار» یکجا می‌شوند.', '91f4741f5157b1620eda35445778ea76ab488d64adcce9f34664a0d1cbc02792', 1198, 'ch-doc-card-522-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='91f4741f5157b1620eda35445778ea76ab488d64adcce9f34664a0d1cbc02792', token_count=1198, vector_point_id='ch-doc-card-522-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-522-4', 'doc-card-522', 'sec-card-522-2', 4, '): «بزرگ‌تر» شدن «ارزش» شبکه با «افزایش» «عضو»؛ «محصول» و «بازار» یکجا می‌شوند. • حلقه اجتماعی (Social Loop): «جریان» «محتوا» در «حلقه»‌های «اجتماعی»: «اشتراک‌گذاری» و «تایید»، «اعتبار» می‌سازد. • تأثیرگر (Influencer): «گره» «کلیدی» در شبکه که «محتوا» را «بازتولید» می‌کند؛ «اعتبار» شخصی،', 'a930b1cccb5f5429600bbbbe553c555af97ef443b07f975a74f9b32ce389f52f', 523, 'ch-doc-card-522-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a930b1cccb5f5429600bbbbe553c555af97ef443b07f975a74f9b32ce389f52f', token_count=523, vector_point_id='ch-doc-card-522-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-522-5', 'doc-card-522', 'sec-card-522-3', 5, '• ساختار شبکه (Network Structure): «الگو» روابط بین «گره‌ها» (فرد، رسانه، نهاد)؛ «ساختار»، «رفتار» را «شکل» می‌دهد. • گره و پیوند (Node and Tie): «گره» (فرد، رسانه) و «پیوند» (ارتباط)؛ «پیوند» «جریان» «معنا» و «سرمایه» است. • سرمایه شبکه‌ای (Network Capital): «ارزش» «موقعیت» در شبکه؛ «ارتباط» «اجتماعی»، «سرمایه» است. • اثر شبکه‌ای (Network Effect): «بزرگ‌تر» شدن «ارزش» شبکه با «افزایش» «عضو»؛ «محصول» و «بازار» یکجا می‌شوند. • حلقه اجتماعی (Social Loop): «جریان» «محتوا» در «حلقه»‌های «اجتماعی»: «اشتراک‌گذاری» و «تایید»، «اعتبار» می‌سازد. • تأثیرگر (Influencer): «گره» «کلیدی» در شبکه که «محتوا» را «بازتولید» می‌کند؛ «اعتبار» شخصی، «سرمایه» شبکه‌ای است.', '5ba5c7db967fcca10a31d3ceb7258cda8b6d048d4e341937c83e9ac983bd32af', 1196, 'ch-doc-card-522-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5ba5c7db967fcca10a31d3ceb7258cda8b6d048d4e341937c83e9ac983bd32af', token_count=1196, vector_point_id='ch-doc-card-522-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-522-6', 'doc-card-522', 'sec-card-522-3', 6, '» در شبکه که «محتوا» را «بازتولید» می‌کند؛ «اعتبار» شخصی، «سرمایه» شبکه‌ای است. • بافت شبکه‌ای (Networked Context): «بافت» که در آن «رفتار» و «هویت» «بازتولید» می‌شوند؛ «بافت»، «ساختار» است. • جریان اطلاعات (Information Flow): «جریان» «محتوا» در شبکه: «مسیر»، «سرعت» و «حجم» «جریان»، «بازتولید» «معنا» است.', 'db9ec0e0560590ef7363df458568a4fad133d94601ef21aab6b9272fe7a76b3e', 556, 'ch-doc-card-522-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='db9ec0e0560590ef7363df458568a4fad133d94601ef21aab6b9272fe7a76b3e', token_count=556, vector_point_id='ch-doc-card-522-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-522-7', 'doc-card-522', 'sec-card-522-4', 7, '«سرمایه» شبکه‌ای است. • بافت شبکه‌ای (Networked Context): «بافت» که در آن «رفتار» و «هویت» «بازتولید» می‌شوند؛ «بافت»، «ساختار» است. • جریان اطلاعات (Information Flow): «جریان» «محتوا» در شبکه: «مسیر»، «سرعت» و «حجم» «جریان»، «بازتولید» «معنا» است.  ۳. نمونه‌های تحلیلی «ساختار شبکه» در عمل: وقتی «خبر» در «شبکه‌ی اجتماعی» «گسترش» می‌یابد، «مسیر» آن از «گره»‌های «کلیدی» (تأثیرگرها) است: «ساختار»، «جریان» را «تعیین» می‌کند.  «سرمایه شبکه‌ای» در عمل: «اعتبار» یک «تأثیرگر» از «موقعیت» او در شبکه است: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت»، «ارزش» دارد.', '247bb6657632114ba71ee6ff6f50b31c5256f8100392d542ed562313674a2a80', 1014, 'ch-doc-card-522-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='247bb6657632114ba71ee6ff6f50b31c5256f8100392d542ed562313674a2a80', token_count=1014, vector_point_id='ch-doc-card-522-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-522-8', 'doc-card-522', 'sec-card-522-4', 8, 'عیت» او در شبکه است: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت»، «ارزش» دارد.  «اثر شبکه‌ای» در «فیسبوک»: هر «عضو» جدیدی که «می‌آید»، «ارزش» شبکه را برای «همه» «بالاتر» می‌برد: «محصول» و «بازار» یکجا می‌شوند.  «حلقه اجتماعی» در عمل: «اشتراک‌گذاری» یک «خبر» در «حلقه» «دوستان»، «اعتبار» «اجتماعی» می‌سازد: «تایید» «اجتماعی»، «جریان» را «بازتولید» می‌کند.  «تأثیرگر» در «اینستاگرام»: «اعتبار» شخصی «تأثیرگر»، «سرمایه» شبکه‌ای است: «محتوا» او از «موقعیت» او در شبکه «جریان» می‌یابد.  «بافت شبکه‌ای» در عمل: «هویت» «دیجیتال» یک «کاربر» در «بافت» شبکه «بازتولید» می‌شود: «رفتار» و «هویت»، «محصول» «ساختار» است.  ۴. نقدها و چالش‌ها ۱.', '399c48d251f87ea37c6ae3f34383931c054216b738810f83e6b5bec01decfea5', 1143, 'ch-doc-card-522-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='399c48d251f87ea37c6ae3f34383931c054216b738810f83e6b5bec01decfea5', token_count=1143, vector_point_id='ch-doc-card-522-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-522-9', 'doc-card-522', 'sec-card-522-4', 9, 'ازتولید» می‌شود: «رفتار» و «هویت»، «محصول» «ساختار» است.  ۴. نقدها و چالش‌ها ۱. «شبکه» و «محتوا» از هم جدا نمی‌شوند: «تحلیل» صرف «ساختار»، «محتوا» را «محو» می‌کند: «محتوا» و «ساختار» در هم تنیده‌اند. ۲. «سرمایه شبکه‌ای» «سنجش‌پذیر» نیست: «ارزش» «موقعیت» در شبکه، «شاخص» واحد ندارد و «اندازه‌گیری» آن «دشواری» است. ۳. «اثر شبکه‌ای» «نامتقارن» است: «بزرگ‌تر» شدن شبکه، «ارزش» را «افزایش» می‌دهد اما «ارزش»، «توزیع» نمی‌شود: «مرکز» «بیشتر', 'c7e0aa5244dbac7d3d2d1a98d596d7387ed3a1e29acabca934402a11e0ec7b13', 790, 'ch-doc-card-522-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c7e0aa5244dbac7d3d2d1a98d596d7387ed3a1e29acabca934402a11e0ec7b13', token_count=790, vector_point_id='ch-doc-card-522-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-522-10', 'doc-card-522', 'sec-card-522-5', 10, '«ساختار شبکه» در عمل: وقتی «خبر» در «شبکه‌ی اجتماعی» «گسترش» می‌یابد، «مسیر» آن از «گره»‌های «کلیدی» (تأثیرگرها) است: «ساختار»، «جریان» را «تعیین» می‌کند.  «سرمایه شبکه‌ای» در عمل: «اعتبار» یک «تأثیرگر» از «موقعیت» او در شبکه است: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت»، «ارزش» دارد.  «اثر شبکه‌ای» در «فیسبوک»: هر «عضو» جدیدی که «می‌آید»، «ارزش» شبکه را برای «همه» «بالاتر» می‌برد: «محصول» و «بازار» یکجا می‌شوند.  «حلقه اجتماعی» در عمل: «اشتراک‌گذاری» یک «خبر» در «حلقه» «دوستان»، «اعتبار» «اجتماعی» می‌سازد: «تایید» «اجتماعی»، «جریان» را «بازتولید» می‌کند.', '591acce302984742f99aaeba653caba140e13292a9114cff4d0b46b06ec2c4c4', 1025, 'ch-doc-card-522-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='591acce302984742f99aaeba653caba140e13292a9114cff4d0b46b06ec2c4c4', token_count=1025, vector_point_id='ch-doc-card-522-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-522-11', 'doc-card-522', 'sec-card-522-5', 11, '، «اعتبار» «اجتماعی» می‌سازد: «تایید» «اجتماعی»، «جریان» را «بازتولید» می‌کند.  «تأثیرگر» در «اینستاگرام»: «اعتبار» شخصی «تأثیرگر»، «سرمایه» شبکه‌ای است: «محتوا» او از «موقعیت» او در شبکه «جریان» می‌یابد.  «بافت شبکه‌ای» در عمل: «هویت» «دیجیتال» یک «کاربر» در «بافت» شبکه «بازتولید» می‌شود: «رفتار» و «هویت»، «محصول» «ساختار» است.', '0c44daa6ebe289aae8e69427d12b93abf90fe4b3ec723e137ecbd2f9cc00d196', 600, 'ch-doc-card-522-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0c44daa6ebe289aae8e69427d12b93abf90fe4b3ec723e137ecbd2f9cc00d196', token_count=600, vector_point_id='ch-doc-card-522-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-522-12', 'doc-card-522', 'sec-card-522-6', 12, '۱. «شبکه» و «محتوا» از هم جدا نمی‌شوند: «تحلیل» صرف «ساختار»، «محتوا» را «محو» می‌کند: «محتوا» و «ساختار» در هم تنیده‌اند. ۲. «سرمایه شبکه‌ای» «سنجش‌پذیر» نیست: «ارزش» «موقعیت» در شبکه، «شاخص» واحد ندارد و «اندازه‌گیری» آن «دشواری» است. ۳. «اثر شبکه‌ای» «نامتقارن» است: «بزرگ‌تر» شدن شبکه، «ارزش» را «افزایش» می‌دهد اما «ارزش»، «توزیع» نمی‌شود: «مرکز» «بیشتر» برد می‌کند. ۴. «تأثیرگر» و «اعتبار»: «اعتبار» تأثیرگر، «بازتولید» «الگوریتم» است: «موقعیت» در شبکه، «تعیین» «الگوریتم» است و «اعتبار»، «ابزاری» می‌شود. ۵. «حلقه اجتماعی» و «فیلتربابل»: «حلقه»‌های «اجتماعی»، «محتوا» ر', '3469caf12f747583e95a176220b927f46875cb1fc71098e9c56dbd3919e2b726', 1047, 'ch-doc-card-522-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3469caf12f747583e95a176220b927f46875cb1fc71098e9c56dbd3919e2b726', token_count=1047, vector_point_id='ch-doc-card-522-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-522-13', 'doc-card-522', 'sec-card-522-7', 13, 'ا «بازتولید» می‌کنند اما «تنوع» را «محو» می‌کنند: «حلقه»، «بابل» می‌شود. ۶. «جریان اطلاعات» و «نظارت»: «جریان» «محتوا» در شبکه، «داده» تولید می‌کند و «نظارت» بر «جریان»، «حاکمیت» است. ۷. «بافت شبکه‌ای» و «هویت»: «هویت» «دیجیتال» در «بافت» شبکه «بازتولید» می‌شود اما «هویت» «آفلاین» «محو» نمی‌شود: «دیالکتیک» «آنلاین» و «آفلاین»، «بازتعریف» لازم دارد. ۸. «شبکه» و «قدرت» در هم تنیده‌اند: «موقعیت» در شبکه، «قدرت» است و «ساختار» شبکه، «قدرت» را «بازتولید» می‌کند. ۹. «شبکه» در «عصر الگوریتم» «بازتعریف» می‌شود: «الگوریتم»، «جریان» را «تعیین» می‌کند و «شبکه»، «الگوریتمی» می‌شود.', 'df3f6cb886d894882a05992b88970ab96b64f2de5b7a800d087e2677b0d75af9', 1047, 'ch-doc-card-522-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='df3f6cb886d894882a05992b88970ab96b64f2de5b7a800d087e2677b0d75af9', token_count=1047, vector_point_id='ch-doc-card-522-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-522-14', 'doc-card-522', 'sec-card-522-10', 14, 'کتاب «ساختار اجتماعی» (بدر، ۱۹۸۳)؛ کتاب «اثر شبکه‌ای» (کارلوس و همکاران، ۲۰۱۰)؛ کتاب «شبکه‌های اجتماعی و رسانه» (والگرن و همکاران، ۲۰۰۵)؛ کتاب «سرمایه شبکه‌ای» (بیر و همکاران، ۲۰۰۸).', '267bd487cac492d7d744a11d37965dbb6cf9ee51653f69e0213ee5c59013a532', 330, 'ch-doc-card-522-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='267bd487cac492d7d744a11d37965dbb6cf9ee51653f69e0213ee5c59013a532', token_count=330, vector_point_id='ch-doc-card-522-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-523-0', 'doc-card-523', NULL, 0, 'نظریه تسهیم نوآوری (راجرز، ۱۹۶۲) پذیرش یک نوآوری را فرایندی زمانی می‌داند که در آن افراد بر اساس تمایلات و موقعیت شبکه‌ای‌شان به گروه‌های نوآور، زودهنگام، اکثریت اولیه، اکثریت دیرهنگام و عقب‌مانده تقسیم می‌شوند.', 'af61eb7fd6690f369a9bb24a54eb8a5eeba08c42f5e348f2d3a49b4d7665a671', 383, 'ch-doc-card-523-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='af61eb7fd6690f369a9bb24a54eb8a5eeba08c42f5e348f2d3a49b4d7665a671', token_count=383, vector_point_id='ch-doc-card-523-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-523-1', 'doc-card-523', 'sec-card-523-1', 1, 'شبکه‌های اجتماعی و نظریه شبکه  پذیرندگان نوآور تا عقبمانده.', 'b7dc9ec7874996a375d33bf97cb069d9965aa2a0946f9d64fe6523d92cb91a30', 107, 'ch-doc-card-523-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b7dc9ec7874996a375d33bf97cb069d9965aa2a0946f9d64fe6523d92cb91a30', token_count=107, vector_point_id='ch-doc-card-523-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-523-2', 'doc-card-523', 'sec-card-523-2', 2, '۱. بنیان و منطق نظری تسهیم نوآوری «شبکه» را «ساختار» روابط می‌داند: نه «محتوا» بلکه «ارتباط» در کانون است. اورت راجرز (۱۹۶۲) در این چارچوب، «رفتار» را نه «ویژگی» فرد بلکه «محصول» «موقعیت» در شبکه تعریف کرد: «چه کسی» به «چه کسی» وصل است، «رفتار» را «شکل» می‌دهد.  بر اساس تسهیم نوآوری، «شبکه‌های اجتماعی» «میدان» تولید «معنا»، «اعتبار» و «قدرت»‌اند: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت» در شبکه، «ارزش» دارد. اورت راجرز (۱۹۶۲) در این چارچوب، «رسانه» را نه «پخش‌کننده» بلکه «میانجی» شبکه خواند: «رسانه»، «موقعیت» شبکه‌ای مخاطب را «بازتولید» می‌کند.', '4f0dbe76ca0f7dfbda39926a63cfe6bef50998aede48085b81913a01f1c49e8f', 1005, 'ch-doc-card-523-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4f0dbe76ca0f7dfbda39926a63cfe6bef50998aede48085b81913a01f1c49e8f', token_count=1005, vector_point_id='ch-doc-card-523-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-523-3', 'doc-card-523', 'sec-card-523-2', 3, 'لکه «میانجی» شبکه خواند: «رسانه»، «موقعیت» شبکه‌ای مخاطب را «بازتولید» می‌کند.  تسهیم نوآوری را می‌توان پاسخی به شکاف میان «تحلیل فرد» و «تحلیل ساختار» دانست: «رفتار»، «محصول» «شبکه» است و «تغییر»، «تغییر» «موقعیت» است. اورت راجرز (۱۹۶۲) در این چارچوب، «شبکه» را نه «ابزار» بلکه «بافت» تعریف کرد: «بافت» شبکه‌ای، «هویت» و «رفتار» را «بازتولید» می‌کند.  ۲. ساختارهای مفهومی • ساختار شبکه (Network Structure): «الگو» روابط بین «گره‌ها» (فرد، رسانه، نهاد)؛ «ساختار»، «رفتار» را «شکل» می‌دهد. • گره و پیوند (Node and Tie): «گره» (فرد، رسانه) و «پیوند» (ارتباط)؛ «پیوند» «جریان» «معنا» و «سرمایه» است.', '921cafdbbc7072c1aaabd4e3f9efaa01e3413eb81718ca57445b3ff8ed9a1c78', 1083, 'ch-doc-card-523-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='921cafdbbc7072c1aaabd4e3f9efaa01e3413eb81718ca57445b3ff8ed9a1c78', token_count=1083, vector_point_id='ch-doc-card-523-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-523-4', 'doc-card-523', 'sec-card-523-2', 4, ': «گره» (فرد، رسانه) و «پیوند» (ارتباط)؛ «پیوند» «جریان» «معنا» و «سرمایه» است. • سرمایه شبکه‌ای (Network Capital): «ارزش» «موقعیت» در شبکه؛ «ارتباط» «اجتماعی»، «سرمایه» است. • اثر شبکه‌ای (Network Effect): «بزرگ‌تر» شدن «ارزش» شبکه با «افزایش» «عضو»؛ «محصول» و «بازار» یکجا می‌شوند. • حلقه اجتماعی (Social Loop): «جریان» «محتوا» در «حلقه»‌های «اجتماعی»: «اشتراک‌گذاری» و «تایید»، «اعتبار» می‌سازد. • تأثیرگر (Influencer): «گره» «کلیدی» در شبکه که «محتوا» را «بازتولید» می‌کند؛ «اع', '8d330cff014ef35738889e9a76b6abea4f39fac50bc70bba9d63531514483932', 874, 'ch-doc-card-523-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8d330cff014ef35738889e9a76b6abea4f39fac50bc70bba9d63531514483932', token_count=874, vector_point_id='ch-doc-card-523-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-523-5', 'doc-card-523', 'sec-card-523-3', 5, '• ساختار شبکه (Network Structure): «الگو» روابط بین «گره‌ها» (فرد، رسانه، نهاد)؛ «ساختار»، «رفتار» را «شکل» می‌دهد. • گره و پیوند (Node and Tie): «گره» (فرد، رسانه) و «پیوند» (ارتباط)؛ «پیوند» «جریان» «معنا» و «سرمایه» است. • سرمایه شبکه‌ای (Network Capital): «ارزش» «موقعیت» در شبکه؛ «ارتباط» «اجتماعی»، «سرمایه» است. • اثر شبکه‌ای (Network Effect): «بزرگ‌تر» شدن «ارزش» شبکه با «افزایش» «عضو»؛ «محصول» و «بازار» یکجا می‌شوند. • حلقه اجتماعی (Social Loop): «جریان» «محتوا» در «حلقه»‌های «اجتماعی»: «اشتراک‌گذاری» و «تایید»، «اعتبار» می‌سازد. • تأثیرگر (Influencer): «گره» «کلیدی» در شبکه که «محتوا» را «بازتولید» می‌کند؛ «اعتبار» شخصی، «سرمایه» شبکه‌ای است.', '5ba5c7db967fcca10a31d3ceb7258cda8b6d048d4e341937c83e9ac983bd32af', 1196, 'ch-doc-card-523-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5ba5c7db967fcca10a31d3ceb7258cda8b6d048d4e341937c83e9ac983bd32af', token_count=1196, vector_point_id='ch-doc-card-523-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-523-6', 'doc-card-523', 'sec-card-523-3', 6, '» در شبکه که «محتوا» را «بازتولید» می‌کند؛ «اعتبار» شخصی، «سرمایه» شبکه‌ای است. • بافت شبکه‌ای (Networked Context): «بافت» که در آن «رفتار» و «هویت» «بازتولید» می‌شوند؛ «بافت»، «ساختار» است. • جریان اطلاعات (Information Flow): «جریان» «محتوا» در شبکه: «مسیر»، «سرعت» و «حجم» «جریان»، «بازتولید» «معنا» است.', 'db9ec0e0560590ef7363df458568a4fad133d94601ef21aab6b9272fe7a76b3e', 556, 'ch-doc-card-523-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='db9ec0e0560590ef7363df458568a4fad133d94601ef21aab6b9272fe7a76b3e', token_count=556, vector_point_id='ch-doc-card-523-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-523-7', 'doc-card-523', 'sec-card-523-4', 7, 'تبار» شخصی، «سرمایه» شبکه‌ای است. • بافت شبکه‌ای (Networked Context): «بافت» که در آن «رفتار» و «هویت» «بازتولید» می‌شوند؛ «بافت»، «ساختار» است. • جریان اطلاعات (Information Flow): «جریان» «محتوا» در شبکه: «مسیر»، «سرعت» و «حجم» «جریان»، «بازتولید» «معنا» است.  ۳. نمونه‌های تحلیلی «ساختار شبکه» در عمل: وقتی «خبر» در «شبکه‌ی اجتماعی» «گسترش» می‌یابد، «مسیر» آن از «گره»‌های «کلیدی» (تأثیرگرها) است: «ساختار»، «جریان» را «تعیین» می‌کند.  «سرمایه شبکه‌ای» در عمل: «اعتبار» یک «تأثیرگر» از «موقعیت» او در شبکه است: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت»، «ارزش» دارد.', '4a2db377caf93ddf92e143366551c335d02c58ddfe42a1688b66196489f3ad81', 1036, 'ch-doc-card-523-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4a2db377caf93ddf92e143366551c335d02c58ddfe42a1688b66196489f3ad81', token_count=1036, vector_point_id='ch-doc-card-523-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-523-8', 'doc-card-523', 'sec-card-523-4', 8, 'عیت» او در شبکه است: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت»، «ارزش» دارد.  «اثر شبکه‌ای» در «فیسبوک»: هر «عضو» جدیدی که «می‌آید»، «ارزش» شبکه را برای «همه» «بالاتر» می‌برد: «محصول» و «بازار» یکجا می‌شوند.  «حلقه اجتماعی» در عمل: «اشتراک‌گذاری» یک «خبر» در «حلقه» «دوستان»، «اعتبار» «اجتماعی» می‌سازد: «تایید» «اجتماعی»، «جریان» را «بازتولید» می‌کند.  «تأثیرگر» در «اینستاگرام»: «اعتبار» شخصی «تأثیرگر»، «سرمایه» شبکه‌ای است: «محتوا» او از «موقعیت» او در شبکه «جریان» می‌یابد.  «بافت شبکه‌ای» در عمل: «هویت» «دیجیتال» یک «کاربر» در «بافت» شبکه «بازتولید» می‌شود: «رفتار» و «هویت»، «محصول» «ساختار» است.  ۴. نقدها و چالش‌ها ۱.', '399c48d251f87ea37c6ae3f34383931c054216b738810f83e6b5bec01decfea5', 1143, 'ch-doc-card-523-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='399c48d251f87ea37c6ae3f34383931c054216b738810f83e6b5bec01decfea5', token_count=1143, vector_point_id='ch-doc-card-523-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-523-9', 'doc-card-523', 'sec-card-523-4', 9, 'ازتولید» می‌شود: «رفتار» و «هویت»، «محصول» «ساختار» است.  ۴. نقدها و چالش‌ها ۱. «شبکه» و «محتوا» از هم جدا نمی‌شوند: «تحلیل» صرف «ساختار»، «محتوا» را «محو» می‌کند: «محتوا» و «ساختار» در هم تنیده‌اند. ۲. «سرمایه شبکه‌ای» «سنجش‌پذیر» نیست: «ارزش» «موقعیت» در شبکه، «شاخص» واحد ندارد و «اندازه‌گیری» آن «دشواری» است. ۳. «اثر شبکه‌ای» «نامتقارن» است: «بزرگ‌تر» شدن شبکه، «ارزش» را «افزایش» می‌دهد اما «ارزش»، «توزیع» نمی‌شود: «مرکز» «بی', 'c7f10006f76c44b7fd6e869be74eb4d9108dca812e504effe76a88d8a7f5902c', 785, 'ch-doc-card-523-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c7f10006f76c44b7fd6e869be74eb4d9108dca812e504effe76a88d8a7f5902c', token_count=785, vector_point_id='ch-doc-card-523-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-523-10', 'doc-card-523', 'sec-card-523-5', 10, '«ساختار شبکه» در عمل: وقتی «خبر» در «شبکه‌ی اجتماعی» «گسترش» می‌یابد، «مسیر» آن از «گره»‌های «کلیدی» (تأثیرگرها) است: «ساختار»، «جریان» را «تعیین» می‌کند.  «سرمایه شبکه‌ای» در عمل: «اعتبار» یک «تأثیرگر» از «موقعیت» او در شبکه است: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت»، «ارزش» دارد.  «اثر شبکه‌ای» در «فیسبوک»: هر «عضو» جدیدی که «می‌آید»، «ارزش» شبکه را برای «همه» «بالاتر» می‌برد: «محصول» و «بازار» یکجا می‌شوند.  «حلقه اجتماعی» در عمل: «اشتراک‌گذاری» یک «خبر» در «حلقه» «دوستان»، «اعتبار» «اجتماعی» می‌سازد: «تایید» «اجتماعی»، «جریان» را «بازتولید» می‌کند.', '591acce302984742f99aaeba653caba140e13292a9114cff4d0b46b06ec2c4c4', 1025, 'ch-doc-card-523-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='591acce302984742f99aaeba653caba140e13292a9114cff4d0b46b06ec2c4c4', token_count=1025, vector_point_id='ch-doc-card-523-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-523-11', 'doc-card-523', 'sec-card-523-5', 11, '، «اعتبار» «اجتماعی» می‌سازد: «تایید» «اجتماعی»، «جریان» را «بازتولید» می‌کند.  «تأثیرگر» در «اینستاگرام»: «اعتبار» شخصی «تأثیرگر»، «سرمایه» شبکه‌ای است: «محتوا» او از «موقعیت» او در شبکه «جریان» می‌یابد.  «بافت شبکه‌ای» در عمل: «هویت» «دیجیتال» یک «کاربر» در «بافت» شبکه «بازتولید» می‌شود: «رفتار» و «هویت»، «محصول» «ساختار» است.', '0c44daa6ebe289aae8e69427d12b93abf90fe4b3ec723e137ecbd2f9cc00d196', 600, 'ch-doc-card-523-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0c44daa6ebe289aae8e69427d12b93abf90fe4b3ec723e137ecbd2f9cc00d196', token_count=600, vector_point_id='ch-doc-card-523-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-523-12', 'doc-card-523', 'sec-card-523-6', 12, '۱. «شبکه» و «محتوا» از هم جدا نمی‌شوند: «تحلیل» صرف «ساختار»، «محتوا» را «محو» می‌کند: «محتوا» و «ساختار» در هم تنیده‌اند. ۲. «سرمایه شبکه‌ای» «سنجش‌پذیر» نیست: «ارزش» «موقعیت» در شبکه، «شاخص» واحد ندارد و «اندازه‌گیری» آن «دشواری» است. ۳. «اثر شبکه‌ای» «نامتقارن» است: «بزرگ‌تر» شدن شبکه، «ارزش» را «افزایش» می‌دهد اما «ارزش»، «توزیع» نمی‌شود: «مرکز» «بیشتر» برد می‌کند. ۴. «تأثیرگر» و «اعتبار»: «اعتبار» تأثیرگر، «بازتولید» «الگوریتم» است: «موقعیت» در شبکه، «تعیین» «الگوریتم» است و «اعتبار»، «ابزاری» می‌شود. ۵. «حلقه اجتماعی» و «فیلتربابل»: «حلقه»‌های «اجتماعی»، «محتوا» ر', '3469caf12f747583e95a176220b927f46875cb1fc71098e9c56dbd3919e2b726', 1047, 'ch-doc-card-523-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3469caf12f747583e95a176220b927f46875cb1fc71098e9c56dbd3919e2b726', token_count=1047, vector_point_id='ch-doc-card-523-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-523-13', 'doc-card-523', 'sec-card-523-7', 13, 'ا «بازتولید» می‌کنند اما «تنوع» را «محو» می‌کنند: «حلقه»، «بابل» می‌شود. ۶. «جریان اطلاعات» و «نظارت»: «جریان» «محتوا» در شبکه، «داده» تولید می‌کند و «نظارت» بر «جریان»، «حاکمیت» است. ۷. «بافت شبکه‌ای» و «هویت»: «هویت» «دیجیتال» در «بافت» شبکه «بازتولید» می‌شود اما «هویت» «آفلاین» «محو» نمی‌شود: «دیالکتیک» «آنلاین» و «آفلاین»، «بازتعریف» لازم دارد. ۸. «شبکه» و «قدرت» در هم تنیده‌اند: «موقعیت» در شبکه، «قدرت» است و «ساختار» شبکه، «قدرت» را «بازتولید» می‌کند. ۹. «شبکه» در «عصر الگوریتم» «بازتعریف» می‌شود: «الگوریتم»، «جریان» را «تعیین» می‌کند و «شبکه»، «الگوریتمی» می‌شود.', 'df3f6cb886d894882a05992b88970ab96b64f2de5b7a800d087e2677b0d75af9', 1047, 'ch-doc-card-523-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='df3f6cb886d894882a05992b88970ab96b64f2de5b7a800d087e2677b0d75af9', token_count=1047, vector_point_id='ch-doc-card-523-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-523-14', 'doc-card-523', 'sec-card-523-10', 14, 'کتاب «ساختار اجتماعی» (بدر، ۱۹۸۳)؛ کتاب «اثر شبکه‌ای» (کارلوس و همکاران، ۲۰۱۰)؛ کتاب «شبکه‌های اجتماعی و رسانه» (والگرن و همکاران، ۲۰۰۵)؛ کتاب «سرمایه شبکه‌ای» (بیر و همکاران، ۲۰۰۸).', '267bd487cac492d7d744a11d37965dbb6cf9ee51653f69e0213ee5c59013a532', 330, 'ch-doc-card-523-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='267bd487cac492d7d744a11d37965dbb6cf9ee51653f69e0213ee5c59013a532', token_count=330, vector_point_id='ch-doc-card-523-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-524-0', 'doc-card-524', NULL, 0, 'شماره دانبار (۱۹۹۲) می‌گوید ظرفیت شناختی انسان حدود ۱۵۰ ارتباط پایدار و معنادار را محدود می‌سازد؛ این حد بیولوژیکی، ساختار گروه‌های اجتماعی، سازمان‌ها و حتی طراحی شبکه‌های دیجیتال را شکل می‌دهد.', '30191c6aa1a6ed4496308215e4f3acdf461975f6c7e3e7106d4411ed3854fc69', 352, 'ch-doc-card-524-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='30191c6aa1a6ed4496308215e4f3acdf461975f6c7e3e7106d4411ed3854fc69', token_count=352, vector_point_id='ch-doc-card-524-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-524-1', 'doc-card-524', 'sec-card-524-1', 1, 'شبکه‌های اجتماعی و نظریه شبکه  محدودیت شناختی اندازه شبکه.', '513479df55d9c422df45e07d0356dc4aa02ece4a81d792dee5eaab7e8b7227b4', 105, 'ch-doc-card-524-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='513479df55d9c422df45e07d0356dc4aa02ece4a81d792dee5eaab7e8b7227b4', token_count=105, vector_point_id='ch-doc-card-524-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-524-2', 'doc-card-524', 'sec-card-524-2', 2, '۱. بنیان و منطق نظری شماره دانبار «شبکه» را «ساختار» روابط می‌داند: نه «محتوا» بلکه «ارتباط» در کانون است. دانبار (۱۹۹۲) در این چارچوب، «رفتار» را نه «ویژگی» فرد بلکه «محصول» «موقعیت» در شبکه تعریف کرد: «چه کسی» به «چه کسی» وصل است، «رفتار» را «شکل» می‌دهد.  بر اساس شماره دانبار، «شبکه‌های اجتماعی» «میدان» تولید «معنا»، «اعتبار» و «قدرت»‌اند: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت» در شبکه، «ارزش» دارد. دانبار (۱۹۹۲) در این چارچوب، «رسانه» را نه «پخش‌کننده» بلکه «میانجی» شبکه خواند: «رسانه»، «موقعیت» شبکه‌ای مخاطب را «بازتولید» می‌کند.', '1b381f29c8bc433c3413509cf99ecaf0fa203da8ee8e1ae2976f92e656dd0df5', 990, 'ch-doc-card-524-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1b381f29c8bc433c3413509cf99ecaf0fa203da8ee8e1ae2976f92e656dd0df5', token_count=990, vector_point_id='ch-doc-card-524-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-524-3', 'doc-card-524', 'sec-card-524-2', 3, 'لکه «میانجی» شبکه خواند: «رسانه»، «موقعیت» شبکه‌ای مخاطب را «بازتولید» می‌کند.  شماره دانبار را می‌توان پاسخی به شکاف میان «تحلیل فرد» و «تحلیل ساختار» دانست: «رفتار»، «محصول» «شبکه» است و «تغییر»، «تغییر» «موقعیت» است. دانبار (۱۹۹۲) در این چارچوب، «شبکه» را نه «ابزار» بلکه «بافت» تعریف کرد: «بافت» شبکه‌ای، «هویت» و «رفتار» را «بازتولید» می‌کند.  ۲. ساختارهای مفهومی • ساختار شبکه (Network Structure): «الگو» روابط بین «گره‌ها» (فرد، رسانه، نهاد)؛ «ساختار»، «رفتار» را «شکل» می‌دهد. • گره و پیوند (Node and Tie): «گره» (فرد، رسانه) و «پیوند» (ارتباط)؛ «پیوند» «جریان» «معنا» و «سرمایه» است.', '98eaf56beb4dc821aee87b027014db009ed7e0755270888bbe9cd524a6af19dc', 1076, 'ch-doc-card-524-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='98eaf56beb4dc821aee87b027014db009ed7e0755270888bbe9cd524a6af19dc', token_count=1076, vector_point_id='ch-doc-card-524-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-524-4', 'doc-card-524', 'sec-card-524-2', 4, ': «گره» (فرد، رسانه) و «پیوند» (ارتباط)؛ «پیوند» «جریان» «معنا» و «سرمایه» است. • سرمایه شبکه‌ای (Network Capital): «ارزش» «موقعیت» در شبکه؛ «ارتباط» «اجتماعی»، «سرمایه» است. • اثر شبکه‌ای (Network Effect): «بزرگ‌تر» شدن «ارزش» شبکه با «افزایش» «عضو»؛ «محصول» و «بازار» یکجا می‌شوند. • حلقه اجتماعی (Social Loop): «جریان» «محتوا» در «حلقه»‌های «اجتماعی»: «اشتراک‌گذاری» و «تایید»، «اعتبار» می‌سازد. • تأثیرگر (Influencer): «گره» «کلیدی» در شبکه که «محتوا» را «بازتولید» می‌کند؛ «اعتبار» شخ', '91455cbe098eb20dac32e28472b63806836c27db64802608dbbc5242fd55f0d6', 889, 'ch-doc-card-524-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='91455cbe098eb20dac32e28472b63806836c27db64802608dbbc5242fd55f0d6', token_count=889, vector_point_id='ch-doc-card-524-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-524-5', 'doc-card-524', 'sec-card-524-3', 5, '• ساختار شبکه (Network Structure): «الگو» روابط بین «گره‌ها» (فرد، رسانه، نهاد)؛ «ساختار»، «رفتار» را «شکل» می‌دهد. • گره و پیوند (Node and Tie): «گره» (فرد، رسانه) و «پیوند» (ارتباط)؛ «پیوند» «جریان» «معنا» و «سرمایه» است. • سرمایه شبکه‌ای (Network Capital): «ارزش» «موقعیت» در شبکه؛ «ارتباط» «اجتماعی»، «سرمایه» است. • اثر شبکه‌ای (Network Effect): «بزرگ‌تر» شدن «ارزش» شبکه با «افزایش» «عضو»؛ «محصول» و «بازار» یکجا می‌شوند. • حلقه اجتماعی (Social Loop): «جریان» «محتوا» در «حلقه»‌های «اجتماعی»: «اشتراک‌گذاری» و «تایید»، «اعتبار» می‌سازد. • تأثیرگر (Influencer): «گره» «کلیدی» در شبکه که «محتوا» را «بازتولید» می‌کند؛ «اعتبار» شخصی، «سرمایه» شبکه‌ای است.', '5ba5c7db967fcca10a31d3ceb7258cda8b6d048d4e341937c83e9ac983bd32af', 1196, 'ch-doc-card-524-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5ba5c7db967fcca10a31d3ceb7258cda8b6d048d4e341937c83e9ac983bd32af', token_count=1196, vector_point_id='ch-doc-card-524-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-524-6', 'doc-card-524', 'sec-card-524-3', 6, '» در شبکه که «محتوا» را «بازتولید» می‌کند؛ «اعتبار» شخصی، «سرمایه» شبکه‌ای است. • بافت شبکه‌ای (Networked Context): «بافت» که در آن «رفتار» و «هویت» «بازتولید» می‌شوند؛ «بافت»، «ساختار» است. • جریان اطلاعات (Information Flow): «جریان» «محتوا» در شبکه: «مسیر»، «سرعت» و «حجم» «جریان»، «بازتولید» «معنا» است.', 'db9ec0e0560590ef7363df458568a4fad133d94601ef21aab6b9272fe7a76b3e', 556, 'ch-doc-card-524-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='db9ec0e0560590ef7363df458568a4fad133d94601ef21aab6b9272fe7a76b3e', token_count=556, vector_point_id='ch-doc-card-524-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-524-7', 'doc-card-524', 'sec-card-524-4', 7, 'صی، «سرمایه» شبکه‌ای است. • بافت شبکه‌ای (Networked Context): «بافت» که در آن «رفتار» و «هویت» «بازتولید» می‌شوند؛ «بافت»، «ساختار» است. • جریان اطلاعات (Information Flow): «جریان» «محتوا» در شبکه: «مسیر»، «سرعت» و «حجم» «جریان»، «بازتولید» «معنا» است.  ۳. نمونه‌های تحلیلی «ساختار شبکه» در عمل: وقتی «خبر» در «شبکه‌ی اجتماعی» «گسترش» می‌یابد، «مسیر» آن از «گره»‌های «کلیدی» (تأثیرگرها) است: «ساختار»، «جریان» را «تعیین» می‌کند.  «سرمایه شبکه‌ای» در عمل: «اعتبار» یک «تأثیرگر» از «موقعیت» او در شبکه است: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت»، «ارزش» دارد.', '7fc532edb224916613cbe5dbb16e58e2caec8a992e47c3b34ddf7feb8e000ed3', 1021, 'ch-doc-card-524-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7fc532edb224916613cbe5dbb16e58e2caec8a992e47c3b34ddf7feb8e000ed3', token_count=1021, vector_point_id='ch-doc-card-524-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-524-8', 'doc-card-524', 'sec-card-524-4', 8, 'عیت» او در شبکه است: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت»، «ارزش» دارد.  «اثر شبکه‌ای» در «فیسبوک»: هر «عضو» جدیدی که «می‌آید»، «ارزش» شبکه را برای «همه» «بالاتر» می‌برد: «محصول» و «بازار» یکجا می‌شوند.  «حلقه اجتماعی» در عمل: «اشتراک‌گذاری» یک «خبر» در «حلقه» «دوستان»، «اعتبار» «اجتماعی» می‌سازد: «تایید» «اجتماعی»، «جریان» را «بازتولید» می‌کند.  «تأثیرگر» در «اینستاگرام»: «اعتبار» شخصی «تأثیرگر»، «سرمایه» شبکه‌ای است: «محتوا» او از «موقعیت» او در شبکه «جریان» می‌یابد.  «بافت شبکه‌ای» در عمل: «هویت» «دیجیتال» یک «کاربر» در «بافت» شبکه «بازتولید» می‌شود: «رفتار» و «هویت»، «محصول» «ساختار» است.  ۴. نقدها و چالش‌ها ۱.', '399c48d251f87ea37c6ae3f34383931c054216b738810f83e6b5bec01decfea5', 1143, 'ch-doc-card-524-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='399c48d251f87ea37c6ae3f34383931c054216b738810f83e6b5bec01decfea5', token_count=1143, vector_point_id='ch-doc-card-524-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-524-9', 'doc-card-524', 'sec-card-524-4', 9, 'ازتولید» می‌شود: «رفتار» و «هویت»، «محصول» «ساختار» است.  ۴. نقدها و چالش‌ها ۱. «شبکه» و «محتوا» از هم جدا نمی‌شوند: «تحلیل» صرف «ساختار»، «محتوا» را «محو» می‌کند: «محتوا» و «ساختار» در هم تنیده‌اند. ۲. «سرمایه شبکه‌ای» «سنجش‌پذیر» نیست: «ارزش» «موقعیت» در شبکه، «شاخص» واحد ندارد و «اندازه‌گیری» آن «دشواری» است. ۳. «اثر شبکه‌ای» «نامتقارن» است: «بزرگ‌تر» شدن شبکه، «ارزش» را «افزایش» می‌دهد اما «ارزش»، «توزیع» نمی‌شود: «مرکز» «بیشتر»', '213dfadab23d9512bdf135c98ef9887692483ba6ce4823c44a022baa8f3eed1e', 792, 'ch-doc-card-524-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='213dfadab23d9512bdf135c98ef9887692483ba6ce4823c44a022baa8f3eed1e', token_count=792, vector_point_id='ch-doc-card-524-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-524-10', 'doc-card-524', 'sec-card-524-5', 10, '«ساختار شبکه» در عمل: وقتی «خبر» در «شبکه‌ی اجتماعی» «گسترش» می‌یابد، «مسیر» آن از «گره»‌های «کلیدی» (تأثیرگرها) است: «ساختار»، «جریان» را «تعیین» می‌کند.  «سرمایه شبکه‌ای» در عمل: «اعتبار» یک «تأثیرگر» از «موقعیت» او در شبکه است: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت»، «ارزش» دارد.  «اثر شبکه‌ای» در «فیسبوک»: هر «عضو» جدیدی که «می‌آید»، «ارزش» شبکه را برای «همه» «بالاتر» می‌برد: «محصول» و «بازار» یکجا می‌شوند.  «حلقه اجتماعی» در عمل: «اشتراک‌گذاری» یک «خبر» در «حلقه» «دوستان»، «اعتبار» «اجتماعی» می‌سازد: «تایید» «اجتماعی»، «جریان» را «بازتولید» می‌کند.', '591acce302984742f99aaeba653caba140e13292a9114cff4d0b46b06ec2c4c4', 1025, 'ch-doc-card-524-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='591acce302984742f99aaeba653caba140e13292a9114cff4d0b46b06ec2c4c4', token_count=1025, vector_point_id='ch-doc-card-524-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-524-11', 'doc-card-524', 'sec-card-524-5', 11, '، «اعتبار» «اجتماعی» می‌سازد: «تایید» «اجتماعی»، «جریان» را «بازتولید» می‌کند.  «تأثیرگر» در «اینستاگرام»: «اعتبار» شخصی «تأثیرگر»، «سرمایه» شبکه‌ای است: «محتوا» او از «موقعیت» او در شبکه «جریان» می‌یابد.  «بافت شبکه‌ای» در عمل: «هویت» «دیجیتال» یک «کاربر» در «بافت» شبکه «بازتولید» می‌شود: «رفتار» و «هویت»، «محصول» «ساختار» است.', '0c44daa6ebe289aae8e69427d12b93abf90fe4b3ec723e137ecbd2f9cc00d196', 600, 'ch-doc-card-524-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0c44daa6ebe289aae8e69427d12b93abf90fe4b3ec723e137ecbd2f9cc00d196', token_count=600, vector_point_id='ch-doc-card-524-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-524-12', 'doc-card-524', 'sec-card-524-6', 12, '۱. «شبکه» و «محتوا» از هم جدا نمی‌شوند: «تحلیل» صرف «ساختار»، «محتوا» را «محو» می‌کند: «محتوا» و «ساختار» در هم تنیده‌اند. ۲. «سرمایه شبکه‌ای» «سنجش‌پذیر» نیست: «ارزش» «موقعیت» در شبکه، «شاخص» واحد ندارد و «اندازه‌گیری» آن «دشواری» است. ۳. «اثر شبکه‌ای» «نامتقارن» است: «بزرگ‌تر» شدن شبکه، «ارزش» را «افزایش» می‌دهد اما «ارزش»، «توزیع» نمی‌شود: «مرکز» «بیشتر» برد می‌کند. ۴. «تأثیرگر» و «اعتبار»: «اعتبار» تأثیرگر، «بازتولید» «الگوریتم» است: «موقعیت» در شبکه، «تعیین» «الگوریتم» است و «اعتبار»، «ابزاری» می‌شود. ۵. «حلقه اجتماعی» و «فیلتربابل»: «حلقه»‌های «اجتماعی»، «محتوا» ر', '3469caf12f747583e95a176220b927f46875cb1fc71098e9c56dbd3919e2b726', 1047, 'ch-doc-card-524-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3469caf12f747583e95a176220b927f46875cb1fc71098e9c56dbd3919e2b726', token_count=1047, vector_point_id='ch-doc-card-524-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-524-13', 'doc-card-524', 'sec-card-524-7', 13, 'ا «بازتولید» می‌کنند اما «تنوع» را «محو» می‌کنند: «حلقه»، «بابل» می‌شود. ۶. «جریان اطلاعات» و «نظارت»: «جریان» «محتوا» در شبکه، «داده» تولید می‌کند و «نظارت» بر «جریان»، «حاکمیت» است. ۷. «بافت شبکه‌ای» و «هویت»: «هویت» «دیجیتال» در «بافت» شبکه «بازتولید» می‌شود اما «هویت» «آفلاین» «محو» نمی‌شود: «دیالکتیک» «آنلاین» و «آفلاین»، «بازتعریف» لازم دارد. ۸. «شبکه» و «قدرت» در هم تنیده‌اند: «موقعیت» در شبکه، «قدرت» است و «ساختار» شبکه، «قدرت» را «بازتولید» می‌کند. ۹. «شبکه» در «عصر الگوریتم» «بازتعریف» می‌شود: «الگوریتم»، «جریان» را «تعیین» می‌کند و «شبکه»، «الگوریتمی» می‌شود.', 'df3f6cb886d894882a05992b88970ab96b64f2de5b7a800d087e2677b0d75af9', 1047, 'ch-doc-card-524-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='df3f6cb886d894882a05992b88970ab96b64f2de5b7a800d087e2677b0d75af9', token_count=1047, vector_point_id='ch-doc-card-524-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-524-14', 'doc-card-524', 'sec-card-524-10', 14, 'کتاب «ساختار اجتماعی» (بدر، ۱۹۸۳)؛ کتاب «اثر شبکه‌ای» (کارلوس و همکاران، ۲۰۱۰)؛ کتاب «شبکه‌های اجتماعی و رسانه» (والگرن و همکاران، ۲۰۰۵)؛ کتاب «سرمایه شبکه‌ای» (بیر و همکاران، ۲۰۰۸).', '267bd487cac492d7d744a11d37965dbb6cf9ee51653f69e0213ee5c59013a532', 330, 'ch-doc-card-524-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='267bd487cac492d7d744a11d37965dbb6cf9ee51653f69e0213ee5c59013a532', token_count=330, vector_point_id='ch-doc-card-524-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-525-0', 'doc-card-525', NULL, 0, 'کلانداده ترکیب هم‌زمان فرآیندهای جهانی و بومی است؛ در رسانه، پلتفرم‌های جهانی با تنظیم محتوا، زبان و الگوریتم با بافت‌های محلی می‌آمیزند و الگوریتم‌ها به میانجی‌های مبهم قدرت و حکمرانی داده‌ای تبدیل می‌شوند.', '4c9dd5f5f3ae520de81cfd0fbb83b4d13c9134a616a95a24ed73f1cbb9e58cec', 376, 'ch-doc-card-525-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4c9dd5f5f3ae520de81cfd0fbb83b4d13c9134a616a95a24ed73f1cbb9e58cec', token_count=376, vector_point_id='ch-doc-card-525-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-525-1', 'doc-card-525', 'sec-card-525-1', 1, 'داده، الگوریتم، نظارت و حریم خصوصی  مفهوم و چالشهای معرفتشناختی.', '4667a23ae2ffaa7b59dd67256df6b5202a061d52df8d7177bd2b39f3dac91b15', 116, 'ch-doc-card-525-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4667a23ae2ffaa7b59dd67256df6b5202a061d52df8d7177bd2b39f3dac91b15', token_count=116, vector_point_id='ch-doc-card-525-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-525-2', 'doc-card-525', 'sec-card-525-2', 2, '۱. بنیان و منطق نظری ادعای محوری کلانداده این است که در جامعه‌ی اطلاعاتی معاصر، داده کالای محوری و الگوریتم سازوکار حکمرانی است. نظریه‌پردازان تحلیل کرد که چگونه استخراج، پروفایل‌سازی و تبادل داده‌های شخصی، رابطه‌ی کاربر، پلتفرم و دولت را بازنشانی می‌کند. در این چارچوب، رسانه‌ی امروز نه به‌مثابه جریان پیام، بلکه به‌مثابه جریان اطلاعات‌کشی خوانده می‌شود که در آن رفتار کاربر ماده‌ی خام بازار است.  بر اساس کلانداده، نظارت از بین نرفته، بلکه فرم عوض کرده است: از نظارت متمرکز و گزینشی دولت به نظارت پراکنده، پیوسته و مبتنی بر داده که در آن خودِ کاربر ردّ تولید می‌کند.', '5ad04f233d478aa1285a8ca6886e62c99f36190fab578c98b82a7f9298fac6c7', 1032, 'ch-doc-card-525-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5ad04f233d478aa1285a8ca6886e62c99f36190fab578c98b82a7f9298fac6c7', token_count=1032, vector_point_id='ch-doc-card-525-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-525-3', 'doc-card-525', 'sec-card-525-2', 3, 'به نظارت پراکنده، پیوسته و مبتنی بر داده که در آن خودِ کاربر ردّ تولید می‌کند. نظریه‌پردازان نشان داد که منطق «نگاه» وارد طراحی پلتفرم‌های دیجیتال شده و عادی‌شدن نظارت، خودرفتار و خودِ مفهوم حریم خصوصی را دگرگون کرده است.  کلانداده الگوریتم‌ها را میانجی‌های مبهمی می‌داند که تعیین می‌کنند چه چیزی دیده شود و چه چیزی پنهان بماند، چه چیزی اولویت بگیرد و چه چیزی دفن شود. نظریه‌پردازان تأکید کرد که تصمیمات الگوریتمی — از فید اخبار تا درخواست وام — در عمل تصمیماتی «اجتماعی»‌اند که در کد نوشته شده‌اند و فقدان شفافیت و پاسخگویی درباره‌ی آن‌ها، فرمی تازه از قدرت بی‌پاسخ‌ساز می‌سازد. مطالعه‌ی این سازوکارها بنابراین از مطالعه‌ی قدرت و عدالت جدا نیست.  ۲.', '5b5b36e351ed988f76182ce9277d8dc9cb42af0b3bda26c93239f5c1b526af34', 1181, 'ch-doc-card-525-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5b5b36e351ed988f76182ce9277d8dc9cb42af0b3bda26c93239f5c1b526af34', token_count=1181, vector_point_id='ch-doc-card-525-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-525-4', 'doc-card-525', 'sec-card-525-2', 4, 'می‌سازد. مطالعه‌ی این سازوکارها بنابراین از مطالعه‌ی قدرت و عدالت جدا نیست.  ۲. ساختارهای مفهومی • داده‌کشی (Data Extraction): جمع‌آوری سیستماتیک داده‌های رفتاری کاربران توسط پلتفرم‌ها و دولت. • پروفایل‌سازی (Profiling): ساختن پروفایل‌های رفتاری و روان‌شناختی از داده برای پیش‌بینی و هدایت رفتار. • مبهم‌بودن الگوریتم (Algorithmic Opacity): عدم دسترسی کاربر و ناظر به منطق و تصمیمات الگوریتم. • حریم خصوصی (Privacy): حق کنترل بر جریان اطلاعات شخصی و شرایط حفاظت از آن در عصر دیجیتال. • داده‌ای‌شدن (Datification): فرایند تبدیل هر بُعد از زندگی اجتماعی به داده. • ردّ دیجیتال (Digital Footprint): اثرهای باقی‌مانده‌ی رفتار فرد در فضاهای دیجیتال و ماندگاری آن‌ها.', 'de946dfef599527d16d3d23651f0440a40b27c852e1feaaef7238d2aa967be77', 1201, 'ch-doc-card-525-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='de946dfef599527d16d3d23651f0440a40b27c852e1feaaef7238d2aa967be77', token_count=1201, vector_point_id='ch-doc-card-525-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-525-5', 'doc-card-525', 'sec-card-525-2', 5, 'l Footprint): اثرهای باقی‌مانده‌ی رفتار فرد در فضاهای دیجیتال و ماندگاری آن‌ها. • پانوپتیکون (Panopticon): مدل فوکویی نظارتی', 'e85cb1f4713ccea7b98f5c291fe3be1b0ac962c4cfe9bd0a63ac746acd1c7d0b', 225, 'ch-doc-card-525-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e85cb1f4713ccea7b98f5c291fe3be1b0ac962c4cfe9bd0a63ac746acd1c7d0b', token_count=225, vector_point_id='ch-doc-card-525-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-525-6', 'doc-card-525', 'sec-card-525-3', 6, '• داده‌کشی (Data Extraction): جمع‌آوری سیستماتیک داده‌های رفتاری کاربران توسط پلتفرم‌ها و دولت. • پروفایل‌سازی (Profiling): ساختن پروفایل‌های رفتاری و روان‌شناختی از داده برای پیش‌بینی و هدایت رفتار. • مبهم‌بودن الگوریتم (Algorithmic Opacity): عدم دسترسی کاربر و ناظر به منطق و تصمیمات الگوریتم. • حریم خصوصی (Privacy): حق کنترل بر جریان اطلاعات شخصی و شرایط حفاظت از آن در عصر دیجیتال. • داده‌ای‌شدن (Datification): فرایند تبدیل هر بُعد از زندگی اجتماعی به داده. • ردّ دیجیتال (Digital Footprint): اثرهای باقی‌مانده‌ی رفتار فرد در فضاهای دیجیتال و ماندگاری آن‌ها. • پانوپتیکون (Panopticon): مدل فوکویی نظارتی که در آن احتمال دیده‌شدن، رفتار را تأمین می‌کند.', '8edb1c82060510576a0f6a7ee2c0631126eb7787f15c81994d3654d1b8502b6d', 1196, 'ch-doc-card-525-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8edb1c82060510576a0f6a7ee2c0631126eb7787f15c81994d3654d1b8502b6d', token_count=1196, vector_point_id='ch-doc-card-525-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-525-7', 'doc-card-525', 'sec-card-525-3', 7, 'Panopticon): مدل فوکویی نظارتی که در آن احتمال دیده‌شدن، رفتار را تأمین می‌کند. • پارادوکس حریم خصوصی (Privacy Paradox): شکاف میان نگرش ابرازشده به حریم خصوصی و رفتار واقعی اشتراک‌گذاری داده.', '8e98a3b52b466d5c84bd6cf264144211ad418393f64e5c4b503958751404e44f', 347, 'ch-doc-card-525-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8e98a3b52b466d5c84bd6cf264144211ad418393f64e5c4b503958751404e44f', token_count=347, vector_point_id='ch-doc-card-525-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-525-8', 'doc-card-525', 'sec-card-525-4', 8, 'که در آن احتمال دیده‌شدن، رفتار را تأمین می‌کند. • پارادوکس حریم خصوصی (Privacy Paradox): شکاف میان نگرش ابرازشده به حریم خصوصی و رفتار واقعی اشتراک‌گذاری داده.  ۳. نمونه‌های تحلیلی تبلیغات هدفمند، رُخِ قابل‌دیدن اقتصاد داده است: کاربری که پس از جست‌وجوی یک محصول، آگهی آن را در شبکه‌ی اجتماعی می‌بیند، در پشت صحنه با سیستمی از پروفایل‌سازی بر پایه‌ی میلیون‌ها تعامل روبه‌روست.  رسوایی‌های سوءاستفاده از داده‌های شبکه‌های اجتماعی در انتخابات (مانند پرونده‌ی کمبریج‌آنالیتیکا) نشان دادند که داده‌های شخصی، هنگامی که تجمیع می‌شوند، به ابزاری برای تأثیر سیاسی خارج از آگاهی و رضایت فرد تبدیل می‌شوند.', '423cc8147b6da13421c023b311dcc93ae3fe9621ddefc6c0a6e0f76fe6fdd71b', 1085, 'ch-doc-card-525-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='423cc8147b6da13421c023b311dcc93ae3fe9621ddefc6c0a6e0f76fe6fdd71b', token_count=1085, vector_point_id='ch-doc-card-525-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-525-9', 'doc-card-525', 'sec-card-525-4', 9, 'ع می‌شوند، به ابزاری برای تأثیر سیاسی خارج از آگاهی و رضایت فرد تبدیل می‌شوند.  سیستم اعتبار اجتماعی در برخی کشورها، منطق نظارت مبتنی بر داده را در حدّ نهایی نشان می‌دهد: امتیازی که بر رفتار شهروند ثبت می‌شود، به دسترسی او به خدمات، سفر و حتی مسکن ربط داده می‌شود.  «نظارت معکوس» — فیلم‌برداری شهروندان از پلیس و نهادهای قدرتمند با گوشی — نشان می‌دهد که نگاه دیگر یک‌طرفه نیست و ساختارهای نظارتی همواره مورد چالش و بازنشانی هستند.  وقتی فید الگوریتمی به کاربر صرفاَ محتوایی هم‌سو با باورهای پیشینش نشان می‌دهد، نه فقط «شخصی‌سازی» رخ داده، بلکه نوعی سانسور الگوریتمی است که ادراک جهان کاربر را بدون آگاهی او شکل می‌دهد.', '8694ba72177c974c35f1980d8fa64c6c9e99d13422e9e76a4ac891bb5cd22053', 1123, 'ch-doc-card-525-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8694ba72177c974c35f1980d8fa64c6c9e99d13422e9e76a4ac891bb5cd22053', token_count=1123, vector_point_id='ch-doc-card-525-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-525-10', 'doc-card-525', 'sec-card-525-4', 10, 'لکه نوعی سانسور الگوریتمی است که ادراک جهان کاربر را بدون آگاهی او شکل می‌دهد.  تنظیمات حریم خصوصی شبکه‌های اجتماعی — پیچیده و پر از پیش‌فرض — نشان می‌دهد «انتخاب»ی که به کاربر پیشنهاد می‌شود گاه انتخابی صوری است و قدرت واقعی تصمیم در دست طراح پلتفرم می‌ماند.  ۴. نقدها و چالش‌ها ۱. جبرگرایی زیرساخت: چارچوب گاه می‌تواند به تصویر «داده‌ی همه‌چیز را می‌بیند و هدایت می‌کند» انجام دهد و عاملیت انسان، مقاومت مدنی و امکان‌های نظارت معکوس را دست‌کم بگیرد. ۲. مبهم‌بودن الگوریتم در دو سو: هم شرکت‌ها و الگوریتم‌هایشان شفاف نیستند و هم کاربرانی که چگونه داده‌شان مصرف می‌شود را نمی‌دانند؛ این ابهام از دو سو هم‌زمان آزمون تجربی ادعاها را دشوار می‌کند. ۳.', '0181b0635251fb48bc8aab39586901a32b12cffb206a8807bdb59ba176d79128', 1178, 'ch-doc-card-525-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0181b0635251fb48bc8aab39586901a32b12cffb206a8807bdb59ba176d79128', token_count=1178, vector_point_id='ch-doc-card-525-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-525-11', 'doc-card-525', 'sec-card-525-4', 11, 'را نمی‌دانند؛ این ابهام از دو سو هم‌زمان آزمون تجربی ادعاها را دشوار می‌کند. ۳. جابه‌جایی سریع هدف: حوزه‌ی داده و نظارت دیجیتال با سرعتی که', '79b5233945a6522ff621df53b44ff972dd83b952f90566343ef3e0290c32bf34', 252, 'ch-doc-card-525-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='79b5233945a6522ff621df53b44ff972dd83b952f90566343ef3e0290c32bf34', token_count=252, vector_point_id='ch-doc-card-525-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-525-12', 'doc-card-525', 'sec-card-525-5', 12, 'تبلیغات هدفمند، رُخِ قابل‌دیدن اقتصاد داده است: کاربری که پس از جست‌وجوی یک محصول، آگهی آن را در شبکه‌ی اجتماعی می‌بیند، در پشت صحنه با سیستمی از پروفایل‌سازی بر پایه‌ی میلیون‌ها تعامل روبه‌روست.  رسوایی‌های سوءاستفاده از داده‌های شبکه‌های اجتماعی در انتخابات (مانند پرونده‌ی کمبریج‌آنالیتیکا) نشان دادند که داده‌های شخصی، هنگامی که تجمیع می‌شوند، به ابزاری برای تأثیر سیاسی خارج از آگاهی و رضایت فرد تبدیل می‌شوند.  سیستم اعتبار اجتماعی در برخی کشورها، منطق نظارت مبتنی بر داده را در حدّ نهایی نشان می‌دهد: امتیازی که بر رفتار شهروند ثبت می‌شود، به دسترسی او به خدمات، سفر و حتی مسکن ربط داده می‌شود.', '3dc96c38b13f32c2b1995dae3348d8b12d3bafe9cce293bdd230368b7078eb69', 1092, 'ch-doc-card-525-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3dc96c38b13f32c2b1995dae3348d8b12d3bafe9cce293bdd230368b7078eb69', token_count=1092, vector_point_id='ch-doc-card-525-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-525-13', 'doc-card-525', 'sec-card-525-5', 13, 'فتار شهروند ثبت می‌شود، به دسترسی او به خدمات، سفر و حتی مسکن ربط داده می‌شود.  «نظارت معکوس» — فیلم‌برداری شهروندان از پلیس و نهادهای قدرتمند با گوشی — نشان می‌دهد که نگاه دیگر یک‌طرفه نیست و ساختارهای نظارتی همواره مورد چالش و بازنشانی هستند.  وقتی فید الگوریتمی به کاربر صرفاَ محتوایی هم‌سو با باورهای پیشینش نشان می‌دهد، نه فقط «شخصی‌سازی» رخ داده، بلکه نوعی سانسور الگوریتمی است که ادراک جهان کاربر را بدون آگاهی او شکل می‌دهد.  تنظیمات حریم خصوصی شبکه‌های اجتماعی — پیچیده و پر از پیش‌فرض — نشان می‌دهد «انتخاب»ی که به کاربر پیشنهاد می‌شود گاه انتخابی صوری است و قدرت واقعی تصمیم در دست طراح پلتفرم می‌ماند.', '3bb22489138dff07609c998d816ad240a46e6cfd7b5a4ebe4dcc0a3caf70e460', 1114, 'ch-doc-card-525-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3bb22489138dff07609c998d816ad240a46e6cfd7b5a4ebe4dcc0a3caf70e460', token_count=1114, vector_point_id='ch-doc-card-525-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-525-14', 'doc-card-525', 'sec-card-525-6', 14, '۱. جبرگرایی زیرساخت: چارچوب گاه می‌تواند به تصویر «داده‌ی همه‌چیز را می‌بیند و هدایت می‌کند» انجام دهد و عاملیت انسان، مقاومت مدنی و امکان‌های نظارت معکوس را دست‌کم بگیرد. ۲. مبهم‌بودن الگوریتم در دو سو: هم شرکت‌ها و الگوریتم‌هایشان شفاف نیستند و هم کاربرانی که چگونه داده‌شان مصرف می‌شود را نمی‌دانند؛ این ابهام از دو سو هم‌زمان آزمون تجربی ادعاها را دشوار می‌کند. ۳. جابه‌جایی سریع هدف: حوزه‌ی داده و نظارت دیجیتال با سرعتی که الگوهای نظارت تغییر می‌کنند، پیش می‌رود و بسیاری از یافته‌ها در نوسانه‌ی بعدی بی‌مورد می‌شوند. ۴.', 'f398ce63199b6479e67d7b985155e60698a50bfc46dc87c835028091d9a42e10', 956, 'ch-doc-card-525-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f398ce63199b6479e67d7b985155e60698a50bfc46dc87c835028091d9a42e10', token_count=956, vector_point_id='ch-doc-card-525-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-525-15', 'doc-card-525', 'sec-card-525-6', 15, 'ر می‌کنند، پیش می‌رود و بسیاری از یافته‌ها در نوسانه‌ی بعدی بی‌مورد می‌شوند. ۴. ناهمگنی «نظارت» در فرهنگ‌ها: مفهوم نظارت و حریم خصوصی در فرهنگ‌ها و نظام‌های حقوقی متفاوت است و مدل‌های توسعه‌یافته در غرب (مانند الگوهای پانوپتیکون) هر جا بدون بازنشانی کاربرد ندارند. ۵. مس', '4aa6d13d77416151b0bfda2b7adad03639b5c4d1946e19469d965084882cc3b9', 490, 'ch-doc-card-525-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4aa6d13d77416151b0bfda2b7adad03639b5c4d1946e19469d965084882cc3b9', token_count=490, vector_point_id='ch-doc-card-525-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-525-16', 'doc-card-525', 'sec-card-525-7', 16, 'ئله‌ی قدرت: تمرکز بر «عادی‌شدن نظارت» می‌تواند قدرت سیاسی و اقتصادی آن‌هایی را که داده را استخراج و از آن سود می‌برند، در تصویر تار بگذارد. ۶. سنجش رفتار: سنجش رفتارهای آنلاین (پذیرش شرایط، اشتراک‌گذاری) به دلیل تغییر مداوم رابط و بستر، قابل‌مقایسه در طول زمان نیست. ۷. پارادوکس رفتار و نگرش: شکاف میان نگرش ابرازشده به حریم خصوصی و رفتار واقعی (پارادوکس حریم خصوصی) می‌تواند نتیجه‌گیری‌های کلی درباره‌ی «ارزش‌های» مخاطب را گمراه‌کننده کند. ۸. غفلت از جنبه‌ی کار: اقتصاد داده بر پایه‌ی کار نامرئی است — تولیدکنندگان محتوا، برچسب‌زنندگان داده، نظارتگران — و چارچوب‌ها این لایه را کمتر پوشش می‌دهند. ۹.', 'cbcd30bf1d0c22b052abf91910125037eb44ac19912a7ec476b3ead3424726e8', 1090, 'ch-doc-card-525-16', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cbcd30bf1d0c22b052abf91910125037eb44ac19912a7ec476b3ead3424726e8', token_count=1090, vector_point_id='ch-doc-card-525-16', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-525-17', 'doc-card-525', 'sec-card-525-7', 17, '، برچسب‌زنندگان داده، نظارتگران — و چارچوب‌ها این لایه را کمتر پوشش می‌دهند. ۹. ریسک تقلیل‌گرایی: تقلیل هر مسئله‌ی اجتماعی به «مسئله‌ی داده» می‌تواند ریشه‌های اقتصادی و سیاسی نابرابری را پنهان کند.', '57783d719f2d993a47b248e60b983d5cf44d6debefc1af56a753a7ac4ae24e1c', 358, 'ch-doc-card-525-17', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='57783d719f2d993a47b248e60b983d5cf44d6debefc1af56a753a7ac4ae24e1c', token_count=358, vector_point_id='ch-doc-card-525-17', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-525-18', 'doc-card-525', 'sec-card-525-10', 18, 'کتاب «جامعه‌ی نظارت» (گوتهام، ۱۹۹۱)؛ کتاب «مردم به‌جای محصول» (گِبر و لوسر، ۲۰۱۷)؛ کتاب «داده‌کشی: اقتصاد داده و قدرت» (شوشان، ۲۰۱۷)؛ استناد مبنا: Zuboff (2019) بر نظارت سرمایه‌داری.', '840da3c01cb66d1dc47e1b4ae58e9e6612928c506f6b419cd6acf5b6ec8d0a6f', 330, 'ch-doc-card-525-18', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='840da3c01cb66d1dc47e1b4ae58e9e6612928c506f6b419cd6acf5b6ec8d0a6f', token_count=330, vector_point_id='ch-doc-card-525-18', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-526-0', 'doc-card-526', NULL, 0, 'تئوری برچسب و امتیازدهی الگوریتمی (گیلسپی، ۲۰۱۴) می‌گوید پلتفرم‌ها با محاسبه و رتبه‌بندی محتوا، برجستگی و دسترسی را تعیین می‌کنند؛ این تصمیمات کدگذاری‌شده در عمل انتخاب‌های اجتماعی هستند و قدرت بی‌پاسخ‌سازی تازه‌ای می‌سازند.', 'c2c4aa79baecb00f9c28fba731386ce28283a520a644c00309cdd38dafa4a3d0', 407, 'ch-doc-card-526-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c2c4aa79baecb00f9c28fba731386ce28283a520a644c00309cdd38dafa4a3d0', token_count=407, vector_point_id='ch-doc-card-526-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-526-1', 'doc-card-526', 'sec-card-526-1', 1, 'داده، الگوریتم، نظارت و حریم خصوصی  پلتفرمها برجستگی را محاسبه میکنند.', '53e759b9044390486ab66be437a5bc26bd02a10e60796fbe5c3363d5ac0d764d', 127, 'ch-doc-card-526-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='53e759b9044390486ab66be437a5bc26bd02a10e60796fbe5c3363d5ac0d764d', token_count=127, vector_point_id='ch-doc-card-526-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-526-2', 'doc-card-526', 'sec-card-526-2', 2, '۱. بنیان و منطق نظری ادعای محوری نظریه برچسب/امتیازدهی الگوریتمی این است که در جامعه‌ی اطلاعاتی معاصر، داده کالای محوری و الگوریتم سازوکار حکمرانی است. تارلتون گیلسپی (۲۰۱۴) تحلیل کرد که چگونه استخراج، پروفایل‌سازی و تبادل داده‌های شخصی، رابطه‌ی کاربر، پلتفرم و دولت را بازنشانی می‌کند. در این چارچوب، رسانه‌ی امروز نه به‌مثابه جریان پیام، بلکه به‌مثابه جریان اطلاعات‌کشی خوانده می‌شود که در آن رفتار کاربر ماده‌ی خام بازار است.  بر اساس نظریه برچسب/امتیازدهی الگوریتمی، نظارت از بین نرفته، بلکه فرم عوض کرده است: از نظارت متمرکز و گزینشی دولت به نظارت پراکنده، پیوسته و مبتنی بر داده که در آن خودِ کاربر ردّ تولید می‌کند.', '2605e5d1c674b6c709b47e05baedf34c6bd91fe8b9974a1d2cfccbaafcccf41a', 1130, 'ch-doc-card-526-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2605e5d1c674b6c709b47e05baedf34c6bd91fe8b9974a1d2cfccbaafcccf41a', token_count=1130, vector_point_id='ch-doc-card-526-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-526-3', 'doc-card-526', 'sec-card-526-2', 3, 'به نظارت پراکنده، پیوسته و مبتنی بر داده که در آن خودِ کاربر ردّ تولید می‌کند. تارلتون گیلسپی (۲۰۱۴) نشان داد که منطق «نگاه» وارد طراحی پلتفرم‌های دیجیتال شده و عادی‌شدن نظارت، خودرفتار و خودِ مفهوم حریم خصوصی را دگرگون کرده است.  نظریه برچسب/امتیازدهی الگوریتمی الگوریتم‌ها را میانجی‌های مبهمی می‌داند که تعیین می‌کنند چه چیزی دیده شود و چه چیزی پنهان بماند، چه چیزی اولویت بگیرد و چه چیزی دفن شود. تارلتون گیلسپی (۲۰۱۴) تأکید کرد که تصمیمات الگوریتمی — از فید اخبار تا درخواست وام — در عمل تصمیماتی «اجتماعی»‌اند که در کد نوشته شده‌اند و فقدان شفافیت و پاسخگویی درباره‌ی آن‌ها، فرمی تازه از قدرت بی‌پاسخ‌ساز می‌سازد.', '85536569a6335498140b1349a1bed9754a5ec2c3d14261669968c3851864983b', 1123, 'ch-doc-card-526-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='85536569a6335498140b1349a1bed9754a5ec2c3d14261669968c3851864983b', token_count=1123, vector_point_id='ch-doc-card-526-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-526-4', 'doc-card-526', 'sec-card-526-2', 4, 'فقدان شفافیت و پاسخگویی درباره‌ی آن‌ها، فرمی تازه از قدرت بی‌پاسخ‌ساز می‌سازد. مطالعه‌ی این سازوکارها بنابراین از مطالعه‌ی قدرت و عدالت جدا نیست.  ۲. ساختارهای مفهومی • داده‌کشی (Data Extraction): جمع‌آوری سیستماتیک داده‌های رفتاری کاربران توسط پلتفرم‌ها و دولت. • پروفایل‌سازی (Profiling): ساختن پروفایل‌های رفتاری و روان‌شناختی از داده برای پیش‌بینی و هدایت رفتار. • مبهم‌بودن الگوریتم (Algorithmic Opacity): عدم دسترسی کاربر و ناظر به منطق و تصمیمات الگوریتم. • حریم خصوصی (Privacy): حق کنترل بر جریان اطلاعات شخصی و شرایط حفاظت از آن در عصر دیجیتال. • داده‌ای‌شدن (Datification): فرایند تبدیل هر بُعد از زندگی اجتماعی به داده.', '478907412d2fe8205797ca895b04e22c8b30cea44b4359908c241bf49b1e2839', 1145, 'ch-doc-card-526-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='478907412d2fe8205797ca895b04e22c8b30cea44b4359908c241bf49b1e2839', token_count=1145, vector_point_id='ch-doc-card-526-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-526-5', 'doc-card-526', 'sec-card-526-2', 5, 'ل. • داده‌ای‌شدن (Datification): فرایند تبدیل هر بُعد از زندگی اجتماعی به داده. • ردّ دیجیتال (Digital Footprint): اثرهای باقی‌مانده‌ی رفتار فرد در فضاهای دیجیتال و ماندگا', '68d7b91302c5f4f8873c1d33022996d5d4c5e403169d3ff9f73c037f0a98701f', 310, 'ch-doc-card-526-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='68d7b91302c5f4f8873c1d33022996d5d4c5e403169d3ff9f73c037f0a98701f', token_count=310, vector_point_id='ch-doc-card-526-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-526-6', 'doc-card-526', 'sec-card-526-3', 6, '• داده‌کشی (Data Extraction): جمع‌آوری سیستماتیک داده‌های رفتاری کاربران توسط پلتفرم‌ها و دولت. • پروفایل‌سازی (Profiling): ساختن پروفایل‌های رفتاری و روان‌شناختی از داده برای پیش‌بینی و هدایت رفتار. • مبهم‌بودن الگوریتم (Algorithmic Opacity): عدم دسترسی کاربر و ناظر به منطق و تصمیمات الگوریتم. • حریم خصوصی (Privacy): حق کنترل بر جریان اطلاعات شخصی و شرایط حفاظت از آن در عصر دیجیتال. • داده‌ای‌شدن (Datification): فرایند تبدیل هر بُعد از زندگی اجتماعی به داده. • ردّ دیجیتال (Digital Footprint): اثرهای باقی‌مانده‌ی رفتار فرد در فضاهای دیجیتال و ماندگاری آن‌ها. • پانوپتیکون (Panopticon): مدل فوکویی نظارتی که در آن احتمال دیده‌شدن، رفتار را تأمین می‌کند.', '8edb1c82060510576a0f6a7ee2c0631126eb7787f15c81994d3654d1b8502b6d', 1196, 'ch-doc-card-526-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8edb1c82060510576a0f6a7ee2c0631126eb7787f15c81994d3654d1b8502b6d', token_count=1196, vector_point_id='ch-doc-card-526-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-526-7', 'doc-card-526', 'sec-card-526-3', 7, 'Panopticon): مدل فوکویی نظارتی که در آن احتمال دیده‌شدن، رفتار را تأمین می‌کند. • پارادوکس حریم خصوصی (Privacy Paradox): شکاف میان نگرش ابرازشده به حریم خصوصی و رفتار واقعی اشتراک‌گذاری داده.', '8e98a3b52b466d5c84bd6cf264144211ad418393f64e5c4b503958751404e44f', 347, 'ch-doc-card-526-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8e98a3b52b466d5c84bd6cf264144211ad418393f64e5c4b503958751404e44f', token_count=347, vector_point_id='ch-doc-card-526-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-526-8', 'doc-card-526', 'sec-card-526-4', 8, 'ری آن‌ها. • پانوپتیکون (Panopticon): مدل فوکویی نظارتی که در آن احتمال دیده‌شدن، رفتار را تأمین می‌کند. • پارادوکس حریم خصوصی (Privacy Paradox): شکاف میان نگرش ابرازشده به حریم خصوصی و رفتار واقعی اشتراک‌گذاری داده.  ۳. نمونه‌های تحلیلی تبلیغات هدفمند، رُخِ قابل‌دیدن اقتصاد داده است: کاربری که پس از جست‌وجوی یک محصول، آگهی آن را در شبکه‌ی اجتماعی می‌بیند، در پشت صحنه با سیستمی از پروفایل‌سازی بر پایه‌ی میلیون‌ها تعامل روبه‌روست.  رسوایی‌های سوءاستفاده از داده‌های شبکه‌های اجتماعی در انتخابات (مانند پرونده‌ی کمبریج‌آنالیتیکا) نشان دادند که داده‌های شخصی، هنگامی که تجمیع می‌شوند، به ابزاری برای تأثیر سیاسی خارج از آگاهی و رضایت فرد تبدیل می‌شوند.', 'ee69fb217c165edeaf2a55542380be79ba3171f7b88e8f2dcf8244847d5b7ff0', 1185, 'ch-doc-card-526-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ee69fb217c165edeaf2a55542380be79ba3171f7b88e8f2dcf8244847d5b7ff0', token_count=1185, vector_point_id='ch-doc-card-526-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-526-9', 'doc-card-526', 'sec-card-526-4', 9, 'ع می‌شوند، به ابزاری برای تأثیر سیاسی خارج از آگاهی و رضایت فرد تبدیل می‌شوند.  سیستم اعتبار اجتماعی در برخی کشورها، منطق نظارت مبتنی بر داده را در حدّ نهایی نشان می‌دهد: امتیازی که بر رفتار شهروند ثبت می‌شود، به دسترسی او به خدمات، سفر و حتی مسکن ربط داده می‌شود.  «نظارت معکوس» — فیلم‌برداری شهروندان از پلیس و نهادهای قدرتمند با گوشی — نشان می‌دهد که نگاه دیگر یک‌طرفه نیست و ساختارهای نظارتی همواره مورد چالش و بازنشانی هستند.  وقتی فید الگوریتمی به کاربر صرفاَ محتوایی هم‌سو با باورهای پیشینش نشان می‌دهد، نه فقط «شخصی‌سازی» رخ داده، بلکه نوعی سانسور الگوریتمی است که ادراک جهان کاربر را بدون آگاهی او شکل می‌دهد.', '8694ba72177c974c35f1980d8fa64c6c9e99d13422e9e76a4ac891bb5cd22053', 1123, 'ch-doc-card-526-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8694ba72177c974c35f1980d8fa64c6c9e99d13422e9e76a4ac891bb5cd22053', token_count=1123, vector_point_id='ch-doc-card-526-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-526-10', 'doc-card-526', 'sec-card-526-4', 10, 'لکه نوعی سانسور الگوریتمی است که ادراک جهان کاربر را بدون آگاهی او شکل می‌دهد.  تنظیمات حریم خصوصی شبکه‌های اجتماعی — پیچیده و پر از پیش‌فرض — نشان می‌دهد «انتخاب»ی که به کاربر پیشنهاد می‌شود گاه انتخابی صوری است و قدرت واقعی تصمیم در دست طراح پلتفرم می‌ماند.  ۴. نقدها و چالش‌ها ۱. جبرگرایی زیرساخت: چارچوب گاه می‌تواند به تصویر «داده‌ی همه‌چیز را می‌بیند و هدایت می‌کند» انجام دهد و عاملیت انسان، مقاومت مدنی و امکان‌های نظارت معکوس را دست‌کم بگیرد. ۲. مبهم‌بودن الگوریتم در دو سو: هم شرکت‌ها و الگوریتم‌هایشان شفاف نیستند و هم کاربرانی که چگونه داده‌شان مصرف می‌شود را نمی‌دانند؛ این ابهام از دو سو هم‌زمان آزمون تجربی ادعاها را دشوار می‌کند. ۳.', '0181b0635251fb48bc8aab39586901a32b12cffb206a8807bdb59ba176d79128', 1178, 'ch-doc-card-526-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0181b0635251fb48bc8aab39586901a32b12cffb206a8807bdb59ba176d79128', token_count=1178, vector_point_id='ch-doc-card-526-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-526-11', 'doc-card-526', 'sec-card-526-4', 11, 'را نمی‌دانند؛ این ابهام از دو سو هم‌زمان آزمون تجربی ادعاها را دشوار می‌کند. ۳. جابه‌جایی سریع هدف: حوزه‌ی داده و نظارت دیجی', 'df6b91592d9c126515353a2806f0cc76f235fb9f87a4b72c80c07ea43243441d', 225, 'ch-doc-card-526-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='df6b91592d9c126515353a2806f0cc76f235fb9f87a4b72c80c07ea43243441d', token_count=225, vector_point_id='ch-doc-card-526-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-526-12', 'doc-card-526', 'sec-card-526-5', 12, 'تبلیغات هدفمند، رُخِ قابل‌دیدن اقتصاد داده است: کاربری که پس از جست‌وجوی یک محصول، آگهی آن را در شبکه‌ی اجتماعی می‌بیند، در پشت صحنه با سیستمی از پروفایل‌سازی بر پایه‌ی میلیون‌ها تعامل روبه‌روست.  رسوایی‌های سوءاستفاده از داده‌های شبکه‌های اجتماعی در انتخابات (مانند پرونده‌ی کمبریج‌آنالیتیکا) نشان دادند که داده‌های شخصی، هنگامی که تجمیع می‌شوند، به ابزاری برای تأثیر سیاسی خارج از آگاهی و رضایت فرد تبدیل می‌شوند.  سیستم اعتبار اجتماعی در برخی کشورها، منطق نظارت مبتنی بر داده را در حدّ نهایی نشان می‌دهد: امتیازی که بر رفتار شهروند ثبت می‌شود، به دسترسی او به خدمات، سفر و حتی مسکن ربط داده می‌شود.', '3dc96c38b13f32c2b1995dae3348d8b12d3bafe9cce293bdd230368b7078eb69', 1092, 'ch-doc-card-526-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3dc96c38b13f32c2b1995dae3348d8b12d3bafe9cce293bdd230368b7078eb69', token_count=1092, vector_point_id='ch-doc-card-526-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-526-13', 'doc-card-526', 'sec-card-526-5', 13, 'فتار شهروند ثبت می‌شود، به دسترسی او به خدمات، سفر و حتی مسکن ربط داده می‌شود.  «نظارت معکوس» — فیلم‌برداری شهروندان از پلیس و نهادهای قدرتمند با گوشی — نشان می‌دهد که نگاه دیگر یک‌طرفه نیست و ساختارهای نظارتی همواره مورد چالش و بازنشانی هستند.  وقتی فید الگوریتمی به کاربر صرفاَ محتوایی هم‌سو با باورهای پیشینش نشان می‌دهد، نه فقط «شخصی‌سازی» رخ داده، بلکه نوعی سانسور الگوریتمی است که ادراک جهان کاربر را بدون آگاهی او شکل می‌دهد.  تنظیمات حریم خصوصی شبکه‌های اجتماعی — پیچیده و پر از پیش‌فرض — نشان می‌دهد «انتخاب»ی که به کاربر پیشنهاد می‌شود گاه انتخابی صوری است و قدرت واقعی تصمیم در دست طراح پلتفرم می‌ماند.', '3bb22489138dff07609c998d816ad240a46e6cfd7b5a4ebe4dcc0a3caf70e460', 1114, 'ch-doc-card-526-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3bb22489138dff07609c998d816ad240a46e6cfd7b5a4ebe4dcc0a3caf70e460', token_count=1114, vector_point_id='ch-doc-card-526-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-526-14', 'doc-card-526', 'sec-card-526-6', 14, '۱. جبرگرایی زیرساخت: چارچوب گاه می‌تواند به تصویر «داده‌ی همه‌چیز را می‌بیند و هدایت می‌کند» انجام دهد و عاملیت انسان، مقاومت مدنی و امکان‌های نظارت معکوس را دست‌کم بگیرد. ۲. مبهم‌بودن الگوریتم در دو سو: هم شرکت‌ها و الگوریتم‌هایشان شفاف نیستند و هم کاربرانی که چگونه داده‌شان مصرف می‌شود را نمی‌دانند؛ این ابهام از دو سو هم‌زمان آزمون تجربی ادعاها را دشوار می‌کند. ۳. جابه‌جایی سریع هدف: حوزه‌ی داده و نظارت دیجیتال با سرعتی که الگوهای نظارت تغییر می‌کنند، پیش می‌رود و بسیاری از یافته‌ها در نوسانه‌ی بعدی بی‌مورد می‌شوند. ۴.', 'f398ce63199b6479e67d7b985155e60698a50bfc46dc87c835028091d9a42e10', 956, 'ch-doc-card-526-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f398ce63199b6479e67d7b985155e60698a50bfc46dc87c835028091d9a42e10', token_count=956, vector_point_id='ch-doc-card-526-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-526-15', 'doc-card-526', 'sec-card-526-6', 15, 'ر می‌کنند، پیش می‌رود و بسیاری از یافته‌ها در نوسانه‌ی بعدی بی‌مورد می‌شوند. ۴. ناهمگنی «نظارت» در فرهنگ‌ها: مفهوم نظارت و حریم خصوصی در فرهنگ‌ها و نظام‌های حقوقی متفاوت است و مدل‌های توسعه‌یافته در غرب (مانند الگوهای پانوپتیکون) هر جا بدون بازنشانی کاربرد ندارند. ۵. مس', '4aa6d13d77416151b0bfda2b7adad03639b5c4d1946e19469d965084882cc3b9', 490, 'ch-doc-card-526-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4aa6d13d77416151b0bfda2b7adad03639b5c4d1946e19469d965084882cc3b9', token_count=490, vector_point_id='ch-doc-card-526-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-526-16', 'doc-card-526', 'sec-card-526-7', 16, 'ئله‌ی قدرت: تمرکز بر «عادی‌شدن نظارت» می‌تواند قدرت سیاسی و اقتصادی آن‌هایی را که داده را استخراج و از آن سود می‌برند، در تصویر تار بگذارد. ۶. سنجش رفتار: سنجش رفتارهای آنلاین (پذیرش شرایط، اشتراک‌گذاری) به دلیل تغییر مداوم رابط و بستر، قابل‌مقایسه در طول زمان نیست. ۷. پارادوکس رفتار و نگرش: شکاف میان نگرش ابرازشده به حریم خصوصی و رفتار واقعی (پارادوکس حریم خصوصی) می‌تواند نتیجه‌گیری‌های کلی درباره‌ی «ارزش‌های» مخاطب را گمراه‌کننده کند. ۸. غفلت از جنبه‌ی کار: اقتصاد داده بر پایه‌ی کار نامرئی است — تولیدکنندگان محتوا، برچسب‌زنندگان داده، نظارتگران — و چارچوب‌ها این لایه را کمتر پوشش می‌دهند. ۹.', 'cbcd30bf1d0c22b052abf91910125037eb44ac19912a7ec476b3ead3424726e8', 1090, 'ch-doc-card-526-16', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cbcd30bf1d0c22b052abf91910125037eb44ac19912a7ec476b3ead3424726e8', token_count=1090, vector_point_id='ch-doc-card-526-16', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-526-17', 'doc-card-526', 'sec-card-526-7', 17, '، برچسب‌زنندگان داده، نظارتگران — و چارچوب‌ها این لایه را کمتر پوشش می‌دهند. ۹. ریسک تقلیل‌گرایی: تقلیل هر مسئله‌ی اجتماعی به «مسئله‌ی داده» می‌تواند ریشه‌های اقتصادی و سیاسی نابرابری را پنهان کند.', '57783d719f2d993a47b248e60b983d5cf44d6debefc1af56a753a7ac4ae24e1c', 358, 'ch-doc-card-526-17', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='57783d719f2d993a47b248e60b983d5cf44d6debefc1af56a753a7ac4ae24e1c', token_count=358, vector_point_id='ch-doc-card-526-17', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-526-18', 'doc-card-526', 'sec-card-526-10', 18, 'کتاب «جامعه‌ی نظارت» (گوتهام، ۱۹۹۱)؛ کتاب «مردم به‌جای محصول» (گِبر و لوسر، ۲۰۱۷)؛ کتاب «داده‌کشی: اقتصاد داده و قدرت» (شوشان، ۲۰۱۷)؛ استناد مبنا: Zuboff (2019) بر نظارت سرمایه‌داری.', '840da3c01cb66d1dc47e1b4ae58e9e6612928c506f6b419cd6acf5b6ec8d0a6f', 330, 'ch-doc-card-526-18', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='840da3c01cb66d1dc47e1b4ae58e9e6612928c506f6b419cd6acf5b6ec8d0a6f', token_count=330, vector_point_id='ch-doc-card-526-18', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-527-0', 'doc-card-527', NULL, 0, 'پانوپتیکون (بنتام، فوکو ۱۹۷۵) مدل نظارتی است که در آن احتمال دیده‌شدن، رفتار را از درون شکل می‌دهد؛ در عصر دیجیتال، نظارت متمرکز به پراکنده و داده‌محور تبدیل شده و خودِ کاربر تولیدکننده ردّ است.', '85ecd995f659d20de97349f59bb070b3dfa86aee28a6427fb85e19ab81c275d5', 352, 'ch-doc-card-527-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='85ecd995f659d20de97349f59bb070b3dfa86aee28a6427fb85e19ab81c275d5', token_count=352, vector_point_id='ch-doc-card-527-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-527-1', 'doc-card-527', 'sec-card-527-1', 1, 'داده، الگوریتم، نظارت و حریم خصوصی  بر پایه بنتام', 'd0a124ff8203eb4502baef4e2554047b2eb038b272d25aadcd03cf9e83e3ff72', 89, 'ch-doc-card-527-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d0a124ff8203eb4502baef4e2554047b2eb038b272d25aadcd03cf9e83e3ff72', token_count=89, vector_point_id='ch-doc-card-527-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-527-2', 'doc-card-527', 'sec-card-527-2', 2, '۱. بنیان و منطق نظری ادعای محوری پانوپتیکن این است که در جامعه‌ی اطلاعاتی معاصر، داده کالای محوری و الگوریتم سازوکار حکمرانی است. فوکو (۱۹۷۵) تحلیل کرد که چگونه استخراج، پروفایل‌سازی و تبادل داده‌های شخصی، رابطه‌ی کاربر، پلتفرم و دولت را بازنشانی می‌کند. در این چارچوب، رسانه‌ی امروز نه به‌مثابه جریان پیام، بلکه به‌مثابه جریان اطلاعات‌کشی خوانده می‌شود که در آن رفتار کاربر ماده‌ی خام بازار است.  بر اساس پانوپتیکن، نظارت از بین نرفته، بلکه فرم عوض کرده است: از نظارت متمرکز و گزینشی دولت به نظارت پراکنده، پیوسته و مبتنی بر داده که در آن خودِ کاربر ردّ تولید می‌کند.', '64cb3ef9120180c379656a8a69daa60e82e662052706ff07e5af6e1d7422998b', 1032, 'ch-doc-card-527-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='64cb3ef9120180c379656a8a69daa60e82e662052706ff07e5af6e1d7422998b', token_count=1032, vector_point_id='ch-doc-card-527-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-527-3', 'doc-card-527', 'sec-card-527-2', 3, 'به نظارت پراکنده، پیوسته و مبتنی بر داده که در آن خودِ کاربر ردّ تولید می‌کند. فوکو (۱۹۷۵) نشان داد که منطق «نگاه» وارد طراحی پلتفرم‌های دیجیتال شده و عادی‌شدن نظارت، خودرفتار و خودِ مفهوم حریم خصوصی را دگرگون کرده است.  پانوپتیکن الگوریتم‌ها را میانجی‌های مبهمی می‌داند که تعیین می‌کنند چه چیزی دیده شود و چه چیزی پنهان بماند، چه چیزی اولویت بگیرد و چه چیزی دفن شود. فوکو (۱۹۷۵) تأکید کرد که تصمیمات الگوریتمی — از فید اخبار تا درخواست وام — در عمل تصمیماتی «اجتماعی»‌اند که در کد نوشته شده‌اند و فقدان شفافیت و پاسخگویی درباره‌ی آن‌ها، فرمی تازه از قدرت بی‌پاسخ‌ساز می‌سازد. مطالعه‌ی این سازوکارها بنابراین از مطالعه‌ی قدرت و عدالت جدا نیست.  ۲.', 'f92b79fe0e951e2873d8e6497e0da6671f41734bb84597c2692d82a4071526c6', 1176, 'ch-doc-card-527-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f92b79fe0e951e2873d8e6497e0da6671f41734bb84597c2692d82a4071526c6', token_count=1176, vector_point_id='ch-doc-card-527-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-527-4', 'doc-card-527', 'sec-card-527-2', 4, 'می‌سازد. مطالعه‌ی این سازوکارها بنابراین از مطالعه‌ی قدرت و عدالت جدا نیست.  ۲. ساختارهای مفهومی • داده‌کشی (Data Extraction): جمع‌آوری سیستماتیک داده‌های رفتاری کاربران توسط پلتفرم‌ها و دولت. • پروفایل‌سازی (Profiling): ساختن پروفایل‌های رفتاری و روان‌شناختی از داده برای پیش‌بینی و هدایت رفتار. • مبهم‌بودن الگوریتم (Algorithmic Opacity): عدم دسترسی کاربر و ناظر به منطق و تصمیمات الگوریتم. • حریم خصوصی (Privacy): حق کنترل بر جریان اطلاعات شخصی و شرایط حفاظت از آن در عصر دیجیتال. • داده‌ای‌شدن (Datification): فرایند تبدیل هر بُعد از زندگی اجتماعی به داده. • ردّ دیجیتال (Digital Footprint): اثرهای باقی‌مانده‌ی رفتار فرد در فضاهای دیجیتال و ماندگاری آن‌ها.', 'de946dfef599527d16d3d23651f0440a40b27c852e1feaaef7238d2aa967be77', 1201, 'ch-doc-card-527-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='de946dfef599527d16d3d23651f0440a40b27c852e1feaaef7238d2aa967be77', token_count=1201, vector_point_id='ch-doc-card-527-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-527-5', 'doc-card-527', 'sec-card-527-2', 5, 'l Footprint): اثرهای باقی‌مانده‌ی رفتار فرد در فضاهای دیجیتال و ماندگاری آن‌ها. • پانوپتیکون (Panopticon): مدل فوکویی نظارتی که', 'ff666ba5b94c3f48a8d85d684691d15b23840e7cedefe6831c0cf535028c5972', 230, 'ch-doc-card-527-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ff666ba5b94c3f48a8d85d684691d15b23840e7cedefe6831c0cf535028c5972', token_count=230, vector_point_id='ch-doc-card-527-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-527-6', 'doc-card-527', 'sec-card-527-3', 6, '• داده‌کشی (Data Extraction): جمع‌آوری سیستماتیک داده‌های رفتاری کاربران توسط پلتفرم‌ها و دولت. • پروفایل‌سازی (Profiling): ساختن پروفایل‌های رفتاری و روان‌شناختی از داده برای پیش‌بینی و هدایت رفتار. • مبهم‌بودن الگوریتم (Algorithmic Opacity): عدم دسترسی کاربر و ناظر به منطق و تصمیمات الگوریتم. • حریم خصوصی (Privacy): حق کنترل بر جریان اطلاعات شخصی و شرایط حفاظت از آن در عصر دیجیتال. • داده‌ای‌شدن (Datification): فرایند تبدیل هر بُعد از زندگی اجتماعی به داده. • ردّ دیجیتال (Digital Footprint): اثرهای باقی‌مانده‌ی رفتار فرد در فضاهای دیجیتال و ماندگاری آن‌ها. • پانوپتیکون (Panopticon): مدل فوکویی نظارتی که در آن احتمال دیده‌شدن، رفتار را تأمین می‌کند.', '8edb1c82060510576a0f6a7ee2c0631126eb7787f15c81994d3654d1b8502b6d', 1196, 'ch-doc-card-527-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8edb1c82060510576a0f6a7ee2c0631126eb7787f15c81994d3654d1b8502b6d', token_count=1196, vector_point_id='ch-doc-card-527-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-527-7', 'doc-card-527', 'sec-card-527-3', 7, 'Panopticon): مدل فوکویی نظارتی که در آن احتمال دیده‌شدن، رفتار را تأمین می‌کند. • پارادوکس حریم خصوصی (Privacy Paradox): شکاف میان نگرش ابرازشده به حریم خصوصی و رفتار واقعی اشتراک‌گذاری داده.', '8e98a3b52b466d5c84bd6cf264144211ad418393f64e5c4b503958751404e44f', 347, 'ch-doc-card-527-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8e98a3b52b466d5c84bd6cf264144211ad418393f64e5c4b503958751404e44f', token_count=347, vector_point_id='ch-doc-card-527-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-527-8', 'doc-card-527', 'sec-card-527-4', 8, 'در آن احتمال دیده‌شدن، رفتار را تأمین می‌کند. • پارادوکس حریم خصوصی (Privacy Paradox): شکاف میان نگرش ابرازشده به حریم خصوصی و رفتار واقعی اشتراک‌گذاری داده.  ۳. نمونه‌های تحلیلی تبلیغات هدفمند، رُخِ قابل‌دیدن اقتصاد داده است: کاربری که پس از جست‌وجوی یک محصول، آگهی آن را در شبکه‌ی اجتماعی می‌بیند، در پشت صحنه با سیستمی از پروفایل‌سازی بر پایه‌ی میلیون‌ها تعامل روبه‌روست.  رسوایی‌های سوءاستفاده از داده‌های شبکه‌های اجتماعی در انتخابات (مانند پرونده‌ی کمبریج‌آنالیتیکا) نشان دادند که داده‌های شخصی، هنگامی که تجمیع می‌شوند، به ابزاری برای تأثیر سیاسی خارج از آگاهی و رضایت فرد تبدیل می‌شوند.', 'e4c4b3605a91b2f2548b510dcf25fbe1a00234e9ae2c4134e1d74c8438e4161b', 1080, 'ch-doc-card-527-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e4c4b3605a91b2f2548b510dcf25fbe1a00234e9ae2c4134e1d74c8438e4161b', token_count=1080, vector_point_id='ch-doc-card-527-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-527-9', 'doc-card-527', 'sec-card-527-4', 9, 'ع می‌شوند، به ابزاری برای تأثیر سیاسی خارج از آگاهی و رضایت فرد تبدیل می‌شوند.  سیستم اعتبار اجتماعی در برخی کشورها، منطق نظارت مبتنی بر داده را در حدّ نهایی نشان می‌دهد: امتیازی که بر رفتار شهروند ثبت می‌شود، به دسترسی او به خدمات، سفر و حتی مسکن ربط داده می‌شود.  «نظارت معکوس» — فیلم‌برداری شهروندان از پلیس و نهادهای قدرتمند با گوشی — نشان می‌دهد که نگاه دیگر یک‌طرفه نیست و ساختارهای نظارتی همواره مورد چالش و بازنشانی هستند.  وقتی فید الگوریتمی به کاربر صرفاَ محتوایی هم‌سو با باورهای پیشینش نشان می‌دهد، نه فقط «شخصی‌سازی» رخ داده، بلکه نوعی سانسور الگوریتمی است که ادراک جهان کاربر را بدون آگاهی او شکل می‌دهد.', '8694ba72177c974c35f1980d8fa64c6c9e99d13422e9e76a4ac891bb5cd22053', 1123, 'ch-doc-card-527-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8694ba72177c974c35f1980d8fa64c6c9e99d13422e9e76a4ac891bb5cd22053', token_count=1123, vector_point_id='ch-doc-card-527-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-527-10', 'doc-card-527', 'sec-card-527-4', 10, 'لکه نوعی سانسور الگوریتمی است که ادراک جهان کاربر را بدون آگاهی او شکل می‌دهد.  تنظیمات حریم خصوصی شبکه‌های اجتماعی — پیچیده و پر از پیش‌فرض — نشان می‌دهد «انتخاب»ی که به کاربر پیشنهاد می‌شود گاه انتخابی صوری است و قدرت واقعی تصمیم در دست طراح پلتفرم می‌ماند.  ۴. نقدها و چالش‌ها ۱. جبرگرایی زیرساخت: چارچوب گاه می‌تواند به تصویر «داده‌ی همه‌چیز را می‌بیند و هدایت می‌کند» انجام دهد و عاملیت انسان، مقاومت مدنی و امکان‌های نظارت معکوس را دست‌کم بگیرد. ۲. مبهم‌بودن الگوریتم در دو سو: هم شرکت‌ها و الگوریتم‌هایشان شفاف نیستند و هم کاربرانی که چگونه داده‌شان مصرف می‌شود را نمی‌دانند؛ این ابهام از دو سو هم‌زمان آزمون تجربی ادعاها را دشوار می‌کند. ۳.', '0181b0635251fb48bc8aab39586901a32b12cffb206a8807bdb59ba176d79128', 1178, 'ch-doc-card-527-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0181b0635251fb48bc8aab39586901a32b12cffb206a8807bdb59ba176d79128', token_count=1178, vector_point_id='ch-doc-card-527-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-527-11', 'doc-card-527', 'sec-card-527-4', 11, 'را نمی‌دانند؛ این ابهام از دو سو هم‌زمان آزمون تجربی ادعاها را دشوار می‌کند. ۳. جابه‌جایی سریع هدف: حوزه‌ی داده و نظارت دیجیتال با سرعتی که ا', 'ddd3dc54c77f3dffb11e1c045c59250f09135816e4cb5bdc58f8a9cf67e2b7b4', 256, 'ch-doc-card-527-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ddd3dc54c77f3dffb11e1c045c59250f09135816e4cb5bdc58f8a9cf67e2b7b4', token_count=256, vector_point_id='ch-doc-card-527-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-527-12', 'doc-card-527', 'sec-card-527-5', 12, 'تبلیغات هدفمند، رُخِ قابل‌دیدن اقتصاد داده است: کاربری که پس از جست‌وجوی یک محصول، آگهی آن را در شبکه‌ی اجتماعی می‌بیند، در پشت صحنه با سیستمی از پروفایل‌سازی بر پایه‌ی میلیون‌ها تعامل روبه‌روست.  رسوایی‌های سوءاستفاده از داده‌های شبکه‌های اجتماعی در انتخابات (مانند پرونده‌ی کمبریج‌آنالیتیکا) نشان دادند که داده‌های شخصی، هنگامی که تجمیع می‌شوند، به ابزاری برای تأثیر سیاسی خارج از آگاهی و رضایت فرد تبدیل می‌شوند.  سیستم اعتبار اجتماعی در برخی کشورها، منطق نظارت مبتنی بر داده را در حدّ نهایی نشان می‌دهد: امتیازی که بر رفتار شهروند ثبت می‌شود، به دسترسی او به خدمات، سفر و حتی مسکن ربط داده می‌شود.', '3dc96c38b13f32c2b1995dae3348d8b12d3bafe9cce293bdd230368b7078eb69', 1092, 'ch-doc-card-527-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3dc96c38b13f32c2b1995dae3348d8b12d3bafe9cce293bdd230368b7078eb69', token_count=1092, vector_point_id='ch-doc-card-527-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-527-13', 'doc-card-527', 'sec-card-527-5', 13, 'فتار شهروند ثبت می‌شود، به دسترسی او به خدمات، سفر و حتی مسکن ربط داده می‌شود.  «نظارت معکوس» — فیلم‌برداری شهروندان از پلیس و نهادهای قدرتمند با گوشی — نشان می‌دهد که نگاه دیگر یک‌طرفه نیست و ساختارهای نظارتی همواره مورد چالش و بازنشانی هستند.  وقتی فید الگوریتمی به کاربر صرفاَ محتوایی هم‌سو با باورهای پیشینش نشان می‌دهد، نه فقط «شخصی‌سازی» رخ داده، بلکه نوعی سانسور الگوریتمی است که ادراک جهان کاربر را بدون آگاهی او شکل می‌دهد.  تنظیمات حریم خصوصی شبکه‌های اجتماعی — پیچیده و پر از پیش‌فرض — نشان می‌دهد «انتخاب»ی که به کاربر پیشنهاد می‌شود گاه انتخابی صوری است و قدرت واقعی تصمیم در دست طراح پلتفرم می‌ماند.', '3bb22489138dff07609c998d816ad240a46e6cfd7b5a4ebe4dcc0a3caf70e460', 1114, 'ch-doc-card-527-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3bb22489138dff07609c998d816ad240a46e6cfd7b5a4ebe4dcc0a3caf70e460', token_count=1114, vector_point_id='ch-doc-card-527-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-527-14', 'doc-card-527', 'sec-card-527-6', 14, '۱. جبرگرایی زیرساخت: چارچوب گاه می‌تواند به تصویر «داده‌ی همه‌چیز را می‌بیند و هدایت می‌کند» انجام دهد و عاملیت انسان، مقاومت مدنی و امکان‌های نظارت معکوس را دست‌کم بگیرد. ۲. مبهم‌بودن الگوریتم در دو سو: هم شرکت‌ها و الگوریتم‌هایشان شفاف نیستند و هم کاربرانی که چگونه داده‌شان مصرف می‌شود را نمی‌دانند؛ این ابهام از دو سو هم‌زمان آزمون تجربی ادعاها را دشوار می‌کند. ۳. جابه‌جایی سریع هدف: حوزه‌ی داده و نظارت دیجیتال با سرعتی که الگوهای نظارت تغییر می‌کنند، پیش می‌رود و بسیاری از یافته‌ها در نوسانه‌ی بعدی بی‌مورد می‌شوند. ۴.', 'f398ce63199b6479e67d7b985155e60698a50bfc46dc87c835028091d9a42e10', 956, 'ch-doc-card-527-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f398ce63199b6479e67d7b985155e60698a50bfc46dc87c835028091d9a42e10', token_count=956, vector_point_id='ch-doc-card-527-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-527-15', 'doc-card-527', 'sec-card-527-6', 15, 'ر می‌کنند، پیش می‌رود و بسیاری از یافته‌ها در نوسانه‌ی بعدی بی‌مورد می‌شوند. ۴. ناهمگنی «نظارت» در فرهنگ‌ها: مفهوم نظارت و حریم خصوصی در فرهنگ‌ها و نظام‌های حقوقی متفاوت است و مدل‌های توسعه‌یافته در غرب (مانند الگوهای پانوپتیکون) هر جا بدون بازنشانی کاربرد ندارند. ۵. مس', '4aa6d13d77416151b0bfda2b7adad03639b5c4d1946e19469d965084882cc3b9', 490, 'ch-doc-card-527-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4aa6d13d77416151b0bfda2b7adad03639b5c4d1946e19469d965084882cc3b9', token_count=490, vector_point_id='ch-doc-card-527-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-527-16', 'doc-card-527', 'sec-card-527-7', 16, 'ئله‌ی قدرت: تمرکز بر «عادی‌شدن نظارت» می‌تواند قدرت سیاسی و اقتصادی آن‌هایی را که داده را استخراج و از آن سود می‌برند، در تصویر تار بگذارد. ۶. سنجش رفتار: سنجش رفتارهای آنلاین (پذیرش شرایط، اشتراک‌گذاری) به دلیل تغییر مداوم رابط و بستر، قابل‌مقایسه در طول زمان نیست. ۷. پارادوکس رفتار و نگرش: شکاف میان نگرش ابرازشده به حریم خصوصی و رفتار واقعی (پارادوکس حریم خصوصی) می‌تواند نتیجه‌گیری‌های کلی درباره‌ی «ارزش‌های» مخاطب را گمراه‌کننده کند. ۸. غفلت از جنبه‌ی کار: اقتصاد داده بر پایه‌ی کار نامرئی است — تولیدکنندگان محتوا، برچسب‌زنندگان داده، نظارتگران — و چارچوب‌ها این لایه را کمتر پوشش می‌دهند. ۹.', 'cbcd30bf1d0c22b052abf91910125037eb44ac19912a7ec476b3ead3424726e8', 1090, 'ch-doc-card-527-16', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cbcd30bf1d0c22b052abf91910125037eb44ac19912a7ec476b3ead3424726e8', token_count=1090, vector_point_id='ch-doc-card-527-16', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-527-17', 'doc-card-527', 'sec-card-527-7', 17, '، برچسب‌زنندگان داده، نظارتگران — و چارچوب‌ها این لایه را کمتر پوشش می‌دهند. ۹. ریسک تقلیل‌گرایی: تقلیل هر مسئله‌ی اجتماعی به «مسئله‌ی داده» می‌تواند ریشه‌های اقتصادی و سیاسی نابرابری را پنهان کند.', '57783d719f2d993a47b248e60b983d5cf44d6debefc1af56a753a7ac4ae24e1c', 358, 'ch-doc-card-527-17', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='57783d719f2d993a47b248e60b983d5cf44d6debefc1af56a753a7ac4ae24e1c', token_count=358, vector_point_id='ch-doc-card-527-17', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-527-18', 'doc-card-527', 'sec-card-527-10', 18, 'کتاب «جامعه‌ی نظارت» (گوتهام، ۱۹۹۱)؛ کتاب «مردم به‌جای محصول» (گِبر و لوسر، ۲۰۱۷)؛ کتاب «داده‌کشی: اقتصاد داده و قدرت» (شوشان، ۲۰۱۷)؛ استناد مبنا: Zuboff (2019) بر نظارت سرمایه‌داری.', '840da3c01cb66d1dc47e1b4ae58e9e6612928c506f6b419cd6acf5b6ec8d0a6f', 330, 'ch-doc-card-527-18', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='840da3c01cb66d1dc47e1b4ae58e9e6612928c506f6b419cd6acf5b6ec8d0a6f', token_count=330, vector_point_id='ch-doc-card-527-18', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-528-0', 'doc-card-528', NULL, 0, 'مکتب نظارت (مان، ۲۰۰۲) تأکید می‌کند نظارت معاصر نه صرفا از بالا، بلکه از پایین و درون جریان داده رخ می‌دهد؛ خودرفتار و تولید پیوسته ردّ دیجیتال، حریم خصوصی و مفهوم «نگاه» را دگرگون کرده است.', '09a2682ea73b350304b657688aa669d8e5b3312abfc80006301d559df767b3fc', 345, 'ch-doc-card-528-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='09a2682ea73b350304b657688aa669d8e5b3312abfc80006301d559df767b3fc', token_count=345, vector_point_id='ch-doc-card-528-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-528-1', 'doc-card-528', 'sec-card-528-1', 1, 'داده، الگوریتم، نظارت و حریم خصوصی  نظارت از پایین.', '449a77a97c133a3717cba19df23034f3c945f550a1bbcca94858c92ef7b51799', 92, 'ch-doc-card-528-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='449a77a97c133a3717cba19df23034f3c945f550a1bbcca94858c92ef7b51799', token_count=92, vector_point_id='ch-doc-card-528-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-528-2', 'doc-card-528', 'sec-card-528-2', 2, '۱. بنیان و منطق نظری ادعای محوری سورویانس این است که در جامعه‌ی اطلاعاتی معاصر، داده کالای محوری و الگوریتم سازوکار حکمرانی است. مان (۲۰۰۲) تحلیل کرد که چگونه استخراج، پروفایل‌سازی و تبادل داده‌های شخصی، رابطه‌ی کاربر، پلتفرم و دولت را بازنشانی می‌کند. در این چارچوب، رسانه‌ی امروز نه به‌مثابه جریان پیام، بلکه به‌مثابه جریان اطلاعات‌کشی خوانده می‌شود که در آن رفتار کاربر ماده‌ی خام بازار است.  بر اساس سورویانس، نظارت از بین نرفته، بلکه فرم عوض کرده است: از نظارت متمرکز و گزینشی دولت به نظارت پراکنده، پیوسته و مبتنی بر داده که در آن خودِ کاربر ردّ تولید می‌کند.', 'c249f1217100208f240fb68e8bdf234ae944fbda515ead1e94ab787901043ed4', 1027, 'ch-doc-card-528-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c249f1217100208f240fb68e8bdf234ae944fbda515ead1e94ab787901043ed4', token_count=1027, vector_point_id='ch-doc-card-528-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-528-3', 'doc-card-528', 'sec-card-528-2', 3, 'به نظارت پراکنده، پیوسته و مبتنی بر داده که در آن خودِ کاربر ردّ تولید می‌کند. مان (۲۰۰۲) نشان داد که منطق «نگاه» وارد طراحی پلتفرم‌های دیجیتال شده و عادی‌شدن نظارت، خودرفتار و خودِ مفهوم حریم خصوصی را دگرگون کرده است.  سورویانس الگوریتم‌ها را میانجی‌های مبهمی می‌داند که تعیین می‌کنند چه چیزی دیده شود و چه چیزی پنهان بماند، چه چیزی اولویت بگیرد و چه چیزی دفن شود. مان (۲۰۰۲) تأکید کرد که تصمیمات الگوریتمی — از فید اخبار تا درخواست وام — در عمل تصمیماتی «اجتماعی»‌اند که در کد نوشته شده‌اند و فقدان شفافیت و پاسخگویی درباره‌ی آن‌ها، فرمی تازه از قدرت بی‌پاسخ‌ساز می‌سازد. مطالعه‌ی این سازوکارها بنابراین از مطالعه‌ی قدرت و عدالت جدا نیست.  ۲.', '6661e10d22b57dd184d86e07634df6cc652636531747f9e748e5664e85d6ba5d', 1170, 'ch-doc-card-528-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6661e10d22b57dd184d86e07634df6cc652636531747f9e748e5664e85d6ba5d', token_count=1170, vector_point_id='ch-doc-card-528-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-528-4', 'doc-card-528', 'sec-card-528-2', 4, 'می‌سازد. مطالعه‌ی این سازوکارها بنابراین از مطالعه‌ی قدرت و عدالت جدا نیست.  ۲. ساختارهای مفهومی • داده‌کشی (Data Extraction): جمع‌آوری سیستماتیک داده‌های رفتاری کاربران توسط پلتفرم‌ها و دولت. • پروفایل‌سازی (Profiling): ساختن پروفایل‌های رفتاری و روان‌شناختی از داده برای پیش‌بینی و هدایت رفتار. • مبهم‌بودن الگوریتم (Algorithmic Opacity): عدم دسترسی کاربر و ناظر به منطق و تصمیمات الگوریتم. • حریم خصوصی (Privacy): حق کنترل بر جریان اطلاعات شخصی و شرایط حفاظت از آن در عصر دیجیتال. • داده‌ای‌شدن (Datification): فرایند تبدیل هر بُعد از زندگی اجتماعی به داده. • ردّ دیجیتال (Digital Footprint): اثرهای باقی‌مانده‌ی رفتار فرد در فضاهای دیجیتال و ماندگاری آن‌ها.', 'de946dfef599527d16d3d23651f0440a40b27c852e1feaaef7238d2aa967be77', 1201, 'ch-doc-card-528-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='de946dfef599527d16d3d23651f0440a40b27c852e1feaaef7238d2aa967be77', token_count=1201, vector_point_id='ch-doc-card-528-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-528-5', 'doc-card-528', 'sec-card-528-2', 5, 'l Footprint): اثرهای باقی‌مانده‌ی رفتار فرد در فضاهای دیجیتال و ماندگاری آن‌ها. • پانوپتیکون (Panopticon): مدل فوکویی نظارتی که در', '1ddabe0f90bd5a2f9270388b6f18eb742873ef698bf0e83fefb8b47808a9f37c', 236, 'ch-doc-card-528-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1ddabe0f90bd5a2f9270388b6f18eb742873ef698bf0e83fefb8b47808a9f37c', token_count=236, vector_point_id='ch-doc-card-528-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-528-6', 'doc-card-528', 'sec-card-528-3', 6, '• داده‌کشی (Data Extraction): جمع‌آوری سیستماتیک داده‌های رفتاری کاربران توسط پلتفرم‌ها و دولت. • پروفایل‌سازی (Profiling): ساختن پروفایل‌های رفتاری و روان‌شناختی از داده برای پیش‌بینی و هدایت رفتار. • مبهم‌بودن الگوریتم (Algorithmic Opacity): عدم دسترسی کاربر و ناظر به منطق و تصمیمات الگوریتم. • حریم خصوصی (Privacy): حق کنترل بر جریان اطلاعات شخصی و شرایط حفاظت از آن در عصر دیجیتال. • داده‌ای‌شدن (Datification): فرایند تبدیل هر بُعد از زندگی اجتماعی به داده. • ردّ دیجیتال (Digital Footprint): اثرهای باقی‌مانده‌ی رفتار فرد در فضاهای دیجیتال و ماندگاری آن‌ها. • پانوپتیکون (Panopticon): مدل فوکویی نظارتی که در آن احتمال دیده‌شدن، رفتار را تأمین می‌کند.', '8edb1c82060510576a0f6a7ee2c0631126eb7787f15c81994d3654d1b8502b6d', 1196, 'ch-doc-card-528-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8edb1c82060510576a0f6a7ee2c0631126eb7787f15c81994d3654d1b8502b6d', token_count=1196, vector_point_id='ch-doc-card-528-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-528-7', 'doc-card-528', 'sec-card-528-3', 7, 'Panopticon): مدل فوکویی نظارتی که در آن احتمال دیده‌شدن، رفتار را تأمین می‌کند. • پارادوکس حریم خصوصی (Privacy Paradox): شکاف میان نگرش ابرازشده به حریم خصوصی و رفتار واقعی اشتراک‌گذاری داده.', '8e98a3b52b466d5c84bd6cf264144211ad418393f64e5c4b503958751404e44f', 347, 'ch-doc-card-528-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8e98a3b52b466d5c84bd6cf264144211ad418393f64e5c4b503958751404e44f', token_count=347, vector_point_id='ch-doc-card-528-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-528-8', 'doc-card-528', 'sec-card-528-4', 8, 'آن احتمال دیده‌شدن، رفتار را تأمین می‌کند. • پارادوکس حریم خصوصی (Privacy Paradox): شکاف میان نگرش ابرازشده به حریم خصوصی و رفتار واقعی اشتراک‌گذاری داده.  ۳. نمونه‌های تحلیلی تبلیغات هدفمند، رُخِ قابل‌دیدن اقتصاد داده است: کاربری که پس از جست‌وجوی یک محصول، آگهی آن را در شبکه‌ی اجتماعی می‌بیند، در پشت صحنه با سیستمی از پروفایل‌سازی بر پایه‌ی میلیون‌ها تعامل روبه‌روست.  رسوایی‌های سوءاستفاده از داده‌های شبکه‌های اجتماعی در انتخابات (مانند پرونده‌ی کمبریج‌آنالیتیکا) نشان دادند که داده‌های شخصی، هنگامی که تجمیع می‌شوند، به ابزاری برای تأثیر سیاسی خارج از آگاهی و رضایت فرد تبدیل می‌شوند.', '2c77292941a7c8c96ffd3c612668ca0a3861171279d8617e4dcac2f93008283c', 1074, 'ch-doc-card-528-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2c77292941a7c8c96ffd3c612668ca0a3861171279d8617e4dcac2f93008283c', token_count=1074, vector_point_id='ch-doc-card-528-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-528-9', 'doc-card-528', 'sec-card-528-4', 9, 'ع می‌شوند، به ابزاری برای تأثیر سیاسی خارج از آگاهی و رضایت فرد تبدیل می‌شوند.  سیستم اعتبار اجتماعی در برخی کشورها، منطق نظارت مبتنی بر داده را در حدّ نهایی نشان می‌دهد: امتیازی که بر رفتار شهروند ثبت می‌شود، به دسترسی او به خدمات، سفر و حتی مسکن ربط داده می‌شود.  «نظارت معکوس» — فیلم‌برداری شهروندان از پلیس و نهادهای قدرتمند با گوشی — نشان می‌دهد که نگاه دیگر یک‌طرفه نیست و ساختارهای نظارتی همواره مورد چالش و بازنشانی هستند.  وقتی فید الگوریتمی به کاربر صرفاَ محتوایی هم‌سو با باورهای پیشینش نشان می‌دهد، نه فقط «شخصی‌سازی» رخ داده، بلکه نوعی سانسور الگوریتمی است که ادراک جهان کاربر را بدون آگاهی او شکل می‌دهد.', '8694ba72177c974c35f1980d8fa64c6c9e99d13422e9e76a4ac891bb5cd22053', 1123, 'ch-doc-card-528-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8694ba72177c974c35f1980d8fa64c6c9e99d13422e9e76a4ac891bb5cd22053', token_count=1123, vector_point_id='ch-doc-card-528-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-528-10', 'doc-card-528', 'sec-card-528-4', 10, 'لکه نوعی سانسور الگوریتمی است که ادراک جهان کاربر را بدون آگاهی او شکل می‌دهد.  تنظیمات حریم خصوصی شبکه‌های اجتماعی — پیچیده و پر از پیش‌فرض — نشان می‌دهد «انتخاب»ی که به کاربر پیشنهاد می‌شود گاه انتخابی صوری است و قدرت واقعی تصمیم در دست طراح پلتفرم می‌ماند.  ۴. نقدها و چالش‌ها ۱. جبرگرایی زیرساخت: چارچوب گاه می‌تواند به تصویر «داده‌ی همه‌چیز را می‌بیند و هدایت می‌کند» انجام دهد و عاملیت انسان، مقاومت مدنی و امکان‌های نظارت معکوس را دست‌کم بگیرد. ۲. مبهم‌بودن الگوریتم در دو سو: هم شرکت‌ها و الگوریتم‌هایشان شفاف نیستند و هم کاربرانی که چگونه داده‌شان مصرف می‌شود را نمی‌دانند؛ این ابهام از دو سو هم‌زمان آزمون تجربی ادعاها را دشوار می‌کند. ۳.', '0181b0635251fb48bc8aab39586901a32b12cffb206a8807bdb59ba176d79128', 1178, 'ch-doc-card-528-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0181b0635251fb48bc8aab39586901a32b12cffb206a8807bdb59ba176d79128', token_count=1178, vector_point_id='ch-doc-card-528-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-528-11', 'doc-card-528', 'sec-card-528-4', 11, 'را نمی‌دانند؛ این ابهام از دو سو هم‌زمان آزمون تجربی ادعاها را دشوار می‌کند. ۳. جابه‌جایی سریع هدف: حوزه‌ی داده و نظارت دیجیتال با سرعتی که الگ', '8498e77e2642d08cceb62806d4c4379e2b0d454e23b3cad32294a241050eff8d', 260, 'ch-doc-card-528-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8498e77e2642d08cceb62806d4c4379e2b0d454e23b3cad32294a241050eff8d', token_count=260, vector_point_id='ch-doc-card-528-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-528-12', 'doc-card-528', 'sec-card-528-5', 12, 'تبلیغات هدفمند، رُخِ قابل‌دیدن اقتصاد داده است: کاربری که پس از جست‌وجوی یک محصول، آگهی آن را در شبکه‌ی اجتماعی می‌بیند، در پشت صحنه با سیستمی از پروفایل‌سازی بر پایه‌ی میلیون‌ها تعامل روبه‌روست.  رسوایی‌های سوءاستفاده از داده‌های شبکه‌های اجتماعی در انتخابات (مانند پرونده‌ی کمبریج‌آنالیتیکا) نشان دادند که داده‌های شخصی، هنگامی که تجمیع می‌شوند، به ابزاری برای تأثیر سیاسی خارج از آگاهی و رضایت فرد تبدیل می‌شوند.  سیستم اعتبار اجتماعی در برخی کشورها، منطق نظارت مبتنی بر داده را در حدّ نهایی نشان می‌دهد: امتیازی که بر رفتار شهروند ثبت می‌شود، به دسترسی او به خدمات، سفر و حتی مسکن ربط داده می‌شود.', '3dc96c38b13f32c2b1995dae3348d8b12d3bafe9cce293bdd230368b7078eb69', 1092, 'ch-doc-card-528-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3dc96c38b13f32c2b1995dae3348d8b12d3bafe9cce293bdd230368b7078eb69', token_count=1092, vector_point_id='ch-doc-card-528-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-528-13', 'doc-card-528', 'sec-card-528-5', 13, 'فتار شهروند ثبت می‌شود، به دسترسی او به خدمات، سفر و حتی مسکن ربط داده می‌شود.  «نظارت معکوس» — فیلم‌برداری شهروندان از پلیس و نهادهای قدرتمند با گوشی — نشان می‌دهد که نگاه دیگر یک‌طرفه نیست و ساختارهای نظارتی همواره مورد چالش و بازنشانی هستند.  وقتی فید الگوریتمی به کاربر صرفاَ محتوایی هم‌سو با باورهای پیشینش نشان می‌دهد، نه فقط «شخصی‌سازی» رخ داده، بلکه نوعی سانسور الگوریتمی است که ادراک جهان کاربر را بدون آگاهی او شکل می‌دهد.  تنظیمات حریم خصوصی شبکه‌های اجتماعی — پیچیده و پر از پیش‌فرض — نشان می‌دهد «انتخاب»ی که به کاربر پیشنهاد می‌شود گاه انتخابی صوری است و قدرت واقعی تصمیم در دست طراح پلتفرم می‌ماند.', '3bb22489138dff07609c998d816ad240a46e6cfd7b5a4ebe4dcc0a3caf70e460', 1114, 'ch-doc-card-528-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3bb22489138dff07609c998d816ad240a46e6cfd7b5a4ebe4dcc0a3caf70e460', token_count=1114, vector_point_id='ch-doc-card-528-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-528-14', 'doc-card-528', 'sec-card-528-6', 14, '۱. جبرگرایی زیرساخت: چارچوب گاه می‌تواند به تصویر «داده‌ی همه‌چیز را می‌بیند و هدایت می‌کند» انجام دهد و عاملیت انسان، مقاومت مدنی و امکان‌های نظارت معکوس را دست‌کم بگیرد. ۲. مبهم‌بودن الگوریتم در دو سو: هم شرکت‌ها و الگوریتم‌هایشان شفاف نیستند و هم کاربرانی که چگونه داده‌شان مصرف می‌شود را نمی‌دانند؛ این ابهام از دو سو هم‌زمان آزمون تجربی ادعاها را دشوار می‌کند. ۳. جابه‌جایی سریع هدف: حوزه‌ی داده و نظارت دیجیتال با سرعتی که الگوهای نظارت تغییر می‌کنند، پیش می‌رود و بسیاری از یافته‌ها در نوسانه‌ی بعدی بی‌مورد می‌شوند. ۴.', 'f398ce63199b6479e67d7b985155e60698a50bfc46dc87c835028091d9a42e10', 956, 'ch-doc-card-528-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f398ce63199b6479e67d7b985155e60698a50bfc46dc87c835028091d9a42e10', token_count=956, vector_point_id='ch-doc-card-528-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-528-15', 'doc-card-528', 'sec-card-528-6', 15, 'ر می‌کنند، پیش می‌رود و بسیاری از یافته‌ها در نوسانه‌ی بعدی بی‌مورد می‌شوند. ۴. ناهمگنی «نظارت» در فرهنگ‌ها: مفهوم نظارت و حریم خصوصی در فرهنگ‌ها و نظام‌های حقوقی متفاوت است و مدل‌های توسعه‌یافته در غرب (مانند الگوهای پانوپتیکون) هر جا بدون بازنشانی کاربرد ندارند. ۵. مس', '4aa6d13d77416151b0bfda2b7adad03639b5c4d1946e19469d965084882cc3b9', 490, 'ch-doc-card-528-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4aa6d13d77416151b0bfda2b7adad03639b5c4d1946e19469d965084882cc3b9', token_count=490, vector_point_id='ch-doc-card-528-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-528-16', 'doc-card-528', 'sec-card-528-7', 16, 'ئله‌ی قدرت: تمرکز بر «عادی‌شدن نظارت» می‌تواند قدرت سیاسی و اقتصادی آن‌هایی را که داده را استخراج و از آن سود می‌برند، در تصویر تار بگذارد. ۶. سنجش رفتار: سنجش رفتارهای آنلاین (پذیرش شرایط، اشتراک‌گذاری) به دلیل تغییر مداوم رابط و بستر، قابل‌مقایسه در طول زمان نیست. ۷. پارادوکس رفتار و نگرش: شکاف میان نگرش ابرازشده به حریم خصوصی و رفتار واقعی (پارادوکس حریم خصوصی) می‌تواند نتیجه‌گیری‌های کلی درباره‌ی «ارزش‌های» مخاطب را گمراه‌کننده کند. ۸. غفلت از جنبه‌ی کار: اقتصاد داده بر پایه‌ی کار نامرئی است — تولیدکنندگان محتوا، برچسب‌زنندگان داده، نظارتگران — و چارچوب‌ها این لایه را کمتر پوشش می‌دهند. ۹.', 'cbcd30bf1d0c22b052abf91910125037eb44ac19912a7ec476b3ead3424726e8', 1090, 'ch-doc-card-528-16', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cbcd30bf1d0c22b052abf91910125037eb44ac19912a7ec476b3ead3424726e8', token_count=1090, vector_point_id='ch-doc-card-528-16', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-528-17', 'doc-card-528', 'sec-card-528-7', 17, '، برچسب‌زنندگان داده، نظارتگران — و چارچوب‌ها این لایه را کمتر پوشش می‌دهند. ۹. ریسک تقلیل‌گرایی: تقلیل هر مسئله‌ی اجتماعی به «مسئله‌ی داده» می‌تواند ریشه‌های اقتصادی و سیاسی نابرابری را پنهان کند.', '57783d719f2d993a47b248e60b983d5cf44d6debefc1af56a753a7ac4ae24e1c', 358, 'ch-doc-card-528-17', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='57783d719f2d993a47b248e60b983d5cf44d6debefc1af56a753a7ac4ae24e1c', token_count=358, vector_point_id='ch-doc-card-528-17', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-528-18', 'doc-card-528', 'sec-card-528-10', 18, 'کتاب «جامعه‌ی نظارت» (گوتهام، ۱۹۹۱)؛ کتاب «مردم به‌جای محصول» (گِبر و لوسر، ۲۰۱۷)؛ کتاب «داده‌کشی: اقتصاد داده و قدرت» (شوشان، ۲۰۱۷)؛ استناد مبنا: Zuboff (2019) بر نظارت سرمایه‌داری.', '840da3c01cb66d1dc47e1b4ae58e9e6612928c506f6b419cd6acf5b6ec8d0a6f', 330, 'ch-doc-card-528-18', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='840da3c01cb66d1dc47e1b4ae58e9e6612928c506f6b419cd6acf5b6ec8d0a6f', token_count=330, vector_point_id='ch-doc-card-528-18', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-529-0', 'doc-card-529', NULL, 0, 'ادعای محوری نظریه دادهبرداری/دادهکاوی این است که در جامعه‌ی اطلاعاتی معاصر، داده کالای محوری و الگوریتم سازوکار حکمرانی است. راجر کلارک (۱۹۸۸) تحلیل کرد که چگونه استخراج، پروفایل‌سازی و تبادل داده‌های شخصی، رابطه‌ی کاربر، پلتفرم و دولت را بازنشانی می‌کند. در این چارچوب، رسانه‌ی …', 'e786f6fe7b2e5b23db894394b2250865839b5b9c9b827b012670e8a7e608f1ab', 509, 'ch-doc-card-529-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e786f6fe7b2e5b23db894394b2250865839b5b9c9b827b012670e8a7e608f1ab', token_count=509, vector_point_id='ch-doc-card-529-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-529-1', 'doc-card-529', 'sec-card-529-1', 1, 'داده، الگوریتم، نظارت و حریم خصوصی  ادعای محوری نظریه دادهبرداری/دادهکاوی این است که در جامعه‌ی اطلاعاتی معاصر، داده کالای محوری و الگوریتم سازوکار حکمرانی است. راجر کلارک (۱۹۸۸) تحلیل کرد که چگونه استخراج، پروفایل‌سازی و تبادل داده‌های شخصی، رابطه‌ی کاربر، پلتفرم و دولت را بازنشانی می‌کند. در این چارچوب، رسانه‌ی امروز نه به‌مثابه جریان پیام، بلکه به‌مثابه جریان اطلاعات‌کشی خوانده می‌شود که در آن رفتار کاربر ماده‌ی خام بازار است.  بر اساس نظریه دادهبرداری/دادهکاوی، نظارت از بین نرفته، بلکه فرم عوض کرده است: از نظارت متمرکز و گزینشی دولت به نظارت پراکنده، پیوسته و مبتنی بر داده که در آن خودِ کاربر ردّ تولید می‌کند.', 'ec55afe8e8d4207453c0ccf2a3991ee0110b24999bdf7e7f1691d68ffe7c681d', 1129, 'ch-doc-card-529-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ec55afe8e8d4207453c0ccf2a3991ee0110b24999bdf7e7f1691d68ffe7c681d', token_count=1129, vector_point_id='ch-doc-card-529-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-529-2', 'doc-card-529', 'sec-card-529-1', 2, 'به نظارت پراکنده، پیوسته و مبتنی بر داده که در آن خودِ کاربر ردّ تولید می‌کند. راجر کلارک (۱۹۸۸) نشان داد که منطق «نگاه» وارد طراحی پلتفرم‌های دیجیتال شده و عادی‌شدن نظارت، خودرفتار و خودِ مفهوم حریم خصوصی را دگرگون کرده است.  نظریه دادهبرداری/دادهکاوی الگوریتم‌ها را میانجی‌های مبهمی می‌داند که تعیین می‌کنند چه چیزی دیده شود و چه چیزی پنهان بماند، چه چیزی اولویت بگیرد و چه چیزی دفن شود. راجر کلارک (۱۹۸۸) تأکید کرد که تصمیمات الگوریتمی — از فید اخبار تا درخواست وام — در عمل تصمیماتی «اجتماعی»‌اند که در کد نوشته شده‌اند و فقدان شفافیت و پاسخگویی درباره‌ی آن‌ها، فرمی تازه از قدرت بی‌پاسخ‌ساز می‌سازد. مطالعه‌ی این سازوکارها بنابراین از مطالعه‌ی قدرت و عدالت جدا نیست.', 'efc0d711b4fe0f92ddbdc4dbe81fd25928f58c0aed26c7581fa488211cc4f54b', 1220, 'ch-doc-card-529-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='efc0d711b4fe0f92ddbdc4dbe81fd25928f58c0aed26c7581fa488211cc4f54b', token_count=1220, vector_point_id='ch-doc-card-529-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-529-3', 'doc-card-529', 'sec-card-529-2', 3, '۱. بنیان و منطق نظری ادعای محوری نظریه دادهبرداری/دادهکاوی این است که در جامعه‌ی اطلاعاتی معاصر، داده کالای محوری و الگوریتم سازوکار حکمرانی است. راجر کلارک (۱۹۸۸) تحلیل کرد که چگونه استخراج، پروفایل‌سازی و تبادل داده‌های شخصی، رابطه‌ی کاربر، پلتفرم و دولت را بازنشانی می‌کند. در این چارچوب، رسانه‌ی امروز نه به‌مثابه جریان پیام، بلکه به‌مثابه جریان اطلاعات‌کشی خوانده می‌شود که در آن رفتار کاربر ماده‌ی خام بازار است.  بر اساس نظریه دادهبرداری/دادهکاوی، نظارت از بین نرفته، بلکه فرم عوض کرده است: از نظارت متمرکز و گزینشی دولت به نظارت پراکنده، پیوسته و مبتنی بر داده که در آن خودِ کاربر ردّ تولید می‌کند.', '5bcfb2a29fa15694c95ace7bfb822390fab4f18059c8278ac4a3b7550273bbb2', 1101, 'ch-doc-card-529-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5bcfb2a29fa15694c95ace7bfb822390fab4f18059c8278ac4a3b7550273bbb2', token_count=1101, vector_point_id='ch-doc-card-529-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-529-4', 'doc-card-529', 'sec-card-529-2', 4, 'به نظارت پراکنده، پیوسته و مبتنی بر داده که در آن خودِ کاربر ردّ تولید می‌کند. راجر کلارک (۱۹۸۸) نشان داد که منطق «نگاه» وارد طراحی پلتفرم‌های دیجیتال شده و عادی‌شدن نظارت، خودرفتار و خودِ مفهوم حریم خصوصی را دگرگون کرده است.  نظریه دادهبرداری/دادهکاوی الگوریتم‌ها را میانجی‌های مبهمی می‌داند که تعیین می‌کنند چه چیزی دیده شود و چه چیزی پنهان بماند، چه چیزی اولویت بگیرد و چه چیزی دفن شود. راجر کلارک (۱۹۸۸) تأکید کرد که تصمیمات الگوریتمی — از فید اخبار تا درخواست وام — در عمل تصمیماتی «اجتماعی»‌اند که در کد نوشته شده‌اند و فقدان شفافیت و پاسخگویی درباره‌ی آن‌ها، فرمی تازه از قدرت بی‌پاسخ‌ساز می‌سازد. مطالعه‌ی این سازوکارها بنابراین از مطالعه‌ی قدرت و عدالت جدا نیست.  ۲.', 'dd537575bbc1195c8b91f846cb7ad305fa5a7f845a5ee5ea46979031dfa7bba8', 1227, 'ch-doc-card-529-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='dd537575bbc1195c8b91f846cb7ad305fa5a7f845a5ee5ea46979031dfa7bba8', token_count=1227, vector_point_id='ch-doc-card-529-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-529-5', 'doc-card-529', 'sec-card-529-2', 5, 'می‌سازد. مطالعه‌ی این سازوکارها بنابراین از مطالعه‌ی قدرت و عدالت جدا نیست.  ۲. ساختارهای مفهومی • داده‌کشی (Data Extraction): جمع‌آوری سیستماتیک داده‌های رفتاری کاربران توسط پلتفرم‌ها و دولت. • پروفایل‌سازی (Profiling): ساختن پروفایل‌های رفتاری و روان‌شناختی از داده برای پیش‌بینی و هدایت رفتار. • مبهم‌بودن الگوریتم (Algorithmic Opacity): عدم دسترسی کاربر و ناظر به منطق و تصمیمات الگوریتم. • حریم خصوصی (Privacy): حق کنترل بر جریان اطلاعات شخصی و شرایط حفاظت از آن در عصر دیجیتال. • داده‌ای‌شدن (Datification): فرایند تبدیل هر بُعد از زندگی اجتماعی به داده. • ردّ دیجیتال (Digital Footprint): اثرهای باقی‌مانده‌ی رفتار فرد در فضاهای دیجیتال و ماندگاری آن‌ها. • پانوپت', 'dfcc7d87745e92f9c36fc471a108eab3f6182b681b08b13ed34bfb827d251190', 1218, 'ch-doc-card-529-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='dfcc7d87745e92f9c36fc471a108eab3f6182b681b08b13ed34bfb827d251190', token_count=1218, vector_point_id='ch-doc-card-529-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-529-6', 'doc-card-529', 'sec-card-529-3', 6, '• داده‌کشی (Data Extraction): جمع‌آوری سیستماتیک داده‌های رفتاری کاربران توسط پلتفرم‌ها و دولت. • پروفایل‌سازی (Profiling): ساختن پروفایل‌های رفتاری و روان‌شناختی از داده برای پیش‌بینی و هدایت رفتار. • مبهم‌بودن الگوریتم (Algorithmic Opacity): عدم دسترسی کاربر و ناظر به منطق و تصمیمات الگوریتم. • حریم خصوصی (Privacy): حق کنترل بر جریان اطلاعات شخصی و شرایط حفاظت از آن در عصر دیجیتال. • داده‌ای‌شدن (Datification): فرایند تبدیل هر بُعد از زندگی اجتماعی به داده. • ردّ دیجیتال (Digital Footprint): اثرهای باقی‌مانده‌ی رفتار فرد در فضاهای دیجیتال و ماندگاری آن‌ها. • پانوپتیکون (Panopticon): مدل فوکویی نظارتی که در آن احتمال دیده‌شدن، رفتار را تأمین می‌کند.', '8edb1c82060510576a0f6a7ee2c0631126eb7787f15c81994d3654d1b8502b6d', 1196, 'ch-doc-card-529-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8edb1c82060510576a0f6a7ee2c0631126eb7787f15c81994d3654d1b8502b6d', token_count=1196, vector_point_id='ch-doc-card-529-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-529-7', 'doc-card-529', 'sec-card-529-3', 7, 'Panopticon): مدل فوکویی نظارتی که در آن احتمال دیده‌شدن، رفتار را تأمین می‌کند. • پارادوکس حریم خصوصی (Privacy Paradox): شکاف میان نگرش ابرازشده به حریم خصوصی و رفتار واقعی اشتراک‌گذاری داده.', '8e98a3b52b466d5c84bd6cf264144211ad418393f64e5c4b503958751404e44f', 347, 'ch-doc-card-529-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8e98a3b52b466d5c84bd6cf264144211ad418393f64e5c4b503958751404e44f', token_count=347, vector_point_id='ch-doc-card-529-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-529-8', 'doc-card-529', 'sec-card-529-4', 8, 'یکون (Panopticon): مدل فوکویی نظارتی که در آن احتمال دیده‌شدن، رفتار را تأمین می‌کند. • پارادوکس حریم خصوصی (Privacy Paradox): شکاف میان نگرش ابرازشده به حریم خصوصی و رفتار واقعی اشتراک‌گذاری داده.  ۳. نمونه‌های تحلیلی تبلیغات هدفمند، رُخِ قابل‌دیدن اقتصاد داده است: کاربری که پس از جست‌وجوی یک محصول، آگهی آن را در شبکه‌ی اجتماعی می‌بیند، در پشت صحنه با سیستمی از پروفایل‌سازی بر پایه‌ی میلیون‌ها تعامل روبه‌روست.  رسوایی‌های سوءاستفاده از داده‌های شبکه‌های اجتماعی در انتخابات (مانند پرونده‌ی کمبریج‌آنالیتیکا) نشان دادند که داده‌های شخصی، هنگامی که تجمیع می‌شوند، به ابزاری برای تأثیر سیاسی خارج از آگاهی و رضایت فرد تبدیل می‌شوند.', 'e9d2a19ecc06217d30ea6d845a51616d2290b768f5c9c29ac57fc4bdff20fba7', 1152, 'ch-doc-card-529-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e9d2a19ecc06217d30ea6d845a51616d2290b768f5c9c29ac57fc4bdff20fba7', token_count=1152, vector_point_id='ch-doc-card-529-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-529-9', 'doc-card-529', 'sec-card-529-4', 9, 'ع می‌شوند، به ابزاری برای تأثیر سیاسی خارج از آگاهی و رضایت فرد تبدیل می‌شوند.  سیستم اعتبار اجتماعی در برخی کشورها، منطق نظارت مبتنی بر داده را در حدّ نهایی نشان می‌دهد: امتیازی که بر رفتار شهروند ثبت می‌شود، به دسترسی او به خدمات، سفر و حتی مسکن ربط داده می‌شود.  «نظارت معکوس» — فیلم‌برداری شهروندان از پلیس و نهادهای قدرتمند با گوشی — نشان می‌دهد که نگاه دیگر یک‌طرفه نیست و ساختارهای نظارتی همواره مورد چالش و بازنشانی هستند.  وقتی فید الگوریتمی به کاربر صرفاَ محتوایی هم‌سو با باورهای پیشینش نشان می‌دهد، نه فقط «شخصی‌سازی» رخ داده، بلکه نوعی سانسور الگوریتمی است که ادراک جهان کاربر را بدون آگاهی او شکل می‌دهد.', '8694ba72177c974c35f1980d8fa64c6c9e99d13422e9e76a4ac891bb5cd22053', 1123, 'ch-doc-card-529-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8694ba72177c974c35f1980d8fa64c6c9e99d13422e9e76a4ac891bb5cd22053', token_count=1123, vector_point_id='ch-doc-card-529-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-529-10', 'doc-card-529', 'sec-card-529-4', 10, 'لکه نوعی سانسور الگوریتمی است که ادراک جهان کاربر را بدون آگاهی او شکل می‌دهد.  تنظیمات حریم خصوصی شبکه‌های اجتماعی — پیچیده و پر از پیش‌فرض — نشان می‌دهد «انتخاب»ی که به کاربر پیشنهاد می‌شود گاه انتخابی صوری است و قدرت واقعی تصمیم در دست طراح پلتفرم می‌ماند.  ۴. نقدها و چالش‌ها ۱. جبرگرایی زیرساخت: چارچوب گاه می‌تواند به تصویر «داده‌ی همه‌چیز را می‌بیند و هدایت می‌کند» انجام دهد و عاملیت انسان، مقاومت مدنی و امکان‌های نظارت معکوس را دست‌کم بگیرد. ۲. مبهم‌بودن الگوریتم در دو سو: هم شرکت‌ها و الگوریتم‌هایشان شفاف نیستند و هم کاربرانی که چگونه داده‌شان مصرف می‌شود را نمی‌دانند؛ این ابهام از دو سو هم‌زمان آزمون تجربی ادعاها را دشوار می‌کند. ۳.', '0181b0635251fb48bc8aab39586901a32b12cffb206a8807bdb59ba176d79128', 1178, 'ch-doc-card-529-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0181b0635251fb48bc8aab39586901a32b12cffb206a8807bdb59ba176d79128', token_count=1178, vector_point_id='ch-doc-card-529-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-529-11', 'doc-card-529', 'sec-card-529-4', 11, 'را نمی‌دانند؛ این ابهام از دو سو هم‌زمان آزمون تجربی ادعاها را دشوار می‌کند. ۳. جابه‌جایی سریع هدف: حوزه‌ی داده و نظارت دیجیتال با', '4cea2f160edc4195e8fb45809e8680bf7322cc1579f4141080426485c334c4eb', 236, 'ch-doc-card-529-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4cea2f160edc4195e8fb45809e8680bf7322cc1579f4141080426485c334c4eb', token_count=236, vector_point_id='ch-doc-card-529-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-529-12', 'doc-card-529', 'sec-card-529-5', 12, 'تبلیغات هدفمند، رُخِ قابل‌دیدن اقتصاد داده است: کاربری که پس از جست‌وجوی یک محصول، آگهی آن را در شبکه‌ی اجتماعی می‌بیند، در پشت صحنه با سیستمی از پروفایل‌سازی بر پایه‌ی میلیون‌ها تعامل روبه‌روست.  رسوایی‌های سوءاستفاده از داده‌های شبکه‌های اجتماعی در انتخابات (مانند پرونده‌ی کمبریج‌آنالیتیکا) نشان دادند که داده‌های شخصی، هنگامی که تجمیع می‌شوند، به ابزاری برای تأثیر سیاسی خارج از آگاهی و رضایت فرد تبدیل می‌شوند.  سیستم اعتبار اجتماعی در برخی کشورها، منطق نظارت مبتنی بر داده را در حدّ نهایی نشان می‌دهد: امتیازی که بر رفتار شهروند ثبت می‌شود، به دسترسی او به خدمات، سفر و حتی مسکن ربط داده می‌شود.', '3dc96c38b13f32c2b1995dae3348d8b12d3bafe9cce293bdd230368b7078eb69', 1092, 'ch-doc-card-529-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3dc96c38b13f32c2b1995dae3348d8b12d3bafe9cce293bdd230368b7078eb69', token_count=1092, vector_point_id='ch-doc-card-529-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-529-13', 'doc-card-529', 'sec-card-529-5', 13, 'فتار شهروند ثبت می‌شود، به دسترسی او به خدمات، سفر و حتی مسکن ربط داده می‌شود.  «نظارت معکوس» — فیلم‌برداری شهروندان از پلیس و نهادهای قدرتمند با گوشی — نشان می‌دهد که نگاه دیگر یک‌طرفه نیست و ساختارهای نظارتی همواره مورد چالش و بازنشانی هستند.  وقتی فید الگوریتمی به کاربر صرفاَ محتوایی هم‌سو با باورهای پیشینش نشان می‌دهد، نه فقط «شخصی‌سازی» رخ داده، بلکه نوعی سانسور الگوریتمی است که ادراک جهان کاربر را بدون آگاهی او شکل می‌دهد.  تنظیمات حریم خصوصی شبکه‌های اجتماعی — پیچیده و پر از پیش‌فرض — نشان می‌دهد «انتخاب»ی که به کاربر پیشنهاد می‌شود گاه انتخابی صوری است و قدرت واقعی تصمیم در دست طراح پلتفرم می‌ماند.', '3bb22489138dff07609c998d816ad240a46e6cfd7b5a4ebe4dcc0a3caf70e460', 1114, 'ch-doc-card-529-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3bb22489138dff07609c998d816ad240a46e6cfd7b5a4ebe4dcc0a3caf70e460', token_count=1114, vector_point_id='ch-doc-card-529-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-529-14', 'doc-card-529', 'sec-card-529-6', 14, '۱. جبرگرایی زیرساخت: چارچوب گاه می‌تواند به تصویر «داده‌ی همه‌چیز را می‌بیند و هدایت می‌کند» انجام دهد و عاملیت انسان، مقاومت مدنی و امکان‌های نظارت معکوس را دست‌کم بگیرد. ۲. مبهم‌بودن الگوریتم در دو سو: هم شرکت‌ها و الگوریتم‌هایشان شفاف نیستند و هم کاربرانی که چگونه داده‌شان مصرف می‌شود را نمی‌دانند؛ این ابهام از دو سو هم‌زمان آزمون تجربی ادعاها را دشوار می‌کند. ۳. جابه‌جایی سریع هدف: حوزه‌ی داده و نظارت دیجیتال با سرعتی که الگوهای نظارت تغییر می‌کنند، پیش می‌رود و بسیاری از یافته‌ها در نوسانه‌ی بعدی بی‌مورد می‌شوند. ۴.', 'f398ce63199b6479e67d7b985155e60698a50bfc46dc87c835028091d9a42e10', 956, 'ch-doc-card-529-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f398ce63199b6479e67d7b985155e60698a50bfc46dc87c835028091d9a42e10', token_count=956, vector_point_id='ch-doc-card-529-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-529-15', 'doc-card-529', 'sec-card-529-6', 15, 'ر می‌کنند، پیش می‌رود و بسیاری از یافته‌ها در نوسانه‌ی بعدی بی‌مورد می‌شوند. ۴. ناهمگنی «نظارت» در فرهنگ‌ها: مفهوم نظارت و حریم خصوصی در فرهنگ‌ها و نظام‌های حقوقی متفاوت است و مدل‌های توسعه‌یافته در غرب (مانند الگوهای پانوپتیکون) هر جا بدون بازنشانی کاربرد ندارند. ۵. مس', '4aa6d13d77416151b0bfda2b7adad03639b5c4d1946e19469d965084882cc3b9', 490, 'ch-doc-card-529-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4aa6d13d77416151b0bfda2b7adad03639b5c4d1946e19469d965084882cc3b9', token_count=490, vector_point_id='ch-doc-card-529-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-529-16', 'doc-card-529', 'sec-card-529-7', 16, 'ئله‌ی قدرت: تمرکز بر «عادی‌شدن نظارت» می‌تواند قدرت سیاسی و اقتصادی آن‌هایی را که داده را استخراج و از آن سود می‌برند، در تصویر تار بگذارد. ۶. سنجش رفتار: سنجش رفتارهای آنلاین (پذیرش شرایط، اشتراک‌گذاری) به دلیل تغییر مداوم رابط و بستر، قابل‌مقایسه در طول زمان نیست. ۷. پارادوکس رفتار و نگرش: شکاف میان نگرش ابرازشده به حریم خصوصی و رفتار واقعی (پارادوکس حریم خصوصی) می‌تواند نتیجه‌گیری‌های کلی درباره‌ی «ارزش‌های» مخاطب را گمراه‌کننده کند. ۸. غفلت از جنبه‌ی کار: اقتصاد داده بر پایه‌ی کار نامرئی است — تولیدکنندگان محتوا، برچسب‌زنندگان داده، نظارتگران — و چارچوب‌ها این لایه را کمتر پوشش می‌دهند. ۹.', 'cbcd30bf1d0c22b052abf91910125037eb44ac19912a7ec476b3ead3424726e8', 1090, 'ch-doc-card-529-16', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cbcd30bf1d0c22b052abf91910125037eb44ac19912a7ec476b3ead3424726e8', token_count=1090, vector_point_id='ch-doc-card-529-16', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-529-17', 'doc-card-529', 'sec-card-529-7', 17, '، برچسب‌زنندگان داده، نظارتگران — و چارچوب‌ها این لایه را کمتر پوشش می‌دهند. ۹. ریسک تقلیل‌گرایی: تقلیل هر مسئله‌ی اجتماعی به «مسئله‌ی داده» می‌تواند ریشه‌های اقتصادی و سیاسی نابرابری را پنهان کند.', '57783d719f2d993a47b248e60b983d5cf44d6debefc1af56a753a7ac4ae24e1c', 358, 'ch-doc-card-529-17', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='57783d719f2d993a47b248e60b983d5cf44d6debefc1af56a753a7ac4ae24e1c', token_count=358, vector_point_id='ch-doc-card-529-17', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-529-18', 'doc-card-529', 'sec-card-529-10', 18, 'کتاب «جامعه‌ی نظارت» (گوتهام، ۱۹۹۱)؛ کتاب «مردم به‌جای محصول» (گِبر و لوسر، ۲۰۱۷)؛ کتاب «داده‌کشی: اقتصاد داده و قدرت» (شوشان، ۲۰۱۷)؛ استناد مبنا: Zuboff (2019) بر نظارت سرمایه‌داری.', '840da3c01cb66d1dc47e1b4ae58e9e6612928c506f6b419cd6acf5b6ec8d0a6f', 330, 'ch-doc-card-529-18', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='840da3c01cb66d1dc47e1b4ae58e9e6612928c506f6b419cd6acf5b6ec8d0a6f', token_count=330, vector_point_id='ch-doc-card-529-18', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-53-0', 'doc-card-53', NULL, 0, 'حقیقت و عقلانیت از رقابت آزاد عقاید پدید می‌آیند. دولت نباید بر اساس ارزیابی صدق یا خطرناکی عقیده‌ای، بیان را محدود کند، زیرا ایده‌های نادرست در مواجهه با نقد اصلاح می‌شوند و ایده‌های درست با آزمون تقویت می‌گردند. هولمز این ایده را در نظر مخالف خود در ۱۹۱۹ به حقوق آمریکا وارد …', 'def308fb857dce18d5f8fd74d38e61b354a4cf3ba4c432b3022f60bde5cd7dde', 505, 'ch-doc-card-53-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='def308fb857dce18d5f8fd74d38e61b354a4cf3ba4c432b3022f60bde5cd7dde', token_count=505, vector_point_id='ch-doc-card-53-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-53-1', 'doc-card-53', 'sec-card-53-1', 1, 'لیبرالیسم کلاسیک / حقوق اساسی آزادی بیان  حقیقت و عقلانیت از رقابت آزاد عقاید پدید می‌آیند. دولت نباید بر اساس ارزیابی صدق یا خطرناکی عقیده‌ای، بیان را محدود کند، زیرا ایده‌های نادرست در مواجهه با نقد اصلاح می‌شوند و ایده‌های درست با آزمون تقویت می‌گردند. هولمز این ایده را در نظر مخالف خود در ۱۹۱۹ به حقوق آمریکا وارد کرد.', '87fb959be9ae20585db6cc0973b3b3e5b70e396595d2548c95a8bd80e609288f', 587, 'ch-doc-card-53-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='87fb959be9ae20585db6cc0973b3b3e5b70e396595d2548c95a8bd80e609288f', token_count=587, vector_point_id='ch-doc-card-53-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-53-2', 'doc-card-53', 'sec-card-53-2', 2, '۱. بنیان و منطق نظری بازار اندیشه‌ها رسانه را در «چارچوب اخلاقی» و «قانونی» تحلیل می‌کند: «تصویر»، «گزارش» و «بازنمایی»، «مسئولیت» دارند. جان استوارت میل (۱۹۱۹) در این چارچوب، «اخلاق رسانه» را نه «قانون» بلکه «مبارزه» بر سر «ارزش‌ها» تعریف کرد: «مسئولیت» رسانه، فراتر از «قانون»، در «ارزش‌ها» و «نمادها» عمل می‌کند.  بر اساس بازار اندیشه‌ها، «قانون» و «اخلاق» «مرز» دارند: «قانون»، «حداقل» است و «اخلاق»، «حداکثر». جان استوارت میل (۱۹۱۹) در این چارچوب، «قانون رسانه» را «چارچوب» «نظام» خواند: «قانون»، «قواعد بازی» را «تعیین» می‌کند و «اخلاق»، «ارزش‌ها» را «بازتولید» می‌کند.', 'adf3db7b2c4e36c3092e325db2de1848446165d2d0fb3c7e8c739260e74f3f8e', 1045, 'ch-doc-card-53-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='adf3db7b2c4e36c3092e325db2de1848446165d2d0fb3c7e8c739260e74f3f8e', token_count=1045, vector_point_id='ch-doc-card-53-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-53-3', 'doc-card-53', 'sec-card-53-2', 3, 'ون»، «قواعد بازی» را «تعیین» می‌کند و «اخلاق»، «ارزش‌ها» را «بازتولید» می‌کند.  بازار اندیشه‌ها را می‌توان پاسخی به شکاف میان «قانون» (تک‌گویی) و «اخلاق» (چندگویی) دانست: «قانون»، «حداقل» است و «اخلاق»، «بازنگری» مداوم. جان استوارت میل (۱۹۱۹) در این چارچوب، «مسئولیت» رسانه را در برابر «مخاطب» و «جامعه» تعریف کرد — نه صرفاَ «رعایت قانون».  ۲. ساختارهای مفهومی • اخلاق رسانه (Media Ethics): «مسئولیت» رسانه در برابر «مخاطب» و «جامعه»؛ فراتر از «قانون»، در «ارزش‌ها» عمل می‌کند. • قانون رسانه (Media Law): «قواعد» «نظام» درباره‌ی «فعالیت» رسانه: «حداقل» «مجاز» است و «نظم» را «بازتولید» می‌کند.', '2f6c7d5610f887b125c40cda0f90041a3659f4b97c1fcf0d5e2e9a72f5a33f0f', 1078, 'ch-doc-card-53-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2f6c7d5610f887b125c40cda0f90041a3659f4b97c1fcf0d5e2e9a72f5a33f0f', token_count=1078, vector_point_id='ch-doc-card-53-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-53-4', 'doc-card-53', 'sec-card-53-2', 4, 'نظام» درباره‌ی «فعالیت» رسانه: «حداقل» «مجاز» است و «نظم» را «بازتولید» می‌کند. • مسئولیت (Accountability): «پاسخگویی» رسانه به «مخاطب» و «جامعه»؛ «مسئولیت»، «بازتولید» روزانه نیاز دارد. • حریم خصوصی (Privacy): «حق» فرد بر «کنترل» اطلاعات شخصی؛ در «اقتصاد داده»، «داده» شخصی «سرمایه» است. • آزادی بیان (Freedom of Expression): «حق» فرد و «رسانه» بر «گفتن»؛ «آزادی» و «مسئولیت» در «موازنه»‌اند. • کد اخلاقی (Ethical Code): «اصول» «حرفه‌ای» رسانه: «دقت»، «استقلال»، «', 'c96886c816045c527bb197a102ac10a5b46e00792fac24f9081d79bdab924be9', 845, 'ch-doc-card-53-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c96886c816045c527bb197a102ac10a5b46e00792fac24f9081d79bdab924be9', token_count=845, vector_point_id='ch-doc-card-53-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-53-5', 'doc-card-53', 'sec-card-53-3', 5, 'رقابت عقاید؛ آزمون عمومی حقیقت؛ آزادی بیان؛ خطر روشن و حاضر (Clear and Present Danger)؛ تنوع منابع؛ تمایز بین دولت و جامعه.', '52acadb5a643b3093710e7cbca990906c3d3364c3bc9ec0d48a468cecbf82ad6', 223, 'ch-doc-card-53-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='52acadb5a643b3093710e7cbca990906c3d3364c3bc9ec0d48a468cecbf82ad6', token_count=223, vector_point_id='ch-doc-card-53-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-53-6', 'doc-card-53', 'sec-card-53-4', 6, 'پاسخگویی»، «عدالت»؛ «کد»، «چارچوب» «اخلاق» است. • نظارت اخلاقی (Ethical Oversight): «نهادها» و «نظم‌ها» که «اخلاق» را «بازتولید» می‌کنند: «کمیته‌های» اخلاق، «نظم‌های» خودتنظیمی. • آسیب به مخاطب (Harm to Audience): «تصویر» و «گزارش» می‌تواند «آسیب» بزند: «حداقل آسیب»، «اصل» «اخلاق» است.  ۳. نمونه‌های تحلیلی «اخلاق رسانه» در عمل: وقتی «رسانه‌ای» «خبر» «غیرواقعی» را «گزارش» می‌کند، «مسئولیت» دارد: «اعتبار» از «دقت» ساخته می‌شود و «خطا»، «اعتبار» را «خورده» می‌کند.  «قانون رسانه» در عمل: «قانون» «حق تکثیر» و «حریم خصوصی»، «حداقل» «مجاز» است: «رعایت» «قانون»، «مجاز» است اما «کافی» نیست.', 'fdc77705d0203c99637faa0e4d9a9371eb4c104adb45b9f40b817c83e61a49ed', 1069, 'ch-doc-card-53-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fdc77705d0203c99637faa0e4d9a9371eb4c104adb45b9f40b817c83e61a49ed', token_count=1069, vector_point_id='ch-doc-card-53-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-53-7', 'doc-card-53', 'sec-card-53-4', 7, '«حریم خصوصی»، «حداقل» «مجاز» است: «رعایت» «قانون»، «مجاز» است اما «کافی» نیست.  «حریم خصوصی» در «عصر دیجیتال»: «داده» شخصی «سرمایه» است و «نظارت» بر آن، «حاکمیت» است: «حق» فرد بر «کنترل» «داده»، «چالش» اصلی «عصر دیجیتال» است.  «آزادی بیان» و «مسئولیت»: «آزادی» «گفتن» و «مسئولیت» «گفتن» در «موازنه»‌اند: «گفتن» بدون «مسئولیت»، «آسیب» است.  «کد اخلاقی» در عمل: «کد» «حرفه‌ای» (دقت، استقلال، پاسخگویی) «چارچوب» «اخلاق» است: «رعایت» «کد»، «مجاز» است اما «کافی» نیست: «اخلاق»، «بازنگری» مداوم است.  «آسیب به مخاطب» در عمل: «تصویر» از «ضحايا» و «فاجعه‌ها»، «آسیب» «دوباره» است: «حداقل آسیب»، «اصل» «اخلاق» است و «تصویر»، «مسئولیت» دارد.  ۴. نقدها و چالش‌ها ۱.', '35cbc51af4e67818699ae73b86e1834cbbbcfe6b287fcfe26b119332977fbf51', 1189, 'ch-doc-card-53-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='35cbc51af4e67818699ae73b86e1834cbbbcfe6b287fcfe26b119332977fbf51', token_count=1189, vector_point_id='ch-doc-card-53-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-53-8', 'doc-card-53', 'sec-card-53-4', 8, 'داقل آسیب»، «اصل» «اخلاق» است و «تصویر»، «مسئولیت» دارد.  ۴. نقدها و چالش‌ها ۱. «اخلاق» به «کد» تقلیل می‌یابد: «رعایت» «کد»، «مجاز» است اما «کافی» نیست: «اخلاق»، «بازنگری» مداوم است و «کد»، «ثابت» است. ۲. «قانون» و «اخلاق» مرز «کمرنگ» دارند: «قانون»، «حداقل» است و «اخلاق»، «حداکثر» است: «مرز» بین آن‌ها «بازتعریف» لازم دارد. ۳. «مسئولیت» در «عصر دیجیتال» «بازتعریف» می‌شود: «مسئولیت» «پلتفرم', '88865ec6f8143833a62fbd968b2bd47befb46ccecaa946433f2c52d6e3573526', 712, 'ch-doc-card-53-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='88865ec6f8143833a62fbd968b2bd47befb46ccecaa946433f2c52d6e3573526', token_count=712, vector_point_id='ch-doc-card-53-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-53-9', 'doc-card-53', 'sec-card-53-5', 9, 'بحث درباره اینکه آیا پلتفرم‌ها باید اطلاعات نادرست را حذف کنند یا با برچسب‌گذاری و نقد عمومی مواجه سازند. مدل بازار اندیشه‌ها از برچسب‌گذاری و تنوع پاسخ‌ها دفاع می‌کند.', 'bf4dd263e787db6d668ca6c6137b3d356ffe938b52b9d6b8da19cf8cd69dc492', 305, 'ch-doc-card-53-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bf4dd263e787db6d668ca6c6137b3d356ffe938b52b9d6b8da19cf8cd69dc492', token_count=305, vector_point_id='ch-doc-card-53-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-53-10', 'doc-card-53', 'sec-card-53-6', 10, 'فرض «بازار آزاد» در عمل با ناترازی قدرت، انحصار پلتفرمی و الگوریتم‌های هدایت‌کننده توجه همراه نیست. اطلاعات نادرست ممکن است سریع‌تر از حقیقت گسترش یابد و اصلاح آن‌ها پس از انتشار هزینه‌بر باشد.', '9ee08cb62a7456f4d5b81d6bbfaa8047525f28fd176ee522ce25b93b96c7f37d', 350, 'ch-doc-card-53-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9ee08cb62a7456f4d5b81d6bbfaa8047525f28fd176ee522ce25b93b96c7f37d', token_count=350, vector_point_id='ch-doc-card-53-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-53-11', 'doc-card-53', 'sec-card-53-10', 11, 'کتاب «اخلاق رسانه» (کوهن، ۱۹۸۶)؛ کتاب «قانون رسانه و ارتباطات» (براون و همکاران، ۱۹۹۸)؛ کتاب «حریم خصوصی در عصر دیجیتال» (وینایم، ۲۰۰۳)؛ کتاب «آزادی بیان و مسئولیت» (استوارت، ۱۹۹۵).', 'e807fd9e6edb686407c85177e6708434e2a676cf2cce49373e6c687ad34253ba', 329, 'ch-doc-card-53-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e807fd9e6edb686407c85177e6708434e2a676cf2cce49373e6c687ad34253ba', token_count=329, vector_point_id='ch-doc-card-53-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-530-0', 'doc-card-530', NULL, 0, 'ادعای محوری اطلاعات نادرست/جعلی و پست-حقیقت این است که در جامعه‌ی اطلاعاتی معاصر، داده کالای محوری و الگوریتم سازوکار حکمرانی است. رالف کیز (۲۰۰۴) تحلیل کرد که چگونه استخراج، پروفایل‌سازی و تبادل داده‌های شخصی، رابطه‌ی کاربر، پلتفرم و دولت را بازنشانی می‌کند. در این چارچوب …', 'b1358c29efd2b8f4cd3efca11471c18f76c8b14c31e5705bf87bc66d3f2b6a63', 499, 'ch-doc-card-530-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b1358c29efd2b8f4cd3efca11471c18f76c8b14c31e5705bf87bc66d3f2b6a63', token_count=499, vector_point_id='ch-doc-card-530-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-530-1', 'doc-card-530', 'sec-card-530-1', 1, 'داده، الگوریتم، نظارت و حریم خصوصی  ادعای محوری اطلاعات نادرست/جعلی و پست-حقیقت این است که در جامعه‌ی اطلاعاتی معاصر، داده کالای محوری و الگوریتم سازوکار حکمرانی است. رالف کیز (۲۰۰۴) تحلیل کرد که چگونه استخراج، پروفایل‌سازی و تبادل داده‌های شخصی، رابطه‌ی کاربر، پلتفرم و دولت را بازنشانی می‌کند. در این چارچوب، رسانه‌ی امروز نه به‌مثابه جریان پیام، بلکه به‌مثابه جریان اطلاعات‌کشی خوانده می‌شود که در آن رفتار کاربر ماده‌ی خام بازار است.  بر اساس اطلاعات نادرست/جعلی و پست-حقیقت، نظارت از بین نرفته، بلکه فرم عوض کرده است: از نظارت متمرکز و گزینشی دولت به نظارت پراکنده، پیوسته و مبتنی بر داده که در آن خودِ کاربر ردّ تولید می‌کند.', 'fd9d7aa887bf5e73c65d579b222ca455191adecef1f3d410ffdbb6810ea4d47e', 1147, 'ch-doc-card-530-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fd9d7aa887bf5e73c65d579b222ca455191adecef1f3d410ffdbb6810ea4d47e', token_count=1147, vector_point_id='ch-doc-card-530-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-530-2', 'doc-card-530', 'sec-card-530-1', 2, 'به نظارت پراکنده، پیوسته و مبتنی بر داده که در آن خودِ کاربر ردّ تولید می‌کند. رالف کیز (۲۰۰۴) نشان داد که منطق «نگاه» وارد طراحی پلتفرم‌های دیجیتال شده و عادی‌شدن نظارت، خودرفتار و خودِ مفهوم حریم خصوصی را دگرگون کرده است.  اطلاعات نادرست/جعلی و پست-حقیقت الگوریتم‌ها را میانجی‌های مبهمی می‌داند که تعیین می‌کنند چه چیزی دیده شود و چه چیزی پنهان بماند، چه چیزی اولویت بگیرد و چه چیزی دفن شود. رالف کیز (۲۰۰۴) تأکید کرد که تصمیمات الگوریتمی — از فید اخبار تا درخواست وام — در عمل تصمیماتی «اجتماعی»‌اند که در کد نوشته شده‌اند و فقدان شفافیت و پاسخگویی درباره‌ی آن‌ها، فرمی تازه از قدرت بی‌پاسخ‌ساز می‌سازد. مطالعه‌ی این سازوکارها بنابراین از مطالعه‌ی قدرت و عدالت جدا نیست.', 'beb8659c1a6ea699ce006febd4ffdb757b2e5bd29f296b2f4b11c9216e4c8f70', 1223, 'ch-doc-card-530-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='beb8659c1a6ea699ce006febd4ffdb757b2e5bd29f296b2f4b11c9216e4c8f70', token_count=1223, vector_point_id='ch-doc-card-530-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-530-3', 'doc-card-530', 'sec-card-530-2', 3, '۱. بنیان و منطق نظری ادعای محوری اطلاعات نادرست/جعلی و پست-حقیقت این است که در جامعه‌ی اطلاعاتی معاصر، داده کالای محوری و الگوریتم سازوکار حکمرانی است. رالف کیز (۲۰۰۴) تحلیل کرد که چگونه استخراج، پروفایل‌سازی و تبادل داده‌های شخصی، رابطه‌ی کاربر، پلتفرم و دولت را بازنشانی می‌کند. در این چارچوب، رسانه‌ی امروز نه به‌مثابه جریان پیام، بلکه به‌مثابه جریان اطلاعات‌کشی خوانده می‌شود که در آن رفتار کاربر ماده‌ی خام بازار است.  بر اساس اطلاعات نادرست/جعلی و پست-حقیقت، نظارت از بین نرفته، بلکه فرم عوض کرده است: از نظارت متمرکز و گزینشی دولت به نظارت پراکنده، پیوسته و مبتنی بر داده که در آن خودِ کاربر ردّ تولید می‌کند.', 'da1c45038d606c5e7d400b40ed9544ebcc658253ff97e902532f60eb6a2fafc6', 1120, 'ch-doc-card-530-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='da1c45038d606c5e7d400b40ed9544ebcc658253ff97e902532f60eb6a2fafc6', token_count=1120, vector_point_id='ch-doc-card-530-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-530-4', 'doc-card-530', 'sec-card-530-2', 4, 'به نظارت پراکنده، پیوسته و مبتنی بر داده که در آن خودِ کاربر ردّ تولید می‌کند. رالف کیز (۲۰۰۴) نشان داد که منطق «نگاه» وارد طراحی پلتفرم‌های دیجیتال شده و عادی‌شدن نظارت، خودرفتار و خودِ مفهوم حریم خصوصی را دگرگون کرده است.  اطلاعات نادرست/جعلی و پست-حقیقت الگوریتم‌ها را میانجی‌های مبهمی می‌داند که تعیین می‌کنند چه چیزی دیده شود و چه چیزی پنهان بماند، چه چیزی اولویت بگیرد و چه چیزی دفن شود. رالف کیز (۲۰۰۴) تأکید کرد که تصمیمات الگوریتمی — از فید اخبار تا درخواست وام — در عمل تصمیماتی «اجتماعی»‌اند که در کد نوشته شده‌اند و فقدان شفافیت و پاسخگویی درباره‌ی آن‌ها، فرمی تازه از قدرت بی‌پاسخ‌ساز می‌سازد. مطالعه‌ی این سازوکارها بنابراین از مطالعه‌ی قدرت و عدالت جدا نیست.  ۲.', 'a651ab338366e546e02bad64b39fbef0da2ea914c72da4820913709e4dcf633e', 1230, 'ch-doc-card-530-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a651ab338366e546e02bad64b39fbef0da2ea914c72da4820913709e4dcf633e', token_count=1230, vector_point_id='ch-doc-card-530-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-530-5', 'doc-card-530', 'sec-card-530-2', 5, 'می‌سازد. مطالعه‌ی این سازوکارها بنابراین از مطالعه‌ی قدرت و عدالت جدا نیست.  ۲. ساختارهای مفهومی • داده‌کشی (Data Extraction): جمع‌آوری سیستماتیک داده‌های رفتاری کاربران توسط پلتفرم‌ها و دولت. • پروفایل‌سازی (Profiling): ساختن پروفایل‌های رفتاری و روان‌شناختی از داده برای پیش‌بینی و هدایت رفتار. • مبهم‌بودن الگوریتم (Algorithmic Opacity): عدم دسترسی کاربر و ناظر به منطق و تصمیمات الگوریتم. • حریم خصوصی (Privacy): حق کنترل بر جریان اطلاعات شخصی و شرایط حفاظت از آن در عصر دیجیتال. • داده‌ای‌شدن (Datification): فرایند تبدیل هر بُعد از زندگی اجتماعی به داده. • ردّ دیجیتال (Digital Footprint): اثرهای باقی‌مانده‌ی رفتار فرد در فضاهای دیجیتال و ماندگاری آن‌ها. •', '3e57678ed3386811841147c100ee51b3104321708a19e8f1f3521341f088ce1f', 1205, 'ch-doc-card-530-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3e57678ed3386811841147c100ee51b3104321708a19e8f1f3521341f088ce1f', token_count=1205, vector_point_id='ch-doc-card-530-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-530-6', 'doc-card-530', 'sec-card-530-3', 6, '• داده‌کشی (Data Extraction): جمع‌آوری سیستماتیک داده‌های رفتاری کاربران توسط پلتفرم‌ها و دولت. • پروفایل‌سازی (Profiling): ساختن پروفایل‌های رفتاری و روان‌شناختی از داده برای پیش‌بینی و هدایت رفتار. • مبهم‌بودن الگوریتم (Algorithmic Opacity): عدم دسترسی کاربر و ناظر به منطق و تصمیمات الگوریتم. • حریم خصوصی (Privacy): حق کنترل بر جریان اطلاعات شخصی و شرایط حفاظت از آن در عصر دیجیتال. • داده‌ای‌شدن (Datification): فرایند تبدیل هر بُعد از زندگی اجتماعی به داده. • ردّ دیجیتال (Digital Footprint): اثرهای باقی‌مانده‌ی رفتار فرد در فضاهای دیجیتال و ماندگاری آن‌ها. • پانوپتیکون (Panopticon): مدل فوکویی نظارتی که در آن احتمال دیده‌شدن، رفتار را تأمین می‌کند.', '8edb1c82060510576a0f6a7ee2c0631126eb7787f15c81994d3654d1b8502b6d', 1196, 'ch-doc-card-530-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8edb1c82060510576a0f6a7ee2c0631126eb7787f15c81994d3654d1b8502b6d', token_count=1196, vector_point_id='ch-doc-card-530-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-530-7', 'doc-card-530', 'sec-card-530-3', 7, 'Panopticon): مدل فوکویی نظارتی که در آن احتمال دیده‌شدن، رفتار را تأمین می‌کند. • پارادوکس حریم خصوصی (Privacy Paradox): شکاف میان نگرش ابرازشده به حریم خصوصی و رفتار واقعی اشتراک‌گذاری داده.', '8e98a3b52b466d5c84bd6cf264144211ad418393f64e5c4b503958751404e44f', 347, 'ch-doc-card-530-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8e98a3b52b466d5c84bd6cf264144211ad418393f64e5c4b503958751404e44f', token_count=347, vector_point_id='ch-doc-card-530-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-530-8', 'doc-card-530', 'sec-card-530-4', 8, 'پانوپتیکون (Panopticon): مدل فوکویی نظارتی که در آن احتمال دیده‌شدن، رفتار را تأمین می‌کند. • پارادوکس حریم خصوصی (Privacy Paradox): شکاف میان نگرش ابرازشده به حریم خصوصی و رفتار واقعی اشتراک‌گذاری داده.  ۳. نمونه‌های تحلیلی تبلیغات هدفمند، رُخِ قابل‌دیدن اقتصاد داده است: کاربری که پس از جست‌وجوی یک محصول، آگهی آن را در شبکه‌ی اجتماعی می‌بیند، در پشت صحنه با سیستمی از پروفایل‌سازی بر پایه‌ی میلیون‌ها تعامل روبه‌روست.  رسوایی‌های سوءاستفاده از داده‌های شبکه‌های اجتماعی در انتخابات (مانند پرونده‌ی کمبریج‌آنالیتیکا) نشان دادند که داده‌های شخصی، هنگامی که تجمیع می‌شوند، به ابزاری برای تأثیر سیاسی خارج از آگاهی و رضایت فرد تبدیل می‌شوند.', '7a362477fef1459ea056798cc027daa2687d62ee379bed4eccb8e8b5d2430f01', 1163, 'ch-doc-card-530-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7a362477fef1459ea056798cc027daa2687d62ee379bed4eccb8e8b5d2430f01', token_count=1163, vector_point_id='ch-doc-card-530-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-530-9', 'doc-card-530', 'sec-card-530-4', 9, 'ع می‌شوند، به ابزاری برای تأثیر سیاسی خارج از آگاهی و رضایت فرد تبدیل می‌شوند.  سیستم اعتبار اجتماعی در برخی کشورها، منطق نظارت مبتنی بر داده را در حدّ نهایی نشان می‌دهد: امتیازی که بر رفتار شهروند ثبت می‌شود، به دسترسی او به خدمات، سفر و حتی مسکن ربط داده می‌شود.  «نظارت معکوس» — فیلم‌برداری شهروندان از پلیس و نهادهای قدرتمند با گوشی — نشان می‌دهد که نگاه دیگر یک‌طرفه نیست و ساختارهای نظارتی همواره مورد چالش و بازنشانی هستند.  وقتی فید الگوریتمی به کاربر صرفاَ محتوایی هم‌سو با باورهای پیشینش نشان می‌دهد، نه فقط «شخصی‌سازی» رخ داده، بلکه نوعی سانسور الگوریتمی است که ادراک جهان کاربر را بدون آگاهی او شکل می‌دهد.', '8694ba72177c974c35f1980d8fa64c6c9e99d13422e9e76a4ac891bb5cd22053', 1123, 'ch-doc-card-530-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8694ba72177c974c35f1980d8fa64c6c9e99d13422e9e76a4ac891bb5cd22053', token_count=1123, vector_point_id='ch-doc-card-530-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-530-10', 'doc-card-530', 'sec-card-530-4', 10, 'لکه نوعی سانسور الگوریتمی است که ادراک جهان کاربر را بدون آگاهی او شکل می‌دهد.  تنظیمات حریم خصوصی شبکه‌های اجتماعی — پیچیده و پر از پیش‌فرض — نشان می‌دهد «انتخاب»ی که به کاربر پیشنهاد می‌شود گاه انتخابی صوری است و قدرت واقعی تصمیم در دست طراح پلتفرم می‌ماند.  ۴. نقدها و چالش‌ها ۱. جبرگرایی زیرساخت: چارچوب گاه می‌تواند به تصویر «داده‌ی همه‌چیز را می‌بیند و هدایت می‌کند» انجام دهد و عاملیت انسان، مقاومت مدنی و امکان‌های نظارت معکوس را دست‌کم بگیرد. ۲. مبهم‌بودن الگوریتم در دو سو: هم شرکت‌ها و الگوریتم‌هایشان شفاف نیستند و هم کاربرانی که چگونه داده‌شان مصرف می‌شود را نمی‌دانند؛ این ابهام از دو سو هم‌زمان آزمون تجربی ادعاها را دشوار می‌کند. ۳.', '0181b0635251fb48bc8aab39586901a32b12cffb206a8807bdb59ba176d79128', 1178, 'ch-doc-card-530-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0181b0635251fb48bc8aab39586901a32b12cffb206a8807bdb59ba176d79128', token_count=1178, vector_point_id='ch-doc-card-530-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-530-11', 'doc-card-530', 'sec-card-530-4', 11, 'را نمی‌دانند؛ این ابهام از دو سو هم‌زمان آزمون تجربی ادعاها را دشوار می‌کند. ۳. جابه‌جایی سریع هدف: حوزه‌ی داده و نظارت دیجیتال با', '4cea2f160edc4195e8fb45809e8680bf7322cc1579f4141080426485c334c4eb', 236, 'ch-doc-card-530-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4cea2f160edc4195e8fb45809e8680bf7322cc1579f4141080426485c334c4eb', token_count=236, vector_point_id='ch-doc-card-530-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-530-12', 'doc-card-530', 'sec-card-530-5', 12, 'تبلیغات هدفمند، رُخِ قابل‌دیدن اقتصاد داده است: کاربری که پس از جست‌وجوی یک محصول، آگهی آن را در شبکه‌ی اجتماعی می‌بیند، در پشت صحنه با سیستمی از پروفایل‌سازی بر پایه‌ی میلیون‌ها تعامل روبه‌روست.  رسوایی‌های سوءاستفاده از داده‌های شبکه‌های اجتماعی در انتخابات (مانند پرونده‌ی کمبریج‌آنالیتیکا) نشان دادند که داده‌های شخصی، هنگامی که تجمیع می‌شوند، به ابزاری برای تأثیر سیاسی خارج از آگاهی و رضایت فرد تبدیل می‌شوند.  سیستم اعتبار اجتماعی در برخی کشورها، منطق نظارت مبتنی بر داده را در حدّ نهایی نشان می‌دهد: امتیازی که بر رفتار شهروند ثبت می‌شود، به دسترسی او به خدمات، سفر و حتی مسکن ربط داده می‌شود.', '3dc96c38b13f32c2b1995dae3348d8b12d3bafe9cce293bdd230368b7078eb69', 1092, 'ch-doc-card-530-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3dc96c38b13f32c2b1995dae3348d8b12d3bafe9cce293bdd230368b7078eb69', token_count=1092, vector_point_id='ch-doc-card-530-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-530-13', 'doc-card-530', 'sec-card-530-5', 13, 'فتار شهروند ثبت می‌شود، به دسترسی او به خدمات، سفر و حتی مسکن ربط داده می‌شود.  «نظارت معکوس» — فیلم‌برداری شهروندان از پلیس و نهادهای قدرتمند با گوشی — نشان می‌دهد که نگاه دیگر یک‌طرفه نیست و ساختارهای نظارتی همواره مورد چالش و بازنشانی هستند.  وقتی فید الگوریتمی به کاربر صرفاَ محتوایی هم‌سو با باورهای پیشینش نشان می‌دهد، نه فقط «شخصی‌سازی» رخ داده، بلکه نوعی سانسور الگوریتمی است که ادراک جهان کاربر را بدون آگاهی او شکل می‌دهد.  تنظیمات حریم خصوصی شبکه‌های اجتماعی — پیچیده و پر از پیش‌فرض — نشان می‌دهد «انتخاب»ی که به کاربر پیشنهاد می‌شود گاه انتخابی صوری است و قدرت واقعی تصمیم در دست طراح پلتفرم می‌ماند.', '3bb22489138dff07609c998d816ad240a46e6cfd7b5a4ebe4dcc0a3caf70e460', 1114, 'ch-doc-card-530-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3bb22489138dff07609c998d816ad240a46e6cfd7b5a4ebe4dcc0a3caf70e460', token_count=1114, vector_point_id='ch-doc-card-530-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-530-14', 'doc-card-530', 'sec-card-530-6', 14, '۱. جبرگرایی زیرساخت: چارچوب گاه می‌تواند به تصویر «داده‌ی همه‌چیز را می‌بیند و هدایت می‌کند» انجام دهد و عاملیت انسان، مقاومت مدنی و امکان‌های نظارت معکوس را دست‌کم بگیرد. ۲. مبهم‌بودن الگوریتم در دو سو: هم شرکت‌ها و الگوریتم‌هایشان شفاف نیستند و هم کاربرانی که چگونه داده‌شان مصرف می‌شود را نمی‌دانند؛ این ابهام از دو سو هم‌زمان آزمون تجربی ادعاها را دشوار می‌کند. ۳. جابه‌جایی سریع هدف: حوزه‌ی داده و نظارت دیجیتال با سرعتی که الگوهای نظارت تغییر می‌کنند، پیش می‌رود و بسیاری از یافته‌ها در نوسانه‌ی بعدی بی‌مورد می‌شوند. ۴.', 'f398ce63199b6479e67d7b985155e60698a50bfc46dc87c835028091d9a42e10', 956, 'ch-doc-card-530-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f398ce63199b6479e67d7b985155e60698a50bfc46dc87c835028091d9a42e10', token_count=956, vector_point_id='ch-doc-card-530-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-530-15', 'doc-card-530', 'sec-card-530-6', 15, 'ر می‌کنند، پیش می‌رود و بسیاری از یافته‌ها در نوسانه‌ی بعدی بی‌مورد می‌شوند. ۴. ناهمگنی «نظارت» در فرهنگ‌ها: مفهوم نظارت و حریم خصوصی در فرهنگ‌ها و نظام‌های حقوقی متفاوت است و مدل‌های توسعه‌یافته در غرب (مانند الگوهای پانوپتیکون) هر جا بدون بازنشانی کاربرد ندارند. ۵. مس', '4aa6d13d77416151b0bfda2b7adad03639b5c4d1946e19469d965084882cc3b9', 490, 'ch-doc-card-530-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4aa6d13d77416151b0bfda2b7adad03639b5c4d1946e19469d965084882cc3b9', token_count=490, vector_point_id='ch-doc-card-530-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-530-16', 'doc-card-530', 'sec-card-530-7', 16, 'ئله‌ی قدرت: تمرکز بر «عادی‌شدن نظارت» می‌تواند قدرت سیاسی و اقتصادی آن‌هایی را که داده را استخراج و از آن سود می‌برند، در تصویر تار بگذارد. ۶. سنجش رفتار: سنجش رفتارهای آنلاین (پذیرش شرایط، اشتراک‌گذاری) به دلیل تغییر مداوم رابط و بستر، قابل‌مقایسه در طول زمان نیست. ۷. پارادوکس رفتار و نگرش: شکاف میان نگرش ابرازشده به حریم خصوصی و رفتار واقعی (پارادوکس حریم خصوصی) می‌تواند نتیجه‌گیری‌های کلی درباره‌ی «ارزش‌های» مخاطب را گمراه‌کننده کند. ۸. غفلت از جنبه‌ی کار: اقتصاد داده بر پایه‌ی کار نامرئی است — تولیدکنندگان محتوا، برچسب‌زنندگان داده، نظارتگران — و چارچوب‌ها این لایه را کمتر پوشش می‌دهند. ۹.', 'cbcd30bf1d0c22b052abf91910125037eb44ac19912a7ec476b3ead3424726e8', 1090, 'ch-doc-card-530-16', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cbcd30bf1d0c22b052abf91910125037eb44ac19912a7ec476b3ead3424726e8', token_count=1090, vector_point_id='ch-doc-card-530-16', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-530-17', 'doc-card-530', 'sec-card-530-7', 17, '، برچسب‌زنندگان داده، نظارتگران — و چارچوب‌ها این لایه را کمتر پوشش می‌دهند. ۹. ریسک تقلیل‌گرایی: تقلیل هر مسئله‌ی اجتماعی به «مسئله‌ی داده» می‌تواند ریشه‌های اقتصادی و سیاسی نابرابری را پنهان کند.', '57783d719f2d993a47b248e60b983d5cf44d6debefc1af56a753a7ac4ae24e1c', 358, 'ch-doc-card-530-17', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='57783d719f2d993a47b248e60b983d5cf44d6debefc1af56a753a7ac4ae24e1c', token_count=358, vector_point_id='ch-doc-card-530-17', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-530-18', 'doc-card-530', 'sec-card-530-10', 18, 'کتاب «جامعه‌ی نظارت» (گوتهام، ۱۹۹۱)؛ کتاب «مردم به‌جای محصول» (گِبر و لوسر، ۲۰۱۷)؛ کتاب «داده‌کشی: اقتصاد داده و قدرت» (شوشان، ۲۰۱۷)؛ استناد مبنا: Zuboff (2019) بر نظارت سرمایه‌داری.', '840da3c01cb66d1dc47e1b4ae58e9e6612928c506f6b419cd6acf5b6ec8d0a6f', 330, 'ch-doc-card-530-18', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='840da3c01cb66d1dc47e1b4ae58e9e6612928c506f6b419cd6acf5b6ec8d0a6f', token_count=330, vector_point_id='ch-doc-card-530-18', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-531-0', 'doc-card-531', NULL, 0, 'مدل هوش مصنوعی مولد در رسانه اینترنت و پلتفرم‌های دیجیتال را محیط رسانه‌ای تازه‌ای می‌داند که منطق ارتباط، تولید و تبادل را دگرگون کرده است. نظریه‌پردازان (۲۰۲۰) استدلال کرد که در عصر شبکه، واحد تحلیل دیگر پیام یا کانال نیست، بلکه پلتفرم است: زیرساخت فنی-اقتصادی که کاربران …', 'ec01590f5f7b86a954b0c1515fdba0a013399ce2cb36e77ad2f805193f5c1fde', 499, 'ch-doc-card-531-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ec01590f5f7b86a954b0c1515fdba0a013399ce2cb36e77ad2f805193f5c1fde', token_count=499, vector_point_id='ch-doc-card-531-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-531-1', 'doc-card-531', 'sec-card-531-1', 1, 'اینترنت، پلتفرم و فناوری  مدل هوش مصنوعی مولد در رسانه اینترنت و پلتفرم‌های دیجیتال را محیط رسانه‌ای تازه‌ای می‌داند که منطق ارتباط، تولید و تبادل را دگرگون کرده است. نظریه‌پردازان (۲۰۲۰) استدلال کرد که در عصر شبکه، واحد تحلیل دیگر پیام یا کانال نیست، بلکه پلتفرم است: زیرساخت فنی-اقتصادی که کاربران، محتوا و سرمایه را به هم وصل می‌کند. در این چارچوب، خودِ طراحی زیرساخت — پروتکل، کارکرد و الگوریتم — رفتار اجتماعی را شکل می‌دهد، نه صرفاَ محتوای عبوری.  بر اساس مدل هوش مصنوعی مولد در رسانه، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است.', 'e79438dedab5ad2841d38923c33b238e20701ca341c9d72209cc334ecc9d20bc', 1027, 'ch-doc-card-531-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e79438dedab5ad2841d38923c33b238e20701ca341c9d72209cc334ecc9d20bc', token_count=1027, vector_point_id='ch-doc-card-531-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-531-2', 'doc-card-531', 'sec-card-531-1', 2, 'سانه، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است. نظریه‌پردازان (۲۰۲۰) فرایندی را تحلیل کرد که فناوری تازه، از ورود و پذیرش، به زندگی روزمره می‌آمیزد، نقش‌ها و روابط را بازنشانی می‌کند و سرانجام «طبیعی» به نظر می‌رسد. ادعای محوری این است که هر نوسازی فناورانه با یک بازنشانی نظم اجتماعی همراه است و مطالعه‌ی فناوری را نمی‌توان از مطالعه‌ی قدرت، اقتصاد و فرهنگ جدا کرد.  مدل هوش مصنوعی مولد در رسانه پلتفرم را بوم‌زمینه‌ای چندوجهی می‌داند که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند.', '347f5a2fa7537cd00347c29d9b0b8f8df60b73afcf0062e3bdb8efc617eb5f48', 990, 'ch-doc-card-531-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='347f5a2fa7537cd00347c29d9b0b8f8df60b73afcf0062e3bdb8efc617eb5f48', token_count=990, vector_point_id='ch-doc-card-531-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-531-3', 'doc-card-531', 'sec-card-531-1', 3, 'د که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند. نظریه‌پردازان (۲۰۲۰) تأکید کرد که پلتفرم هم‌زمان فناوری، بازار و شیوه‌ی حکمرانی است و قدرت آن از کنترل بر «قوانین بازی» — چشم‌اندازی، دسترسی و معامله — می‌آید. این رویکرد، تحلیل پلتفرم را در تقاطع جامعه‌شناسی فناوری، اقتصاد و حکمرانی جای می‌دهد.', '4ea0ad0687b7f5dc79a4f1850eefda1900cbc0cb903bf271e6d374788f737d96', 590, 'ch-doc-card-531-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4ea0ad0687b7f5dc79a4f1850eefda1900cbc0cb903bf271e6d374788f737d96', token_count=590, vector_point_id='ch-doc-card-531-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-531-4', 'doc-card-531', 'sec-card-531-2', 4, '۱. بنیان و منطق نظری مدل هوش مصنوعی مولد در رسانه اینترنت و پلتفرم‌های دیجیتال را محیط رسانه‌ای تازه‌ای می‌داند که منطق ارتباط، تولید و تبادل را دگرگون کرده است. نظریه‌پردازان (۲۰۲۰) استدلال کرد که در عصر شبکه، واحد تحلیل دیگر پیام یا کانال نیست، بلکه پلتفرم است: زیرساخت فنی-اقتصادی که کاربران، محتوا و سرمایه را به هم وصل می‌کند. در این چارچوب، خودِ طراحی زیرساخت — پروتکل، کارکرد و الگوریتم — رفتار اجتماعی را شکل می‌دهد، نه صرفاَ محتوای عبوری.  بر اساس مدل هوش مصنوعی مولد در رسانه، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است.', '0f23d32aaecef013d871635eee26cabae0bdb92ce994ed5ed88489194565dca8', 1018, 'ch-doc-card-531-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0f23d32aaecef013d871635eee26cabae0bdb92ce994ed5ed88489194565dca8', token_count=1018, vector_point_id='ch-doc-card-531-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-531-5', 'doc-card-531', 'sec-card-531-2', 5, 'سانه، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است. نظریه‌پردازان (۲۰۲۰) فرایندی را تحلیل کرد که فناوری تازه، از ورود و پذیرش، به زندگی روزمره می‌آمیزد، نقش‌ها و روابط را بازنشانی می‌کند و سرانجام «طبیعی» به نظر می‌رسد. ادعای محوری این است که هر نوسازی فناورانه با یک بازنشانی نظم اجتماعی همراه است و مطالعه‌ی فناوری را نمی‌توان از مطالعه‌ی قدرت، اقتصاد و فرهنگ جدا کرد.  مدل هوش مصنوعی مولد در رسانه پلتفرم را بوم‌زمینه‌ای چندوجهی می‌داند که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند.', '347f5a2fa7537cd00347c29d9b0b8f8df60b73afcf0062e3bdb8efc617eb5f48', 990, 'ch-doc-card-531-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='347f5a2fa7537cd00347c29d9b0b8f8df60b73afcf0062e3bdb8efc617eb5f48', token_count=990, vector_point_id='ch-doc-card-531-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-531-6', 'doc-card-531', 'sec-card-531-2', 6, 'د که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند. نظریه‌پردازان (۲۰۲۰) تأکید کرد که پلتفرم هم‌زمان فناوری، بازار و شیوه‌ی حکمرانی است و قدرت آن از کنترل بر «قوانین بازی» — چشم‌اندازی، دسترسی و معامله — می‌آید. این رویکرد، تحلیل پلتفرم را در تقاطع جامعه‌شناسی فناوری، اقتصاد و حکمرانی جای می‌دهد.  ۲. ساختارهای مفهومی • پلتفرم (Platform): زیرساخت دیجیتالی که بازیگران متعدد را گرد هم می‌آورد و تعامل آن‌ها را میانجی می‌کند. • کارکرد/امکان (Affordance): قابلیت‌های کنشی که طراحی فناوری به کاربر پیشنهاد می‌دهد و عادت‌های او را شکل می‌دهد. • اثر شبکه‌ای (Network Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود.', 'ace65313c6f96490cdb9b983ed7731a3c0bf7d68e91f14233a440a0edac7b1ab', 1216, 'ch-doc-card-531-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ace65313c6f96490cdb9b983ed7731a3c0bf7d68e91f14233a440a0edac7b1ab', token_count=1216, vector_point_id='ch-doc-card-531-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-531-7', 'doc-card-531', 'sec-card-531-2', 7, 'Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود. • حکمرانی الگوریتمی (Algorithmic Governance): فرایندی که الگوریتم‌ها درباره‌ی چشم‌اندازی، اولویت‌بندی و دسترسی تصمیم می‌گیرند. • زیرساخت دیجیتال (Digital Infrastructure): لایه‌ی فنی پایینی (سرور، پروت', '95c2a41b56c224b42488e19dbf2064ef44e99b6af08464075cc3e4296e54705c', 509, 'ch-doc-card-531-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='95c2a41b56c224b42488e19dbf2064ef44e99b6af08464075cc3e4296e54705c', token_count=509, vector_point_id='ch-doc-card-531-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-531-8', 'doc-card-531', 'sec-card-531-3', 8, '• پلتفرم (Platform): زیرساخت دیجیتالی که بازیگران متعدد را گرد هم می‌آورد و تعامل آن‌ها را میانجی می‌کند. • کارکرد/امکان (Affordance): قابلیت‌های کنشی که طراحی فناوری به کاربر پیشنهاد می‌دهد و عادت‌های او را شکل می‌دهد. • اثر شبکه‌ای (Network Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود. • حکمرانی الگوریتمی (Algorithmic Governance): فرایندی که الگوریتم‌ها درباره‌ی چشم‌اندازی، اولویت‌بندی و دسترسی تصمیم می‌گیرند. • زیرساخت دیجیتال (Digital Infrastructure): لایه‌ی فنی پایینی (سرور، پروتکل، شبکه) که خدمات بر آن ساخته می‌شوند. • پذیرش (Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن.', '3c61d5d146cf756011fcb316faa0502d957ac65ac19e581e862b4f675e0dc33f', 1167, 'ch-doc-card-531-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3c61d5d146cf756011fcb316faa0502d957ac65ac19e581e862b4f675e0dc33f', token_count=1167, vector_point_id='ch-doc-card-531-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-531-9', 'doc-card-531', 'sec-card-531-3', 9, '• پذیرش (Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن. • شکاف دیجیتال (Digital Divide): نابرابری ساختاری در دسترسی به فناوری دیجیتال، استفاده از آن و بهره‌مندی از آن. • پلتفرمی‌شدن (Platformization): فرایند گسترش منطق و ارزش‌های پلتفرم به حوزه‌های دیگر زندگی اجتماعی.', '058868170e5dcb763251870b437b68e333b102c73b1c8f9ac8c3bbac174cd0e9', 530, 'ch-doc-card-531-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='058868170e5dcb763251870b437b68e333b102c73b1c8f9ac8c3bbac174cd0e9', token_count=530, vector_point_id='ch-doc-card-531-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-531-10', 'doc-card-531', 'sec-card-531-4', 10, 'کل، شبکه) که خدمات بر آن ساخته می‌شوند. • پذیرش (Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن. • شکاف دیجیتال (Digital Divide): نابرابری ساختاری در دسترسی به فناوری دیجیتال، استفاده از آن و بهره‌مندی از آن. • پلتفرمی‌شدن (Platformization): فرایند گسترش منطق و ارزش‌های پلتفرم به حوزه‌های دیگر زندگی اجتماعی.  ۳. نمونه‌های تحلیلی ظهور پلتفرم‌های ویدیویی کوتاه امروز کمتر به کیفیت محتوای تولیدی بازمی‌گردد و بیشتر به طراحی فید الگوریتمی: فید با کارکرد «اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.', 'a56e2fc0daf0f988561df9df60ac9c69ef5920672e24eef06aeb5f8b303c5d97', 1007, 'ch-doc-card-531-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a56e2fc0daf0f988561df9df60ac9c69ef5920672e24eef06aeb5f8b303c5d97', token_count=1007, vector_point_id='ch-doc-card-531-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-531-11', 'doc-card-531', 'sec-card-531-4', 11, 'اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.  حکمرانی پلتفرم‌های بزرگ — نظارت بر محتوا، تعلیق حساب، اولویت‌بندی در جست‌وجو — در عمل نوعی قدرت شبه‌قضایی بر میلیاردها کاربر است که بدون شفافیت و پاسخگویی معیارهای دولتی اعمال می‌شود.  گوشی‌های هوشمند در عرض چند سال عادات ارتباط اجتماعی، خبرخوانی و خرید را تغییر داده‌اند؛ نمونه‌ی کلاسیکی از اینکه چگونه پذیرش یک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.  جابه‌جایی بسیاری از خدمات عمومی و تجاری به اپلیکیشن‌ها نمونه‌ای از پلتفرمی‌شدن است: منطق امتیازدهی، حساب کاربری و داده وارد حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).', 'cdb4fa11f8d231ff735dedf288a7c9d18381c00e6e762e0b8aaca4fe3338ad00', 1223, 'ch-doc-card-531-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cdb4fa11f8d231ff735dedf288a7c9d18381c00e6e762e0b8aaca4fe3338ad00', token_count=1223, vector_point_id='ch-doc-card-531-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-531-12', 'doc-card-531', 'sec-card-531-4', 12, 'حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).  رقابت صنعت استریم بر «محتوای انحصاری» استراتژی است برای بهره‌گیری از اثر شبکه‌ای: تمرکز مخاطب روی یک پلتفرم، ارزش آن را هم برای کاربران و هم برای تولیدکنندگان بزرگ‌تر می‌کند.  شکاف دیجیتال تنها درباره‌ی دسترسی به اینترنت نیست: تفاوت میان جوانی شهری که محتوا تولید می‌کند و مسنی روستایی که مصرف‌کننده‌ی منفعل است، نشان می‌دهد شکاف در سطح مهارت، زبان و قدرت اقتصادی نیز کار می‌کند.  ۴. نقدها و چالش‌ها ۱. ریسک جبرگرایی فناورانه: چارچوب «طراحی فناوری رفتار را شکل می‌دهد» می‌تواند به غفلت از انتخاب‌های اجتماعی، سیاسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲.', '4c8a35b8d7922ea06254566270f4f2631332f3bdcde0a1e3f70b05a02715fca1', 1218, 'ch-doc-card-531-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4c8a35b8d7922ea06254566270f4f2631332f3bdcde0a1e3f70b05a02715fca1', token_count=1218, vector_point_id='ch-doc-card-531-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-531-13', 'doc-card-531', 'sec-card-531-4', 13, 'اسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲. ناهمگنی مفهوم پلتفرم: واژه‌ی پلتفرم از سیستم‌عامل تا بازار آنلاین را پوشش می', '19fa9f0e05b2985d390de2678d7b48de8e57f7d857df69791d6add7a3f815e8e', 283, 'ch-doc-card-531-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='19fa9f0e05b2985d390de2678d7b48de8e57f7d857df69791d6add7a3f815e8e', token_count=283, vector_point_id='ch-doc-card-531-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-531-14', 'doc-card-531', 'sec-card-531-5', 14, 'ظهور پلتفرم‌های ویدیویی کوتاه امروز کمتر به کیفیت محتوای تولیدی بازمی‌گردد و بیشتر به طراحی فید الگوریتمی: فید با کارکرد «اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.  حکمرانی پلتفرم‌های بزرگ — نظارت بر محتوا، تعلیق حساب، اولویت‌بندی در جست‌وجو — در عمل نوعی قدرت شبه‌قضایی بر میلیاردها کاربر است که بدون شفافیت و پاسخگویی معیارهای دولتی اعمال می‌شود.  گوشی‌های هوشمند در عرض چند سال عادات ارتباط اجتماعی، خبرخوانی و خرید را تغییر داده‌اند؛ نمونه‌ی کلاسیکی از اینکه چگونه پذیرش یک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.', '636ba3dc6888936f1a685d93cce595caa0f4a53f230bfe4d00f0a25d7ebcf916', 1074, 'ch-doc-card-531-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='636ba3dc6888936f1a685d93cce595caa0f4a53f230bfe4d00f0a25d7ebcf916', token_count=1074, vector_point_id='ch-doc-card-531-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-531-15', 'doc-card-531', 'sec-card-531-5', 15, 'ک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.  جابه‌جایی بسیاری از خدمات عمومی و تجاری به اپلیکیشن‌ها نمونه‌ای از پلتفرمی‌شدن است: منطق امتیازدهی، حساب کاربری و داده وارد حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).  رقابت صنعت استریم بر «محتوای انحصاری» استراتژی است برای بهره‌گیری از اثر شبکه‌ای: تمرکز مخاطب روی یک پلتفرم، ارزش آن را هم برای کاربران و هم برای تولیدکنندگان بزرگ‌تر می‌کند.  شکاف دیجیتال تنها درباره‌ی دسترسی به اینترنت نیست: تفاوت میان جوانی شهری که محتوا تولید می‌کند و مسنی روستایی که مصرف‌کننده‌ی منفعل است، نشان می‌دهد شکاف در سطح مهارت، زبان و قدرت اقتصادی نیز کار می‌کند.', 'e3f0eb156fbda3efdb1f2e84350a04d71dda4dc87fff0d4186a864617a061e62', 1205, 'ch-doc-card-531-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e3f0eb156fbda3efdb1f2e84350a04d71dda4dc87fff0d4186a864617a061e62', token_count=1205, vector_point_id='ch-doc-card-531-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-531-16', 'doc-card-531', 'sec-card-531-6', 16, '۱. ریسک جبرگرایی فناورانه: چارچوب «طراحی فناوری رفتار را شکل می‌دهد» می‌تواند به غفلت از انتخاب‌های اجتماعی، سیاسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲. ناهمگنی مفهوم پلتفرم: واژه‌ی پلتفرم از سیستم‌عامل تا بازار آنلاین را پوشش می‌دهد و نتیجه‌گیری‌های کلی از یک نوع، لازم نیست به نوع دیگر بربخشد. ۳. غرب‌مندی پژوهش: بیشتر مطالعات کلاسیک بر بستر آمریکایی تمرکز دارند و ویژگی‌های رشد پلتفرم در مناطق دیگر (از جمله جنوب جهانی) کمتر پوشش داده شده است. ۴. سرعت تغییر: سرعت دگرگونی فناوری از سرعت تولید تئوری سریع‌تر است و بسیاری از مدل‌ها پیش از آنکه آزمون شوند، کهنه می‌شوند. ۵. جعبه‌ی سیاه الگوریتم: مبهم‌بودن الگوریتم‌ه', '34971c15146ca17ec874cd3416b1e60d2d48b22da945b7fc7a7d255e541f719c', 1189, 'ch-doc-card-531-16', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='34971c15146ca17ec874cd3416b1e60d2d48b22da945b7fc7a7d255e541f719c', token_count=1189, vector_point_id='ch-doc-card-531-16', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-531-17', 'doc-card-531', 'sec-card-531-7', 17, 'ایی که ادعاهای چارچوب بر آن‌ها استوار است، آزمون مستقل ادعاها را دشوار می‌کند. ۶. غفلت از شرایط مادی: تمرکز بر منطق «شبکه» می‌تواند تصویر بسازد که فناوری دیجیتال «بی‌وزن» است، درحالی‌که به مراکز داده‌ی پرمصرف انرژی، استخراج منابع و نیروی کار وابسته است. ۷. ابهام مرز «طراحی» و «رفتار»: اثبات اینکه رفتاری خاص محصول یک کارکرد است — نه نتیجه‌ی عادات اجتماعی و هنجارهای پیشین — بسیار دشوار است. ۸. مسئله‌ی قدرت: چارچوب گاه «حکمرانی» پلتفرم را توصیف می‌کند بدون آنکه ساختار مالکیت و منافع سیاسی پشت آن را عمیق تحلیل کند. ۹. تعمیم میان‌فرهنگی: پذیرش و اهلی‌سازی فناوری در فرهنگ‌ها به‌شدت متفاوت است و مدل ساخته‌شده در یک بستر، در بستر دیگر گمراه‌کننده می‌شود.', '1dca1cba3657dc9eb15a7fb9271b08cd7e5efc3b4e0380a2aa2f7eb41074c6f3', 1189, 'ch-doc-card-531-17', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1dca1cba3657dc9eb15a7fb9271b08cd7e5efc3b4e0380a2aa2f7eb41074c6f3', token_count=1189, vector_point_id='ch-doc-card-531-17', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-531-18', 'doc-card-531', 'sec-card-531-10', 18, 'کتاب «سرمایه‌داری پلتفرمی» (نیک سرنیک، ۲۰۱۷)؛ کتاب «عصر دوم رسانه» (یوهان وان‌دایک، ۲۰۰۵)؛ کتاب «انقلاب پلتفرمی» (پarker، وان آلستاین و چوداری، ۲۰۱۶)؛ استناد مبنا: Castells (2010) بر جامعه‌ی شبکه‌ای.', '0a3c1c145bb3103ffd193cce634d5d1dee4ff4a554a19424194c0f1d290155bf', 361, 'ch-doc-card-531-18', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0a3c1c145bb3103ffd193cce634d5d1dee4ff4a554a19424194c0f1d290155bf', token_count=361, vector_point_id='ch-doc-card-531-18', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-532-0', 'doc-card-532', NULL, 0, 'نظریه همانندی ارتباطی «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». هاوارد گایلز (۱۹۷۱) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده». بر اساس نظریه همانندی ارتباطی، «سازمانی» …', '9ba3508edcc84571cdda946544b363d4c2f250b3b70567afdb05b87c7c539013', 509, 'ch-doc-card-532-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9ba3508edcc84571cdda946544b363d4c2f250b3b70567afdb05b87c7c539013', token_count=509, vector_point_id='ch-doc-card-532-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-532-1', 'doc-card-532', 'sec-card-532-1', 1, 'ارتباطات بین‌فرهنگی، سازمانی و میان‌فردی  نظریه همانندی ارتباطی «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». هاوارد گایلز (۱۹۷۱) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس نظریه همانندی ارتباطی، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. هاوارد گایلز (۱۹۷۱) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', '345b6749db9a5e5fb5566ff686da0edbf384401d7637db5c216fcac627a1fcf3', 1005, 'ch-doc-card-532-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='345b6749db9a5e5fb5566ff686da0edbf384401d7637db5c216fcac627a1fcf3', token_count=1005, vector_point_id='ch-doc-card-532-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-532-2', 'doc-card-532', 'sec-card-532-1', 2, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  نظریه همانندی ارتباطی را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. هاوارد گایلز (۱۹۷۱) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.', '34ff1c8f57995f6c4aa79e3007076a64995454ab5a820652aa86fce032843d44', 654, 'ch-doc-card-532-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='34ff1c8f57995f6c4aa79e3007076a64995454ab5a820652aa86fce032843d44', token_count=654, vector_point_id='ch-doc-card-532-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-532-3', 'doc-card-532', 'sec-card-532-2', 3, '۱. بنیان و منطق نظری نظریه همانندی ارتباطی «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». هاوارد گایلز (۱۹۷۱) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس نظریه همانندی ارتباطی، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. هاوارد گایلز (۱۹۷۱) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', 'cac580e4109d8f3e3ac0a28bcbccb4eea691d0a8df39fbebb2ab2a4a1d3785d0', 967, 'ch-doc-card-532-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cac580e4109d8f3e3ac0a28bcbccb4eea691d0a8df39fbebb2ab2a4a1d3785d0', token_count=967, vector_point_id='ch-doc-card-532-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-532-4', 'doc-card-532', 'sec-card-532-2', 4, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  نظریه همانندی ارتباطی را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. هاوارد گایلز (۱۹۷۱) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.  ۲. ساختارهای مفهومی • ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند.', '0ba76d556814fb2d14eadafe4b09a12f2bccafd50a7f1517e6cfafadecd39558', 1132, 'ch-doc-card-532-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0ba76d556814fb2d14eadafe4b09a12f2bccafd50a7f1517e6cfafadecd39558', token_count=1132, vector_point_id='ch-doc-card-532-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-532-5', 'doc-card-532', 'sec-card-532-2', 5, ': «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. • تعارض و مذاکره (C', '4b2ee92a4bd95f0fa71fc3e321eb30deb772834aaeb2f023c43f2a324e54e499', 789, 'ch-doc-card-532-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4b2ee92a4bd95f0fa71fc3e321eb30deb772834aaeb2f023c43f2a324e54e499', token_count=789, vector_point_id='ch-doc-card-532-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-532-6', 'doc-card-532', 'sec-card-532-3', 6, '• ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. • تعارض و مذاکره (Conflict and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است.', 'bf50a19f3fa6a4558d5edbd42200280c7f4b92c377964c4e6187e1ed0133db26', 1230, 'ch-doc-card-532-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bf50a19f3fa6a4558d5edbd42200280c7f4b92c377964c4e6187e1ed0133db26', token_count=1230, vector_point_id='ch-doc-card-532-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-532-7', 'doc-card-532', 'sec-card-532-3', 7, 'flict and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است. • بافت‌محوری (Contextualism): «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • قدرت و نقش (Power and Role): «توان» در «ارتباط»: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.', 'b64e4de88dbaf207aea343dd750d2b2d8bd0b257fd13137445296eaa2c40c444', 527, 'ch-doc-card-532-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b64e4de88dbaf207aea343dd750d2b2d8bd0b257fd13137445296eaa2c40c444', token_count=527, vector_point_id='ch-doc-card-532-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-532-8', 'doc-card-532', 'sec-card-532-4', 8, 'onflict and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است. • بافت‌محوری (Contextualism): «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • قدرت و نقش (Power and Role): «توان» در «ارتباط»: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  ۳. نمونه‌های تحلیلی «ارتباط میان‌فردی» در عمل: «گفت‌وگو» بین «دوستان» «معنا» «ساخته» می‌شود: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  «ارتباط سازمانی» در عمل: «جلسه» «سازمانی»، «بافت» «توان» است: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  «ارتباط بین‌فرهنگی» در عمل: «مذاکره» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است و «فهم» «فرهنگ» دیگر، «توان» است.', 'c081b9b059efc2c0f489208780f89cb4fefeca5b43798f741fcfda388f3ef7cd', 1225, 'ch-doc-card-532-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c081b9b059efc2c0f489208780f89cb4fefeca5b43798f741fcfda388f3ef7cd', token_count=1225, vector_point_id='ch-doc-card-532-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-532-9', 'doc-card-532', 'sec-card-532-4', 9, 'فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است و «فهم» «فرهنگ» دیگر، «توان» است.  «هوش فرهنگی» در عمل: «مذاکره‌گر» با «هوش فرهنگی» «بافت» «دیگر» را «فهم» می‌کند: «ارتباط» در «بافت» «بین‌فرهنگی»، «توان» است.  «تعارض و مذاکره» در عمل: «مذاکره» «حل» «تعارض» است: «ارتباط» در «تعارض»، «بافت» «حل» است.  «بافت‌محوری» در عمل: «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» (فرهنگ) و «بافت» «کوچک» (گفت‌وگو) در هم تنیده‌اند.  ۴. نقدها و چالش‌ها ۱. «میان‌فردی» و «بافت»: «ارتباط» «میان‌فردی» در «بافت» «توان» است: «توان» در «گفت‌وگو» عمل می‌کند و «میان‌فردی»، «میان‌ساختاری» است. ۲.', '4f66e19cee71c86691f4a1c87800cc8ea0d26c39a8114664a1b1dd7d40e29bf6', 1040, 'ch-doc-card-532-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4f66e19cee71c86691f4a1c87800cc8ea0d26c39a8114664a1b1dd7d40e29bf6', token_count=1040, vector_point_id='ch-doc-card-532-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-532-10', 'doc-card-532', 'sec-card-532-4', 10, 'توان» است: «توان» در «گفت‌وگو» عمل می‌کند و «میان‌فردی»، «میان‌ساختاری» است. ۲. «فرهنگ سازمانی» و «قدرت»: «فرهنگ» در سازمان، «قدرت» است: «فرهنگ» «رقابت»، «فشار» می‌سازد و «ارتباط» را «بازتولید» می‌کند. ۳. «هوش فرهنگی» و «استعمار»: «هوش فرهنگی» می‌تواند «تثبیت» «فرهنگ» دیگر باشد: «فهم» «فرهنگ» دیگر، «آزادی» نیست، «توان» است. ۴. «ارتباط بین‌فره', '5c40399baa92f354685d1e8df245f031567289a107e39c2f3be10cba52e5f0b9', 625, 'ch-doc-card-532-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5c40399baa92f354685d1e8df245f031567289a107e39c2f3be10cba52e5f0b9', token_count=625, vector_point_id='ch-doc-card-532-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
