INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-532-13', 'doc-card-532', 'sec-card-532-6', 13, '۱. «میان‌فردی» و «بافت»: «ارتباط» «میان‌فردی» در «بافت» «توان» است: «توان» در «گفت‌وگو» عمل می‌کند و «میان‌فردی»، «میان‌ساختاری» است. ۲. «فرهنگ سازمانی» و «قدرت»: «فرهنگ» در سازمان، «قدرت» است: «فرهنگ» «رقابت»، «فشار» می‌سازد و «ارتباط» را «بازتولید» می‌کند. ۳. «هوش فرهنگی» و «استعمار»: «هوش فرهنگی» می‌تواند «تثبیت» «فرهنگ» دیگر باشد: «فهم» «فرهنگ» دیگر، «آزادی» نیست، «توان» است. ۴. «ارتباط بین‌فرهنگی» و «دوگانه»: «فرهنگ» «دوگانه» نیست: «تنوع» داخل «فرهنگ» به‌قدری «بزرگ» است که «دوگانه» «افسانه» است. ۵. «مذاکره» و «توان»: «مذاکره» در «توان» «نامتقارن»، «حل» «تعارض» نیست', 'c23b7447826b60647458a2d7d01fc71144cc1a740dda9a9d6c4cef757a8dc3a2', 1047, 'ch-doc-card-532-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c23b7447826b60647458a2d7d01fc71144cc1a740dda9a9d6c4cef757a8dc3a2', token_count=1047, vector_point_id='ch-doc-card-532-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-532-14', 'doc-card-532', 'sec-card-532-7', 14, ': «توان»، «مذاکره» را «بازتولید» می‌کند. ۶. «بافت‌محوری» و «تعمیم»: «معنا» در «بافت» «ساخته» می‌شود اما «بافت» «تعمیم» «پذیر» نیست: «بافت» «بومی» است و «تحلیل»، «بومی» لازم دارد. ۷. «ارتباط سازمانی» و «ساختار»: «ارتباط» در «ساختار» «سازمانی»، «بازتولید» «توان» است: «ساختار»، «ارتباط» است. ۸. «ارتباط» و «رسانه»: «ارتباط» «میان‌فردی» و «سازمانی» در «عصر دیجیتال»، «رسانه» «دیجیتال» «بازتعریف» می‌شود: «بافت» «دیجیتال»، «ارتباط» را «بازتولید» می‌کند. ۹. «هوش فرهنگی» و «بافت»: «هوش فرهنگی» در «بافت» «دیجیتال»، «بازتعریف» می‌شود: «بافت» «دیجیتال»، «فرهنگ» را «بازتولید» می‌کند.', '6bdec743a480fb86611d0cdb02061e889fbe8f7dd8911f02a030608c0f3c2be5', 1047, 'ch-doc-card-532-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6bdec743a480fb86611d0cdb02061e889fbe8f7dd8911f02a030608c0f3c2be5', token_count=1047, vector_point_id='ch-doc-card-532-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-532-15', 'doc-card-532', 'sec-card-532-10', 15, 'کتاب «ارتباط میان‌فردی» (آدلمن و همکاران، ۱۹۹۸)؛ کتاب «ارتباط سازمانی» (مکنزی و همکاران، ۲۰۰۵)؛ کتاب «ارتباط بین‌فرهنگی» (لومبونگ و همکاران، ۲۰۰۳)؛ کتاب «هوش فرهنگی» (رابن و همکاران، ۲۰۰۷).', '956a1e981812fd0aee168d40ca4cfc0e60c304bdfcef5b69be87a8e90e1ab9e3', 343, 'ch-doc-card-532-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='956a1e981812fd0aee168d40ca4cfc0e60c304bdfcef5b69be87a8e90e1ab9e3', token_count=343, vector_point_id='ch-doc-card-532-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-533-0', 'doc-card-533', NULL, 0, 'نظریه نقطهنظر «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». هاردینگ (۱۹۸۶) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده». بر اساس نظریه نقطهنظر، «سازمانی» «بافت» «قدرت» و «نقش» …', 'ddf41aadebaeb7df6e963e2c136ae53e58296689d3b3d79397c777f36236d6d9', 510, 'ch-doc-card-533-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ddf41aadebaeb7df6e963e2c136ae53e58296689d3b3d79397c777f36236d6d9', token_count=510, vector_point_id='ch-doc-card-533-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-533-1', 'doc-card-533', 'sec-card-533-1', 1, 'ارتباطات بین‌فرهنگی، سازمانی و میان‌فردی  نظریه نقطهنظر «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». هاردینگ (۱۹۸۶) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس نظریه نقطهنظر، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. هاردینگ (۱۹۸۶) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', '95f4cc19a39cb392ca49e6a1b774f88e0d2008a6589ccc80553693567386d04b', 958, 'ch-doc-card-533-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='95f4cc19a39cb392ca49e6a1b774f88e0d2008a6589ccc80553693567386d04b', token_count=958, vector_point_id='ch-doc-card-533-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-533-2', 'doc-card-533', 'sec-card-533-1', 2, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  نظریه نقطهنظر را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. هاردینگ (۱۹۸۶) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.', '58c27e271631edc2676fbba09dfcf95b12754a3e5bfe77c899b270ba6359e804', 630, 'ch-doc-card-533-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='58c27e271631edc2676fbba09dfcf95b12754a3e5bfe77c899b270ba6359e804', token_count=630, vector_point_id='ch-doc-card-533-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
