INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-533-4', 'doc-card-533', 'sec-card-533-2', 4, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  نظریه نقطهنظر را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. هاردینگ (۱۹۸۶) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.  ۲. ساختارهای مفهومی • ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند.', '79065d3bb513f097a9a23d29792c57cbfb10d8b414b6dbd21f6983e1a1ab591f', 1109, 'ch-doc-card-533-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='79065d3bb513f097a9a23d29792c57cbfb10d8b414b6dbd21f6983e1a1ab591f', token_count=1109, vector_point_id='ch-doc-card-533-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-533-5', 'doc-card-533', 'sec-card-533-2', 5, ': «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. • تعارض و مذاکره (Conflict and Negotiation)', '858d8491d411cc26097f2247ca4f09f5931a6d814e93bd3b86f76c3721137b69', 832, 'ch-doc-card-533-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='858d8491d411cc26097f2247ca4f09f5931a6d814e93bd3b86f76c3721137b69', token_count=832, vector_point_id='ch-doc-card-533-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
