INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-534-1', 'doc-card-534', 'sec-card-534-1', 1, 'ارتباطات بین‌فرهنگی، سازمانی و میان‌فردی  ارتباطات سازمانی بهعنوان تولید معنا «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». ویک (۱۹۷۹) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس ارتباطات سازمانی بهعنوان تولید معنا، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. ویک (۱۹۷۹) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', 'efffb2ed9af807dc0a0aba830858968ad8fbb4c325d87ff5881fc3947f86b2e9', 1023, 'ch-doc-card-534-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='efffb2ed9af807dc0a0aba830858968ad8fbb4c325d87ff5881fc3947f86b2e9', token_count=1023, vector_point_id='ch-doc-card-534-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-534-2', 'doc-card-534', 'sec-card-534-1', 2, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  ارتباطات سازمانی بهعنوان تولید معنا را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. ویک (۱۹۷۹) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.', 'a58c30519e2d3b89775ce6122c74ad93c237a11f3d65110340cce6d9d457d408', 663, 'ch-doc-card-534-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a58c30519e2d3b89775ce6122c74ad93c237a11f3d65110340cce6d9d457d408', token_count=663, vector_point_id='ch-doc-card-534-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
