INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-534-4', 'doc-card-534', 'sec-card-534-2', 4, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  ارتباطات سازمانی بهعنوان تولید معنا را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. ویک (۱۹۷۹) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.  ۲. ساختارهای مفهومی • ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند.', '77f7e33ed31261070d60945f3dc60514ac72ad8d2641a9fda62e588bd6470dbb', 1141, 'ch-doc-card-534-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='77f7e33ed31261070d60945f3dc60514ac72ad8d2641a9fda62e588bd6470dbb', token_count=1141, vector_point_id='ch-doc-card-534-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
