INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-534-12', 'doc-card-534', 'sec-card-534-5', 12, 'اکره» در عمل: «مذاکره» «حل» «تعارض» است: «ارتباط» در «تعارض»، «بافت» «حل» است.  «بافت‌محوری» در عمل: «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» (فرهنگ) و «بافت» «کوچک» (گفت‌وگو) در هم تنیده‌اند.', '70e3ddf05c8eaea9d7529c749dddc708444781f2934e78b2fabb313171dbc2bc', 359, 'ch-doc-card-534-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='70e3ddf05c8eaea9d7529c749dddc708444781f2934e78b2fabb313171dbc2bc', token_count=359, vector_point_id='ch-doc-card-534-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-534-13', 'doc-card-534', 'sec-card-534-6', 13, '۱. «میان‌فردی» و «بافت»: «ارتباط» «میان‌فردی» در «بافت» «توان» است: «توان» در «گفت‌وگو» عمل می‌کند و «میان‌فردی»، «میان‌ساختاری» است. ۲. «فرهنگ سازمانی» و «قدرت»: «فرهنگ» در سازمان، «قدرت» است: «فرهنگ» «رقابت»، «فشار» می‌سازد و «ارتباط» را «بازتولید» می‌کند. ۳. «هوش فرهنگی» و «استعمار»: «هوش فرهنگی» می‌تواند «تثبیت» «فرهنگ» دیگر باشد: «فهم» «فرهنگ» دیگر، «آزادی» نیست، «توان» است. ۴. «ارتباط بین‌فرهنگی» و «دوگانه»: «فرهنگ» «دوگانه» نیست: «تنوع» داخل «فرهنگ» به‌قدری «بزرگ» است که «دوگانه» «افسانه» است. ۵. «مذاکره» و «توان»: «مذاکره» در «توان» «نامتقارن»، «حل» «تعارض» نیست', 'c23b7447826b60647458a2d7d01fc71144cc1a740dda9a9d6c4cef757a8dc3a2', 1047, 'ch-doc-card-534-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c23b7447826b60647458a2d7d01fc71144cc1a740dda9a9d6c4cef757a8dc3a2', token_count=1047, vector_point_id='ch-doc-card-534-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-534-14', 'doc-card-534', 'sec-card-534-7', 14, ': «توان»، «مذاکره» را «بازتولید» می‌کند. ۶. «بافت‌محوری» و «تعمیم»: «معنا» در «بافت» «ساخته» می‌شود اما «بافت» «تعمیم» «پذیر» نیست: «بافت» «بومی» است و «تحلیل»، «بومی» لازم دارد. ۷. «ارتباط سازمانی» و «ساختار»: «ارتباط» در «ساختار» «سازمانی»، «بازتولید» «توان» است: «ساختار»، «ارتباط» است. ۸. «ارتباط» و «رسانه»: «ارتباط» «میان‌فردی» و «سازمانی» در «عصر دیجیتال»، «رسانه» «دیجیتال» «بازتعریف» می‌شود: «بافت» «دیجیتال»، «ارتباط» را «بازتولید» می‌کند. ۹. «هوش فرهنگی» و «بافت»: «هوش فرهنگی» در «بافت» «دیجیتال»، «بازتعریف» می‌شود: «بافت» «دیجیتال»، «فرهنگ» را «بازتولید» می‌کند.', '6bdec743a480fb86611d0cdb02061e889fbe8f7dd8911f02a030608c0f3c2be5', 1047, 'ch-doc-card-534-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6bdec743a480fb86611d0cdb02061e889fbe8f7dd8911f02a030608c0f3c2be5', token_count=1047, vector_point_id='ch-doc-card-534-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-534-15', 'doc-card-534', 'sec-card-534-10', 15, 'کتاب «ارتباط میان‌فردی» (آدلمن و همکاران، ۱۹۹۸)؛ کتاب «ارتباط سازمانی» (مکنزی و همکاران، ۲۰۰۵)؛ کتاب «ارتباط بین‌فرهنگی» (لومبونگ و همکاران، ۲۰۰۳)؛ کتاب «هوش فرهنگی» (رابن و همکاران، ۲۰۰۷).', '956a1e981812fd0aee168d40ca4cfc0e60c304bdfcef5b69be87a8e90e1ab9e3', 343, 'ch-doc-card-534-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='956a1e981812fd0aee168d40ca4cfc0e60c304bdfcef5b69be87a8e90e1ab9e3', token_count=343, vector_point_id='ch-doc-card-534-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-535-0', 'doc-card-535', NULL, 0, 'ادعای محوری فرضیه انتقال تحریک این است که مواجهه با پیام‌های رسانه‌ای می‌تواند ازطریق سازوکارهای روان‌شناختی و شناختی مشخص، باورها، نگرش‌ها و رفتارهای مخاطب را دگرگون کند. زیلمان (۱۹۷۱) کوشید دقیقاً مشخص کند کدام سازوکارها در عمل هستند و تحت چه شرایطی اثر رخ می‌دهد. در این سنت …', 'e78b91cb90aa4841aa4ead1c259b6228a6088511b20fab5705a85eddd4852e1b', 507, 'ch-doc-card-535-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e78b91cb90aa4841aa4ead1c259b6228a6088511b20fab5705a85eddd4852e1b', token_count=507, vector_point_id='ch-doc-card-535-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-535-1', 'doc-card-535', 'sec-card-535-1', 1, 'تأثیر رسانه، اقناع و تغییر نگرش  ادعای محوری فرضیه انتقال تحریک این است که مواجهه با پیام‌های رسانه‌ای می‌تواند ازطریق سازوکارهای روان‌شناختی و شناختی مشخص، باورها، نگرش‌ها و رفتارهای مخاطب را دگرگون کند. زیلمان (۱۹۷۱) کوشید دقیقاً مشخص کند کدام سازوکارها در عمل هستند و تحت چه شرایطی اثر رخ می‌دهد. در این سنت، اثر رسانه جادو نیست؛ فرایندی منظم است که شرایط مرزی آن — پیام، منبع، کانال و مخاطب — قابل شناسایی و آزمون است.  بر اساس فرضیه انتقال تحریک، اثرات رسانه یکدست و همگانی نیست، بلکه محدود و مشروط است. زیلمان (۱۹۷۱) تأکید کرد که فرد پیام را انفعالی دریافت نمی‌کند، بلکه بر اساس باورهای پیشین، انگیزه و اطلاعات در دسترس آن را پردازش می‌کند.', '3bb5ef5172ddcda9826ff8df9bad9eadf37bc5303b2fedde3c4fcbbebf3e7aef', 1174, 'ch-doc-card-535-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3bb5ef5172ddcda9826ff8df9bad9eadf37bc5303b2fedde3c4fcbbebf3e7aef', token_count=1174, vector_point_id='ch-doc-card-535-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-535-2', 'doc-card-535', 'sec-card-535-1', 2, 'کند، بلکه بر اساس باورهای پیشین، انگیزه و اطلاعات در دسترس آن را پردازش می‌کند. قوت اثر رسانه به تناسب میان پیام و شرایط شناختی و انگیزشی مخاطب بستگی دارد و در بیشتر موارد، اثر در سطح «درباره‌ی چه چیزی فکر کنیم» و «چگونه به آن بنگریم» رخ می‌دهد، نه در سطح «به چه چیزی باور داشته باشیم».  فرضیه انتقال تحریک اثرات رسانه را فرایندی روان‌شناختی-اجتماعی می‌داند که در آن پیام، منبع و بستر اجتماعی با هم بر مخاطب اثر می‌گذارند. زیلمان (۱۹۷۱) مسیر شناختی و عاطفی که پیام از ادراک به تغییر نگرش را طی می‌کند تحلیل کرد و بر این نکته تأکید داشت که در فرایند اقناع، مقاومت، پادواژه‌سازی و بستر اجتماعی هم‌سنگِ خودِ محتوا اهمیت دارند.', '93e66d2802e273d34b032415bd9b3ffe18b5ead30088e25692212fef368f1031', 1132, 'ch-doc-card-535-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='93e66d2802e273d34b032415bd9b3ffe18b5ead30088e25692212fef368f1031', token_count=1132, vector_point_id='ch-doc-card-535-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-535-3', 'doc-card-535', 'sec-card-535-2', 3, '۱. بنیان و منطق نظری ادعای محوری فرضیه انتقال تحریک این است که مواجهه با پیام‌های رسانه‌ای می‌تواند ازطریق سازوکارهای روان‌شناختی و شناختی مشخص، باورها، نگرش‌ها و رفتارهای مخاطب را دگرگون کند. زیلمان (۱۹۷۱) کوشید دقیقاً مشخص کند کدام سازوکارها در عمل هستند و تحت چه شرایطی اثر رخ می‌دهد. در این سنت، اثر رسانه جادو نیست؛ فرایندی منظم است که شرایط مرزی آن — پیام، منبع، کانال و مخاطب — قابل شناسایی و آزمون است.  بر اساس فرضیه انتقال تحریک، اثرات رسانه یکدست و همگانی نیست، بلکه محدود و مشروط است. زیلمان (۱۹۷۱) تأکید کرد که فرد پیام را انفعالی دریافت نمی‌کند، بلکه بر اساس باورهای پیشین، انگیزه و اطلاعات در دسترس آن را پردازش می‌کند.', '76bc73d2226994741aafc3f1ad5f7f68070112b4b2dac42ded41c3f02b871461', 1152, 'ch-doc-card-535-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='76bc73d2226994741aafc3f1ad5f7f68070112b4b2dac42ded41c3f02b871461', token_count=1152, vector_point_id='ch-doc-card-535-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-535-4', 'doc-card-535', 'sec-card-535-2', 4, 'کند، بلکه بر اساس باورهای پیشین، انگیزه و اطلاعات در دسترس آن را پردازش می‌کند. قوت اثر رسانه به تناسب میان پیام و شرایط شناختی و انگیزشی مخاطب بستگی دارد و در بیشتر موارد، اثر در سطح «درباره‌ی چه چیزی فکر کنیم» و «چگونه به آن بنگریم» رخ می‌دهد، نه در سطح «به چه چیزی باور داشته باشیم».  فرضیه انتقال تحریک اثرات رسانه را فرایندی روان‌شناختی-اجتماعی می‌داند که در آن پیام، منبع و بستر اجتماعی با هم بر مخاطب اثر می‌گذارند. زیلمان (۱۹۷۱) مسیر شناختی و عاطفی که پیام از ادراک به تغییر نگرش را طی می‌کند تحلیل کرد و بر این نکته تأکید داشت که در فرایند اقناع، مقاومت، پادواژه‌سازی و بستر اجتماعی هم‌سنگِ خودِ محتوا اهمیت دارند.  ۲.', '0703ba07d38cd7454cfafbfdbf5b6daf5ee134e5376bc29afd2dc24131a59893', 1140, 'ch-doc-card-535-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0703ba07d38cd7454cfafbfdbf5b6daf5ee134e5376bc29afd2dc24131a59893', token_count=1140, vector_point_id='ch-doc-card-535-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-535-5', 'doc-card-535', 'sec-card-535-2', 5, 'اقناع، مقاومت، پادواژه‌سازی و بستر اجتماعی هم‌سنگِ خودِ محتوا اهمیت دارند.  ۲. ساختارهای مفهومی • مواجهه‌ی گزینشی (Selective Exposure): گرایشی که فرد را به انتخاب پیام‌های هم‌سو با باورهای پیشین خود سوق می‌دهد. • پردازش شناختی (Cognitive Processing): عمق پردازش ذهنی پیام و نقش آن در ماندگاری تغییر نگرش. • اعتبار منبع (Source Credibility): ادراک تخصص و اطمینان‌پذیری فرستنده و اثر آن بر اقناع. • ترس‌افکنی (Fear Appeals): پیام‌هایی که ترس برانگیخت و اثر آن‌ها مشروط به ادراک کارآمدی راه‌حل است. • دانش اقناع (Persuasion Knowledge): آگاهی مخاطب از ماهیت اقناعی پیام و بیدار شدن مقاومت در برابر آن.', 'a853032611fe00615c9171d02e164be4327397e8750f0f29985f4747beddaa98', 1085, 'ch-doc-card-535-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a853032611fe00615c9171d02e164be4327397e8750f0f29985f4747beddaa98', token_count=1085, vector_point_id='ch-doc-card-535-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-535-6', 'doc-card-535', 'sec-card-535-2', 6, 'on Knowledge): آگاهی مخاطب از ماهیت اقناعی پیام و بیدار شدن مقاومت در برابر آن. • جریان دوشعویه (Two-Step Flow): انتقال اثر رسانه به مخاطبان ازطریق رهبران افکار و شبکه‌های بین‌فردی. • وابستگی به رسانه (Media Dependency): درجه‌ای که مخاطب در شرایط مشخص به رسانه به‌عنوان', 'fd58aae269993d0bb6b90e63570769d40d43271737e6e2acb3ceba7b571db9fb', 489, 'ch-doc-card-535-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fd58aae269993d0bb6b90e63570769d40d43271737e6e2acb3ceba7b571db9fb', token_count=489, vector_point_id='ch-doc-card-535-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-535-7', 'doc-card-535', 'sec-card-535-3', 7, '• مواجهه‌ی گزینشی (Selective Exposure): گرایشی که فرد را به انتخاب پیام‌های هم‌سو با باورهای پیشین خود سوق می‌دهد. • پردازش شناختی (Cognitive Processing): عمق پردازش ذهنی پیام و نقش آن در ماندگاری تغییر نگرش. • اعتبار منبع (Source Credibility): ادراک تخصص و اطمینان‌پذیری فرستنده و اثر آن بر اقناع. • ترس‌افکنی (Fear Appeals): پیام‌هایی که ترس برانگیخت و اثر آن‌ها مشروط به ادراک کارآمدی راه‌حل است. • دانش اقناع (Persuasion Knowledge): آگاهی مخاطب از ماهیت اقناعی پیام و بیدار شدن مقاومت در برابر آن. • جریان دوشعویه (Two-Step Flow): انتقال اثر رسانه به مخاطبان ازطریق رهبران افکار و شبکه‌های بین‌فردی.', '5ba4192c06afb04e4f1853b25107b5bef641d99f68e2cbc33c6846e7e625635f', 1096, 'ch-doc-card-535-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5ba4192c06afb04e4f1853b25107b5bef641d99f68e2cbc33c6846e7e625635f', token_count=1096, vector_point_id='ch-doc-card-535-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-535-8', 'doc-card-535', 'sec-card-535-3', 8, 'tep Flow): انتقال اثر رسانه به مخاطبان ازطریق رهبران افکار و شبکه‌های بین‌فردی. • وابستگی به رسانه (Media Dependency): درجه‌ای که مخاطب در شرایط مشخص به رسانه به‌عنوان منبع جهت‌یابی تکیه می‌کند. • قوت نگرش (Attitude Strength): میزان پایداری و مقاومت یک نگرش در برابر تغییر توسط پیام‌های جدید.', '5c8ecd026bd5af33d8cca9e0b2ad74e1b572f1b62ef899a1a3a5377825a2febf', 530, 'ch-doc-card-535-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5c8ecd026bd5af33d8cca9e0b2ad74e1b572f1b62ef899a1a3a5377825a2febf', token_count=530, vector_point_id='ch-doc-card-535-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-535-9', 'doc-card-535', 'sec-card-535-4', 9, 'منبع جهت‌یابی تکیه می‌کند. • قوت نگرش (Attitude Strength): میزان پایداری و مقاومت یک نگرش در برابر تغییر توسط پیام‌های جدید.  ۳. نمونه‌های تحلیلی در یک کمپین واکسیناسیون، انتخاب منبع قابل‌اعتماد (پزشک به‌جای مقام رسمی) و تأکید بر کارآمدی راه‌حل به‌جای ترس‌افکنی ساده، کاربرد عملی سازوکارهای اعتبار منبع و شرایط ترس‌افکنی است.  در انتخابات، نامزدهایی که هفته‌ها بر رویدادهای خبری و ترندهای شبکه‌های اجتماعی سلطه دارند، کوشش نمی‌کنند رأی‌دهندگان «به چه چیزی باور کنند»، بلکه موضوعی را به صدر دستور ذهنی رای‌دهندگان می‌برند؛ استراتژی‌ای مبتنی بر بُعد شناختی اثر رسانه.', '9e541cbdb9ddf3bc8556ae11fc782ad693e5150fb5a3a53293bd4c2f5488583b', 1027, 'ch-doc-card-535-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9e541cbdb9ddf3bc8556ae11fc782ad693e5150fb5a3a53293bd4c2f5488583b', token_count=1027, vector_point_id='ch-doc-card-535-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-535-10', 'doc-card-535', 'sec-card-535-4', 10, 'در دستور ذهنی رای‌دهندگان می‌برند؛ استراتژی‌ای مبتنی بر بُعد شناختی اثر رسانه.  فردی که باور دارد «اقتصاد خوب است»، هنگام مواجهه با ویدیویی وایرال از گران‌شدن، ابتدا تفسیرهای هم‌سو با باور خود را می‌جستجو و سپس نگرشش را تعدیل می‌کند؛ نمونه‌ای که در آن باورهای پیشین و پردازش گزینشی جهت اثر را تعیین می‌کند.  در شبکه‌های اجتماعی، پیام سیاسی که لایک و شریک‌کردن فراوان می‌گیرد، «اثبات اجتماعی» می‌سازد که اثر اقناعی آن را بر مخاطبان مردد بزرگ‌تر می‌کند، حتی اگر محتوایش تازه نباشد.', 'bbab35ee938ed96b483a4633717efec32374d1d5ed025e10195c38faf1581057', 870, 'ch-doc-card-535-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bbab35ee938ed96b483a4633717efec32374d1d5ed025e10195c38faf1581057', token_count=870, vector_point_id='ch-doc-card-535-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-535-11', 'doc-card-535', 'sec-card-535-4', 11, 'ه اثر اقناعی آن را بر مخاطبان مردد بزرگ‌تر می‌کند، حتی اگر محتوایش تازه نباشد.  جوانی که مستند تغییر اقلیم می‌بیند ممکن است نگرشی کوتاه‌مدت بگیرد، اما اگر محیط اجتماعی او — خانواده، دوستان، محل کار — همان نگرش را نپذیرد، اثر در عرض چند هفته می‌خوابد؛ نمونه‌ی کلاسیک مشروط بودن اثر رسانه به بستر اجتماعی.  وقتی یک سلبریتی یک محصول را تأیید می‌کند، مخاطب بیشتر ازطریق دلبستگی عاطفی و ادراک شباهت با منبع تحت تأثیر قرار می‌گیرد تا ازطریق منطق استدلال؛ سازوکاری که در مسیر محیطی پردازش فعال می‌شود.  ۴. نقدها و چالش‌ها ۱.', '2d158f16533ebcad1ca08ee412b4fe2e26db1f6b380959af168a76b744ba6259', 939, 'ch-doc-card-535-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2d158f16533ebcad1ca08ee412b4fe2e26db1f6b380959af168a76b744ba6259', token_count=939, vector_point_id='ch-doc-card-535-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-535-12', 'doc-card-535', 'sec-card-535-4', 12, 'ق استدلال؛ سازوکاری که در مسیر محیطی پردازش فعال می‌شود.  ۴. نقدها و چالش‌ها ۱. مسئله اندازه‌ی اثر: آزمایش‌های آزمایشگاهی اغلب اثرهای کوچک و کوتاه‌مدت نشان می‌دهند، درحالی‌که در شرایط میدانی واقعی (مانند انتخابات) اثرها بزرگ‌تر و ماندگارتر به نظر می‌رسند؛ جمع‌بندی این دو مجموعه یافته دشوار است. ۲. جهت علیت: اثبات اینکه رسانه نگرش را تغییر داده است — نه اینکه فرد بر اساس نگرش پیشین رسانه‌اش را انتخاب کرده — به‌دلیل مواجهه‌ی گزینشی بسیار دشوار است. ۳. فرهنگی‌بودن نمونه‌ها: بیشتر یافته‌های کلاسیک از نمونه‌های غربی و فردگرا گرفته شده‌اند و قابلیت تعمیم سازوکارها', '612660a4cddecfc3c825a280f7beeea6d81ce9a38e9ebe4a3021c3d26c52ab71', 1025, 'ch-doc-card-535-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='612660a4cddecfc3c825a280f7beeea6d81ce9a38e9ebe4a3021c3d26c52ab71', token_count=1025, vector_point_id='ch-doc-card-535-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-535-13', 'doc-card-535', 'sec-card-535-5', 13, 'در یک کمپین واکسیناسیون، انتخاب منبع قابل‌اعتماد (پزشک به‌جای مقام رسمی) و تأکید بر کارآمدی راه‌حل به‌جای ترس‌افکنی ساده، کاربرد عملی سازوکارهای اعتبار منبع و شرایط ترس‌افکنی است.  در انتخابات، نامزدهایی که هفته‌ها بر رویدادهای خبری و ترندهای شبکه‌های اجتماعی سلطه دارند، کوشش نمی‌کنند رأی‌دهندگان «به چه چیزی باور کنند»، بلکه موضوعی را به صدر دستور ذهنی رای‌دهندگان می‌برند؛ استراتژی‌ای مبتنی بر بُعد شناختی اثر رسانه.  فردی که باور دارد «اقتصاد خوب است»، هنگام مواجهه با ویدیویی وایرال از گران‌شدن، ابتدا تفسیرهای هم‌سو با باور خود را می‌جستجو و سپس نگرشش را تعدیل می‌کند؛ نمونه‌ای که در آن باورهای پیشین و پردازش گزینشی جهت اثر را تعیین می‌کند.', 'e3653456c57b761fc9848b6141ef7414b6848ad44191a380c138557056565ab7', 1176, 'ch-doc-card-535-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e3653456c57b761fc9848b6141ef7414b6848ad44191a380c138557056565ab7', token_count=1176, vector_point_id='ch-doc-card-535-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-535-14', 'doc-card-535', 'sec-card-535-5', 14, '‌کند؛ نمونه‌ای که در آن باورهای پیشین و پردازش گزینشی جهت اثر را تعیین می‌کند.  در شبکه‌های اجتماعی، پیام سیاسی که لایک و شریک‌کردن فراوان می‌گیرد، «اثبات اجتماعی» می‌سازد که اثر اقناعی آن را بر مخاطبان مردد بزرگ‌تر می‌کند، حتی اگر محتوایش تازه نباشد.  جوانی که مستند تغییر اقلیم می‌بیند ممکن است نگرشی کوتاه‌مدت بگیرد، اما اگر محیط اجتماعی او — خانواده، دوستان، محل کار — همان نگرش را نپذیرد، اثر در عرض چند هفته می‌خوابد؛ نمونه‌ی کلاسیک مشروط بودن اثر رسانه به بستر اجتماعی.  وقتی یک سلبریتی یک محصول را تأیید می‌کند، مخاطب بیشتر ازطریق دلبستگی عاطفی و ادراک شباهت با منبع تحت تأثیر قرار می‌گیرد تا ازطریق منطق استدلال؛ سازوکاری که در مسیر محیطی پردازش فعال می‌شود.', '86b5fb91c8d2da43961b96a2577417ddaefedec6574c76089400633906a2b64c', 1212, 'ch-doc-card-535-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='86b5fb91c8d2da43961b96a2577417ddaefedec6574c76089400633906a2b64c', token_count=1212, vector_point_id='ch-doc-card-535-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-535-15', 'doc-card-535', 'sec-card-535-6', 15, '۱. مسئله اندازه‌ی اثر: آزمایش‌های آزمایشگاهی اغلب اثرهای کوچک و کوتاه‌مدت نشان می‌دهند، درحالی‌که در شرایط میدانی واقعی (مانند انتخابات) اثرها بزرگ‌تر و ماندگارتر به نظر می‌رسند؛ جمع‌بندی این دو مجموعه یافته دشوار است. ۲. جهت علیت: اثبات اینکه رسانه نگرش را تغییر داده است — نه اینکه فرد بر اساس نگرش پیشین رسانه‌اش را انتخاب کرده — به‌دلیل مواجهه‌ی گزینشی بسیار دشوار است. ۳. فرهنگی‌بودن نمونه‌ها: بیشتر یافته‌های کلاسیک از نمونه‌های غربی و فردگرا گرفته شده‌اند و قابلیت تعمیم سازوکارهای آن‌ها به فرهنگ‌های جمع‌گرا محدود است. ۴.', 'b0aa500499a48a77c7729dc7e13ff2c59e80f31b94af5f00ba68e269d3cd0240', 961, 'ch-doc-card-535-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b0aa500499a48a77c7729dc7e13ff2c59e80f31b94af5f00ba68e269d3cd0240', token_count=961, vector_point_id='ch-doc-card-535-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-535-16', 'doc-card-535', 'sec-card-535-6', 16, 'رفته شده‌اند و قابلیت تعمیم سازوکارهای آن‌ها به فرهنگ‌های جمع‌گرا محدود است. ۴. تکه‌تکه‌شدن مخاطب: در عصر شخصی‌سازی و فیدهای الگوریتمی، مخاطب دیگر با «رسانه‌ی مشترک» مواجه نیست و پیش‌فرض پژوهش‌های کلاسیک اثرات توده‌ای — پیام مشترک برای مخاطب مشترک — ضعیف شده است. ۵. پارادوکس اثر قوی: ادعای اثرهای قوی و مستقیم ر', '3ce9ed6f1efae452035ee76414b0d9b62e80aa53d05b6888a40f81610b52b979', 567, 'ch-doc-card-535-16', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3ce9ed6f1efae452035ee76414b0d9b62e80aa53d05b6888a40f81610b52b979', token_count=567, vector_point_id='ch-doc-card-535-16', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-535-17', 'doc-card-535', 'sec-card-535-7', 17, 'سانه با دهه‌ها یافته‌ی «اثر محدود» در تنش است و «بازگشت به اثر قوی» بیش از آنکه تغییری در سازوکار روان‌شناختی باشد، تغییری در بستر رسانه‌ای است. ۶. عملیاتی‌سازی نگرش: سنجش تغییر نگرش و باور به خودگزارش وابسته است و مستعد سوگیری مطلوبیت اجتماعی و خطای حافظه است. ۷. غفلت از محدودیت‌های ساختاری: مدل‌های روان‌شناختی اثر، گاه تصویر می‌سازند که نگرش‌ها صرفاَ با «پردازش» تغییر می‌کنند، درحالی‌که شرایط ساختاری و اقتصادی تعیین می‌کنند مخاطب در اصل چه پیام‌هایی را می‌بیند. ۸. تصویر ثابت از مخاطب: بسیاری از مدل‌ها مخاطب را گیرنده‌ای با ویژگی‌های ثابت می‌پندارند، درحالی‌که مخاطب امروز خود نیز تولیدکننده‌ی محتوا و شکل‌دهنده به جریان پیام است. ۹.', '83ad1e4c2ae9bd237bb0dc1d0b223e894ccdcacb62f01ea4f133201381ce750b', 1163, 'ch-doc-card-535-17', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='83ad1e4c2ae9bd237bb0dc1d0b223e894ccdcacb62f01ea4f133201381ce750b', token_count=1163, vector_point_id='ch-doc-card-535-17', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-535-18', 'doc-card-535', 'sec-card-535-7', 18, 'الی‌که مخاطب امروز خود نیز تولیدکننده‌ی محتوا و شکل‌دهنده به جریان پیام است. ۹. تعمیم‌پذیری: اثرهایی که در بستر خاصی (کمپین بهداشتی، یک انتخابات) مشاهده می‌شوند، لزوماً به بسترهای دیگر تعمیم نمی‌یابند.', '944b4496d806d2aa875bdf136a9d77a97e6af1b935a2e0ac116b916058f0c72d', 365, 'ch-doc-card-535-18', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='944b4496d806d2aa875bdf136a9d77a97e6af1b935a2e0ac116b916058f0c72d', token_count=365, vector_point_id='ch-doc-card-535-18', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-535-19', 'doc-card-535', 'sec-card-535-10', 19, 'کتاب «نگرش‌ها و تغییر نگرش» (جان پتی، ۲۰۰۲)؛ کتاب «تأثیر: روان‌شناسی اقناع» (رابرت سیالدینی، ۱۹۸۴)؛ کتاب «اثرات رسانه‌های جمعی» (هوولاند، جانیز و کلی، ۱۹۵۳)؛ استناد مبنا: Petty & Cacioppo (1986) بر مدل قابلیت بسط.', '0553ef2ff323c489b3735af97eb1e64def88c12148bfd7f5935b714a6e4b0818', 387, 'ch-doc-card-535-19', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0553ef2ff323c489b3735af97eb1e64def88c12148bfd7f5935b714a6e4b0818', token_count=387, vector_point_id='ch-doc-card-535-19', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-536-0', 'doc-card-536', NULL, 0, 'تعامل فرامرزی (هورتون، ۱۹۵۶) رابطه‌ی احساسی و یک‌طرفه‌ای است که مخاطب با شخصیت‌های رسانه‌ای برقرار می‌کند؛ در بافت دیجیتال، این تعامل به سمت مشارکت، مم‌سازی و بازتولید مشترک معنا میان صنعت و مخاطب حرکت می‌کند.', 'bce5a354d03c799b98f49d5019f2f1e9515909ced063339b2c2c80893fd000c9', 379, 'ch-doc-card-536-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bce5a354d03c799b98f49d5019f2f1e9515909ced063339b2c2c80893fd000c9', token_count=379, vector_point_id='ch-doc-card-536-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-536-1', 'doc-card-536', 'sec-card-536-1', 1, 'بازی، سرگرمی و فرهنگ دیجیتال  رابطه احساسی مخاطب با شخصیت رسانهای.', 'e954af06a5f2ac9a2c43cd0ba84db98452cd333d6f1adc595113dc634e4a9252', 119, 'ch-doc-card-536-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e954af06a5f2ac9a2c43cd0ba84db98452cd333d6f1adc595113dc634e4a9252', token_count=119, vector_point_id='ch-doc-card-536-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-536-2', 'doc-card-536', 'sec-card-536-2', 2, '۱. بنیان و منطق نظری تعامل فرامرزی «بازی» را «فعالیت» معنادار در «بافت» دیجیتال می‌داند: نه «فرار» از واقعیت بلکه «بازی» با «معنا». هورتون (۱۹۵۶) در این چارچوب، «فرهنگ» را نه «محصول» «صنعت» بلکه «فعالیت» مخاطب تعریف کرد: «بازی»، «زبان» «نسل» دیجیتال است.  بر اساس تعامل فرامرزی، «سرگرمی» «صنعت» است اما «فرهنگ» «فعالیت» مخاطب است: «صنعت» «محتوا» تولید می‌کند و «مخاطب» «معنا» بازتولید می‌کند. هورتون (۱۹۵۶) در این چارچوب، «فرهنگ دیجیتال» را «فضا» «تولید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.', '482a2845803a8916b9d587cc34e92c5a9f3735acba669ced8daa7a6247ce729b', 961, 'ch-doc-card-536-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='482a2845803a8916b9d587cc34e92c5a9f3735acba669ced8daa7a6247ce729b', token_count=961, vector_point_id='ch-doc-card-536-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-536-3', 'doc-card-536', 'sec-card-536-2', 3, 'ید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  تعامل فرامرزی را می‌توان پاسخی به شکاف میان «نقد» «صنعت فرهنگ» (فرانکفورت) و «مطالعات فرهنگی» (مقاومت مخاطب) دانست: «بازی» و «سرگرمی» هم «بازتولید» «ایدئولوژی» است و هم «مقاومت» مخاطب. هورتون (۱۹۵۶) در این چارچوب، «فرهنگ دیجیتال» را «میدان» «دیالکتیک» «صنعت» و «مخاطب» تعریف کرد.  ۲. ساختارهای مفهومی • بازی و فرهنگ (Play and Culture): «بازی» به‌عنوان «زبان» «نسل» دیجیتال: «معنا» در «بازی» ساخته می‌شود. • فرهنگ دیجیتال (Digital Culture): «بافت» «فرهنگی» «نسل» دیجیتال: «بازی»، «بازی»، «میم» و «ریپلای»، «زبان» این «بافت»‌اند.', 'ff11691e22f3af305c1e228727af3d3f60b2cdcc9cb17ab1fda94c0bcd26e1ff', 1103, 'ch-doc-card-536-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ff11691e22f3af305c1e228727af3d3f60b2cdcc9cb17ab1fda94c0bcd26e1ff', token_count=1103, vector_point_id='ch-doc-card-536-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-536-4', 'doc-card-536', 'sec-card-536-2', 4, 'فرهنگی» «نسل» دیجیتال: «بازی»، «بازی»، «میم» و «ریپلای»، «زبان» این «بافت»‌اند. • صنعت سرگرمی (Entertainment Industry): «صنعت» «تولید» «محتوای» سرگرمی: «سود»، «تکرار» و «استاندارد»، «منطق» «صنعت» است. • فرهنگ عامه دیجیتال (Digital Pop Culture): «فرهنگ» «عامه» در «بافت» دیجیتال: «محتوا» «مخاطب» «ساخته»، «زبان» «فرهنگ» است. • تعامل و مشارکت (Interaction and Participation): «مخاطب» در «بافت» دیجیتال «مشارکت» می‌کند: «بازی» و «بازی»، «مشارکت» است. • مم (Meme): «واحد» «فرهنگی» که «ت', 'ecc322ae2bda0f3022e7422e0ab4986fcd2dc0be37cab88cc9cfeb2a0360667f', 876, 'ch-doc-card-536-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ecc322ae2bda0f3022e7422e0ab4986fcd2dc0be37cab88cc9cfeb2a0360667f', token_count=876, vector_point_id='ch-doc-card-536-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-536-5', 'doc-card-536', 'sec-card-536-3', 5, '• بازی و فرهنگ (Play and Culture): «بازی» به‌عنوان «زبان» «نسل» دیجیتال: «معنا» در «بازی» ساخته می‌شود. • فرهنگ دیجیتال (Digital Culture): «بافت» «فرهنگی» «نسل» دیجیتال: «بازی»، «بازی»، «میم» و «ریپلای»، «زبان» این «بافت»‌اند. • صنعت سرگرمی (Entertainment Industry): «صنعت» «تولید» «محتوای» سرگرمی: «سود»، «تکرار» و «استاندارد»، «منطق» «صنعت» است. • فرهنگ عامه دیجیتال (Digital Pop Culture): «فرهنگ» «عامه» در «بافت» دیجیتال: «محتوا» «مخاطب» «ساخته»، «زبان» «فرهنگ» است. • تعامل و مشارکت (Interaction and Participation): «مخاطب» در «بافت» دیجیتال «مشارکت» می‌کند: «بازی» و «بازی»، «مشارکت» است.', '3568aba6d13f485a22c8484a9dc926175664929f5d61008ea007723802e07e96', 1080, 'ch-doc-card-536-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3568aba6d13f485a22c8484a9dc926175664929f5d61008ea007723802e07e96', token_count=1080, vector_point_id='ch-doc-card-536-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
