INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-537-1', 'doc-card-537', 'sec-card-537-1', 1, 'بازی، سرگرمی و فرهنگ دیجیتال  بازیگرایی «بازی» را «فعالیت» معنادار در «بافت» دیجیتال می‌داند: نه «فرار» از واقعیت بلکه «بازی» با «معنا». ویلیام استیفنson (۱۹۶۷) در این چارچوب، «فرهنگ» را نه «محصول» «صنعت» بلکه «فعالیت» مخاطب تعریف کرد: «بازی»، «زبان» «نسل» دیجیتال است.  بر اساس بازیگرایی، «سرگرمی» «صنعت» است اما «فرهنگ» «فعالیت» مخاطب است: «صنعت» «محتوا» تولید می‌کند و «مخاطب» «معنا» بازتولید می‌کند. ویلیام استیفنson (۱۹۶۷) در این چارچوب، «فرهنگ دیجیتال» را «فضا» «تولید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.', '82eaf0a69f278898b250b43c9dd370a4699e4fa16e70cdc39dcaa93f6ef6d1bb', 999, 'ch-doc-card-537-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='82eaf0a69f278898b250b43c9dd370a4699e4fa16e70cdc39dcaa93f6ef6d1bb', token_count=999, vector_point_id='ch-doc-card-537-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-537-2', 'doc-card-537', 'sec-card-537-1', 2, 'ید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  بازیگرایی را می‌توان پاسخی به شکاف میان «نقد» «صنعت فرهنگ» (فرانکفورت) و «مطالعات فرهنگی» (مقاومت مخاطب) دانست: «بازی» و «سرگرمی» هم «بازتولید» «ایدئولوژی» است و هم «مقاومت» مخاطب. ویلیام استیفنson (۱۹۶۷) در این چارچوب، «فرهنگ دیجیتال» را «میدان» «دیالکتیک» «صنعت» و «مخاطب» تعریف کرد.', 'fb132e344574ee12c9cd93e8f008247574194ddced18729874fd28ac0c7380a7', 663, 'ch-doc-card-537-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fb132e344574ee12c9cd93e8f008247574194ddced18729874fd28ac0c7380a7', token_count=663, vector_point_id='ch-doc-card-537-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
