INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-537-13', 'doc-card-537', 'sec-card-537-6', 13, '۱. «بازی» و «استثمار»: «بازی» در «صنعت» «سرگرمی»، «کار» است: «مخاطب» «بازی» می‌کند و «صنعت» «سود» می‌برد: «استثمار» در «بازی» پنهان است. ۲. «میم» و «ایدئولوژی»: «میم» «مقاومت» است اما «بازتولید» «ایدئولوژی» هم: «طنز»، «نقد» نیست، «بازی» است. ۳. «فرهنگ دیجیتال» و «اعتیاد»: «مشارکت» «دیجیتال» می‌تواند «اعتیاد» باشد: «بازی» و «اعتیاد» مرز «کمرنگ» دارد. ۴. «صنعت سرگرمی» و «تنوع»: «صنعت» «استاندارد» می‌کند و «تنوع» را «محو» می‌کند: «سود»، «تنوع» را «حذف» می‌کند. ۵. «بازی‌سازی» و «انگیزه»: «بازی‌سازی» «رفتار» را «بازتولید» می‌کند اما «ا', '2e4941d52959e89db7bc7e9d3006bc9777ecfe2ae344d44bf4db263bfdfd463e', 974, 'ch-doc-card-537-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2e4941d52959e89db7bc7e9d3006bc9777ecfe2ae344d44bf4db263bfdfd463e', token_count=974, vector_point_id='ch-doc-card-537-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
