INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-538-13', 'doc-card-538', 'sec-card-538-6', 13, '۱. «بازی» و «استثمار»: «بازی» در «صنعت» «سرگرمی»، «کار» است: «مخاطب» «بازی» می‌کند و «صنعت» «سود» می‌برد: «استثمار» در «بازی» پنهان است. ۲. «میم» و «ایدئولوژی»: «میم» «مقاومت» است اما «بازتولید» «ایدئولوژی» هم: «طنز»، «نقد» نیست، «بازی» است. ۳. «فرهنگ دیجیتال» و «اعتیاد»: «مشارکت» «دیجیتال» می‌تواند «اعتیاد» باشد: «بازی» و «اعتیاد» مرز «کمرنگ» دارد. ۴. «صنعت سرگرمی» و «تنوع»: «صنعت» «استاندارد» می‌کند و «تنوع» را «محو» می‌کند: «سود»، «تنوع» را «حذف» می‌کند. ۵. «بازی‌سازی» و «انگیزه»: «بازی‌سازی» «رفتار» را «بازتولید» می‌کند اما «ا', '2e4941d52959e89db7bc7e9d3006bc9777ecfe2ae344d44bf4db263bfdfd463e', 974, 'ch-doc-card-538-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2e4941d52959e89db7bc7e9d3006bc9777ecfe2ae344d44bf4db263bfdfd463e', token_count=974, vector_point_id='ch-doc-card-538-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-538-14', 'doc-card-538', 'sec-card-538-7', 14, 'نگیزه» «داخلی» را «محو» می‌کند: «پاداش»، «بازی» را «کار» می‌کند. ۶. «فرهنگ همگرا» و «نظارت»: «مخاطب» «تولید» می‌کند و «صنعت» «بازتولید» می‌کند: «نظارت» بر «مخاطب»، «حاکمیت» است. ۷. «فرهنگ عامه دیجیتال» و «اعتبار»: «محتوای» «مخاطب» «ساخته»، «اعتبار» ندارد: «مرز» بین «حرفه‌ای» و «مخاطب»، «بازتعریف» لازم دارد. ۸. «بازی» و «واقعیت»: «بازی» در «بافت» دیجیتال، «واقعیت» است: «مرز» بین «بازی» و «واقعیت»، «محو» شده است. ۹. «فرهنگ دیجیتال» و «نسل»: «فرهنگ» دیجیتال، «نسل» است اما «همه» «نسل‌ها» در آن «حاضر»‌اند: «مرز» «نسل»، «کمرنگ» شده است.', '0b0c3f05ea135af8deed6fc16c6361ab3920d24bdf5ebb22d4b4a264efdf1ab2', 974, 'ch-doc-card-538-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0b0c3f05ea135af8deed6fc16c6361ab3920d24bdf5ebb22d4b4a264efdf1ab2', token_count=974, vector_point_id='ch-doc-card-538-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-538-15', 'doc-card-538', 'sec-card-538-10', 15, 'کتاب «فرهنگ همگرا» (جَنکینز، ۲۰۰۶)؛ کتاب «بازی و فرهنگ» (سوسا، ۱۹۵۵)؛ کتاب «صنعت فرهنگ» (آدورنو و هورکهایمر، ۱۹۴۴)؛ کتاب «فرهنگ دیجیتال» (منرو و همکاران، ۲۰۰۴).', '373e57c2c2351d10cec24f7b867cae52e67956b87e6039750582abd935eddb22', 290, 'ch-doc-card-538-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='373e57c2c2351d10cec24f7b867cae52e67956b87e6039750582abd935eddb22', token_count=290, vector_point_id='ch-doc-card-538-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-539-0', 'doc-card-539', NULL, 0, 'نظریه جهانیشدن فرهنگی «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». رابرتسون (۱۹۹۲) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده». بر اساس نظریه جهانیشدن فرهنگی، «سازمانی» …', '211d693935ca3bd2e8a17e3c18cab9c673bed9401c2e057587050ae0b50c6a4d', 501, 'ch-doc-card-539-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='211d693935ca3bd2e8a17e3c18cab9c673bed9401c2e057587050ae0b50c6a4d', token_count=501, vector_point_id='ch-doc-card-539-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-539-1', 'doc-card-539', 'sec-card-539-1', 1, 'ارتباطات بین‌فرهنگی، سازمانی و میان‌فردی  نظریه جهانیشدن فرهنگی «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». رابرتسون (۱۹۹۲) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس نظریه جهانیشدن فرهنگی، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. رابرتسون (۱۹۹۲) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', '75daeb8fbbb324080d77a070f5cd6a88063e9fbfeff53dcea2be88e47c4a28d6', 990, 'ch-doc-card-539-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='75daeb8fbbb324080d77a070f5cd6a88063e9fbfeff53dcea2be88e47c4a28d6', token_count=990, vector_point_id='ch-doc-card-539-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-539-2', 'doc-card-539', 'sec-card-539-1', 2, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  نظریه جهانیشدن فرهنگی را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. رابرتسون (۱۹۹۲) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.', 'e43ecca0d9b796b43c142e5abbbab284cf48351f413093896b91edf6d4309a9d', 647, 'ch-doc-card-539-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e43ecca0d9b796b43c142e5abbbab284cf48351f413093896b91edf6d4309a9d', token_count=647, vector_point_id='ch-doc-card-539-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-539-3', 'doc-card-539', 'sec-card-539-2', 3, '۱. بنیان و منطق نظری نظریه جهانیشدن فرهنگی «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». رابرتسون (۱۹۹۲) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس نظریه جهانیشدن فرهنگی، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. رابرتسون (۱۹۹۲) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', 'dd7307c8116703848ec501dbbce82a35a60f16d225aafe1088364ede69bcd142', 952, 'ch-doc-card-539-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='dd7307c8116703848ec501dbbce82a35a60f16d225aafe1088364ede69bcd142', token_count=952, vector_point_id='ch-doc-card-539-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-539-4', 'doc-card-539', 'sec-card-539-2', 4, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  نظریه جهانیشدن فرهنگی را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. رابرتسون (۱۹۹۲) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.  ۲. ساختارهای مفهومی • ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند.', 'eab41b00e3a905779aec78d4a5b97a20ec20fca9c07126cba4539f0ca99e7b2f', 1125, 'ch-doc-card-539-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='eab41b00e3a905779aec78d4a5b97a20ec20fca9c07126cba4539f0ca99e7b2f', token_count=1125, vector_point_id='ch-doc-card-539-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-539-5', 'doc-card-539', 'sec-card-539-2', 5, ': «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. • تعارض و مذاکره (Conflict', 'fc027e099a654f68114534fa40d1a97900d33dd8a78874e69ec4c8770bea550b', 801, 'ch-doc-card-539-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fc027e099a654f68114534fa40d1a97900d33dd8a78874e69ec4c8770bea550b', token_count=801, vector_point_id='ch-doc-card-539-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-539-6', 'doc-card-539', 'sec-card-539-3', 6, '• ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. • تعارض و مذاکره (Conflict and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است.', 'bf50a19f3fa6a4558d5edbd42200280c7f4b92c377964c4e6187e1ed0133db26', 1230, 'ch-doc-card-539-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bf50a19f3fa6a4558d5edbd42200280c7f4b92c377964c4e6187e1ed0133db26', token_count=1230, vector_point_id='ch-doc-card-539-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-539-7', 'doc-card-539', 'sec-card-539-3', 7, 'flict and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است. • بافت‌محوری (Contextualism): «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • قدرت و نقش (Power and Role): «توان» در «ارتباط»: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.', 'b64e4de88dbaf207aea343dd750d2b2d8bd0b257fd13137445296eaa2c40c444', 527, 'ch-doc-card-539-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b64e4de88dbaf207aea343dd750d2b2d8bd0b257fd13137445296eaa2c40c444', token_count=527, vector_point_id='ch-doc-card-539-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-539-8', 'doc-card-539', 'sec-card-539-4', 8, 'and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است. • بافت‌محوری (Contextualism): «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • قدرت و نقش (Power and Role): «توان» در «ارتباط»: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  ۳. نمونه‌های تحلیلی «ارتباط میان‌فردی» در عمل: «گفت‌وگو» بین «دوستان» «معنا» «ساخته» می‌شود: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  «ارتباط سازمانی» در عمل: «جلسه» «سازمانی»، «بافت» «توان» است: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  «ارتباط بین‌فرهنگی» در عمل: «مذاکره» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است و «فهم» «فرهنگ» دیگر، «توان» است.', '763d1ed12346c549d4f265a9c96555b3aea102c860d161313b0220a599d5a8b6', 1210, 'ch-doc-card-539-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='763d1ed12346c549d4f265a9c96555b3aea102c860d161313b0220a599d5a8b6', token_count=1210, vector_point_id='ch-doc-card-539-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-539-9', 'doc-card-539', 'sec-card-539-4', 9, 'فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است و «فهم» «فرهنگ» دیگر، «توان» است.  «هوش فرهنگی» در عمل: «مذاکره‌گر» با «هوش فرهنگی» «بافت» «دیگر» را «فهم» می‌کند: «ارتباط» در «بافت» «بین‌فرهنگی»، «توان» است.  «تعارض و مذاکره» در عمل: «مذاکره» «حل» «تعارض» است: «ارتباط» در «تعارض»، «بافت» «حل» است.  «بافت‌محوری» در عمل: «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» (فرهنگ) و «بافت» «کوچک» (گفت‌وگو) در هم تنیده‌اند.  ۴. نقدها و چالش‌ها ۱. «میان‌فردی» و «بافت»: «ارتباط» «میان‌فردی» در «بافت» «توان» است: «توان» در «گفت‌وگو» عمل می‌کند و «میان‌فردی»، «میان‌ساختاری» است. ۲.', '4f66e19cee71c86691f4a1c87800cc8ea0d26c39a8114664a1b1dd7d40e29bf6', 1040, 'ch-doc-card-539-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4f66e19cee71c86691f4a1c87800cc8ea0d26c39a8114664a1b1dd7d40e29bf6', token_count=1040, vector_point_id='ch-doc-card-539-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-539-10', 'doc-card-539', 'sec-card-539-4', 10, 'توان» است: «توان» در «گفت‌وگو» عمل می‌کند و «میان‌فردی»، «میان‌ساختاری» است. ۲. «فرهنگ سازمانی» و «قدرت»: «فرهنگ» در سازمان، «قدرت» است: «فرهنگ» «رقابت»، «فشار» می‌سازد و «ارتباط» را «بازتولید» می‌کند. ۳. «هوش فرهنگی» و «استعمار»: «هوش فرهنگی» می‌تواند «تثبیت» «فرهنگ» دیگر باشد: «فهم» «فرهنگ» دیگر، «آزادی» نیست، «توان» است. ۴. «ارتباط بین‌فرهنگی»', '6c647848070ba3c8ef29f6e649ccfc6ffe6d00173cfcbba82cfe75d7937d7386', 632, 'ch-doc-card-539-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6c647848070ba3c8ef29f6e649ccfc6ffe6d00173cfcbba82cfe75d7937d7386', token_count=632, vector_point_id='ch-doc-card-539-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
