INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-613-11', 'doc-card-613', 'sec-card-613-5', 11, '«توان» حرفه‌ای را «حفظ» می‌کند: «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی رسانه است.  «ریسک شغلی» در «عصر دیجیتال»: «مسابقه» برای «نکست» و «فشار» «سرعت»، «کار» رسانه‌ای را «پراکنده» و «ناپایدار» کرده است: «استقلال» حرفه‌ای «تحت فشار» است.', '714b07ad4f7a51079e90fad97f6ce548775ccc75495317d26370de2f83c7510d', 419, 'ch-doc-card-613-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='714b07ad4f7a51079e90fad97f6ce548775ccc75495317d26370de2f83c7510d', token_count=419, vector_point_id='ch-doc-card-613-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-613-12', 'doc-card-613', 'sec-card-613-6', 12, '۱. «حرفه‌ای‌سازی» به «نقش‌پردازی» تقلیل می‌یابد: «اصول» به «نقش» تبدیل می‌شوند و «کار» به «نقش‌بازی»: «اعتبار» بدون «عمل» «معنا» ندارد. ۲. «ساختار سازمانی» در «عصر دیجیتال» «بازتعریف» می‌شود: «سلسله‌مراتب» کلاسیک در «پلتفرم‌ها» «عمل» نمی‌کند و «ساختار» «شبکه‌ای»، «بازتعریف» لازم دارد. ۳. «منابع انسانی» و «داده»: «ارزیابی» کارکنان با «داده» و «الگوریتم»، «حرفه‌ای‌بودن» را «ابزاری» می‌کند: «توان» به «داده» تبدیل می‌شود. ۴. «کار پراکنده» و «اعتبار»: «مستقل» «حرفه‌ای» نیست و «اعتبار» ندارد: «مرز» بین «حرفه‌ای» و «مستقل»، «بازتعریف» لازم دارد. ۵. «فرهنگ سازمانی» و «قدرت»: «فرهنگ» در «سلسله‌مراتب»، «قدرت» است: «فرهنگ»', '2b6e87c0375f44acac0dbf50743587916b51216784afad745c61db32777925b4', 1125, 'ch-doc-card-613-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2b6e87c0375f44acac0dbf50743587916b51216784afad745c61db32777925b4', token_count=1125, vector_point_id='ch-doc-card-613-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-613-13', 'doc-card-613', 'sec-card-613-7', 13, '«رقابت»، «فشار» می‌سازد و «کار» را «استثمار» می‌کند. ۶. «توسعه شغلی» و «بازار»: «مسیر» شغلی در «بازار» «رقابت» «تعیین» می‌شود: «توان» حرفه‌ای «بازتولید» نمی‌شود و «کار» به «رقابت» تقلیل می‌یابد. ۷. «ریسک شغلی» در «بافت‌های دولتی» «عمیق‌تر» است: «فشار» «سیاسی» بر «کار» رسانه‌ای، «ریسک» را «افزایش» می‌دهد و «استقلال» حرفه‌ای «تحت فشار» است. ۸. «مدیریت منابع انسانی» و «حقوق»: «حقوق» کارکنان رسانه‌ای در «بازار» «رقابت» «تعیین» می‌شود: «سرمایه‌ی انسانی» «استثمار» می‌شود. ۹. «ساختار» و «نقش» در «عصر الگوریتم» «بازتعریف» می‌شوند: «الگوریتم»، «نقش» «کارکنان» را «تعیین» می‌کند و «ساختار» «سازمانی»، «بازتعریف» لازم دارد.', '59813802a8fd8b584b7cf5aaf1f17e5f784c089429ecd008c4916c8e5915090b', 1123, 'ch-doc-card-613-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='59813802a8fd8b584b7cf5aaf1f17e5f784c089429ecd008c4916c8e5915090b', token_count=1123, vector_point_id='ch-doc-card-613-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-613-14', 'doc-card-613', 'sec-card-613-10', 14, 'کتاب «حرفه‌ای‌سازی رسانه» (گارتنر و همکاران، ۱۹۸۶)؛ کتاب «سازمان رسانه‌ای» (تاکت و همکاران، ۱۹۹۰)؛ کتاب «کار پراکنده و رسانه» (بویل و همکاران، ۲۰۱۵)؛ کتاب «منابع انسانی در رسانه» (مورگان، ۲۰۰۴).', 'd88d82e7ec3cb842cb7f0755a7adc74d63d4eaf63470e287fa072ada619a6ae9', 352, 'ch-doc-card-613-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d88d82e7ec3cb842cb7f0755a7adc74d63d4eaf63470e287fa072ada619a6ae9', token_count=352, vector_point_id='ch-doc-card-613-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-614-0', 'doc-card-614', NULL, 0, 'نظریه دو عاملی (انگیزش–بهداشت) کار رسانه‌ای را «حرفه‌ای‌سازی» (professionalization) می‌داند: رسانه، «نهاد» است و «حرفه‌ای» بودن، «اعتبار» می‌سازد. هرزبرگ (۱۹۵۹) در این چارچوب، «کار رسانه‌ای» را از «پیشه» به «حرفه» ارتقا داد: «اصول»، «نقش» و «نقش‌های» سازمانی، «ساختار» کار را …', '642a23085a309775f5bb87c74e8a89604d191c5e860c980dc838c619a8b2c8cd', 503, 'ch-doc-card-614-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='642a23085a309775f5bb87c74e8a89604d191c5e860c980dc838c619a8b2c8cd', token_count=503, vector_point_id='ch-doc-card-614-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-614-1', 'doc-card-614', 'sec-card-614-1', 1, 'منابع انسانی و کار رسانه‌ای  نظریه دو عاملی (انگیزش–بهداشت) کار رسانه‌ای را «حرفه‌ای‌سازی» (professionalization) می‌داند: رسانه، «نهاد» است و «حرفه‌ای» بودن، «اعتبار» می‌سازد. هرزبرگ (۱۹۵۹) در این چارچوب، «کار رسانه‌ای» را از «پیشه» به «حرفه» ارتقا داد: «اصول»، «نقش» و «نقش‌های» سازمانی، «ساختار» کار را «تعیین» می‌کنند.  بر اساس نظریه دو عاملی (انگیزش–بهداشت)، «سازمان رسانه‌ای» با «ساختار» و «فرهنگ» سازمانی «کار» را «بازتولید» می‌کند: «سلسله‌مراتب»، «نقش‌ها» و «فرهنگ» سازمانی، «رفتار» کارکنان را «شکل» می‌دهند. هرزبرگ (۱۹۵۹) در این چارچوب، «منابع انسانی» را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.', '8e71647eb7bebac96024281e1a2af52fd15dc8ae9bfe84beb9d8318cf600f1ff', 1158, 'ch-doc-card-614-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8e71647eb7bebac96024281e1a2af52fd15dc8ae9bfe84beb9d8318cf600f1ff', token_count=1158, vector_point_id='ch-doc-card-614-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-614-2', 'doc-card-614', 'sec-card-614-1', 2, 'را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.  نظریه دو عاملی (انگیزش–بهداشت) را می‌توان پاسخی به شکاف میان «سازمان کلاسیک» (سلسله‌مراتبی) و «سازمان دیجیتال» (شبکه‌ای) دانست: در «عصر دیجیتال»، «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده و «کار» رسانه‌ای به «کار پراکنده» (gig) تبدیل شده است. هرزبرگ (۱۹۵۹) در این چارچوب، «کار» را نه «پاره‌ای» از «سازمان» بلکه «جریان» در «بازار» تعریف کرد.', '6ccee1f2961dbf2c8267bb066866cc623664172a318ae76ca45fd7b40179c4e1', 758, 'ch-doc-card-614-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6ccee1f2961dbf2c8267bb066866cc623664172a318ae76ca45fd7b40179c4e1', token_count=758, vector_point_id='ch-doc-card-614-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-614-3', 'doc-card-614', 'sec-card-614-2', 3, '۱. بنیان و منطق نظری نظریه دو عاملی (انگیزش–بهداشت) کار رسانه‌ای را «حرفه‌ای‌سازی» (professionalization) می‌داند: رسانه، «نهاد» است و «حرفه‌ای» بودن، «اعتبار» می‌سازد. هرزبرگ (۱۹۵۹) در این چارچوب، «کار رسانه‌ای» را از «پیشه» به «حرفه» ارتقا داد: «اصول»، «نقش» و «نقش‌های» سازمانی، «ساختار» کار را «تعیین» می‌کنند.  بر اساس نظریه دو عاملی (انگیزش–بهداشت)، «سازمان رسانه‌ای» با «ساختار» و «فرهنگ» سازمانی «کار» را «بازتولید» می‌کند: «سلسله‌مراتب»، «نقش‌ها» و «فرهنگ» سازمانی، «رفتار» کارکنان را «شکل» می‌دهند. هرزبرگ (۱۹۵۹) در این چارچوب، «منابع انسانی» را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.', '23fb6bc6ce62160bf058a0060c01395339ff23368f8d300010efa2348e8751ec', 1143, 'ch-doc-card-614-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='23fb6bc6ce62160bf058a0060c01395339ff23368f8d300010efa2348e8751ec', token_count=1143, vector_point_id='ch-doc-card-614-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-614-4', 'doc-card-614', 'sec-card-614-2', 4, 'را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.  نظریه دو عاملی (انگیزش–بهداشت) را می‌توان پاسخی به شکاف میان «سازمان کلاسیک» (سلسله‌مراتبی) و «سازمان دیجیتال» (شبکه‌ای) دانست: در «عصر دیجیتال»، «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده و «کار» رسانه‌ای به «کار پراکنده» (gig) تبدیل شده است. هرزبرگ (۱۹۵۹) در این چارچوب، «کار» را نه «پاره‌ای» از «سازمان» بلکه «جریان» در «بازار» تعریف کرد.  ۲. ساختارهای مفهومی • حرفه‌ای‌سازی (Professionalization): فرایند «حرفه‌ای» شدن کار رسانه‌ای: «اصول»، «نقش» و «نقش‌های» سازمانی؛ «اعتبار» و «استقلال».', '2bbe4bdc1d8f141f457e22cffb58e214dabc7bf4106d857a0e6e1b2bf22d75a1', 1032, 'ch-doc-card-614-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2bbe4bdc1d8f141f457e22cffb58e214dabc7bf4106d857a0e6e1b2bf22d75a1', token_count=1032, vector_point_id='ch-doc-card-614-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-614-5', 'doc-card-614', 'sec-card-614-2', 5, '‌ای» شدن کار رسانه‌ای: «اصول»، «نقش» و «نقش‌های» سازمانی؛ «اعتبار» و «استقلال». • ساختار سازمانی (Organizational Structure): «سلسله‌مراتب»، «نقش‌ها» و «مسئولیت‌ها» در رسانه؛ «ساختار»، «رفتار» کارکنان را «شکل» می‌دهد. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها»، «باورها» و «نمادها» در رسانه؛ «فرهنگ»، «رفتار» را «بازتولید» می‌کند. • مدیریت منابع انسانی (HR Management): «جذب»، «آموزش»، «ارزیابی» و «حفظ» «توان» حرفه‌ای؛ «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی است. • کار پراکنده (Gig Work): «کار» «مستقل»، «پاره‌وقت» و «پروژه‌ای» در رسانه؛ «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده است. • ریس', '3d1927e7c6d474693df15d1a4c0fb368870caf0e48b00b2a271ecb92467ffed5', 1078, 'ch-doc-card-614-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3d1927e7c6d474693df15d1a4c0fb368870caf0e48b00b2a271ecb92467ffed5', token_count=1078, vector_point_id='ch-doc-card-614-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-614-6', 'doc-card-614', 'sec-card-614-3', 6, '• حرفه‌ای‌سازی (Professionalization): فرایند «حرفه‌ای» شدن کار رسانه‌ای: «اصول»، «نقش» و «نقش‌های» سازمانی؛ «اعتبار» و «استقلال». • ساختار سازمانی (Organizational Structure): «سلسله‌مراتب»، «نقش‌ها» و «مسئولیت‌ها» در رسانه؛ «ساختار»، «رفتار» کارکنان را «شکل» می‌دهد. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها»، «باورها» و «نمادها» در رسانه؛ «فرهنگ»، «رفتار» را «بازتولید» می‌کند. • مدیریت منابع انسانی (HR Management): «جذب»، «آموزش»، «ارزیابی» و «حفظ» «توان» حرفه‌ای؛ «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی است. • کار پراکنده (Gig Work): «کار» «مستقل»، «پاره‌وقت» و «پروژه‌ای» در رسانه؛ «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده است.', '8ed776a62c1398c2193e6cdfcbb731d44985ab6f4f5d05b39d5fcf428dc75fd7', 1158, 'ch-doc-card-614-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8ed776a62c1398c2193e6cdfcbb731d44985ab6f4f5d05b39d5fcf428dc75fd7', token_count=1158, vector_point_id='ch-doc-card-614-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-614-7', 'doc-card-614', 'sec-card-614-3', 7, '«پاره‌وقت» و «پروژه‌ای» در رسانه؛ «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده است. • ریسک شغلی (Job Insecurity): «ناپایداری» کار رسانه‌ای؛ «مسابقه» و «فشار» در «عصر دیجیتال»، «ریسک» را «افزایش» داده است. • نقش حرفه‌ای (Professional Role): «نقش» روزنامه‌نگار، ویراستار، کارگردان، مدیر؛ «نقش‌ها»، «ساختار» کار را «تعیین» می‌کنند. • توسعه شغلی (Career Development): «مسیر» شغلی و «آموزش» مداوم؛ «توان» حرفه‌ای، «بازتولید» روزانه نیاز دارد.', '6b0e6d8e71d49df86b71221030f14b943240b5f58c4de60c1f73c41d0770e7ab', 785, 'ch-doc-card-614-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6b0e6d8e71d49df86b71221030f14b943240b5f58c4de60c1f73c41d0770e7ab', token_count=785, vector_point_id='ch-doc-card-614-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-614-8', 'doc-card-614', 'sec-card-614-4', 8, 'ک شغلی (Job Insecurity): «ناپایداری» کار رسانه‌ای؛ «مسابقه» و «فشار» در «عصر دیجیتال»، «ریسک» را «افزایش» داده است. • نقش حرفه‌ای (Professional Role): «نقش» روزنامه‌نگار، ویراستار، کارگردان، مدیر؛ «نقش‌ها»، «ساختار» کار را «تعیین» می‌کنند. • توسعه شغلی (Career Development): «مسیر» شغلی و «آموزش» مداوم؛ «توان» حرفه‌ای، «بازتولید» روزانه نیاز دارد.  ۳. نمونه‌های تحلیلی «حرفه‌ای‌سازی» در عمل: «روزنامه‌نگار» با «دوره» و «اصول» «حرفه‌ای» می‌شود: «اعتبار» از «آموزش» و «اصول» ساخته می‌شود.  «ساختار سازمانی» در عمل: «سلسله‌مراتب» در «تلفظ» (گزارشگر، ویراستار، مدیر) «رفتار» کارکنان را «تعیین» می‌کند: «سلسله‌مراتب»، «نقش» است.', '8062eaaf879ae6ca58432b9289fe7d378912da05281bcf68e651137cf88836b2', 1134, 'ch-doc-card-614-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8062eaaf879ae6ca58432b9289fe7d378912da05281bcf68e651137cf88836b2', token_count=1134, vector_point_id='ch-doc-card-614-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-614-9', 'doc-card-614', 'sec-card-614-4', 9, '، ویراستار، مدیر) «رفتار» کارکنان را «تعیین» می‌کند: «سلسله‌مراتب»، «نقش» است.  «کار پراکنده» در عمل: «مستقل» در «شبکه‌های اجتماعی» «محتوا» می‌سازد: «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده و «ریسک شغلی» «افزایش» یافته است.  «فرهنگ سازمانی» در عمل: «فرهنگ» «رقابت» در «رسانه‌ای» و «فرهنگ» «همکاری» در «رسانه‌ای» دیگر، «رفتار» کارکنان را «بازتولید» می‌کند: «فرهنگ»، «ساختار» است.  «مدیریت منابع انسانی» در عمل: «آموزش» «مداوم» «توان» حرفه‌ای را «حفظ» می‌کند: «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی رسانه است.  «ریسک شغلی» در «عصر دیجیتال»: «مسابقه» برای «نکست» و «فشار» «سرعت»، «کار» رسانه‌ای را «پراکنده» و «ناپایدار» کرده است: «استقلال» حرفه‌ای «تحت فشار» است.  ۴. نقدها و چالش‌ها ۱.', 'd93efc58fc5f7db9a37ef54a7de73693fc1e2f66801cdd0367735073346c4011', 1234, 'ch-doc-card-614-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d93efc58fc5f7db9a37ef54a7de73693fc1e2f66801cdd0367735073346c4011', token_count=1234, vector_point_id='ch-doc-card-614-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-614-10', 'doc-card-614', 'sec-card-614-4', 10, 'و «ناپایدار» کرده است: «استقلال» حرفه‌ای «تحت فشار» است.  ۴. نقدها و چالش‌ها ۱. «حرفه‌ای‌سازی» به «نقش‌پردازی» تقلیل می‌یابد: «اصول» به «نقش» تبدیل می‌شوند و «کار» به «نقش‌بازی»: «اعتبار» بدون «عمل» «معنا» ندارد. ۲. «ساختار سازمانی» در «عصر دیجیتال» «بازتعریف» می‌شود: «سلسله‌مراتب» کلاسیک در «پلتفرم‌ها» «عمل» نمی‌کند و «ساختار» «شبکه‌ای»، «بازتعریف» لازم دارد. ۳. «منابع انسانی» و «داده»: «ارزیابی» کارکنان با «داده» و «الگوریتم»، «حرفه‌ای‌بودن» را «ابزاری» می‌کند: «توان» به «داده» تبدی', '047e6a7bfac42dc65a3a9d842bb73e26f224b86494c26c29fab5a917780b05f2', 889, 'ch-doc-card-614-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='047e6a7bfac42dc65a3a9d842bb73e26f224b86494c26c29fab5a917780b05f2', token_count=889, vector_point_id='ch-doc-card-614-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
