INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-614-12', 'doc-card-614', 'sec-card-614-5', 12, '«توان» حرفه‌ای را «حفظ» می‌کند: «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی رسانه است.  «ریسک شغلی» در «عصر دیجیتال»: «مسابقه» برای «نکست» و «فشار» «سرعت»، «کار» رسانه‌ای را «پراکنده» و «ناپایدار» کرده است: «استقلال» حرفه‌ای «تحت فشار» است.', '714b07ad4f7a51079e90fad97f6ce548775ccc75495317d26370de2f83c7510d', 419, 'ch-doc-card-614-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='714b07ad4f7a51079e90fad97f6ce548775ccc75495317d26370de2f83c7510d', token_count=419, vector_point_id='ch-doc-card-614-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-614-13', 'doc-card-614', 'sec-card-614-6', 13, '۱. «حرفه‌ای‌سازی» به «نقش‌پردازی» تقلیل می‌یابد: «اصول» به «نقش» تبدیل می‌شوند و «کار» به «نقش‌بازی»: «اعتبار» بدون «عمل» «معنا» ندارد. ۲. «ساختار سازمانی» در «عصر دیجیتال» «بازتعریف» می‌شود: «سلسله‌مراتب» کلاسیک در «پلتفرم‌ها» «عمل» نمی‌کند و «ساختار» «شبکه‌ای»، «بازتعریف» لازم دارد. ۳. «منابع انسانی» و «داده»: «ارزیابی» کارکنان با «داده» و «الگوریتم»، «حرفه‌ای‌بودن» را «ابزاری» می‌کند: «توان» به «داده» تبدیل می‌شود. ۴. «کار پراکنده» و «اعتبار»: «مستقل» «حرفه‌ای» نیست و «اعتبار» ندارد: «مرز» بین «حرفه‌ای» و «مستقل»، «بازتعریف» لازم دارد. ۵. «فرهنگ سازمانی» و «قدرت»: «فرهنگ» در «سلسله‌مراتب»، «قدرت» است: «فرهنگ»', '2b6e87c0375f44acac0dbf50743587916b51216784afad745c61db32777925b4', 1125, 'ch-doc-card-614-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2b6e87c0375f44acac0dbf50743587916b51216784afad745c61db32777925b4', token_count=1125, vector_point_id='ch-doc-card-614-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-614-14', 'doc-card-614', 'sec-card-614-7', 14, '«رقابت»، «فشار» می‌سازد و «کار» را «استثمار» می‌کند. ۶. «توسعه شغلی» و «بازار»: «مسیر» شغلی در «بازار» «رقابت» «تعیین» می‌شود: «توان» حرفه‌ای «بازتولید» نمی‌شود و «کار» به «رقابت» تقلیل می‌یابد. ۷. «ریسک شغلی» در «بافت‌های دولتی» «عمیق‌تر» است: «فشار» «سیاسی» بر «کار» رسانه‌ای، «ریسک» را «افزایش» می‌دهد و «استقلال» حرفه‌ای «تحت فشار» است. ۸. «مدیریت منابع انسانی» و «حقوق»: «حقوق» کارکنان رسانه‌ای در «بازار» «رقابت» «تعیین» می‌شود: «سرمایه‌ی انسانی» «استثمار» می‌شود. ۹. «ساختار» و «نقش» در «عصر الگوریتم» «بازتعریف» می‌شوند: «الگوریتم»، «نقش» «کارکنان» را «تعیین» می‌کند و «ساختار» «سازمانی»، «بازتعریف» لازم دارد.', '59813802a8fd8b584b7cf5aaf1f17e5f784c089429ecd008c4916c8e5915090b', 1123, 'ch-doc-card-614-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='59813802a8fd8b584b7cf5aaf1f17e5f784c089429ecd008c4916c8e5915090b', token_count=1123, vector_point_id='ch-doc-card-614-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-614-15', 'doc-card-614', 'sec-card-614-10', 15, 'کتاب «حرفه‌ای‌سازی رسانه» (گارتنر و همکاران، ۱۹۸۶)؛ کتاب «سازمان رسانه‌ای» (تاکت و همکاران، ۱۹۹۰)؛ کتاب «کار پراکنده و رسانه» (بویل و همکاران، ۲۰۱۵)؛ کتاب «منابع انسانی در رسانه» (مورگان، ۲۰۰۴).', 'd88d82e7ec3cb842cb7f0755a7adc74d63d4eaf63470e287fa072ada619a6ae9', 352, 'ch-doc-card-614-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d88d82e7ec3cb842cb7f0755a7adc74d63d4eaf63470e287fa072ada619a6ae9', token_count=352, vector_point_id='ch-doc-card-614-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-615-0', 'doc-card-615', NULL, 0, 'نظریه Z کار رسانه‌ای را «حرفه‌ای‌سازی» (professionalization) می‌داند: رسانه، «نهاد» است و «حرفه‌ای» بودن، «اعتبار» می‌سازد. ویلیام اوچی (۱۹۸۱) در این چارچوب، «کار رسانه‌ای» را از «پیشه» به «حرفه» ارتقا داد: «اصول»، «نقش» و «نقش‌های» سازمانی، «ساختار» کار را «تعیین» می‌کنند. بر …', 'eb86e0c02f194b94e71c5225b9c63eaf48f6a94485b810a33b19c340b8725569', 507, 'ch-doc-card-615-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='eb86e0c02f194b94e71c5225b9c63eaf48f6a94485b810a33b19c340b8725569', token_count=507, vector_point_id='ch-doc-card-615-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-615-1', 'doc-card-615', 'sec-card-615-1', 1, 'منابع انسانی و کار رسانه‌ای  نظریه Z کار رسانه‌ای را «حرفه‌ای‌سازی» (professionalization) می‌داند: رسانه، «نهاد» است و «حرفه‌ای» بودن، «اعتبار» می‌سازد. ویلیام اوچی (۱۹۸۱) در این چارچوب، «کار رسانه‌ای» را از «پیشه» به «حرفه» ارتقا داد: «اصول»، «نقش» و «نقش‌های» سازمانی، «ساختار» کار را «تعیین» می‌کنند.  بر اساس نظریه Z، «سازمان رسانه‌ای» با «ساختار» و «فرهنگ» سازمانی «کار» را «بازتولید» می‌کند: «سلسله‌مراتب»، «نقش‌ها» و «فرهنگ» سازمانی، «رفتار» کارکنان را «شکل» می‌دهند. ویلیام اوچی (۱۹۸۱) در این چارچوب، «منابع انسانی» را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.', 'fa7d3065866dbb2ba2cecfe49fee16ad98f370ff437edf24994d088627034e28', 1092, 'ch-doc-card-615-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fa7d3065866dbb2ba2cecfe49fee16ad98f370ff437edf24994d088627034e28', token_count=1092, vector_point_id='ch-doc-card-615-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-615-2', 'doc-card-615', 'sec-card-615-1', 2, 'را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.  نظریه Z را می‌توان پاسخی به شکاف میان «سازمان کلاسیک» (سلسله‌مراتبی) و «سازمان دیجیتال» (شبکه‌ای) دانست: در «عصر دیجیتال»، «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده و «کار» رسانه‌ای به «کار پراکنده» (gig) تبدیل شده است. ویلیام اوچی (۱۹۸۱) در این چارچوب، «کار» را نه «پاره‌ای» از «سازمان» بلکه «جریان» در «بازار» تعریف کرد.', 'a2bfd82fd694621b2bfdc20d35d7e2529fb03e9fcbf4c196e156074d0aa3bb23', 725, 'ch-doc-card-615-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a2bfd82fd694621b2bfdc20d35d7e2529fb03e9fcbf4c196e156074d0aa3bb23', token_count=725, vector_point_id='ch-doc-card-615-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-615-3', 'doc-card-615', 'sec-card-615-2', 3, '۱. بنیان و منطق نظری نظریه Z کار رسانه‌ای را «حرفه‌ای‌سازی» (professionalization) می‌داند: رسانه، «نهاد» است و «حرفه‌ای» بودن، «اعتبار» می‌سازد. ویلیام اوچی (۱۹۸۱) در این چارچوب، «کار رسانه‌ای» را از «پیشه» به «حرفه» ارتقا داد: «اصول»، «نقش» و «نقش‌های» سازمانی، «ساختار» کار را «تعیین» می‌کنند.  بر اساس نظریه Z، «سازمان رسانه‌ای» با «ساختار» و «فرهنگ» سازمانی «کار» را «بازتولید» می‌کند: «سلسله‌مراتب»، «نقش‌ها» و «فرهنگ» سازمانی، «رفتار» کارکنان را «شکل» می‌دهند. ویلیام اوچی (۱۹۸۱) در این چارچوب، «منابع انسانی» را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.', 'cb69bf659af2235644fc9068f6029aa889486ae236ac8b28e2980240616a781a', 1078, 'ch-doc-card-615-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cb69bf659af2235644fc9068f6029aa889486ae236ac8b28e2980240616a781a', token_count=1078, vector_point_id='ch-doc-card-615-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-615-4', 'doc-card-615', 'sec-card-615-2', 4, 'را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.  نظریه Z را می‌توان پاسخی به شکاف میان «سازمان کلاسیک» (سلسله‌مراتبی) و «سازمان دیجیتال» (شبکه‌ای) دانست: در «عصر دیجیتال»، «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده و «کار» رسانه‌ای به «کار پراکنده» (gig) تبدیل شده است. ویلیام اوچی (۱۹۸۱) در این چارچوب، «کار» را نه «پاره‌ای» از «سازمان» بلکه «جریان» در «بازار» تعریف کرد.  ۲. ساختارهای مفهومی • حرفه‌ای‌سازی (Professionalization): فرایند «حرفه‌ای» شدن کار رسانه‌ای: «اصول»، «نقش» و «نقش‌های» سازمانی؛ «اعتبار» و «استقلال».', 'a53a3224edeef8144905c170921d1534889e490691d55b98eb42e31e308ea9d7', 999, 'ch-doc-card-615-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a53a3224edeef8144905c170921d1534889e490691d55b98eb42e31e308ea9d7', token_count=999, vector_point_id='ch-doc-card-615-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-615-5', 'doc-card-615', 'sec-card-615-2', 5, '‌ای» شدن کار رسانه‌ای: «اصول»، «نقش» و «نقش‌های» سازمانی؛ «اعتبار» و «استقلال». • ساختار سازمانی (Organizational Structure): «سلسله‌مراتب»، «نقش‌ها» و «مسئولیت‌ها» در رسانه؛ «ساختار»، «رفتار» کارکنان را «شکل» می‌دهد. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها»، «باورها» و «نمادها» در رسانه؛ «فرهنگ»، «رفتار» را «بازتولید» می‌کند. • مدیریت منابع انسانی (HR Management): «جذب»، «آموزش»، «ارزیابی» و «حفظ» «توان» حرفه‌ای؛ «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی است. • کار پراکنده (Gig Work): «کار» «مستقل»، «پاره‌وقت» و «پروژه‌ای» در رسانه؛ «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده است. • ریسک شغلی (Job Insecurity): «ناپ', '7fe402cb284dcc19121b8c8bd678192604b7223383aebd70e7076dcf385523e9', 1130, 'ch-doc-card-615-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7fe402cb284dcc19121b8c8bd678192604b7223383aebd70e7076dcf385523e9', token_count=1130, vector_point_id='ch-doc-card-615-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-615-6', 'doc-card-615', 'sec-card-615-3', 6, '• حرفه‌ای‌سازی (Professionalization): فرایند «حرفه‌ای» شدن کار رسانه‌ای: «اصول»، «نقش» و «نقش‌های» سازمانی؛ «اعتبار» و «استقلال». • ساختار سازمانی (Organizational Structure): «سلسله‌مراتب»، «نقش‌ها» و «مسئولیت‌ها» در رسانه؛ «ساختار»، «رفتار» کارکنان را «شکل» می‌دهد. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها»، «باورها» و «نمادها» در رسانه؛ «فرهنگ»، «رفتار» را «بازتولید» می‌کند. • مدیریت منابع انسانی (HR Management): «جذب»، «آموزش»، «ارزیابی» و «حفظ» «توان» حرفه‌ای؛ «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی است. • کار پراکنده (Gig Work): «کار» «مستقل»، «پاره‌وقت» و «پروژه‌ای» در رسانه؛ «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده است.', '8ed776a62c1398c2193e6cdfcbb731d44985ab6f4f5d05b39d5fcf428dc75fd7', 1158, 'ch-doc-card-615-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8ed776a62c1398c2193e6cdfcbb731d44985ab6f4f5d05b39d5fcf428dc75fd7', token_count=1158, vector_point_id='ch-doc-card-615-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-615-7', 'doc-card-615', 'sec-card-615-3', 7, '«پاره‌وقت» و «پروژه‌ای» در رسانه؛ «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده است. • ریسک شغلی (Job Insecurity): «ناپایداری» کار رسانه‌ای؛ «مسابقه» و «فشار» در «عصر دیجیتال»، «ریسک» را «افزایش» داده است. • نقش حرفه‌ای (Professional Role): «نقش» روزنامه‌نگار، ویراستار، کارگردان، مدیر؛ «نقش‌ها»، «ساختار» کار را «تعیین» می‌کنند. • توسعه شغلی (Career Development): «مسیر» شغلی و «آموزش» مداوم؛ «توان» حرفه‌ای، «بازتولید» روزانه نیاز دارد.', '6b0e6d8e71d49df86b71221030f14b943240b5f58c4de60c1f73c41d0770e7ab', 785, 'ch-doc-card-615-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6b0e6d8e71d49df86b71221030f14b943240b5f58c4de60c1f73c41d0770e7ab', token_count=785, vector_point_id='ch-doc-card-615-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-615-8', 'doc-card-615', 'sec-card-615-4', 8, 'ایداری» کار رسانه‌ای؛ «مسابقه» و «فشار» در «عصر دیجیتال»، «ریسک» را «افزایش» داده است. • نقش حرفه‌ای (Professional Role): «نقش» روزنامه‌نگار، ویراستار، کارگردان، مدیر؛ «نقش‌ها»، «ساختار» کار را «تعیین» می‌کنند. • توسعه شغلی (Career Development): «مسیر» شغلی و «آموزش» مداوم؛ «توان» حرفه‌ای، «بازتولید» روزانه نیاز دارد.  ۳. نمونه‌های تحلیلی «حرفه‌ای‌سازی» در عمل: «روزنامه‌نگار» با «دوره» و «اصول» «حرفه‌ای» می‌شود: «اعتبار» از «آموزش» و «اصول» ساخته می‌شود.  «ساختار سازمانی» در عمل: «سلسله‌مراتب» در «تلفظ» (گزارشگر، ویراستار، مدیر) «رفتار» کارکنان را «تعیین» می‌کند: «سلسله‌مراتب»، «نقش» است.', '9cd82c864ab28f9d697f6767dbda2e2a8025772a3f4aeca5ccf27beeb9858b62', 1081, 'ch-doc-card-615-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9cd82c864ab28f9d697f6767dbda2e2a8025772a3f4aeca5ccf27beeb9858b62', token_count=1081, vector_point_id='ch-doc-card-615-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-615-9', 'doc-card-615', 'sec-card-615-4', 9, '، ویراستار، مدیر) «رفتار» کارکنان را «تعیین» می‌کند: «سلسله‌مراتب»، «نقش» است.  «کار پراکنده» در عمل: «مستقل» در «شبکه‌های اجتماعی» «محتوا» می‌سازد: «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده و «ریسک شغلی» «افزایش» یافته است.  «فرهنگ سازمانی» در عمل: «فرهنگ» «رقابت» در «رسانه‌ای» و «فرهنگ» «همکاری» در «رسانه‌ای» دیگر، «رفتار» کارکنان را «بازتولید» می‌کند: «فرهنگ»، «ساختار» است.  «مدیریت منابع انسانی» در عمل: «آموزش» «مداوم» «توان» حرفه‌ای را «حفظ» می‌کند: «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی رسانه است.  «ریسک شغلی» در «عصر دیجیتال»: «مسابقه» برای «نکست» و «فشار» «سرعت»، «کار» رسانه‌ای را «پراکنده» و «ناپایدار» کرده است: «استقلال» حرفه‌ای «تحت فشار» است.  ۴. نقدها و چالش‌ها ۱.', 'd93efc58fc5f7db9a37ef54a7de73693fc1e2f66801cdd0367735073346c4011', 1234, 'ch-doc-card-615-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d93efc58fc5f7db9a37ef54a7de73693fc1e2f66801cdd0367735073346c4011', token_count=1234, vector_point_id='ch-doc-card-615-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-615-10', 'doc-card-615', 'sec-card-615-4', 10, 'و «ناپایدار» کرده است: «استقلال» حرفه‌ای «تحت فشار» است.  ۴. نقدها و چالش‌ها ۱. «حرفه‌ای‌سازی» به «نقش‌پردازی» تقلیل می‌یابد: «اصول» به «نقش» تبدیل می‌شوند و «کار» به «نقش‌بازی»: «اعتبار» بدون «عمل» «معنا» ندارد. ۲. «ساختار سازمانی» در «عصر دیجیتال» «بازتعریف» می‌شود: «سلسله‌مراتب» کلاسیک در «پلتفرم‌ها» «عمل» نمی‌کند و «ساختار» «شبکه‌ای»، «بازتعریف» لازم دارد. ۳. «منابع انسانی» و «داده»: «ارزیابی» کارکنان با «داده» و «الگوریتم»، «حرفه‌ای‌بودن» را «ابزاری» می‌کند: «توان» به «داده» تبدیل م', '275dbdbb5296ef819adaa0ddd7d654ea1750a1415ecf086b8cff13666e50a397', 894, 'ch-doc-card-615-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='275dbdbb5296ef819adaa0ddd7d654ea1750a1415ecf086b8cff13666e50a397', token_count=894, vector_point_id='ch-doc-card-615-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
