INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-632-12', 'doc-card-632', 'sec-card-632-5', 12, '«توان» حرفه‌ای را «حفظ» می‌کند: «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی رسانه است.  «ریسک شغلی» در «عصر دیجیتال»: «مسابقه» برای «نکست» و «فشار» «سرعت»، «کار» رسانه‌ای را «پراکنده» و «ناپایدار» کرده است: «استقلال» حرفه‌ای «تحت فشار» است.', '714b07ad4f7a51079e90fad97f6ce548775ccc75495317d26370de2f83c7510d', 419, 'ch-doc-card-632-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='714b07ad4f7a51079e90fad97f6ce548775ccc75495317d26370de2f83c7510d', token_count=419, vector_point_id='ch-doc-card-632-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-632-13', 'doc-card-632', 'sec-card-632-6', 13, '۱. «حرفه‌ای‌سازی» به «نقش‌پردازی» تقلیل می‌یابد: «اصول» به «نقش» تبدیل می‌شوند و «کار» به «نقش‌بازی»: «اعتبار» بدون «عمل» «معنا» ندارد. ۲. «ساختار سازمانی» در «عصر دیجیتال» «بازتعریف» می‌شود: «سلسله‌مراتب» کلاسیک در «پلتفرم‌ها» «عمل» نمی‌کند و «ساختار» «شبکه‌ای»، «بازتعریف» لازم دارد. ۳. «منابع انسانی» و «داده»: «ارزیابی» کارکنان با «داده» و «الگوریتم»، «حرفه‌ای‌بودن» را «ابزاری» می‌کند: «توان» به «داده» تبدیل می‌شود. ۴. «کار پراکنده» و «اعتبار»: «مستقل» «حرفه‌ای» نیست و «اعتبار» ندارد: «مرز» بین «حرفه‌ای» و «مستقل»، «بازتعریف» لازم دارد. ۵. «فرهنگ سازمانی» و «قدرت»: «فرهنگ» در «سلسله‌مراتب»، «قدرت» است: «فرهنگ»', '2b6e87c0375f44acac0dbf50743587916b51216784afad745c61db32777925b4', 1125, 'ch-doc-card-632-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2b6e87c0375f44acac0dbf50743587916b51216784afad745c61db32777925b4', token_count=1125, vector_point_id='ch-doc-card-632-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-632-14', 'doc-card-632', 'sec-card-632-7', 14, '«رقابت»، «فشار» می‌سازد و «کار» را «استثمار» می‌کند. ۶. «توسعه شغلی» و «بازار»: «مسیر» شغلی در «بازار» «رقابت» «تعیین» می‌شود: «توان» حرفه‌ای «بازتولید» نمی‌شود و «کار» به «رقابت» تقلیل می‌یابد. ۷. «ریسک شغلی» در «بافت‌های دولتی» «عمیق‌تر» است: «فشار» «سیاسی» بر «کار» رسانه‌ای، «ریسک» را «افزایش» می‌دهد و «استقلال» حرفه‌ای «تحت فشار» است. ۸. «مدیریت منابع انسانی» و «حقوق»: «حقوق» کارکنان رسانه‌ای در «بازار» «رقابت» «تعیین» می‌شود: «سرمایه‌ی انسانی» «استثمار» می‌شود. ۹. «ساختار» و «نقش» در «عصر الگوریتم» «بازتعریف» می‌شوند: «الگوریتم»، «نقش» «کارکنان» را «تعیین» می‌کند و «ساختار» «سازمانی»، «بازتعریف» لازم دارد.', '59813802a8fd8b584b7cf5aaf1f17e5f784c089429ecd008c4916c8e5915090b', 1123, 'ch-doc-card-632-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='59813802a8fd8b584b7cf5aaf1f17e5f784c089429ecd008c4916c8e5915090b', token_count=1123, vector_point_id='ch-doc-card-632-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-632-15', 'doc-card-632', 'sec-card-632-10', 15, 'کتاب «حرفه‌ای‌سازی رسانه» (گارتنر و همکاران، ۱۹۸۶)؛ کتاب «سازمان رسانه‌ای» (تاکت و همکاران، ۱۹۹۰)؛ کتاب «کار پراکنده و رسانه» (بویل و همکاران، ۲۰۱۵)؛ کتاب «منابع انسانی در رسانه» (مورگان، ۲۰۰۴).', 'd88d82e7ec3cb842cb7f0755a7adc74d63d4eaf63470e287fa072ada619a6ae9', 352, 'ch-doc-card-632-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d88d82e7ec3cb842cb7f0755a7adc74d63d4eaf63470e287fa072ada619a6ae9', token_count=352, vector_point_id='ch-doc-card-632-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-633-0', 'doc-card-633', NULL, 0, 'رهبری موقعیتی کار رسانه‌ای را «حرفه‌ای‌سازی» (professionalization) می‌داند: رسانه، «نهاد» است و «حرفه‌ای» بودن، «اعتبار» می‌سازد. هرسی (۱۹۶۹) در این چارچوب، «کار رسانه‌ای» را از «پیشه» به «حرفه» ارتقا داد: «اصول»، «نقش» و «نقش‌های» سازمانی، «ساختار» کار را «تعیین» می‌کنند. بر …', '93ab35fbd1fc9a8cc7e41eaec044b994493c7cd4750759b731a68ced7d6f7be9', 505, 'ch-doc-card-633-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='93ab35fbd1fc9a8cc7e41eaec044b994493c7cd4750759b731a68ced7d6f7be9', token_count=505, vector_point_id='ch-doc-card-633-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-633-1', 'doc-card-633', 'sec-card-633-1', 1, 'منابع انسانی و کار رسانه‌ای  رهبری موقعیتی کار رسانه‌ای را «حرفه‌ای‌سازی» (professionalization) می‌داند: رسانه، «نهاد» است و «حرفه‌ای» بودن، «اعتبار» می‌سازد. هرسی (۱۹۶۹) در این چارچوب، «کار رسانه‌ای» را از «پیشه» به «حرفه» ارتقا داد: «اصول»، «نقش» و «نقش‌های» سازمانی، «ساختار» کار را «تعیین» می‌کنند.  بر اساس رهبری موقعیتی، «سازمان رسانه‌ای» با «ساختار» و «فرهنگ» سازمانی «کار» را «بازتولید» می‌کند: «سلسله‌مراتب»، «نقش‌ها» و «فرهنگ» سازمانی، «رفتار» کارکنان را «شکل» می‌دهند. هرسی (۱۹۶۹) در این چارچوب، «منابع انسانی» را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.', 'b471beb666d34d6e35fd47beb0c30d48a3a67319661d748c07c1377a422c098c', 1089, 'ch-doc-card-633-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b471beb666d34d6e35fd47beb0c30d48a3a67319661d748c07c1377a422c098c', token_count=1089, vector_point_id='ch-doc-card-633-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-633-2', 'doc-card-633', 'sec-card-633-1', 2, 'را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.  رهبری موقعیتی را می‌توان پاسخی به شکاف میان «سازمان کلاسیک» (سلسله‌مراتبی) و «سازمان دیجیتال» (شبکه‌ای) دانست: در «عصر دیجیتال»، «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده و «کار» رسانه‌ای به «کار پراکنده» (gig) تبدیل شده است. هرسی (۱۹۶۹) در این چارچوب، «کار» را نه «پاره‌ای» از «سازمان» بلکه «جریان» در «بازار» تعریف کرد.', '4ba8506aa50fd29290f84acc999734dc1d347a7aa3d7592d5f41b82876ce3380', 723, 'ch-doc-card-633-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4ba8506aa50fd29290f84acc999734dc1d347a7aa3d7592d5f41b82876ce3380', token_count=723, vector_point_id='ch-doc-card-633-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-633-3', 'doc-card-633', 'sec-card-633-2', 3, '۱. بنیان و منطق نظری رهبری موقعیتی کار رسانه‌ای را «حرفه‌ای‌سازی» (professionalization) می‌داند: رسانه، «نهاد» است و «حرفه‌ای» بودن، «اعتبار» می‌سازد. هرسی (۱۹۶۹) در این چارچوب، «کار رسانه‌ای» را از «پیشه» به «حرفه» ارتقا داد: «اصول»، «نقش» و «نقش‌های» سازمانی، «ساختار» کار را «تعیین» می‌کنند.  بر اساس رهبری موقعیتی، «سازمان رسانه‌ای» با «ساختار» و «فرهنگ» سازمانی «کار» را «بازتولید» می‌کند: «سلسله‌مراتب»، «نقش‌ها» و «فرهنگ» سازمانی، «رفتار» کارکنان را «شکل» می‌دهند. هرسی (۱۹۶۹) در این چارچوب، «منابع انسانی» را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.', 'b50d3ee62004c3a807ec602538e7490a680612aa27755cc5bd7105eb1cc1f9b0', 1074, 'ch-doc-card-633-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b50d3ee62004c3a807ec602538e7490a680612aa27755cc5bd7105eb1cc1f9b0', token_count=1074, vector_point_id='ch-doc-card-633-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-633-4', 'doc-card-633', 'sec-card-633-2', 4, 'را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.  رهبری موقعیتی را می‌توان پاسخی به شکاف میان «سازمان کلاسیک» (سلسله‌مراتبی) و «سازمان دیجیتال» (شبکه‌ای) دانست: در «عصر دیجیتال»، «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده و «کار» رسانه‌ای به «کار پراکنده» (gig) تبدیل شده است. هرسی (۱۹۶۹) در این چارچوب، «کار» را نه «پاره‌ای» از «سازمان» بلکه «جریان» در «بازار» تعریف کرد.  ۲. ساختارهای مفهومی • حرفه‌ای‌سازی (Professionalization): فرایند «حرفه‌ای» شدن کار رسانه‌ای: «اصول»، «نقش» و «نقش‌های» سازمانی؛ «اعتبار» و «استقلال».', '2add2be04a549f5900a5cd5dabadb0b95704c7ca15e1b621b9afa6adc2f01b3d', 998, 'ch-doc-card-633-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2add2be04a549f5900a5cd5dabadb0b95704c7ca15e1b621b9afa6adc2f01b3d', token_count=998, vector_point_id='ch-doc-card-633-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-633-5', 'doc-card-633', 'sec-card-633-2', 5, '‌ای» شدن کار رسانه‌ای: «اصول»، «نقش» و «نقش‌های» سازمانی؛ «اعتبار» و «استقلال». • ساختار سازمانی (Organizational Structure): «سلسله‌مراتب»، «نقش‌ها» و «مسئولیت‌ها» در رسانه؛ «ساختار»، «رفتار» کارکنان را «شکل» می‌دهد. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها»، «باورها» و «نمادها» در رسانه؛ «فرهنگ»، «رفتار» را «بازتولید» می‌کند. • مدیریت منابع انسانی (HR Management): «جذب»، «آموزش»، «ارزیابی» و «حفظ» «توان» حرفه‌ای؛ «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی است. • کار پراکنده (Gig Work): «کار» «مستقل»، «پاره‌وقت» و «پروژه‌ای» در رسانه؛ «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده است. • ریسک شغلی (Job Insecurity): «ناپایدا', '39bec2d0a4c9eeae6569d5a1bc412261759f7a46a48aaa39287bd3fda2f2924c', 1138, 'ch-doc-card-633-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='39bec2d0a4c9eeae6569d5a1bc412261759f7a46a48aaa39287bd3fda2f2924c', token_count=1138, vector_point_id='ch-doc-card-633-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-633-6', 'doc-card-633', 'sec-card-633-3', 6, '• حرفه‌ای‌سازی (Professionalization): فرایند «حرفه‌ای» شدن کار رسانه‌ای: «اصول»، «نقش» و «نقش‌های» سازمانی؛ «اعتبار» و «استقلال». • ساختار سازمانی (Organizational Structure): «سلسله‌مراتب»، «نقش‌ها» و «مسئولیت‌ها» در رسانه؛ «ساختار»، «رفتار» کارکنان را «شکل» می‌دهد. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها»، «باورها» و «نمادها» در رسانه؛ «فرهنگ»، «رفتار» را «بازتولید» می‌کند. • مدیریت منابع انسانی (HR Management): «جذب»، «آموزش»، «ارزیابی» و «حفظ» «توان» حرفه‌ای؛ «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی است. • کار پراکنده (Gig Work): «کار» «مستقل»، «پاره‌وقت» و «پروژه‌ای» در رسانه؛ «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده است.', '8ed776a62c1398c2193e6cdfcbb731d44985ab6f4f5d05b39d5fcf428dc75fd7', 1158, 'ch-doc-card-633-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8ed776a62c1398c2193e6cdfcbb731d44985ab6f4f5d05b39d5fcf428dc75fd7', token_count=1158, vector_point_id='ch-doc-card-633-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-633-7', 'doc-card-633', 'sec-card-633-3', 7, '«پاره‌وقت» و «پروژه‌ای» در رسانه؛ «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده است. • ریسک شغلی (Job Insecurity): «ناپایداری» کار رسانه‌ای؛ «مسابقه» و «فشار» در «عصر دیجیتال»، «ریسک» را «افزایش» داده است. • نقش حرفه‌ای (Professional Role): «نقش» روزنامه‌نگار، ویراستار، کارگردان، مدیر؛ «نقش‌ها»، «ساختار» کار را «تعیین» می‌کنند. • توسعه شغلی (Career Development): «مسیر» شغلی و «آموزش» مداوم؛ «توان» حرفه‌ای، «بازتولید» روزانه نیاز دارد.', '6b0e6d8e71d49df86b71221030f14b943240b5f58c4de60c1f73c41d0770e7ab', 785, 'ch-doc-card-633-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6b0e6d8e71d49df86b71221030f14b943240b5f58c4de60c1f73c41d0770e7ab', token_count=785, vector_point_id='ch-doc-card-633-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-633-8', 'doc-card-633', 'sec-card-633-4', 8, 'ری» کار رسانه‌ای؛ «مسابقه» و «فشار» در «عصر دیجیتال»، «ریسک» را «افزایش» داده است. • نقش حرفه‌ای (Professional Role): «نقش» روزنامه‌نگار، ویراستار، کارگردان، مدیر؛ «نقش‌ها»، «ساختار» کار را «تعیین» می‌کنند. • توسعه شغلی (Career Development): «مسیر» شغلی و «آموزش» مداوم؛ «توان» حرفه‌ای، «بازتولید» روزانه نیاز دارد.  ۳. نمونه‌های تحلیلی «حرفه‌ای‌سازی» در عمل: «روزنامه‌نگار» با «دوره» و «اصول» «حرفه‌ای» می‌شود: «اعتبار» از «آموزش» و «اصول» ساخته می‌شود.  «ساختار سازمانی» در عمل: «سلسله‌مراتب» در «تلفظ» (گزارشگر، ویراستار، مدیر) «رفتار» کارکنان را «تعیین» می‌کند: «سلسله‌مراتب»، «نقش» است.', '82df242ca01d0fdbfe6b62abab5271a2e32661b037ca3f5a2f488ee4aea034b3', 1074, 'ch-doc-card-633-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='82df242ca01d0fdbfe6b62abab5271a2e32661b037ca3f5a2f488ee4aea034b3', token_count=1074, vector_point_id='ch-doc-card-633-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-633-9', 'doc-card-633', 'sec-card-633-4', 9, '، ویراستار، مدیر) «رفتار» کارکنان را «تعیین» می‌کند: «سلسله‌مراتب»، «نقش» است.  «کار پراکنده» در عمل: «مستقل» در «شبکه‌های اجتماعی» «محتوا» می‌سازد: «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده و «ریسک شغلی» «افزایش» یافته است.  «فرهنگ سازمانی» در عمل: «فرهنگ» «رقابت» در «رسانه‌ای» و «فرهنگ» «همکاری» در «رسانه‌ای» دیگر، «رفتار» کارکنان را «بازتولید» می‌کند: «فرهنگ»، «ساختار» است.  «مدیریت منابع انسانی» در عمل: «آموزش» «مداوم» «توان» حرفه‌ای را «حفظ» می‌کند: «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی رسانه است.  «ریسک شغلی» در «عصر دیجیتال»: «مسابقه» برای «نکست» و «فشار» «سرعت»، «کار» رسانه‌ای را «پراکنده» و «ناپایدار» کرده است: «استقلال» حرفه‌ای «تحت فشار» است.  ۴. نقدها و چالش‌ها ۱.', 'd93efc58fc5f7db9a37ef54a7de73693fc1e2f66801cdd0367735073346c4011', 1234, 'ch-doc-card-633-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d93efc58fc5f7db9a37ef54a7de73693fc1e2f66801cdd0367735073346c4011', token_count=1234, vector_point_id='ch-doc-card-633-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-633-10', 'doc-card-633', 'sec-card-633-4', 10, 'و «ناپایدار» کرده است: «استقلال» حرفه‌ای «تحت فشار» است.  ۴. نقدها و چالش‌ها ۱. «حرفه‌ای‌سازی» به «نقش‌پردازی» تقلیل می‌یابد: «اصول» به «نقش» تبدیل می‌شوند و «کار» به «نقش‌بازی»: «اعتبار» بدون «عمل» «معنا» ندارد. ۲. «ساختار سازمانی» در «عصر دیجیتال» «بازتعریف» می‌شود: «سلسله‌مراتب» کلاسیک در «پلتفرم‌ها» «عمل» نمی‌کند و «ساختار» «شبکه‌ای»، «بازتعریف» لازم دارد. ۳. «منابع انسانی» و «داده»: «ارزیابی» کارکنان با «داده» و «الگوریتم»، «حرفه‌ای‌بودن» را «ابزاری» می‌کند: «توان» به «داده» تبدیل می‌شود', '05583d3b5a2da314f6f76464d2b35fe88e963431d8a5aa01b13ca08a0ceff064', 903, 'ch-doc-card-633-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='05583d3b5a2da314f6f76464d2b35fe88e963431d8a5aa01b13ca08a0ceff064', token_count=903, vector_point_id='ch-doc-card-633-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-633-11', 'doc-card-633', 'sec-card-633-5', 11, '«حرفه‌ای‌سازی» در عمل: «روزنامه‌نگار» با «دوره» و «اصول» «حرفه‌ای» می‌شود: «اعتبار» از «آموزش» و «اصول» ساخته می‌شود.  «ساختار سازمانی» در عمل: «سلسله‌مراتب» در «تلفظ» (گزارشگر، ویراستار، مدیر) «رفتار» کارکنان را «تعیین» می‌کند: «سلسله‌مراتب»، «نقش» است.  «کار پراکنده» در عمل: «مستقل» در «شبکه‌های اجتماعی» «محتوا» می‌سازد: «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده و «ریسک شغلی» «افزایش» یافته است.  «فرهنگ سازمانی» در عمل: «فرهنگ» «رقابت» در «رسانه‌ای» و «فرهنگ» «همکاری» در «رسانه‌ای» دیگر، «رفتار» کارکنان را «بازتولید» می‌کند: «فرهنگ»، «ساختار» است.  «مدیریت منابع انسانی» در عمل: «آموزش» «مداوم» «توان» حرفه‌ای را «حفظ» می‌کند: «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی رسانه است.', '6a68e2945ec469e28fc56bba76efd3d7d13bcbee407858fe8e6060d48d54e96b', 1232, 'ch-doc-card-633-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6a68e2945ec469e28fc56bba76efd3d7d13bcbee407858fe8e6060d48d54e96b', token_count=1232, vector_point_id='ch-doc-card-633-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-633-12', 'doc-card-633', 'sec-card-633-5', 12, '«توان» حرفه‌ای را «حفظ» می‌کند: «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی رسانه است.  «ریسک شغلی» در «عصر دیجیتال»: «مسابقه» برای «نکست» و «فشار» «سرعت»، «کار» رسانه‌ای را «پراکنده» و «ناپایدار» کرده است: «استقلال» حرفه‌ای «تحت فشار» است.', '714b07ad4f7a51079e90fad97f6ce548775ccc75495317d26370de2f83c7510d', 419, 'ch-doc-card-633-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='714b07ad4f7a51079e90fad97f6ce548775ccc75495317d26370de2f83c7510d', token_count=419, vector_point_id='ch-doc-card-633-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-633-13', 'doc-card-633', 'sec-card-633-6', 13, '۱. «حرفه‌ای‌سازی» به «نقش‌پردازی» تقلیل می‌یابد: «اصول» به «نقش» تبدیل می‌شوند و «کار» به «نقش‌بازی»: «اعتبار» بدون «عمل» «معنا» ندارد. ۲. «ساختار سازمانی» در «عصر دیجیتال» «بازتعریف» می‌شود: «سلسله‌مراتب» کلاسیک در «پلتفرم‌ها» «عمل» نمی‌کند و «ساختار» «شبکه‌ای»، «بازتعریف» لازم دارد. ۳. «منابع انسانی» و «داده»: «ارزیابی» کارکنان با «داده» و «الگوریتم»، «حرفه‌ای‌بودن» را «ابزاری» می‌کند: «توان» به «داده» تبدیل می‌شود. ۴. «کار پراکنده» و «اعتبار»: «مستقل» «حرفه‌ای» نیست و «اعتبار» ندارد: «مرز» بین «حرفه‌ای» و «مستقل»، «بازتعریف» لازم دارد. ۵. «فرهنگ سازمانی» و «قدرت»: «فرهنگ» در «سلسله‌مراتب»، «قدرت» است: «فرهنگ»', '2b6e87c0375f44acac0dbf50743587916b51216784afad745c61db32777925b4', 1125, 'ch-doc-card-633-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2b6e87c0375f44acac0dbf50743587916b51216784afad745c61db32777925b4', token_count=1125, vector_point_id='ch-doc-card-633-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-633-14', 'doc-card-633', 'sec-card-633-7', 14, '«رقابت»، «فشار» می‌سازد و «کار» را «استثمار» می‌کند. ۶. «توسعه شغلی» و «بازار»: «مسیر» شغلی در «بازار» «رقابت» «تعیین» می‌شود: «توان» حرفه‌ای «بازتولید» نمی‌شود و «کار» به «رقابت» تقلیل می‌یابد. ۷. «ریسک شغلی» در «بافت‌های دولتی» «عمیق‌تر» است: «فشار» «سیاسی» بر «کار» رسانه‌ای، «ریسک» را «افزایش» می‌دهد و «استقلال» حرفه‌ای «تحت فشار» است. ۸. «مدیریت منابع انسانی» و «حقوق»: «حقوق» کارکنان رسانه‌ای در «بازار» «رقابت» «تعیین» می‌شود: «سرمایه‌ی انسانی» «استثمار» می‌شود. ۹. «ساختار» و «نقش» در «عصر الگوریتم» «بازتعریف» می‌شوند: «الگوریتم»، «نقش» «کارکنان» را «تعیین» می‌کند و «ساختار» «سازمانی»، «بازتعریف» لازم دارد.', '59813802a8fd8b584b7cf5aaf1f17e5f784c089429ecd008c4916c8e5915090b', 1123, 'ch-doc-card-633-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='59813802a8fd8b584b7cf5aaf1f17e5f784c089429ecd008c4916c8e5915090b', token_count=1123, vector_point_id='ch-doc-card-633-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-633-15', 'doc-card-633', 'sec-card-633-10', 15, 'کتاب «حرفه‌ای‌سازی رسانه» (گارتنر و همکاران، ۱۹۸۶)؛ کتاب «سازمان رسانه‌ای» (تاکت و همکاران، ۱۹۹۰)؛ کتاب «کار پراکنده و رسانه» (بویل و همکاران، ۲۰۱۵)؛ کتاب «منابع انسانی در رسانه» (مورگان، ۲۰۰۴).', 'd88d82e7ec3cb842cb7f0755a7adc74d63d4eaf63470e287fa072ada619a6ae9', 352, 'ch-doc-card-633-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d88d82e7ec3cb842cb7f0755a7adc74d63d4eaf63470e287fa072ada619a6ae9', token_count=352, vector_point_id='ch-doc-card-633-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-634-0', 'doc-card-634', NULL, 0, 'رهبری خدمتگزار کار رسانه‌ای را «حرفه‌ای‌سازی» (professionalization) می‌داند: رسانه، «نهاد» است و «حرفه‌ای» بودن، «اعتبار» می‌سازد. گرینلیف (۱۹۷۰) در این چارچوب، «کار رسانه‌ای» را از «پیشه» به «حرفه» ارتقا داد: «اصول»، «نقش» و «نقش‌های» سازمانی، «ساختار» کار را «تعیین» می‌کنند …', '7e4ab008f2d7dda685c833928329de486865e688fdf045ee97851c0179139c3f', 505, 'ch-doc-card-634-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7e4ab008f2d7dda685c833928329de486865e688fdf045ee97851c0179139c3f', token_count=505, vector_point_id='ch-doc-card-634-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-634-1', 'doc-card-634', 'sec-card-634-1', 1, 'منابع انسانی و کار رسانه‌ای  رهبری خدمتگزار کار رسانه‌ای را «حرفه‌ای‌سازی» (professionalization) می‌داند: رسانه، «نهاد» است و «حرفه‌ای» بودن، «اعتبار» می‌سازد. گرینلیف (۱۹۷۰) در این چارچوب، «کار رسانه‌ای» را از «پیشه» به «حرفه» ارتقا داد: «اصول»، «نقش» و «نقش‌های» سازمانی، «ساختار» کار را «تعیین» می‌کنند.  بر اساس رهبری خدمتگزار، «سازمان رسانه‌ای» با «ساختار» و «فرهنگ» سازمانی «کار» را «بازتولید» می‌کند: «سلسله‌مراتب»، «نقش‌ها» و «فرهنگ» سازمانی، «رفتار» کارکنان را «شکل» می‌دهند. گرینلیف (۱۹۷۰) در این چارچوب، «منابع انسانی» را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.', '98f02477600a7b4761115c94a409f4ed71a9fd635eac6ce0d0304947c90546f2', 1103, 'ch-doc-card-634-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='98f02477600a7b4761115c94a409f4ed71a9fd635eac6ce0d0304947c90546f2', token_count=1103, vector_point_id='ch-doc-card-634-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-634-2', 'doc-card-634', 'sec-card-634-1', 2, 'را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.  رهبری خدمتگزار را می‌توان پاسخی به شکاف میان «سازمان کلاسیک» (سلسله‌مراتبی) و «سازمان دیجیتال» (شبکه‌ای) دانست: در «عصر دیجیتال»، «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده و «کار» رسانه‌ای به «کار پراکنده» (gig) تبدیل شده است. گرینلیف (۱۹۷۰) در این چارچوب، «کار» را نه «پاره‌ای» از «سازمان» بلکه «جریان» در «بازار» تعریف کرد.', '0b43cc69ef2a11df3f8a771bd84b10af24b700ad87a7dd3283002badb66f6e90', 730, 'ch-doc-card-634-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0b43cc69ef2a11df3f8a771bd84b10af24b700ad87a7dd3283002badb66f6e90', token_count=730, vector_point_id='ch-doc-card-634-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-634-3', 'doc-card-634', 'sec-card-634-2', 3, '۱. بنیان و منطق نظری رهبری خدمتگزار کار رسانه‌ای را «حرفه‌ای‌سازی» (professionalization) می‌داند: رسانه، «نهاد» است و «حرفه‌ای» بودن، «اعتبار» می‌سازد. گرینلیف (۱۹۷۰) در این چارچوب، «کار رسانه‌ای» را از «پیشه» به «حرفه» ارتقا داد: «اصول»، «نقش» و «نقش‌های» سازمانی، «ساختار» کار را «تعیین» می‌کنند.  بر اساس رهبری خدمتگزار، «سازمان رسانه‌ای» با «ساختار» و «فرهنگ» سازمانی «کار» را «بازتولید» می‌کند: «سلسله‌مراتب»، «نقش‌ها» و «فرهنگ» سازمانی، «رفتار» کارکنان را «شکل» می‌دهند. گرینلیف (۱۹۷۰) در این چارچوب، «منابع انسانی» را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.', '7297178a2cb4b72617106b75270b210b016134513e17ddcc99fddae47f0f64e5', 1089, 'ch-doc-card-634-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7297178a2cb4b72617106b75270b210b016134513e17ddcc99fddae47f0f64e5', token_count=1089, vector_point_id='ch-doc-card-634-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-634-4', 'doc-card-634', 'sec-card-634-2', 4, 'را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.  رهبری خدمتگزار را می‌توان پاسخی به شکاف میان «سازمان کلاسیک» (سلسله‌مراتبی) و «سازمان دیجیتال» (شبکه‌ای) دانست: در «عصر دیجیتال»، «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده و «کار» رسانه‌ای به «کار پراکنده» (gig) تبدیل شده است. گرینلیف (۱۹۷۰) در این چارچوب، «کار» را نه «پاره‌ای» از «سازمان» بلکه «جریان» در «بازار» تعریف کرد.  ۲. ساختارهای مفهومی • حرفه‌ای‌سازی (Professionalization): فرایند «حرفه‌ای» شدن کار رسانه‌ای: «اصول»، «نقش» و «نقش‌های» سازمانی؛ «اعتبار» و «استقلال».', '6d8f5c3a54947fa3334960f559598792d68ba49e3bfadbc17d653bf0ed576b24', 1005, 'ch-doc-card-634-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6d8f5c3a54947fa3334960f559598792d68ba49e3bfadbc17d653bf0ed576b24', token_count=1005, vector_point_id='ch-doc-card-634-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-634-5', 'doc-card-634', 'sec-card-634-2', 5, '‌ای» شدن کار رسانه‌ای: «اصول»، «نقش» و «نقش‌های» سازمانی؛ «اعتبار» و «استقلال». • ساختار سازمانی (Organizational Structure): «سلسله‌مراتب»، «نقش‌ها» و «مسئولیت‌ها» در رسانه؛ «ساختار»، «رفتار» کارکنان را «شکل» می‌دهد. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها»، «باورها» و «نمادها» در رسانه؛ «فرهنگ»، «رفتار» را «بازتولید» می‌کند. • مدیریت منابع انسانی (HR Management): «جذب»، «آموزش»، «ارزیابی» و «حفظ» «توان» حرفه‌ای؛ «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی است. • کار پراکنده (Gig Work): «کار» «مستقل»، «پاره‌وقت» و «پروژه‌ای» در رسانه؛ «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده است. • ریسک شغلی (Job Insecurity):', '95574a1d2657761a22a4e40123f796f09cb5ab6034368cf58836584c8068ed56', 1121, 'ch-doc-card-634-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='95574a1d2657761a22a4e40123f796f09cb5ab6034368cf58836584c8068ed56', token_count=1121, vector_point_id='ch-doc-card-634-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-634-6', 'doc-card-634', 'sec-card-634-3', 6, '• حرفه‌ای‌سازی (Professionalization): فرایند «حرفه‌ای» شدن کار رسانه‌ای: «اصول»، «نقش» و «نقش‌های» سازمانی؛ «اعتبار» و «استقلال». • ساختار سازمانی (Organizational Structure): «سلسله‌مراتب»، «نقش‌ها» و «مسئولیت‌ها» در رسانه؛ «ساختار»، «رفتار» کارکنان را «شکل» می‌دهد. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها»، «باورها» و «نمادها» در رسانه؛ «فرهنگ»، «رفتار» را «بازتولید» می‌کند. • مدیریت منابع انسانی (HR Management): «جذب»، «آموزش»، «ارزیابی» و «حفظ» «توان» حرفه‌ای؛ «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی است. • کار پراکنده (Gig Work): «کار» «مستقل»، «پاره‌وقت» و «پروژه‌ای» در رسانه؛ «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده است.', '8ed776a62c1398c2193e6cdfcbb731d44985ab6f4f5d05b39d5fcf428dc75fd7', 1158, 'ch-doc-card-634-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8ed776a62c1398c2193e6cdfcbb731d44985ab6f4f5d05b39d5fcf428dc75fd7', token_count=1158, vector_point_id='ch-doc-card-634-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-634-7', 'doc-card-634', 'sec-card-634-3', 7, '«پاره‌وقت» و «پروژه‌ای» در رسانه؛ «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده است. • ریسک شغلی (Job Insecurity): «ناپایداری» کار رسانه‌ای؛ «مسابقه» و «فشار» در «عصر دیجیتال»، «ریسک» را «افزایش» داده است. • نقش حرفه‌ای (Professional Role): «نقش» روزنامه‌نگار، ویراستار، کارگردان، مدیر؛ «نقش‌ها»، «ساختار» کار را «تعیین» می‌کنند. • توسعه شغلی (Career Development): «مسیر» شغلی و «آموزش» مداوم؛ «توان» حرفه‌ای، «بازتولید» روزانه نیاز دارد.', '6b0e6d8e71d49df86b71221030f14b943240b5f58c4de60c1f73c41d0770e7ab', 785, 'ch-doc-card-634-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6b0e6d8e71d49df86b71221030f14b943240b5f58c4de60c1f73c41d0770e7ab', token_count=785, vector_point_id='ch-doc-card-634-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-634-8', 'doc-card-634', 'sec-card-634-4', 8, '«ناپایداری» کار رسانه‌ای؛ «مسابقه» و «فشار» در «عصر دیجیتال»، «ریسک» را «افزایش» داده است. • نقش حرفه‌ای (Professional Role): «نقش» روزنامه‌نگار، ویراستار، کارگردان، مدیر؛ «نقش‌ها»، «ساختار» کار را «تعیین» می‌کنند. • توسعه شغلی (Career Development): «مسیر» شغلی و «آموزش» مداوم؛ «توان» حرفه‌ای، «بازتولید» روزانه نیاز دارد.  ۳. نمونه‌های تحلیلی «حرفه‌ای‌سازی» در عمل: «روزنامه‌نگار» با «دوره» و «اصول» «حرفه‌ای» می‌شود: «اعتبار» از «آموزش» و «اصول» ساخته می‌شود.  «ساختار سازمانی» در عمل: «سلسله‌مراتب» در «تلفظ» (گزارشگر، ویراستار، مدیر) «رفتار» کارکنان را «تعیین» می‌کند: «سلسله‌مراتب»، «نقش» است.', '35870326e2d9251dd9522aa6076f1dd420c893101364c69e258b2c2bb8819558', 1089, 'ch-doc-card-634-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='35870326e2d9251dd9522aa6076f1dd420c893101364c69e258b2c2bb8819558', token_count=1089, vector_point_id='ch-doc-card-634-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-634-9', 'doc-card-634', 'sec-card-634-4', 9, '، ویراستار، مدیر) «رفتار» کارکنان را «تعیین» می‌کند: «سلسله‌مراتب»، «نقش» است.  «کار پراکنده» در عمل: «مستقل» در «شبکه‌های اجتماعی» «محتوا» می‌سازد: «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده و «ریسک شغلی» «افزایش» یافته است.  «فرهنگ سازمانی» در عمل: «فرهنگ» «رقابت» در «رسانه‌ای» و «فرهنگ» «همکاری» در «رسانه‌ای» دیگر، «رفتار» کارکنان را «بازتولید» می‌کند: «فرهنگ»، «ساختار» است.  «مدیریت منابع انسانی» در عمل: «آموزش» «مداوم» «توان» حرفه‌ای را «حفظ» می‌کند: «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی رسانه است.  «ریسک شغلی» در «عصر دیجیتال»: «مسابقه» برای «نکست» و «فشار» «سرعت»، «کار» رسانه‌ای را «پراکنده» و «ناپایدار» کرده است: «استقلال» حرفه‌ای «تحت فشار» است.  ۴. نقدها و چالش‌ها ۱.', 'd93efc58fc5f7db9a37ef54a7de73693fc1e2f66801cdd0367735073346c4011', 1234, 'ch-doc-card-634-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d93efc58fc5f7db9a37ef54a7de73693fc1e2f66801cdd0367735073346c4011', token_count=1234, vector_point_id='ch-doc-card-634-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-634-10', 'doc-card-634', 'sec-card-634-4', 10, 'و «ناپایدار» کرده است: «استقلال» حرفه‌ای «تحت فشار» است.  ۴. نقدها و چالش‌ها ۱. «حرفه‌ای‌سازی» به «نقش‌پردازی» تقلیل می‌یابد: «اصول» به «نقش» تبدیل می‌شوند و «کار» به «نقش‌بازی»: «اعتبار» بدون «عمل» «معنا» ندارد. ۲. «ساختار سازمانی» در «عصر دیجیتال» «بازتعریف» می‌شود: «سلسله‌مراتب» کلاسیک در «پلتفرم‌ها» «عمل» نمی‌کند و «ساختار» «شبکه‌ای»، «بازتعریف» لازم دارد. ۳. «منابع انسانی» و «داده»: «ارزیابی» کارکنان با «داده» و «الگوریتم»، «حرفه‌ای‌بودن» را «ابزاری» می‌کند: «توان» به «داده» تبدیل می', '6c2959a39e29ad463687e3f714f2a483574bc753f7e62192adaf3c41fc003443', 896, 'ch-doc-card-634-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6c2959a39e29ad463687e3f714f2a483574bc753f7e62192adaf3c41fc003443', token_count=896, vector_point_id='ch-doc-card-634-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
