INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-635-12', 'doc-card-635', 'sec-card-635-5', 12, '«توان» حرفه‌ای را «حفظ» می‌کند: «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی رسانه است.  «ریسک شغلی» در «عصر دیجیتال»: «مسابقه» برای «نکست» و «فشار» «سرعت»، «کار» رسانه‌ای را «پراکنده» و «ناپایدار» کرده است: «استقلال» حرفه‌ای «تحت فشار» است.', '714b07ad4f7a51079e90fad97f6ce548775ccc75495317d26370de2f83c7510d', 419, 'ch-doc-card-635-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='714b07ad4f7a51079e90fad97f6ce548775ccc75495317d26370de2f83c7510d', token_count=419, vector_point_id='ch-doc-card-635-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-635-13', 'doc-card-635', 'sec-card-635-6', 13, '۱. «حرفه‌ای‌سازی» به «نقش‌پردازی» تقلیل می‌یابد: «اصول» به «نقش» تبدیل می‌شوند و «کار» به «نقش‌بازی»: «اعتبار» بدون «عمل» «معنا» ندارد. ۲. «ساختار سازمانی» در «عصر دیجیتال» «بازتعریف» می‌شود: «سلسله‌مراتب» کلاسیک در «پلتفرم‌ها» «عمل» نمی‌کند و «ساختار» «شبکه‌ای»، «بازتعریف» لازم دارد. ۳. «منابع انسانی» و «داده»: «ارزیابی» کارکنان با «داده» و «الگوریتم»، «حرفه‌ای‌بودن» را «ابزاری» می‌کند: «توان» به «داده» تبدیل می‌شود. ۴. «کار پراکنده» و «اعتبار»: «مستقل» «حرفه‌ای» نیست و «اعتبار» ندارد: «مرز» بین «حرفه‌ای» و «مستقل»، «بازتعریف» لازم دارد. ۵. «فرهنگ سازمانی» و «قدرت»: «فرهنگ» در «سلسله‌مراتب»، «قدرت» است: «فرهنگ»', '2b6e87c0375f44acac0dbf50743587916b51216784afad745c61db32777925b4', 1125, 'ch-doc-card-635-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2b6e87c0375f44acac0dbf50743587916b51216784afad745c61db32777925b4', token_count=1125, vector_point_id='ch-doc-card-635-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-635-14', 'doc-card-635', 'sec-card-635-7', 14, '«رقابت»، «فشار» می‌سازد و «کار» را «استثمار» می‌کند. ۶. «توسعه شغلی» و «بازار»: «مسیر» شغلی در «بازار» «رقابت» «تعیین» می‌شود: «توان» حرفه‌ای «بازتولید» نمی‌شود و «کار» به «رقابت» تقلیل می‌یابد. ۷. «ریسک شغلی» در «بافت‌های دولتی» «عمیق‌تر» است: «فشار» «سیاسی» بر «کار» رسانه‌ای، «ریسک» را «افزایش» می‌دهد و «استقلال» حرفه‌ای «تحت فشار» است. ۸. «مدیریت منابع انسانی» و «حقوق»: «حقوق» کارکنان رسانه‌ای در «بازار» «رقابت» «تعیین» می‌شود: «سرمایه‌ی انسانی» «استثمار» می‌شود. ۹. «ساختار» و «نقش» در «عصر الگوریتم» «بازتعریف» می‌شوند: «الگوریتم»، «نقش» «کارکنان» را «تعیین» می‌کند و «ساختار» «سازمانی»، «بازتعریف» لازم دارد.', '59813802a8fd8b584b7cf5aaf1f17e5f784c089429ecd008c4916c8e5915090b', 1123, 'ch-doc-card-635-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='59813802a8fd8b584b7cf5aaf1f17e5f784c089429ecd008c4916c8e5915090b', token_count=1123, vector_point_id='ch-doc-card-635-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-635-15', 'doc-card-635', 'sec-card-635-10', 15, 'کتاب «حرفه‌ای‌سازی رسانه» (گارتنر و همکاران، ۱۹۸۶)؛ کتاب «سازمان رسانه‌ای» (تاکت و همکاران، ۱۹۹۰)؛ کتاب «کار پراکنده و رسانه» (بویل و همکاران، ۲۰۱۵)؛ کتاب «منابع انسانی در رسانه» (مورگان، ۲۰۰۴).', 'd88d82e7ec3cb842cb7f0755a7adc74d63d4eaf63470e287fa072ada619a6ae9', 352, 'ch-doc-card-635-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d88d82e7ec3cb842cb7f0755a7adc74d63d4eaf63470e287fa072ada619a6ae9', token_count=352, vector_point_id='ch-doc-card-635-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-636-0', 'doc-card-636', NULL, 0, 'برند کارفرما کار رسانه‌ای را «حرفه‌ای‌سازی» (professionalization) می‌داند: رسانه، «نهاد» است و «حرفه‌ای» بودن، «اعتبار» می‌سازد. امبلر (۱۹۹۶) در این چارچوب، «کار رسانه‌ای» را از «پیشه» به «حرفه» ارتقا داد: «اصول»، «نقش» و «نقش‌های» سازمانی، «ساختار» کار را «تعیین» می‌کنند. بر …', 'a1a62e615f124c18b1e8b8a8e51258fdfb5adf02e5359b4b91ca74cb7508c675', 505, 'ch-doc-card-636-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a1a62e615f124c18b1e8b8a8e51258fdfb5adf02e5359b4b91ca74cb7508c675', token_count=505, vector_point_id='ch-doc-card-636-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-636-1', 'doc-card-636', 'sec-card-636-1', 1, 'منابع انسانی و کار رسانه‌ای  برند کارفرما کار رسانه‌ای را «حرفه‌ای‌سازی» (professionalization) می‌داند: رسانه، «نهاد» است و «حرفه‌ای» بودن، «اعتبار» می‌سازد. امبلر (۱۹۹۶) در این چارچوب، «کار رسانه‌ای» را از «پیشه» به «حرفه» ارتقا داد: «اصول»، «نقش» و «نقش‌های» سازمانی، «ساختار» کار را «تعیین» می‌کنند.  بر اساس برند کارفرما، «سازمان رسانه‌ای» با «ساختار» و «فرهنگ» سازمانی «کار» را «بازتولید» می‌کند: «سلسله‌مراتب»، «نقش‌ها» و «فرهنگ» سازمانی، «رفتار» کارکنان را «شکل» می‌دهند. امبلر (۱۹۹۶) در این چارچوب، «منابع انسانی» را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.', '31b096fea25343ae537cdf00d7585612d5a0eea5477bce6aa344894e09e2322f', 1089, 'ch-doc-card-636-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='31b096fea25343ae537cdf00d7585612d5a0eea5477bce6aa344894e09e2322f', token_count=1089, vector_point_id='ch-doc-card-636-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-636-2', 'doc-card-636', 'sec-card-636-1', 2, 'را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.  برند کارفرما را می‌توان پاسخی به شکاف میان «سازمان کلاسیک» (سلسله‌مراتبی) و «سازمان دیجیتال» (شبکه‌ای) دانست: در «عصر دیجیتال»، «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده و «کار» رسانه‌ای به «کار پراکنده» (gig) تبدیل شده است. امبلر (۱۹۹۶) در این چارچوب، «کار» را نه «پاره‌ای» از «سازمان» بلکه «جریان» در «بازار» تعریف کرد.', '70d919927c878e9c06b8442a37ceb11d9d8dcedf13bb7363242b9f8643fd8008', 723, 'ch-doc-card-636-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='70d919927c878e9c06b8442a37ceb11d9d8dcedf13bb7363242b9f8643fd8008', token_count=723, vector_point_id='ch-doc-card-636-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-636-3', 'doc-card-636', 'sec-card-636-2', 3, '۱. بنیان و منطق نظری برند کارفرما کار رسانه‌ای را «حرفه‌ای‌سازی» (professionalization) می‌داند: رسانه، «نهاد» است و «حرفه‌ای» بودن، «اعتبار» می‌سازد. امبلر (۱۹۹۶) در این چارچوب، «کار رسانه‌ای» را از «پیشه» به «حرفه» ارتقا داد: «اصول»، «نقش» و «نقش‌های» سازمانی، «ساختار» کار را «تعیین» می‌کنند.  بر اساس برند کارفرما، «سازمان رسانه‌ای» با «ساختار» و «فرهنگ» سازمانی «کار» را «بازتولید» می‌کند: «سلسله‌مراتب»، «نقش‌ها» و «فرهنگ» سازمانی، «رفتار» کارکنان را «شکل» می‌دهند. امبلر (۱۹۹۶) در این چارچوب، «منابع انسانی» را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.', '88ae8af7d948b5cdf80e024e86b9cfee094a5a24e2b96e0384203f952a25d9c9', 1074, 'ch-doc-card-636-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='88ae8af7d948b5cdf80e024e86b9cfee094a5a24e2b96e0384203f952a25d9c9', token_count=1074, vector_point_id='ch-doc-card-636-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-636-4', 'doc-card-636', 'sec-card-636-2', 4, 'را «سرمایه‌ی» اصلی رسانه خواند: «توان» حرفه‌ای «کارکنان»، «اعتبار» رسانه است.  برند کارفرما را می‌توان پاسخی به شکاف میان «سازمان کلاسیک» (سلسله‌مراتبی) و «سازمان دیجیتال» (شبکه‌ای) دانست: در «عصر دیجیتال»، «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده و «کار» رسانه‌ای به «کار پراکنده» (gig) تبدیل شده است. امبلر (۱۹۹۶) در این چارچوب، «کار» را نه «پاره‌ای» از «سازمان» بلکه «جریان» در «بازار» تعریف کرد.  ۲. ساختارهای مفهومی • حرفه‌ای‌سازی (Professionalization): فرایند «حرفه‌ای» شدن کار رسانه‌ای: «اصول»، «نقش» و «نقش‌های» سازمانی؛ «اعتبار» و «استقلال».', '0a9b65d7f0e226ee2bd59d3df7896cbcebd032f407aa2cdcd898cfba6e640f70', 998, 'ch-doc-card-636-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0a9b65d7f0e226ee2bd59d3df7896cbcebd032f407aa2cdcd898cfba6e640f70', token_count=998, vector_point_id='ch-doc-card-636-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-636-5', 'doc-card-636', 'sec-card-636-2', 5, '‌ای» شدن کار رسانه‌ای: «اصول»، «نقش» و «نقش‌های» سازمانی؛ «اعتبار» و «استقلال». • ساختار سازمانی (Organizational Structure): «سلسله‌مراتب»، «نقش‌ها» و «مسئولیت‌ها» در رسانه؛ «ساختار»، «رفتار» کارکنان را «شکل» می‌دهد. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها»، «باورها» و «نمادها» در رسانه؛ «فرهنگ»، «رفتار» را «بازتولید» می‌کند. • مدیریت منابع انسانی (HR Management): «جذب»، «آموزش»، «ارزیابی» و «حفظ» «توان» حرفه‌ای؛ «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی است. • کار پراکنده (Gig Work): «کار» «مستقل»، «پاره‌وقت» و «پروژه‌ای» در رسانه؛ «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده است. • ریسک شغلی (Job Insecurity): «ناپاید', 'db3a26c5c8a448d98fb433ec1a59ee3c6ab2005b9bf51bc3a8194f2a5be78b6e', 1136, 'ch-doc-card-636-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='db3a26c5c8a448d98fb433ec1a59ee3c6ab2005b9bf51bc3a8194f2a5be78b6e', token_count=1136, vector_point_id='ch-doc-card-636-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-636-6', 'doc-card-636', 'sec-card-636-3', 6, '• حرفه‌ای‌سازی (Professionalization): فرایند «حرفه‌ای» شدن کار رسانه‌ای: «اصول»، «نقش» و «نقش‌های» سازمانی؛ «اعتبار» و «استقلال». • ساختار سازمانی (Organizational Structure): «سلسله‌مراتب»، «نقش‌ها» و «مسئولیت‌ها» در رسانه؛ «ساختار»، «رفتار» کارکنان را «شکل» می‌دهد. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها»، «باورها» و «نمادها» در رسانه؛ «فرهنگ»، «رفتار» را «بازتولید» می‌کند. • مدیریت منابع انسانی (HR Management): «جذب»، «آموزش»، «ارزیابی» و «حفظ» «توان» حرفه‌ای؛ «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی است. • کار پراکنده (Gig Work): «کار» «مستقل»، «پاره‌وقت» و «پروژه‌ای» در رسانه؛ «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده است.', '8ed776a62c1398c2193e6cdfcbb731d44985ab6f4f5d05b39d5fcf428dc75fd7', 1158, 'ch-doc-card-636-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8ed776a62c1398c2193e6cdfcbb731d44985ab6f4f5d05b39d5fcf428dc75fd7', token_count=1158, vector_point_id='ch-doc-card-636-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-636-7', 'doc-card-636', 'sec-card-636-3', 7, '«پاره‌وقت» و «پروژه‌ای» در رسانه؛ «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده است. • ریسک شغلی (Job Insecurity): «ناپایداری» کار رسانه‌ای؛ «مسابقه» و «فشار» در «عصر دیجیتال»، «ریسک» را «افزایش» داده است. • نقش حرفه‌ای (Professional Role): «نقش» روزنامه‌نگار، ویراستار، کارگردان، مدیر؛ «نقش‌ها»، «ساختار» کار را «تعیین» می‌کنند. • توسعه شغلی (Career Development): «مسیر» شغلی و «آموزش» مداوم؛ «توان» حرفه‌ای، «بازتولید» روزانه نیاز دارد.', '6b0e6d8e71d49df86b71221030f14b943240b5f58c4de60c1f73c41d0770e7ab', 785, 'ch-doc-card-636-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6b0e6d8e71d49df86b71221030f14b943240b5f58c4de60c1f73c41d0770e7ab', token_count=785, vector_point_id='ch-doc-card-636-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-636-8', 'doc-card-636', 'sec-card-636-4', 8, 'اری» کار رسانه‌ای؛ «مسابقه» و «فشار» در «عصر دیجیتال»، «ریسک» را «افزایش» داده است. • نقش حرفه‌ای (Professional Role): «نقش» روزنامه‌نگار، ویراستار، کارگردان، مدیر؛ «نقش‌ها»، «ساختار» کار را «تعیین» می‌کنند. • توسعه شغلی (Career Development): «مسیر» شغلی و «آموزش» مداوم؛ «توان» حرفه‌ای، «بازتولید» روزانه نیاز دارد.  ۳. نمونه‌های تحلیلی «حرفه‌ای‌سازی» در عمل: «روزنامه‌نگار» با «دوره» و «اصول» «حرفه‌ای» می‌شود: «اعتبار» از «آموزش» و «اصول» ساخته می‌شود.  «ساختار سازمانی» در عمل: «سلسله‌مراتب» در «تلفظ» (گزارشگر، ویراستار، مدیر) «رفتار» کارکنان را «تعیین» می‌کند: «سلسله‌مراتب»، «نقش» است.', '96675001fba80cf75863ef895f66fd6bbd6ce2e7c7fa459da7baa5f0268cb54e', 1076, 'ch-doc-card-636-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='96675001fba80cf75863ef895f66fd6bbd6ce2e7c7fa459da7baa5f0268cb54e', token_count=1076, vector_point_id='ch-doc-card-636-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-636-9', 'doc-card-636', 'sec-card-636-4', 9, '، ویراستار، مدیر) «رفتار» کارکنان را «تعیین» می‌کند: «سلسله‌مراتب»، «نقش» است.  «کار پراکنده» در عمل: «مستقل» در «شبکه‌های اجتماعی» «محتوا» می‌سازد: «مرز» بین «حرفه‌ای» و «مستقل» کمرنگ شده و «ریسک شغلی» «افزایش» یافته است.  «فرهنگ سازمانی» در عمل: «فرهنگ» «رقابت» در «رسانه‌ای» و «فرهنگ» «همکاری» در «رسانه‌ای» دیگر، «رفتار» کارکنان را «بازتولید» می‌کند: «فرهنگ»، «ساختار» است.  «مدیریت منابع انسانی» در عمل: «آموزش» «مداوم» «توان» حرفه‌ای را «حفظ» می‌کند: «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی رسانه است.  «ریسک شغلی» در «عصر دیجیتال»: «مسابقه» برای «نکست» و «فشار» «سرعت»، «کار» رسانه‌ای را «پراکنده» و «ناپایدار» کرده است: «استقلال» حرفه‌ای «تحت فشار» است.  ۴. نقدها و چالش‌ها ۱.', 'd93efc58fc5f7db9a37ef54a7de73693fc1e2f66801cdd0367735073346c4011', 1234, 'ch-doc-card-636-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d93efc58fc5f7db9a37ef54a7de73693fc1e2f66801cdd0367735073346c4011', token_count=1234, vector_point_id='ch-doc-card-636-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-636-10', 'doc-card-636', 'sec-card-636-4', 10, 'و «ناپایدار» کرده است: «استقلال» حرفه‌ای «تحت فشار» است.  ۴. نقدها و چالش‌ها ۱. «حرفه‌ای‌سازی» به «نقش‌پردازی» تقلیل می‌یابد: «اصول» به «نقش» تبدیل می‌شوند و «کار» به «نقش‌بازی»: «اعتبار» بدون «عمل» «معنا» ندارد. ۲. «ساختار سازمانی» در «عصر دیجیتال» «بازتعریف» می‌شود: «سلسله‌مراتب» کلاسیک در «پلتفرم‌ها» «عمل» نمی‌کند و «ساختار» «شبکه‌ای»، «بازتعریف» لازم دارد. ۳. «منابع انسانی» و «داده»: «ارزیابی» کارکنان با «داده» و «الگوریتم»، «حرفه‌ای‌بودن» را «ابزاری» می‌کند: «توان» به «داده» تبدیل می‌شو', 'c745b5ee5c6e9927a19c4cf4429843f6c0b28b7588a7233490b8f96280e4af35', 901, 'ch-doc-card-636-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c745b5ee5c6e9927a19c4cf4429843f6c0b28b7588a7233490b8f96280e4af35', token_count=901, vector_point_id='ch-doc-card-636-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
