INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-636-12', 'doc-card-636', 'sec-card-636-5', 12, '«توان» حرفه‌ای را «حفظ» می‌کند: «سرمایه‌ی انسانی»، «سرمایه‌ی» اصلی رسانه است.  «ریسک شغلی» در «عصر دیجیتال»: «مسابقه» برای «نکست» و «فشار» «سرعت»، «کار» رسانه‌ای را «پراکنده» و «ناپایدار» کرده است: «استقلال» حرفه‌ای «تحت فشار» است.', '714b07ad4f7a51079e90fad97f6ce548775ccc75495317d26370de2f83c7510d', 419, 'ch-doc-card-636-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='714b07ad4f7a51079e90fad97f6ce548775ccc75495317d26370de2f83c7510d', token_count=419, vector_point_id='ch-doc-card-636-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-636-13', 'doc-card-636', 'sec-card-636-6', 13, '۱. «حرفه‌ای‌سازی» به «نقش‌پردازی» تقلیل می‌یابد: «اصول» به «نقش» تبدیل می‌شوند و «کار» به «نقش‌بازی»: «اعتبار» بدون «عمل» «معنا» ندارد. ۲. «ساختار سازمانی» در «عصر دیجیتال» «بازتعریف» می‌شود: «سلسله‌مراتب» کلاسیک در «پلتفرم‌ها» «عمل» نمی‌کند و «ساختار» «شبکه‌ای»، «بازتعریف» لازم دارد. ۳. «منابع انسانی» و «داده»: «ارزیابی» کارکنان با «داده» و «الگوریتم»، «حرفه‌ای‌بودن» را «ابزاری» می‌کند: «توان» به «داده» تبدیل می‌شود. ۴. «کار پراکنده» و «اعتبار»: «مستقل» «حرفه‌ای» نیست و «اعتبار» ندارد: «مرز» بین «حرفه‌ای» و «مستقل»، «بازتعریف» لازم دارد. ۵. «فرهنگ سازمانی» و «قدرت»: «فرهنگ» در «سلسله‌مراتب»، «قدرت» است: «فرهنگ»', '2b6e87c0375f44acac0dbf50743587916b51216784afad745c61db32777925b4', 1125, 'ch-doc-card-636-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2b6e87c0375f44acac0dbf50743587916b51216784afad745c61db32777925b4', token_count=1125, vector_point_id='ch-doc-card-636-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-636-14', 'doc-card-636', 'sec-card-636-7', 14, '«رقابت»، «فشار» می‌سازد و «کار» را «استثمار» می‌کند. ۶. «توسعه شغلی» و «بازار»: «مسیر» شغلی در «بازار» «رقابت» «تعیین» می‌شود: «توان» حرفه‌ای «بازتولید» نمی‌شود و «کار» به «رقابت» تقلیل می‌یابد. ۷. «ریسک شغلی» در «بافت‌های دولتی» «عمیق‌تر» است: «فشار» «سیاسی» بر «کار» رسانه‌ای، «ریسک» را «افزایش» می‌دهد و «استقلال» حرفه‌ای «تحت فشار» است. ۸. «مدیریت منابع انسانی» و «حقوق»: «حقوق» کارکنان رسانه‌ای در «بازار» «رقابت» «تعیین» می‌شود: «سرمایه‌ی انسانی» «استثمار» می‌شود. ۹. «ساختار» و «نقش» در «عصر الگوریتم» «بازتعریف» می‌شوند: «الگوریتم»، «نقش» «کارکنان» را «تعیین» می‌کند و «ساختار» «سازمانی»، «بازتعریف» لازم دارد.', '59813802a8fd8b584b7cf5aaf1f17e5f784c089429ecd008c4916c8e5915090b', 1123, 'ch-doc-card-636-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='59813802a8fd8b584b7cf5aaf1f17e5f784c089429ecd008c4916c8e5915090b', token_count=1123, vector_point_id='ch-doc-card-636-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-636-15', 'doc-card-636', 'sec-card-636-10', 15, 'کتاب «حرفه‌ای‌سازی رسانه» (گارتنر و همکاران، ۱۹۸۶)؛ کتاب «سازمان رسانه‌ای» (تاکت و همکاران، ۱۹۹۰)؛ کتاب «کار پراکنده و رسانه» (بویل و همکاران، ۲۰۱۵)؛ کتاب «منابع انسانی در رسانه» (مورگان، ۲۰۰۴).', 'd88d82e7ec3cb842cb7f0755a7adc74d63d4eaf63470e287fa072ada619a6ae9', 352, 'ch-doc-card-636-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d88d82e7ec3cb842cb7f0755a7adc74d63d4eaf63470e287fa072ada619a6ae9', token_count=352, vector_point_id='ch-doc-card-636-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-637-0', 'doc-card-637', NULL, 0, 'نظریه مالکیت مسئله رسانه را «سازوکار حاکمیت» می‌داند: نه صرفاَ «ابزار» دولت، بلکه «زمینه‌ی» قدرت، رقابت و مشروعیت‌سازی. پتروچیک (۱۹۹۶) نشان داد که «قدرت» بر رسانه از سه مسیر عمل می‌کند: «مالکیت» (چه کسی مالک است)، «محتوا» (چه چیزی گفته می‌شود) و «فرمت» (چگونه گفته می‌شود). این …', '19edc42feb024ea96974ff4b668d98e3909e7090f9752bad1c5fe22e774a4955', 507, 'ch-doc-card-637-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='19edc42feb024ea96974ff4b668d98e3909e7090f9752bad1c5fe22e774a4955', token_count=507, vector_point_id='ch-doc-card-637-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-637-1', 'doc-card-637', 'sec-card-637-1', 1, 'قدرت، سیاست و حاکمیت رسانه  نظریه مالکیت مسئله رسانه را «سازوکار حاکمیت» می‌داند: نه صرفاَ «ابزار» دولت، بلکه «زمینه‌ی» قدرت، رقابت و مشروعیت‌سازی. پتروچیک (۱۹۹۶) نشان داد که «قدرت» بر رسانه از سه مسیر عمل می‌کند: «مالکیت» (چه کسی مالک است)، «محتوا» (چه چیزی گفته می‌شود) و «فرمت» (چگونه گفته می‌شود). این چارچوب در سطح کلان تحلیل، رسانه را از «ابزار» به «نهاد سیاسی» ارتقا می‌دهد.  بر اساس نظریه مالکیت مسئله، «حاکمیت رسانه» یعنی «مدیریت جریان معنا» در سطح کلان: «سیاست‌گذاری رسانه‌ای»، «قانون» و «نظم‌های» خودتنظیمی، «قواعد بازی» را تعیین می‌کنند. پتروچیک (۱۹۹۶) در این چارچوب، «نظم رسانه‌ای» را نه «پایان» بلکه «نقطه‌ی آغاز» تحلیل قرار داد: نظم، میدان نبرد سیاسی است.', '07efd9ecebc72a95ff74c00c88a04abbf5e32ef1011422652a720e530d86fbf6', 1218, 'ch-doc-card-637-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='07efd9ecebc72a95ff74c00c88a04abbf5e32ef1011422652a720e530d86fbf6', token_count=1218, vector_point_id='ch-doc-card-637-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-637-2', 'doc-card-637', 'sec-card-637-1', 2, 'ی» را نه «پایان» بلکه «نقطه‌ی آغاز» تحلیل قرار داد: نظم، میدان نبرد سیاسی است.  نظریه مالکیت مسئله را می‌توان پاسخی به شکاف میان «نظریه‌ی وابستگی» (رسانه، بازتاب قدرت) و «نظریه‌ی استقلال» (رسانه، حواله‌گر قدرت) دانست: قدرت، نه «بازتاب» بلکه «بازتولید» است. پتروچیک (۱۹۹۶) در این چارچوب، «قدرت رسانه» را «دوسویه» خواند: رسانه هم «تحت تأثیر» قدرت است و هم «تولیدکننده» آن.', 'a158d818466b9f308063501cd17b4bcf17c335bd9d029055060283d91ea35d8d', 672, 'ch-doc-card-637-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a158d818466b9f308063501cd17b4bcf17c335bd9d029055060283d91ea35d8d', token_count=672, vector_point_id='ch-doc-card-637-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-637-3', 'doc-card-637', 'sec-card-637-2', 3, '۱. بنیان و منطق نظری نظریه مالکیت مسئله رسانه را «سازوکار حاکمیت» می‌داند: نه صرفاَ «ابزار» دولت، بلکه «زمینه‌ی» قدرت، رقابت و مشروعیت‌سازی. پتروچیک (۱۹۹۶) نشان داد که «قدرت» بر رسانه از سه مسیر عمل می‌کند: «مالکیت» (چه کسی مالک است)، «محتوا» (چه چیزی گفته می‌شود) و «فرمت» (چگونه گفته می‌شود). این چارچوب در سطح کلان تحلیل، رسانه را از «ابزار» به «نهاد سیاسی» ارتقا می‌دهد.  بر اساس نظریه مالکیت مسئله، «حاکمیت رسانه» یعنی «مدیریت جریان معنا» در سطح کلان: «سیاست‌گذاری رسانه‌ای»، «قانون» و «نظم‌های» خودتنظیمی، «قواعد بازی» را تعیین می‌کنند. پتروچیک (۱۹۹۶) در این چارچوب، «نظم رسانه‌ای» را نه «پایان» بلکه «نقطه‌ی آغاز» تحلیل قرار داد: نظم، میدان نبرد سیاسی است.', '9cd36e7009c31f67e3e267c93b69884e5be43395bf5735935d9c70df7d8091fd', 1205, 'ch-doc-card-637-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9cd36e7009c31f67e3e267c93b69884e5be43395bf5735935d9c70df7d8091fd', token_count=1205, vector_point_id='ch-doc-card-637-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-637-4', 'doc-card-637', 'sec-card-637-2', 4, 'ی» را نه «پایان» بلکه «نقطه‌ی آغاز» تحلیل قرار داد: نظم، میدان نبرد سیاسی است.  نظریه مالکیت مسئله را می‌توان پاسخی به شکاف میان «نظریه‌ی وابستگی» (رسانه، بازتاب قدرت) و «نظریه‌ی استقلال» (رسانه، حواله‌گر قدرت) دانست: قدرت، نه «بازتاب» بلکه «بازتولید» است. پتروچیک (۱۹۹۶) در این چارچوب، «قدرت رسانه» را «دوسویه» خواند: رسانه هم «تحت تأثیر» قدرت است و هم «تولیدکننده» آن.  ۲. ساختارهای مفهومی • قدرت بر رسانه (Power over Media): «مالکیت»، «فروشگاه» و «نظم» که «محتوا» را از پیش تعیین می‌کنند؛ پرسش «چه کسی تصمیم می‌گیرد؟» در کانون است. • قدرت رسانه (Power of Media): توانایی رسانه در «تدوین» واقعیت، «مشروعیت‌سازی» و «نهادسازی»؛ رسانه، «قدرت نرم» تولید می‌کند.', 'f10458c37717b3889d13e712bd574f77dd8c1b5e688a6492f00c02324aa6a6f4', 1198, 'ch-doc-card-637-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f10458c37717b3889d13e712bd574f77dd8c1b5e688a6492f00c02324aa6a6f4', token_count=1198, vector_point_id='ch-doc-card-637-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-637-5', 'doc-card-637', 'sec-card-637-2', 5, 'در «تدوین» واقعیت، «مشروعیت‌سازی» و «نهادسازی»؛ رسانه، «قدرت نرم» تولید می‌کند. • نظم رسانه‌ای (Media Regulation): «قواعد بازی» رسانه: «قانون»، «نظم‌های» خودتنظیمی و «نظم‌های» دولتی؛ هر «نظم»، انتخاب سیاسی است. • سیاست‌گذاری رسانه‌ای (Media Policy): فرایند «تصمیم‌گیری» درباره‌ی «ساختار»، «مالکیت» و «محتوای» رسانه؛ «نهادها» و «گروه‌های» فشار در کانون‌اند. • مالکیت رسانه‌ای (Media Ownership): «ساختار» مالکیت (تمرکز/تعدد) که «محتو', '877d17817da7c15c372ac3de62c34b809b07e2313e666ddba92825607fb87507', 783, 'ch-doc-card-637-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='877d17817da7c15c372ac3de62c34b809b07e2313e666ddba92825607fb87507', token_count=783, vector_point_id='ch-doc-card-637-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-637-6', 'doc-card-637', 'sec-card-637-3', 6, '• قدرت بر رسانه (Power over Media): «مالکیت»، «فروشگاه» و «نظم» که «محتوا» را از پیش تعیین می‌کنند؛ پرسش «چه کسی تصمیم می‌گیرد؟» در کانون است. • قدرت رسانه (Power of Media): توانایی رسانه در «تدوین» واقعیت، «مشروعیت‌سازی» و «نهادسازی»؛ رسانه، «قدرت نرم» تولید می‌کند. • نظم رسانه‌ای (Media Regulation): «قواعد بازی» رسانه: «قانون»، «نظم‌های» خودتنظیمی و «نظم‌های» دولتی؛ هر «نظم»، انتخاب سیاسی است. • سیاست‌گذاری رسانه‌ای (Media Policy): فرایند «تصمیم‌گیری» درباره‌ی «ساختار»، «مالکیت» و «محتوای» رسانه؛ «نهادها» و «گروه‌های» فشار در کانون‌اند.', '9c13d9d60f70428338de8f419e6539e1b79fa830e8c2a96fa764fb8e452094ba', 989, 'ch-doc-card-637-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9c13d9d60f70428338de8f419e6539e1b79fa830e8c2a96fa764fb8e452094ba', token_count=989, vector_point_id='ch-doc-card-637-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-637-7', 'doc-card-637', 'sec-card-637-3', 7, 'ی «ساختار»، «مالکیت» و «محتوای» رسانه؛ «نهادها» و «گروه‌های» فشار در کانون‌اند. • مالکیت رسانه‌ای (Media Ownership): «ساختار» مالکیت (تمرکز/تعدد) که «محتوا» را از پیش شکل می‌دهد؛ «مالکیت» و «اقتصاد» در هم تنیده‌اند. • مشروعیت‌سازی (Legitimation): رسانه با «گزارش» و «بازنمایی»، «حاکمیت» را «مشروع» می‌نمایاند؛ «تصویر» و «زبان»، ابزار «مشروعیت‌سازی»‌اند. • حاکمیت رسانه‌ای (Media Governance): «مدیریت کلان» رسانه: «نهادها»، «قوانین»، «نظم‌ها» و «نهادسازی» که «جریان معنا» را «تنظیم» می‌کنند. • رقابت رسانه‌ای (Media Competition): «رقابت» بین نهادهای رسانه‌ای برای «دسته‌ی» هدف، «سرمایه» و «اعتبار»؛ «رقابت» و «تمرکز» در «موازنه»‌اند.', 'e14293519f380356fbb4aacac333490eee67597b70dc853348070a5b60a65d3e', 1149, 'ch-doc-card-637-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e14293519f380356fbb4aacac333490eee67597b70dc853348070a5b60a65d3e', token_count=1149, vector_point_id='ch-doc-card-637-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-637-8', 'doc-card-637', 'sec-card-637-4', 8, 'ا» را از پیش شکل می‌دهد؛ «مالکیت» و «اقتصاد» در هم تنیده‌اند. • مشروعیت‌سازی (Legitimation): رسانه با «گزارش» و «بازنمایی»، «حاکمیت» را «مشروع» می‌نمایاند؛ «تصویر» و «زبان»، ابزار «مشروعیت‌سازی»‌اند. • حاکمیت رسانه‌ای (Media Governance): «مدیریت کلان» رسانه: «نهادها»، «قوانین»، «نظم‌ها» و «نهادسازی» که «جریان معنا» را «تنظیم» می‌کنند. • رقابت رسانه‌ای (Media Competition): «رقابت» بین نهادهای رسانه‌ای برای «دسته‌ی» هدف، «سرمایه» و «اعتبار»؛ «رقابت» و «تمرکز» در «موازنه»‌اند.  ۳. نمونه‌های تحلیلی وقتی «رسانه‌ای» از «انتخابات» گزارش می‌دهد، «موضوعات» و «زبان» آن، «مشروعیت‌سازی» است: «نحوه‌ی» گزارش، «حاکمیت» را «طبیعی» می‌نمایاند.', 'ef053e946121efe32612dacc66e2a4d6f9f59f53097b5164b49fc5d5df0881e9', 1152, 'ch-doc-card-637-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ef053e946121efe32612dacc66e2a4d6f9f59f53097b5164b49fc5d5df0881e9', token_count=1152, vector_point_id='ch-doc-card-637-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-637-9', 'doc-card-637', 'sec-card-637-4', 9, '«زبان» آن، «مشروعیت‌سازی» است: «نحوه‌ی» گزارش، «حاکمیت» را «طبیعی» می‌نمایاند.  «مالکیت رسانه‌ای» در عمل: وقتی یک «گروه اقتصادی» «رسانه» می‌خرد، «محتوا» از «پیش» شکل می‌گیرد؛ «مالکیت» و «اقتصاد» در هم تنیده‌اند.  «نظم رسانه‌ای» در «ایران» به «قانون» و «نظم دولتی» تقلیل نمی‌یابد: «نظم‌های» خودتنظیمی (کمیته‌های رسانه‌ای) و «نظم‌های» فرهنگی (سلیقه‌ی حاکم) هم در کانون‌اند.  «سیاست‌گذاری رسانه‌ای» در «اتحادیه اروپا» با «قانون خدمات رسانه‌ای» و «حریم خصوصی» تعریف می‌شود و «رقابت» بین «پلتفرم‌ها» و «رسانه‌های» سنتی، «موضوع» اصلی است.  «قدرت رسانه» در «بحران» به «تدوین» واقعیت تبدیل می‌شود: «نحوه‌ی» گزارش «بحران»، «واکنش» عمومی را «تعیین» می‌کند.', '057050f37b71e01990190aaf59926ad717dcacae89e107146383712e8573e87e', 1174, 'ch-doc-card-637-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='057050f37b71e01990190aaf59926ad717dcacae89e107146383712e8573e87e', token_count=1174, vector_point_id='ch-doc-card-637-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-637-10', 'doc-card-637', 'sec-card-637-4', 10, 'واقعیت تبدیل می‌شود: «نحوه‌ی» گزارش «بحران»، «واکنش» عمومی را «تعیین» می‌کند.  «حاکمیت رسانه‌ای» در «عصر دیجیتال» با «پلتفرم‌ها» «بازتعریف» می‌شود: «الگوریتم» و «داده»، «نظم» تازه‌ای از «حاکمیت» تولید می‌کنند که «قانون» سنتی، «توصیف» نمی‌کند.  ۴. نقدها و چالش‌ها ۱. «قدرت بر رسانه» و «قدرت رسانه» مرز «کمرنگ» دارند: «تدوین» و «تلقین» در هم تنیده‌اند و «سنجش» مستقل آن‌ها دشوار است. ۲. «نظم رسانه‌ای» به «قانون» تقلیل می‌یابد: «نظم‌های» خودتنظیمی، «فرهنگی» و «اقتصادی» اغلب', 'fc98e5d354fd2c522bb0fe9cc1cd0039b2fadfdb539c439cd357075db097ab7c', 858, 'ch-doc-card-637-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fc98e5d354fd2c522bb0fe9cc1cd0039b2fadfdb539c439cd357075db097ab7c', token_count=858, vector_point_id='ch-doc-card-637-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-637-11', 'doc-card-637', 'sec-card-637-5', 11, 'وقتی «رسانه‌ای» از «انتخابات» گزارش می‌دهد، «موضوعات» و «زبان» آن، «مشروعیت‌سازی» است: «نحوه‌ی» گزارش، «حاکمیت» را «طبیعی» می‌نمایاند.  «مالکیت رسانه‌ای» در عمل: وقتی یک «گروه اقتصادی» «رسانه» می‌خرد، «محتوا» از «پیش» شکل می‌گیرد؛ «مالکیت» و «اقتصاد» در هم تنیده‌اند.  «نظم رسانه‌ای» در «ایران» به «قانون» و «نظم دولتی» تقلیل نمی‌یابد: «نظم‌های» خودتنظیمی (کمیته‌های رسانه‌ای) و «نظم‌های» فرهنگی (سلیقه‌ی حاکم) هم در کانون‌اند.  «سیاست‌گذاری رسانه‌ای» در «اتحادیه اروپا» با «قانون خدمات رسانه‌ای» و «حریم خصوصی» تعریف می‌شود و «رقابت» بین «پلتفرم‌ها» و «رسانه‌های» سنتی، «موضوع» اصلی است.', '7c50682f15810007e46a9d561f490fced23d4f2c46a9a4ca16577fdc14239d48', 1069, 'ch-doc-card-637-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7c50682f15810007e46a9d561f490fced23d4f2c46a9a4ca16577fdc14239d48', token_count=1069, vector_point_id='ch-doc-card-637-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-637-12', 'doc-card-637', 'sec-card-637-5', 12, '» تعریف می‌شود و «رقابت» بین «پلتفرم‌ها» و «رسانه‌های» سنتی، «موضوع» اصلی است.  «قدرت رسانه» در «بحران» به «تدوین» واقعیت تبدیل می‌شود: «نحوه‌ی» گزارش «بحران»، «واکنش» عمومی را «تعیین» می‌کند.  «حاکمیت رسانه‌ای» در «عصر دیجیتال» با «پلتفرم‌ها» «بازتعریف» می‌شود: «الگوریتم» و «داده»، «نظم» تازه‌ای از «حاکمیت» تولید می‌کنند که «قانون» سنتی، «توصیف» نمی‌کند.', '1fa66ac8dd596d4449515b08a71d6c7b64a2df21ee3498bae7353f59043c34c4', 649, 'ch-doc-card-637-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1fa66ac8dd596d4449515b08a71d6c7b64a2df21ee3498bae7353f59043c34c4', token_count=649, vector_point_id='ch-doc-card-637-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-637-13', 'doc-card-637', 'sec-card-637-6', 13, '۱. «قدرت بر رسانه» و «قدرت رسانه» مرز «کمرنگ» دارند: «تدوین» و «تلقین» در هم تنیده‌اند و «سنجش» مستقل آن‌ها دشوار است. ۲. «نظم رسانه‌ای» به «قانون» تقلیل می‌یابد: «نظم‌های» خودتنظیمی، «فرهنگی» و «اقتصادی» اغلب نادیده گرفته می‌شوند. ۳. «مالکیت» در «عصر دیجیتال» «بازتعریف» می‌شود: «مالکیت» پلتفرم، «مالکیت» سنتی نیست و «اقتصاد داده» و «الگوریتم»، «ساختار» تازه‌ای تولید می‌کنند. ۴. «مشروعیت‌سازی» مفهوم «غیرقابل انکار» است: نشان دادن «مشروعیت‌سازی» در عمل، «تفسیر» نیاز دارد و «داده» به‌کلی، «تأیید» نمی‌کند. ۵. «رقابت رسانه‌ای» در «بافت‌های دولتی» «محدود» اس', '812da107625645cc46b32ecb992a477b60ad1e6db3cbfda988f18d1c5dd53aea', 1014, 'ch-doc-card-637-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='812da107625645cc46b32ecb992a477b60ad1e6db3cbfda988f18d1c5dd53aea', token_count=1014, vector_point_id='ch-doc-card-637-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-637-14', 'doc-card-637', 'sec-card-637-7', 14, 'ت: «رقابت» به «تقابل» بین «رسانه‌های دولتی» و «غیروادبی» تقلیل می‌یابد. ۶. «حاکمیت رسانه‌ای» و «نظارت» در هم تنیده‌اند: «نظم» و «نظارت» مرز «کمرنگ» دارند و «نظم» می‌تواند «ابزار» «نظارت» شود. ۷. «قدرت» و «اقتصاد» از هم جدا نمی‌شوند: «قدرت» رسانه، بدون «اقتصاد» «توصیف» نمی‌شود و «اقتصاد» رسانه، بدون «قدرت» «بازسازی» نمی‌شود. ۸. «نظم» و «حاکمیت» مرز «نامشخص» دارند: «نظم رسانه‌ای» می‌تواند «ابزار» «حاکمیت» باشد و «حاکمیت»، «نظم» را «بازتولید» می‌کند. ۹. «الگوریتم» و «حاکمیت» «بازتعریف» می‌شوند: «قدرت» در «الگوریتم» پنهان است و «نظم» سنتی، «توصیف» نمی‌کند.', 'c4884d28f520e4268fde03d624764b7796c6e5d841f492f3cfe3f8f445ca5862', 1014, 'ch-doc-card-637-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c4884d28f520e4268fde03d624764b7796c6e5d841f492f3cfe3f8f445ca5862', token_count=1014, vector_point_id='ch-doc-card-637-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-637-15', 'doc-card-637', 'sec-card-637-10', 15, 'کتاب «قدرت و رسانه» (مورگن و همکاران، ۱۹۹۸)؛ کتاب «نظم رسانه‌ای» (نیکلسون و همکاران، ۲۰۰۴)؛ کتاب «سیاست‌گذاری رسانه‌ای» (بن و همکاران، ۲۰۰۲)؛ کتاب «اقتصادسیاست رسانه» (گورینگ و پاول، ۱۹۹۴).', '3936fe241b543d42170763c866dd088d055f4ed4434b7cf1089f51425607d1ae', 343, 'ch-doc-card-637-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3936fe241b543d42170763c866dd088d055f4ed4434b7cf1089f51425607d1ae', token_count=343, vector_point_id='ch-doc-card-637-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-638-0', 'doc-card-638', NULL, 0, 'اثر سیانان رسانه را «سازوکار حاکمیت» می‌داند: نه صرفاَ «ابزار» دولت، بلکه «زمینه‌ی» قدرت، رقابت و مشروعیت‌سازی. رابینسون (۱۹۹۷) نشان داد که «قدرت» بر رسانه از سه مسیر عمل می‌کند: «مالکیت» (چه کسی مالک است)، «محتوا» (چه چیزی گفته می‌شود) و «فرمت» (چگونه گفته می‌شود). این چارچوب …', 'd7064dc4718001d38010f510083bc2f09b42867934130d7877101080ec6aeaf8', 507, 'ch-doc-card-638-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d7064dc4718001d38010f510083bc2f09b42867934130d7877101080ec6aeaf8', token_count=507, vector_point_id='ch-doc-card-638-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-638-1', 'doc-card-638', 'sec-card-638-1', 1, 'قدرت، سیاست و حاکمیت رسانه  اثر سیانان رسانه را «سازوکار حاکمیت» می‌داند: نه صرفاَ «ابزار» دولت، بلکه «زمینه‌ی» قدرت، رقابت و مشروعیت‌سازی. رابینسون (۱۹۹۷) نشان داد که «قدرت» بر رسانه از سه مسیر عمل می‌کند: «مالکیت» (چه کسی مالک است)، «محتوا» (چه چیزی گفته می‌شود) و «فرمت» (چگونه گفته می‌شود). این چارچوب در سطح کلان تحلیل، رسانه را از «ابزار» به «نهاد سیاسی» ارتقا می‌دهد.  بر اساس اثر سیانان، «حاکمیت رسانه» یعنی «مدیریت جریان معنا» در سطح کلان: «سیاست‌گذاری رسانه‌ای»، «قانون» و «نظم‌های» خودتنظیمی، «قواعد بازی» را تعیین می‌کنند. رابینسون (۱۹۹۷) در این چارچوب، «نظم رسانه‌ای» را نه «پایان» بلکه «نقطه‌ی آغاز» تحلیل قرار داد: نظم، میدان نبرد سیاسی است.', '7d6914f45e8d648342fc5513e1a68131ed7bbb2a6def0b1472439adcd74f55a2', 1192, 'ch-doc-card-638-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7d6914f45e8d648342fc5513e1a68131ed7bbb2a6def0b1472439adcd74f55a2', token_count=1192, vector_point_id='ch-doc-card-638-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-638-2', 'doc-card-638', 'sec-card-638-1', 2, 'ی» را نه «پایان» بلکه «نقطه‌ی آغاز» تحلیل قرار داد: نظم، میدان نبرد سیاسی است.  اثر سیانان را می‌توان پاسخی به شکاف میان «نظریه‌ی وابستگی» (رسانه، بازتاب قدرت) و «نظریه‌ی استقلال» (رسانه، حواله‌گر قدرت) دانست: قدرت، نه «بازتاب» بلکه «بازتولید» است. رابینسون (۱۹۹۷) در این چارچوب، «قدرت رسانه» را «دوسویه» خواند: رسانه هم «تحت تأثیر» قدرت است و هم «تولیدکننده» آن.', '646cfe981f7cbdaea06f043967cd9a5f4b35df7efdcd4ff88cf04184b7ec8452', 660, 'ch-doc-card-638-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='646cfe981f7cbdaea06f043967cd9a5f4b35df7efdcd4ff88cf04184b7ec8452', token_count=660, vector_point_id='ch-doc-card-638-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-638-3', 'doc-card-638', 'sec-card-638-2', 3, '۱. بنیان و منطق نظری اثر سیانان رسانه را «سازوکار حاکمیت» می‌داند: نه صرفاَ «ابزار» دولت، بلکه «زمینه‌ی» قدرت، رقابت و مشروعیت‌سازی. رابینسون (۱۹۹۷) نشان داد که «قدرت» بر رسانه از سه مسیر عمل می‌کند: «مالکیت» (چه کسی مالک است)، «محتوا» (چه چیزی گفته می‌شود) و «فرمت» (چگونه گفته می‌شود). این چارچوب در سطح کلان تحلیل، رسانه را از «ابزار» به «نهاد سیاسی» ارتقا می‌دهد.  بر اساس اثر سیانان، «حاکمیت رسانه» یعنی «مدیریت جریان معنا» در سطح کلان: «سیاست‌گذاری رسانه‌ای»، «قانون» و «نظم‌های» خودتنظیمی، «قواعد بازی» را تعیین می‌کنند. رابینسون (۱۹۹۷) در این چارچوب، «نظم رسانه‌ای» را نه «پایان» بلکه «نقطه‌ی آغاز» تحلیل قرار داد: نظم، میدان نبرد سیاسی است.', '9a9f880cba3c9d4df4deb5f24b8cc6e5813a096c989bcbf2d521c60356caa4fc', 1180, 'ch-doc-card-638-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9a9f880cba3c9d4df4deb5f24b8cc6e5813a096c989bcbf2d521c60356caa4fc', token_count=1180, vector_point_id='ch-doc-card-638-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-638-4', 'doc-card-638', 'sec-card-638-2', 4, 'ی» را نه «پایان» بلکه «نقطه‌ی آغاز» تحلیل قرار داد: نظم، میدان نبرد سیاسی است.  اثر سیانان را می‌توان پاسخی به شکاف میان «نظریه‌ی وابستگی» (رسانه، بازتاب قدرت) و «نظریه‌ی استقلال» (رسانه، حواله‌گر قدرت) دانست: قدرت، نه «بازتاب» بلکه «بازتولید» است. رابینسون (۱۹۹۷) در این چارچوب، «قدرت رسانه» را «دوسویه» خواند: رسانه هم «تحت تأثیر» قدرت است و هم «تولیدکننده» آن.  ۲. ساختارهای مفهومی • قدرت بر رسانه (Power over Media): «مالکیت»، «فروشگاه» و «نظم» که «محتوا» را از پیش تعیین می‌کنند؛ پرسش «چه کسی تصمیم می‌گیرد؟» در کانون است. • قدرت رسانه (Power of Media): توانایی رسانه در «تدوین» واقعیت، «مشروعیت‌سازی» و «نهادسازی»؛ رسانه، «قدرت نرم» تولید می‌کند.', '21038df7359004663b7408c625b0b1f8ca4f2f045da055c4e98ea6847726f810', 1185, 'ch-doc-card-638-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='21038df7359004663b7408c625b0b1f8ca4f2f045da055c4e98ea6847726f810', token_count=1185, vector_point_id='ch-doc-card-638-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-638-5', 'doc-card-638', 'sec-card-638-2', 5, 'در «تدوین» واقعیت، «مشروعیت‌سازی» و «نهادسازی»؛ رسانه، «قدرت نرم» تولید می‌کند. • نظم رسانه‌ای (Media Regulation): «قواعد بازی» رسانه: «قانون»، «نظم‌های» خودتنظیمی و «نظم‌های» دولتی؛ هر «نظم»، انتخاب سیاسی است. • سیاست‌گذاری رسانه‌ای (Media Policy): فرایند «تصمیم‌گیری» درباره‌ی «ساختار»، «مالکیت» و «محتوای» رسانه؛ «نهادها» و «گروه‌های» فشار در کانون‌اند. • مالکیت رسانه‌ای (Media Ownership): «ساختار» مالکیت (تمرکز/تعدد) که «محتوا» را از پیش', '8adedf624bcc3833823dbace7cbf68db7dca800a6dc2ab15db8aaf1314bc03fd', 805, 'ch-doc-card-638-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8adedf624bcc3833823dbace7cbf68db7dca800a6dc2ab15db8aaf1314bc03fd', token_count=805, vector_point_id='ch-doc-card-638-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-638-6', 'doc-card-638', 'sec-card-638-3', 6, '• قدرت بر رسانه (Power over Media): «مالکیت»، «فروشگاه» و «نظم» که «محتوا» را از پیش تعیین می‌کنند؛ پرسش «چه کسی تصمیم می‌گیرد؟» در کانون است. • قدرت رسانه (Power of Media): توانایی رسانه در «تدوین» واقعیت، «مشروعیت‌سازی» و «نهادسازی»؛ رسانه، «قدرت نرم» تولید می‌کند. • نظم رسانه‌ای (Media Regulation): «قواعد بازی» رسانه: «قانون»، «نظم‌های» خودتنظیمی و «نظم‌های» دولتی؛ هر «نظم»، انتخاب سیاسی است. • سیاست‌گذاری رسانه‌ای (Media Policy): فرایند «تصمیم‌گیری» درباره‌ی «ساختار»، «مالکیت» و «محتوای» رسانه؛ «نهادها» و «گروه‌های» فشار در کانون‌اند.', '9c13d9d60f70428338de8f419e6539e1b79fa830e8c2a96fa764fb8e452094ba', 989, 'ch-doc-card-638-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9c13d9d60f70428338de8f419e6539e1b79fa830e8c2a96fa764fb8e452094ba', token_count=989, vector_point_id='ch-doc-card-638-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-638-7', 'doc-card-638', 'sec-card-638-3', 7, 'ی «ساختار»، «مالکیت» و «محتوای» رسانه؛ «نهادها» و «گروه‌های» فشار در کانون‌اند. • مالکیت رسانه‌ای (Media Ownership): «ساختار» مالکیت (تمرکز/تعدد) که «محتوا» را از پیش شکل می‌دهد؛ «مالکیت» و «اقتصاد» در هم تنیده‌اند. • مشروعیت‌سازی (Legitimation): رسانه با «گزارش» و «بازنمایی»، «حاکمیت» را «مشروع» می‌نمایاند؛ «تصویر» و «زبان»، ابزار «مشروعیت‌سازی»‌اند. • حاکمیت رسانه‌ای (Media Governance): «مدیریت کلان» رسانه: «نهادها»، «قوانین»، «نظم‌ها» و «نهادسازی» که «جریان معنا» را «تنظیم» می‌کنند. • رقابت رسانه‌ای (Media Competition): «رقابت» بین نهادهای رسانه‌ای برای «دسته‌ی» هدف، «سرمایه» و «اعتبار»؛ «رقابت» و «تمرکز» در «موازنه»‌اند.', 'e14293519f380356fbb4aacac333490eee67597b70dc853348070a5b60a65d3e', 1149, 'ch-doc-card-638-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e14293519f380356fbb4aacac333490eee67597b70dc853348070a5b60a65d3e', token_count=1149, vector_point_id='ch-doc-card-638-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-638-8', 'doc-card-638', 'sec-card-638-4', 8, 'شکل می‌دهد؛ «مالکیت» و «اقتصاد» در هم تنیده‌اند. • مشروعیت‌سازی (Legitimation): رسانه با «گزارش» و «بازنمایی»، «حاکمیت» را «مشروع» می‌نمایاند؛ «تصویر» و «زبان»، ابزار «مشروعیت‌سازی»‌اند. • حاکمیت رسانه‌ای (Media Governance): «مدیریت کلان» رسانه: «نهادها»، «قوانین»، «نظم‌ها» و «نهادسازی» که «جریان معنا» را «تنظیم» می‌کنند. • رقابت رسانه‌ای (Media Competition): «رقابت» بین نهادهای رسانه‌ای برای «دسته‌ی» هدف، «سرمایه» و «اعتبار»؛ «رقابت» و «تمرکز» در «موازنه»‌اند.  ۳. نمونه‌های تحلیلی وقتی «رسانه‌ای» از «انتخابات» گزارش می‌دهد، «موضوعات» و «زبان» آن، «مشروعیت‌سازی» است: «نحوه‌ی» گزارش، «حاکمیت» را «طبیعی» می‌نمایاند.', 'e088ca8c2909873027e3df5406aa1811da9922dcbd32744713d5d1ca0c388d0a', 1129, 'ch-doc-card-638-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e088ca8c2909873027e3df5406aa1811da9922dcbd32744713d5d1ca0c388d0a', token_count=1129, vector_point_id='ch-doc-card-638-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-638-9', 'doc-card-638', 'sec-card-638-4', 9, '«زبان» آن، «مشروعیت‌سازی» است: «نحوه‌ی» گزارش، «حاکمیت» را «طبیعی» می‌نمایاند.  «مالکیت رسانه‌ای» در عمل: وقتی یک «گروه اقتصادی» «رسانه» می‌خرد، «محتوا» از «پیش» شکل می‌گیرد؛ «مالکیت» و «اقتصاد» در هم تنیده‌اند.  «نظم رسانه‌ای» در «ایران» به «قانون» و «نظم دولتی» تقلیل نمی‌یابد: «نظم‌های» خودتنظیمی (کمیته‌های رسانه‌ای) و «نظم‌های» فرهنگی (سلیقه‌ی حاکم) هم در کانون‌اند.  «سیاست‌گذاری رسانه‌ای» در «اتحادیه اروپا» با «قانون خدمات رسانه‌ای» و «حریم خصوصی» تعریف می‌شود و «رقابت» بین «پلتفرم‌ها» و «رسانه‌های» سنتی، «موضوع» اصلی است.  «قدرت رسانه» در «بحران» به «تدوین» واقعیت تبدیل می‌شود: «نحوه‌ی» گزارش «بحران»، «واکنش» عمومی را «تعیین» می‌کند.', '057050f37b71e01990190aaf59926ad717dcacae89e107146383712e8573e87e', 1174, 'ch-doc-card-638-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='057050f37b71e01990190aaf59926ad717dcacae89e107146383712e8573e87e', token_count=1174, vector_point_id='ch-doc-card-638-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-638-10', 'doc-card-638', 'sec-card-638-4', 10, 'واقعیت تبدیل می‌شود: «نحوه‌ی» گزارش «بحران»، «واکنش» عمومی را «تعیین» می‌کند.  «حاکمیت رسانه‌ای» در «عصر دیجیتال» با «پلتفرم‌ها» «بازتعریف» می‌شود: «الگوریتم» و «داده»، «نظم» تازه‌ای از «حاکمیت» تولید می‌کنند که «قانون» سنتی، «توصیف» نمی‌کند.  ۴. نقدها و چالش‌ها ۱. «قدرت بر رسانه» و «قدرت رسانه» مرز «کمرنگ» دارند: «تدوین» و «تلقین» در هم تنیده‌اند و «سنجش» مستقل آن‌ها دشوار است. ۲. «نظم رسانه‌ای» به «قانون» تقلیل می‌یابد: «نظم‌های» خودتنظیمی، «فرهنگی» و «اقتصادی» اغلب ن', '1061d39c712c35a5c161960953bc6fb37a0c1b149c4555327293fa2a387af2ab', 861, 'ch-doc-card-638-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1061d39c712c35a5c161960953bc6fb37a0c1b149c4555327293fa2a387af2ab', token_count=861, vector_point_id='ch-doc-card-638-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
