INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-660-8', 'doc-card-660', 'sec-card-660-4', 8, 'ای است. • بافت شبکه‌ای (Networked Context): «بافت» که در آن «رفتار» و «هویت» «بازتولید» می‌شوند؛ «بافت»، «ساختار» است. • جریان اطلاعات (Information Flow): «جریان» «محتوا» در شبکه: «مسیر»، «سرعت» و «حجم» «جریان»، «بازتولید» «معنا» است.  ۳. نمونه‌های تحلیلی «ساختار شبکه» در عمل: وقتی «خبر» در «شبکه‌ی اجتماعی» «گسترش» می‌یابد، «مسیر» آن از «گره»‌های «کلیدی» (تأثیرگرها) است: «ساختار»، «جریان» را «تعیین» می‌کند.  «سرمایه شبکه‌ای» در عمل: «اعتبار» یک «تأثیرگر» از «موقعیت» او در شبکه است: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت»، «ارزش» دارد.  «اثر شبکه‌ای» در «فیسبوک»: هر «عضو» جدیدی که «می‌آید»، «ارزش» شبکه را برای «همه» «بالاتر» می‌برد: «محصول» و «بازار» یکجا می‌شوند.', '6288f534e9e0526d5c173ba491f55f973a314443e8c4494a0348f23395bc1c36', 1227, 'ch-doc-card-660-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6288f534e9e0526d5c173ba491f55f973a314443e8c4494a0348f23395bc1c36', token_count=1227, vector_point_id='ch-doc-card-660-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-660-9', 'doc-card-660', 'sec-card-660-4', 9, 'د»، «ارزش» شبکه را برای «همه» «بالاتر» می‌برد: «محصول» و «بازار» یکجا می‌شوند.  «حلقه اجتماعی» در عمل: «اشتراک‌گذاری» یک «خبر» در «حلقه» «دوستان»، «اعتبار» «اجتماعی» می‌سازد: «تایید» «اجتماعی»، «جریان» را «بازتولید» می‌کند.  «تأثیرگر» در «اینستاگرام»: «اعتبار» شخصی «تأثیرگر»، «سرمایه» شبکه‌ای است: «محتوا» او از «موقعیت» او در شبکه «جریان» می‌یابد.  «بافت شبکه‌ای» در عمل: «هویت» «دیجیتال» یک «کاربر» در «بافت» شبکه «بازتولید» می‌شود: «رفتار» و «هویت»، «محصول» «ساختار» است.  ۴. نقدها و چالش‌ها ۱. «شبکه» و «محتوا» از هم جدا نمی‌شوند: «تحلیل» صرف «ساختار»، «محتوا» را «محو» می‌کند: «محتوا» و «ساختار» در هم تنیده‌اند. ۲.', '45527934c6adaeb1e99f9cab34181bf62c1603d1ec125df721a815b30f469b3f', 1129, 'ch-doc-card-660-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='45527934c6adaeb1e99f9cab34181bf62c1603d1ec125df721a815b30f469b3f', token_count=1129, vector_point_id='ch-doc-card-660-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
