INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-664-6', 'doc-card-664', 'sec-card-664-3', 6, '» در شبکه که «محتوا» را «بازتولید» می‌کند؛ «اعتبار» شخصی، «سرمایه» شبکه‌ای است. • بافت شبکه‌ای (Networked Context): «بافت» که در آن «رفتار» و «هویت» «بازتولید» می‌شوند؛ «بافت»، «ساختار» است. • جریان اطلاعات (Information Flow): «جریان» «محتوا» در شبکه: «مسیر»، «سرعت» و «حجم» «جریان»، «بازتولید» «معنا» است.', 'db9ec0e0560590ef7363df458568a4fad133d94601ef21aab6b9272fe7a76b3e', 556, 'ch-doc-card-664-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='db9ec0e0560590ef7363df458568a4fad133d94601ef21aab6b9272fe7a76b3e', token_count=556, vector_point_id='ch-doc-card-664-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-664-7', 'doc-card-664', 'sec-card-664-4', 7, 'ار» شخصی، «سرمایه» شبکه‌ای است. • بافت شبکه‌ای (Networked Context): «بافت» که در آن «رفتار» و «هویت» «بازتولید» می‌شوند؛ «بافت»، «ساختار» است. • جریان اطلاعات (Information Flow): «جریان» «محتوا» در شبکه: «مسیر»، «سرعت» و «حجم» «جریان»، «بازتولید» «معنا» است.  ۳. نمونه‌های تحلیلی «ساختار شبکه» در عمل: وقتی «خبر» در «شبکه‌ی اجتماعی» «گسترش» می‌یابد، «مسیر» آن از «گره»‌های «کلیدی» (تأثیرگرها) است: «ساختار»، «جریان» را «تعیین» می‌کند.  «سرمایه شبکه‌ای» در عمل: «اعتبار» یک «تأثیرگر» از «موقعیت» او در شبکه است: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت»، «ارزش» دارد.', 'cda4f1f0930983a1ba18f669efa0a4c76a893788bcf1ce03562339e089a6dbf9', 1032, 'ch-doc-card-664-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cda4f1f0930983a1ba18f669efa0a4c76a893788bcf1ce03562339e089a6dbf9', token_count=1032, vector_point_id='ch-doc-card-664-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-664-8', 'doc-card-664', 'sec-card-664-4', 8, 'عیت» او در شبکه است: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت»، «ارزش» دارد.  «اثر شبکه‌ای» در «فیسبوک»: هر «عضو» جدیدی که «می‌آید»، «ارزش» شبکه را برای «همه» «بالاتر» می‌برد: «محصول» و «بازار» یکجا می‌شوند.  «حلقه اجتماعی» در عمل: «اشتراک‌گذاری» یک «خبر» در «حلقه» «دوستان»، «اعتبار» «اجتماعی» می‌سازد: «تایید» «اجتماعی»، «جریان» را «بازتولید» می‌کند.  «تأثیرگر» در «اینستاگرام»: «اعتبار» شخصی «تأثیرگر»، «سرمایه» شبکه‌ای است: «محتوا» او از «موقعیت» او در شبکه «جریان» می‌یابد.  «بافت شبکه‌ای» در عمل: «هویت» «دیجیتال» یک «کاربر» در «بافت» شبکه «بازتولید» می‌شود: «رفتار» و «هویت»، «محصول» «ساختار» است.  ۴. نقدها و چالش‌ها ۱.', '399c48d251f87ea37c6ae3f34383931c054216b738810f83e6b5bec01decfea5', 1143, 'ch-doc-card-664-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='399c48d251f87ea37c6ae3f34383931c054216b738810f83e6b5bec01decfea5', token_count=1143, vector_point_id='ch-doc-card-664-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-664-9', 'doc-card-664', 'sec-card-664-4', 9, 'ازتولید» می‌شود: «رفتار» و «هویت»، «محصول» «ساختار» است.  ۴. نقدها و چالش‌ها ۱. «شبکه» و «محتوا» از هم جدا نمی‌شوند: «تحلیل» صرف «ساختار»، «محتوا» را «محو» می‌کند: «محتوا» و «ساختار» در هم تنیده‌اند. ۲. «سرمایه شبکه‌ای» «سنجش‌پذیر» نیست: «ارزش» «موقعیت» در شبکه، «شاخص» واحد ندارد و «اندازه‌گیری» آن «دشواری» است. ۳. «اثر شبکه‌ای» «نامتقارن» است: «بزرگ‌تر» شدن شبکه، «ارزش» را «افزایش» می‌دهد اما «ارزش»، «توزیع» نمی‌شود: «مرکز» «بیشتر»', '213dfadab23d9512bdf135c98ef9887692483ba6ce4823c44a022baa8f3eed1e', 792, 'ch-doc-card-664-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='213dfadab23d9512bdf135c98ef9887692483ba6ce4823c44a022baa8f3eed1e', token_count=792, vector_point_id='ch-doc-card-664-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-664-10', 'doc-card-664', 'sec-card-664-5', 10, '«ساختار شبکه» در عمل: وقتی «خبر» در «شبکه‌ی اجتماعی» «گسترش» می‌یابد، «مسیر» آن از «گره»‌های «کلیدی» (تأثیرگرها) است: «ساختار»، «جریان» را «تعیین» می‌کند.  «سرمایه شبکه‌ای» در عمل: «اعتبار» یک «تأثیرگر» از «موقعیت» او در شبکه است: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت»، «ارزش» دارد.  «اثر شبکه‌ای» در «فیسبوک»: هر «عضو» جدیدی که «می‌آید»، «ارزش» شبکه را برای «همه» «بالاتر» می‌برد: «محصول» و «بازار» یکجا می‌شوند.  «حلقه اجتماعی» در عمل: «اشتراک‌گذاری» یک «خبر» در «حلقه» «دوستان»، «اعتبار» «اجتماعی» می‌سازد: «تایید» «اجتماعی»، «جریان» را «بازتولید» می‌کند.', '591acce302984742f99aaeba653caba140e13292a9114cff4d0b46b06ec2c4c4', 1025, 'ch-doc-card-664-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='591acce302984742f99aaeba653caba140e13292a9114cff4d0b46b06ec2c4c4', token_count=1025, vector_point_id='ch-doc-card-664-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-664-11', 'doc-card-664', 'sec-card-664-5', 11, '، «اعتبار» «اجتماعی» می‌سازد: «تایید» «اجتماعی»، «جریان» را «بازتولید» می‌کند.  «تأثیرگر» در «اینستاگرام»: «اعتبار» شخصی «تأثیرگر»، «سرمایه» شبکه‌ای است: «محتوا» او از «موقعیت» او در شبکه «جریان» می‌یابد.  «بافت شبکه‌ای» در عمل: «هویت» «دیجیتال» یک «کاربر» در «بافت» شبکه «بازتولید» می‌شود: «رفتار» و «هویت»، «محصول» «ساختار» است.', '0c44daa6ebe289aae8e69427d12b93abf90fe4b3ec723e137ecbd2f9cc00d196', 600, 'ch-doc-card-664-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0c44daa6ebe289aae8e69427d12b93abf90fe4b3ec723e137ecbd2f9cc00d196', token_count=600, vector_point_id='ch-doc-card-664-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-664-12', 'doc-card-664', 'sec-card-664-6', 12, '۱. «شبکه» و «محتوا» از هم جدا نمی‌شوند: «تحلیل» صرف «ساختار»، «محتوا» را «محو» می‌کند: «محتوا» و «ساختار» در هم تنیده‌اند. ۲. «سرمایه شبکه‌ای» «سنجش‌پذیر» نیست: «ارزش» «موقعیت» در شبکه، «شاخص» واحد ندارد و «اندازه‌گیری» آن «دشواری» است. ۳. «اثر شبکه‌ای» «نامتقارن» است: «بزرگ‌تر» شدن شبکه، «ارزش» را «افزایش» می‌دهد اما «ارزش»، «توزیع» نمی‌شود: «مرکز» «بیشتر» برد می‌کند. ۴. «تأثیرگر» و «اعتبار»: «اعتبار» تأثیرگر، «بازتولید» «الگوریتم» است: «موقعیت» در شبکه، «تعیین» «الگوریتم» است و «اعتبار»، «ابزاری» می‌شود. ۵. «حلقه اجتماعی» و «فیلتربابل»: «حلقه»‌های «اجتماعی»، «محتوا» ر', '3469caf12f747583e95a176220b927f46875cb1fc71098e9c56dbd3919e2b726', 1047, 'ch-doc-card-664-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3469caf12f747583e95a176220b927f46875cb1fc71098e9c56dbd3919e2b726', token_count=1047, vector_point_id='ch-doc-card-664-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-664-13', 'doc-card-664', 'sec-card-664-7', 13, 'ا «بازتولید» می‌کنند اما «تنوع» را «محو» می‌کنند: «حلقه»، «بابل» می‌شود. ۶. «جریان اطلاعات» و «نظارت»: «جریان» «محتوا» در شبکه، «داده» تولید می‌کند و «نظارت» بر «جریان»، «حاکمیت» است. ۷. «بافت شبکه‌ای» و «هویت»: «هویت» «دیجیتال» در «بافت» شبکه «بازتولید» می‌شود اما «هویت» «آفلاین» «محو» نمی‌شود: «دیالکتیک» «آنلاین» و «آفلاین»، «بازتعریف» لازم دارد. ۸. «شبکه» و «قدرت» در هم تنیده‌اند: «موقعیت» در شبکه، «قدرت» است و «ساختار» شبکه، «قدرت» را «بازتولید» می‌کند. ۹. «شبکه» در «عصر الگوریتم» «بازتعریف» می‌شود: «الگوریتم»، «جریان» را «تعیین» می‌کند و «شبکه»، «الگوریتمی» می‌شود.', 'df3f6cb886d894882a05992b88970ab96b64f2de5b7a800d087e2677b0d75af9', 1047, 'ch-doc-card-664-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='df3f6cb886d894882a05992b88970ab96b64f2de5b7a800d087e2677b0d75af9', token_count=1047, vector_point_id='ch-doc-card-664-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-664-14', 'doc-card-664', 'sec-card-664-10', 14, 'کتاب «ساختار اجتماعی» (بدر، ۱۹۸۳)؛ کتاب «اثر شبکه‌ای» (کارلوس و همکاران، ۲۰۱۰)؛ کتاب «شبکه‌های اجتماعی و رسانه» (والگرن و همکاران، ۲۰۰۵)؛ کتاب «سرمایه شبکه‌ای» (بیر و همکاران، ۲۰۰۸).', '267bd487cac492d7d744a11d37965dbb6cf9ee51653f69e0213ee5c59013a532', 330, 'ch-doc-card-664-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='267bd487cac492d7d744a11d37965dbb6cf9ee51653f69e0213ee5c59013a532', token_count=330, vector_point_id='ch-doc-card-664-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-665-0', 'doc-card-665', NULL, 0, 'نظریه پیوند ضعیف در شبکههای آنلاین «شبکه» را «ساختار» روابط می‌داند: نه «محتوا» بلکه «ارتباط» در کانون است. بیکمن (۲۰۱۲) در این چارچوب، «رفتار» را نه «ویژگی» فرد بلکه «محصول» «موقعیت» در شبکه تعریف کرد: «چه کسی» به «چه کسی» وصل است، «رفتار» را «شکل» می‌دهد. بر اساس نظریه پیوند …', 'f0f9b69363f2010d090880fcf48781e5f4fb54876863cfc1a5a69e8b41b7f90a', 507, 'ch-doc-card-665-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f0f9b69363f2010d090880fcf48781e5f4fb54876863cfc1a5a69e8b41b7f90a', token_count=507, vector_point_id='ch-doc-card-665-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-665-1', 'doc-card-665', 'sec-card-665-1', 1, 'شبکه‌های اجتماعی و نظریه شبکه  نظریه پیوند ضعیف در شبکههای آنلاین «شبکه» را «ساختار» روابط می‌داند: نه «محتوا» بلکه «ارتباط» در کانون است. بیکمن (۲۰۱۲) در این چارچوب، «رفتار» را نه «ویژگی» فرد بلکه «محصول» «موقعیت» در شبکه تعریف کرد: «چه کسی» به «چه کسی» وصل است، «رفتار» را «شکل» می‌دهد.  بر اساس نظریه پیوند ضعیف در شبکههای آنلاین، «شبکه‌های اجتماعی» «میدان» تولید «معنا»، «اعتبار» و «قدرت»‌اند: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت» در شبکه، «ارزش» دارد. بیکمن (۲۰۱۲) در این چارچوب، «رسانه» را نه «پخش‌کننده» بلکه «میانجی» شبکه خواند: «رسانه»، «موقعیت» شبکه‌ای مخاطب را «بازتولید» می‌کند.', '637b6832418f0997815ddca9b710b9237aea8d67b604fe3ce76288c8d153c5ce', 1085, 'ch-doc-card-665-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='637b6832418f0997815ddca9b710b9237aea8d67b604fe3ce76288c8d153c5ce', token_count=1085, vector_point_id='ch-doc-card-665-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-665-2', 'doc-card-665', 'sec-card-665-1', 2, 'لکه «میانجی» شبکه خواند: «رسانه»، «موقعیت» شبکه‌ای مخاطب را «بازتولید» می‌کند.  نظریه پیوند ضعیف در شبکههای آنلاین را می‌توان پاسخی به شکاف میان «تحلیل فرد» و «تحلیل ساختار» دانست: «رفتار»، «محصول» «شبکه» است و «تغییر»، «تغییر» «موقعیت» است. بیکمن (۲۰۱۲) در این چارچوب، «شبکه» را نه «ابزار» بلکه «بافت» تعریف کرد: «بافت» شبکه‌ای، «هویت» و «رفتار» را «بازتولید» می‌کند.', 'f86861e8568fe5682d1a6e6583cf4fb6e7817b3c19c99a2a7ad1bf248bfdc944', 669, 'ch-doc-card-665-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f86861e8568fe5682d1a6e6583cf4fb6e7817b3c19c99a2a7ad1bf248bfdc944', token_count=669, vector_point_id='ch-doc-card-665-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-665-3', 'doc-card-665', 'sec-card-665-2', 3, '۱. بنیان و منطق نظری نظریه پیوند ضعیف در شبکههای آنلاین «شبکه» را «ساختار» روابط می‌داند: نه «محتوا» بلکه «ارتباط» در کانون است. بیکمن (۲۰۱۲) در این چارچوب، «رفتار» را نه «ویژگی» فرد بلکه «محصول» «موقعیت» در شبکه تعریف کرد: «چه کسی» به «چه کسی» وصل است، «رفتار» را «شکل» می‌دهد.  بر اساس نظریه پیوند ضعیف در شبکههای آنلاین، «شبکه‌های اجتماعی» «میدان» تولید «معنا»، «اعتبار» و «قدرت»‌اند: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت» در شبکه، «ارزش» دارد. بیکمن (۲۰۱۲) در این چارچوب، «رسانه» را نه «پخش‌کننده» بلکه «میانجی» شبکه خواند: «رسانه»، «موقعیت» شبکه‌ای مخاطب را «بازتولید» می‌کند.', '730bac098833b59555f11cd835208b49891f905c8978cf64346d35f9d04e4790', 1067, 'ch-doc-card-665-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='730bac098833b59555f11cd835208b49891f905c8978cf64346d35f9d04e4790', token_count=1067, vector_point_id='ch-doc-card-665-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-665-4', 'doc-card-665', 'sec-card-665-2', 4, 'لکه «میانجی» شبکه خواند: «رسانه»، «موقعیت» شبکه‌ای مخاطب را «بازتولید» می‌کند.  نظریه پیوند ضعیف در شبکههای آنلاین را می‌توان پاسخی به شکاف میان «تحلیل فرد» و «تحلیل ساختار» دانست: «رفتار»، «محصول» «شبکه» است و «تغییر»، «تغییر» «موقعیت» است. بیکمن (۲۰۱۲) در این چارچوب، «شبکه» را نه «ابزار» بلکه «بافت» تعریف کرد: «بافت» شبکه‌ای، «هویت» و «رفتار» را «بازتولید» می‌کند.  ۲. ساختارهای مفهومی • ساختار شبکه (Network Structure): «الگو» روابط بین «گره‌ها» (فرد، رسانه، نهاد)؛ «ساختار»، «رفتار» را «شکل» می‌دهد. • گره و پیوند (Node and Tie): «گره» (فرد، رسانه) و «پیوند» (ارتباط)؛ «پیوند» «جریان» «معنا» و «سرمایه» است.', '41fec2de31b26100d18de7a4f22d3fab652a3132ca644c82395512cbb34496e0', 1114, 'ch-doc-card-665-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='41fec2de31b26100d18de7a4f22d3fab652a3132ca644c82395512cbb34496e0', token_count=1114, vector_point_id='ch-doc-card-665-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-665-5', 'doc-card-665', 'sec-card-665-2', 5, ': «گره» (فرد، رسانه) و «پیوند» (ارتباط)؛ «پیوند» «جریان» «معنا» و «سرمایه» است. • سرمایه شبکه‌ای (Network Capital): «ارزش» «موقعیت» در شبکه؛ «ارتباط» «اجتماعی»، «سرمایه» است. • اثر شبکه‌ای (Network Effect): «بزرگ‌تر» شدن «ارزش» شبکه با «افزایش» «عضو»؛ «محصول» و «بازار» یکجا می‌شوند. • حلقه اجتماعی (Social Loop): «جریان» «محتوا» در «حلقه»‌های «اجتماعی»: «اشتراک‌گذاری» و «تایید»، «اعتبار» می‌سازد. • تأثیرگر (Influencer): «گره» «کلیدی» در شبکه که «محتوا»', 'bc8e8a42f116194443a7b4ba97e51872576212edb56950bfe9df8aed099376bf', 827, 'ch-doc-card-665-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bc8e8a42f116194443a7b4ba97e51872576212edb56950bfe9df8aed099376bf', token_count=827, vector_point_id='ch-doc-card-665-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-665-6', 'doc-card-665', 'sec-card-665-3', 6, '• ساختار شبکه (Network Structure): «الگو» روابط بین «گره‌ها» (فرد، رسانه، نهاد)؛ «ساختار»، «رفتار» را «شکل» می‌دهد. • گره و پیوند (Node and Tie): «گره» (فرد، رسانه) و «پیوند» (ارتباط)؛ «پیوند» «جریان» «معنا» و «سرمایه» است. • سرمایه شبکه‌ای (Network Capital): «ارزش» «موقعیت» در شبکه؛ «ارتباط» «اجتماعی»، «سرمایه» است. • اثر شبکه‌ای (Network Effect): «بزرگ‌تر» شدن «ارزش» شبکه با «افزایش» «عضو»؛ «محصول» و «بازار» یکجا می‌شوند. • حلقه اجتماعی (Social Loop): «جریان» «محتوا» در «حلقه»‌های «اجتماعی»: «اشتراک‌گذاری» و «تایید»، «اعتبار» می‌سازد. • تأثیرگر (Influencer): «گره» «کلیدی» در شبکه که «محتوا» را «بازتولید» می‌کند؛ «اعتبار» شخصی، «سرمایه» شبکه‌ای است.', '5ba5c7db967fcca10a31d3ceb7258cda8b6d048d4e341937c83e9ac983bd32af', 1196, 'ch-doc-card-665-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5ba5c7db967fcca10a31d3ceb7258cda8b6d048d4e341937c83e9ac983bd32af', token_count=1196, vector_point_id='ch-doc-card-665-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-665-7', 'doc-card-665', 'sec-card-665-3', 7, '» در شبکه که «محتوا» را «بازتولید» می‌کند؛ «اعتبار» شخصی، «سرمایه» شبکه‌ای است. • بافت شبکه‌ای (Networked Context): «بافت» که در آن «رفتار» و «هویت» «بازتولید» می‌شوند؛ «بافت»، «ساختار» است. • جریان اطلاعات (Information Flow): «جریان» «محتوا» در شبکه: «مسیر»، «سرعت» و «حجم» «جریان»، «بازتولید» «معنا» است.', 'db9ec0e0560590ef7363df458568a4fad133d94601ef21aab6b9272fe7a76b3e', 556, 'ch-doc-card-665-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='db9ec0e0560590ef7363df458568a4fad133d94601ef21aab6b9272fe7a76b3e', token_count=556, vector_point_id='ch-doc-card-665-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-665-8', 'doc-card-665', 'sec-card-665-4', 8, 'را «بازتولید» می‌کند؛ «اعتبار» شخصی، «سرمایه» شبکه‌ای است. • بافت شبکه‌ای (Networked Context): «بافت» که در آن «رفتار» و «هویت» «بازتولید» می‌شوند؛ «بافت»، «ساختار» است. • جریان اطلاعات (Information Flow): «جریان» «محتوا» در شبکه: «مسیر»، «سرعت» و «حجم» «جریان»، «بازتولید» «معنا» است.  ۳. نمونه‌های تحلیلی «ساختار شبکه» در عمل: وقتی «خبر» در «شبکه‌ی اجتماعی» «گسترش» می‌یابد، «مسیر» آن از «گره»‌های «کلیدی» (تأثیرگرها) است: «ساختار»، «جریان» را «تعیین» می‌کند.  «سرمایه شبکه‌ای» در عمل: «اعتبار» یک «تأثیرگر» از «موقعیت» او در شبکه است: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت»، «ارزش» دارد.', '1bb4d875c3ca057320ee684dcd8e0e78d5a0123edcc670db12d184cfce15e2c7', 1081, 'ch-doc-card-665-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1bb4d875c3ca057320ee684dcd8e0e78d5a0123edcc670db12d184cfce15e2c7', token_count=1081, vector_point_id='ch-doc-card-665-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-665-9', 'doc-card-665', 'sec-card-665-4', 9, 'عیت» او در شبکه است: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت»، «ارزش» دارد.  «اثر شبکه‌ای» در «فیسبوک»: هر «عضو» جدیدی که «می‌آید»، «ارزش» شبکه را برای «همه» «بالاتر» می‌برد: «محصول» و «بازار» یکجا می‌شوند.  «حلقه اجتماعی» در عمل: «اشتراک‌گذاری» یک «خبر» در «حلقه» «دوستان»، «اعتبار» «اجتماعی» می‌سازد: «تایید» «اجتماعی»، «جریان» را «بازتولید» می‌کند.  «تأثیرگر» در «اینستاگرام»: «اعتبار» شخصی «تأثیرگر»، «سرمایه» شبکه‌ای است: «محتوا» او از «موقعیت» او در شبکه «جریان» می‌یابد.  «بافت شبکه‌ای» در عمل: «هویت» «دیجیتال» یک «کاربر» در «بافت» شبکه «بازتولید» می‌شود: «رفتار» و «هویت»، «محصول» «ساختار» است.  ۴. نقدها و چالش‌ها ۱.', '399c48d251f87ea37c6ae3f34383931c054216b738810f83e6b5bec01decfea5', 1143, 'ch-doc-card-665-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='399c48d251f87ea37c6ae3f34383931c054216b738810f83e6b5bec01decfea5', token_count=1143, vector_point_id='ch-doc-card-665-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-665-10', 'doc-card-665', 'sec-card-665-4', 10, 'ازتولید» می‌شود: «رفتار» و «هویت»، «محصول» «ساختار» است.  ۴. نقدها و چالش‌ها ۱. «شبکه» و «محتوا» از هم جدا نمی‌شوند: «تحلیل» صرف «ساختار»، «محتوا» را «محو» می‌کند: «محتوا» و «ساختار» در هم تنیده‌اند. ۲. «سرمایه شبکه‌ای» «سنجش‌پذیر» نیست: «ارزش» «موقعیت» در شبکه، «شاخص» واحد ندارد و «اندازه‌گیری» آن «دشواری» است. ۳. «اثر شبکه‌ای» «نامتقارن» است: «بزرگ‌تر» شدن شبکه، «ارزش» را «افزایش» می‌دهد اما «ارزش»، «توزیع» نمی‌شود: «مرکز» «', 'b680a37dd4d823cc78ac3f576ac42b77c03472d09de53d21011546af9f8fb322', 781, 'ch-doc-card-665-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b680a37dd4d823cc78ac3f576ac42b77c03472d09de53d21011546af9f8fb322', token_count=781, vector_point_id='ch-doc-card-665-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
