INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-681-0', 'doc-card-681', NULL, 0, 'نظریه نفوذ اجتماعی «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». آلتمن (۱۹۷۳) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده». بر اساس نظریه نفوذ اجتماعی، «سازمانی» «بافت» «قدرت» …', 'a30ef7044f417c2c498022a9d5544488fc91e7dad3bf71ad5b81318d0b8a933a', 510, 'ch-doc-card-681-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a30ef7044f417c2c498022a9d5544488fc91e7dad3bf71ad5b81318d0b8a933a', token_count=510, vector_point_id='ch-doc-card-681-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-681-1', 'doc-card-681', 'sec-card-681-1', 1, 'ارتباطات بین‌فرهنگی، سازمانی و میان‌فردی  نظریه نفوذ اجتماعی «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». آلتمن (۱۹۷۳) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس نظریه نفوذ اجتماعی، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. آلتمن (۱۹۷۳) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', 'dfd0be3b025f130ec59a66d1331eff39bfdeb925b5502a0a9cd3b976ca157193', 969, 'ch-doc-card-681-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='dfd0be3b025f130ec59a66d1331eff39bfdeb925b5502a0a9cd3b976ca157193', token_count=969, vector_point_id='ch-doc-card-681-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-681-2', 'doc-card-681', 'sec-card-681-1', 2, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  نظریه نفوذ اجتماعی را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. آلتمن (۱۹۷۳) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.', '1784d85635358b2db82dbf4c19804a320624d27d8cec32e283e9ec229dec6c77', 636, 'ch-doc-card-681-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1784d85635358b2db82dbf4c19804a320624d27d8cec32e283e9ec229dec6c77', token_count=636, vector_point_id='ch-doc-card-681-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
