INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-681-4', 'doc-card-681', 'sec-card-681-2', 4, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  نظریه نفوذ اجتماعی را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. آلتمن (۱۹۷۳) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.  ۲. ساختارهای مفهومی • ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند.', '13ff96461164e2c27dadd5c98e31c4f88e3a9a65baea408c01e65e590d52ebc7', 1114, 'ch-doc-card-681-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='13ff96461164e2c27dadd5c98e31c4f88e3a9a65baea408c01e65e590d52ebc7', token_count=1114, vector_point_id='ch-doc-card-681-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-681-5', 'doc-card-681', 'sec-card-681-2', 5, ': «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. • تعارض و مذاکره (Conflict and Negotia', '45739dbabe89253c879bb03064016b8f6e9df96ad8b00104735ac7191c0f0a41', 823, 'ch-doc-card-681-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='45739dbabe89253c879bb03064016b8f6e9df96ad8b00104735ac7191c0f0a41', token_count=823, vector_point_id='ch-doc-card-681-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
