INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-682-0', 'doc-card-682', NULL, 0, 'نظریه ادب «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». براون (۱۹۸۷) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده». بر اساس نظریه ادب، «سازمانی» «بافت» «قدرت» و «نقش» است: …', '8a51fb1dccdb78c52ff7fda1a60bd22b5681d2d57ced2dcaeb92358d4dcb14c1', 501, 'ch-doc-card-682-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8a51fb1dccdb78c52ff7fda1a60bd22b5681d2d57ced2dcaeb92358d4dcb14c1', token_count=501, vector_point_id='ch-doc-card-682-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-682-1', 'doc-card-682', 'sec-card-682-1', 1, 'ارتباطات بین‌فرهنگی، سازمانی و میان‌فردی  نظریه ادب «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». براون (۱۹۸۷) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس نظریه ادب، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. براون (۱۹۸۷) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', '1c925305eb52c432c657edc8f9f1b9e897b1e988cb981249861c6dac383ea189', 936, 'ch-doc-card-682-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1c925305eb52c432c657edc8f9f1b9e897b1e988cb981249861c6dac383ea189', token_count=936, vector_point_id='ch-doc-card-682-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-682-2', 'doc-card-682', 'sec-card-682-1', 2, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  نظریه ادب را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. براون (۱۹۸۷) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.', 'e254fc6cf070c484406e8f075d5b04ca7d194e1779237f704a9f4c3cce391a21', 620, 'ch-doc-card-682-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e254fc6cf070c484406e8f075d5b04ca7d194e1779237f704a9f4c3cce391a21', token_count=620, vector_point_id='ch-doc-card-682-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-682-3', 'doc-card-682', 'sec-card-682-2', 3, '۱. بنیان و منطق نظری نظریه ادب «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». براون (۱۹۸۷) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس نظریه ادب، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. براون (۱۹۸۷) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  نظریه ادب را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند.', '9259a5f67ef14837f420a41844f9626ee5b9d2be965ff0bec1146eb6a1825952', 1221, 'ch-doc-card-682-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9259a5f67ef14837f420a41844f9626ee5b9d2be965ff0bec1146eb6a1825952', token_count=1221, vector_point_id='ch-doc-card-682-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-682-4', 'doc-card-682', 'sec-card-682-2', 4, 'بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. براون (۱۹۸۷) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.  ۲. ساختارهای مفهومی • ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است.', '00460790bbdff2da99a07d975525d9ee2b020560a49ed1a1c62dde790a50b70e', 1183, 'ch-doc-card-682-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='00460790bbdff2da99a07d975525d9ee2b020560a49ed1a1c62dde790a50b70e', token_count=1183, vector_point_id='ch-doc-card-682-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
