INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-685-0', 'doc-card-685', NULL, 0, 'مدیریت هماهنگ معنا «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». پیرس (۱۹۸۰) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده». بر اساس مدیریت هماهنگ معنا، «سازمانی» «بافت» «قدرت» …', '4dac266d082d9b34cc491ea05406ee89e49c7f1a1867d2d8be4e49edd5993437', 509, 'ch-doc-card-685-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4dac266d082d9b34cc491ea05406ee89e49c7f1a1867d2d8be4e49edd5993437', token_count=509, vector_point_id='ch-doc-card-685-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-685-1', 'doc-card-685', 'sec-card-685-1', 1, 'ارتباطات بین‌فرهنگی، سازمانی و میان‌فردی  مدیریت هماهنگ معنا «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». پیرس (۱۹۸۰) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس مدیریت هماهنگ معنا، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. پیرس (۱۹۸۰) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', '507a9adfb1cfa64a721b6b7337eaa796e100652c6585635d030362ec04b5c273', 965, 'ch-doc-card-685-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='507a9adfb1cfa64a721b6b7337eaa796e100652c6585635d030362ec04b5c273', token_count=965, vector_point_id='ch-doc-card-685-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-685-2', 'doc-card-685', 'sec-card-685-1', 2, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  مدیریت هماهنگ معنا را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. پیرس (۱۹۸۰) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.', 'bb3c90a0e319e96427cd8081093c4a409e4dfc8b9c2d0597df6f7af1b1205e66', 634, 'ch-doc-card-685-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bb3c90a0e319e96427cd8081093c4a409e4dfc8b9c2d0597df6f7af1b1205e66', token_count=634, vector_point_id='ch-doc-card-685-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
