INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-685-4', 'doc-card-685', 'sec-card-685-2', 4, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  مدیریت هماهنگ معنا را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. پیرس (۱۹۸۰) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.  ۲. ساختارهای مفهومی • ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند.', '762e065ab4c6804c2c89c0146b6e221ad9138c91931128f4cd77aaa86d8097c1', 1112, 'ch-doc-card-685-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='762e065ab4c6804c2c89c0146b6e221ad9138c91931128f4cd77aaa86d8097c1', token_count=1112, vector_point_id='ch-doc-card-685-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
