INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-686-1', 'doc-card-686', 'sec-card-686-1', 1, 'ارتباطات بین‌فرهنگی، سازمانی و میان‌فردی  دیالکتیکهای رابطهای «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». باکستر (۱۹۹۶) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس دیالکتیکهای رابطهای، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. باکستر (۱۹۹۶) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', '59a9a19888db74100e22b0cb124bcae076f044affedcd0ab13b5ba108c6b0b9f', 976, 'ch-doc-card-686-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='59a9a19888db74100e22b0cb124bcae076f044affedcd0ab13b5ba108c6b0b9f', token_count=976, vector_point_id='ch-doc-card-686-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-686-2', 'doc-card-686', 'sec-card-686-1', 2, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  دیالکتیکهای رابطهای را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. باکستر (۱۹۹۶) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.', '72e1d08b3197d464c9ca3f6c0608f1a47d345830aa51e5191c9f756b48790afa', 640, 'ch-doc-card-686-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='72e1d08b3197d464c9ca3f6c0608f1a47d345830aa51e5191c9f756b48790afa', token_count=640, vector_point_id='ch-doc-card-686-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
