INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-686-4', 'doc-card-686', 'sec-card-686-2', 4, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  دیالکتیکهای رابطهای را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. باکستر (۱۹۹۶) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.  ۲. ساختارهای مفهومی • ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند.', '3430360612e84e4184d2051c75806913261d41cd0c323fef287dbd296f66ecde', 1118, 'ch-doc-card-686-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3430360612e84e4184d2051c75806913261d41cd0c323fef287dbd296f66ecde', token_count=1118, vector_point_id='ch-doc-card-686-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
