INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-687-0', 'doc-card-687', NULL, 0, 'نظریه تبادل اجتماعی «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». هومنز (۱۹۵۸) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده». بر اساس نظریه تبادل اجتماعی، «سازمانی» «بافت» …', '754da41e39d92745fa013be167c2a0418dc425d3f771be5f3d10e5df28c4ad9e', 501, 'ch-doc-card-687-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='754da41e39d92745fa013be167c2a0418dc425d3f771be5f3d10e5df28c4ad9e', token_count=501, vector_point_id='ch-doc-card-687-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-687-1', 'doc-card-687', 'sec-card-687-1', 1, 'ارتباطات بین‌فرهنگی، سازمانی و میان‌فردی  نظریه تبادل اجتماعی «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». هومنز (۱۹۵۸) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس نظریه تبادل اجتماعی، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. هومنز (۱۹۵۸) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', '765af812d7ec922c5d3f46e720772354f8549908369228681f8da4de2dcce697', 972, 'ch-doc-card-687-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='765af812d7ec922c5d3f46e720772354f8549908369228681f8da4de2dcce697', token_count=972, vector_point_id='ch-doc-card-687-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-687-2', 'doc-card-687', 'sec-card-687-1', 2, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  نظریه تبادل اجتماعی را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. هومنز (۱۹۵۸) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.', '8c76bf79c44590bf8a9f7e89577d09961935dbd5fa119e767039ad901683559d', 638, 'ch-doc-card-687-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8c76bf79c44590bf8a9f7e89577d09961935dbd5fa119e767039ad901683559d', token_count=638, vector_point_id='ch-doc-card-687-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
