INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-688-1', 'doc-card-688', 'sec-card-688-1', 1, 'ارتباطات بین‌فرهنگی، سازمانی و میان‌فردی  نظریه وابستگی متقابل «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». کلی (۱۹۵۹) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس نظریه وابستگی متقابل، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. کلی (۱۹۵۹) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', '7e541f3812e504847e5f5574643cf0b4f4156d64c5e1341f15c541c4425ee1a4', 969, 'ch-doc-card-688-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7e541f3812e504847e5f5574643cf0b4f4156d64c5e1341f15c541c4425ee1a4', token_count=969, vector_point_id='ch-doc-card-688-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-688-2', 'doc-card-688', 'sec-card-688-1', 2, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  نظریه وابستگی متقابل را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. کلی (۱۹۵۹) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.', '4cf464505731e276592765b7ae3df61af1afd4c1490552f2daa54bf117cc6c86', 636, 'ch-doc-card-688-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4cf464505731e276592765b7ae3df61af1afd4c1490552f2daa54bf117cc6c86', token_count=636, vector_point_id='ch-doc-card-688-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
