INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-688-4', 'doc-card-688', 'sec-card-688-2', 4, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  نظریه وابستگی متقابل را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. کلی (۱۹۵۹) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.  ۲. ساختارهای مفهومی • ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند.', '11fd3b738402046d664b61a5d67d10bad54ccc9a1ca8f09e58f684d54da49f8a', 1114, 'ch-doc-card-688-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='11fd3b738402046d664b61a5d67d10bad54ccc9a1ca8f09e58f684d54da49f8a', token_count=1114, vector_point_id='ch-doc-card-688-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-688-5', 'doc-card-688', 'sec-card-688-2', 5, ': «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. • تعارض و مذاکره (Conflict and Negotiat', '2b0eaafcccdb375f21a6e256ba928dfb5f2b7abcfa7a191bc271f958b86b3184', 825, 'ch-doc-card-688-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2b0eaafcccdb375f21a6e256ba928dfb5f2b7abcfa7a191bc271f958b86b3184', token_count=825, vector_point_id='ch-doc-card-688-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
