INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-688-8', 'doc-card-688', 'sec-card-688-4', 8, 'ion): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است. • بافت‌محوری (Contextualism): «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • قدرت و نقش (Power and Role): «توان» در «ارتباط»: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  ۳. نمونه‌های تحلیلی «ارتباط میان‌فردی» در عمل: «گفت‌وگو» بین «دوستان» «معنا» «ساخته» می‌شود: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  «ارتباط سازمانی» در عمل: «جلسه» «سازمانی»، «بافت» «توان» است: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  «ارتباط بین‌فرهنگی» در عمل: «مذاکره» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است و «فهم» «فرهنگ» دیگر، «توان» است.', 'c615de846fdea4d18e6a0593da2fbdada249e7cd8d5658e1a3b9084dddb9d977', 1189, 'ch-doc-card-688-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c615de846fdea4d18e6a0593da2fbdada249e7cd8d5658e1a3b9084dddb9d977', token_count=1189, vector_point_id='ch-doc-card-688-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
