INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-688-14', 'doc-card-688', 'sec-card-688-7', 14, ': «توان»، «مذاکره» را «بازتولید» می‌کند. ۶. «بافت‌محوری» و «تعمیم»: «معنا» در «بافت» «ساخته» می‌شود اما «بافت» «تعمیم» «پذیر» نیست: «بافت» «بومی» است و «تحلیل»، «بومی» لازم دارد. ۷. «ارتباط سازمانی» و «ساختار»: «ارتباط» در «ساختار» «سازمانی»، «بازتولید» «توان» است: «ساختار»، «ارتباط» است. ۸. «ارتباط» و «رسانه»: «ارتباط» «میان‌فردی» و «سازمانی» در «عصر دیجیتال»، «رسانه» «دیجیتال» «بازتعریف» می‌شود: «بافت» «دیجیتال»، «ارتباط» را «بازتولید» می‌کند. ۹. «هوش فرهنگی» و «بافت»: «هوش فرهنگی» در «بافت» «دیجیتال»، «بازتعریف» می‌شود: «بافت» «دیجیتال»، «فرهنگ» را «بازتولید» می‌کند.', '6bdec743a480fb86611d0cdb02061e889fbe8f7dd8911f02a030608c0f3c2be5', 1047, 'ch-doc-card-688-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6bdec743a480fb86611d0cdb02061e889fbe8f7dd8911f02a030608c0f3c2be5', token_count=1047, vector_point_id='ch-doc-card-688-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-688-15', 'doc-card-688', 'sec-card-688-10', 15, 'کتاب «ارتباط میان‌فردی» (آدلمن و همکاران، ۱۹۹۸)؛ کتاب «ارتباط سازمانی» (مکنزی و همکاران، ۲۰۰۵)؛ کتاب «ارتباط بین‌فرهنگی» (لومبونگ و همکاران، ۲۰۰۳)؛ کتاب «هوش فرهنگی» (رابن و همکاران، ۲۰۰۷).', '956a1e981812fd0aee168d40ca4cfc0e60c304bdfcef5b69be87a8e90e1ab9e3', 343, 'ch-doc-card-688-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='956a1e981812fd0aee168d40ca4cfc0e60c304bdfcef5b69be87a8e90e1ab9e3', token_count=343, vector_point_id='ch-doc-card-688-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-689-0', 'doc-card-689', NULL, 0, 'نظریه بالبی (۱۹۶۹) مبنی بر آنکه الگوهای عاطفی اولیه‌ی وابستگی در ارتباطات بین‌فردی شکل می‌گیرند و بر سبک ارتباطات بعدی، از جمله در بافت‌های سازمانی و میان‌فرهنگی، اثر می‌گذارند؛ کاربرد رسانه‌ای آن در فهم روابط مخاطب با رسانه و تیم‌سازی است.', '5682d031ada3bce097bf7c1a15fcfe328b09c7baae8f6bd9b638086267ddb172', 436, 'ch-doc-card-689-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5682d031ada3bce097bf7c1a15fcfe328b09c7baae8f6bd9b638086267ddb172', token_count=436, vector_point_id='ch-doc-card-689-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-689-1', 'doc-card-689', 'sec-card-689-1', 1, 'ارتباطات بین‌فرهنگی، سازمانی و میان‌فردی  کاربرد رسانهای', '17b7c382a6ef63e888f07ec83261c5dc798c05af40f1e1af3221ea2f5be45672', 101, 'ch-doc-card-689-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='17b7c382a6ef63e888f07ec83261c5dc798c05af40f1e1af3221ea2f5be45672', token_count=101, vector_point_id='ch-doc-card-689-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-689-2', 'doc-card-689', 'sec-card-689-2', 2, '۱. بنیان و منطق نظری نظریه دلبستگی «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». بالبی (۱۹۶۹) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس نظریه دلبستگی، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. بالبی (۱۹۶۹) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', 'e301482a90603569cff9123cb627d0b95764faa4cec4a79ab8d525f740c6fe17', 912, 'ch-doc-card-689-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e301482a90603569cff9123cb627d0b95764faa4cec4a79ab8d525f740c6fe17', token_count=912, vector_point_id='ch-doc-card-689-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-689-3', 'doc-card-689', 'sec-card-689-2', 3, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  نظریه دلبستگی را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. بالبی (۱۹۶۹) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.  ۲. ساختارهای مفهومی • ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند.', '07b2a38115c60c23a3d6ca7610119a2468fe67f0b585da66a7186792705eabb7', 1105, 'ch-doc-card-689-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='07b2a38115c60c23a3d6ca7610119a2468fe67f0b585da66a7186792705eabb7', token_count=1105, vector_point_id='ch-doc-card-689-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-689-4', 'doc-card-689', 'sec-card-689-2', 4, ': «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. • تعارض و مذاکره (Conflict and Negotiation): «ا', 'ae34d5e2c5692a2314601ca4285f18b36cab7ccb566c71148c47eab296fe59c7', 839, 'ch-doc-card-689-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ae34d5e2c5692a2314601ca4285f18b36cab7ccb566c71148c47eab296fe59c7', token_count=839, vector_point_id='ch-doc-card-689-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
