INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-691-0', 'doc-card-691', NULL, 0, 'نظریه ارزشهای فرهنگی شوارتز «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». شوارتز (۱۹۹۲) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده». بر اساس نظریه ارزشهای فرهنگی شوارتز …', '2ed1c439ddd008a028e79efd1ae9e4bc31854290003a99f37f5ced3584be79e2', 499, 'ch-doc-card-691-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2ed1c439ddd008a028e79efd1ae9e4bc31854290003a99f37f5ced3584be79e2', token_count=499, vector_point_id='ch-doc-card-691-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-691-1', 'doc-card-691', 'sec-card-691-1', 1, 'ارتباطات بین‌فرهنگی، سازمانی و میان‌فردی  نظریه ارزشهای فرهنگی شوارتز «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». شوارتز (۱۹۹۲) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس نظریه ارزشهای فرهنگی شوارتز، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. شوارتز (۱۹۹۲) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', '0067d6ae16fd522e0e90bf681dbfbf0c78497c3ecfb28b025d61aed6498c13b9', 1005, 'ch-doc-card-691-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0067d6ae16fd522e0e90bf681dbfbf0c78497c3ecfb28b025d61aed6498c13b9', token_count=1005, vector_point_id='ch-doc-card-691-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-691-2', 'doc-card-691', 'sec-card-691-1', 2, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  نظریه ارزشهای فرهنگی شوارتز را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. شوارتز (۱۹۹۲) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.', '7307d591deeabd544cbe9b75083b412e651b602185a2ae65520d9726ee95dd53', 654, 'ch-doc-card-691-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7307d591deeabd544cbe9b75083b412e651b602185a2ae65520d9726ee95dd53', token_count=654, vector_point_id='ch-doc-card-691-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
