INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-691-6', 'doc-card-691', 'sec-card-691-3', 6, '• ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. • تعارض و مذاکره (Conflict and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است.', 'bf50a19f3fa6a4558d5edbd42200280c7f4b92c377964c4e6187e1ed0133db26', 1230, 'ch-doc-card-691-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bf50a19f3fa6a4558d5edbd42200280c7f4b92c377964c4e6187e1ed0133db26', token_count=1230, vector_point_id='ch-doc-card-691-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-691-7', 'doc-card-691', 'sec-card-691-3', 7, 'flict and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است. • بافت‌محوری (Contextualism): «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • قدرت و نقش (Power and Role): «توان» در «ارتباط»: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.', 'b64e4de88dbaf207aea343dd750d2b2d8bd0b257fd13137445296eaa2c40c444', 527, 'ch-doc-card-691-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b64e4de88dbaf207aea343dd750d2b2d8bd0b257fd13137445296eaa2c40c444', token_count=527, vector_point_id='ch-doc-card-691-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-691-8', 'doc-card-691', 'sec-card-691-4', 8, 'flict and Negotiation): «ارتباط» در «تعارض»: «مذاکره»، «بافت» «حل» «تعارض» است. • بافت‌محوری (Contextualism): «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • قدرت و نقش (Power and Role): «توان» در «ارتباط»: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  ۳. نمونه‌های تحلیلی «ارتباط میان‌فردی» در عمل: «گفت‌وگو» بین «دوستان» «معنا» «ساخته» می‌شود: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  «ارتباط سازمانی» در عمل: «جلسه» «سازمانی»، «بافت» «توان» است: «نقش» و «ساختار»، «ارتباط» را «بازتولید» می‌کنند.  «ارتباط بین‌فرهنگی» در عمل: «مذاکره» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است و «فهم» «فرهنگ» دیگر، «توان» است.', 'f4b06b3ba0c171027cf87b7b2346605680aabbcf1e8210a4638e4094ceb0b04a', 1221, 'ch-doc-card-691-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f4b06b3ba0c171027cf87b7b2346605680aabbcf1e8210a4638e4094ceb0b04a', token_count=1221, vector_point_id='ch-doc-card-691-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-691-9', 'doc-card-691', 'sec-card-691-4', 9, 'فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است و «فهم» «فرهنگ» دیگر، «توان» است.  «هوش فرهنگی» در عمل: «مذاکره‌گر» با «هوش فرهنگی» «بافت» «دیگر» را «فهم» می‌کند: «ارتباط» در «بافت» «بین‌فرهنگی»، «توان» است.  «تعارض و مذاکره» در عمل: «مذاکره» «حل» «تعارض» است: «ارتباط» در «تعارض»، «بافت» «حل» است.  «بافت‌محوری» در عمل: «معنا» در «بافت» «ساخته» می‌شود: «بافت» «بزرگ» (فرهنگ) و «بافت» «کوچک» (گفت‌وگو) در هم تنیده‌اند.  ۴. نقدها و چالش‌ها ۱. «میان‌فردی» و «بافت»: «ارتباط» «میان‌فردی» در «بافت» «توان» است: «توان» در «گفت‌وگو» عمل می‌کند و «میان‌فردی»، «میان‌ساختاری» است. ۲.', '4f66e19cee71c86691f4a1c87800cc8ea0d26c39a8114664a1b1dd7d40e29bf6', 1040, 'ch-doc-card-691-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4f66e19cee71c86691f4a1c87800cc8ea0d26c39a8114664a1b1dd7d40e29bf6', token_count=1040, vector_point_id='ch-doc-card-691-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
