INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-693-1', 'doc-card-693', 'sec-card-693-1', 1, 'ارتباطات بین‌فرهنگی، سازمانی و میان‌فردی  نظریه سامانه–جهان «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». والرشتاین (۱۹۷۴) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس نظریه سامانه–جهان، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. والرشتاین (۱۹۷۴) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', '7f7b2d8829716f90891b61285ddc065e7f70dff45aea7f374277e7595918f2de', 979, 'ch-doc-card-693-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7f7b2d8829716f90891b61285ddc065e7f70dff45aea7f374277e7595918f2de', token_count=979, vector_point_id='ch-doc-card-693-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-693-2', 'doc-card-693', 'sec-card-693-1', 2, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  نظریه سامانه–جهان را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. والرشتاین (۱۹۷۴) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.', '58aa15c3912887f092f3341420eb44be9f9fa62c920a86e4229bbe2b64c5c933', 641, 'ch-doc-card-693-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='58aa15c3912887f092f3341420eb44be9f9fa62c920a86e4229bbe2b64c5c933', token_count=641, vector_point_id='ch-doc-card-693-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
