INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-693-4', 'doc-card-693', 'sec-card-693-2', 4, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  نظریه سامانه–جهان را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. والرشتاین (۱۹۷۴) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.  ۲. ساختارهای مفهومی • ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند.', 'f1f596276154a5d113c63cc4cfe8a89ccb8051cf25001505b6cf9ff5474444c4', 1120, 'ch-doc-card-693-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f1f596276154a5d113c63cc4cfe8a89ccb8051cf25001505b6cf9ff5474444c4', token_count=1120, vector_point_id='ch-doc-card-693-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
