INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-694-1', 'doc-card-694', 'sec-card-694-1', 1, 'ارتباطات بین‌فرهنگی، سازمانی و میان‌فردی  گزارش مکبراید «ارتباط» را «بافت» «معنا» می‌داند: نه «انتقال» «محتوا» بلکه «ساختن» «معنا» در «بافت». شون مکبراید (۱۹۸۰) در این چارچوب، «میان‌فردی» را «بافت» «ارتباط» تعریف کرد: «معنا» در «گفت‌وگو» «ساخته» می‌شود، نه در «فرستنده».  بر اساس گزارش مکبراید، «سازمانی» «بافت» «قدرت» و «نقش» است: «ساختار» و «فرهنگ» سازمانی، «ارتباط» را «بازتولید» می‌کنند. شون مکبراید (۱۹۸۰) در این چارچوب، «ارتباط سازمانی» را نه «جریان» «معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.', '9278732f897f53db72c72e02eeb71613e0b713d69596160ea718712a77cdca0d', 972, 'ch-doc-card-694-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9278732f897f53db72c72e02eeb71613e0b713d69596160ea718712a77cdca0d', token_count=972, vector_point_id='ch-doc-card-694-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-694-2', 'doc-card-694', 'sec-card-694-1', 2, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  گزارش مکبراید را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. شون مکبراید (۱۹۸۰) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.', 'd4f4a27d6789e43aea209740df34b002a69b52f63c9b715d362eb40b5394e6b1', 638, 'ch-doc-card-694-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d4f4a27d6789e43aea209740df34b002a69b52f63c9b715d362eb40b5394e6b1', token_count=638, vector_point_id='ch-doc-card-694-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
