INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-694-4', 'doc-card-694', 'sec-card-694-2', 4, '«معلومات» بلکه «بافت» «توان» تعریف کرد: «توان» در «نقش» و «ساختار» عمل می‌کند.  گزارش مکبراید را می‌توان پاسخی به شکاف میان «ارتباط» «میان‌فردی» (بافت) و «ارتباط» «بین‌فرهنگی» (بافت بزرگ) دانست: «فرهنگ» «بافت» «ارتباط» است و «بافت» «معنا» را «بازتولید» می‌کند. شون مکبراید (۱۹۸۰) در این چارچوب، «ارتباط» را «بافت» «دیالکتیک» «فرد» و «فرهنگ» تعریف کرد.  ۲. ساختارهای مفهومی • ارتباط میان‌فردی (Interpersonal Communication): «بافت» «ارتباط» بین «افراد»: «معنا» در «گفت‌وگو» «ساخته» می‌شود. • ارتباط سازمانی (Organizational Communication): «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند.', '8dfd56c7aaaf162ce39ee1b38bda63d0aa38880f16da74621621b57a539b44d1', 1116, 'ch-doc-card-694-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8dfd56c7aaaf162ce39ee1b38bda63d0aa38880f16da74621621b57a539b44d1', token_count=1116, vector_point_id='ch-doc-card-694-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-694-5', 'doc-card-694', 'sec-card-694-2', 5, ': «جریان» «معلومات» در «ساختار» سازمانی: «توان» در «نقش» و «ساختار» عمل می‌کند. • فرهنگ سازمانی (Organizational Culture): «ارزش‌ها» و «باورها» در سازمان: «فرهنگ»، «ارتباط» را «بازتولید» می‌کند. • ارتباط بین‌فرهنگی (Intercultural Communication): «ارتباط» بین «فرهنگ‌های» مختلف: «فرهنگ»، «بافت» «معنا» است. • هوش فرهنگی (Cultural Intelligence): «توان» «ارتباط» در «بافت» «بین‌فرهنگی»: «فهم» و «بازی» با «فرهنگ» دیگر. • تعارض و مذاکره (Conflict and Nego', 'ce2970881759cec7e5c50b7ab1fe0a7b615b8f4eb4228e7699d52fb04de653ec', 818, 'ch-doc-card-694-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ce2970881759cec7e5c50b7ab1fe0a7b615b8f4eb4228e7699d52fb04de653ec', token_count=818, vector_point_id='ch-doc-card-694-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
