INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-694-13', 'doc-card-694', 'sec-card-694-6', 13, '۱. «میان‌فردی» و «بافت»: «ارتباط» «میان‌فردی» در «بافت» «توان» است: «توان» در «گفت‌وگو» عمل می‌کند و «میان‌فردی»، «میان‌ساختاری» است. ۲. «فرهنگ سازمانی» و «قدرت»: «فرهنگ» در سازمان، «قدرت» است: «فرهنگ» «رقابت»، «فشار» می‌سازد و «ارتباط» را «بازتولید» می‌کند. ۳. «هوش فرهنگی» و «استعمار»: «هوش فرهنگی» می‌تواند «تثبیت» «فرهنگ» دیگر باشد: «فهم» «فرهنگ» دیگر، «آزادی» نیست، «توان» است. ۴. «ارتباط بین‌فرهنگی» و «دوگانه»: «فرهنگ» «دوگانه» نیست: «تنوع» داخل «فرهنگ» به‌قدری «بزرگ» است که «دوگانه» «افسانه» است. ۵. «مذاکره» و «توان»: «مذاکره» در «توان» «نامتقارن»، «حل» «تعارض» نیست', 'c23b7447826b60647458a2d7d01fc71144cc1a740dda9a9d6c4cef757a8dc3a2', 1047, 'ch-doc-card-694-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c23b7447826b60647458a2d7d01fc71144cc1a740dda9a9d6c4cef757a8dc3a2', token_count=1047, vector_point_id='ch-doc-card-694-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-694-14', 'doc-card-694', 'sec-card-694-7', 14, ': «توان»، «مذاکره» را «بازتولید» می‌کند. ۶. «بافت‌محوری» و «تعمیم»: «معنا» در «بافت» «ساخته» می‌شود اما «بافت» «تعمیم» «پذیر» نیست: «بافت» «بومی» است و «تحلیل»، «بومی» لازم دارد. ۷. «ارتباط سازمانی» و «ساختار»: «ارتباط» در «ساختار» «سازمانی»، «بازتولید» «توان» است: «ساختار»، «ارتباط» است. ۸. «ارتباط» و «رسانه»: «ارتباط» «میان‌فردی» و «سازمانی» در «عصر دیجیتال»، «رسانه» «دیجیتال» «بازتعریف» می‌شود: «بافت» «دیجیتال»، «ارتباط» را «بازتولید» می‌کند. ۹. «هوش فرهنگی» و «بافت»: «هوش فرهنگی» در «بافت» «دیجیتال»، «بازتعریف» می‌شود: «بافت» «دیجیتال»، «فرهنگ» را «بازتولید» می‌کند.', '6bdec743a480fb86611d0cdb02061e889fbe8f7dd8911f02a030608c0f3c2be5', 1047, 'ch-doc-card-694-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6bdec743a480fb86611d0cdb02061e889fbe8f7dd8911f02a030608c0f3c2be5', token_count=1047, vector_point_id='ch-doc-card-694-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-694-15', 'doc-card-694', 'sec-card-694-10', 15, 'کتاب «ارتباط میان‌فردی» (آدلمن و همکاران، ۱۹۹۸)؛ کتاب «ارتباط سازمانی» (مکنزی و همکاران، ۲۰۰۵)؛ کتاب «ارتباط بین‌فرهنگی» (لومبونگ و همکاران، ۲۰۰۳)؛ کتاب «هوش فرهنگی» (رابن و همکاران، ۲۰۰۷).', '956a1e981812fd0aee168d40ca4cfc0e60c304bdfcef5b69be87a8e90e1ab9e3', 343, 'ch-doc-card-694-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='956a1e981812fd0aee168d40ca4cfc0e60c304bdfcef5b69be87a8e90e1ab9e3', token_count=343, vector_point_id='ch-doc-card-694-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-695-0', 'doc-card-695', NULL, 0, 'چارچوب آینه/بازتاب در برابر برساخت روزنامه‌نگاری را «حرفه‌ی» گزارش‌دهی «واقعیت» بر اساس «اصول» مشخص می‌داند: «استقلال»، «دقت»، «پاسخگویی» و «خدمت به عموم». شادسون در این چارچوب، «خبر» را نه «حقیقت خام» بلکه «ساخته‌ی حرفه‌ای» تعریف کرد: «خبر» از «فرزشت» (gatekeeping) …', '71efd81ef95b1fd91fd0cd2c0f544c22d1c30eb75b82905b2ad768e1a13d35ad', 487, 'ch-doc-card-695-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='71efd81ef95b1fd91fd0cd2c0f544c22d1c30eb75b82905b2ad768e1a13d35ad', token_count=487, vector_point_id='ch-doc-card-695-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-695-1', 'doc-card-695', 'sec-card-695-1', 1, 'روزنامه‌نگاری  چارچوب آینه/بازتاب در برابر برساخت روزنامه‌نگاری را «حرفه‌ی» گزارش‌دهی «واقعیت» بر اساس «اصول» مشخص می‌داند: «استقلال»، «دقت»، «پاسخگویی» و «خدمت به عموم». شادسون در این چارچوب، «خبر» را نه «حقیقت خام» بلکه «ساخته‌ی حرفه‌ای» تعریف کرد: «خبر» از «فرزشت» (gatekeeping)، «چارچوب‌بندی» و «اصول حرفه‌ای» می‌گذرد تا به «خواننده» برسد.  بر اساس چارچوب آینه/بازتاب در برابر برساخت، «اعتبار» روزنامه‌نگاری، «سرمایه‌ی» اصلی آن است: «اعتبار» از «دقت»، «استقلال» و «پاسخگویی» ساخته می‌شود و «بازتولید» روزانه‌ی آن، «اعتماد» عمومی را حفظ می‌کند. شادسون در این چارچوب، «رسانه» را نه «نهاد تبلیغاتی» بلکه «سازوکار پاسخگویی» خواند: «رسانه»، «نظارت» بر «قدرت» انجام می‌دهد.', '8d9d9def8ef2eaeabe94f616aae0bb6c7034e47496ed3545c29ce76f8a564e09', 1220, 'ch-doc-card-695-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8d9d9def8ef2eaeabe94f616aae0bb6c7034e47496ed3545c29ce76f8a564e09', token_count=1220, vector_point_id='ch-doc-card-695-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-695-2', 'doc-card-695', 'sec-card-695-1', 2, 'یغاتی» بلکه «سازوکار پاسخگویی» خواند: «رسانه»، «نظارت» بر «قدرت» انجام می‌دهد.  چارچوب آینه/بازتاب در برابر برساخت را می‌توان پاسخی به شکاف میان «روزنامه‌نگاری حرفه‌ای» (تحت «نهاد») و «روزنامه‌نگاری شهروندی» (بی‌«نهاد») دانست: در «عصر دیجیتال»، «مرز» بین «حرفه‌ای» و «شهروند» «کمرنگ» شده و «اعتبار» باید «بازسازی» شود. شادسون در این چارچوب، «اصول» را «ثابت» و «فرمت» را «متغیر» خواند: «اصول» (دقت، استقلال، پاسخگویی) در هر «فرمت» باید «حاضر» باشند.', '8db7b921b1a3fd27d1a5c1e3a575a2685ec3bc7da5bc6a03e42ab43e6f16cf63', 814, 'ch-doc-card-695-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8db7b921b1a3fd27d1a5c1e3a575a2685ec3bc7da5bc6a03e42ab43e6f16cf63', token_count=814, vector_point_id='ch-doc-card-695-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-695-3', 'doc-card-695', 'sec-card-695-2', 3, '۱. بنیان و منطق نظری چارچوب آینه/بازتاب در برابر برساخت روزنامه‌نگاری را «حرفه‌ی» گزارش‌دهی «واقعیت» بر اساس «اصول» مشخص می‌داند: «استقلال»، «دقت»، «پاسخگویی» و «خدمت به عموم». شادسون در این چارچوب، «خبر» را نه «حقیقت خام» بلکه «ساخته‌ی حرفه‌ای» تعریف کرد: «خبر» از «فرزشت» (gatekeeping)، «چارچوب‌بندی» و «اصول حرفه‌ای» می‌گذرد تا به «خواننده» برسد.  بر اساس چارچوب آینه/بازتاب در برابر برساخت، «اعتبار» روزنامه‌نگاری، «سرمایه‌ی» اصلی آن است: «اعتبار» از «دقت»، «استقلال» و «پاسخگویی» ساخته می‌شود و «بازتولید» روزانه‌ی آن، «اعتماد» عمومی را حفظ می‌کند. شادسون در این چارچوب، «رسانه» را نه «نهاد تبلیغاتی» بلکه «سازوکار پاسخگویی» خواند: «رسانه»، «نظارت» بر «قدرت» انجام می‌دهد.', 'ce3bca54567bf37051aea85a4d0d94069f4810aede94abcf229bdd6ed95f446a', 1230, 'ch-doc-card-695-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ce3bca54567bf37051aea85a4d0d94069f4810aede94abcf229bdd6ed95f446a', token_count=1230, vector_point_id='ch-doc-card-695-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-695-4', 'doc-card-695', 'sec-card-695-2', 4, 'یغاتی» بلکه «سازوکار پاسخگویی» خواند: «رسانه»، «نظارت» بر «قدرت» انجام می‌دهد.  چارچوب آینه/بازتاب در برابر برساخت را می‌توان پاسخی به شکاف میان «روزنامه‌نگاری حرفه‌ای» (تحت «نهاد») و «روزنامه‌نگاری شهروندی» (بی‌«نهاد») دانست: در «عصر دیجیتال»، «مرز» بین «حرفه‌ای» و «شهروند» «کمرنگ» شده و «اعتبار» باید «بازسازی» شود. شادسون در این چارچوب، «اصول» را «ثابت» و «فرمت» را «متغیر» خواند: «اصول» (دقت، استقلال، پاسخگویی) در هر «فرمت» باید «حاضر» باشند.  ۲. ساختارهای مفهومی • فرزشت (Gatekeeping): فرایند «انتخاب» که «چه خبر» است و «چه خبر نیست»؛ «فرزشت» در «هر سطح» (مخبر، ویراستار، مدیر) عمل می‌کند.', 'fc5627c57e5871efcd45e1bf3099fae46348fd4261ca3410893d155f2437189c', 1083, 'ch-doc-card-695-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fc5627c57e5871efcd45e1bf3099fae46348fd4261ca3410893d155f2437189c', token_count=1083, vector_point_id='ch-doc-card-695-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-695-5', 'doc-card-695', 'sec-card-695-2', 5, 'بر» است و «چه خبر نیست»؛ «فرزشت» در «هر سطح» (مخبر، ویراستار، مدیر) عمل می‌کند. • چارچوب‌بندی (Framing): «نحوه‌ی» ارائه «خبر»: «چه چیزی» در «پیش‌زمینه» و «چه چیزی» در «پس‌زمینه» است؛ «چارچوب»، «معنا» می‌سازد. • اعتبار حرفه‌ای (Professional Credibility): «اعتماد» عمومی به «حرفه»؛ از «دقت»، «استقلال» و «پاسخگویی» ساخته می‌شود. • نظارت بر قدرت (Watchdog Function): «نقش» رسانه به‌عنوان «نظارت» بر «قدرت» (دولت، اقتصاد)؛ «روزنامه‌نگاری تحقیقی»، ابزار اصلی آن است. • روزنامه‌نگاری تحقیقی (Investigative Journalism): «گزارش‌دهی» «عمیق» از «مخفی‌ها»؛ «زمان»، «منابع» و «ری', '40fe134d840515d32aaabe22daf5225ea26c93f283e26690fdaaadf37e0fb7c5', 1030, 'ch-doc-card-695-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='40fe134d840515d32aaabe22daf5225ea26c93f283e26690fdaaadf37e0fb7c5', token_count=1030, vector_point_id='ch-doc-card-695-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-695-6', 'doc-card-695', 'sec-card-695-3', 6, '• فرزشت (Gatekeeping): فرایند «انتخاب» که «چه خبر» است و «چه خبر نیست»؛ «فرزشت» در «هر سطح» (مخبر، ویراستار، مدیر) عمل می‌کند. • چارچوب‌بندی (Framing): «نحوه‌ی» ارائه «خبر»: «چه چیزی» در «پیش‌زمینه» و «چه چیزی» در «پس‌زمینه» است؛ «چارچوب»، «معنا» می‌سازد. • اعتبار حرفه‌ای (Professional Credibility): «اعتماد» عمومی به «حرفه»؛ از «دقت»، «استقلال» و «پاسخگویی» ساخته می‌شود. • نظارت بر قدرت (Watchdog Function): «نقش» رسانه به‌عنوان «نظارت» بر «قدرت» (دولت، اقتصاد)؛ «روزنامه‌نگاری تحقیقی»، ابزار اصلی آن است. • روزنامه‌نگاری تحقیقی (Investigative Journalism): «گزارش‌دهی» «عمیق» از «مخفی‌ها»؛ «زمان»، «منابع» و «ریسک» دارد و «اعتبار» را «حفظ» می‌کند.', 'a7e0e198bbe769eff4697ac10291d5e8db94b5e8d5dca8fae1769bc5b01ad650', 1181, 'ch-doc-card-695-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a7e0e198bbe769eff4697ac10291d5e8db94b5e8d5dca8fae1769bc5b01ad650', token_count=1181, vector_point_id='ch-doc-card-695-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-695-7', 'doc-card-695', 'sec-card-695-3', 7, '«عمیق» از «مخفی‌ها»؛ «زمان»، «منابع» و «ریسک» دارد و «اعتبار» را «حفظ» می‌کند. • روزنامه‌نگاری شهروندی (Citizen Journalism): «گزارش‌دهی» توسط «غیرحرفه‌ای‌ها»؛ «سرعت» و «حضور» دارد اما «اصول» و «اعتبار» آن «نامشخص» است. • اصول حرفه‌ای (Journalistic Norms): «دقت»، «استقلال»، «پاسخگویی»، «عدالت» و «حداقل آسیب»؛ «اصول»، «ثابت»‌اند و «فرمت»، «متغیر» است. • اعتماد عمومی (Public Trust): «سرمایه‌ی» اجتماعی رسانه؛ «اعتبار» بدون «اعتماد» «معنا» ندارد و «اعتماد»، «بازتولید» روزانه نیاز دارد.', '186672da8fd82ac295b210aaa303d8a3c416e1f4f3f5e0217cdd913e789c662b', 881, 'ch-doc-card-695-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='186672da8fd82ac295b210aaa303d8a3c416e1f4f3f5e0217cdd913e789c662b', token_count=881, vector_point_id='ch-doc-card-695-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-695-8', 'doc-card-695', 'sec-card-695-4', 8, 'سک» دارد و «اعتبار» را «حفظ» می‌کند. • روزنامه‌نگاری شهروندی (Citizen Journalism): «گزارش‌دهی» توسط «غیرحرفه‌ای‌ها»؛ «سرعت» و «حضور» دارد اما «اصول» و «اعتبار» آن «نامشخص» است. • اصول حرفه‌ای (Journalistic Norms): «دقت»، «استقلال»، «پاسخگویی»، «عدالت» و «حداقل آسیب»؛ «اصول»، «ثابت»‌اند و «فرمت»، «متغیر» است. • اعتماد عمومی (Public Trust): «سرمایه‌ی» اجتماعی رسانه؛ «اعتبار» بدون «اعتماد» «معنا» ندارد و «اعتماد»، «بازتولید» روزانه نیاز دارد.  ۳. نمونه‌های تحلیلی «فرزشت» در عمل: «ویراستار» با «انتخاب» «کد» از بین «۵۰ خبر»، «نشان» می‌دهد که «چه خبر» است: «انتخاب» خود، «چارچوب» است.', '0979abbe408ed0295cba9349bb373f5752433aa420007b450849953106b319fa', 1061, 'ch-doc-card-695-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0979abbe408ed0295cba9349bb373f5752433aa420007b450849953106b319fa', token_count=1061, vector_point_id='ch-doc-card-695-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-695-9', 'doc-card-695', 'sec-card-695-4', 9, 'د» از بین «۵۰ خبر»، «نشان» می‌دهد که «چه خبر» است: «انتخاب» خود، «چارچوب» است.  «چارچوب‌بندی» در عمل: وقتی «بحران» اقتصادی «به‌عنوان» «کم‌کاری دولت» چارچوب می‌شود، «معنا» از «پیش» ساخته شده است: «نحوه‌ی» ارائه، «واقعیت» می‌سازد.  «روزنامه‌نگاری تحقیقی» در عمل: «گزارش» از «فساد» در «نهاد دولتی»، «نظارت» بر «قدرت» است: «زمان» (ماه‌ها)، «منابع» (سند، فرد) و «ریسک» (حقوقی) دارد.  «روزنامه‌نگاری شهروندی» در عمل: «گزارش» «مستقیم» از «تظاهرات» در «شبکه‌های اجتماعی»، «سرعت» و «حضور» دارد اما «دقت» و «اصول» آن «نامشخص» است: «اعتبار»، «چالش» اصلی است.', 'e17a892dba658c652f005bb877c6734d7c602a016230677a88f92cfe190d16c0', 994, 'ch-doc-card-695-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e17a892dba658c652f005bb877c6734d7c602a016230677a88f92cfe190d16c0', token_count=994, vector_point_id='ch-doc-card-695-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-695-10', 'doc-card-695', 'sec-card-695-4', 10, '» و «حضور» دارد اما «دقت» و «اصول» آن «نامشخص» است: «اعتبار»، «چالش» اصلی است.  «اعتبار» در «بحران»: وقتی «رسانه‌ای» «خطا» می‌کند، «اعتراف» و «اصلاح»، «اعتبار» را «حفظ» می‌کند: «پاسخگویی»، «ابزار» «بازتولید» «اعتماد» است.  «استقلال» در عمل: «رسانه‌ای» که «مالکیت» آن «وابسته» به «نهاد سیاسی» است، «استقلال» ندارد و «خبر» آن، «تبلیغ» است: «مالکیت»، «استقلال» را «تعیین» می‌کند.  ۴. نقدها و چالش‌ها ۱. «اصول حرفه‌ای» «ارزش‌ها» هستند: «دقت» و «استقلال» «سنجش‌پذیر» نیستند و «اعتبار» به «خودارزیابی» تقلیل می‌یابد. ۲. «نظارت بر قدرت» در عمل «وابسته» است: «روزنامه‌نگاری تحقیقی» در «بافت‌های دولتی» «محدود» است و «نظارت» به «گزارش» تقلیل می‌یابد. ۳.', '3e36b5400d383666e1bad12529a11ef134a5cc91aa6d820fa36a70d688c3f4cd', 1170, 'ch-doc-card-695-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3e36b5400d383666e1bad12529a11ef134a5cc91aa6d820fa36a70d688c3f4cd', token_count=1170, vector_point_id='ch-doc-card-695-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-695-11', 'doc-card-695', 'sec-card-695-4', 11, 'تحقیقی» در «بافت‌های دولتی» «محدود» است و «نظارت» به «گزارش» تقلیل می‌یابد. ۳. «روزنامه‌نگاری شهروندی» و «اعتبار»: «مرز» بین «حرفه‌ای» و «شهرو', '9b5f0f74ecc8b5988f5f6489b1e2c35d1edd9a58b8e1da607f30659f64fa05df', 258, 'ch-doc-card-695-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9b5f0f74ecc8b5988f5f6489b1e2c35d1edd9a58b8e1da607f30659f64fa05df', token_count=258, vector_point_id='ch-doc-card-695-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-695-12', 'doc-card-695', 'sec-card-695-5', 12, '«فرزشت» در عمل: «ویراستار» با «انتخاب» «کد» از بین «۵۰ خبر»، «نشان» می‌دهد که «چه خبر» است: «انتخاب» خود، «چارچوب» است.  «چارچوب‌بندی» در عمل: وقتی «بحران» اقتصادی «به‌عنوان» «کم‌کاری دولت» چارچوب می‌شود، «معنا» از «پیش» ساخته شده است: «نحوه‌ی» ارائه، «واقعیت» می‌سازد.  «روزنامه‌نگاری تحقیقی» در عمل: «گزارش» از «فساد» در «نهاد دولتی»، «نظارت» بر «قدرت» است: «زمان» (ماه‌ها)، «منابع» (سند، فرد) و «ریسک» (حقوقی) دارد.  «روزنامه‌نگاری شهروندی» در عمل: «گزارش» «مستقیم» از «تظاهرات» در «شبکه‌های اجتماعی»، «سرعت» و «حضور» دارد اما «دقت» و «اصول» آن «نامشخص» است: «اعتبار»، «چالش» اصلی است.', 'b2c55244c9ae0c0feda5d024ded4915f9b6f6b729f8c3bd555483dfe3c90f2dc', 1069, 'ch-doc-card-695-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b2c55244c9ae0c0feda5d024ded4915f9b6f6b729f8c3bd555483dfe3c90f2dc', token_count=1069, vector_point_id='ch-doc-card-695-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-695-13', 'doc-card-695', 'sec-card-695-5', 13, '» و «حضور» دارد اما «دقت» و «اصول» آن «نامشخص» است: «اعتبار»، «چالش» اصلی است.  «اعتبار» در «بحران»: وقتی «رسانه‌ای» «خطا» می‌کند، «اعتراف» و «اصلاح»، «اعتبار» را «حفظ» می‌کند: «پاسخگویی»، «ابزار» «بازتولید» «اعتماد» است.  «استقلال» در عمل: «رسانه‌ای» که «مالکیت» آن «وابسته» به «نهاد سیاسی» است، «استقلال» ندارد و «خبر» آن، «تبلیغ» است: «مالکیت»، «استقلال» را «تعیین» می‌کند.', 'e0b1690251c049b893c626adb63cd3cf326bf236cb1c2caa7253b80c7476a21f', 683, 'ch-doc-card-695-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e0b1690251c049b893c626adb63cd3cf326bf236cb1c2caa7253b80c7476a21f', token_count=683, vector_point_id='ch-doc-card-695-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-695-14', 'doc-card-695', 'sec-card-695-6', 14, '۱. «اصول حرفه‌ای» «ارزش‌ها» هستند: «دقت» و «استقلال» «سنجش‌پذیر» نیستند و «اعتبار» به «خودارزیابی» تقلیل می‌یابد. ۲. «نظارت بر قدرت» در عمل «وابسته» است: «روزنامه‌نگاری تحقیقی» در «بافت‌های دولتی» «محدود» است و «نظارت» به «گزارش» تقلیل می‌یابد. ۳. «روزنامه‌نگاری شهروندی» و «اعتبار»: «مرز» بین «حرفه‌ای» و «شهروند» «کمرنگ» شده و «اعتبار» «بازسازی» نشده است: «هر کسی» «خبر» می‌سازد و «اعتبار»، «چالش» اصلی است. ۴. «فرزشت» و «ساختاری»: «فرزشت» صرفا «ویراستار» نیست: «مالکیت»، «بازار» و «الگوریتم» هم «فرزشت» می‌کنند: «ساختار»، «فرزشت» است. ۵. «چارچوب‌بندی» و «ایدئولوژی»: «چارچوب» همیشه «ایدئولوژیک» است و «خبر» «خنثی» وج', '49923e96ddebc7dddf52f59107a3f58238bdb3fc5b7d6f4ff863d5cb3d2e1b1e', 1125, 'ch-doc-card-695-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='49923e96ddebc7dddf52f59107a3f58238bdb3fc5b7d6f4ff863d5cb3d2e1b1e', token_count=1125, vector_point_id='ch-doc-card-695-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-695-15', 'doc-card-695', 'sec-card-695-7', 15, 'ود ندارد: «تحلیل» «چارچوب»، «نقد» «ایدئولوژی» می‌شود. ۶. «اعتبار» و «بازار»: «اعتبار» حرفه‌ای در «بازار» «رقابت» با «سرعت» و «محتوای» «فرهنگ عامه» است: «اعتبار» در برابر «سرعت»، «بازنده» است؟ ۷. «استقلال» در «اقتصاد داده» «بازتعریف» می‌شود: «درآمد» از «داده» و «تبلیغات» است و «استقلال» در «اقتصاد» «تعیین» می‌شود. ۸. «روزنامه‌نگاری تحقیقی» و «ریسک»: «تحقیقی» بودن «ریسک» دارد (حقوقی، امنیتی) و «حرفه‌ای» در «بافت‌های» «محدود»، «تحت فشار» است. ۹. «اعتماد عمومی» و «قطبی‌شدن»: «اعتماد» در «عصر دیجیتال» «قطبی» شده است: «مخاطب» به «رسانه‌ای» اعتماد می‌کند که «دیدگاه» او را «تأیید» می‌کند: «اعتماد»، «ایدئولوژیک» شده است.', 'e4437e49466e4a43a0f7175079c19355bd32c7f8439115aab07f59a9d7399c67', 1125, 'ch-doc-card-695-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e4437e49466e4a43a0f7175079c19355bd32c7f8439115aab07f59a9d7399c67', token_count=1125, vector_point_id='ch-doc-card-695-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-695-16', 'doc-card-695', 'sec-card-695-10', 16, 'کتاب «خبر چیست؟» (تورنر، ۱۹۷۹)؛ کتاب «روزنامه‌نگاری و اقتدار» (گارسیا، ۱۹۸۸)؛ کتاب «روزنامه‌نگاری تحقیقی» (آلن و همکاران، ۲۰۰۱)؛ کتاب «روزنامه‌نگاری شهروندی» (گراس و همکاران، ۲۰۰۹).', '6c486eeff52ca4898cccc820904163927b9bdcdde1030afa231f7fbffd16c26b', 329, 'ch-doc-card-695-16', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6c486eeff52ca4898cccc820904163927b9bdcdde1030afa231f7fbffd16c26b', token_count=329, vector_point_id='ch-doc-card-695-16', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-696-0', 'doc-card-696', NULL, 0, 'نظریه برساخت اجتماعی خبر روزنامه‌نگاری را «حرفه‌ی» گزارش‌دهی «واقعیت» بر اساس «اصول» مشخص می‌داند: «استقلال»، «دقت»، «پاسخگویی» و «خدمت به عموم». گمزون (۱۹۷۸) در این چارچوب، «خبر» را نه «حقیقت خام» بلکه «ساخته‌ی حرفه‌ای» تعریف کرد: «خبر» از «فرزشت» (gatekeeping)، «چارچوب‌بندی» و …', 'f709581007dcaac1b0a8a52dd1ad4acc6bf54c0e782d60c5b93663c7f5c40854', 510, 'ch-doc-card-696-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f709581007dcaac1b0a8a52dd1ad4acc6bf54c0e782d60c5b93663c7f5c40854', token_count=510, vector_point_id='ch-doc-card-696-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-696-1', 'doc-card-696', 'sec-card-696-1', 1, 'روزنامه‌نگاری  نظریه برساخت اجتماعی خبر روزنامه‌نگاری را «حرفه‌ی» گزارش‌دهی «واقعیت» بر اساس «اصول» مشخص می‌داند: «استقلال»، «دقت»، «پاسخگویی» و «خدمت به عموم». گمزون (۱۹۷۸) در این چارچوب، «خبر» را نه «حقیقت خام» بلکه «ساخته‌ی حرفه‌ای» تعریف کرد: «خبر» از «فرزشت» (gatekeeping)، «چارچوب‌بندی» و «اصول حرفه‌ای» می‌گذرد تا به «خواننده» برسد.  بر اساس نظریه برساخت اجتماعی خبر، «اعتبار» روزنامه‌نگاری، «سرمایه‌ی» اصلی آن است: «اعتبار» از «دقت»، «استقلال» و «پاسخگویی» ساخته می‌شود و «بازتولید» روزانه‌ی آن، «اعتماد» عمومی را حفظ می‌کند. گمزون (۱۹۷۸) در این چارچوب، «رسانه» را نه «نهاد تبلیغاتی» بلکه «سازوکار پاسخگویی» خواند: «رسانه»، «نظارت» بر «قدرت» انجام می‌دهد.', '1595fe26e6d4c22d5a2a247f8bdfc7f68000ddb93e7e63a0d0fd943fa2ed68c1', 1205, 'ch-doc-card-696-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1595fe26e6d4c22d5a2a247f8bdfc7f68000ddb93e7e63a0d0fd943fa2ed68c1', token_count=1205, vector_point_id='ch-doc-card-696-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-696-2', 'doc-card-696', 'sec-card-696-1', 2, 'یغاتی» بلکه «سازوکار پاسخگویی» خواند: «رسانه»، «نظارت» بر «قدرت» انجام می‌دهد.  نظریه برساخت اجتماعی خبر را می‌توان پاسخی به شکاف میان «روزنامه‌نگاری حرفه‌ای» (تحت «نهاد») و «روزنامه‌نگاری شهروندی» (بی‌«نهاد») دانست: در «عصر دیجیتال»، «مرز» بین «حرفه‌ای» و «شهروند» «کمرنگ» شده و «اعتبار» باید «بازسازی» شود. گمزون (۱۹۷۸) در این چارچوب، «اصول» را «ثابت» و «فرمت» را «متغیر» خواند: «اصول» (دقت، استقلال، پاسخگویی) در هر «فرمت» باید «حاضر» باشند.', 'c224851ecabb03f144cdc0a3e2b070f7af846f624a594429605ea5d39596112c', 807, 'ch-doc-card-696-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c224851ecabb03f144cdc0a3e2b070f7af846f624a594429605ea5d39596112c', token_count=807, vector_point_id='ch-doc-card-696-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-696-3', 'doc-card-696', 'sec-card-696-2', 3, '۱. بنیان و منطق نظری نظریه برساخت اجتماعی خبر روزنامه‌نگاری را «حرفه‌ی» گزارش‌دهی «واقعیت» بر اساس «اصول» مشخص می‌داند: «استقلال»، «دقت»، «پاسخگویی» و «خدمت به عموم». گمزون (۱۹۷۸) در این چارچوب، «خبر» را نه «حقیقت خام» بلکه «ساخته‌ی حرفه‌ای» تعریف کرد: «خبر» از «فرزشت» (gatekeeping)، «چارچوب‌بندی» و «اصول حرفه‌ای» می‌گذرد تا به «خواننده» برسد.  بر اساس نظریه برساخت اجتماعی خبر، «اعتبار» روزنامه‌نگاری، «سرمایه‌ی» اصلی آن است: «اعتبار» از «دقت»، «استقلال» و «پاسخگویی» ساخته می‌شود و «بازتولید» روزانه‌ی آن، «اعتماد» عمومی را حفظ می‌کند. گمزون (۱۹۷۸) در این چارچوب، «رسانه» را نه «نهاد تبلیغاتی» بلکه «سازوکار پاسخگویی» خواند: «رسانه»، «نظارت» بر «قدرت» انجام می‌دهد.', '01a2ad5258f6b6eb797967edb3c11934b87ce271df08476313459f4660faa72d', 1216, 'ch-doc-card-696-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='01a2ad5258f6b6eb797967edb3c11934b87ce271df08476313459f4660faa72d', token_count=1216, vector_point_id='ch-doc-card-696-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-696-4', 'doc-card-696', 'sec-card-696-2', 4, 'یغاتی» بلکه «سازوکار پاسخگویی» خواند: «رسانه»، «نظارت» بر «قدرت» انجام می‌دهد.  نظریه برساخت اجتماعی خبر را می‌توان پاسخی به شکاف میان «روزنامه‌نگاری حرفه‌ای» (تحت «نهاد») و «روزنامه‌نگاری شهروندی» (بی‌«نهاد») دانست: در «عصر دیجیتال»، «مرز» بین «حرفه‌ای» و «شهروند» «کمرنگ» شده و «اعتبار» باید «بازسازی» شود. گمزون (۱۹۷۸) در این چارچوب، «اصول» را «ثابت» و «فرمت» را «متغیر» خواند: «اصول» (دقت، استقلال، پاسخگویی) در هر «فرمت» باید «حاضر» باشند.  ۲. ساختارهای مفهومی • فرزشت (Gatekeeping): فرایند «انتخاب» که «چه خبر» است و «چه خبر نیست»؛ «فرزشت» در «هر سطح» (مخبر، ویراستار، مدیر) عمل می‌کند.', 'bda90917ba6f95b3a7288ca70c0607bed80cd0644a8bfed38d63deb08d19890e', 1076, 'ch-doc-card-696-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bda90917ba6f95b3a7288ca70c0607bed80cd0644a8bfed38d63deb08d19890e', token_count=1076, vector_point_id='ch-doc-card-696-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-696-5', 'doc-card-696', 'sec-card-696-2', 5, 'بر» است و «چه خبر نیست»؛ «فرزشت» در «هر سطح» (مخبر، ویراستار، مدیر) عمل می‌کند. • چارچوب‌بندی (Framing): «نحوه‌ی» ارائه «خبر»: «چه چیزی» در «پیش‌زمینه» و «چه چیزی» در «پس‌زمینه» است؛ «چارچوب»، «معنا» می‌سازد. • اعتبار حرفه‌ای (Professional Credibility): «اعتماد» عمومی به «حرفه»؛ از «دقت»، «استقلال» و «پاسخگویی» ساخته می‌شود. • نظارت بر قدرت (Watchdog Function): «نقش» رسانه به‌عنوان «نظارت» بر «قدرت» (دولت، اقتصاد)؛ «روزنامه‌نگاری تحقیقی»، ابزار اصلی آن است. • روزنامه‌نگاری تحقیقی (Investigative Journalism): «گزارش‌دهی» «عمیق» از «مخفی‌ها»؛ «زمان»، «منابع» و «ریسک»', 'bf54c70175816f12f60e2cb614b98aa7b42a00c23b311c717e927b11819350aa', 1036, 'ch-doc-card-696-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bf54c70175816f12f60e2cb614b98aa7b42a00c23b311c717e927b11819350aa', token_count=1036, vector_point_id='ch-doc-card-696-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-696-6', 'doc-card-696', 'sec-card-696-3', 6, '• فرزشت (Gatekeeping): فرایند «انتخاب» که «چه خبر» است و «چه خبر نیست»؛ «فرزشت» در «هر سطح» (مخبر، ویراستار، مدیر) عمل می‌کند. • چارچوب‌بندی (Framing): «نحوه‌ی» ارائه «خبر»: «چه چیزی» در «پیش‌زمینه» و «چه چیزی» در «پس‌زمینه» است؛ «چارچوب»، «معنا» می‌سازد. • اعتبار حرفه‌ای (Professional Credibility): «اعتماد» عمومی به «حرفه»؛ از «دقت»، «استقلال» و «پاسخگویی» ساخته می‌شود. • نظارت بر قدرت (Watchdog Function): «نقش» رسانه به‌عنوان «نظارت» بر «قدرت» (دولت، اقتصاد)؛ «روزنامه‌نگاری تحقیقی»، ابزار اصلی آن است. • روزنامه‌نگاری تحقیقی (Investigative Journalism): «گزارش‌دهی» «عمیق» از «مخفی‌ها»؛ «زمان»، «منابع» و «ریسک» دارد و «اعتبار» را «حفظ» می‌کند.', 'a7e0e198bbe769eff4697ac10291d5e8db94b5e8d5dca8fae1769bc5b01ad650', 1181, 'ch-doc-card-696-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a7e0e198bbe769eff4697ac10291d5e8db94b5e8d5dca8fae1769bc5b01ad650', token_count=1181, vector_point_id='ch-doc-card-696-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-696-7', 'doc-card-696', 'sec-card-696-3', 7, '«عمیق» از «مخفی‌ها»؛ «زمان»، «منابع» و «ریسک» دارد و «اعتبار» را «حفظ» می‌کند. • روزنامه‌نگاری شهروندی (Citizen Journalism): «گزارش‌دهی» توسط «غیرحرفه‌ای‌ها»؛ «سرعت» و «حضور» دارد اما «اصول» و «اعتبار» آن «نامشخص» است. • اصول حرفه‌ای (Journalistic Norms): «دقت»، «استقلال»، «پاسخگویی»، «عدالت» و «حداقل آسیب»؛ «اصول»، «ثابت»‌اند و «فرمت»، «متغیر» است. • اعتماد عمومی (Public Trust): «سرمایه‌ی» اجتماعی رسانه؛ «اعتبار» بدون «اعتماد» «معنا» ندارد و «اعتماد»، «بازتولید» روزانه نیاز دارد.', '186672da8fd82ac295b210aaa303d8a3c416e1f4f3f5e0217cdd913e789c662b', 881, 'ch-doc-card-696-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='186672da8fd82ac295b210aaa303d8a3c416e1f4f3f5e0217cdd913e789c662b', token_count=881, vector_point_id='ch-doc-card-696-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-696-8', 'doc-card-696', 'sec-card-696-4', 8, 'دارد و «اعتبار» را «حفظ» می‌کند. • روزنامه‌نگاری شهروندی (Citizen Journalism): «گزارش‌دهی» توسط «غیرحرفه‌ای‌ها»؛ «سرعت» و «حضور» دارد اما «اصول» و «اعتبار» آن «نامشخص» است. • اصول حرفه‌ای (Journalistic Norms): «دقت»، «استقلال»، «پاسخگویی»، «عدالت» و «حداقل آسیب»؛ «اصول»، «ثابت»‌اند و «فرمت»، «متغیر» است. • اعتماد عمومی (Public Trust): «سرمایه‌ی» اجتماعی رسانه؛ «اعتبار» بدون «اعتماد» «معنا» ندارد و «اعتماد»، «بازتولید» روزانه نیاز دارد.  ۳. نمونه‌های تحلیلی «فرزشت» در عمل: «ویراستار» با «انتخاب» «کد» از بین «۵۰ خبر»، «نشان» می‌دهد که «چه خبر» است: «انتخاب» خود، «چارچوب» است.', '530a932d78797178adff42e2f853b4b92245607d724009826758406f90c2152c', 1054, 'ch-doc-card-696-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='530a932d78797178adff42e2f853b4b92245607d724009826758406f90c2152c', token_count=1054, vector_point_id='ch-doc-card-696-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-696-9', 'doc-card-696', 'sec-card-696-4', 9, 'د» از بین «۵۰ خبر»، «نشان» می‌دهد که «چه خبر» است: «انتخاب» خود، «چارچوب» است.  «چارچوب‌بندی» در عمل: وقتی «بحران» اقتصادی «به‌عنوان» «کم‌کاری دولت» چارچوب می‌شود، «معنا» از «پیش» ساخته شده است: «نحوه‌ی» ارائه، «واقعیت» می‌سازد.  «روزنامه‌نگاری تحقیقی» در عمل: «گزارش» از «فساد» در «نهاد دولتی»، «نظارت» بر «قدرت» است: «زمان» (ماه‌ها)، «منابع» (سند، فرد) و «ریسک» (حقوقی) دارد.  «روزنامه‌نگاری شهروندی» در عمل: «گزارش» «مستقیم» از «تظاهرات» در «شبکه‌های اجتماعی»، «سرعت» و «حضور» دارد اما «دقت» و «اصول» آن «نامشخص» است: «اعتبار»، «چالش» اصلی است.', 'e17a892dba658c652f005bb877c6734d7c602a016230677a88f92cfe190d16c0', 994, 'ch-doc-card-696-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e17a892dba658c652f005bb877c6734d7c602a016230677a88f92cfe190d16c0', token_count=994, vector_point_id='ch-doc-card-696-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-696-10', 'doc-card-696', 'sec-card-696-4', 10, '» و «حضور» دارد اما «دقت» و «اصول» آن «نامشخص» است: «اعتبار»، «چالش» اصلی است.  «اعتبار» در «بحران»: وقتی «رسانه‌ای» «خطا» می‌کند، «اعتراف» و «اصلاح»، «اعتبار» را «حفظ» می‌کند: «پاسخگویی»، «ابزار» «بازتولید» «اعتماد» است.  «استقلال» در عمل: «رسانه‌ای» که «مالکیت» آن «وابسته» به «نهاد سیاسی» است، «استقلال» ندارد و «خبر» آن، «تبلیغ» است: «مالکیت»، «استقلال» را «تعیین» می‌کند.  ۴. نقدها و چالش‌ها ۱. «اصول حرفه‌ای» «ارزش‌ها» هستند: «دقت» و «استقلال» «سنجش‌پذیر» نیستند و «اعتبار» به «خودارزیابی» تقلیل می‌یابد. ۲. «نظارت بر قدرت» در عمل «وابسته» است: «روزنامه‌نگاری تحقیقی» در «بافت‌های دولتی» «محدود» است و «نظارت» به «گزارش» تقلیل می‌یابد. ۳.', '3e36b5400d383666e1bad12529a11ef134a5cc91aa6d820fa36a70d688c3f4cd', 1170, 'ch-doc-card-696-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3e36b5400d383666e1bad12529a11ef134a5cc91aa6d820fa36a70d688c3f4cd', token_count=1170, vector_point_id='ch-doc-card-696-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-696-11', 'doc-card-696', 'sec-card-696-4', 11, 'تحقیقی» در «بافت‌های دولتی» «محدود» است و «نظارت» به «گزارش» تقلیل می‌یابد. ۳. «روزنامه‌نگاری شهروندی» و «اعتبار»: «مرز» بین «حرفه‌ای» و «ش', 'd84b0987dbf486e2587c2afd83fd764a053b68ef9f85edf04ea5deeff7f04942', 252, 'ch-doc-card-696-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d84b0987dbf486e2587c2afd83fd764a053b68ef9f85edf04ea5deeff7f04942', token_count=252, vector_point_id='ch-doc-card-696-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-696-12', 'doc-card-696', 'sec-card-696-5', 12, '«فرزشت» در عمل: «ویراستار» با «انتخاب» «کد» از بین «۵۰ خبر»، «نشان» می‌دهد که «چه خبر» است: «انتخاب» خود، «چارچوب» است.  «چارچوب‌بندی» در عمل: وقتی «بحران» اقتصادی «به‌عنوان» «کم‌کاری دولت» چارچوب می‌شود، «معنا» از «پیش» ساخته شده است: «نحوه‌ی» ارائه، «واقعیت» می‌سازد.  «روزنامه‌نگاری تحقیقی» در عمل: «گزارش» از «فساد» در «نهاد دولتی»، «نظارت» بر «قدرت» است: «زمان» (ماه‌ها)، «منابع» (سند، فرد) و «ریسک» (حقوقی) دارد.  «روزنامه‌نگاری شهروندی» در عمل: «گزارش» «مستقیم» از «تظاهرات» در «شبکه‌های اجتماعی»، «سرعت» و «حضور» دارد اما «دقت» و «اصول» آن «نامشخص» است: «اعتبار»، «چالش» اصلی است.', 'b2c55244c9ae0c0feda5d024ded4915f9b6f6b729f8c3bd555483dfe3c90f2dc', 1069, 'ch-doc-card-696-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b2c55244c9ae0c0feda5d024ded4915f9b6f6b729f8c3bd555483dfe3c90f2dc', token_count=1069, vector_point_id='ch-doc-card-696-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-696-13', 'doc-card-696', 'sec-card-696-5', 13, '» و «حضور» دارد اما «دقت» و «اصول» آن «نامشخص» است: «اعتبار»، «چالش» اصلی است.  «اعتبار» در «بحران»: وقتی «رسانه‌ای» «خطا» می‌کند، «اعتراف» و «اصلاح»، «اعتبار» را «حفظ» می‌کند: «پاسخگویی»، «ابزار» «بازتولید» «اعتماد» است.  «استقلال» در عمل: «رسانه‌ای» که «مالکیت» آن «وابسته» به «نهاد سیاسی» است، «استقلال» ندارد و «خبر» آن، «تبلیغ» است: «مالکیت»، «استقلال» را «تعیین» می‌کند.', 'e0b1690251c049b893c626adb63cd3cf326bf236cb1c2caa7253b80c7476a21f', 683, 'ch-doc-card-696-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e0b1690251c049b893c626adb63cd3cf326bf236cb1c2caa7253b80c7476a21f', token_count=683, vector_point_id='ch-doc-card-696-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-696-14', 'doc-card-696', 'sec-card-696-6', 14, '۱. «اصول حرفه‌ای» «ارزش‌ها» هستند: «دقت» و «استقلال» «سنجش‌پذیر» نیستند و «اعتبار» به «خودارزیابی» تقلیل می‌یابد. ۲. «نظارت بر قدرت» در عمل «وابسته» است: «روزنامه‌نگاری تحقیقی» در «بافت‌های دولتی» «محدود» است و «نظارت» به «گزارش» تقلیل می‌یابد. ۳. «روزنامه‌نگاری شهروندی» و «اعتبار»: «مرز» بین «حرفه‌ای» و «شهروند» «کمرنگ» شده و «اعتبار» «بازسازی» نشده است: «هر کسی» «خبر» می‌سازد و «اعتبار»، «چالش» اصلی است. ۴. «فرزشت» و «ساختاری»: «فرزشت» صرفا «ویراستار» نیست: «مالکیت»، «بازار» و «الگوریتم» هم «فرزشت» می‌کنند: «ساختار»، «فرزشت» است. ۵. «چارچوب‌بندی» و «ایدئولوژی»: «چارچوب» همیشه «ایدئولوژیک» است و «خبر» «خنثی» وج', '49923e96ddebc7dddf52f59107a3f58238bdb3fc5b7d6f4ff863d5cb3d2e1b1e', 1125, 'ch-doc-card-696-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='49923e96ddebc7dddf52f59107a3f58238bdb3fc5b7d6f4ff863d5cb3d2e1b1e', token_count=1125, vector_point_id='ch-doc-card-696-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-696-15', 'doc-card-696', 'sec-card-696-7', 15, 'ود ندارد: «تحلیل» «چارچوب»، «نقد» «ایدئولوژی» می‌شود. ۶. «اعتبار» و «بازار»: «اعتبار» حرفه‌ای در «بازار» «رقابت» با «سرعت» و «محتوای» «فرهنگ عامه» است: «اعتبار» در برابر «سرعت»، «بازنده» است؟ ۷. «استقلال» در «اقتصاد داده» «بازتعریف» می‌شود: «درآمد» از «داده» و «تبلیغات» است و «استقلال» در «اقتصاد» «تعیین» می‌شود. ۸. «روزنامه‌نگاری تحقیقی» و «ریسک»: «تحقیقی» بودن «ریسک» دارد (حقوقی، امنیتی) و «حرفه‌ای» در «بافت‌های» «محدود»، «تحت فشار» است. ۹. «اعتماد عمومی» و «قطبی‌شدن»: «اعتماد» در «عصر دیجیتال» «قطبی» شده است: «مخاطب» به «رسانه‌ای» اعتماد می‌کند که «دیدگاه» او را «تأیید» می‌کند: «اعتماد»، «ایدئولوژیک» شده است.', 'e4437e49466e4a43a0f7175079c19355bd32c7f8439115aab07f59a9d7399c67', 1125, 'ch-doc-card-696-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e4437e49466e4a43a0f7175079c19355bd32c7f8439115aab07f59a9d7399c67', token_count=1125, vector_point_id='ch-doc-card-696-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-696-16', 'doc-card-696', 'sec-card-696-10', 16, 'کتاب «خبر چیست؟» (تورنر، ۱۹۷۹)؛ کتاب «روزنامه‌نگاری و اقتدار» (گارسیا، ۱۹۸۸)؛ کتاب «روزنامه‌نگاری تحقیقی» (آلن و همکاران، ۲۰۰۱)؛ کتاب «روزنامه‌نگاری شهروندی» (گراس و همکاران، ۲۰۰۹).', '6c486eeff52ca4898cccc820904163927b9bdcdde1030afa231f7fbffd16c26b', 329, 'ch-doc-card-696-16', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6c486eeff52ca4898cccc820904163927b9bdcdde1030afa231f7fbffd16c26b', token_count=329, vector_point_id='ch-doc-card-696-16', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-697-0', 'doc-card-697', NULL, 0, 'مدلی از هال (۱۹۷۸) که پوشش خبری را فرایندی برای مذاکره بر سر معنا می‌داند که در آن روایت رسمی غالب حفظ می‌شود اما مطالب چالش‌برانگیز از طریق حاشیه‌نشینی (marginalization) در قالب‌های کم‌اعتبار خنثی می‌شوند.', '00b29d05b36c9fc80e7cca5fe05dcf654455c46b3e9ce2c1cd30c3effb053a8c', 374, 'ch-doc-card-697-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='00b29d05b36c9fc80e7cca5fe05dcf654455c46b3e9ce2c1cd30c3effb053a8c', token_count=374, vector_point_id='ch-doc-card-697-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-697-1', 'doc-card-697', 'sec-card-697-1', 1, 'روزنامه‌نگاری  «پلیسینگ the Crisis»', '75861e56daf91db82ebd7a0fc30b1226daa191f257212a5d43fbdaabd198c19f', 63, 'ch-doc-card-697-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='75861e56daf91db82ebd7a0fc30b1226daa191f257212a5d43fbdaabd198c19f', token_count=63, vector_point_id='ch-doc-card-697-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-697-2', 'doc-card-697', 'sec-card-697-2', 2, '۱. بنیان و منطق نظری مدل مذاکره/حاشیهنشینی خبر روزنامه‌نگاری را «حرفه‌ی» گزارش‌دهی «واقعیت» بر اساس «اصول» مشخص می‌داند: «استقلال»، «دقت»، «پاسخگویی» و «خدمت به عموم». هال (۱۹۷۸) در این چارچوب، «خبر» را نه «حقیقت خام» بلکه «ساخته‌ی حرفه‌ای» تعریف کرد: «خبر» از «فرزشت» (gatekeeping)، «چارچوب‌بندی» و «اصول حرفه‌ای» می‌گذرد تا به «خواننده» برسد.  بر اساس مدل مذاکره/حاشیهنشینی خبر، «اعتبار» روزنامه‌نگاری، «سرمایه‌ی» اصلی آن است: «اعتبار» از «دقت»، «استقلال» و «پاسخگویی» ساخته می‌شود و «بازتولید» روزانه‌ی آن، «اعتماد» عمومی را حفظ می‌کند. هال (۱۹۷۸) در این چارچوب، «رسانه» را نه «نهاد تبلیغاتی» بلکه «سازوکار پاسخگویی» خواند: «رسانه»، «نظارت» بر «قدرت» انجام می‌دهد.', 'd04fc5737da50709899ff7870604910d5ebc5d160ac696083d1dd1cdde8f706e', 1212, 'ch-doc-card-697-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d04fc5737da50709899ff7870604910d5ebc5d160ac696083d1dd1cdde8f706e', token_count=1212, vector_point_id='ch-doc-card-697-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-697-3', 'doc-card-697', 'sec-card-697-2', 3, 'یغاتی» بلکه «سازوکار پاسخگویی» خواند: «رسانه»، «نظارت» بر «قدرت» انجام می‌دهد.  مدل مذاکره/حاشیهنشینی خبر را می‌توان پاسخی به شکاف میان «روزنامه‌نگاری حرفه‌ای» (تحت «نهاد») و «روزنامه‌نگاری شهروندی» (بی‌«نهاد») دانست: در «عصر دیجیتال»، «مرز» بین «حرفه‌ای» و «شهروند» «کمرنگ» شده و «اعتبار» باید «بازسازی» شود. هال (۱۹۷۸) در این چارچوب، «اصول» را «ثابت» و «فرمت» را «متغیر» خواند: «اصول» (دقت، استقلال، پاسخگویی) در هر «فرمت» باید «حاضر» باشند.  ۲. ساختارهای مفهومی • فرزشت (Gatekeeping): فرایند «انتخاب» که «چه خبر» است و «چه خبر نیست»؛ «فرزشت» در «هر سطح» (مخبر، ویراستار، مدیر) عمل می‌کند.', '3850ca115d52c1573dbf01a4d87afa2b47da70e7e77e07919a316b01fe6a2354', 1074, 'ch-doc-card-697-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3850ca115d52c1573dbf01a4d87afa2b47da70e7e77e07919a316b01fe6a2354', token_count=1074, vector_point_id='ch-doc-card-697-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-697-4', 'doc-card-697', 'sec-card-697-2', 4, 'بر» است و «چه خبر نیست»؛ «فرزشت» در «هر سطح» (مخبر، ویراستار، مدیر) عمل می‌کند. • چارچوب‌بندی (Framing): «نحوه‌ی» ارائه «خبر»: «چه چیزی» در «پیش‌زمینه» و «چه چیزی» در «پس‌زمینه» است؛ «چارچوب»، «معنا» می‌سازد. • اعتبار حرفه‌ای (Professional Credibility): «اعتماد» عمومی به «حرفه»؛ از «دقت»، «استقلال» و «پاسخگویی» ساخته می‌شود. • نظارت بر قدرت (Watchdog Function): «نقش» رسانه به‌عنوان «نظارت» بر «قدرت» (دولت، اقتصاد)؛ «روزنامه‌نگاری تحقیقی»، ابزار اصلی آن است. • روزنامه‌نگاری تحقیقی (Investigative Journalism): «گزارش‌دهی» «عمیق» از «مخفی‌ها»؛ «زمان»، «منابع» و «ریسک» دار', '34e4addf7c83228a58a474afd90cfc68b05e4d6c6356ae3d07aa1fc4c57116cb', 1043, 'ch-doc-card-697-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='34e4addf7c83228a58a474afd90cfc68b05e4d6c6356ae3d07aa1fc4c57116cb', token_count=1043, vector_point_id='ch-doc-card-697-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-697-5', 'doc-card-697', 'sec-card-697-3', 5, '• فرزشت (Gatekeeping): فرایند «انتخاب» که «چه خبر» است و «چه خبر نیست»؛ «فرزشت» در «هر سطح» (مخبر، ویراستار، مدیر) عمل می‌کند. • چارچوب‌بندی (Framing): «نحوه‌ی» ارائه «خبر»: «چه چیزی» در «پیش‌زمینه» و «چه چیزی» در «پس‌زمینه» است؛ «چارچوب»، «معنا» می‌سازد. • اعتبار حرفه‌ای (Professional Credibility): «اعتماد» عمومی به «حرفه»؛ از «دقت»، «استقلال» و «پاسخگویی» ساخته می‌شود. • نظارت بر قدرت (Watchdog Function): «نقش» رسانه به‌عنوان «نظارت» بر «قدرت» (دولت، اقتصاد)؛ «روزنامه‌نگاری تحقیقی»، ابزار اصلی آن است. • روزنامه‌نگاری تحقیقی (Investigative Journalism): «گزارش‌دهی» «عمیق» از «مخفی‌ها»؛ «زمان»، «منابع» و «ریسک» دارد و «اعتبار» را «حفظ» می‌کند.', 'a7e0e198bbe769eff4697ac10291d5e8db94b5e8d5dca8fae1769bc5b01ad650', 1181, 'ch-doc-card-697-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a7e0e198bbe769eff4697ac10291d5e8db94b5e8d5dca8fae1769bc5b01ad650', token_count=1181, vector_point_id='ch-doc-card-697-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-697-6', 'doc-card-697', 'sec-card-697-3', 6, '«عمیق» از «مخفی‌ها»؛ «زمان»، «منابع» و «ریسک» دارد و «اعتبار» را «حفظ» می‌کند. • روزنامه‌نگاری شهروندی (Citizen Journalism): «گزارش‌دهی» توسط «غیرحرفه‌ای‌ها»؛ «سرعت» و «حضور» دارد اما «اصول» و «اعتبار» آن «نامشخص» است. • اصول حرفه‌ای (Journalistic Norms): «دقت»، «استقلال»، «پاسخگویی»، «عدالت» و «حداقل آسیب»؛ «اصول»، «ثابت»‌اند و «فرمت»، «متغیر» است. • اعتماد عمومی (Public Trust): «سرمایه‌ی» اجتماعی رسانه؛ «اعتبار» بدون «اعتماد» «معنا» ندارد و «اعتماد»، «بازتولید» روزانه نیاز دارد.', '186672da8fd82ac295b210aaa303d8a3c416e1f4f3f5e0217cdd913e789c662b', 881, 'ch-doc-card-697-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='186672da8fd82ac295b210aaa303d8a3c416e1f4f3f5e0217cdd913e789c662b', token_count=881, vector_point_id='ch-doc-card-697-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-697-7', 'doc-card-697', 'sec-card-697-4', 7, 'د و «اعتبار» را «حفظ» می‌کند. • روزنامه‌نگاری شهروندی (Citizen Journalism): «گزارش‌دهی» توسط «غیرحرفه‌ای‌ها»؛ «سرعت» و «حضور» دارد اما «اصول» و «اعتبار» آن «نامشخص» است. • اصول حرفه‌ای (Journalistic Norms): «دقت»، «استقلال»، «پاسخگویی»، «عدالت» و «حداقل آسیب»؛ «اصول»، «ثابت»‌اند و «فرمت»، «متغیر» است. • اعتماد عمومی (Public Trust): «سرمایه‌ی» اجتماعی رسانه؛ «اعتبار» بدون «اعتماد» «معنا» ندارد و «اعتماد»، «بازتولید» روزانه نیاز دارد.  ۳. نمونه‌های تحلیلی «فرزشت» در عمل: «ویراستار» با «انتخاب» «کد» از بین «۵۰ خبر»، «نشان» می‌دهد که «چه خبر» است: «انتخاب» خود، «چارچوب» است.', '38c088fcf429f76b9e3e4ba7f0d28693744316f9894c80ff563b6d6db8f99ddf', 1049, 'ch-doc-card-697-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='38c088fcf429f76b9e3e4ba7f0d28693744316f9894c80ff563b6d6db8f99ddf', token_count=1049, vector_point_id='ch-doc-card-697-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-697-8', 'doc-card-697', 'sec-card-697-4', 8, 'د» از بین «۵۰ خبر»، «نشان» می‌دهد که «چه خبر» است: «انتخاب» خود، «چارچوب» است.  «چارچوب‌بندی» در عمل: وقتی «بحران» اقتصادی «به‌عنوان» «کم‌کاری دولت» چارچوب می‌شود، «معنا» از «پیش» ساخته شده است: «نحوه‌ی» ارائه، «واقعیت» می‌سازد.  «روزنامه‌نگاری تحقیقی» در عمل: «گزارش» از «فساد» در «نهاد دولتی»، «نظارت» بر «قدرت» است: «زمان» (ماه‌ها)، «منابع» (سند، فرد) و «ریسک» (حقوقی) دارد.  «روزنامه‌نگاری شهروندی» در عمل: «گزارش» «مستقیم» از «تظاهرات» در «شبکه‌های اجتماعی»، «سرعت» و «حضور» دارد اما «دقت» و «اصول» آن «نامشخص» است: «اعتبار»، «چالش» اصلی است.', 'e17a892dba658c652f005bb877c6734d7c602a016230677a88f92cfe190d16c0', 994, 'ch-doc-card-697-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e17a892dba658c652f005bb877c6734d7c602a016230677a88f92cfe190d16c0', token_count=994, vector_point_id='ch-doc-card-697-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-697-9', 'doc-card-697', 'sec-card-697-4', 9, '» و «حضور» دارد اما «دقت» و «اصول» آن «نامشخص» است: «اعتبار»، «چالش» اصلی است.  «اعتبار» در «بحران»: وقتی «رسانه‌ای» «خطا» می‌کند، «اعتراف» و «اصلاح»، «اعتبار» را «حفظ» می‌کند: «پاسخگویی»، «ابزار» «بازتولید» «اعتماد» است.  «استقلال» در عمل: «رسانه‌ای» که «مالکیت» آن «وابسته» به «نهاد سیاسی» است، «استقلال» ندارد و «خبر» آن، «تبلیغ» است: «مالکیت»، «استقلال» را «تعیین» می‌کند.  ۴. نقدها و چالش‌ها ۱. «اصول حرفه‌ای» «ارزش‌ها» هستند: «دقت» و «استقلال» «سنجش‌پذیر» نیستند و «اعتبار» به «خودارزیابی» تقلیل می‌یابد. ۲. «نظارت بر قدرت» در عمل «وابسته» است: «روزنامه‌نگاری تحقیقی» در «بافت‌های دولتی» «محدود» است و «نظارت» به «گزارش» تقلیل می‌یابد. ۳.', '3e36b5400d383666e1bad12529a11ef134a5cc91aa6d820fa36a70d688c3f4cd', 1170, 'ch-doc-card-697-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3e36b5400d383666e1bad12529a11ef134a5cc91aa6d820fa36a70d688c3f4cd', token_count=1170, vector_point_id='ch-doc-card-697-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-697-10', 'doc-card-697', 'sec-card-697-4', 10, 'تحقیقی» در «بافت‌های دولتی» «محدود» است و «نظارت» به «گزارش» تقلیل می‌یابد. ۳. «روزنامه‌نگاری شهروندی» و «اعتبار»: «مرز» بین «حرفه‌ای» و «شهر', '2c78e4fcf5c7430e4b771dfe0cfc5905d96605ad339428778bb28d7e849489e4', 256, 'ch-doc-card-697-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2c78e4fcf5c7430e4b771dfe0cfc5905d96605ad339428778bb28d7e849489e4', token_count=256, vector_point_id='ch-doc-card-697-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
