INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-701-13', 'doc-card-701', 'sec-card-701-5', 13, '» و «حضور» دارد اما «دقت» و «اصول» آن «نامشخص» است: «اعتبار»، «چالش» اصلی است.  «اعتبار» در «بحران»: وقتی «رسانه‌ای» «خطا» می‌کند، «اعتراف» و «اصلاح»، «اعتبار» را «حفظ» می‌کند: «پاسخگویی»، «ابزار» «بازتولید» «اعتماد» است.  «استقلال» در عمل: «رسانه‌ای» که «مالکیت» آن «وابسته» به «نهاد سیاسی» است، «استقلال» ندارد و «خبر» آن، «تبلیغ» است: «مالکیت»، «استقلال» را «تعیین» می‌کند.', 'e0b1690251c049b893c626adb63cd3cf326bf236cb1c2caa7253b80c7476a21f', 683, 'ch-doc-card-701-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e0b1690251c049b893c626adb63cd3cf326bf236cb1c2caa7253b80c7476a21f', token_count=683, vector_point_id='ch-doc-card-701-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-701-14', 'doc-card-701', 'sec-card-701-6', 14, '۱. «اصول حرفه‌ای» «ارزش‌ها» هستند: «دقت» و «استقلال» «سنجش‌پذیر» نیستند و «اعتبار» به «خودارزیابی» تقلیل می‌یابد. ۲. «نظارت بر قدرت» در عمل «وابسته» است: «روزنامه‌نگاری تحقیقی» در «بافت‌های دولتی» «محدود» است و «نظارت» به «گزارش» تقلیل می‌یابد. ۳. «روزنامه‌نگاری شهروندی» و «اعتبار»: «مرز» بین «حرفه‌ای» و «شهروند» «کمرنگ» شده و «اعتبار» «بازسازی» نشده است: «هر کسی» «خبر» می‌سازد و «اعتبار»، «چالش» اصلی است. ۴. «فرزشت» و «ساختاری»: «فرزشت» صرفا «ویراستار» نیست: «مالکیت»، «بازار» و «الگوریتم» هم «فرزشت» می‌کنند: «ساختار»، «فرزشت» است. ۵. «چارچوب‌بندی» و «ایدئولوژی»: «چارچوب» همیشه «ایدئولوژیک» است و «خبر» «خنثی» وج', '49923e96ddebc7dddf52f59107a3f58238bdb3fc5b7d6f4ff863d5cb3d2e1b1e', 1125, 'ch-doc-card-701-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='49923e96ddebc7dddf52f59107a3f58238bdb3fc5b7d6f4ff863d5cb3d2e1b1e', token_count=1125, vector_point_id='ch-doc-card-701-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-701-15', 'doc-card-701', 'sec-card-701-7', 15, 'ود ندارد: «تحلیل» «چارچوب»، «نقد» «ایدئولوژی» می‌شود. ۶. «اعتبار» و «بازار»: «اعتبار» حرفه‌ای در «بازار» «رقابت» با «سرعت» و «محتوای» «فرهنگ عامه» است: «اعتبار» در برابر «سرعت»، «بازنده» است؟ ۷. «استقلال» در «اقتصاد داده» «بازتعریف» می‌شود: «درآمد» از «داده» و «تبلیغات» است و «استقلال» در «اقتصاد» «تعیین» می‌شود. ۸. «روزنامه‌نگاری تحقیقی» و «ریسک»: «تحقیقی» بودن «ریسک» دارد (حقوقی، امنیتی) و «حرفه‌ای» در «بافت‌های» «محدود»، «تحت فشار» است. ۹. «اعتماد عمومی» و «قطبی‌شدن»: «اعتماد» در «عصر دیجیتال» «قطبی» شده است: «مخاطب» به «رسانه‌ای» اعتماد می‌کند که «دیدگاه» او را «تأیید» می‌کند: «اعتماد»، «ایدئولوژیک» شده است.', 'e4437e49466e4a43a0f7175079c19355bd32c7f8439115aab07f59a9d7399c67', 1125, 'ch-doc-card-701-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e4437e49466e4a43a0f7175079c19355bd32c7f8439115aab07f59a9d7399c67', token_count=1125, vector_point_id='ch-doc-card-701-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
