INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-702-1', 'doc-card-702', 'sec-card-702-1', 1, 'روزنامه‌نگاری  چارچوب روزنامهنگاری راهحلمحور روزنامه‌نگاری را «حرفه‌ی» گزارش‌دهی «واقعیت» بر اساس «اصول» مشخص می‌داند: «استقلال»، «دقت»، «پاسخگویی» و «خدمت به عموم». بنش در این چارچوب، «خبر» را نه «حقیقت خام» بلکه «ساخته‌ی حرفه‌ای» تعریف کرد: «خبر» از «فرزشت» (gatekeeping)، «چارچوب‌بندی» و «اصول حرفه‌ای» می‌گذرد تا به «خواننده» برسد.  بر اساس چارچوب روزنامهنگاری راهحلمحور، «اعتبار» روزنامه‌نگاری، «سرمایه‌ی» اصلی آن است: «اعتبار» از «دقت»، «استقلال» و «پاسخگویی» ساخته می‌شود و «بازتولید» روزانه‌ی آن، «اعتماد» عمومی را حفظ می‌کند. بنش در این چارچوب، «رسانه» را نه «نهاد تبلیغاتی» بلکه «سازوکار پاسخگویی» خواند: «رسانه»، «نظارت» بر «قدرت» انجام می‌دهد.', 'f999c13c23c2a0b24898230831a6d57a98a10f296c50ffb705d556ae3566f5ae', 1190, 'ch-doc-card-702-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f999c13c23c2a0b24898230831a6d57a98a10f296c50ffb705d556ae3566f5ae', token_count=1190, vector_point_id='ch-doc-card-702-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-702-2', 'doc-card-702', 'sec-card-702-1', 2, 'یغاتی» بلکه «سازوکار پاسخگویی» خواند: «رسانه»، «نظارت» بر «قدرت» انجام می‌دهد.  چارچوب روزنامهنگاری راهحلمحور را می‌توان پاسخی به شکاف میان «روزنامه‌نگاری حرفه‌ای» (تحت «نهاد») و «روزنامه‌نگاری شهروندی» (بی‌«نهاد») دانست: در «عصر دیجیتال»، «مرز» بین «حرفه‌ای» و «شهروند» «کمرنگ» شده و «اعتبار» باید «بازسازی» شود. بنش در این چارچوب، «اصول» را «ثابت» و «فرمت» را «متغیر» خواند: «اصول» (دقت، استقلال، پاسخگویی) در هر «فرمت» باید «حاضر» باشند.', 'e2359e14a38b8813ada8448a18f04dd6dd244203508c2d1fd8caf41b94724654', 799, 'ch-doc-card-702-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e2359e14a38b8813ada8448a18f04dd6dd244203508c2d1fd8caf41b94724654', token_count=799, vector_point_id='ch-doc-card-702-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
