INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-704-7', 'doc-card-704', 'sec-card-704-3', 7, '«عمیق» از «مخفی‌ها»؛ «زمان»، «منابع» و «ریسک» دارد و «اعتبار» را «حفظ» می‌کند. • روزنامه‌نگاری شهروندی (Citizen Journalism): «گزارش‌دهی» توسط «غیرحرفه‌ای‌ها»؛ «سرعت» و «حضور» دارد اما «اصول» و «اعتبار» آن «نامشخص» است. • اصول حرفه‌ای (Journalistic Norms): «دقت»، «استقلال»، «پاسخگویی»، «عدالت» و «حداقل آسیب»؛ «اصول»، «ثابت»‌اند و «فرمت»، «متغیر» است. • اعتماد عمومی (Public Trust): «سرمایه‌ی» اجتماعی رسانه؛ «اعتبار» بدون «اعتماد» «معنا» ندارد و «اعتماد»، «بازتولید» روزانه نیاز دارد.', '186672da8fd82ac295b210aaa303d8a3c416e1f4f3f5e0217cdd913e789c662b', 881, 'ch-doc-card-704-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='186672da8fd82ac295b210aaa303d8a3c416e1f4f3f5e0217cdd913e789c662b', token_count=881, vector_point_id='ch-doc-card-704-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
