INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-704-9', 'doc-card-704', 'sec-card-704-4', 9, 'د» از بین «۵۰ خبر»، «نشان» می‌دهد که «چه خبر» است: «انتخاب» خود، «چارچوب» است.  «چارچوب‌بندی» در عمل: وقتی «بحران» اقتصادی «به‌عنوان» «کم‌کاری دولت» چارچوب می‌شود، «معنا» از «پیش» ساخته شده است: «نحوه‌ی» ارائه، «واقعیت» می‌سازد.  «روزنامه‌نگاری تحقیقی» در عمل: «گزارش» از «فساد» در «نهاد دولتی»، «نظارت» بر «قدرت» است: «زمان» (ماه‌ها)، «منابع» (سند، فرد) و «ریسک» (حقوقی) دارد.  «روزنامه‌نگاری شهروندی» در عمل: «گزارش» «مستقیم» از «تظاهرات» در «شبکه‌های اجتماعی»، «سرعت» و «حضور» دارد اما «دقت» و «اصول» آن «نامشخص» است: «اعتبار»، «چالش» اصلی است.', 'e17a892dba658c652f005bb877c6734d7c602a016230677a88f92cfe190d16c0', 994, 'ch-doc-card-704-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e17a892dba658c652f005bb877c6734d7c602a016230677a88f92cfe190d16c0', token_count=994, vector_point_id='ch-doc-card-704-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-704-10', 'doc-card-704', 'sec-card-704-4', 10, '» و «حضور» دارد اما «دقت» و «اصول» آن «نامشخص» است: «اعتبار»، «چالش» اصلی است.  «اعتبار» در «بحران»: وقتی «رسانه‌ای» «خطا» می‌کند، «اعتراف» و «اصلاح»، «اعتبار» را «حفظ» می‌کند: «پاسخگویی»، «ابزار» «بازتولید» «اعتماد» است.  «استقلال» در عمل: «رسانه‌ای» که «مالکیت» آن «وابسته» به «نهاد سیاسی» است، «استقلال» ندارد و «خبر» آن، «تبلیغ» است: «مالکیت»، «استقلال» را «تعیین» می‌کند.  ۴. نقدها و چالش‌ها ۱. «اصول حرفه‌ای» «ارزش‌ها» هستند: «دقت» و «استقلال» «سنجش‌پذیر» نیستند و «اعتبار» به «خودارزیابی» تقلیل می‌یابد. ۲. «نظارت بر قدرت» در عمل «وابسته» است: «روزنامه‌نگاری تحقیقی» در «بافت‌های دولتی» «محدود» است و «نظارت» به «گزارش» تقلیل می‌یابد. ۳.', '3e36b5400d383666e1bad12529a11ef134a5cc91aa6d820fa36a70d688c3f4cd', 1170, 'ch-doc-card-704-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3e36b5400d383666e1bad12529a11ef134a5cc91aa6d820fa36a70d688c3f4cd', token_count=1170, vector_point_id='ch-doc-card-704-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
