INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-709-0', 'doc-card-709', NULL, 0, 'این نظریه در حوزه «روان‌شناسی رسانه، پردازش شناختی و عواطف» جای می‌گیرد و نظریه سرگرمی را به‌عنوان سازه‌ای بنیادین برای تبیین Entertainment در مطالعات رسانه و ارتباطات صورت‌بندی می‌کند؛ کاربرد اصلی آن تحلیل، توضیح و پیش‌بینی پدیده‌های مرتبط با همین دسته است.', 'b30ad6f1e2f375d4bc0cec6f8eb0b272644e7a64c505f6429391a1c5ed1b0bb1', 469, 'ch-doc-card-709-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b30ad6f1e2f375d4bc0cec6f8eb0b272644e7a64c505f6429391a1c5ed1b0bb1', token_count=469, vector_point_id='ch-doc-card-709-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
