INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-709-2', 'doc-card-709', 'sec-card-709-2', 2, '۱. بنیان و منطق نظری نظریه سرگرمی بهعنوان بازی «بازی» را «فعالیت» معنادار در «بافت» دیجیتال می‌داند: نه «فرار» از واقعیت بلکه «بازی» با «معنا». استیفنسون (۱۹۶۷) در این چارچوب، «فرهنگ» را نه «محصول» «صنعت» بلکه «فعالیت» مخاطب تعریف کرد: «بازی»، «زبان» «نسل» دیجیتال است.  بر اساس نظریه سرگرمی بهعنوان بازی، «سرگرمی» «صنعت» است اما «فرهنگ» «فعالیت» مخاطب است: «صنعت» «محتوا» تولید می‌کند و «مخاطب» «معنا» بازتولید می‌کند. استیفنسون (۱۹۶۷) در این چارچوب، «فرهنگ دیجیتال» را «فضا» «تولید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.', '087b99f2c1ac86d602de1c1e876d71347d610110f74f410c70ccc62e3ade825e', 1016, 'ch-doc-card-709-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='087b99f2c1ac86d602de1c1e876d71347d610110f74f410c70ccc62e3ade825e', token_count=1016, vector_point_id='ch-doc-card-709-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-709-3', 'doc-card-709', 'sec-card-709-2', 3, 'ید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  نظریه سرگرمی بهعنوان بازی را می‌توان پاسخی به شکاف میان «نقد» «صنعت فرهنگ» (فرانکفورت) و «مطالعات فرهنگی» (مقاومت مخاطب) دانست: «بازی» و «سرگرمی» هم «بازتولید» «ایدئولوژی» است و هم «مقاومت» مخاطب. استیفنسون (۱۹۶۷) در این چارچوب، «فرهنگ دیجیتال» را «میدان» «دیالکتیک» «صنعت» و «مخاطب» تعریف کرد.  ۲. ساختارهای مفهومی • بازی و فرهنگ (Play and Culture): «بازی» به‌عنوان «زبان» «نسل» دیجیتال: «معنا» در «بازی» ساخته می‌شود. • فرهنگ دیجیتال (Digital Culture): «بافت» «فرهنگی» «نسل» دیجیتال: «بازی»، «بازی»، «میم» و «ریپلای»، «زبان» این «بافت»‌اند.', '4b3e611e405950d2fffc6663e1c33ef934c023a3de01dcf090965b7f3da71bfc', 1130, 'ch-doc-card-709-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4b3e611e405950d2fffc6663e1c33ef934c023a3de01dcf090965b7f3da71bfc', token_count=1130, vector_point_id='ch-doc-card-709-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
