INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-710-1', 'doc-card-710', 'sec-card-710-1', 1, 'بازی، سرگرمی و فرهنگ دیجیتال  نظریه انتخاب مواجهه «بازی» را «فعالیت» معنادار در «بافت» دیجیتال می‌داند: نه «فرار» از واقعیت بلکه «بازی» با «معنا». فرستباخ (۱۹۵۷) در این چارچوب، «فرهنگ» را نه «محصول» «صنعت» بلکه «فعالیت» مخاطب تعریف کرد: «بازی»، «زبان» «نسل» دیجیتال است.  بر اساس نظریه انتخاب مواجهه، «سرگرمی» «صنعت» است اما «فرهنگ» «فعالیت» مخاطب است: «صنعت» «محتوا» تولید می‌کند و «مخاطب» «معنا» بازتولید می‌کند. فرستباخ (۱۹۵۷) در این چارچوب، «فرهنگ دیجیتال» را «فضا» «تولید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.', 'eedcbc02e9b3568a53d2d135faac5cf85f93c40a0fea05fc24a505c848d01cb9', 1003, 'ch-doc-card-710-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='eedcbc02e9b3568a53d2d135faac5cf85f93c40a0fea05fc24a505c848d01cb9', token_count=1003, vector_point_id='ch-doc-card-710-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-710-2', 'doc-card-710', 'sec-card-710-1', 2, 'ید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  نظریه انتخاب مواجهه را می‌توان پاسخی به شکاف میان «نقد» «صنعت فرهنگ» (فرانکفورت) و «مطالعات فرهنگی» (مقاومت مخاطب) دانست: «بازی» و «سرگرمی» هم «بازتولید» «ایدئولوژی» است و هم «مقاومت» مخاطب. فرستباخ (۱۹۵۷) در این چارچوب، «فرهنگ دیجیتال» را «میدان» «دیالکتیک» «صنعت» و «مخاطب» تعریف کرد.', '7f400c384da4f150c8e289381e577f793b909a15fa1222896034e7ae57eea2f9', 665, 'ch-doc-card-710-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7f400c384da4f150c8e289381e577f793b909a15fa1222896034e7ae57eea2f9', token_count=665, vector_point_id='ch-doc-card-710-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
