INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-712-1', 'doc-card-712', 'sec-card-712-1', 1, 'بازی، سرگرمی و فرهنگ دیجیتال  چارچوب اختلال بازی اینترنتی «بازی» را «فعالیت» معنادار در «بافت» دیجیتال می‌داند: نه «فرار» از واقعیت بلکه «بازی» با «معنا». WHO (۲۰۱۹) در این چارچوب، «فرهنگ» را نه «محصول» «صنعت» بلکه «فعالیت» مخاطب تعریف کرد: «بازی»، «زبان» «نسل» دیجیتال است.  بر اساس چارچوب اختلال بازی اینترنتی، «سرگرمی» «صنعت» است اما «فرهنگ» «فعالیت» مخاطب است: «صنعت» «محتوا» تولید می‌کند و «مخاطب» «معنا» بازتولید می‌کند. WHO (۲۰۱۹) در این چارچوب، «فرهنگ دیجیتال» را «فضا» «تولید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.', '2104d50e8c1a0edbcdd061e4415a300407d8dcf92ff927606ca887073930cd74', 1018, 'ch-doc-card-712-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2104d50e8c1a0edbcdd061e4415a300407d8dcf92ff927606ca887073930cd74', token_count=1018, vector_point_id='ch-doc-card-712-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-712-2', 'doc-card-712', 'sec-card-712-1', 2, 'ید مشترک» خواند: «مخاطب»، «تولیدکننده» است و «صنعت»، «بازتولید» «معنا» می‌کند.  چارچوب اختلال بازی اینترنتی را می‌توان پاسخی به شکاف میان «نقد» «صنعت فرهنگ» (فرانکفورت) و «مطالعات فرهنگی» (مقاومت مخاطب) دانست: «بازی» و «سرگرمی» هم «بازتولید» «ایدئولوژی» است و هم «مقاومت» مخاطب. WHO (۲۰۱۹) در این چارچوب، «فرهنگ دیجیتال» را «میدان» «دیالکتیک» «صنعت» و «مخاطب» تعریف کرد.', 'a5143baf2e78d0fe8100f19687ff54b4ab23c29df5adb6b8fd5a2eaa70bc7159', 672, 'ch-doc-card-712-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a5143baf2e78d0fe8100f19687ff54b4ab23c29df5adb6b8fd5a2eaa70bc7159', token_count=672, vector_point_id='ch-doc-card-712-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
