INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-714-1', 'doc-card-714', 'sec-card-714-1', 1, 'روش‌شناسی پژوهش ارتباطات  تحلیل چارچوب «روش» را «بافت» «معنا» می‌داند: نه «ابزار» «تحلیل» بلکه «بافت» «تحلیل». انتمن (۱۹۹۳) در این چارچوب، «روش» را «بافت» «معرفت» تعریف کرد: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش».  بر اساس تحلیل چارچوب، «روش» «دیالکتیک» «نظریه» و «داده» است: «نظریه»، «بافت» «تحلیل» است و «داده»، «بافت» «نظریه». انتمن (۱۹۹۳) در این چارچوب، «روش» را «بافت» «اعتماد» تعریف کرد: «اعتماد» در «روش» «ساخته» می‌شود، نه در «نتیجه».  تحلیل چارچوب را می‌توان پاسخی به شکاف میان «روش» «کمّی» (تعمیم) و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش».', '01475466ef1d413a401e9461e88032a994028af160adcc6fd3b754e45e6e2315', 1085, 'ch-doc-card-714-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='01475466ef1d413a401e9461e88032a994028af160adcc6fd3b754e45e6e2315', token_count=1085, vector_point_id='ch-doc-card-714-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-714-2', 'doc-card-714', 'sec-card-714-1', 2, 'و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش». انتمن (۱۹۹۳) در این چارچوب، «روش» را «بافت» «بازی» تعریف کرد: «تحلیل»، «بازی» با «داده» است.', '39fe859dd2fef4e763aeca18e4b0090875529fcf42d60cfe852a66ec7babdbec', 310, 'ch-doc-card-714-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='39fe859dd2fef4e763aeca18e4b0090875529fcf42d60cfe852a66ec7babdbec', token_count=310, vector_point_id='ch-doc-card-714-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-714-3', 'doc-card-714', 'sec-card-714-2', 3, '۱. بنیان و منطق نظری تحلیل چارچوب «روش» را «بافت» «معنا» می‌داند: نه «ابزار» «تحلیل» بلکه «بافت» «تحلیل». انتمن (۱۹۹۳) در این چارچوب، «روش» را «بافت» «معرفت» تعریف کرد: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش».  بر اساس تحلیل چارچوب، «روش» «دیالکتیک» «نظریه» و «داده» است: «نظریه»، «بافت» «تحلیل» است و «داده»، «بافت» «نظریه». انتمن (۱۹۹۳) در این چارچوب، «روش» را «بافت» «اعتماد» تعریف کرد: «اعتماد» در «روش» «ساخته» می‌شود، نه در «نتیجه».  تحلیل چارچوب را می‌توان پاسخی به شکاف میان «روش» «کمّی» (تعمیم) و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش».', '6dc40205fb9017edae7123287959c103c5673e946342298a71ccf17909a57503', 1076, 'ch-doc-card-714-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6dc40205fb9017edae7123287959c103c5673e946342298a71ccf17909a57503', token_count=1076, vector_point_id='ch-doc-card-714-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-714-4', 'doc-card-714', 'sec-card-714-2', 4, 'و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش». انتمن (۱۹۹۳) در این چارچوب، «روش» را «بافت» «بازی» تعریف کرد: «تحلیل»، «بازی» با «داده» است.  ۲. ساختارهای مفهومی • روش کمّی (Quantitative Method): «اندازه‌گیری» و «تعمیم»: «داده» «عددی» و «تحلیل» «آمار». • روش کیفی (Qualitative Method): «فهم» و «عمق»: «داده» «کیفی» و «تحلیل» «تفسیر». • روش ترکیبی (Mixed Methods): «ترکیب» «کمّی» و «کیفی»: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • پیمایش (Survey): «اندازه‌گیری» «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته». • تحلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن».', '24e05c62272c508fc7ad4409a13f70256b09a478b785a188ae6eed50fdcdcb27', 1150, 'ch-doc-card-714-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='24e05c62272c508fc7ad4409a13f70256b09a478b785a188ae6eed50fdcdcb27', token_count=1150, vector_point_id='ch-doc-card-714-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-714-5', 'doc-card-714', 'sec-card-714-2', 5, 'حلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن». • نظریه داده بنیادین (Grounded Theory): «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود. • قوم‌نگاری (Ethnography): «فهم» «بافت»: «حضور» در «بافت» و «فهم» «معنا» در «بافت». • ا', 'df0eda18b6d271c48939586569e3f04e2e612c4dede00f6c381c30f9e9b789b5', 481, 'ch-doc-card-714-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='df0eda18b6d271c48939586569e3f04e2e612c4dede00f6c381c30f9e9b789b5', token_count=481, vector_point_id='ch-doc-card-714-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-714-6', 'doc-card-714', 'sec-card-714-3', 6, '• روش کمّی (Quantitative Method): «اندازه‌گیری» و «تعمیم»: «داده» «عددی» و «تحلیل» «آمار». • روش کیفی (Qualitative Method): «فهم» و «عمق»: «داده» «کیفی» و «تحلیل» «تفسیر». • روش ترکیبی (Mixed Methods): «ترکیب» «کمّی» و «کیفی»: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • پیمایش (Survey): «اندازه‌گیری» «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته». • تحلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن». • نظریه داده بنیادین (Grounded Theory): «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود. • قوم‌نگاری (Ethnography): «فهم» «بافت»: «حضور» در «بافت» و «فهم» «معنا» در «بافت».', '29be7f3dc90ec8c011217980f9d3be38bd15c9d8be3b5f64ef849e45c5353b04', 1130, 'ch-doc-card-714-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='29be7f3dc90ec8c011217980f9d3be38bd15c9d8be3b5f64ef849e45c5353b04', token_count=1130, vector_point_id='ch-doc-card-714-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-714-7', 'doc-card-714', 'sec-card-714-3', 7, 'م‌نگاری (Ethnography): «فهم» «بافت»: «حضور» در «بافت» و «فهم» «معنا» در «بافت». • اعتبار و قابلیت اطمینان (Validity and Reliability): «اعتماد» در «روش»: «اعتبار» و «قابلیت اطمینان»، «بافت» «اعتماد» است.', 'e108afeb8569077c94032189fc753fc159d7debd04726a0fdfe0fe1f553fddc1', 367, 'ch-doc-card-714-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e108afeb8569077c94032189fc753fc159d7debd04726a0fdfe0fe1f553fddc1', token_count=367, vector_point_id='ch-doc-card-714-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-714-8', 'doc-card-714', 'sec-card-714-4', 8, 'عتبار و قابلیت اطمینان (Validity and Reliability): «اعتماد» در «روش»: «اعتبار» و «قابلیت اطمینان»، «بافت» «اعتماد» است.  ۳. نمونه‌های تحلیلی «روش کمّی» در عمل: «نظرسنجی» از «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته»: «تعمیم» «نتیجه» به «دسته».  «روش کیفی» در عمل: «مصاحبه» «عمیق» از «دسته‌ی» «کوچک»: «فهم» «معنا» در «بافت» «مصاحبه»: «عمق» «تحلیل».  «پیمایش» در عمل: «پیمایش» «نظر» «مخاطب» از «محتوای» «رسانه»: «سؤال» و «پاسخ» در «بافت» «دسته»: «تعمیم» «نتیجه».  «تحلیل محتوا» در عمل: «تحلیل» «متن» «خبر» از «چارچوب» و «واژه»: «کد» و «فراوانی» در «بافت» «متن»: «تحلیل» «ساختار» «متن».', '5c76962cf7ff828021033ae4043000f9f286ccfc2cea523af4e81dc777fd8a68', 1072, 'ch-doc-card-714-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5c76962cf7ff828021033ae4043000f9f286ccfc2cea523af4e81dc777fd8a68', token_count=1072, vector_point_id='ch-doc-card-714-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-714-9', 'doc-card-714', 'sec-card-714-4', 9, 'ز «چارچوب» و «واژه»: «کد» و «فراوانی» در «بافت» «متن»: «تحلیل» «ساختار» «متن».  «نظریه داده بنیادین» در عمل: «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود: «تحلیل»، «بازی» با «داده» است.  «قوم‌نگاری» در عمل: «حضور» در «بافت» «مخاطب»: «فهم» «معنا» در «بافت» «مخاطب»: «عمق» «تحلیل» در «بافت» «بومی».  ۴. نقدها و چالش‌ها ۱. «کمّی» و «کیفی» «دیالکتیک»‌اند: «کمّی» «تعمیم» دارد اما «عمق» ندارد و «کیفی» «عمق» دارد اما «تعمیم» ندارد: «روش» «ترکیبی»، «بافت» «دیالکتیک» است. ۲. «روش» و «نظریه» در هم تنیده‌اند: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش»: «روش» «خنثی» وجود ندارد. ۳.', '17842b057ad0f8425860f241c60fd05a93e47f100d43e207106133f550b126e1', 1076, 'ch-doc-card-714-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='17842b057ad0f8425860f241c60fd05a93e47f100d43e207106133f550b126e1', token_count=1076, vector_point_id='ch-doc-card-714-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
