INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-714-12', 'doc-card-714', 'sec-card-714-6', 12, '۱. «کمّی» و «کیفی» «دیالکتیک»‌اند: «کمّی» «تعمیم» دارد اما «عمق» ندارد و «کیفی» «عمق» دارد اما «تعمیم» ندارد: «روش» «ترکیبی»، «بافت» «دیالکتیک» است. ۲. «روش» و «نظریه» در هم تنیده‌اند: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش»: «روش» «خنثی» وجود ندارد. ۳. «اعتبار» در «روش» «کیفی» «سنجش‌پذیر» نیست: «اعتماد» در «بافت» «تحلیل» «ساخته» می‌شود و «اندازه‌گیری» آن «دشواری» است. ۴. «پیمایش» و «بافت»: «سؤال» در «پیمایش»، «بافت» «تحلیل» است: «سؤال» «بافت» «پاسخ» را «تعیین» می‌کند: «روش»، «بافت» «معنا» است. ۵. «تحلیل محتوا» و «ایدئولوژی»: «تحلیل» «متن» همیشه «ایدئولوژیک» است: «کد» و «فر', 'daddb583cd0633a2e558a3fe0d94268b91303a459fd83142997af0bb4d306082', 1072, 'ch-doc-card-714-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='daddb583cd0633a2e558a3fe0d94268b91303a459fd83142997af0bb4d306082', token_count=1072, vector_point_id='ch-doc-card-714-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-714-13', 'doc-card-714', 'sec-card-714-7', 13, 'اوانی»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «ایدئولوژی» می‌شود. ۶. «قوم‌نگاری» و «بافت»: «حضور» در «بافت»، «بافت» «تحلیل» را «بازتولید» می‌کند: «تحلیل‌گر»، «بافت» «تحلیل» است. ۷. «روش» در «عصر دیجیتال» «بازتعریف» می‌شود: «داده» «دیجیتال» (داده‌کاوی، تحلیل شبکه) «روش» تازه‌ای تولید می‌کند که «بافت» «تحلیل» را «بازتعریف» می‌کند. ۸. «نظریه داده بنیادین» و «بافت»: «نظریه» از «داده» «ساخته» می‌شود اما «بافت» «داده»، «نظریه» را «تعیین» می‌کند: «بافت»، «نظریه» است. ۹. «روش» و «اعتبار»: «اعتبار» در «روش» «ساخته» می‌شود: «اعتماد» به «روش»، «اعتماد» به «نتیجه» است: «روش»، «بافت» «اعتبار» است.', '1dfa81db7c8df8c9c1993f81fca908972365a222a9570aa9405bc4e6981b4ca4', 1072, 'ch-doc-card-714-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1dfa81db7c8df8c9c1993f81fca908972365a222a9570aa9405bc4e6981b4ca4', token_count=1072, vector_point_id='ch-doc-card-714-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
