INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-716-4', 'doc-card-716', 'sec-card-716-2', 4, 'و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش». مورلی (۱۹۸۰) در این چارچوب، «روش» را «بافت» «بازی» تعریف کرد: «تحلیل»، «بازی» با «داده» است.  ۲. ساختارهای مفهومی • روش کمّی (Quantitative Method): «اندازه‌گیری» و «تعمیم»: «داده» «عددی» و «تحلیل» «آمار». • روش کیفی (Qualitative Method): «فهم» و «عمق»: «داده» «کیفی» و «تحلیل» «تفسیر». • روش ترکیبی (Mixed Methods): «ترکیب» «کمّی» و «کیفی»: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • پیمایش (Survey): «اندازه‌گیری» «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته». • تحلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن».', 'aacc707b02b3464949ca4a7a5e03d942effcf07608603a8cf58a325043d380d0', 1150, 'ch-doc-card-716-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='aacc707b02b3464949ca4a7a5e03d942effcf07608603a8cf58a325043d380d0', token_count=1150, vector_point_id='ch-doc-card-716-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-716-5', 'doc-card-716', 'sec-card-716-2', 5, 'حلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن». • نظریه داده بنیادین (Grounded Theory): «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود. • قوم‌نگاری (Ethnography): «فهم» «بافت»: «حضور» در «بافت» و «فهم» «معنا» در «بافت».', '876970b6ee751a76c33eb7bf601a56bd54692cb7f216eb234fed7c8f48ac9075', 474, 'ch-doc-card-716-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='876970b6ee751a76c33eb7bf601a56bd54692cb7f216eb234fed7c8f48ac9075', token_count=474, vector_point_id='ch-doc-card-716-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
