INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-716-13', 'doc-card-716', 'sec-card-716-7', 13, 'اوانی»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «ایدئولوژی» می‌شود. ۶. «قوم‌نگاری» و «بافت»: «حضور» در «بافت»، «بافت» «تحلیل» را «بازتولید» می‌کند: «تحلیل‌گر»، «بافت» «تحلیل» است. ۷. «روش» در «عصر دیجیتال» «بازتعریف» می‌شود: «داده» «دیجیتال» (داده‌کاوی، تحلیل شبکه) «روش» تازه‌ای تولید می‌کند که «بافت» «تحلیل» را «بازتعریف» می‌کند. ۸. «نظریه داده بنیادین» و «بافت»: «نظریه» از «داده» «ساخته» می‌شود اما «بافت» «داده»، «نظریه» را «تعیین» می‌کند: «بافت»، «نظریه» است. ۹. «روش» و «اعتبار»: «اعتبار» در «روش» «ساخته» می‌شود: «اعتماد» به «روش»، «اعتماد» به «نتیجه» است: «روش»، «بافت» «اعتبار» است.', '1dfa81db7c8df8c9c1993f81fca908972365a222a9570aa9405bc4e6981b4ca4', 1072, 'ch-doc-card-716-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1dfa81db7c8df8c9c1993f81fca908972365a222a9570aa9405bc4e6981b4ca4', token_count=1072, vector_point_id='ch-doc-card-716-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
