INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-717-1', 'doc-card-717', 'sec-card-717-1', 1, 'روش‌شناسی پژوهش ارتباطات  قومنگاری رسانههای دیجیتال «روش» را «بافت» «معنا» می‌داند: نه «ابزار» «تحلیل» بلکه «بافت» «تحلیل». بوید در این چارچوب، «روش» را «بافت» «معرفت» تعریف کرد: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش».  بر اساس قومنگاری رسانههای دیجیتال، «روش» «دیالکتیک» «نظریه» و «داده» است: «نظریه»، «بافت» «تحلیل» است و «داده»، «بافت» «نظریه». بوید در این چارچوب، «روش» را «بافت» «اعتماد» تعریف کرد: «اعتماد» در «روش» «ساخته» می‌شود، نه در «نتیجه».  قومنگاری رسانههای دیجیتال را می‌توان پاسخی به شکاف میان «روش» «کمّی» (تعمیم) و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش».', '2c96b03d251f8ee42d763915a2ac22fe67381fbf1c83e8681d069abe7addecf1', 1127, 'ch-doc-card-717-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2c96b03d251f8ee42d763915a2ac22fe67381fbf1c83e8681d069abe7addecf1', token_count=1127, vector_point_id='ch-doc-card-717-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-717-2', 'doc-card-717', 'sec-card-717-1', 2, 'و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش». بوید در این چارچوب، «روش» را «بافت» «بازی» تعریف کرد: «تحلیل»، «بازی» با «داده» است.', '423caf57b8f424be72e51a30736855bd1e38aed1de8dd519ebf1607c85416c38', 296, 'ch-doc-card-717-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='423caf57b8f424be72e51a30736855bd1e38aed1de8dd519ebf1607c85416c38', token_count=296, vector_point_id='ch-doc-card-717-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-717-3', 'doc-card-717', 'sec-card-717-2', 3, '۱. بنیان و منطق نظری قومنگاری رسانههای دیجیتال «روش» را «بافت» «معنا» می‌داند: نه «ابزار» «تحلیل» بلکه «بافت» «تحلیل». بوید در این چارچوب، «روش» را «بافت» «معرفت» تعریف کرد: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش».  بر اساس قومنگاری رسانههای دیجیتال، «روش» «دیالکتیک» «نظریه» و «داده» است: «نظریه»، «بافت» «تحلیل» است و «داده»، «بافت» «نظریه». بوید در این چارچوب، «روش» را «بافت» «اعتماد» تعریف کرد: «اعتماد» در «روش» «ساخته» می‌شود، نه در «نتیجه».  قومنگاری رسانههای دیجیتال را می‌توان پاسخی به شکاف میان «روش» «کمّی» (تعمیم) و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش».', '00e9e4fad103197d6a06191d432ec1c6fb2b58a116b04b3e916e5dba058a8ebe', 1118, 'ch-doc-card-717-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='00e9e4fad103197d6a06191d432ec1c6fb2b58a116b04b3e916e5dba058a8ebe', token_count=1118, vector_point_id='ch-doc-card-717-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-717-4', 'doc-card-717', 'sec-card-717-2', 4, 'و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش». بوید در این چارچوب، «روش» را «بافت» «بازی» تعریف کرد: «تحلیل»، «بازی» با «داده» است.  ۲. ساختارهای مفهومی • روش کمّی (Quantitative Method): «اندازه‌گیری» و «تعمیم»: «داده» «عددی» و «تحلیل» «آمار». • روش کیفی (Qualitative Method): «فهم» و «عمق»: «داده» «کیفی» و «تحلیل» «تفسیر». • روش ترکیبی (Mixed Methods): «ترکیب» «کمّی» و «کیفی»: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • پیمایش (Survey): «اندازه‌گیری» «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته». • تحلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن».', 'aebe5312a61a3e54e09c043acfaa0e5d68db036fcc40dc616e9c60a7adc79ec8', 1136, 'ch-doc-card-717-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='aebe5312a61a3e54e09c043acfaa0e5d68db036fcc40dc616e9c60a7adc79ec8', token_count=1136, vector_point_id='ch-doc-card-717-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-717-5', 'doc-card-717', 'sec-card-717-2', 5, 'حلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن». • نظریه داده بنیادین (Grounded Theory): «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود. • قوم‌نگاری (Ethnography): «فهم» «بافت»: «حضور» در «بافت» و «فهم» «معنا» در «بافت»', 'a1eb56d00e1bca16556c21a5d8960663c2edc343ecc353dad0e367b86112d07c', 472, 'ch-doc-card-717-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a1eb56d00e1bca16556c21a5d8960663c2edc343ecc353dad0e367b86112d07c', token_count=472, vector_point_id='ch-doc-card-717-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
