INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-717-8', 'doc-card-717', 'sec-card-717-4', 8, '. • اعتبار و قابلیت اطمینان (Validity and Reliability): «اعتماد» در «روش»: «اعتبار» و «قابلیت اطمینان»، «بافت» «اعتماد» است.  ۳. نمونه‌های تحلیلی «روش کمّی» در عمل: «نظرسنجی» از «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته»: «تعمیم» «نتیجه» به «دسته».  «روش کیفی» در عمل: «مصاحبه» «عمیق» از «دسته‌ی» «کوچک»: «فهم» «معنا» در «بافت» «مصاحبه»: «عمق» «تحلیل».  «پیمایش» در عمل: «پیمایش» «نظر» «مخاطب» از «محتوای» «رسانه»: «سؤال» و «پاسخ» در «بافت» «دسته»: «تعمیم» «نتیجه».  «تحلیل محتوا» در عمل: «تحلیل» «متن» «خبر» از «چارچوب» و «واژه»: «کد» و «فراوانی» در «بافت» «متن»: «تحلیل» «ساختار» «متن».', 'ecef202d22ca03b294a237fc5bb569a5728ab640a636b6e4513aa2927eefe220', 1081, 'ch-doc-card-717-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ecef202d22ca03b294a237fc5bb569a5728ab640a636b6e4513aa2927eefe220', token_count=1081, vector_point_id='ch-doc-card-717-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
