INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-718-7', 'doc-card-718', 'sec-card-718-3', 7, 'م‌نگاری (Ethnography): «فهم» «بافت»: «حضور» در «بافت» و «فهم» «معنا» در «بافت». • اعتبار و قابلیت اطمینان (Validity and Reliability): «اعتماد» در «روش»: «اعتبار» و «قابلیت اطمینان»، «بافت» «اعتماد» است.', 'e108afeb8569077c94032189fc753fc159d7debd04726a0fdfe0fe1f553fddc1', 367, 'ch-doc-card-718-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e108afeb8569077c94032189fc753fc159d7debd04726a0fdfe0fe1f553fddc1', token_count=367, vector_point_id='ch-doc-card-718-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-718-8', 'doc-card-718', 'sec-card-718-4', 8, '«بافت». • اعتبار و قابلیت اطمینان (Validity and Reliability): «اعتماد» در «روش»: «اعتبار» و «قابلیت اطمینان»، «بافت» «اعتماد» است.  ۳. نمونه‌های تحلیلی «روش کمّی» در عمل: «نظرسنجی» از «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته»: «تعمیم» «نتیجه» به «دسته».  «روش کیفی» در عمل: «مصاحبه» «عمیق» از «دسته‌ی» «کوچک»: «فهم» «معنا» در «بافت» «مصاحبه»: «عمق» «تحلیل».  «پیمایش» در عمل: «پیمایش» «نظر» «مخاطب» از «محتوای» «رسانه»: «سؤال» و «پاسخ» در «بافت» «دسته»: «تعمیم» «نتیجه».  «تحلیل محتوا» در عمل: «تحلیل» «متن» «خبر» از «چارچوب» و «واژه»: «کد» و «فراوانی» در «بافت» «متن»: «تحلیل» «ساختار» «متن».', '2df1aea8fac438976f616adb8d3c65aa46c2c08593ddb674d06b54aacae15007', 1092, 'ch-doc-card-718-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2df1aea8fac438976f616adb8d3c65aa46c2c08593ddb674d06b54aacae15007', token_count=1092, vector_point_id='ch-doc-card-718-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-718-9', 'doc-card-718', 'sec-card-718-4', 9, 'ز «چارچوب» و «واژه»: «کد» و «فراوانی» در «بافت» «متن»: «تحلیل» «ساختار» «متن».  «نظریه داده بنیادین» در عمل: «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود: «تحلیل»، «بازی» با «داده» است.  «قوم‌نگاری» در عمل: «حضور» در «بافت» «مخاطب»: «فهم» «معنا» در «بافت» «مخاطب»: «عمق» «تحلیل» در «بافت» «بومی».  ۴. نقدها و چالش‌ها ۱. «کمّی» و «کیفی» «دیالکتیک»‌اند: «کمّی» «تعمیم» دارد اما «عمق» ندارد و «کیفی» «عمق» دارد اما «تعمیم» ندارد: «روش» «ترکیبی»، «بافت» «دیالکتیک» است. ۲. «روش» و «نظریه» در هم تنیده‌اند: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش»: «روش» «خنثی» وجود ندارد. ۳.', '17842b057ad0f8425860f241c60fd05a93e47f100d43e207106133f550b126e1', 1076, 'ch-doc-card-718-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='17842b057ad0f8425860f241c60fd05a93e47f100d43e207106133f550b126e1', token_count=1076, vector_point_id='ch-doc-card-718-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
