INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-718-12', 'doc-card-718', 'sec-card-718-6', 12, '۱. «کمّی» و «کیفی» «دیالکتیک»‌اند: «کمّی» «تعمیم» دارد اما «عمق» ندارد و «کیفی» «عمق» دارد اما «تعمیم» ندارد: «روش» «ترکیبی»، «بافت» «دیالکتیک» است. ۲. «روش» و «نظریه» در هم تنیده‌اند: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش»: «روش» «خنثی» وجود ندارد. ۳. «اعتبار» در «روش» «کیفی» «سنجش‌پذیر» نیست: «اعتماد» در «بافت» «تحلیل» «ساخته» می‌شود و «اندازه‌گیری» آن «دشواری» است. ۴. «پیمایش» و «بافت»: «سؤال» در «پیمایش»، «بافت» «تحلیل» است: «سؤال» «بافت» «پاسخ» را «تعیین» می‌کند: «روش»، «بافت» «معنا» است. ۵. «تحلیل محتوا» و «ایدئولوژی»: «تحلیل» «متن» همیشه «ایدئولوژیک» است: «کد» و «فر', 'daddb583cd0633a2e558a3fe0d94268b91303a459fd83142997af0bb4d306082', 1072, 'ch-doc-card-718-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='daddb583cd0633a2e558a3fe0d94268b91303a459fd83142997af0bb4d306082', token_count=1072, vector_point_id='ch-doc-card-718-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
