INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-719-4', 'doc-card-719', 'sec-card-719-2', 4, 'و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش». هاولند در این چارچوب، «روش» را «بافت» «بازی» تعریف کرد: «تحلیل»، «بازی» با «داده» است.  ۲. ساختارهای مفهومی • روش کمّی (Quantitative Method): «اندازه‌گیری» و «تعمیم»: «داده» «عددی» و «تحلیل» «آمار». • روش کیفی (Qualitative Method): «فهم» و «عمق»: «داده» «کیفی» و «تحلیل» «تفسیر». • روش ترکیبی (Mixed Methods): «ترکیب» «کمّی» و «کیفی»: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • پیمایش (Survey): «اندازه‌گیری» «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته». • تحلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن».', 'de243ea59e3f4a0f66ad03f9c99ee1f8a33835d704f04ffa8eaca29bb53f4074', 1140, 'ch-doc-card-719-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='de243ea59e3f4a0f66ad03f9c99ee1f8a33835d704f04ffa8eaca29bb53f4074', token_count=1140, vector_point_id='ch-doc-card-719-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
