INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-72-6', 'doc-card-72', 'sec-card-72-4', 6, 'نا» در «بافت». • اعتبار و قابلیت اطمینان (Validity and Reliability): «اعتماد» در «روش»: «اعتبار» و «قابلیت اطمینان»، «بافت» «اعتماد» است.  ۳. نمونه‌های تحلیلی «روش کمّی» در عمل: «نظرسنجی» از «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته»: «تعمیم» «نتیجه» به «دسته».  «روش کیفی» در عمل: «مصاحبه» «عمیق» از «دسته‌ی» «کوچک»: «فهم» «معنا» در «بافت» «مصاحبه»: «عمق» «تحلیل».  «پیمایش» در عمل: «پیمایش» «نظر» «مخاطب» از «محتوای» «رسانه»: «سؤال» و «پاسخ» در «بافت» «دسته»: «تعمیم» «نتیجه».  «تحلیل محتوا» در عمل: «تحلیل» «متن» «خبر» از «چارچوب» و «واژه»: «کد» و «فراوانی» در «بافت» «متن»: «تحلیل» «ساختار» «متن».', 'a6b6d256df36e1794ba16a81174e916f801ffbf46a6280c2a5aea3a69b7b3490', 1105, 'ch-doc-card-72-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a6b6d256df36e1794ba16a81174e916f801ffbf46a6280c2a5aea3a69b7b3490', token_count=1105, vector_point_id='ch-doc-card-72-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-72-7', 'doc-card-72', 'sec-card-72-4', 7, 'ز «چارچوب» و «واژه»: «کد» و «فراوانی» در «بافت» «متن»: «تحلیل» «ساختار» «متن».  «نظریه داده بنیادین» در عمل: «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود: «تحلیل»، «بازی» با «داده» است.  «قوم‌نگاری» در عمل: «حضور» در «بافت» «مخاطب»: «فهم» «معنا» در «بافت» «مخاطب»: «عمق» «تحلیل» در «بافت» «بومی».  ۴. نقدها و چالش‌ها ۱. «کمّی» و «کیفی» «دیالکتیک»‌اند: «کمّی» «تعمیم» دارد اما «عمق» ندارد و «کیفی» «عمق» دارد اما «تعمیم» ندارد: «روش» «ترکیبی»، «بافت» «دیالکتیک» است. ۲. «روش» و «نظریه» در هم تنیده‌اند: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش»: «روش» «خنثی» وجود ندارد. ۳.', '17842b057ad0f8425860f241c60fd05a93e47f100d43e207106133f550b126e1', 1076, 'ch-doc-card-72-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='17842b057ad0f8425860f241c60fd05a93e47f100d43e207106133f550b126e1', token_count=1076, vector_point_id='ch-doc-card-72-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-72-8', 'doc-card-72', 'sec-card-72-4', 8, '«روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش»: «روش» «خنثی» وجود ندارد. ۳. «اعتبار» در «روش» «کیفی» «سنجش‌پذیر» نیست: «اعتماد» در «بافت» «تحلیل» «ساخته» می‌شود و «اندازه‌گیری» آن «دشواری» است. ۴. «پیمایش» و «بافت»: «سؤال» در «پیمایش»، «بافت» «تحلیل» است: «سؤال» «بافت» «پاسخ» را «تعیین» می‌کند:', '280e67c4bbdb9012c36b674e708f8afa625998809e3cc47beeb1014dd38f5215', 541, 'ch-doc-card-72-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='280e67c4bbdb9012c36b674e708f8afa625998809e3cc47beeb1014dd38f5215', token_count=541, vector_point_id='ch-doc-card-72-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-72-9', 'doc-card-72', 'sec-card-72-5', 9, 'بررسی بازنمایی مهاجران در ۱۰۰۰ تیتر خبری سه شبکه تلویزیونی، با دو کدگذار مستقل و محاسبه آلفا برای سنجش توافق قبل از تحلیل نهایی.', 'c79cec5e5112a74bb25c812ccea70dc566aecf780b795cbf5d9f986fe7d94a15', 232, 'ch-doc-card-72-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c79cec5e5112a74bb25c812ccea70dc566aecf780b795cbf5d9f986fe7d94a15', token_count=232, vector_point_id='ch-doc-card-72-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-72-10', 'doc-card-72', 'sec-card-72-6', 10, 'تحلیل محتوای کمّی بیشتر به آنچه در متن صریح است توجه دارد و معنای ضمنی را دشوار می‌سنجد. همچنین انتخاب مقوله‌ها می‌تواند پیش‌داوری پژوهشگر را وارد کند.', '9216bf5a7c5a7e1b36dd7ec8353dec3679a28f55ec845c9fb233d3e6ca85f630', 274, 'ch-doc-card-72-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9216bf5a7c5a7e1b36dd7ec8353dec3679a28f55ec845c9fb233d3e6ca85f630', token_count=274, vector_point_id='ch-doc-card-72-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-72-11', 'doc-card-72', 'sec-card-72-10', 11, 'کتاب «روش پژوهش در ارتباطات» (بیر و همکاران، ۲۰۰۸)؛ کتاب «تحلیل محتوا» (هایرینگ، ۱۹۶۷)؛ کتاب «نظریه داده بنیادین» (گلایزر و استرأس، ۱۹۶۷)؛ کتاب «قوم‌نگاری و فرهنگ» (انول، ۱۹۸۴).', 'f40602f4e73937c5ab57d913729cc1b6482b7e5ff6a6c5988096f450bd7988a5', 321, 'ch-doc-card-72-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f40602f4e73937c5ab57d913729cc1b6482b7e5ff6a6c5988096f450bd7988a5', token_count=321, vector_point_id='ch-doc-card-72-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-720-0', 'doc-card-720', NULL, 0, 'کارکردگرایی ساختاری به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. پارسونز (۱۹۵۱) در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا …', '4c14b711bf9ad067f9f494bfff4fabbbd912b330bd8ab8adf0a77f6ca5363648', 503, 'ch-doc-card-720-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4c14b711bf9ad067f9f494bfff4fabbbd912b330bd8ab8adf0a77f6ca5363648', token_count=503, vector_point_id='ch-doc-card-720-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-720-1', 'doc-card-720', 'sec-card-720-1', 1, 'نظریه‌ها و پارادایم‌های کلان  کارکردگرایی ساختاری به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. پارسونز (۱۹۵۱) در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا ساخته و بازتولید می‌شود. این چارچوب در سطح کلان تحلیل، پرسش‌های بنیادین حوزه نظریه‌ها و پارادایم‌های کلان را شکل می‌دهد.  بر اساس کارکردگرایی ساختاری، درک رسانه بدون درک جایگاه آن در کلان‌نظام اجتماعی ممکن نیست. پارسونز (۱۹۵۱) نشان داد که هر رویکرد به رسانه — چه کارکردگرا، چه انتقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند.', 'a413c5a57635040bc86fef8723fbac01eb7573397eda48ceed984b2d7e352a4c', 1207, 'ch-doc-card-720-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a413c5a57635040bc86fef8723fbac01eb7573397eda48ceed984b2d7e352a4c', token_count=1207, vector_point_id='ch-doc-card-720-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-720-2', 'doc-card-720', 'sec-card-720-1', 2, 'تقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند. این چارچوب در سطح کلان، رسانه را در بستر قدرت، اقتصاد و فرهنگ می‌خواند.  کارکردگرایی ساختاری پارادایمی است که مرز میان «جامعه» و «رسانه» را کمرنگ می‌کند: رسانه هم بازتاب‌دهنده‌ی کلان‌نظام اجتماعی است و هم خودِ آن را می‌سازد. پارسونز (۱۹۵۱) در این چارچوب، پرسش «رسانه چه اثری دارد؟» را با پرسش «رسانه در این ساختار اجتماعی چه نقشی بازی می‌کند؟» جایگزین کرد و تحلیل را به سطح کلان برد.', '4495625ed03de6c2d6c9a9b06081204c68f698631230ba0e86d6de862c5e076e', 841, 'ch-doc-card-720-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4495625ed03de6c2d6c9a9b06081204c68f698631230ba0e86d6de862c5e076e', token_count=841, vector_point_id='ch-doc-card-720-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-720-3', 'doc-card-720', 'sec-card-720-2', 3, '۱. بنیان و منطق نظری کارکردگرایی ساختاری به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. پارسونز (۱۹۵۱) در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا ساخته و بازتولید می‌شود. این چارچوب در سطح کلان تحلیل، پرسش‌های بنیادین حوزه نظریه‌ها و پارادایم‌های کلان را شکل می‌دهد.  بر اساس کارکردگرایی ساختاری، درک رسانه بدون درک جایگاه آن در کلان‌نظام اجتماعی ممکن نیست. پارسونز (۱۹۵۱) نشان داد که هر رویکرد به رسانه — چه کارکردگرا، چه انتقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند.', 'e495a82d65d370c4f13b086733c342ef29f44b66d7151b39aec42bafa2d00ece', 1190, 'ch-doc-card-720-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e495a82d65d370c4f13b086733c342ef29f44b66d7151b39aec42bafa2d00ece', token_count=1190, vector_point_id='ch-doc-card-720-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-720-4', 'doc-card-720', 'sec-card-720-2', 4, 'تقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند. این چارچوب در سطح کلان، رسانه را در بستر قدرت، اقتصاد و فرهنگ می‌خواند.  کارکردگرایی ساختاری پارادایمی است که مرز میان «جامعه» و «رسانه» را کمرنگ می‌کند: رسانه هم بازتاب‌دهنده‌ی کلان‌نظام اجتماعی است و هم خودِ آن را می‌سازد. پارسونز (۱۹۵۱) در این چارچوب، پرسش «رسانه چه اثری دارد؟» را با پرسش «رسانه در این ساختار اجتماعی چه نقشی بازی می‌کند؟» جایگزین کرد و تحلیل را به سطح کلان برد.  ۲. ساختارهای مفهومی • پارادایم (Paradigm): مجموعه‌ی پیش‌فرض‌های مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند.', 'fca28d0890836b8bee2863938d453321f6b92e7fd98f8f5a8e4b28ff38961b4a', 1101, 'ch-doc-card-720-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fca28d0890836b8bee2863938d453321f6b92e7fd98f8f5a8e4b28ff38961b4a', token_count=1101, vector_point_id='ch-doc-card-720-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-720-5', 'doc-card-720', 'sec-card-720-2', 5, 'ی مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند. • ساختار کلان (Macro-Structure): نظام‌های بزرگ اجتماعی — اقتصاد، سیاست، طبقات — که رسانه در آن‌ها عمل می‌کند. • بازتولید (Reproduction): فرایند تداوم و تکرار نظم اجتماعی از طریق نهادها و بازنمایی‌ها. • ایدئولوژی (Ideology): نظام باورهای «عادی‌به‌نظر»یافته که موقعیت‌های قدرت را توجیه می‌کند. • بازنمایی کلان (Macro-Representation): نشان‌دادن روابط اجتماعی بزرگ (طبقه، جنسیت، قومیت) در متن‌های رسانه‌ای. • نقد اجتماعی (Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد. • تجربه‌', '8d18095c09790ea1764d931e2c5ad6a36a62d511ad3298782d7abd169246331e', 1063, 'ch-doc-card-720-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8d18095c09790ea1764d931e2c5ad6a36a62d511ad3298782d7abd169246331e', token_count=1063, vector_point_id='ch-doc-card-720-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-720-6', 'doc-card-720', 'sec-card-720-3', 6, '• پارادایم (Paradigm): مجموعه‌ی پیش‌فرض‌های مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند. • ساختار کلان (Macro-Structure): نظام‌های بزرگ اجتماعی — اقتصاد، سیاست، طبقات — که رسانه در آن‌ها عمل می‌کند. • بازتولید (Reproduction): فرایند تداوم و تکرار نظم اجتماعی از طریق نهادها و بازنمایی‌ها. • ایدئولوژی (Ideology): نظام باورهای «عادی‌به‌نظر»یافته که موقعیت‌های قدرت را توجیه می‌کند. • بازنمایی کلان (Macro-Representation): نشان‌دادن روابط اجتماعی بزرگ (طبقه، جنسیت، قومیت) در متن‌های رسانه‌ای. • نقد اجتماعی (Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد.', '2739813c609a72e6f71aa6513ad47c37b7804f2e5db12dbc7a75dffccc10f4f9', 1123, 'ch-doc-card-720-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2739813c609a72e6f71aa6513ad47c37b7804f2e5db12dbc7a75dffccc10f4f9', token_count=1123, vector_point_id='ch-doc-card-720-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-720-7', 'doc-card-720', 'sec-card-720-3', 7, '(Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد. • تجربه‌ی زیسته (Lived Experience): بستر پدیدارشناختی که در آن فرد رسانه را در زندگی روزمره معنادار می‌کند. • میان‌دستور (Inter-discourse): پیوند میان گفتمان‌های کلان که هویت و هنجار اجتماعی را می‌سازند.', '8ac74a955304bcba921b3db4b00741a2ac1fe3c1ae0f02fc06ea47b8b6cdd050', 514, 'ch-doc-card-720-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8ac74a955304bcba921b3db4b00741a2ac1fe3c1ae0f02fc06ea47b8b6cdd050', token_count=514, vector_point_id='ch-doc-card-720-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-720-8', 'doc-card-720', 'sec-card-720-4', 8, 'ی زیسته (Lived Experience): بستر پدیدارشناختی که در آن فرد رسانه را در زندگی روزمره معنادار می‌کند. • میان‌دستور (Inter-discourse): پیوند میان گفتمان‌های کلان که هویت و هنجار اجتماعی را می‌سازند.  ۳. نمونه‌های تحلیلی وقتی یک پژوهشگر با نگرش کارکردگرا به پوشش خبری انتخابات نگاه می‌کند، می‌پرسد «رسانه چگونه به پایداری نظام سیاسی کمک می‌کند؟» اما پژوهشگر تعارضی می‌پرسد «این پوشش، موقعیت کدام طبقه یا قوه را بازتولید می‌کند؟» — دو پارادایم، دو پرسش بنیادین از یک رویداد.  در تحلیل یک سریال تلویزنی، فمینیسم رسانه‌ای به بازنمایی زنان می‌نگرد، کوئیرتئوری به بازنمایی جنسیت‌های غیردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.', '1a1d593ed8a5c361a504b66512eca30125d8bcf53787d49f2103a6e389418e4d', 1189, 'ch-doc-card-720-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1a1d593ed8a5c361a504b66512eca30125d8bcf53787d49f2103a6e389418e4d', token_count=1189, vector_point_id='ch-doc-card-720-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-720-9', 'doc-card-720', 'sec-card-720-4', 9, 'ردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.  پوشش خبری یک اعتصاب کارگری می‌تواند از سه پارادایم خوانده شود: کارکردگرا آن را «پایان‌بخشی به اختلال» می‌خواند، تعارضی آن را «نبرد طبقاتی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.  وقتی رسانه‌ها از «فقر» به‌عنوان «کمبود فردی» در برابر «شکاف ساختاری» گزارش می‌دهند، در عمل یک انتخاب پارادایمی (فردی/کلان) در جریان است.  در تحلیل گفتمان مهاجرت، کوئیرتئوری و فمینیسم رسانه‌ای به حضور یا غیاب زنان و افراد غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.', 'f7e94bf9a49b0191f246e901ad8f2fa47fb1bcf18d748c9040edfda84e722e39', 1078, 'ch-doc-card-720-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f7e94bf9a49b0191f246e901ad8f2fa47fb1bcf18d748c9040edfda84e722e39', token_count=1078, vector_point_id='ch-doc-card-720-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-720-10', 'doc-card-720', 'sec-card-720-4', 10, 'غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.  نظریه‌ی فلسفه‌ی رسانه پرسش می‌کند که «خودِ» تکنولوژی (بصری/گوشی/الگوریتم) چگونه پیش‌فرض‌های ما از «واقعیت» را دگرگون می‌کند — پرسشی که فراتر از تحلیل محتوا، در سطح هستی‌شناختی قرار دارد.  ۴. نقدها و چالش‌ها ۱. سطح‌آلودگی: پارادایم‌های کلان گاه «بسیار بزرگ‌تر» از داده‌های رسانه‌ای هستند و خطر تقلیل تحلیل رسانه به یک پیش‌فرض فلسفی را دارند. ۲. ناتوانی در آزمون: ادعاهای هستی‌شناختی و معرفت‌شناختی پارادایم‌ها به‌ندرت به پیش‌بینی‌های قابل‌آزمون درباره‌ی رسانه تبدیل می‌شوند. ۳. مشکل معرفت‌شناختی: مرز میان «تحلیل با پا', '77d8a8ef009d30bf5f35392a2ad703cd55986dfaeddd228811a8d038b370e07a', 1083, 'ch-doc-card-720-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='77d8a8ef009d30bf5f35392a2ad703cd55986dfaeddd228811a8d038b370e07a', token_count=1083, vector_point_id='ch-doc-card-720-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-720-11', 'doc-card-720', 'sec-card-720-5', 11, 'وقتی یک پژوهشگر با نگرش کارکردگرا به پوشش خبری انتخابات نگاه می‌کند، می‌پرسد «رسانه چگونه به پایداری نظام سیاسی کمک می‌کند؟» اما پژوهشگر تعارضی می‌پرسد «این پوشش، موقعیت کدام طبقه یا قوه را بازتولید می‌کند؟» — دو پارادایم، دو پرسش بنیادین از یک رویداد.  در تحلیل یک سریال تلویزنی، فمینیسم رسانه‌ای به بازنمایی زنان می‌نگرد، کوئیرتئوری به بازنمایی جنسیت‌های غیردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.  پوشش خبری یک اعتصاب کارگری می‌تواند از سه پارادایم خوانده شود: کارکردگرا آن را «پایان‌بخشی به اختلال» می‌خواند، تعارضی آن را «نبرد طبقاتی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.', '3cca623c7b4db145a873737ee7ac459bf4fe07c5d42dc948595966eb0c0ab89c', 1185, 'ch-doc-card-720-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3cca623c7b4db145a873737ee7ac459bf4fe07c5d42dc948595966eb0c0ab89c', token_count=1185, vector_point_id='ch-doc-card-720-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-720-12', 'doc-card-720', 'sec-card-720-5', 12, 'تی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.  وقتی رسانه‌ها از «فقر» به‌عنوان «کمبود فردی» در برابر «شکاف ساختاری» گزارش می‌دهند، در عمل یک انتخاب پارادایمی (فردی/کلان) در جریان است.  در تحلیل گفتمان مهاجرت، کوئیرتئوری و فمینیسم رسانه‌ای به حضور یا غیاب زنان و افراد غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.  نظریه‌ی فلسفه‌ی رسانه پرسش می‌کند که «خودِ» تکنولوژی (بصری/گوشی/الگوریتم) چگونه پیش‌فرض‌های ما از «واقعیت» را دگرگون می‌کند — پرسشی که فراتر از تحلیل محتوا، در سطح هستی‌شناختی قرار دارد.', '3964a887a5f7f61d3707079756671ba972bed56a0753e9165c2cae980f3243e7', 1029, 'ch-doc-card-720-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3964a887a5f7f61d3707079756671ba972bed56a0753e9165c2cae980f3243e7', token_count=1029, vector_point_id='ch-doc-card-720-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-720-13', 'doc-card-720', 'sec-card-720-6', 13, '۱. سطح‌آلودگی: پارادایم‌های کلان گاه «بسیار بزرگ‌تر» از داده‌های رسانه‌ای هستند و خطر تقلیل تحلیل رسانه به یک پیش‌فرض فلسفی را دارند. ۲. ناتوانی در آزمون: ادعاهای هستی‌شناختی و معرفت‌شناختی پارادایم‌ها به‌ندرت به پیش‌بینی‌های قابل‌آزمون درباره‌ی رسانه تبدیل می‌شوند. ۳. مشکل معرفت‌شناختی: مرز میان «تحلیل با پارادایم» و «تحلیل از پیش‌فرض پارادایم» در عمل کمرنگ است و پژوهشگر اغلب پارادایم را انتخاب می‌کند، نه داده. ۴. تک‌پارادایمی‌شدن آموزش: در دوره‌های آموزشی، پارادایم‌ها به‌صورت بسته‌های بسته تدریس می‌شوند و دیالکتیک میان آن‌ها فراموش می‌شود. ۵. غرب‌مندی فلسفی: پارادایم‌های پساساختارگرایی، پدیدارشناسی و فمینیسمِ رسانه‌ای عمدتا در بافت‌های آکادمیک غربی شکل', '7f38efe2bb0ebacd2e44d05b3de77842ff65729ac3a6c5c3b9219e874ced915a', 1203, 'ch-doc-card-720-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7f38efe2bb0ebacd2e44d05b3de77842ff65729ac3a6c5c3b9219e874ced915a', token_count=1203, vector_point_id='ch-doc-card-720-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-720-14', 'doc-card-720', 'sec-card-720-7', 14, 'گرفته‌اند و کاربرد آن‌ها در بافت‌های دیگر نیازمند بومی‌سازی است. ۶. مسئله‌ی «عمل»: پارادایم‌های انتقادی در توصیف و نقد قوی‌اند، اما در «چه باید کرد؟» اغلب صامت می‌مانند. ۷. واژه‌آلودگی: استفاده‌ی زیاد از واژگان پارادایمی (بازتولید، ایدئولوژی، گفتمان) بدون تعریف روشن، تحلیل را مبهم می‌کند. ۸. خطر دوگانه‌سازی: پارادایم‌ها اغلب جهان را به دو دسته تقسیم می‌کنند (نظم/تعارض، ساختار/عاملیت) و پیچیدگی‌های میانی را نادیده می‌گیرند. ۹. نوسازی کند: دگرگونی‌های رسانه‌ای (پلتفرم، الگوریتم) سریع‌تر از بازسازی مفهومی پارادایم‌ها رخ می‌دهند. ۱۰. سیاست‌زدگی روش: در بسیاری از بافت‌ها، انتخاب یک پارادایم انتقادی، خود یک موضع سیاسی است و این «پیش‌مقوله» باید شفاف اعلام شود.', '16c91d6de9a957b0e729d93b5680fc395b3a50319da43e261dd217503feedee5', 1203, 'ch-doc-card-720-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='16c91d6de9a957b0e729d93b5680fc395b3a50319da43e261dd217503feedee5', token_count=1203, vector_point_id='ch-doc-card-720-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-720-15', 'doc-card-720', 'sec-card-720-10', 15, 'کتاب «نظریه‌های ارتباطات جمعی» (دنیس مک‌کوایل، ۱۹۸۳)؛ کتاب «فلسفه‌ی رسانه» (فیلیپ مک‌چر، ۲۰۰۵)؛ کتاب «ساختارهای عمیق فرهنگ و ذهن» (کلیر کلاسل، ۱۹۶۳)؛ استناد مبنا: McQuail (1983) بر طبقه‌بندی پارادایم‌ها.', '5e54f2a3bf785e5acae536d3523485d9a2dc63a2b3cd9f6eed85ebd882893d57', 369, 'ch-doc-card-720-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5e54f2a3bf785e5acae536d3523485d9a2dc63a2b3cd9f6eed85ebd882893d57', token_count=369, vector_point_id='ch-doc-card-720-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-721-0', 'doc-card-721', NULL, 0, 'نظریه تعارض به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. مارکس در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا ساخته و بازتولید …', 'abaa5020b142627f221a5d3e662c4392f409331b21467e3c63dc8584621cc547', 503, 'ch-doc-card-721-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='abaa5020b142627f221a5d3e662c4392f409331b21467e3c63dc8584621cc547', token_count=503, vector_point_id='ch-doc-card-721-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-721-1', 'doc-card-721', 'sec-card-721-1', 1, 'نظریه‌ها و پارادایم‌های کلان  نظریه تعارض به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. مارکس در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا ساخته و بازتولید می‌شود. این چارچوب در سطح کلان تحلیل، پرسش‌های بنیادین حوزه نظریه‌ها و پارادایم‌های کلان را شکل می‌دهد.  بر اساس نظریه تعارض، درک رسانه بدون درک جایگاه آن در کلان‌نظام اجتماعی ممکن نیست. مارکس نشان داد که هر رویکرد به رسانه — چه کارکردگرا، چه انتقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند.', 'df0cc403ecb101ea94e05533d4d5e0c12c1b45f14fb09ad66e891aa9a8e4588e', 1145, 'ch-doc-card-721-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='df0cc403ecb101ea94e05533d4d5e0c12c1b45f14fb09ad66e891aa9a8e4588e', token_count=1145, vector_point_id='ch-doc-card-721-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-721-2', 'doc-card-721', 'sec-card-721-1', 2, 'تقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند. این چارچوب در سطح کلان، رسانه را در بستر قدرت، اقتصاد و فرهنگ می‌خواند.  نظریه تعارض پارادایمی است که مرز میان «جامعه» و «رسانه» را کمرنگ می‌کند: رسانه هم بازتاب‌دهنده‌ی کلان‌نظام اجتماعی است و هم خودِ آن را می‌سازد. مارکس در این چارچوب، پرسش «رسانه چه اثری دارد؟» را با پرسش «رسانه در این ساختار اجتماعی چه نقشی بازی می‌کند؟» جایگزین کرد و تحلیل را به سطح کلان برد.', 'e9145eeed707b26e27729f12c79ae614e8cf1892aefbfd57c2ed53855ea8e72b', 810, 'ch-doc-card-721-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e9145eeed707b26e27729f12c79ae614e8cf1892aefbfd57c2ed53855ea8e72b', token_count=810, vector_point_id='ch-doc-card-721-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-721-3', 'doc-card-721', 'sec-card-721-2', 3, '۱. بنیان و منطق نظری نظریه تعارض به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. مارکس در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا ساخته و بازتولید می‌شود. این چارچوب در سطح کلان تحلیل، پرسش‌های بنیادین حوزه نظریه‌ها و پارادایم‌های کلان را شکل می‌دهد.  بر اساس نظریه تعارض، درک رسانه بدون درک جایگاه آن در کلان‌نظام اجتماعی ممکن نیست. مارکس نشان داد که هر رویکرد به رسانه — چه کارکردگرا، چه انتقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند.', '7e6c129f146118de054b3bcc3758abefa11836a9e4d49a6f0878a3451e714809', 1129, 'ch-doc-card-721-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7e6c129f146118de054b3bcc3758abefa11836a9e4d49a6f0878a3451e714809', token_count=1129, vector_point_id='ch-doc-card-721-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-721-4', 'doc-card-721', 'sec-card-721-2', 4, 'تقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند. این چارچوب در سطح کلان، رسانه را در بستر قدرت، اقتصاد و فرهنگ می‌خواند.  نظریه تعارض پارادایمی است که مرز میان «جامعه» و «رسانه» را کمرنگ می‌کند: رسانه هم بازتاب‌دهنده‌ی کلان‌نظام اجتماعی است و هم خودِ آن را می‌سازد. مارکس در این چارچوب، پرسش «رسانه چه اثری دارد؟» را با پرسش «رسانه در این ساختار اجتماعی چه نقشی بازی می‌کند؟» جایگزین کرد و تحلیل را به سطح کلان برد.  ۲. ساختارهای مفهومی • پارادایم (Paradigm): مجموعه‌ی پیش‌فرض‌های مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند.', 'c320de6a97a682c592e89416c54ffc6fce91741facfbf2c3677469f86548f126', 1070, 'ch-doc-card-721-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c320de6a97a682c592e89416c54ffc6fce91741facfbf2c3677469f86548f126', token_count=1070, vector_point_id='ch-doc-card-721-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-721-5', 'doc-card-721', 'sec-card-721-2', 5, 'ی مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند. • ساختار کلان (Macro-Structure): نظام‌های بزرگ اجتماعی — اقتصاد، سیاست، طبقات — که رسانه در آن‌ها عمل می‌کند. • بازتولید (Reproduction): فرایند تداوم و تکرار نظم اجتماعی از طریق نهادها و بازنمایی‌ها. • ایدئولوژی (Ideology): نظام باورهای «عادی‌به‌نظر»یافته که موقعیت‌های قدرت را توجیه می‌کند. • بازنمایی کلان (Macro-Representation): نشان‌دادن روابط اجتماعی بزرگ (طبقه، جنسیت، قومیت) در متن‌های رسانه‌ای. • نقد اجتماعی (Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد. • تجربه‌ی زیسته (Lived Experience): بست', '48543eb2865085b67e01414ed561ea289231577d7f8252ed5099cac32fe20710', 1120, 'ch-doc-card-721-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='48543eb2865085b67e01414ed561ea289231577d7f8252ed5099cac32fe20710', token_count=1120, vector_point_id='ch-doc-card-721-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-721-6', 'doc-card-721', 'sec-card-721-3', 6, '• پارادایم (Paradigm): مجموعه‌ی پیش‌فرض‌های مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند. • ساختار کلان (Macro-Structure): نظام‌های بزرگ اجتماعی — اقتصاد، سیاست، طبقات — که رسانه در آن‌ها عمل می‌کند. • بازتولید (Reproduction): فرایند تداوم و تکرار نظم اجتماعی از طریق نهادها و بازنمایی‌ها. • ایدئولوژی (Ideology): نظام باورهای «عادی‌به‌نظر»یافته که موقعیت‌های قدرت را توجیه می‌کند. • بازنمایی کلان (Macro-Representation): نشان‌دادن روابط اجتماعی بزرگ (طبقه، جنسیت، قومیت) در متن‌های رسانه‌ای. • نقد اجتماعی (Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد.', '2739813c609a72e6f71aa6513ad47c37b7804f2e5db12dbc7a75dffccc10f4f9', 1123, 'ch-doc-card-721-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2739813c609a72e6f71aa6513ad47c37b7804f2e5db12dbc7a75dffccc10f4f9', token_count=1123, vector_point_id='ch-doc-card-721-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-721-7', 'doc-card-721', 'sec-card-721-3', 7, '(Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد. • تجربه‌ی زیسته (Lived Experience): بستر پدیدارشناختی که در آن فرد رسانه را در زندگی روزمره معنادار می‌کند. • میان‌دستور (Inter-discourse): پیوند میان گفتمان‌های کلان که هویت و هنجار اجتماعی را می‌سازند.', '8ac74a955304bcba921b3db4b00741a2ac1fe3c1ae0f02fc06ea47b8b6cdd050', 514, 'ch-doc-card-721-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8ac74a955304bcba921b3db4b00741a2ac1fe3c1ae0f02fc06ea47b8b6cdd050', token_count=514, vector_point_id='ch-doc-card-721-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-721-8', 'doc-card-721', 'sec-card-721-4', 8, 'ر پدیدارشناختی که در آن فرد رسانه را در زندگی روزمره معنادار می‌کند. • میان‌دستور (Inter-discourse): پیوند میان گفتمان‌های کلان که هویت و هنجار اجتماعی را می‌سازند.  ۳. نمونه‌های تحلیلی وقتی یک پژوهشگر با نگرش کارکردگرا به پوشش خبری انتخابات نگاه می‌کند، می‌پرسد «رسانه چگونه به پایداری نظام سیاسی کمک می‌کند؟» اما پژوهشگر تعارضی می‌پرسد «این پوشش، موقعیت کدام طبقه یا قوه را بازتولید می‌کند؟» — دو پارادایم، دو پرسش بنیادین از یک رویداد.  در تحلیل یک سریال تلویزنی، فمینیسم رسانه‌ای به بازنمایی زنان می‌نگرد، کوئیرتئوری به بازنمایی جنسیت‌های غیردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.', '65e49d1d17e58952a3ed5e764baac0da492980d82f3d5a9529116fdd16b2eb2b', 1132, 'ch-doc-card-721-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='65e49d1d17e58952a3ed5e764baac0da492980d82f3d5a9529116fdd16b2eb2b', token_count=1132, vector_point_id='ch-doc-card-721-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-721-9', 'doc-card-721', 'sec-card-721-4', 9, 'ردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.  پوشش خبری یک اعتصاب کارگری می‌تواند از سه پارادایم خوانده شود: کارکردگرا آن را «پایان‌بخشی به اختلال» می‌خواند، تعارضی آن را «نبرد طبقاتی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.  وقتی رسانه‌ها از «فقر» به‌عنوان «کمبود فردی» در برابر «شکاف ساختاری» گزارش می‌دهند، در عمل یک انتخاب پارادایمی (فردی/کلان) در جریان است.  در تحلیل گفتمان مهاجرت، کوئیرتئوری و فمینیسم رسانه‌ای به حضور یا غیاب زنان و افراد غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.', 'f7e94bf9a49b0191f246e901ad8f2fa47fb1bcf18d748c9040edfda84e722e39', 1078, 'ch-doc-card-721-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f7e94bf9a49b0191f246e901ad8f2fa47fb1bcf18d748c9040edfda84e722e39', token_count=1078, vector_point_id='ch-doc-card-721-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-721-10', 'doc-card-721', 'sec-card-721-4', 10, 'غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.  نظریه‌ی فلسفه‌ی رسانه پرسش می‌کند که «خودِ» تکنولوژی (بصری/گوشی/الگوریتم) چگونه پیش‌فرض‌های ما از «واقعیت» را دگرگون می‌کند — پرسشی که فراتر از تحلیل محتوا، در سطح هستی‌شناختی قرار دارد.  ۴. نقدها و چالش‌ها ۱. سطح‌آلودگی: پارادایم‌های کلان گاه «بسیار بزرگ‌تر» از داده‌های رسانه‌ای هستند و خطر تقلیل تحلیل رسانه به یک پیش‌فرض فلسفی را دارند. ۲. ناتوانی در آزمون: ادعاهای هستی‌شناختی و معرفت‌شناختی پارادایم‌ها به‌ندرت به پیش‌بینی‌های قابل‌آزمون درباره‌ی رسانه تبدیل می‌شوند. ۳. مشکل معرفت‌شناختی: مرز میان «تحلیل با پارادایم» و «ت', 'b669f7d57f6e2f0c1bf24d75342091bccfac10425718701e266ef3d9cc64db70', 1105, 'ch-doc-card-721-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b669f7d57f6e2f0c1bf24d75342091bccfac10425718701e266ef3d9cc64db70', token_count=1105, vector_point_id='ch-doc-card-721-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-721-11', 'doc-card-721', 'sec-card-721-5', 11, 'وقتی یک پژوهشگر با نگرش کارکردگرا به پوشش خبری انتخابات نگاه می‌کند، می‌پرسد «رسانه چگونه به پایداری نظام سیاسی کمک می‌کند؟» اما پژوهشگر تعارضی می‌پرسد «این پوشش، موقعیت کدام طبقه یا قوه را بازتولید می‌کند؟» — دو پارادایم، دو پرسش بنیادین از یک رویداد.  در تحلیل یک سریال تلویزنی، فمینیسم رسانه‌ای به بازنمایی زنان می‌نگرد، کوئیرتئوری به بازنمایی جنسیت‌های غیردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.  پوشش خبری یک اعتصاب کارگری می‌تواند از سه پارادایم خوانده شود: کارکردگرا آن را «پایان‌بخشی به اختلال» می‌خواند، تعارضی آن را «نبرد طبقاتی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.', '3cca623c7b4db145a873737ee7ac459bf4fe07c5d42dc948595966eb0c0ab89c', 1185, 'ch-doc-card-721-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3cca623c7b4db145a873737ee7ac459bf4fe07c5d42dc948595966eb0c0ab89c', token_count=1185, vector_point_id='ch-doc-card-721-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-721-12', 'doc-card-721', 'sec-card-721-5', 12, 'تی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.  وقتی رسانه‌ها از «فقر» به‌عنوان «کمبود فردی» در برابر «شکاف ساختاری» گزارش می‌دهند، در عمل یک انتخاب پارادایمی (فردی/کلان) در جریان است.  در تحلیل گفتمان مهاجرت، کوئیرتئوری و فمینیسم رسانه‌ای به حضور یا غیاب زنان و افراد غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.  نظریه‌ی فلسفه‌ی رسانه پرسش می‌کند که «خودِ» تکنولوژی (بصری/گوشی/الگوریتم) چگونه پیش‌فرض‌های ما از «واقعیت» را دگرگون می‌کند — پرسشی که فراتر از تحلیل محتوا، در سطح هستی‌شناختی قرار دارد.', '3964a887a5f7f61d3707079756671ba972bed56a0753e9165c2cae980f3243e7', 1029, 'ch-doc-card-721-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3964a887a5f7f61d3707079756671ba972bed56a0753e9165c2cae980f3243e7', token_count=1029, vector_point_id='ch-doc-card-721-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-721-13', 'doc-card-721', 'sec-card-721-6', 13, '۱. سطح‌آلودگی: پارادایم‌های کلان گاه «بسیار بزرگ‌تر» از داده‌های رسانه‌ای هستند و خطر تقلیل تحلیل رسانه به یک پیش‌فرض فلسفی را دارند. ۲. ناتوانی در آزمون: ادعاهای هستی‌شناختی و معرفت‌شناختی پارادایم‌ها به‌ندرت به پیش‌بینی‌های قابل‌آزمون درباره‌ی رسانه تبدیل می‌شوند. ۳. مشکل معرفت‌شناختی: مرز میان «تحلیل با پارادایم» و «تحلیل از پیش‌فرض پارادایم» در عمل کمرنگ است و پژوهشگر اغلب پارادایم را انتخاب می‌کند، نه داده. ۴. تک‌پارادایمی‌شدن آموزش: در دوره‌های آموزشی، پارادایم‌ها به‌صورت بسته‌های بسته تدریس می‌شوند و دیالکتیک میان آن‌ها فراموش می‌شود. ۵. غرب‌مندی فلسفی: پارادایم‌های پساساختارگرایی، پدیدارشناسی و فمینیسمِ رسانه‌ای عمدتا در بافت‌های آکادمیک غربی شکل', '7f38efe2bb0ebacd2e44d05b3de77842ff65729ac3a6c5c3b9219e874ced915a', 1203, 'ch-doc-card-721-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7f38efe2bb0ebacd2e44d05b3de77842ff65729ac3a6c5c3b9219e874ced915a', token_count=1203, vector_point_id='ch-doc-card-721-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-721-14', 'doc-card-721', 'sec-card-721-7', 14, 'گرفته‌اند و کاربرد آن‌ها در بافت‌های دیگر نیازمند بومی‌سازی است. ۶. مسئله‌ی «عمل»: پارادایم‌های انتقادی در توصیف و نقد قوی‌اند، اما در «چه باید کرد؟» اغلب صامت می‌مانند. ۷. واژه‌آلودگی: استفاده‌ی زیاد از واژگان پارادایمی (بازتولید، ایدئولوژی، گفتمان) بدون تعریف روشن، تحلیل را مبهم می‌کند. ۸. خطر دوگانه‌سازی: پارادایم‌ها اغلب جهان را به دو دسته تقسیم می‌کنند (نظم/تعارض، ساختار/عاملیت) و پیچیدگی‌های میانی را نادیده می‌گیرند. ۹. نوسازی کند: دگرگونی‌های رسانه‌ای (پلتفرم، الگوریتم) سریع‌تر از بازسازی مفهومی پارادایم‌ها رخ می‌دهند. ۱۰. سیاست‌زدگی روش: در بسیاری از بافت‌ها، انتخاب یک پارادایم انتقادی، خود یک موضع سیاسی است و این «پیش‌مقوله» باید شفاف اعلام شود.', '16c91d6de9a957b0e729d93b5680fc395b3a50319da43e261dd217503feedee5', 1203, 'ch-doc-card-721-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='16c91d6de9a957b0e729d93b5680fc395b3a50319da43e261dd217503feedee5', token_count=1203, vector_point_id='ch-doc-card-721-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-721-15', 'doc-card-721', 'sec-card-721-10', 15, 'کتاب «نظریه‌های ارتباطات جمعی» (دنیس مک‌کوایل، ۱۹۸۳)؛ کتاب «فلسفه‌ی رسانه» (فیلیپ مک‌چر، ۲۰۰۵)؛ کتاب «ساختارهای عمیق فرهنگ و ذهن» (کلیر کلاسل، ۱۹۶۳)؛ استناد مبنا: McQuail (1983) بر طبقه‌بندی پارادایم‌ها.', '5e54f2a3bf785e5acae536d3523485d9a2dc63a2b3cd9f6eed85ebd882893d57', 369, 'ch-doc-card-721-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5e54f2a3bf785e5acae536d3523485d9a2dc63a2b3cd9f6eed85ebd882893d57', token_count=369, vector_point_id='ch-doc-card-721-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-722-0', 'doc-card-722', NULL, 0, 'پدیدارشناسی به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. شوتز (۱۹۶۷) در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا ساخته و …', '139355b11cab8a14382666c0601afe32be8437816f587fc2dccdf3ff64b6508f', 498, 'ch-doc-card-722-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='139355b11cab8a14382666c0601afe32be8437816f587fc2dccdf3ff64b6508f', token_count=498, vector_point_id='ch-doc-card-722-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-722-1', 'doc-card-722', 'sec-card-722-1', 1, 'نظریه‌ها و پارادایم‌های کلان  پدیدارشناسی به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. شوتز (۱۹۶۷) در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا ساخته و بازتولید می‌شود. این چارچوب در سطح کلان تحلیل، پرسش‌های بنیادین حوزه نظریه‌ها و پارادایم‌های کلان را شکل می‌دهد.  بر اساس پدیدارشناسی، درک رسانه بدون درک جایگاه آن در کلان‌نظام اجتماعی ممکن نیست. شوتز (۱۹۶۷) نشان داد که هر رویکرد به رسانه — چه کارکردگرا، چه انتقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند.', 'addb75f7a25b98a51a98c3c0ffdf4d4b6ed82cfddc5b035678b23e65b842dc20', 1167, 'ch-doc-card-722-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='addb75f7a25b98a51a98c3c0ffdf4d4b6ed82cfddc5b035678b23e65b842dc20', token_count=1167, vector_point_id='ch-doc-card-722-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-722-2', 'doc-card-722', 'sec-card-722-1', 2, 'تقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند. این چارچوب در سطح کلان، رسانه را در بستر قدرت، اقتصاد و فرهنگ می‌خواند.  پدیدارشناسی پارادایمی است که مرز میان «جامعه» و «رسانه» را کمرنگ می‌کند: رسانه هم بازتاب‌دهنده‌ی کلان‌نظام اجتماعی است و هم خودِ آن را می‌سازد. شوتز (۱۹۶۷) در این چارچوب، پرسش «رسانه چه اثری دارد؟» را با پرسش «رسانه در این ساختار اجتماعی چه نقشی بازی می‌کند؟» جایگزین کرد و تحلیل را به سطح کلان برد.', '6c85ca5b01a353825407b0e6368918d3ca4cde654433032c04fa7a2d62c247c5', 821, 'ch-doc-card-722-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6c85ca5b01a353825407b0e6368918d3ca4cde654433032c04fa7a2d62c247c5', token_count=821, vector_point_id='ch-doc-card-722-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-722-3', 'doc-card-722', 'sec-card-722-2', 3, '۱. بنیان و منطق نظری پدیدارشناسی به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. شوتز (۱۹۶۷) در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا ساخته و بازتولید می‌شود. این چارچوب در سطح کلان تحلیل، پرسش‌های بنیادین حوزه نظریه‌ها و پارادایم‌های کلان را شکل می‌دهد.  بر اساس پدیدارشناسی، درک رسانه بدون درک جایگاه آن در کلان‌نظام اجتماعی ممکن نیست. شوتز (۱۹۶۷) نشان داد که هر رویکرد به رسانه — چه کارکردگرا، چه انتقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند.', '04c7db8135af4a9f0dd392397116f8f3887fa882e841f59598e51d996d80b2a1', 1150, 'ch-doc-card-722-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='04c7db8135af4a9f0dd392397116f8f3887fa882e841f59598e51d996d80b2a1', token_count=1150, vector_point_id='ch-doc-card-722-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-722-4', 'doc-card-722', 'sec-card-722-2', 4, 'تقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند. این چارچوب در سطح کلان، رسانه را در بستر قدرت، اقتصاد و فرهنگ می‌خواند.  پدیدارشناسی پارادایمی است که مرز میان «جامعه» و «رسانه» را کمرنگ می‌کند: رسانه هم بازتاب‌دهنده‌ی کلان‌نظام اجتماعی است و هم خودِ آن را می‌سازد. شوتز (۱۹۶۷) در این چارچوب، پرسش «رسانه چه اثری دارد؟» را با پرسش «رسانه در این ساختار اجتماعی چه نقشی بازی می‌کند؟» جایگزین کرد و تحلیل را به سطح کلان برد.  ۲. ساختارهای مفهومی • پارادایم (Paradigm): مجموعه‌ی پیش‌فرض‌های مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند.', '9d672c3865a9a89678c907091c3d086c22a86ab88f03c435033f60316cd86fe7', 1081, 'ch-doc-card-722-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9d672c3865a9a89678c907091c3d086c22a86ab88f03c435033f60316cd86fe7', token_count=1081, vector_point_id='ch-doc-card-722-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-722-5', 'doc-card-722', 'sec-card-722-2', 5, 'ی مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند. • ساختار کلان (Macro-Structure): نظام‌های بزرگ اجتماعی — اقتصاد، سیاست، طبقات — که رسانه در آن‌ها عمل می‌کند. • بازتولید (Reproduction): فرایند تداوم و تکرار نظم اجتماعی از طریق نهادها و بازنمایی‌ها. • ایدئولوژی (Ideology): نظام باورهای «عادی‌به‌نظر»یافته که موقعیت‌های قدرت را توجیه می‌کند. • بازنمایی کلان (Macro-Representation): نشان‌دادن روابط اجتماعی بزرگ (طبقه، جنسیت، قومیت) در متن‌های رسانه‌ای. • نقد اجتماعی (Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد. • تجربه‌ی زیسته (Lived Expe', '9614a8abb2575d584358c8ba6ddcce71deceb824e0c4227ecd64b91c211c8d8e', 1098, 'ch-doc-card-722-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9614a8abb2575d584358c8ba6ddcce71deceb824e0c4227ecd64b91c211c8d8e', token_count=1098, vector_point_id='ch-doc-card-722-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-722-6', 'doc-card-722', 'sec-card-722-3', 6, '• پارادایم (Paradigm): مجموعه‌ی پیش‌فرض‌های مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند. • ساختار کلان (Macro-Structure): نظام‌های بزرگ اجتماعی — اقتصاد، سیاست، طبقات — که رسانه در آن‌ها عمل می‌کند. • بازتولید (Reproduction): فرایند تداوم و تکرار نظم اجتماعی از طریق نهادها و بازنمایی‌ها. • ایدئولوژی (Ideology): نظام باورهای «عادی‌به‌نظر»یافته که موقعیت‌های قدرت را توجیه می‌کند. • بازنمایی کلان (Macro-Representation): نشان‌دادن روابط اجتماعی بزرگ (طبقه، جنسیت، قومیت) در متن‌های رسانه‌ای. • نقد اجتماعی (Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد.', '2739813c609a72e6f71aa6513ad47c37b7804f2e5db12dbc7a75dffccc10f4f9', 1123, 'ch-doc-card-722-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2739813c609a72e6f71aa6513ad47c37b7804f2e5db12dbc7a75dffccc10f4f9', token_count=1123, vector_point_id='ch-doc-card-722-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-722-7', 'doc-card-722', 'sec-card-722-3', 7, '(Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد. • تجربه‌ی زیسته (Lived Experience): بستر پدیدارشناختی که در آن فرد رسانه را در زندگی روزمره معنادار می‌کند. • میان‌دستور (Inter-discourse): پیوند میان گفتمان‌های کلان که هویت و هنجار اجتماعی را می‌سازند.', '8ac74a955304bcba921b3db4b00741a2ac1fe3c1ae0f02fc06ea47b8b6cdd050', 514, 'ch-doc-card-722-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8ac74a955304bcba921b3db4b00741a2ac1fe3c1ae0f02fc06ea47b8b6cdd050', token_count=514, vector_point_id='ch-doc-card-722-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-722-8', 'doc-card-722', 'sec-card-722-4', 8, 'rience): بستر پدیدارشناختی که در آن فرد رسانه را در زندگی روزمره معنادار می‌کند. • میان‌دستور (Inter-discourse): پیوند میان گفتمان‌های کلان که هویت و هنجار اجتماعی را می‌سازند.  ۳. نمونه‌های تحلیلی وقتی یک پژوهشگر با نگرش کارکردگرا به پوشش خبری انتخابات نگاه می‌کند، می‌پرسد «رسانه چگونه به پایداری نظام سیاسی کمک می‌کند؟» اما پژوهشگر تعارضی می‌پرسد «این پوشش، موقعیت کدام طبقه یا قوه را بازتولید می‌کند؟» — دو پارادایم، دو پرسش بنیادین از یک رویداد.  در تحلیل یک سریال تلویزنی، فمینیسم رسانه‌ای به بازنمایی زنان می‌نگرد، کوئیرتئوری به بازنمایی جنسیت‌های غیردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.', '30458643d2abc52df16e3fc80683387c3d0ef11d80ead069fc936294c79160cf', 1154, 'ch-doc-card-722-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='30458643d2abc52df16e3fc80683387c3d0ef11d80ead069fc936294c79160cf', token_count=1154, vector_point_id='ch-doc-card-722-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-722-9', 'doc-card-722', 'sec-card-722-4', 9, 'ردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.  پوشش خبری یک اعتصاب کارگری می‌تواند از سه پارادایم خوانده شود: کارکردگرا آن را «پایان‌بخشی به اختلال» می‌خواند، تعارضی آن را «نبرد طبقاتی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.  وقتی رسانه‌ها از «فقر» به‌عنوان «کمبود فردی» در برابر «شکاف ساختاری» گزارش می‌دهند، در عمل یک انتخاب پارادایمی (فردی/کلان) در جریان است.  در تحلیل گفتمان مهاجرت، کوئیرتئوری و فمینیسم رسانه‌ای به حضور یا غیاب زنان و افراد غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.', 'f7e94bf9a49b0191f246e901ad8f2fa47fb1bcf18d748c9040edfda84e722e39', 1078, 'ch-doc-card-722-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f7e94bf9a49b0191f246e901ad8f2fa47fb1bcf18d748c9040edfda84e722e39', token_count=1078, vector_point_id='ch-doc-card-722-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-722-10', 'doc-card-722', 'sec-card-722-4', 10, 'غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.  نظریه‌ی فلسفه‌ی رسانه پرسش می‌کند که «خودِ» تکنولوژی (بصری/گوشی/الگوریتم) چگونه پیش‌فرض‌های ما از «واقعیت» را دگرگون می‌کند — پرسشی که فراتر از تحلیل محتوا، در سطح هستی‌شناختی قرار دارد.  ۴. نقدها و چالش‌ها ۱. سطح‌آلودگی: پارادایم‌های کلان گاه «بسیار بزرگ‌تر» از داده‌های رسانه‌ای هستند و خطر تقلیل تحلیل رسانه به یک پیش‌فرض فلسفی را دارند. ۲. ناتوانی در آزمون: ادعاهای هستی‌شناختی و معرفت‌شناختی پارادایم‌ها به‌ندرت به پیش‌بینی‌های قابل‌آزمون درباره‌ی رسانه تبدیل می‌شوند. ۳. مشکل معرفت‌شناختی: مرز میان «تحلیل با پارادایم', '24a44b95f85f95e1a8b662cf475162dae081adb2d186e5ad98b47166fe35de47', 1094, 'ch-doc-card-722-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='24a44b95f85f95e1a8b662cf475162dae081adb2d186e5ad98b47166fe35de47', token_count=1094, vector_point_id='ch-doc-card-722-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-722-11', 'doc-card-722', 'sec-card-722-5', 11, 'وقتی یک پژوهشگر با نگرش کارکردگرا به پوشش خبری انتخابات نگاه می‌کند، می‌پرسد «رسانه چگونه به پایداری نظام سیاسی کمک می‌کند؟» اما پژوهشگر تعارضی می‌پرسد «این پوشش، موقعیت کدام طبقه یا قوه را بازتولید می‌کند؟» — دو پارادایم، دو پرسش بنیادین از یک رویداد.  در تحلیل یک سریال تلویزنی، فمینیسم رسانه‌ای به بازنمایی زنان می‌نگرد، کوئیرتئوری به بازنمایی جنسیت‌های غیردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.  پوشش خبری یک اعتصاب کارگری می‌تواند از سه پارادایم خوانده شود: کارکردگرا آن را «پایان‌بخشی به اختلال» می‌خواند، تعارضی آن را «نبرد طبقاتی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.', '3cca623c7b4db145a873737ee7ac459bf4fe07c5d42dc948595966eb0c0ab89c', 1185, 'ch-doc-card-722-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3cca623c7b4db145a873737ee7ac459bf4fe07c5d42dc948595966eb0c0ab89c', token_count=1185, vector_point_id='ch-doc-card-722-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-722-12', 'doc-card-722', 'sec-card-722-5', 12, 'تی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.  وقتی رسانه‌ها از «فقر» به‌عنوان «کمبود فردی» در برابر «شکاف ساختاری» گزارش می‌دهند، در عمل یک انتخاب پارادایمی (فردی/کلان) در جریان است.  در تحلیل گفتمان مهاجرت، کوئیرتئوری و فمینیسم رسانه‌ای به حضور یا غیاب زنان و افراد غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.  نظریه‌ی فلسفه‌ی رسانه پرسش می‌کند که «خودِ» تکنولوژی (بصری/گوشی/الگوریتم) چگونه پیش‌فرض‌های ما از «واقعیت» را دگرگون می‌کند — پرسشی که فراتر از تحلیل محتوا، در سطح هستی‌شناختی قرار دارد.', '3964a887a5f7f61d3707079756671ba972bed56a0753e9165c2cae980f3243e7', 1029, 'ch-doc-card-722-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3964a887a5f7f61d3707079756671ba972bed56a0753e9165c2cae980f3243e7', token_count=1029, vector_point_id='ch-doc-card-722-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-722-13', 'doc-card-722', 'sec-card-722-6', 13, '۱. سطح‌آلودگی: پارادایم‌های کلان گاه «بسیار بزرگ‌تر» از داده‌های رسانه‌ای هستند و خطر تقلیل تحلیل رسانه به یک پیش‌فرض فلسفی را دارند. ۲. ناتوانی در آزمون: ادعاهای هستی‌شناختی و معرفت‌شناختی پارادایم‌ها به‌ندرت به پیش‌بینی‌های قابل‌آزمون درباره‌ی رسانه تبدیل می‌شوند. ۳. مشکل معرفت‌شناختی: مرز میان «تحلیل با پارادایم» و «تحلیل از پیش‌فرض پارادایم» در عمل کمرنگ است و پژوهشگر اغلب پارادایم را انتخاب می‌کند، نه داده. ۴. تک‌پارادایمی‌شدن آموزش: در دوره‌های آموزشی، پارادایم‌ها به‌صورت بسته‌های بسته تدریس می‌شوند و دیالکتیک میان آن‌ها فراموش می‌شود. ۵. غرب‌مندی فلسفی: پارادایم‌های پساساختارگرایی، پدیدارشناسی و فمینیسمِ رسانه‌ای عمدتا در بافت‌های آکادمیک غربی شکل', '7f38efe2bb0ebacd2e44d05b3de77842ff65729ac3a6c5c3b9219e874ced915a', 1203, 'ch-doc-card-722-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7f38efe2bb0ebacd2e44d05b3de77842ff65729ac3a6c5c3b9219e874ced915a', token_count=1203, vector_point_id='ch-doc-card-722-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-722-14', 'doc-card-722', 'sec-card-722-7', 14, 'گرفته‌اند و کاربرد آن‌ها در بافت‌های دیگر نیازمند بومی‌سازی است. ۶. مسئله‌ی «عمل»: پارادایم‌های انتقادی در توصیف و نقد قوی‌اند، اما در «چه باید کرد؟» اغلب صامت می‌مانند. ۷. واژه‌آلودگی: استفاده‌ی زیاد از واژگان پارادایمی (بازتولید، ایدئولوژی، گفتمان) بدون تعریف روشن، تحلیل را مبهم می‌کند. ۸. خطر دوگانه‌سازی: پارادایم‌ها اغلب جهان را به دو دسته تقسیم می‌کنند (نظم/تعارض، ساختار/عاملیت) و پیچیدگی‌های میانی را نادیده می‌گیرند. ۹. نوسازی کند: دگرگونی‌های رسانه‌ای (پلتفرم، الگوریتم) سریع‌تر از بازسازی مفهومی پارادایم‌ها رخ می‌دهند. ۱۰. سیاست‌زدگی روش: در بسیاری از بافت‌ها، انتخاب یک پارادایم انتقادی، خود یک موضع سیاسی است و این «پیش‌مقوله» باید شفاف اعلام شود.', '16c91d6de9a957b0e729d93b5680fc395b3a50319da43e261dd217503feedee5', 1203, 'ch-doc-card-722-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='16c91d6de9a957b0e729d93b5680fc395b3a50319da43e261dd217503feedee5', token_count=1203, vector_point_id='ch-doc-card-722-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-722-15', 'doc-card-722', 'sec-card-722-10', 15, 'کتاب «نظریه‌های ارتباطات جمعی» (دنیس مک‌کوایل، ۱۹۸۳)؛ کتاب «فلسفه‌ی رسانه» (فیلیپ مک‌چر، ۲۰۰۵)؛ کتاب «ساختارهای عمیق فرهنگ و ذهن» (کلیر کلاسل، ۱۹۶۳)؛ استناد مبنا: McQuail (1983) بر طبقه‌بندی پارادایم‌ها.', '5e54f2a3bf785e5acae536d3523485d9a2dc63a2b3cd9f6eed85ebd882893d57', 369, 'ch-doc-card-722-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5e54f2a3bf785e5acae536d3523485d9a2dc63a2b3cd9f6eed85ebd882893d57', token_count=369, vector_point_id='ch-doc-card-722-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-723-0', 'doc-card-723', NULL, 0, 'فمینیسم رسانهای به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. توشمان در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا ساخته و …', '23867166a7452d850c1aeafb75b0a33ed5d71c1a2a83d7f34875f30ca66112d7', 496, 'ch-doc-card-723-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='23867166a7452d850c1aeafb75b0a33ed5d71c1a2a83d7f34875f30ca66112d7', token_count=496, vector_point_id='ch-doc-card-723-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-723-1', 'doc-card-723', 'sec-card-723-1', 1, 'نظریه‌ها و پارادایم‌های کلان  فمینیسم رسانهای به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. توشمان در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا ساخته و بازتولید می‌شود. این چارچوب در سطح کلان تحلیل، پرسش‌های بنیادین حوزه نظریه‌ها و پارادایم‌های کلان را شکل می‌دهد.  بر اساس فمینیسم رسانهای، درک رسانه بدون درک جایگاه آن در کلان‌نظام اجتماعی ممکن نیست. توشمان نشان داد که هر رویکرد به رسانه — چه کارکردگرا، چه انتقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند.', '828dad843a4bc786f3deab1f32d94637a9dc7fa137d9c8efc9f42cc7560594be', 1163, 'ch-doc-card-723-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='828dad843a4bc786f3deab1f32d94637a9dc7fa137d9c8efc9f42cc7560594be', token_count=1163, vector_point_id='ch-doc-card-723-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-723-2', 'doc-card-723', 'sec-card-723-1', 2, 'تقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند. این چارچوب در سطح کلان، رسانه را در بستر قدرت، اقتصاد و فرهنگ می‌خواند.  فمینیسم رسانهای پارادایمی است که مرز میان «جامعه» و «رسانه» را کمرنگ می‌کند: رسانه هم بازتاب‌دهنده‌ی کلان‌نظام اجتماعی است و هم خودِ آن را می‌سازد. توشمان در این چارچوب، پرسش «رسانه چه اثری دارد؟» را با پرسش «رسانه در این ساختار اجتماعی چه نقشی بازی می‌کند؟» جایگزین کرد و تحلیل را به سطح کلان برد.', 'e0ef45f92bacd77d8b93656971694c870de8e199a5cc95997300af62a21dc91e', 819, 'ch-doc-card-723-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e0ef45f92bacd77d8b93656971694c870de8e199a5cc95997300af62a21dc91e', token_count=819, vector_point_id='ch-doc-card-723-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-723-3', 'doc-card-723', 'sec-card-723-2', 3, '۱. بنیان و منطق نظری فمینیسم رسانهای به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. توشمان در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا ساخته و بازتولید می‌شود. این چارچوب در سطح کلان تحلیل، پرسش‌های بنیادین حوزه نظریه‌ها و پارادایم‌های کلان را شکل می‌دهد.  بر اساس فمینیسم رسانهای، درک رسانه بدون درک جایگاه آن در کلان‌نظام اجتماعی ممکن نیست. توشمان نشان داد که هر رویکرد به رسانه — چه کارکردگرا، چه انتقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند.', '2695a5eb4c99fc194b7a637ffc412e42323f3b716c7fa02e927b1923b9b498a3', 1147, 'ch-doc-card-723-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2695a5eb4c99fc194b7a637ffc412e42323f3b716c7fa02e927b1923b9b498a3', token_count=1147, vector_point_id='ch-doc-card-723-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-723-4', 'doc-card-723', 'sec-card-723-2', 4, 'تقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند. این چارچوب در سطح کلان، رسانه را در بستر قدرت، اقتصاد و فرهنگ می‌خواند.  فمینیسم رسانهای پارادایمی است که مرز میان «جامعه» و «رسانه» را کمرنگ می‌کند: رسانه هم بازتاب‌دهنده‌ی کلان‌نظام اجتماعی است و هم خودِ آن را می‌سازد. توشمان در این چارچوب، پرسش «رسانه چه اثری دارد؟» را با پرسش «رسانه در این ساختار اجتماعی چه نقشی بازی می‌کند؟» جایگزین کرد و تحلیل را به سطح کلان برد.  ۲. ساختارهای مفهومی • پارادایم (Paradigm): مجموعه‌ی پیش‌فرض‌های مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند.', '10d428e5df959b5b1713559e955d54b0d347924a1c11ebe7587f7a6f09b23731', 1080, 'ch-doc-card-723-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='10d428e5df959b5b1713559e955d54b0d347924a1c11ebe7587f7a6f09b23731', token_count=1080, vector_point_id='ch-doc-card-723-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-723-5', 'doc-card-723', 'sec-card-723-2', 5, 'ی مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند. • ساختار کلان (Macro-Structure): نظام‌های بزرگ اجتماعی — اقتصاد، سیاست، طبقات — که رسانه در آن‌ها عمل می‌کند. • بازتولید (Reproduction): فرایند تداوم و تکرار نظم اجتماعی از طریق نهادها و بازنمایی‌ها. • ایدئولوژی (Ideology): نظام باورهای «عادی‌به‌نظر»یافته که موقعیت‌های قدرت را توجیه می‌کند. • بازنمایی کلان (Macro-Representation): نشان‌دادن روابط اجتماعی بزرگ (طبقه، جنسیت، قومیت) در متن‌های رسانه‌ای. • نقد اجتماعی (Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد. • تجربه‌ی زیسته (Lived Experien', 'e2f01b15799cd0fdbd489445d1f1ec2c4e56c7e84650b80487039e5ea9c85029', 1105, 'ch-doc-card-723-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e2f01b15799cd0fdbd489445d1f1ec2c4e56c7e84650b80487039e5ea9c85029', token_count=1105, vector_point_id='ch-doc-card-723-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-723-6', 'doc-card-723', 'sec-card-723-3', 6, '• پارادایم (Paradigm): مجموعه‌ی پیش‌فرض‌های مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند. • ساختار کلان (Macro-Structure): نظام‌های بزرگ اجتماعی — اقتصاد، سیاست، طبقات — که رسانه در آن‌ها عمل می‌کند. • بازتولید (Reproduction): فرایند تداوم و تکرار نظم اجتماعی از طریق نهادها و بازنمایی‌ها. • ایدئولوژی (Ideology): نظام باورهای «عادی‌به‌نظر»یافته که موقعیت‌های قدرت را توجیه می‌کند. • بازنمایی کلان (Macro-Representation): نشان‌دادن روابط اجتماعی بزرگ (طبقه، جنسیت، قومیت) در متن‌های رسانه‌ای. • نقد اجتماعی (Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد.', '2739813c609a72e6f71aa6513ad47c37b7804f2e5db12dbc7a75dffccc10f4f9', 1123, 'ch-doc-card-723-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2739813c609a72e6f71aa6513ad47c37b7804f2e5db12dbc7a75dffccc10f4f9', token_count=1123, vector_point_id='ch-doc-card-723-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-723-7', 'doc-card-723', 'sec-card-723-3', 7, '(Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد. • تجربه‌ی زیسته (Lived Experience): بستر پدیدارشناختی که در آن فرد رسانه را در زندگی روزمره معنادار می‌کند. • میان‌دستور (Inter-discourse): پیوند میان گفتمان‌های کلان که هویت و هنجار اجتماعی را می‌سازند.', '8ac74a955304bcba921b3db4b00741a2ac1fe3c1ae0f02fc06ea47b8b6cdd050', 514, 'ch-doc-card-723-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8ac74a955304bcba921b3db4b00741a2ac1fe3c1ae0f02fc06ea47b8b6cdd050', token_count=514, vector_point_id='ch-doc-card-723-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-723-8', 'doc-card-723', 'sec-card-723-4', 8, 'ce): بستر پدیدارشناختی که در آن فرد رسانه را در زندگی روزمره معنادار می‌کند. • میان‌دستور (Inter-discourse): پیوند میان گفتمان‌های کلان که هویت و هنجار اجتماعی را می‌سازند.  ۳. نمونه‌های تحلیلی وقتی یک پژوهشگر با نگرش کارکردگرا به پوشش خبری انتخابات نگاه می‌کند، می‌پرسد «رسانه چگونه به پایداری نظام سیاسی کمک می‌کند؟» اما پژوهشگر تعارضی می‌پرسد «این پوشش، موقعیت کدام طبقه یا قوه را بازتولید می‌کند؟» — دو پارادایم، دو پرسش بنیادین از یک رویداد.  در تحلیل یک سریال تلویزنی، فمینیسم رسانه‌ای به بازنمایی زنان می‌نگرد، کوئیرتئوری به بازنمایی جنسیت‌های غیردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.', 'adfd5fb42a74fa51c7a500e6a6a6f6f6c3011aa543d752ce6f2098dbb34410e1', 1147, 'ch-doc-card-723-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='adfd5fb42a74fa51c7a500e6a6a6f6f6c3011aa543d752ce6f2098dbb34410e1', token_count=1147, vector_point_id='ch-doc-card-723-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-723-9', 'doc-card-723', 'sec-card-723-4', 9, 'ردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.  پوشش خبری یک اعتصاب کارگری می‌تواند از سه پارادایم خوانده شود: کارکردگرا آن را «پایان‌بخشی به اختلال» می‌خواند، تعارضی آن را «نبرد طبقاتی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.  وقتی رسانه‌ها از «فقر» به‌عنوان «کمبود فردی» در برابر «شکاف ساختاری» گزارش می‌دهند، در عمل یک انتخاب پارادایمی (فردی/کلان) در جریان است.  در تحلیل گفتمان مهاجرت، کوئیرتئوری و فمینیسم رسانه‌ای به حضور یا غیاب زنان و افراد غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.', 'f7e94bf9a49b0191f246e901ad8f2fa47fb1bcf18d748c9040edfda84e722e39', 1078, 'ch-doc-card-723-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f7e94bf9a49b0191f246e901ad8f2fa47fb1bcf18d748c9040edfda84e722e39', token_count=1078, vector_point_id='ch-doc-card-723-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-723-10', 'doc-card-723', 'sec-card-723-4', 10, 'غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.  نظریه‌ی فلسفه‌ی رسانه پرسش می‌کند که «خودِ» تکنولوژی (بصری/گوشی/الگوریتم) چگونه پیش‌فرض‌های ما از «واقعیت» را دگرگون می‌کند — پرسشی که فراتر از تحلیل محتوا، در سطح هستی‌شناختی قرار دارد.  ۴. نقدها و چالش‌ها ۱. سطح‌آلودگی: پارادایم‌های کلان گاه «بسیار بزرگ‌تر» از داده‌های رسانه‌ای هستند و خطر تقلیل تحلیل رسانه به یک پیش‌فرض فلسفی را دارند. ۲. ناتوانی در آزمون: ادعاهای هستی‌شناختی و معرفت‌شناختی پارادایم‌ها به‌ندرت به پیش‌بینی‌های قابل‌آزمون درباره‌ی رسانه تبدیل می‌شوند. ۳. مشکل معرفت‌شناختی: مرز میان «تحلیل با پارادایم» و', '3ab1b999885af3f683179fdd39ac1fac7b06fd9efaa142a050ac469dcf52d4bc', 1100, 'ch-doc-card-723-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3ab1b999885af3f683179fdd39ac1fac7b06fd9efaa142a050ac469dcf52d4bc', token_count=1100, vector_point_id='ch-doc-card-723-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-723-11', 'doc-card-723', 'sec-card-723-5', 11, 'وقتی یک پژوهشگر با نگرش کارکردگرا به پوشش خبری انتخابات نگاه می‌کند، می‌پرسد «رسانه چگونه به پایداری نظام سیاسی کمک می‌کند؟» اما پژوهشگر تعارضی می‌پرسد «این پوشش، موقعیت کدام طبقه یا قوه را بازتولید می‌کند؟» — دو پارادایم، دو پرسش بنیادین از یک رویداد.  در تحلیل یک سریال تلویزنی، فمینیسم رسانه‌ای به بازنمایی زنان می‌نگرد، کوئیرتئوری به بازنمایی جنسیت‌های غیردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.  پوشش خبری یک اعتصاب کارگری می‌تواند از سه پارادایم خوانده شود: کارکردگرا آن را «پایان‌بخشی به اختلال» می‌خواند، تعارضی آن را «نبرد طبقاتی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.', '3cca623c7b4db145a873737ee7ac459bf4fe07c5d42dc948595966eb0c0ab89c', 1185, 'ch-doc-card-723-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3cca623c7b4db145a873737ee7ac459bf4fe07c5d42dc948595966eb0c0ab89c', token_count=1185, vector_point_id='ch-doc-card-723-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-723-12', 'doc-card-723', 'sec-card-723-5', 12, 'تی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.  وقتی رسانه‌ها از «فقر» به‌عنوان «کمبود فردی» در برابر «شکاف ساختاری» گزارش می‌دهند، در عمل یک انتخاب پارادایمی (فردی/کلان) در جریان است.  در تحلیل گفتمان مهاجرت، کوئیرتئوری و فمینیسم رسانه‌ای به حضور یا غیاب زنان و افراد غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.  نظریه‌ی فلسفه‌ی رسانه پرسش می‌کند که «خودِ» تکنولوژی (بصری/گوشی/الگوریتم) چگونه پیش‌فرض‌های ما از «واقعیت» را دگرگون می‌کند — پرسشی که فراتر از تحلیل محتوا، در سطح هستی‌شناختی قرار دارد.', '3964a887a5f7f61d3707079756671ba972bed56a0753e9165c2cae980f3243e7', 1029, 'ch-doc-card-723-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3964a887a5f7f61d3707079756671ba972bed56a0753e9165c2cae980f3243e7', token_count=1029, vector_point_id='ch-doc-card-723-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-723-13', 'doc-card-723', 'sec-card-723-6', 13, '۱. سطح‌آلودگی: پارادایم‌های کلان گاه «بسیار بزرگ‌تر» از داده‌های رسانه‌ای هستند و خطر تقلیل تحلیل رسانه به یک پیش‌فرض فلسفی را دارند. ۲. ناتوانی در آزمون: ادعاهای هستی‌شناختی و معرفت‌شناختی پارادایم‌ها به‌ندرت به پیش‌بینی‌های قابل‌آزمون درباره‌ی رسانه تبدیل می‌شوند. ۳. مشکل معرفت‌شناختی: مرز میان «تحلیل با پارادایم» و «تحلیل از پیش‌فرض پارادایم» در عمل کمرنگ است و پژوهشگر اغلب پارادایم را انتخاب می‌کند، نه داده. ۴. تک‌پارادایمی‌شدن آموزش: در دوره‌های آموزشی، پارادایم‌ها به‌صورت بسته‌های بسته تدریس می‌شوند و دیالکتیک میان آن‌ها فراموش می‌شود. ۵. غرب‌مندی فلسفی: پارادایم‌های پساساختارگرایی، پدیدارشناسی و فمینیسمِ رسانه‌ای عمدتا در بافت‌های آکادمیک غربی شکل', '7f38efe2bb0ebacd2e44d05b3de77842ff65729ac3a6c5c3b9219e874ced915a', 1203, 'ch-doc-card-723-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7f38efe2bb0ebacd2e44d05b3de77842ff65729ac3a6c5c3b9219e874ced915a', token_count=1203, vector_point_id='ch-doc-card-723-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-723-14', 'doc-card-723', 'sec-card-723-7', 14, 'گرفته‌اند و کاربرد آن‌ها در بافت‌های دیگر نیازمند بومی‌سازی است. ۶. مسئله‌ی «عمل»: پارادایم‌های انتقادی در توصیف و نقد قوی‌اند، اما در «چه باید کرد؟» اغلب صامت می‌مانند. ۷. واژه‌آلودگی: استفاده‌ی زیاد از واژگان پارادایمی (بازتولید، ایدئولوژی، گفتمان) بدون تعریف روشن، تحلیل را مبهم می‌کند. ۸. خطر دوگانه‌سازی: پارادایم‌ها اغلب جهان را به دو دسته تقسیم می‌کنند (نظم/تعارض، ساختار/عاملیت) و پیچیدگی‌های میانی را نادیده می‌گیرند. ۹. نوسازی کند: دگرگونی‌های رسانه‌ای (پلتفرم، الگوریتم) سریع‌تر از بازسازی مفهومی پارادایم‌ها رخ می‌دهند. ۱۰. سیاست‌زدگی روش: در بسیاری از بافت‌ها، انتخاب یک پارادایم انتقادی، خود یک موضع سیاسی است و این «پیش‌مقوله» باید شفاف اعلام شود.', '16c91d6de9a957b0e729d93b5680fc395b3a50319da43e261dd217503feedee5', 1203, 'ch-doc-card-723-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='16c91d6de9a957b0e729d93b5680fc395b3a50319da43e261dd217503feedee5', token_count=1203, vector_point_id='ch-doc-card-723-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-723-15', 'doc-card-723', 'sec-card-723-10', 15, 'کتاب «نظریه‌های ارتباطات جمعی» (دنیس مک‌کوایل، ۱۹۸۳)؛ کتاب «فلسفه‌ی رسانه» (فیلیپ مک‌چر، ۲۰۰۵)؛ کتاب «ساختارهای عمیق فرهنگ و ذهن» (کلیر کلاسل، ۱۹۶۳)؛ استناد مبنا: McQuail (1983) بر طبقه‌بندی پارادایم‌ها.', '5e54f2a3bf785e5acae536d3523485d9a2dc63a2b3cd9f6eed85ebd882893d57', 369, 'ch-doc-card-723-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5e54f2a3bf785e5acae536d3523485d9a2dc63a2b3cd9f6eed85ebd882893d57', token_count=369, vector_point_id='ch-doc-card-723-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-724-0', 'doc-card-724', NULL, 0, 'نظریه کوئیر و رسانه به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. باتلر (۱۹۹۰) در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا ساخته …', '80aa2d0b821cd3bc46035bbb29bba1a13d3de25357b9908395282a885672cf64', 510, 'ch-doc-card-724-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='80aa2d0b821cd3bc46035bbb29bba1a13d3de25357b9908395282a885672cf64', token_count=510, vector_point_id='ch-doc-card-724-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-724-1', 'doc-card-724', 'sec-card-724-1', 1, 'نظریه‌ها و پارادایم‌های کلان  نظریه کوئیر و رسانه به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. باتلر (۱۹۹۰) در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا ساخته و بازتولید می‌شود. این چارچوب در سطح کلان تحلیل، پرسش‌های بنیادین حوزه نظریه‌ها و پارادایم‌های کلان را شکل می‌دهد.  بر اساس نظریه کوئیر و رسانه، درک رسانه بدون درک جایگاه آن در کلان‌نظام اجتماعی ممکن نیست. باتلر (۱۹۹۰) نشان داد که هر رویکرد به رسانه — چه کارکردگرا، چه انتقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند.', 'bdbb7f66866fb790c23f01c8aac66d5bae2fabbf00833e9abd6aea6b44355a00', 1200, 'ch-doc-card-724-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bdbb7f66866fb790c23f01c8aac66d5bae2fabbf00833e9abd6aea6b44355a00', token_count=1200, vector_point_id='ch-doc-card-724-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-724-2', 'doc-card-724', 'sec-card-724-1', 2, 'تقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند. این چارچوب در سطح کلان، رسانه را در بستر قدرت، اقتصاد و فرهنگ می‌خواند.  نظریه کوئیر و رسانه پارادایمی است که مرز میان «جامعه» و «رسانه» را کمرنگ می‌کند: رسانه هم بازتاب‌دهنده‌ی کلان‌نظام اجتماعی است و هم خودِ آن را می‌سازد. باتلر (۱۹۹۰) در این چارچوب، پرسش «رسانه چه اثری دارد؟» را با پرسش «رسانه در این ساختار اجتماعی چه نقشی بازی می‌کند؟» جایگزین کرد و تحلیل را به سطح کلان برد.', '05da99e3d9c1cba96a9fcc3e52862b881260308c19950dd5bdbe492eca77fdf0', 838, 'ch-doc-card-724-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='05da99e3d9c1cba96a9fcc3e52862b881260308c19950dd5bdbe492eca77fdf0', token_count=838, vector_point_id='ch-doc-card-724-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-724-3', 'doc-card-724', 'sec-card-724-2', 3, '۱. بنیان و منطق نظری نظریه کوئیر و رسانه به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. باتلر (۱۹۹۰) در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا ساخته و بازتولید می‌شود. این چارچوب در سطح کلان تحلیل، پرسش‌های بنیادین حوزه نظریه‌ها و پارادایم‌های کلان را شکل می‌دهد.  بر اساس نظریه کوئیر و رسانه، درک رسانه بدون درک جایگاه آن در کلان‌نظام اجتماعی ممکن نیست. باتلر (۱۹۹۰) نشان داد که هر رویکرد به رسانه — چه کارکردگرا، چه انتقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند.', 'cb6bce52ef69acbe185062ff88c4718c95a24e8b733c0e384b59b3e530b2ebb5', 1183, 'ch-doc-card-724-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cb6bce52ef69acbe185062ff88c4718c95a24e8b733c0e384b59b3e530b2ebb5', token_count=1183, vector_point_id='ch-doc-card-724-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-724-4', 'doc-card-724', 'sec-card-724-2', 4, 'تقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند. این چارچوب در سطح کلان، رسانه را در بستر قدرت، اقتصاد و فرهنگ می‌خواند.  نظریه کوئیر و رسانه پارادایمی است که مرز میان «جامعه» و «رسانه» را کمرنگ می‌کند: رسانه هم بازتاب‌دهنده‌ی کلان‌نظام اجتماعی است و هم خودِ آن را می‌سازد. باتلر (۱۹۹۰) در این چارچوب، پرسش «رسانه چه اثری دارد؟» را با پرسش «رسانه در این ساختار اجتماعی چه نقشی بازی می‌کند؟» جایگزین کرد و تحلیل را به سطح کلان برد.  ۲. ساختارهای مفهومی • پارادایم (Paradigm): مجموعه‌ی پیش‌فرض‌های مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند.', '52ce25f4584e4ff660dd235616ef32534497f2201116efac8683f2a62fead3ca', 1098, 'ch-doc-card-724-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='52ce25f4584e4ff660dd235616ef32534497f2201116efac8683f2a62fead3ca', token_count=1098, vector_point_id='ch-doc-card-724-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-724-5', 'doc-card-724', 'sec-card-724-2', 5, 'ی مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند. • ساختار کلان (Macro-Structure): نظام‌های بزرگ اجتماعی — اقتصاد، سیاست، طبقات — که رسانه در آن‌ها عمل می‌کند. • بازتولید (Reproduction): فرایند تداوم و تکرار نظم اجتماعی از طریق نهادها و بازنمایی‌ها. • ایدئولوژی (Ideology): نظام باورهای «عادی‌به‌نظر»یافته که موقعیت‌های قدرت را توجیه می‌کند. • بازنمایی کلان (Macro-Representation): نشان‌دادن روابط اجتماعی بزرگ (طبقه، جنسیت، قومیت) در متن‌های رسانه‌ای. • نقد اجتماعی (Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد. • تجربه‌ی زی', '77125103d11803d6f260c7a82993189b127604fe37a3d889724277d8d650e7b9', 1070, 'ch-doc-card-724-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='77125103d11803d6f260c7a82993189b127604fe37a3d889724277d8d650e7b9', token_count=1070, vector_point_id='ch-doc-card-724-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-724-6', 'doc-card-724', 'sec-card-724-3', 6, '• پارادایم (Paradigm): مجموعه‌ی پیش‌فرض‌های مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند. • ساختار کلان (Macro-Structure): نظام‌های بزرگ اجتماعی — اقتصاد، سیاست، طبقات — که رسانه در آن‌ها عمل می‌کند. • بازتولید (Reproduction): فرایند تداوم و تکرار نظم اجتماعی از طریق نهادها و بازنمایی‌ها. • ایدئولوژی (Ideology): نظام باورهای «عادی‌به‌نظر»یافته که موقعیت‌های قدرت را توجیه می‌کند. • بازنمایی کلان (Macro-Representation): نشان‌دادن روابط اجتماعی بزرگ (طبقه، جنسیت، قومیت) در متن‌های رسانه‌ای. • نقد اجتماعی (Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد.', '2739813c609a72e6f71aa6513ad47c37b7804f2e5db12dbc7a75dffccc10f4f9', 1123, 'ch-doc-card-724-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2739813c609a72e6f71aa6513ad47c37b7804f2e5db12dbc7a75dffccc10f4f9', token_count=1123, vector_point_id='ch-doc-card-724-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-724-7', 'doc-card-724', 'sec-card-724-3', 7, '(Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد. • تجربه‌ی زیسته (Lived Experience): بستر پدیدارشناختی که در آن فرد رسانه را در زندگی روزمره معنادار می‌کند. • میان‌دستور (Inter-discourse): پیوند میان گفتمان‌های کلان که هویت و هنجار اجتماعی را می‌سازند.', '8ac74a955304bcba921b3db4b00741a2ac1fe3c1ae0f02fc06ea47b8b6cdd050', 514, 'ch-doc-card-724-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8ac74a955304bcba921b3db4b00741a2ac1fe3c1ae0f02fc06ea47b8b6cdd050', token_count=514, vector_point_id='ch-doc-card-724-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-724-8', 'doc-card-724', 'sec-card-724-4', 8, 'سته (Lived Experience): بستر پدیدارشناختی که در آن فرد رسانه را در زندگی روزمره معنادار می‌کند. • میان‌دستور (Inter-discourse): پیوند میان گفتمان‌های کلان که هویت و هنجار اجتماعی را می‌سازند.  ۳. نمونه‌های تحلیلی وقتی یک پژوهشگر با نگرش کارکردگرا به پوشش خبری انتخابات نگاه می‌کند، می‌پرسد «رسانه چگونه به پایداری نظام سیاسی کمک می‌کند؟» اما پژوهشگر تعارضی می‌پرسد «این پوشش، موقعیت کدام طبقه یا قوه را بازتولید می‌کند؟» — دو پارادایم، دو پرسش بنیادین از یک رویداد.  در تحلیل یک سریال تلویزنی، فمینیسم رسانه‌ای به بازنمایی زنان می‌نگرد، کوئیرتئوری به بازنمایی جنسیت‌های غیردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.', 'db24f9148ab91bc51bf2afe8bf3b3bb6dea59ff085e9f0b91d4bf6e9d03a4822', 1181, 'ch-doc-card-724-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='db24f9148ab91bc51bf2afe8bf3b3bb6dea59ff085e9f0b91d4bf6e9d03a4822', token_count=1181, vector_point_id='ch-doc-card-724-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-724-9', 'doc-card-724', 'sec-card-724-4', 9, 'ردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.  پوشش خبری یک اعتصاب کارگری می‌تواند از سه پارادایم خوانده شود: کارکردگرا آن را «پایان‌بخشی به اختلال» می‌خواند، تعارضی آن را «نبرد طبقاتی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.  وقتی رسانه‌ها از «فقر» به‌عنوان «کمبود فردی» در برابر «شکاف ساختاری» گزارش می‌دهند، در عمل یک انتخاب پارادایمی (فردی/کلان) در جریان است.  در تحلیل گفتمان مهاجرت، کوئیرتئوری و فمینیسم رسانه‌ای به حضور یا غیاب زنان و افراد غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.', 'f7e94bf9a49b0191f246e901ad8f2fa47fb1bcf18d748c9040edfda84e722e39', 1078, 'ch-doc-card-724-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f7e94bf9a49b0191f246e901ad8f2fa47fb1bcf18d748c9040edfda84e722e39', token_count=1078, vector_point_id='ch-doc-card-724-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-724-10', 'doc-card-724', 'sec-card-724-4', 10, 'غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.  نظریه‌ی فلسفه‌ی رسانه پرسش می‌کند که «خودِ» تکنولوژی (بصری/گوشی/الگوریتم) چگونه پیش‌فرض‌های ما از «واقعیت» را دگرگون می‌کند — پرسشی که فراتر از تحلیل محتوا، در سطح هستی‌شناختی قرار دارد.  ۴. نقدها و چالش‌ها ۱. سطح‌آلودگی: پارادایم‌های کلان گاه «بسیار بزرگ‌تر» از داده‌های رسانه‌ای هستند و خطر تقلیل تحلیل رسانه به یک پیش‌فرض فلسفی را دارند. ۲. ناتوانی در آزمون: ادعاهای هستی‌شناختی و معرفت‌شناختی پارادایم‌ها به‌ندرت به پیش‌بینی‌های قابل‌آزمون درباره‌ی رسانه تبدیل می‌شوند. ۳. مشکل معرفت‌شناختی: مرز میان «تحلیل با پارا', '33155c7c7f42cc80e0c1fef14b352263beef390988e5864356c09c27728c5fc3', 1087, 'ch-doc-card-724-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='33155c7c7f42cc80e0c1fef14b352263beef390988e5864356c09c27728c5fc3', token_count=1087, vector_point_id='ch-doc-card-724-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-724-11', 'doc-card-724', 'sec-card-724-5', 11, 'وقتی یک پژوهشگر با نگرش کارکردگرا به پوشش خبری انتخابات نگاه می‌کند، می‌پرسد «رسانه چگونه به پایداری نظام سیاسی کمک می‌کند؟» اما پژوهشگر تعارضی می‌پرسد «این پوشش، موقعیت کدام طبقه یا قوه را بازتولید می‌کند؟» — دو پارادایم، دو پرسش بنیادین از یک رویداد.  در تحلیل یک سریال تلویزنی، فمینیسم رسانه‌ای به بازنمایی زنان می‌نگرد، کوئیرتئوری به بازنمایی جنسیت‌های غیردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.  پوشش خبری یک اعتصاب کارگری می‌تواند از سه پارادایم خوانده شود: کارکردگرا آن را «پایان‌بخشی به اختلال» می‌خواند، تعارضی آن را «نبرد طبقاتی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.', '3cca623c7b4db145a873737ee7ac459bf4fe07c5d42dc948595966eb0c0ab89c', 1185, 'ch-doc-card-724-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3cca623c7b4db145a873737ee7ac459bf4fe07c5d42dc948595966eb0c0ab89c', token_count=1185, vector_point_id='ch-doc-card-724-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-724-12', 'doc-card-724', 'sec-card-724-5', 12, 'تی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.  وقتی رسانه‌ها از «فقر» به‌عنوان «کمبود فردی» در برابر «شکاف ساختاری» گزارش می‌دهند، در عمل یک انتخاب پارادایمی (فردی/کلان) در جریان است.  در تحلیل گفتمان مهاجرت، کوئیرتئوری و فمینیسم رسانه‌ای به حضور یا غیاب زنان و افراد غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.  نظریه‌ی فلسفه‌ی رسانه پرسش می‌کند که «خودِ» تکنولوژی (بصری/گوشی/الگوریتم) چگونه پیش‌فرض‌های ما از «واقعیت» را دگرگون می‌کند — پرسشی که فراتر از تحلیل محتوا، در سطح هستی‌شناختی قرار دارد.', '3964a887a5f7f61d3707079756671ba972bed56a0753e9165c2cae980f3243e7', 1029, 'ch-doc-card-724-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3964a887a5f7f61d3707079756671ba972bed56a0753e9165c2cae980f3243e7', token_count=1029, vector_point_id='ch-doc-card-724-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-724-13', 'doc-card-724', 'sec-card-724-6', 13, '۱. سطح‌آلودگی: پارادایم‌های کلان گاه «بسیار بزرگ‌تر» از داده‌های رسانه‌ای هستند و خطر تقلیل تحلیل رسانه به یک پیش‌فرض فلسفی را دارند. ۲. ناتوانی در آزمون: ادعاهای هستی‌شناختی و معرفت‌شناختی پارادایم‌ها به‌ندرت به پیش‌بینی‌های قابل‌آزمون درباره‌ی رسانه تبدیل می‌شوند. ۳. مشکل معرفت‌شناختی: مرز میان «تحلیل با پارادایم» و «تحلیل از پیش‌فرض پارادایم» در عمل کمرنگ است و پژوهشگر اغلب پارادایم را انتخاب می‌کند، نه داده. ۴. تک‌پارادایمی‌شدن آموزش: در دوره‌های آموزشی، پارادایم‌ها به‌صورت بسته‌های بسته تدریس می‌شوند و دیالکتیک میان آن‌ها فراموش می‌شود. ۵. غرب‌مندی فلسفی: پارادایم‌های پساساختارگرایی، پدیدارشناسی و فمینیسمِ رسانه‌ای عمدتا در بافت‌های آکادمیک غربی شکل', '7f38efe2bb0ebacd2e44d05b3de77842ff65729ac3a6c5c3b9219e874ced915a', 1203, 'ch-doc-card-724-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7f38efe2bb0ebacd2e44d05b3de77842ff65729ac3a6c5c3b9219e874ced915a', token_count=1203, vector_point_id='ch-doc-card-724-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-724-14', 'doc-card-724', 'sec-card-724-7', 14, 'گرفته‌اند و کاربرد آن‌ها در بافت‌های دیگر نیازمند بومی‌سازی است. ۶. مسئله‌ی «عمل»: پارادایم‌های انتقادی در توصیف و نقد قوی‌اند، اما در «چه باید کرد؟» اغلب صامت می‌مانند. ۷. واژه‌آلودگی: استفاده‌ی زیاد از واژگان پارادایمی (بازتولید، ایدئولوژی، گفتمان) بدون تعریف روشن، تحلیل را مبهم می‌کند. ۸. خطر دوگانه‌سازی: پارادایم‌ها اغلب جهان را به دو دسته تقسیم می‌کنند (نظم/تعارض، ساختار/عاملیت) و پیچیدگی‌های میانی را نادیده می‌گیرند. ۹. نوسازی کند: دگرگونی‌های رسانه‌ای (پلتفرم، الگوریتم) سریع‌تر از بازسازی مفهومی پارادایم‌ها رخ می‌دهند. ۱۰. سیاست‌زدگی روش: در بسیاری از بافت‌ها، انتخاب یک پارادایم انتقادی، خود یک موضع سیاسی است و این «پیش‌مقوله» باید شفاف اعلام شود.', '16c91d6de9a957b0e729d93b5680fc395b3a50319da43e261dd217503feedee5', 1203, 'ch-doc-card-724-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='16c91d6de9a957b0e729d93b5680fc395b3a50319da43e261dd217503feedee5', token_count=1203, vector_point_id='ch-doc-card-724-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-724-15', 'doc-card-724', 'sec-card-724-10', 15, 'کتاب «نظریه‌های ارتباطات جمعی» (دنیس مک‌کوایل، ۱۹۸۳)؛ کتاب «فلسفه‌ی رسانه» (فیلیپ مک‌چر، ۲۰۰۵)؛ کتاب «ساختارهای عمیق فرهنگ و ذهن» (کلیر کلاسل، ۱۹۶۳)؛ استناد مبنا: McQuail (1983) بر طبقه‌بندی پارادایم‌ها.', '5e54f2a3bf785e5acae536d3523485d9a2dc63a2b3cd9f6eed85ebd882893d57', 369, 'ch-doc-card-724-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5e54f2a3bf785e5acae536d3523485d9a2dc63a2b3cd9f6eed85ebd882893d57', token_count=369, vector_point_id='ch-doc-card-724-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-725-0', 'doc-card-725', NULL, 0, 'پساساختارگرایی به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. دریدا در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا ساخته و بازتولید …', '6a612f20b9d42d15e1bc7c9ab3a910564ab4a37baf08d88230bf392e357693cc', 509, 'ch-doc-card-725-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6a612f20b9d42d15e1bc7c9ab3a910564ab4a37baf08d88230bf392e357693cc', token_count=509, vector_point_id='ch-doc-card-725-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-725-1', 'doc-card-725', 'sec-card-725-1', 1, 'نظریه‌ها و پارادایم‌های کلان  پساساختارگرایی به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. دریدا در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا ساخته و بازتولید می‌شود. این چارچوب در سطح کلان تحلیل، پرسش‌های بنیادین حوزه نظریه‌ها و پارادایم‌های کلان را شکل می‌دهد.  بر اساس پساساختارگرایی، درک رسانه بدون درک جایگاه آن در کلان‌نظام اجتماعی ممکن نیست. دریدا نشان داد که هر رویکرد به رسانه — چه کارکردگرا، چه انتقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند.', '1afcd708981453a21b9777d4d3863a9e7ea9e9e37e092d22c3512618753aa1c1', 1156, 'ch-doc-card-725-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1afcd708981453a21b9777d4d3863a9e7ea9e9e37e092d22c3512618753aa1c1', token_count=1156, vector_point_id='ch-doc-card-725-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-725-2', 'doc-card-725', 'sec-card-725-1', 2, 'تقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند. این چارچوب در سطح کلان، رسانه را در بستر قدرت، اقتصاد و فرهنگ می‌خواند.  پساساختارگرایی پارادایمی است که مرز میان «جامعه» و «رسانه» را کمرنگ می‌کند: رسانه هم بازتاب‌دهنده‌ی کلان‌نظام اجتماعی است و هم خودِ آن را می‌سازد. دریدا در این چارچوب، پرسش «رسانه چه اثری دارد؟» را با پرسش «رسانه در این ساختار اجتماعی چه نقشی بازی می‌کند؟» جایگزین کرد و تحلیل را به سطح کلان برد.', 'f121d3d19d907e5ec90946d96749eeb6d32c83c6ac5c9c2517323447675a6ad0', 816, 'ch-doc-card-725-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f121d3d19d907e5ec90946d96749eeb6d32c83c6ac5c9c2517323447675a6ad0', token_count=816, vector_point_id='ch-doc-card-725-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-725-3', 'doc-card-725', 'sec-card-725-2', 3, '۱. بنیان و منطق نظری پساساختارگرایی به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. دریدا در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا ساخته و بازتولید می‌شود. این چارچوب در سطح کلان تحلیل، پرسش‌های بنیادین حوزه نظریه‌ها و پارادایم‌های کلان را شکل می‌دهد.  بر اساس پساساختارگرایی، درک رسانه بدون درک جایگاه آن در کلان‌نظام اجتماعی ممکن نیست. دریدا نشان داد که هر رویکرد به رسانه — چه کارکردگرا، چه انتقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند.', 'd28b7538c34d1c0223924650bbeb3593ee5fdab63500d9b12be4ec0cb58f005c', 1140, 'ch-doc-card-725-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d28b7538c34d1c0223924650bbeb3593ee5fdab63500d9b12be4ec0cb58f005c', token_count=1140, vector_point_id='ch-doc-card-725-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-725-4', 'doc-card-725', 'sec-card-725-2', 4, 'تقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند. این چارچوب در سطح کلان، رسانه را در بستر قدرت، اقتصاد و فرهنگ می‌خواند.  پساساختارگرایی پارادایمی است که مرز میان «جامعه» و «رسانه» را کمرنگ می‌کند: رسانه هم بازتاب‌دهنده‌ی کلان‌نظام اجتماعی است و هم خودِ آن را می‌سازد. دریدا در این چارچوب، پرسش «رسانه چه اثری دارد؟» را با پرسش «رسانه در این ساختار اجتماعی چه نقشی بازی می‌کند؟» جایگزین کرد و تحلیل را به سطح کلان برد.  ۲. ساختارهای مفهومی • پارادایم (Paradigm): مجموعه‌ی پیش‌فرض‌های مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند.', 'f7e379b53bde350c9a8f2df2dc06572c7e5f8d878e1e57c1f60829069a6572e8', 1076, 'ch-doc-card-725-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f7e379b53bde350c9a8f2df2dc06572c7e5f8d878e1e57c1f60829069a6572e8', token_count=1076, vector_point_id='ch-doc-card-725-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-725-5', 'doc-card-725', 'sec-card-725-2', 5, 'ی مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند. • ساختار کلان (Macro-Structure): نظام‌های بزرگ اجتماعی — اقتصاد، سیاست، طبقات — که رسانه در آن‌ها عمل می‌کند. • بازتولید (Reproduction): فرایند تداوم و تکرار نظم اجتماعی از طریق نهادها و بازنمایی‌ها. • ایدئولوژی (Ideology): نظام باورهای «عادی‌به‌نظر»یافته که موقعیت‌های قدرت را توجیه می‌کند. • بازنمایی کلان (Macro-Representation): نشان‌دادن روابط اجتماعی بزرگ (طبقه، جنسیت، قومیت) در متن‌های رسانه‌ای. • نقد اجتماعی (Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد. • تجربه‌ی زیسته (Lived Experience)', '5f66b3b43e1321b39d6f189761cc7b587331107fe1eaed55bd6b5758e0d11101', 1110, 'ch-doc-card-725-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5f66b3b43e1321b39d6f189761cc7b587331107fe1eaed55bd6b5758e0d11101', token_count=1110, vector_point_id='ch-doc-card-725-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-725-6', 'doc-card-725', 'sec-card-725-3', 6, '• پارادایم (Paradigm): مجموعه‌ی پیش‌فرض‌های مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند. • ساختار کلان (Macro-Structure): نظام‌های بزرگ اجتماعی — اقتصاد، سیاست، طبقات — که رسانه در آن‌ها عمل می‌کند. • بازتولید (Reproduction): فرایند تداوم و تکرار نظم اجتماعی از طریق نهادها و بازنمایی‌ها. • ایدئولوژی (Ideology): نظام باورهای «عادی‌به‌نظر»یافته که موقعیت‌های قدرت را توجیه می‌کند. • بازنمایی کلان (Macro-Representation): نشان‌دادن روابط اجتماعی بزرگ (طبقه، جنسیت، قومیت) در متن‌های رسانه‌ای. • نقد اجتماعی (Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد.', '2739813c609a72e6f71aa6513ad47c37b7804f2e5db12dbc7a75dffccc10f4f9', 1123, 'ch-doc-card-725-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2739813c609a72e6f71aa6513ad47c37b7804f2e5db12dbc7a75dffccc10f4f9', token_count=1123, vector_point_id='ch-doc-card-725-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-725-7', 'doc-card-725', 'sec-card-725-3', 7, '(Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد. • تجربه‌ی زیسته (Lived Experience): بستر پدیدارشناختی که در آن فرد رسانه را در زندگی روزمره معنادار می‌کند. • میان‌دستور (Inter-discourse): پیوند میان گفتمان‌های کلان که هویت و هنجار اجتماعی را می‌سازند.', '8ac74a955304bcba921b3db4b00741a2ac1fe3c1ae0f02fc06ea47b8b6cdd050', 514, 'ch-doc-card-725-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8ac74a955304bcba921b3db4b00741a2ac1fe3c1ae0f02fc06ea47b8b6cdd050', token_count=514, vector_point_id='ch-doc-card-725-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-725-8', 'doc-card-725', 'sec-card-725-4', 8, ': بستر پدیدارشناختی که در آن فرد رسانه را در زندگی روزمره معنادار می‌کند. • میان‌دستور (Inter-discourse): پیوند میان گفتمان‌های کلان که هویت و هنجار اجتماعی را می‌سازند.  ۳. نمونه‌های تحلیلی وقتی یک پژوهشگر با نگرش کارکردگرا به پوشش خبری انتخابات نگاه می‌کند، می‌پرسد «رسانه چگونه به پایداری نظام سیاسی کمک می‌کند؟» اما پژوهشگر تعارضی می‌پرسد «این پوشش، موقعیت کدام طبقه یا قوه را بازتولید می‌کند؟» — دو پارادایم، دو پرسش بنیادین از یک رویداد.  در تحلیل یک سریال تلویزنی، فمینیسم رسانه‌ای به بازنمایی زنان می‌نگرد، کوئیرتئوری به بازنمایی جنسیت‌های غیردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.', 'd85095c97a3cb1c05b876ea399444b4f3c75ba5467fc70e61fc56ba63d24a45c', 1141, 'ch-doc-card-725-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d85095c97a3cb1c05b876ea399444b4f3c75ba5467fc70e61fc56ba63d24a45c', token_count=1141, vector_point_id='ch-doc-card-725-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-725-9', 'doc-card-725', 'sec-card-725-4', 9, 'ردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.  پوشش خبری یک اعتصاب کارگری می‌تواند از سه پارادایم خوانده شود: کارکردگرا آن را «پایان‌بخشی به اختلال» می‌خواند، تعارضی آن را «نبرد طبقاتی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.  وقتی رسانه‌ها از «فقر» به‌عنوان «کمبود فردی» در برابر «شکاف ساختاری» گزارش می‌دهند، در عمل یک انتخاب پارادایمی (فردی/کلان) در جریان است.  در تحلیل گفتمان مهاجرت، کوئیرتئوری و فمینیسم رسانه‌ای به حضور یا غیاب زنان و افراد غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.', 'f7e94bf9a49b0191f246e901ad8f2fa47fb1bcf18d748c9040edfda84e722e39', 1078, 'ch-doc-card-725-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f7e94bf9a49b0191f246e901ad8f2fa47fb1bcf18d748c9040edfda84e722e39', token_count=1078, vector_point_id='ch-doc-card-725-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-725-10', 'doc-card-725', 'sec-card-725-4', 10, 'غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.  نظریه‌ی فلسفه‌ی رسانه پرسش می‌کند که «خودِ» تکنولوژی (بصری/گوشی/الگوریتم) چگونه پیش‌فرض‌های ما از «واقعیت» را دگرگون می‌کند — پرسشی که فراتر از تحلیل محتوا، در سطح هستی‌شناختی قرار دارد.  ۴. نقدها و چالش‌ها ۱. سطح‌آلودگی: پارادایم‌های کلان گاه «بسیار بزرگ‌تر» از داده‌های رسانه‌ای هستند و خطر تقلیل تحلیل رسانه به یک پیش‌فرض فلسفی را دارند. ۲. ناتوانی در آزمون: ادعاهای هستی‌شناختی و معرفت‌شناختی پارادایم‌ها به‌ندرت به پیش‌بینی‌های قابل‌آزمون درباره‌ی رسانه تبدیل می‌شوند. ۳. مشکل معرفت‌شناختی: مرز میان «تحلیل با پارادایم» و «', 'e07a3ee459e441686e0096367dd2450fed0d452888f451586d797ea56da7d425', 1103, 'ch-doc-card-725-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e07a3ee459e441686e0096367dd2450fed0d452888f451586d797ea56da7d425', token_count=1103, vector_point_id='ch-doc-card-725-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-725-11', 'doc-card-725', 'sec-card-725-5', 11, 'وقتی یک پژوهشگر با نگرش کارکردگرا به پوشش خبری انتخابات نگاه می‌کند، می‌پرسد «رسانه چگونه به پایداری نظام سیاسی کمک می‌کند؟» اما پژوهشگر تعارضی می‌پرسد «این پوشش، موقعیت کدام طبقه یا قوه را بازتولید می‌کند؟» — دو پارادایم، دو پرسش بنیادین از یک رویداد.  در تحلیل یک سریال تلویزنی، فمینیسم رسانه‌ای به بازنمایی زنان می‌نگرد، کوئیرتئوری به بازنمایی جنسیت‌های غیردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.  پوشش خبری یک اعتصاب کارگری می‌تواند از سه پارادایم خوانده شود: کارکردگرا آن را «پایان‌بخشی به اختلال» می‌خواند، تعارضی آن را «نبرد طبقاتی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.', '3cca623c7b4db145a873737ee7ac459bf4fe07c5d42dc948595966eb0c0ab89c', 1185, 'ch-doc-card-725-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3cca623c7b4db145a873737ee7ac459bf4fe07c5d42dc948595966eb0c0ab89c', token_count=1185, vector_point_id='ch-doc-card-725-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-725-12', 'doc-card-725', 'sec-card-725-5', 12, 'تی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.  وقتی رسانه‌ها از «فقر» به‌عنوان «کمبود فردی» در برابر «شکاف ساختاری» گزارش می‌دهند، در عمل یک انتخاب پارادایمی (فردی/کلان) در جریان است.  در تحلیل گفتمان مهاجرت، کوئیرتئوری و فمینیسم رسانه‌ای به حضور یا غیاب زنان و افراد غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.  نظریه‌ی فلسفه‌ی رسانه پرسش می‌کند که «خودِ» تکنولوژی (بصری/گوشی/الگوریتم) چگونه پیش‌فرض‌های ما از «واقعیت» را دگرگون می‌کند — پرسشی که فراتر از تحلیل محتوا، در سطح هستی‌شناختی قرار دارد.', '3964a887a5f7f61d3707079756671ba972bed56a0753e9165c2cae980f3243e7', 1029, 'ch-doc-card-725-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3964a887a5f7f61d3707079756671ba972bed56a0753e9165c2cae980f3243e7', token_count=1029, vector_point_id='ch-doc-card-725-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-725-13', 'doc-card-725', 'sec-card-725-6', 13, '۱. سطح‌آلودگی: پارادایم‌های کلان گاه «بسیار بزرگ‌تر» از داده‌های رسانه‌ای هستند و خطر تقلیل تحلیل رسانه به یک پیش‌فرض فلسفی را دارند. ۲. ناتوانی در آزمون: ادعاهای هستی‌شناختی و معرفت‌شناختی پارادایم‌ها به‌ندرت به پیش‌بینی‌های قابل‌آزمون درباره‌ی رسانه تبدیل می‌شوند. ۳. مشکل معرفت‌شناختی: مرز میان «تحلیل با پارادایم» و «تحلیل از پیش‌فرض پارادایم» در عمل کمرنگ است و پژوهشگر اغلب پارادایم را انتخاب می‌کند، نه داده. ۴. تک‌پارادایمی‌شدن آموزش: در دوره‌های آموزشی، پارادایم‌ها به‌صورت بسته‌های بسته تدریس می‌شوند و دیالکتیک میان آن‌ها فراموش می‌شود. ۵. غرب‌مندی فلسفی: پارادایم‌های پساساختارگرایی، پدیدارشناسی و فمینیسمِ رسانه‌ای عمدتا در بافت‌های آکادمیک غربی شکل', '7f38efe2bb0ebacd2e44d05b3de77842ff65729ac3a6c5c3b9219e874ced915a', 1203, 'ch-doc-card-725-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7f38efe2bb0ebacd2e44d05b3de77842ff65729ac3a6c5c3b9219e874ced915a', token_count=1203, vector_point_id='ch-doc-card-725-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-725-14', 'doc-card-725', 'sec-card-725-7', 14, 'گرفته‌اند و کاربرد آن‌ها در بافت‌های دیگر نیازمند بومی‌سازی است. ۶. مسئله‌ی «عمل»: پارادایم‌های انتقادی در توصیف و نقد قوی‌اند، اما در «چه باید کرد؟» اغلب صامت می‌مانند. ۷. واژه‌آلودگی: استفاده‌ی زیاد از واژگان پارادایمی (بازتولید، ایدئولوژی، گفتمان) بدون تعریف روشن، تحلیل را مبهم می‌کند. ۸. خطر دوگانه‌سازی: پارادایم‌ها اغلب جهان را به دو دسته تقسیم می‌کنند (نظم/تعارض، ساختار/عاملیت) و پیچیدگی‌های میانی را نادیده می‌گیرند. ۹. نوسازی کند: دگرگونی‌های رسانه‌ای (پلتفرم، الگوریتم) سریع‌تر از بازسازی مفهومی پارادایم‌ها رخ می‌دهند. ۱۰. سیاست‌زدگی روش: در بسیاری از بافت‌ها، انتخاب یک پارادایم انتقادی، خود یک موضع سیاسی است و این «پیش‌مقوله» باید شفاف اعلام شود.', '16c91d6de9a957b0e729d93b5680fc395b3a50319da43e261dd217503feedee5', 1203, 'ch-doc-card-725-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='16c91d6de9a957b0e729d93b5680fc395b3a50319da43e261dd217503feedee5', token_count=1203, vector_point_id='ch-doc-card-725-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-725-15', 'doc-card-725', 'sec-card-725-10', 15, 'کتاب «نظریه‌های ارتباطات جمعی» (دنیس مک‌کوایل، ۱۹۸۳)؛ کتاب «فلسفه‌ی رسانه» (فیلیپ مک‌چر، ۲۰۰۵)؛ کتاب «ساختارهای عمیق فرهنگ و ذهن» (کلیر کلاسل، ۱۹۶۳)؛ استناد مبنا: McQuail (1983) بر طبقه‌بندی پارادایم‌ها.', '5e54f2a3bf785e5acae536d3523485d9a2dc63a2b3cd9f6eed85ebd882893d57', 369, 'ch-doc-card-725-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5e54f2a3bf785e5acae536d3523485d9a2dc63a2b3cd9f6eed85ebd882893d57', token_count=369, vector_point_id='ch-doc-card-725-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-726-0', 'doc-card-726', NULL, 0, 'پارادایم کلان عملگرایی که رسانه را نه صرفاً کانال انتقال، بلکه بخشی از ساختار کلان اجتماعی می‌داند که در آن نظم، تعارض و معنا ساخته و بازتولید می‌شود؛ پرسش «رسانه چه اثری دارد» به پرسش «رسانه در این ساختار چه نقشی دارد» بدل می‌شود.', 'bef8c0efb93c0fbbd766e6d0e5cbc4b1d44de48b6142dd815e6cdf9bd7d66431', 419, 'ch-doc-card-726-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bef8c0efb93c0fbbd766e6d0e5cbc4b1d44de48b6142dd815e6cdf9bd7d66431', token_count=419, vector_point_id='ch-doc-card-726-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-726-1', 'doc-card-726', 'sec-card-726-1', 1, 'نظریه‌ها و پارادایم‌های کلان  رسانه و دموکراسی', '181308131f880cadca63e1b1bc97cc874a511582cb05dbf34bb3c27e755f19c3', 83, 'ch-doc-card-726-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='181308131f880cadca63e1b1bc97cc874a511582cb05dbf34bb3c27e755f19c3', token_count=83, vector_point_id='ch-doc-card-726-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-726-2', 'doc-card-726', 'sec-card-726-2', 2, '۱. بنیان و منطق نظری عملگرایی به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. دیویی (۱۹۲۰) در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا ساخته و بازتولید می‌شود. این چارچوب در سطح کلان تحلیل، پرسش‌های بنیادین حوزه نظریه‌ها و پارادایم‌های کلان را شکل می‌دهد.  بر اساس عملگرایی، درک رسانه بدون درک جایگاه آن در کلان‌نظام اجتماعی ممکن نیست. دیویی (۱۹۲۰) نشان داد که هر رویکرد به رسانه — چه کارکردگرا، چه انتقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند.', '292ee032c8630393d709127fe5ce585411f01c201ac2a69f54771a114b8f93e1', 1143, 'ch-doc-card-726-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='292ee032c8630393d709127fe5ce585411f01c201ac2a69f54771a114b8f93e1', token_count=1143, vector_point_id='ch-doc-card-726-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-726-3', 'doc-card-726', 'sec-card-726-2', 3, 'تقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند. این چارچوب در سطح کلان، رسانه را در بستر قدرت، اقتصاد و فرهنگ می‌خواند.  عملگرایی پارادایمی است که مرز میان «جامعه» و «رسانه» را کمرنگ می‌کند: رسانه هم بازتاب‌دهنده‌ی کلان‌نظام اجتماعی است و هم خودِ آن را می‌سازد. دیویی (۱۹۲۰) در این چارچوب، پرسش «رسانه چه اثری دارد؟» را با پرسش «رسانه در این ساختار اجتماعی چه نقشی بازی می‌کند؟» جایگزین کرد و تحلیل را به سطح کلان برد.  ۲. ساختارهای مفهومی • پارادایم (Paradigm): مجموعه‌ی پیش‌فرض‌های مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند.', 'ea750cd74b12a2bb00b18b2d7492373accec53aace847764cfb028069574f491', 1078, 'ch-doc-card-726-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ea750cd74b12a2bb00b18b2d7492373accec53aace847764cfb028069574f491', token_count=1078, vector_point_id='ch-doc-card-726-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-726-4', 'doc-card-726', 'sec-card-726-2', 4, 'ی مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند. • ساختار کلان (Macro-Structure): نظام‌های بزرگ اجتماعی — اقتصاد، سیاست، طبقات — که رسانه در آن‌ها عمل می‌کند. • بازتولید (Reproduction): فرایند تداوم و تکرار نظم اجتماعی از طریق نهادها و بازنمایی‌ها. • ایدئولوژی (Ideology): نظام باورهای «عادی‌به‌نظر»یافته که موقعیت‌های قدرت را توجیه می‌کند. • بازنمایی کلان (Macro-Representation): نشان‌دادن روابط اجتماعی بزرگ (طبقه، جنسیت، قومیت) در متن‌های رسانه‌ای. • نقد اجتماعی (Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد. • تجربه‌ی زیسته (Lived Experie', 'fd84d3f881156393e4a0336ed59621f90b434ad04d4e4d0a2d4f3f4d080f3dbe', 1103, 'ch-doc-card-726-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fd84d3f881156393e4a0336ed59621f90b434ad04d4e4d0a2d4f3f4d080f3dbe', token_count=1103, vector_point_id='ch-doc-card-726-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-726-5', 'doc-card-726', 'sec-card-726-3', 5, '• پارادایم (Paradigm): مجموعه‌ی پیش‌فرض‌های مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند. • ساختار کلان (Macro-Structure): نظام‌های بزرگ اجتماعی — اقتصاد، سیاست، طبقات — که رسانه در آن‌ها عمل می‌کند. • بازتولید (Reproduction): فرایند تداوم و تکرار نظم اجتماعی از طریق نهادها و بازنمایی‌ها. • ایدئولوژی (Ideology): نظام باورهای «عادی‌به‌نظر»یافته که موقعیت‌های قدرت را توجیه می‌کند. • بازنمایی کلان (Macro-Representation): نشان‌دادن روابط اجتماعی بزرگ (طبقه، جنسیت، قومیت) در متن‌های رسانه‌ای. • نقد اجتماعی (Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد.', '2739813c609a72e6f71aa6513ad47c37b7804f2e5db12dbc7a75dffccc10f4f9', 1123, 'ch-doc-card-726-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2739813c609a72e6f71aa6513ad47c37b7804f2e5db12dbc7a75dffccc10f4f9', token_count=1123, vector_point_id='ch-doc-card-726-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-726-6', 'doc-card-726', 'sec-card-726-3', 6, '(Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد. • تجربه‌ی زیسته (Lived Experience): بستر پدیدارشناختی که در آن فرد رسانه را در زندگی روزمره معنادار می‌کند. • میان‌دستور (Inter-discourse): پیوند میان گفتمان‌های کلان که هویت و هنجار اجتماعی را می‌سازند.', '8ac74a955304bcba921b3db4b00741a2ac1fe3c1ae0f02fc06ea47b8b6cdd050', 514, 'ch-doc-card-726-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8ac74a955304bcba921b3db4b00741a2ac1fe3c1ae0f02fc06ea47b8b6cdd050', token_count=514, vector_point_id='ch-doc-card-726-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-726-7', 'doc-card-726', 'sec-card-726-4', 7, 'nce): بستر پدیدارشناختی که در آن فرد رسانه را در زندگی روزمره معنادار می‌کند. • میان‌دستور (Inter-discourse): پیوند میان گفتمان‌های کلان که هویت و هنجار اجتماعی را می‌سازند.  ۳. نمونه‌های تحلیلی وقتی یک پژوهشگر با نگرش کارکردگرا به پوشش خبری انتخابات نگاه می‌کند، می‌پرسد «رسانه چگونه به پایداری نظام سیاسی کمک می‌کند؟» اما پژوهشگر تعارضی می‌پرسد «این پوشش، موقعیت کدام طبقه یا قوه را بازتولید می‌کند؟» — دو پارادایم، دو پرسش بنیادین از یک رویداد.  در تحلیل یک سریال تلویزنی، فمینیسم رسانه‌ای به بازنمایی زنان می‌نگرد، کوئیرتئوری به بازنمایی جنسیت‌های غیردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.', '460ad75705744228e4c3d707db3e5373a384d81ac6f628bc2bfd4db9a375acd5', 1149, 'ch-doc-card-726-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='460ad75705744228e4c3d707db3e5373a384d81ac6f628bc2bfd4db9a375acd5', token_count=1149, vector_point_id='ch-doc-card-726-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-726-8', 'doc-card-726', 'sec-card-726-4', 8, 'ردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.  پوشش خبری یک اعتصاب کارگری می‌تواند از سه پارادایم خوانده شود: کارکردگرا آن را «پایان‌بخشی به اختلال» می‌خواند، تعارضی آن را «نبرد طبقاتی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.  وقتی رسانه‌ها از «فقر» به‌عنوان «کمبود فردی» در برابر «شکاف ساختاری» گزارش می‌دهند، در عمل یک انتخاب پارادایمی (فردی/کلان) در جریان است.  در تحلیل گفتمان مهاجرت، کوئیرتئوری و فمینیسم رسانه‌ای به حضور یا غیاب زنان و افراد غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.', 'f7e94bf9a49b0191f246e901ad8f2fa47fb1bcf18d748c9040edfda84e722e39', 1078, 'ch-doc-card-726-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f7e94bf9a49b0191f246e901ad8f2fa47fb1bcf18d748c9040edfda84e722e39', token_count=1078, vector_point_id='ch-doc-card-726-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-726-9', 'doc-card-726', 'sec-card-726-4', 9, 'غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.  نظریه‌ی فلسفه‌ی رسانه پرسش می‌کند که «خودِ» تکنولوژی (بصری/گوشی/الگوریتم) چگونه پیش‌فرض‌های ما از «واقعیت» را دگرگون می‌کند — پرسشی که فراتر از تحلیل محتوا، در سطح هستی‌شناختی قرار دارد.  ۴. نقدها و چالش‌ها ۱. سطح‌آلودگی: پارادایم‌های کلان گاه «بسیار بزرگ‌تر» از داده‌های رسانه‌ای هستند و خطر تقلیل تحلیل رسانه به یک پیش‌فرض فلسفی را دارند. ۲. ناتوانی در آزمون: ادعاهای هستی‌شناختی و معرفت‌شناختی پارادایم‌ها به‌ندرت به پیش‌بینی‌های قابل‌آزمون درباره‌ی رسانه تبدیل می‌شوند. ۳. مشکل معرفت‌شناختی: مرز میان «تحلیل با پارادایم', '24a44b95f85f95e1a8b662cf475162dae081adb2d186e5ad98b47166fe35de47', 1094, 'ch-doc-card-726-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='24a44b95f85f95e1a8b662cf475162dae081adb2d186e5ad98b47166fe35de47', token_count=1094, vector_point_id='ch-doc-card-726-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-726-10', 'doc-card-726', 'sec-card-726-5', 10, 'وقتی یک پژوهشگر با نگرش کارکردگرا به پوشش خبری انتخابات نگاه می‌کند، می‌پرسد «رسانه چگونه به پایداری نظام سیاسی کمک می‌کند؟» اما پژوهشگر تعارضی می‌پرسد «این پوشش، موقعیت کدام طبقه یا قوه را بازتولید می‌کند؟» — دو پارادایم، دو پرسش بنیادین از یک رویداد.  در تحلیل یک سریال تلویزنی، فمینیسم رسانه‌ای به بازنمایی زنان می‌نگرد، کوئیرتئوری به بازنمایی جنسیت‌های غیردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.  پوشش خبری یک اعتصاب کارگری می‌تواند از سه پارادایم خوانده شود: کارکردگرا آن را «پایان‌بخشی به اختلال» می‌خواند، تعارضی آن را «نبرد طبقاتی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.', '3cca623c7b4db145a873737ee7ac459bf4fe07c5d42dc948595966eb0c0ab89c', 1185, 'ch-doc-card-726-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3cca623c7b4db145a873737ee7ac459bf4fe07c5d42dc948595966eb0c0ab89c', token_count=1185, vector_point_id='ch-doc-card-726-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-726-11', 'doc-card-726', 'sec-card-726-5', 11, 'تی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.  وقتی رسانه‌ها از «فقر» به‌عنوان «کمبود فردی» در برابر «شکاف ساختاری» گزارش می‌دهند، در عمل یک انتخاب پارادایمی (فردی/کلان) در جریان است.  در تحلیل گفتمان مهاجرت، کوئیرتئوری و فمینیسم رسانه‌ای به حضور یا غیاب زنان و افراد غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.  نظریه‌ی فلسفه‌ی رسانه پرسش می‌کند که «خودِ» تکنولوژی (بصری/گوشی/الگوریتم) چگونه پیش‌فرض‌های ما از «واقعیت» را دگرگون می‌کند — پرسشی که فراتر از تحلیل محتوا، در سطح هستی‌شناختی قرار دارد.', '3964a887a5f7f61d3707079756671ba972bed56a0753e9165c2cae980f3243e7', 1029, 'ch-doc-card-726-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3964a887a5f7f61d3707079756671ba972bed56a0753e9165c2cae980f3243e7', token_count=1029, vector_point_id='ch-doc-card-726-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-726-12', 'doc-card-726', 'sec-card-726-6', 12, '۱. سطح‌آلودگی: پارادایم‌های کلان گاه «بسیار بزرگ‌تر» از داده‌های رسانه‌ای هستند و خطر تقلیل تحلیل رسانه به یک پیش‌فرض فلسفی را دارند. ۲. ناتوانی در آزمون: ادعاهای هستی‌شناختی و معرفت‌شناختی پارادایم‌ها به‌ندرت به پیش‌بینی‌های قابل‌آزمون درباره‌ی رسانه تبدیل می‌شوند. ۳. مشکل معرفت‌شناختی: مرز میان «تحلیل با پارادایم» و «تحلیل از پیش‌فرض پارادایم» در عمل کمرنگ است و پژوهشگر اغلب پارادایم را انتخاب می‌کند، نه داده. ۴. تک‌پارادایمی‌شدن آموزش: در دوره‌های آموزشی، پارادایم‌ها به‌صورت بسته‌های بسته تدریس می‌شوند و دیالکتیک میان آن‌ها فراموش می‌شود. ۵. غرب‌مندی فلسفی: پارادایم‌های پساساختارگرایی، پدیدارشناسی و فمینیسمِ رسانه‌ای عمدتا در بافت‌های آکادمیک غربی شکل', '7f38efe2bb0ebacd2e44d05b3de77842ff65729ac3a6c5c3b9219e874ced915a', 1203, 'ch-doc-card-726-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7f38efe2bb0ebacd2e44d05b3de77842ff65729ac3a6c5c3b9219e874ced915a', token_count=1203, vector_point_id='ch-doc-card-726-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-726-13', 'doc-card-726', 'sec-card-726-7', 13, 'گرفته‌اند و کاربرد آن‌ها در بافت‌های دیگر نیازمند بومی‌سازی است. ۶. مسئله‌ی «عمل»: پارادایم‌های انتقادی در توصیف و نقد قوی‌اند، اما در «چه باید کرد؟» اغلب صامت می‌مانند. ۷. واژه‌آلودگی: استفاده‌ی زیاد از واژگان پارادایمی (بازتولید، ایدئولوژی، گفتمان) بدون تعریف روشن، تحلیل را مبهم می‌کند. ۸. خطر دوگانه‌سازی: پارادایم‌ها اغلب جهان را به دو دسته تقسیم می‌کنند (نظم/تعارض، ساختار/عاملیت) و پیچیدگی‌های میانی را نادیده می‌گیرند. ۹. نوسازی کند: دگرگونی‌های رسانه‌ای (پلتفرم، الگوریتم) سریع‌تر از بازسازی مفهومی پارادایم‌ها رخ می‌دهند. ۱۰. سیاست‌زدگی روش: در بسیاری از بافت‌ها، انتخاب یک پارادایم انتقادی، خود یک موضع سیاسی است و این «پیش‌مقوله» باید شفاف اعلام شود.', '16c91d6de9a957b0e729d93b5680fc395b3a50319da43e261dd217503feedee5', 1203, 'ch-doc-card-726-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='16c91d6de9a957b0e729d93b5680fc395b3a50319da43e261dd217503feedee5', token_count=1203, vector_point_id='ch-doc-card-726-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-726-14', 'doc-card-726', 'sec-card-726-10', 14, 'کتاب «نظریه‌های ارتباطات جمعی» (دنیس مک‌کوایل، ۱۹۸۳)؛ کتاب «فلسفه‌ی رسانه» (فیلیپ مک‌چر، ۲۰۰۵)؛ کتاب «ساختارهای عمیق فرهنگ و ذهن» (کلیر کلاسل، ۱۹۶۳)؛ استناد مبنا: McQuail (1983) بر طبقه‌بندی پارادایم‌ها.', '5e54f2a3bf785e5acae536d3523485d9a2dc63a2b3cd9f6eed85ebd882893d57', 369, 'ch-doc-card-726-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5e54f2a3bf785e5acae536d3523485d9a2dc63a2b3cd9f6eed85ebd882893d57', token_count=369, vector_point_id='ch-doc-card-726-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-727-0', 'doc-card-727', NULL, 0, 'فلسفه رسانه به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. کیتلر (۱۹۹۹) در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا ساخته و …', 'ab293334338fdce426f0edbc457c22f7384ba4f91601db100fc250803242ea92', 499, 'ch-doc-card-727-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ab293334338fdce426f0edbc457c22f7384ba4f91601db100fc250803242ea92', token_count=499, vector_point_id='ch-doc-card-727-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-727-1', 'doc-card-727', 'sec-card-727-1', 1, 'نظریه‌ها و پارادایم‌های کلان  فلسفه رسانه به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. کیتلر (۱۹۹۹) در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا ساخته و بازتولید می‌شود. این چارچوب در سطح کلان تحلیل، پرسش‌های بنیادین حوزه نظریه‌ها و پارادایم‌های کلان را شکل می‌دهد.  بر اساس فلسفه رسانه، درک رسانه بدون درک جایگاه آن در کلان‌نظام اجتماعی ممکن نیست. کیتلر (۱۹۹۹) نشان داد که هر رویکرد به رسانه — چه کارکردگرا، چه انتقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند.', 'bdf42dfda5fa6867323f04bfe698a627f221d8ae64c3b8d09852ca73e980ada5', 1170, 'ch-doc-card-727-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bdf42dfda5fa6867323f04bfe698a627f221d8ae64c3b8d09852ca73e980ada5', token_count=1170, vector_point_id='ch-doc-card-727-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-727-2', 'doc-card-727', 'sec-card-727-1', 2, 'تقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند. این چارچوب در سطح کلان، رسانه را در بستر قدرت، اقتصاد و فرهنگ می‌خواند.  فلسفه رسانه پارادایمی است که مرز میان «جامعه» و «رسانه» را کمرنگ می‌کند: رسانه هم بازتاب‌دهنده‌ی کلان‌نظام اجتماعی است و هم خودِ آن را می‌سازد. کیتلر (۱۹۹۹) در این چارچوب، پرسش «رسانه چه اثری دارد؟» را با پرسش «رسانه در این ساختار اجتماعی چه نقشی بازی می‌کند؟» جایگزین کرد و تحلیل را به سطح کلان برد.', 'e4e5b0774c42ed68feaea2e9a256bb0514020bbcd28bb1b2cff2bf7600bd760a', 823, 'ch-doc-card-727-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e4e5b0774c42ed68feaea2e9a256bb0514020bbcd28bb1b2cff2bf7600bd760a', token_count=823, vector_point_id='ch-doc-card-727-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-727-3', 'doc-card-727', 'sec-card-727-2', 3, '۱. بنیان و منطق نظری فلسفه رسانه به‌عنوان یک پارادایم کلان، پیش‌فرض‌های بنیادین درباره‌ی ماهیت جامعه، واقعیت و تغییر اجتماعی را برای تحلیل رسانه تعیین می‌کند. کیتلر (۱۹۹۹) در این پارادایم، رسانه نه صرفاَ یک «کانال انتقال» بلکه بخشی از ساختار کلان اجتماعی است که در آن نظم، تعارض یا معنا ساخته و بازتولید می‌شود. این چارچوب در سطح کلان تحلیل، پرسش‌های بنیادین حوزه نظریه‌ها و پارادایم‌های کلان را شکل می‌دهد.  بر اساس فلسفه رسانه، درک رسانه بدون درک جایگاه آن در کلان‌نظام اجتماعی ممکن نیست. کیتلر (۱۹۹۹) نشان داد که هر رویکرد به رسانه — چه کارکردگرا، چه انتقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند.', '971ff7c9d40e018ac39196074a580b0971a5eb7f906fdcc65de651ae1ae596b8', 1154, 'ch-doc-card-727-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='971ff7c9d40e018ac39196074a580b0971a5eb7f906fdcc65de651ae1ae596b8', token_count=1154, vector_point_id='ch-doc-card-727-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-727-4', 'doc-card-727', 'sec-card-727-2', 4, 'تقادی — پیش از آنکه به «رسانه» بپردازد، از یک تصویر خاص از «جامعه» شروع می‌کند. این چارچوب در سطح کلان، رسانه را در بستر قدرت، اقتصاد و فرهنگ می‌خواند.  فلسفه رسانه پارادایمی است که مرز میان «جامعه» و «رسانه» را کمرنگ می‌کند: رسانه هم بازتاب‌دهنده‌ی کلان‌نظام اجتماعی است و هم خودِ آن را می‌سازد. کیتلر (۱۹۹۹) در این چارچوب، پرسش «رسانه چه اثری دارد؟» را با پرسش «رسانه در این ساختار اجتماعی چه نقشی بازی می‌کند؟» جایگزین کرد و تحلیل را به سطح کلان برد.  ۲. ساختارهای مفهومی • پارادایم (Paradigm): مجموعه‌ی پیش‌فرض‌های مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند.', 'ce61264b49548ff18974d0add4778ba219cf0834177af39443038c4f2ea6401e', 1083, 'ch-doc-card-727-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ce61264b49548ff18974d0add4778ba219cf0834177af39443038c4f2ea6401e', token_count=1083, vector_point_id='ch-doc-card-727-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-727-5', 'doc-card-727', 'sec-card-727-2', 5, 'ی مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند. • ساختار کلان (Macro-Structure): نظام‌های بزرگ اجتماعی — اقتصاد، سیاست، طبقات — که رسانه در آن‌ها عمل می‌کند. • بازتولید (Reproduction): فرایند تداوم و تکرار نظم اجتماعی از طریق نهادها و بازنمایی‌ها. • ایدئولوژی (Ideology): نظام باورهای «عادی‌به‌نظر»یافته که موقعیت‌های قدرت را توجیه می‌کند. • بازنمایی کلان (Macro-Representation): نشان‌دادن روابط اجتماعی بزرگ (طبقه، جنسیت، قومیت) در متن‌های رسانه‌ای. • نقد اجتماعی (Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد. • تجربه‌ی زیسته (Lived Ex', 'bb649f59b70804bf6dfe31b59a9815835b51478c5f44e516375690e392f0461b', 1094, 'ch-doc-card-727-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bb649f59b70804bf6dfe31b59a9815835b51478c5f44e516375690e392f0461b', token_count=1094, vector_point_id='ch-doc-card-727-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-727-6', 'doc-card-727', 'sec-card-727-3', 6, '• پارادایم (Paradigm): مجموعه‌ی پیش‌فرض‌های مشترکی که پژوهشگر برای تفسیر پدیده انتخاب می‌کند و پرسش‌هایش را تعیین می‌کند. • ساختار کلان (Macro-Structure): نظام‌های بزرگ اجتماعی — اقتصاد، سیاست، طبقات — که رسانه در آن‌ها عمل می‌کند. • بازتولید (Reproduction): فرایند تداوم و تکرار نظم اجتماعی از طریق نهادها و بازنمایی‌ها. • ایدئولوژی (Ideology): نظام باورهای «عادی‌به‌نظر»یافته که موقعیت‌های قدرت را توجیه می‌کند. • بازنمایی کلان (Macro-Representation): نشان‌دادن روابط اجتماعی بزرگ (طبقه، جنسیت، قومیت) در متن‌های رسانه‌ای. • نقد اجتماعی (Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد.', '2739813c609a72e6f71aa6513ad47c37b7804f2e5db12dbc7a75dffccc10f4f9', 1123, 'ch-doc-card-727-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2739813c609a72e6f71aa6513ad47c37b7804f2e5db12dbc7a75dffccc10f4f9', token_count=1123, vector_point_id='ch-doc-card-727-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-727-7', 'doc-card-727', 'sec-card-727-3', 7, '(Social Critique): رویکردی که رسانه را در بستر نابرابری و قدرت تحلیل و می‌سنجد. • تجربه‌ی زیسته (Lived Experience): بستر پدیدارشناختی که در آن فرد رسانه را در زندگی روزمره معنادار می‌کند. • میان‌دستور (Inter-discourse): پیوند میان گفتمان‌های کلان که هویت و هنجار اجتماعی را می‌سازند.', '8ac74a955304bcba921b3db4b00741a2ac1fe3c1ae0f02fc06ea47b8b6cdd050', 514, 'ch-doc-card-727-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8ac74a955304bcba921b3db4b00741a2ac1fe3c1ae0f02fc06ea47b8b6cdd050', token_count=514, vector_point_id='ch-doc-card-727-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-727-8', 'doc-card-727', 'sec-card-727-4', 8, 'perience): بستر پدیدارشناختی که در آن فرد رسانه را در زندگی روزمره معنادار می‌کند. • میان‌دستور (Inter-discourse): پیوند میان گفتمان‌های کلان که هویت و هنجار اجتماعی را می‌سازند.  ۳. نمونه‌های تحلیلی وقتی یک پژوهشگر با نگرش کارکردگرا به پوشش خبری انتخابات نگاه می‌کند، می‌پرسد «رسانه چگونه به پایداری نظام سیاسی کمک می‌کند؟» اما پژوهشگر تعارضی می‌پرسد «این پوشش، موقعیت کدام طبقه یا قوه را بازتولید می‌کند؟» — دو پارادایم، دو پرسش بنیادین از یک رویداد.  در تحلیل یک سریال تلویزنی، فمینیسم رسانه‌ای به بازنمایی زنان می‌نگرد، کوئیرتئوری به بازنمایی جنسیت‌های غیردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.', '0ba7e4fadaa35e176290f778819ea32e6236d9818913ecbb4631a60755d5d066', 1158, 'ch-doc-card-727-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0ba7e4fadaa35e176290f778819ea32e6236d9818913ecbb4631a60755d5d066', token_count=1158, vector_point_id='ch-doc-card-727-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-727-9', 'doc-card-727', 'sec-card-727-4', 9, 'ردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.  پوشش خبری یک اعتصاب کارگری می‌تواند از سه پارادایم خوانده شود: کارکردگرا آن را «پایان‌بخشی به اختلال» می‌خواند، تعارضی آن را «نبرد طبقاتی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.  وقتی رسانه‌ها از «فقر» به‌عنوان «کمبود فردی» در برابر «شکاف ساختاری» گزارش می‌دهند، در عمل یک انتخاب پارادایمی (فردی/کلان) در جریان است.  در تحلیل گفتمان مهاجرت، کوئیرتئوری و فمینیسم رسانه‌ای به حضور یا غیاب زنان و افراد غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.', 'f7e94bf9a49b0191f246e901ad8f2fa47fb1bcf18d748c9040edfda84e722e39', 1078, 'ch-doc-card-727-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f7e94bf9a49b0191f246e901ad8f2fa47fb1bcf18d748c9040edfda84e722e39', token_count=1078, vector_point_id='ch-doc-card-727-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-727-10', 'doc-card-727', 'sec-card-727-4', 10, 'غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.  نظریه‌ی فلسفه‌ی رسانه پرسش می‌کند که «خودِ» تکنولوژی (بصری/گوشی/الگوریتم) چگونه پیش‌فرض‌های ما از «واقعیت» را دگرگون می‌کند — پرسشی که فراتر از تحلیل محتوا، در سطح هستی‌شناختی قرار دارد.  ۴. نقدها و چالش‌ها ۱. سطح‌آلودگی: پارادایم‌های کلان گاه «بسیار بزرگ‌تر» از داده‌های رسانه‌ای هستند و خطر تقلیل تحلیل رسانه به یک پیش‌فرض فلسفی را دارند. ۲. ناتوانی در آزمون: ادعاهای هستی‌شناختی و معرفت‌شناختی پارادایم‌ها به‌ندرت به پیش‌بینی‌های قابل‌آزمون درباره‌ی رسانه تبدیل می‌شوند. ۳. مشکل معرفت‌شناختی: مرز میان «تحلیل با پارادای', 'b87007f218b10b1d2ec802301294d61a19932733b5b6ee608e204af588dcf941', 1092, 'ch-doc-card-727-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b87007f218b10b1d2ec802301294d61a19932733b5b6ee608e204af588dcf941', token_count=1092, vector_point_id='ch-doc-card-727-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-727-11', 'doc-card-727', 'sec-card-727-5', 11, 'وقتی یک پژوهشگر با نگرش کارکردگرا به پوشش خبری انتخابات نگاه می‌کند، می‌پرسد «رسانه چگونه به پایداری نظام سیاسی کمک می‌کند؟» اما پژوهشگر تعارضی می‌پرسد «این پوشش، موقعیت کدام طبقه یا قوه را بازتولید می‌کند؟» — دو پارادایم، دو پرسش بنیادین از یک رویداد.  در تحلیل یک سریال تلویزنی، فمینیسم رسانه‌ای به بازنمایی زنان می‌نگرد، کوئیرتئوری به بازنمایی جنسیت‌های غیردوگانه، و پساساختارگرایی به «نحوه‌ی» شکل‌گیری معنای «مرد» و «زن» در آن سریال.  پوشش خبری یک اعتصاب کارگری می‌تواند از سه پارادایم خوانده شود: کارکردگرا آن را «پایان‌بخشی به اختلال» می‌خواند، تعارضی آن را «نبرد طبقاتی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.', '3cca623c7b4db145a873737ee7ac459bf4fe07c5d42dc948595966eb0c0ab89c', 1185, 'ch-doc-card-727-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3cca623c7b4db145a873737ee7ac459bf4fe07c5d42dc948595966eb0c0ab89c', token_count=1185, vector_point_id='ch-doc-card-727-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-727-12', 'doc-card-727', 'sec-card-727-5', 12, 'تی» می‌خواند و پدیدارشناختی از «تجربه‌ی زیسته‌ی» کارگران و رسانه‌گران می‌پرسد.  وقتی رسانه‌ها از «فقر» به‌عنوان «کمبود فردی» در برابر «شکاف ساختاری» گزارش می‌دهند، در عمل یک انتخاب پارادایمی (فردی/کلان) در جریان است.  در تحلیل گفتمان مهاجرت، کوئیرتئوری و فمینیسم رسانه‌ای به حضور یا غیاب زنان و افراد غیرهتروسکسوال در بازنمایی‌ها نگاه می‌کنند؛ این «غیاب» خود یک داده‌ی کلان است.  نظریه‌ی فلسفه‌ی رسانه پرسش می‌کند که «خودِ» تکنولوژی (بصری/گوشی/الگوریتم) چگونه پیش‌فرض‌های ما از «واقعیت» را دگرگون می‌کند — پرسشی که فراتر از تحلیل محتوا، در سطح هستی‌شناختی قرار دارد.', '3964a887a5f7f61d3707079756671ba972bed56a0753e9165c2cae980f3243e7', 1029, 'ch-doc-card-727-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3964a887a5f7f61d3707079756671ba972bed56a0753e9165c2cae980f3243e7', token_count=1029, vector_point_id='ch-doc-card-727-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-727-13', 'doc-card-727', 'sec-card-727-6', 13, '۱. سطح‌آلودگی: پارادایم‌های کلان گاه «بسیار بزرگ‌تر» از داده‌های رسانه‌ای هستند و خطر تقلیل تحلیل رسانه به یک پیش‌فرض فلسفی را دارند. ۲. ناتوانی در آزمون: ادعاهای هستی‌شناختی و معرفت‌شناختی پارادایم‌ها به‌ندرت به پیش‌بینی‌های قابل‌آزمون درباره‌ی رسانه تبدیل می‌شوند. ۳. مشکل معرفت‌شناختی: مرز میان «تحلیل با پارادایم» و «تحلیل از پیش‌فرض پارادایم» در عمل کمرنگ است و پژوهشگر اغلب پارادایم را انتخاب می‌کند، نه داده. ۴. تک‌پارادایمی‌شدن آموزش: در دوره‌های آموزشی، پارادایم‌ها به‌صورت بسته‌های بسته تدریس می‌شوند و دیالکتیک میان آن‌ها فراموش می‌شود. ۵. غرب‌مندی فلسفی: پارادایم‌های پساساختارگرایی، پدیدارشناسی و فمینیسمِ رسانه‌ای عمدتا در بافت‌های آکادمیک غربی شکل', '7f38efe2bb0ebacd2e44d05b3de77842ff65729ac3a6c5c3b9219e874ced915a', 1203, 'ch-doc-card-727-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7f38efe2bb0ebacd2e44d05b3de77842ff65729ac3a6c5c3b9219e874ced915a', token_count=1203, vector_point_id='ch-doc-card-727-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-727-14', 'doc-card-727', 'sec-card-727-7', 14, 'گرفته‌اند و کاربرد آن‌ها در بافت‌های دیگر نیازمند بومی‌سازی است. ۶. مسئله‌ی «عمل»: پارادایم‌های انتقادی در توصیف و نقد قوی‌اند، اما در «چه باید کرد؟» اغلب صامت می‌مانند. ۷. واژه‌آلودگی: استفاده‌ی زیاد از واژگان پارادایمی (بازتولید، ایدئولوژی، گفتمان) بدون تعریف روشن، تحلیل را مبهم می‌کند. ۸. خطر دوگانه‌سازی: پارادایم‌ها اغلب جهان را به دو دسته تقسیم می‌کنند (نظم/تعارض، ساختار/عاملیت) و پیچیدگی‌های میانی را نادیده می‌گیرند. ۹. نوسازی کند: دگرگونی‌های رسانه‌ای (پلتفرم، الگوریتم) سریع‌تر از بازسازی مفهومی پارادایم‌ها رخ می‌دهند. ۱۰. سیاست‌زدگی روش: در بسیاری از بافت‌ها، انتخاب یک پارادایم انتقادی، خود یک موضع سیاسی است و این «پیش‌مقوله» باید شفاف اعلام شود.', '16c91d6de9a957b0e729d93b5680fc395b3a50319da43e261dd217503feedee5', 1203, 'ch-doc-card-727-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='16c91d6de9a957b0e729d93b5680fc395b3a50319da43e261dd217503feedee5', token_count=1203, vector_point_id='ch-doc-card-727-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-727-15', 'doc-card-727', 'sec-card-727-10', 15, 'کتاب «نظریه‌های ارتباطات جمعی» (دنیس مک‌کوایل، ۱۹۸۳)؛ کتاب «فلسفه‌ی رسانه» (فیلیپ مک‌چر، ۲۰۰۵)؛ کتاب «ساختارهای عمیق فرهنگ و ذهن» (کلیر کلاسل، ۱۹۶۳)؛ استناد مبنا: McQuail (1983) بر طبقه‌بندی پارادایم‌ها.', '5e54f2a3bf785e5acae536d3523485d9a2dc63a2b3cd9f6eed85ebd882893d57', 369, 'ch-doc-card-727-15', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5e54f2a3bf785e5acae536d3523485d9a2dc63a2b3cd9f6eed85ebd882893d57', token_count=369, vector_point_id='ch-doc-card-727-15', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-728-0', 'doc-card-728', NULL, 0, 'هنگامی که سازمان‌ها با شوک‌ها، بحران‌ها و شرایط مبهم و نامطمئن روبه‌رو می‌شوند، اعضای سازمان از طریق کنش ارتباطی و گفتگو، روایتی باورپذیر خلق می‌کنند تا به موقعیت معنا ببخشند. در این فرآیند، «باورپذیری» (Plausibility) روایت کارکردی بسیار حیاتی‌تر از «دقت عینی» دارد.', '3e033289b0b9a2e202a22d0e655d5b543e66f43824d4dd8d4ae180b5401573b6', 483, 'ch-doc-card-728-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3e033289b0b9a2e202a22d0e655d5b543e66f43824d4dd8d4ae180b5401573b6', token_count=483, vector_point_id='ch-doc-card-728-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-728-1', 'doc-card-728', 'sec-card-728-1', 1, 'ارتباطات سازمانی / مدیریت بحران و روایت‌گری  هنگامی که سازمان‌ها با شوک‌ها، بحران‌ها و شرایط مبهم و نامطمئن روبه‌رو می‌شوند، اعضای سازمان از طریق کنش ارتباطی و گفتگو، روایتی باورپذیر خلق می‌کنند تا به موقعیت معنا ببخشند. در این فرآیند، «باورپذیری» (Plausibility) روایت کارکردی بسیار حیاتی‌تر از «دقت عینی» دارد.', '103ac7d0589aa41f754d5a96b4b0fc665e7d933dc7ff064338b6b565c42ba87f', 565, 'ch-doc-card-728-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='103ac7d0589aa41f754d5a96b4b0fc665e7d933dc7ff064338b6b565c42ba87f', token_count=565, vector_point_id='ch-doc-card-728-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-728-2', 'doc-card-728', 'sec-card-728-2', 2, '۱. بنیان و منطق نظری حس‌سازی سازمانی روابط عمومی را فرایند مدیریت ارتباط دوسویه‌ی سازمان با عموم‌هایش می‌داند: شناسایی عموم‌ها، درک انتظارهای آن‌ها، تنظیم پیام و پایش بازخورد. کارل وایک (۱۹۹۵) در این چارچوب، روابط عمومی را نه صرفاَ «تبلیغ» بلکه «مدیریت اعتبار» تعریف کرد؛ اعتباری که سرمایه‌ی بلندمدت سازمان است.  بر اساس حس‌سازی سازمانی، هدف روابط عمومی، «افزودن اعتبار» به سازمان ازطریق شفافیت، پاسخگویی و اعتمادسازی است. کارل وایک (۱۹۹۵) نشان داد که در بحران، سازمانی که اعتبار دارد، «بانک اعتباری»‌ای دارد که می‌تواند به آن تکیه کند؛ این چارچوب در سطح میانی تحلیل، روابط عمومی را به «مدیریت ریسک سازمانی» ارتقا می‌دهد.', '14ec0aa2e935081e5c564ac290fde99073fc486cafdd69f38c87e3686fb9d0fe', 1129, 'ch-doc-card-728-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='14ec0aa2e935081e5c564ac290fde99073fc486cafdd69f38c87e3686fb9d0fe', token_count=1129, vector_point_id='ch-doc-card-728-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-728-3', 'doc-card-728', 'sec-card-728-2', 3, 'رچوب در سطح میانی تحلیل، روابط عمومی را به «مدیریت ریسک سازمانی» ارتقا می‌دهد.  حس‌سازی سازمانی را می‌توان پاسخی به شکاف میان «ارتباطات یک‌سویه» (تبلیغات، اطلاع‌رسانی) و «گفت‌وگوی واقعی» دانست: در عصر شبکه‌ها، عموم‌ها دیگر فقط شنونده نیستند، بلکه سخنران و پایشگر‌اند. کارل وایک (۱۹۹۵) در این چارچوب، دوسویه‌ی بودن، شفافیت و هماهنگی پیام را اصول بنیادین روابط عمومی معاصر قرار داد.  ۲. ساختارهای مفهومی • عموم (Publics): گروه‌هایی که با یک مسئله‌ی مشترک با سازمان درگیرند و بر تصمیمات آن اثر می‌گذارند. • اعتبار (Credibility): ادراک صداقت، شفافیت و امانتداری سازمان که در طول زمان ساخته می‌شود.', '865c816d4358421194b75882b68b28937317b180c66a6f3d7a9861d7d136a796', 1078, 'ch-doc-card-728-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='865c816d4358421194b75882b68b28937317b180c66a6f3d7a9861d7d136a796', token_count=1078, vector_point_id='ch-doc-card-728-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-728-4', 'doc-card-728', 'sec-card-728-2', 4, 'edibility): ادراک صداقت، شفافیت و امانتداری سازمان که در طول زمان ساخته می‌شود. • مدیریت بحران (Crisis Management): مجموعه‌ی اقدامات پیشگیرانه، واکنشی و بازیابی پس از بحران سازمانی. • گفت‌وگوی دوسویه (Two-Way Dialogue): ارتباطی که در آن سازمان نه فقط پیام می‌فرستد، بلکه گوش می‌دهد و پاسخ می‌دهد. • شهرت سازمانی (Organizational Reputation): تصویر کلانی که عموم‌ها در ذهن خود از سازمان دارند و بر رفتار آن‌ها اثر می‌گذارد. • پایش و شنود (Monitoring & Listening): رصد مستمر صحبت‌های عموم‌ها در رسانه‌ها و شبکه‌های اجتماعی. • پیام‌های هم‌خوان (Consistent Messaging): هماهنگی پیام سازمان در تمام کانال‌ها و تمام موقعیت‌ها.', 'de8e599b3c69c86ff416ecdb4908cc6b96058652cf549c3c74a44f58c83c6ba1', 1123, 'ch-doc-card-728-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='de8e599b3c69c86ff416ecdb4908cc6b96058652cf549c3c74a44f58c83c6ba1', token_count=1123, vector_point_id='ch-doc-card-728-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-728-5', 'doc-card-728', 'sec-card-728-2', 5, '(Consistent Messaging): هماهنگی پیام سازمان در تمام کانال‌ها و تمام موقعیت‌ها. • پاسخگویی (Accountability): تعهد سازمان به توضیح علل تصمیمات و پذیرش', '99a0e47e69288315b265d3653bbd3eacc1560e995557ed40267cd4bcbbf97d5b', 269, 'ch-doc-card-728-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='99a0e47e69288315b265d3653bbd3eacc1560e995557ed40267cd4bcbbf97d5b', token_count=269, vector_point_id='ch-doc-card-728-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-728-6', 'doc-card-728', 'sec-card-728-3', 6, '۷ ویژگی حس‌سازی (گذشته‌نگر بودن، مبتنی بر هویت، اجتماعی، پیوسته، برساخت محیط، مبتنی بر سرنخ‌های استخراج‌شده، معطوف به باورپذیری به جای دقت)، فروریزی معنا (Cosmology Episode).', 'd0333fddbd730a5e0dcced332e4cd591253832289eea4ece9758f7ffad4cda06', 316, 'ch-doc-card-728-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d0333fddbd730a5e0dcced332e4cd591253832289eea4ece9758f7ffad4cda06', token_count=316, vector_point_id='ch-doc-card-728-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-728-7', 'doc-card-728', 'sec-card-728-4', 7, 'مسئولیت در برابر عموم‌ها.  ۳. نمونه‌های تحلیلی وقتی یک شرکت پس از رسوایی محیطی، به‌جای انکار، «پذیرش مسئولیت + طرح اصلاح + گزارش‌دهی شفاف» را اعلام می‌کند، در عمل از «بانک اعتباری» استفاده می‌کند: عمومی، بر اساس سوابق شفافیت آن شرکت، به پیامش اعتماد می‌کند.  در بحران یک پرونده‌ی حقوقی، شرکتی که «گفت‌وگوی دوسویه» را اجرا می‌کند (پرسش‌های رسانه و عموم را می‌شنود و پاسخ می‌دهد)، در مقایسه با شرکتی که فقط «بیانیه‌ی رسمی» منتشر می‌کند، اعتماد بیشتری حفظ می‌کند.  پایش شبکه‌های اجتماعی نشان می‌دهد که یک «شکایت کوچک» از یک محصول، اگر بی‌پاسخ بماند، می‌تواند به «بحران شهرت» تبدیل شود؛ در مقابل، پاسخ سریع و صادقانه، «بانک اعتبار» را پر می‌کند.', '8843cf937b3dc6411273ab0e792455d17667ebf2c37be2c1f6d2bc54ec27c29b', 1165, 'ch-doc-card-728-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8843cf937b3dc6411273ab0e792455d17667ebf2c37be2c1f6d2bc54ec27c29b', token_count=1165, vector_point_id='ch-doc-card-728-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-728-8', 'doc-card-728', 'sec-card-728-4', 8, 'ان شهرت» تبدیل شود؛ در مقابل، پاسخ سریع و صادقانه، «بانک اعتبار» را پر می‌کند.  وقتی یک برند ورزشی از یک چهره‌ی ورزشی «گسل» می‌کند، انتخاب «چه کسی می‌گوید، چه می‌گوید، از چه کانالی» — همان «هماهنگی پیام» — تعیین می‌کند که پیام، «مسئولیت‌پذیری» خوانده شود یا «پنهان‌کاری».  در بحران یک شرکت هواپیمایی، شرکتی که «پایش» را جدی می‌گیرد، می‌داند عمومی «چه نگرانی‌ای» دارد و پاسخش را دقیقاً به همان نگرانی می‌سپارد؛ شرکتی که «پایش» نمی‌کند، به «سوئال» عمومی پاسخ «غلط» می‌دهد و بحران را عمیق‌تر می‌کند.  «پاسخگویی» در عمل به این معناست که سازمان «چرا این تصمیم را گرفت» را توضیح می‌دهد، حتی وقتی توضیح، محبوب نیست؛ این «شفافیت نامطلوب» گاهی ارزشمندتر از «پاسخ محبوب اما مبهم» است.  ۴.', '6facbaa61ed0454d563230f98a5a0bfd9938bf02b1bb02742ab8fb864f7069c8', 1232, 'ch-doc-card-728-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6facbaa61ed0454d563230f98a5a0bfd9938bf02b1bb02742ab8fb864f7069c8', token_count=1232, vector_point_id='ch-doc-card-728-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-728-9', 'doc-card-728', 'sec-card-728-4', 9, 'بوب نیست؛ این «شفافیت نامطلوب» گاهی ارزشمندتر از «پاسخ محبوب اما مبهم» است.  ۴. نقدها و چالش‌ها ۱. مرز میان «روابط عمومی» و «تبلیغات»: در عمل، مرز این دو اغلب کمرنگ است و بسیاری از اقدامات «روابط عمومی»، ماهیت تبلیغاتی دارند؛ این چارچوب باید بتواند «ارزش افزوده» دوگانگی را توضیح دهد. ۲. مسئله‌ی «اعتبار» و سنجش آن: اعتبار یک مفهوم ادراکی است و سنجش دقیق آن (فراتر از نظرسنجی‌های کلی) دشوار است؛ شاخص‌های اعتبار اغلب بازتاب «خوداوری» هستند، نه «واقعیت». ۳. غفلت از «عمومی‌های ضعیف»: چارچوب‌های روابط عمومی عمدتا بر «عمومی‌های قدرتمند» (رسانه‌ها، مقامات) تمرکز دارند و صدای «عمومی‌های', '6fdcf65843b65ecfbc49715f8096acb12883d0ef94d52891bc3657d056915b89', 1060, 'ch-doc-card-728-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6fdcf65843b65ecfbc49715f8096acb12883d0ef94d52891bc3657d056915b89', token_count=1060, vector_point_id='ch-doc-card-728-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-728-10', 'doc-card-728', 'sec-card-728-5', 10, 'مدیریت ارتباطی اتاق خبر در لحظات وقوع بحران‌های پیش‌بینی‌نشده، یا رفتار تیم‌های بحران در روابط عمومی هنگام افشای رسوایی‌های شرکتی.', '993438686ae2d0e0ec14444e64669b9a25d0684b86e2d74b05173c073d096065', 236, 'ch-doc-card-728-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='993438686ae2d0e0ec14444e64669b9a25d0684b86e2d74b05173c073d096065', token_count=236, vector_point_id='ch-doc-card-728-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-728-11', 'doc-card-728', 'sec-card-728-6', 11, 'تمرکز غلیظ بر پردازش‌های زبانی و روایی و کم‌توجهی نسبی به نابرابری‌های ساختاری قدرت و منابع مادی که تعیین می‌کنند روایت چه کسی دست بالا را پیدا می‌کند.', '809b9f25142b560e2b392080c96a029b3c497f08140d2b62912bffea5b902bcb', 274, 'ch-doc-card-728-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='809b9f25142b560e2b392080c96a029b3c497f08140d2b62912bffea5b902bcb', token_count=274, vector_point_id='ch-doc-card-728-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-728-12', 'doc-card-728', 'sec-card-728-10', 12, 'کتاب مشهور «حس‌سازی در سازمان‌ها» (کارل وایک، ۱۹۹۵).', '8f79ec10ce16f11887ebca96656c7df058280fb20070a506b9dcda8437027a70', 94, 'ch-doc-card-728-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8f79ec10ce16f11887ebca96656c7df058280fb20070a506b9dcda8437027a70', token_count=94, vector_point_id='ch-doc-card-728-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-729-0', 'doc-card-729', NULL, 0, 'تئوری‌های عام مدیریت استراتژیک برای محیط‌های خطی پاسخگوی ویژگی‌های صنایع رسانه‌ای نیستند. رسانه‌ها محصولاتی با ماهیت نمادین، بازارهای دومرحله‌ای و تحولات غیرخطی تکنولوژیک دارند و بقای آن‌ها نیازمند مدیریت هم‌زمان خلاقیت فرهنگی و انضباط تجاری است.', '55aa7a3a96b6e731b0433b2e759d23112070e4110a0431939a75114ea759c6cf', 447, 'ch-doc-card-729-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='55aa7a3a96b6e731b0433b2e759d23112070e4110a0431939a75114ea759c6cf', token_count=447, vector_point_id='ch-doc-card-729-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-729-1', 'doc-card-729', 'sec-card-729-1', 1, 'مدیریت رسانه / اقتصاد استراتژیک و رهبری خلاق  تئوری‌های عام مدیریت استراتژیک برای محیط‌های خطی پاسخگوی ویژگی‌های صنایع رسانه‌ای نیستند. رسانه‌ها محصولاتی با ماهیت نمادین، بازارهای دومرحله‌ای و تحولات غیرخطی تکنولوژیک دارند و بقای آن‌ها نیازمند مدیریت هم‌زمان خلاقیت فرهنگی و انضباط تجاری است.', 'f750ce00b8f268118e83884a23d5dcd73965f465b46beb6da00fbc7dc1db68cd', 530, 'ch-doc-card-729-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f750ce00b8f268118e83884a23d5dcd73965f465b46beb6da00fbc7dc1db68cd', token_count=530, vector_point_id='ch-doc-card-729-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-729-2', 'doc-card-729', 'sec-card-729-2', 2, '۱. جایگاه نظری: چرا مدیریت عام برای رسانه کافی نیست؟ کتاب «مدیریت استراتژیک در رسانه: از تئوری تا عمل» (لوسی کونگ، ۲۰۰۸؛ ویرایش دوم ۲۰۱۷) برای پاسخ به خلأ بنیادینی نوشته شده است: ابزارهای «عام» مدیریت استراتژیک (پنج نیروی پورتر، SWOT، دیدگاه مبتنی بر منابع) بر مبنای بازارهای صنعتی خطی و نسبتا پایدار ساخته شده‌اند، در حالی که صنعت رسانه محصولاتی «نمادین» (ارزش پیش‌از‌فروش نامشخص)، بازارهای «دومرحله‌ای» (تولید-مصرف و مخاطب-تبلیغ‌دهنده)، تحولات «غیرخطی» تکنولوژیک (گذار از فیلم به دیجیتال در چند دهه) و «تنظیمات قوی» بیرونی دارد.  ۲.', '0df69eb6e7e55f5c76e19b1e390dc9058f74b67b1d0fa1a060c7872c7e873ca6', 970, 'ch-doc-card-729-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0df69eb6e7e55f5c76e19b1e390dc9058f74b67b1d0fa1a060c7872c7e873ca6', token_count=970, vector_point_id='ch-doc-card-729-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-729-3', 'doc-card-729', 'sec-card-729-2', 3, 'تکنولوژیک (گذار از فیلم به دیجیتال در چند دهه) و «تنظیمات قوی» بیرونی دارد.  ۲. مفاهیم محوری چارچوب مهم‌ترین مفهوم این چارچوب «دوسوتوانی استراتژیک» (Strategic Ambidexterity) است: توانایی سازمان در «بهره‌برداری» هم‌زمان از کسب‌وکار جاری', '93aab5ddf8ac3855ee9e01501e4caffb7f7b7003493df7f7e3ecdc8bfa382188', 427, 'ch-doc-card-729-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='93aab5ddf8ac3855ee9e01501e4caffb7f7b7003493df7f7e3ecdc8bfa382188', token_count=427, vector_point_id='ch-doc-card-729-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-729-4', 'doc-card-729', 'sec-card-729-3', 4, 'معمای دوسوتوانی (Ambidexterity - بهره‌برداری از کسب‌وکار جاری در کنار اکتشاف مدل‌های نوین)، اختلال دیجیتال (Digital Disruption)، نقشه‌های شناختی مدیران رسانه، اکوسیستم پلتفرمی.', '936cec5d3d4a75762bd2a8b8db6670c9444935be13354208aced3ce1056279dd', 320, 'ch-doc-card-729-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='936cec5d3d4a75762bd2a8b8db6670c9444935be13354208aced3ce1056279dd', token_count=320, vector_point_id='ch-doc-card-729-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-729-5', 'doc-card-729', 'sec-card-729-4', 5, 'و «اکتشاف» مدل‌های نوین. کونگ نشان می‌دهد بسیاری سازمان‌های رسانه‌ای سنتی نه به کمبود منابع، بلکه به ناتوانی در حفظ هم‌زمان هر دو شکست خورده‌اند: فرهنگ «بهره‌برداری» (دلاین، بودجه‌ی ثابت، متریک‌های فوری) مانع فرهنگ «اکتشاف» (آزمایش، تحمل شکست، سرمایه‌گذاری بلندمدت) می‌شود.  سایر مفاهیم محوری: «اختلال دیجیتال» (Digital Disruption) و منطق «نوآوری مختل‌کننده» (کریستنسن) در بافتار رسانه، نقش «نقشه‌های ذهنی مدیران» (Mental Models) در تفسیر گذار دیجیتال، و «اکوسیستم‌های پلتفرمی» به‌مثابه‌ی ساختار تازه‌ی زنجیره‌ی ارزش.  ۳.', 'f9e9a814ba6c9fa7e6a73192da021e5fa669f7fcf1cf8a59ec41df785a06a8d6', 947, 'ch-doc-card-729-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f9e9a814ba6c9fa7e6a73192da021e5fa669f7fcf1cf8a59ec41df785a06a8d6', token_count=947, vector_point_id='ch-doc-card-729-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-729-6', 'doc-card-729', 'sec-card-729-4', 6, 'ر دیجیتال، و «اکوسیستم‌های پلتفرمی» به‌مثابه‌ی ساختار تازه‌ی زنجیره‌ی ارزش.  ۳. کاربردهای عملی: روزنامه‌ها در گذار مشهورترین کاربرد این چارچوب، گذار روزنامه‌های سنتی به اشتراک دیجیتال است: نیویورک تایمز (دیوار پرداختی، ۲۰۱۱)، گاردین (مدل حمایتی) و', '060c12be49132b2a82cdf0162ba333d97fe7bbbad412931a798ec8ff8d4e68e5', 449, 'ch-doc-card-729-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='060c12be49132b2a82cdf0162ba333d97fe7bbbad412931a798ec8ff8d4e68e5', token_count=449, vector_point_id='ch-doc-card-729-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-729-7', 'doc-card-729', 'sec-card-729-5', 7, 'استراتژی‌های روزنامه‌های مطرح جهانی مانند نیویورک تایمز در گذار از مدل چاپ کاغذی به اشتراک دیجیتال، پادکست و بازی‌های آنلاین.', 'bb859b61e9786e4aee394c680a29ec62561a39bfc70d1f4022b5f089ec6cba58', 227, 'ch-doc-card-729-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bb859b61e9786e4aee394c680a29ec62561a39bfc70d1f4022b5f089ec6cba58', token_count=227, vector_point_id='ch-doc-card-729-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-729-8', 'doc-card-729', 'sec-card-729-6', 8, 'شتاب فزاینده تغییرات الگوریتمی در پلتفرم‌های غول‌پیکر گاهی چرخه‌های سنتی برنامه‌ریزی استراتژیک را ناممکن ساخته و سازمان‌ها را وادار به واکنش‌های لحظه‌ای می‌کند.', 'e3917ad9e31056e4ca2eeb1e93b8e53151aa37723008308b82dd32b309486123', 290, 'ch-doc-card-729-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e3917ad9e31056e4ca2eeb1e93b8e53151aa37723008308b82dd32b309486123', token_count=290, vector_point_id='ch-doc-card-729-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-729-9', 'doc-card-729', 'sec-card-729-10', 9, 'کتاب مرجع «مدیریت استراتژیک در رسانه: از تئوری تا عمل» (لوسی کونگ، ویرایش دوم ۲۰۱۷).', '3050fa5681d4ed441b2c78d6a5215800e9ac0814d16ae498fee76f494d6adbef', 152, 'ch-doc-card-729-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3050fa5681d4ed441b2c78d6a5215800e9ac0814d16ae498fee76f494d6adbef', token_count=152, vector_point_id='ch-doc-card-729-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-73-0', 'doc-card-73', NULL, 0, 'هر روش پژوهش تصویری جزئی و محدود از واقعیت می‌دهد، پس با ترکیب منابع داده، روش‌ها، پژوهشگران یا نظریه‌ها می‌توان نقاط ضعف هر کدام را جبران کرد. اگر یافته‌های مستقل به یک نتیجه برسند، اعتماد به آن نتیجه بیشتر می‌شود. دنزین چهار نوع سه‌سوسازی را تمایز داد.', '498c2088a76371cf21df37a9cfeb1ee5d8a7d3bffa15484cca1cd12d797ec38f', 461, 'ch-doc-card-73-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='498c2088a76371cf21df37a9cfeb1ee5d8a7d3bffa15484cca1cd12d797ec38f', token_count=461, vector_point_id='ch-doc-card-73-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-73-1', 'doc-card-73', 'sec-card-73-1', 1, 'روش‌شناسی / اعتبارسنجی پژوهش  هر روش پژوهش تصویری جزئی و محدود از واقعیت می‌دهد، پس با ترکیب منابع داده، روش‌ها، پژوهشگران یا نظریه‌ها می‌توان نقاط ضعف هر کدام را جبران کرد. اگر یافته‌های مستقل به یک نتیجه برسند، اعتماد به آن نتیجه بیشتر می‌شود. دنزین چهار نوع سه‌سوسازی را تمایز داد.', '792d4a6f08aafdf3ddc5576a9cfd873c0edb93fe61726a9c249a9a18611ef1d9', 516, 'ch-doc-card-73-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='792d4a6f08aafdf3ddc5576a9cfd873c0edb93fe61726a9c249a9a18611ef1d9', token_count=516, vector_point_id='ch-doc-card-73-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-73-2', 'doc-card-73', 'sec-card-73-2', 2, '۱. بنیان و منطق نظری سه‌سوسازی «روش» را «بافت» «معنا» می‌داند: نه «ابزار» «تحلیل» بلکه «بافت» «تحلیل». نورمن کی. دنزین (۱۹۷۸) در این چارچوب، «روش» را «بافت» «معرفت» تعریف کرد: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش».  بر اساس سه‌سوسازی، «روش» «دیالکتیک» «نظریه» و «داده» است: «نظریه»، «بافت» «تحلیل» است و «داده»، «بافت» «نظریه». نورمن کی. دنزین (۱۹۷۸) در این چارچوب، «روش» را «بافت» «اعتماد» تعریف کرد: «اعتماد» در «روش» «ساخته» می‌شود، نه در «نتیجه».  سه‌سوسازی را می‌توان پاسخی به شکاف میان «روش» «کمّی» (تعمیم) و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش». نورمن کی.', 'a706dba30985ae21c1e6948a317ef8c578c777c3a1eed723d4b4decdb881f57d', 1114, 'ch-doc-card-73-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a706dba30985ae21c1e6948a317ef8c578c777c3a1eed723d4b4decdb881f57d', token_count=1114, vector_point_id='ch-doc-card-73-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-73-3', 'doc-card-73', 'sec-card-73-2', 3, 'کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش». نورمن کی. دنزین (۱۹۷۸) در این چارچوب، «روش» را «بافت» «بازی» تعریف کرد: «تحلیل»، «بازی» با «داده» است.  ۲. ساختارهای مفهومی • روش کمّی (Quantitative Method): «اندازه‌گیری» و «تعمیم»: «داده» «عددی» و «تحلیل» «آمار». • روش کیفی (Qualitative Method): «فهم» و «عمق»: «داده» «کیفی» و «تحلیل» «تفسیر». • روش ترکیبی (Mixed Methods): «ترکیب» «کمّی» و «کیفی»: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • پیمایش (Survey): «اندازه‌گیری» «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته». • تحلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن».', '7c5210121d12337ec2df919734e558b23086cee9bd8dd09bcd19f9a8972e673d', 1152, 'ch-doc-card-73-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7c5210121d12337ec2df919734e558b23086cee9bd8dd09bcd19f9a8972e673d', token_count=1152, vector_point_id='ch-doc-card-73-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-73-4', 'doc-card-73', 'sec-card-73-2', 4, 'حلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن». • نظریه داده بنیادین (Grounded Theory): «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود. • قوم‌نگاری (Ethnography): «فهم» «بافت»: «حضور» در «بافت» و «فهم» «معنا»', 'c2e7708c67dc42c479e96901e5b1ada3bd28cfbb55f8263a5eacdf1bbbc367e1', 454, 'ch-doc-card-73-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c2e7708c67dc42c479e96901e5b1ada3bd28cfbb55f8263a5eacdf1bbbc367e1', token_count=454, vector_point_id='ch-doc-card-73-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-73-5', 'doc-card-73', 'sec-card-73-3', 5, 'سه‌سوسازی داده‌ها؛ سه‌سوسازی روش‌ها؛ سه‌سوسازی پژوهشگران؛ سه‌سوسازی نظریه‌ها؛ اعتبار؛ تکمیل‌کنندگی یافته‌ها.', '813f7cc2a3d3a792ae469c9de9cc9176672b77346e62405e663410ec9f381d42', 196, 'ch-doc-card-73-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='813f7cc2a3d3a792ae469c9de9cc9176672b77346e62405e663410ec9f381d42', token_count=196, vector_point_id='ch-doc-card-73-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-73-6', 'doc-card-73', 'sec-card-73-4', 6, 'در «بافت». • اعتبار و قابلیت اطمینان (Validity and Reliability): «اعتماد» در «روش»: «اعتبار» و «قابلیت اطمینان»، «بافت» «اعتماد» است.  ۳. نمونه‌های تحلیلی «روش کمّی» در عمل: «نظرسنجی» از «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته»: «تعمیم» «نتیجه» به «دسته».  «روش کیفی» در عمل: «مصاحبه» «عمیق» از «دسته‌ی» «کوچک»: «فهم» «معنا» در «بافت» «مصاحبه»: «عمق» «تحلیل».  «پیمایش» در عمل: «پیمایش» «نظر» «مخاطب» از «محتوای» «رسانه»: «سؤال» و «پاسخ» در «بافت» «دسته»: «تعمیم» «نتیجه».  «تحلیل محتوا» در عمل: «تحلیل» «متن» «خبر» از «چارچوب» و «واژه»: «کد» و «فراوانی» در «بافت» «متن»: «تحلیل» «ساختار» «متن».', '0190b6ad1087bf63ba5678119ac6432bdacee4f2d7abf55b92b757ee65f149aa', 1098, 'ch-doc-card-73-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0190b6ad1087bf63ba5678119ac6432bdacee4f2d7abf55b92b757ee65f149aa', token_count=1098, vector_point_id='ch-doc-card-73-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-73-7', 'doc-card-73', 'sec-card-73-4', 7, 'ز «چارچوب» و «واژه»: «کد» و «فراوانی» در «بافت» «متن»: «تحلیل» «ساختار» «متن».  «نظریه داده بنیادین» در عمل: «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود: «تحلیل»، «بازی» با «داده» است.  «قوم‌نگاری» در عمل: «حضور» در «بافت» «مخاطب»: «فهم» «معنا» در «بافت» «مخاطب»: «عمق» «تحلیل» در «بافت» «بومی».  ۴. نقدها و چالش‌ها ۱. «کمّی» و «کیفی» «دیالکتیک»‌اند: «کمّی» «تعمیم» دارد اما «عمق» ندارد و «کیفی» «عمق» دارد اما «تعمیم» ندارد: «روش» «ترکیبی»، «بافت» «دیالکتیک» است. ۲. «روش» و «نظریه» در هم تنیده‌اند: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش»: «روش» «خنثی» وجود ندارد. ۳.', '17842b057ad0f8425860f241c60fd05a93e47f100d43e207106133f550b126e1', 1076, 'ch-doc-card-73-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='17842b057ad0f8425860f241c60fd05a93e47f100d43e207106133f550b126e1', token_count=1076, vector_point_id='ch-doc-card-73-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-73-8', 'doc-card-73', 'sec-card-73-4', 8, '«روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش»: «روش» «خنثی» وجود ندارد. ۳. «اعتبار» در «روش» «کیفی» «سنجش‌پذیر» نیست: «اعتماد» در «بافت» «تحلیل» «ساخته» می‌شود و «اندازه‌گیری» آن «دشواری» است. ۴. «پیمایش» و «بافت»: «سؤال» در «پیمایش»، «بافت» «تحلیل» است: «سؤال» «بافت» «پاسخ» را «تعیین» می‌کند:', '280e67c4bbdb9012c36b674e708f8afa625998809e3cc47beeb1014dd38f5215', 541, 'ch-doc-card-73-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='280e67c4bbdb9012c36b674e708f8afa625998809e3cc47beeb1014dd38f5215', token_count=541, vector_point_id='ch-doc-card-73-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-73-9', 'doc-card-73', 'sec-card-73-5', 9, 'مطالعه‌ای درباره اعتماد به اخبار که با پیمایش کمّی، مصاحبه عمیق و تحلیل داده‌های رفتاری ترکیب می‌شود تا به نتیجه‌ای واحد از سه منبع مستقل برسد.', '23ab1eba94333a5bf04a1fdcc3bedf926d27afa6c52fc12713e6c032a2736592', 260, 'ch-doc-card-73-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='23ab1eba94333a5bf04a1fdcc3bedf926d27afa6c52fc12713e6c032a2736592', token_count=260, vector_point_id='ch-doc-card-73-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-73-10', 'doc-card-73', 'sec-card-73-6', 10, 'ترکیب روش‌ها لزوماً به اعتبار بیشتر منجر نمی‌شود، زیرا روش‌های متفاوت ممکن است واقعیت‌های متفاوتی را بسنجند و ناهمخوانی آن‌ها لزوماً خطا نیست. همچنین سه‌سوسازی هزینه و زمان پژوهش را افزایش می‌دهد.', '1c166a04dbf8e3a5f31cebdf17b8208bfc982b7aca95f98916953413b4c10a8e', 356, 'ch-doc-card-73-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1c166a04dbf8e3a5f31cebdf17b8208bfc982b7aca95f98916953413b4c10a8e', token_count=356, vector_point_id='ch-doc-card-73-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-73-11', 'doc-card-73', 'sec-card-73-10', 11, 'کتاب «روش پژوهش در ارتباطات» (بیر و همکاران، ۲۰۰۸)؛ کتاب «تحلیل محتوا» (هایرینگ، ۱۹۶۷)؛ کتاب «نظریه داده بنیادین» (گلایزر و استرأس، ۱۹۶۷)؛ کتاب «قوم‌نگاری و فرهنگ» (انول، ۱۹۸۴).', 'f40602f4e73937c5ab57d913729cc1b6482b7e5ff6a6c5988096f450bd7988a5', 321, 'ch-doc-card-73-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f40602f4e73937c5ab57d913729cc1b6482b7e5ff6a6c5988096f450bd7988a5', token_count=321, vector_point_id='ch-doc-card-73-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-730-0', 'doc-card-730', NULL, 0, 'نفوذ همه‌جانبه و عمیق منطق‌های اقتصادی، زیرساختی و حاکمیتی پلتفرم‌های بزرگ دیجیتال به تاروپود تولید فرهنگ و خدمات اجتماعی. در این شرایط، تولیدکنندگان محتوا و رسانه‌ها ناچارند تولیدات خود را در قالب «کالاهای مشروط به الگوریتم» بازتعریف کنند.', '26d73881303da5e3f617e561755fea6c10b027c6874380950a71f96448d5e7e9', 436, 'ch-doc-card-730-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='26d73881303da5e3f617e561755fea6c10b027c6874380950a71f96448d5e7e9', token_count=436, vector_point_id='ch-doc-card-730-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-730-1', 'doc-card-730', 'sec-card-730-1', 1, 'مطالعات نرم‌افزار و پلتفرم / جامعه‌شناسی زیرساخت دیجیتال  نفوذ همه‌جانبه و عمیق منطق‌های اقتصادی، زیرساختی و حاکمیتی پلتفرم‌های بزرگ دیجیتال به تاروپود تولید فرهنگ و خدمات اجتماعی. در این شرایط، تولیدکنندگان محتوا و رسانه‌ها ناچارند تولیدات خود را در قالب «کالاهای مشروط به الگوریتم» بازتعریف کنند.', '8750699e2c59d25c2d1919a5a7b9a8f2e36f36bda8e55ef7710cc24cb51ba2bb', 541, 'ch-doc-card-730-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8750699e2c59d25c2d1919a5a7b9a8f2e36f36bda8e55ef7710cc24cb51ba2bb', token_count=541, vector_point_id='ch-doc-card-730-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-730-2', 'doc-card-730', 'sec-card-730-2', 2, '۱. بنیان و منطق نظری پلتفرمی‌شدن اینترنت و پلتفرم‌های دیجیتال را محیط رسانه‌ای تازه‌ای می‌داند که منطق ارتباط، تولید و تبادل را دگرگون کرده است. آن هلموند (۲۰۱۵) استدلال کرد که در عصر شبکه، واحد تحلیل دیگر پیام یا کانال نیست، بلکه پلتفرم است: زیرساخت فنی-اقتصادی که کاربران، محتوا و سرمایه را به هم وصل می‌کند. در این چارچوب، خودِ طراحی زیرساخت — پروتکل، کارکرد و الگوریتم — رفتار اجتماعی را شکل می‌دهد، نه صرفاَ محتوای عبوری.  بر اساس پلتفرمی‌شدن، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است.', '1f536cd689e7d1b2d86cd3b2417b33cf2762ad9045ff59056121c2cf976127d8', 949, 'ch-doc-card-730-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1f536cd689e7d1b2d86cd3b2417b33cf2762ad9045ff59056121c2cf976127d8', token_count=949, vector_point_id='ch-doc-card-730-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-730-3', 'doc-card-730', 'sec-card-730-2', 3, '‌شدن، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است. آن هلموند (۲۰۱۵) فرایندی را تحلیل کرد که فناوری تازه، از ورود و پذیرش، به زندگی روزمره می‌آمیزد، نقش‌ها و روابط را بازنشانی می‌کند و سرانجام «طبیعی» به نظر می‌رسد. ادعای محوری این است که هر نوسازی فناورانه با یک بازنشانی نظم اجتماعی همراه است و مطالعه‌ی فناوری را نمی‌توان از مطالعه‌ی قدرت، اقتصاد و فرهنگ جدا کرد.  پلتفرمی‌شدن پلتفرم را بوم‌زمینه‌ای چندوجهی می‌داند که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند.', 'b9643ee5231490dd46cb850039f9b72d1ea9927a2def1b610e84a8bc29ed0cd3', 952, 'ch-doc-card-730-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b9643ee5231490dd46cb850039f9b72d1ea9927a2def1b610e84a8bc29ed0cd3', token_count=952, vector_point_id='ch-doc-card-730-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-730-4', 'doc-card-730', 'sec-card-730-2', 4, 'د که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند. آن هلموند (۲۰۱۵) تأکید کرد که پلتفرم هم‌زمان فناوری، بازار و شیوه‌ی حکمرانی است و قدرت آن از کنترل بر «قوانین بازی» — چشم‌اندازی، دسترسی و معامله — می‌آید. این رویکرد، تحلیل پلتفرم را در تقاطع جامعه‌شناسی فناوری، اقتصاد و حکمرانی جای می‌دهد.  ۲. ساختارهای مفهومی • پلتفرم (Platform): زیرساخت دیجیتالی که بازیگران متعدد را گرد هم می‌آورد و تعامل آن‌ها را میانجی می‌کند. • کارکرد/امکان (Affordance): قابلیت‌های کنشی که طراحی فناوری به کاربر پیشنهاد می‌دهد و عادت‌های او را شکل می‌دهد. • اثر شبکه‌ای (Network Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود.', 'ce20cefefaeacde18ba6c8be21e2f4e6e93fe57b79ad931f90fd3b7f80180f20', 1209, 'ch-doc-card-730-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ce20cefefaeacde18ba6c8be21e2f4e6e93fe57b79ad931f90fd3b7f80180f20', token_count=1209, vector_point_id='ch-doc-card-730-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-730-5', 'doc-card-730', 'sec-card-730-2', 5, 'Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود. • حکمرانی الگوریتمی (Algorithmic Governance): فرایندی که الگوریتم‌ها درباره‌ی چشم‌اندازی، اولویت‌بندی و دسترسی تصمیم می‌گیرند. • زیرساخت دیجیتال (Digital Infrastructure): لایه‌ی فنی پایینی (سرور، پروتکل، شبکه) که خدمات بر آن ساخته می‌شون', '3f36866eb5d29af58c4080c286e876305fc6838e752cda055dff975529eef8f8', 576, 'ch-doc-card-730-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3f36866eb5d29af58c4080c286e876305fc6838e752cda055dff975529eef8f8', token_count=576, vector_point_id='ch-doc-card-730-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-730-6', 'doc-card-730', 'sec-card-730-3', 6, 'کالای مشروط (Contingent Commodity)، قابلیت برنامه‌ریزی زیرساختی (Programmability)، معماری ماژولار پلتفرم، یکپارچگی داده‌ای APIها، وابستگی زیرساختی.', '100f21e411d5a8b7721330e634cd089757d6081eac8b39313c44269e85df1759', 267, 'ch-doc-card-730-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='100f21e411d5a8b7721330e634cd089757d6081eac8b39313c44269e85df1759', token_count=267, vector_point_id='ch-doc-card-730-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-730-7', 'doc-card-730', 'sec-card-730-4', 7, 'د. • پذیرش (Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن. • شکاف دیجیتال (Digital Divide): نابرابری ساختاری در دسترسی به فناوری دیجیتال، استفاده از آن و بهره‌مندی از آن. • پلتفرمی‌شدن (Platformization): فرایند گسترش منطق و ارزش‌های پلتفرم به حوزه‌های دیگر زندگی اجتماعی.  ۳. نمونه‌های تحلیلی ظهور پلتفرم‌های ویدیویی کوتاه امروز کمتر به کیفیت محتوای تولیدی بازمی‌گردد و بیشتر به طراحی فید الگوریتمی: فید با کارکرد «اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.', 'f6195bf42b868eaf12d6e67637d17585c15411dd293fa67852ceb92665da714e', 939, 'ch-doc-card-730-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f6195bf42b868eaf12d6e67637d17585c15411dd293fa67852ceb92665da714e', token_count=939, vector_point_id='ch-doc-card-730-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-730-8', 'doc-card-730', 'sec-card-730-4', 8, 'اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.  حکمرانی پلتفرم‌های بزرگ — نظارت بر محتوا، تعلیق حساب، اولویت‌بندی در جست‌وجو — در عمل نوعی قدرت شبه‌قضایی بر میلیاردها کاربر است که بدون شفافیت و پاسخگویی معیارهای دولتی اعمال می‌شود.  گوشی‌های هوشمند در عرض چند سال عادات ارتباط اجتماعی، خبرخوانی و خرید را تغییر داده‌اند؛ نمونه‌ی کلاسیکی از اینکه چگونه پذیرش یک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.  جابه‌جایی بسیاری از خدمات عمومی و تجاری به اپلیکیشن‌ها نمونه‌ای از پلتفرمی‌شدن است: منطق امتیازدهی، حساب کاربری و داده وارد حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).', 'cdb4fa11f8d231ff735dedf288a7c9d18381c00e6e762e0b8aaca4fe3338ad00', 1223, 'ch-doc-card-730-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cdb4fa11f8d231ff735dedf288a7c9d18381c00e6e762e0b8aaca4fe3338ad00', token_count=1223, vector_point_id='ch-doc-card-730-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-730-9', 'doc-card-730', 'sec-card-730-4', 9, 'حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).  رقابت صنعت استریم بر «محتوای انحصاری» استراتژی است برای بهره‌گیری از اثر شبکه‌ای: تمرکز مخاطب روی یک پلتفرم، ارزش آن را هم برای کاربران و هم برای تولیدکنندگان بزرگ‌تر می‌کند.  شکاف دیجیتال تنها درباره‌ی دسترسی به اینترنت نیست: تفاوت میان جوانی شهری که محتوا تولید می‌کند و مسنی روستایی که مصرف‌کننده‌ی منفعل است، نشان می‌دهد شکاف در سطح مهارت، زبان و قدرت اقتصادی نیز کار می‌کند.  ۴. نقدها و چالش‌ها ۱. ریسک جبرگرایی فناورانه: چارچوب «طراحی فناوری رفتار را شکل می‌دهد» می‌تواند به غفلت از انتخاب‌های اجتماعی، سیاسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲.', '4c8a35b8d7922ea06254566270f4f2631332f3bdcde0a1e3f70b05a02715fca1', 1218, 'ch-doc-card-730-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4c8a35b8d7922ea06254566270f4f2631332f3bdcde0a1e3f70b05a02715fca1', token_count=1218, vector_point_id='ch-doc-card-730-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-730-10', 'doc-card-730', 'sec-card-730-4', 10, 'اسی و اقتصادی که خودِ طراحی و استفاده از فناوری را تعیین می‌کنند، انجام دهد. ۲. ناهمگنی مفهوم پلتفرم: واژه‌ی پلتفرم از سیستم‌عامل تا بازار آنلاین را پوشش می‌دهد و نتی', 'e75590837c1e11fba8af07f65ca397710f42da898b07ca4b2de9a7f1111cb4d4', 301, 'ch-doc-card-730-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e75590837c1e11fba8af07f65ca397710f42da898b07ca4b2de9a7f1111cb4d4', token_count=301, vector_point_id='ch-doc-card-730-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-730-11', 'doc-card-730', 'sec-card-730-5', 11, 'وابستگی کامل روزنامه‌ها، اینفلوئنسرها و ناشران موسیقی به سازوکارهای توزیع، رتبه‌بندی و سهم درآمدی پلتفرم‌های یوتیوب، اپل، اسپاتیفای و اینستاگرام.', 'c2ef92a5d7592bf9dca0873a219a5034a9204a4d5d84e9ea28fe15fd096f20f0', 263, 'ch-doc-card-730-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c2ef92a5d7592bf9dca0873a219a5034a9204a4d5d84e9ea28fe15fd096f20f0', token_count=263, vector_point_id='ch-doc-card-730-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-730-12', 'doc-card-730', 'sec-card-730-6', 12, 'تمرکز نهادی و زیرساختی این نظریه گاه نقش فعالانه کاربران و تاکتیک‌های آگاهانه آنان را برای دور زدن و فریب دادن الگوریتم‌های حاکم دست‌کم می‌گیرد.', '2aa3a85f3de7fc542a8955b20c4162757029979350e27ef13cf64c6393d8a297', 261, 'ch-doc-card-730-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2aa3a85f3de7fc542a8955b20c4162757029979350e27ef13cf64c6393d8a297', token_count=261, vector_point_id='ch-doc-card-730-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-730-13', 'doc-card-730', 'sec-card-730-10', 13, 'مقاله اثرگذار «پلتفرمی‌شدن تولید رسانه: یک چارچوب تحلیلی» (دیوید نیبورگ و توماس پول، ۲۰۱۹)؛ «پلتفرمی‌شدن وب» (آن هلموند، ۲۰۱۵).', 'd7ca4740be72aabbb09135db10ce908e9e89dfb6472f83885a448985bb43fd98', 230, 'ch-doc-card-730-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d7ca4740be72aabbb09135db10ce908e9e89dfb6472f83885a448985bb43fd98', token_count=230, vector_point_id='ch-doc-card-730-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-731-0', 'doc-card-731', NULL, 0, 'در بسترهای شبکه‌ای مانند توییتر و اینستاگرام، اجتماعات انسانی بیش از آنکه حول استدلال‌های عقلانی هابرماسی گرد آیند، از طریق «هم‌طنین‌شدن احساسات، خشم‌ها و عواطف مشترک» شکل می‌گیرند. این عواطف موج‌های آنی همبستگی خلق می‌کنند که به سرعت فراگیر می‌شوند اما حفظ پیوند نهادی آن‌ها …', '57fa9e1f61a8d6f96652e69395d1023e3495dc09c6665b808541cc6be5b563a8', 503, 'ch-doc-card-731-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='57fa9e1f61a8d6f96652e69395d1023e3495dc09c6665b808541cc6be5b563a8', token_count=503, vector_point_id='ch-doc-card-731-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-731-1', 'doc-card-731', 'sec-card-731-1', 1, 'مطالعات رسانه‌های اجتماعی / نظریه عواطف در ارتباطات سیاسی  در بسترهای شبکه‌ای مانند توییتر و اینستاگرام، اجتماعات انسانی بیش از آنکه حول استدلال‌های عقلانی هابرماسی گرد آیند، از طریق «هم‌طنین‌شدن احساسات، خشم‌ها و عواطف مشترک» شکل می‌گیرند. این عواطف موج‌های آنی همبستگی خلق می‌کنند که به سرعت فراگیر می‌شوند اما حفظ پیوند نهادی آن‌ها دشوار است.', '70a03358d7a8523847cd57ce92caec2dcad926bd432bb9e19e032be30158281f', 627, 'ch-doc-card-731-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='70a03358d7a8523847cd57ce92caec2dcad926bd432bb9e19e032be30158281f', token_count=627, vector_point_id='ch-doc-card-731-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-731-2', 'doc-card-731', 'sec-card-731-2', 2, '۱. بنیان و منطق نظری عمومیت‌های عاطفی «شبکه» را «ساختار» روابط می‌داند: نه «محتوا» بلکه «ارتباط» در کانون است. زیزی پاپاچاریسی (۲۰۱۵) در این چارچوب، «رفتار» را نه «ویژگی» فرد بلکه «محصول» «موقعیت» در شبکه تعریف کرد: «چه کسی» به «چه کسی» وصل است، «رفتار» را «شکل» می‌دهد.  بر اساس عمومیت‌های عاطفی، «شبکه‌های اجتماعی» «میدان» تولید «معنا»، «اعتبار» و «قدرت»‌اند: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت» در شبکه، «ارزش» دارد. زیزی پاپاچاریسی (۲۰۱۵) در این چارچوب، «رسانه» را نه «پخش‌کننده» بلکه «میانجی» شبکه خواند: «رسانه»، «موقعیت» شبکه‌ای مخاطب را «بازتولید» می‌کند.', '667c72b496d98e6d8c585782fb69e3becf36183936c1b251e02bab96ea8ad66e', 1038, 'ch-doc-card-731-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='667c72b496d98e6d8c585782fb69e3becf36183936c1b251e02bab96ea8ad66e', token_count=1038, vector_point_id='ch-doc-card-731-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-731-3', 'doc-card-731', 'sec-card-731-2', 3, 'لکه «میانجی» شبکه خواند: «رسانه»، «موقعیت» شبکه‌ای مخاطب را «بازتولید» می‌کند.  عمومیت‌های عاطفی را می‌توان پاسخی به شکاف میان «تحلیل فرد» و «تحلیل ساختار» دانست: «رفتار»، «محصول» «شبکه» است و «تغییر»، «تغییر» «موقعیت» است. زیزی پاپاچاریسی (۲۰۱۵) در این چارچوب، «شبکه» را نه «ابزار» بلکه «بافت» تعریف کرد: «بافت» شبکه‌ای، «هویت» و «رفتار» را «بازتولید» می‌کند.  ۲. ساختارهای مفهومی • ساختار شبکه (Network Structure): «الگو» روابط بین «گره‌ها» (فرد، رسانه، نهاد)؛ «ساختار»، «رفتار» را «شکل» می‌دهد. • گره و پیوند (Node and Tie): «گره» (فرد، رسانه) و «پیوند» (ارتباط)؛ «پیوند» «جریان» «معنا» و «سرمایه» است.', 'c9cb5566804b1150abeefa900386ee83e1027b888a197cb1bb84c54b58db1b90', 1100, 'ch-doc-card-731-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c9cb5566804b1150abeefa900386ee83e1027b888a197cb1bb84c54b58db1b90', token_count=1100, vector_point_id='ch-doc-card-731-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-731-4', 'doc-card-731', 'sec-card-731-2', 4, ': «گره» (فرد، رسانه) و «پیوند» (ارتباط)؛ «پیوند» «جریان» «معنا» و «سرمایه» است. • سرمایه شبکه‌ای (Network Capital): «ارزش» «موقعیت» در شبکه؛ «ارتباط» «اجتماعی»، «سرمایه» است. • اثر شبکه‌ای (Network Effect): «بزرگ‌تر» شدن «ارزش» شبکه با «افزایش» «عضو»؛ «محصول» و «بازار» یکجا می‌شوند. • حلقه اجتماعی (Social Loop): «جریان» «محتوا» در «حلقه»‌های «اجتماعی»: «اشتراک‌گذاری» و «تایید»، «اعتبار» می‌سازد. • تأثیرگر (Influencer): «گره» «کلیدی» در شبکه که «محتوا» را «بازتو', '0997bda21ff2e2dd57cb195206da8db119a02a9e41ae493b76e288b4c5be9caa', 845, 'ch-doc-card-731-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0997bda21ff2e2dd57cb195206da8db119a02a9e41ae493b76e288b4c5be9caa', token_count=845, vector_point_id='ch-doc-card-731-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-731-5', 'doc-card-731', 'sec-card-731-3', 5, 'اتصال عاطفی (Affective Attunement)، ریتم‌های هشتگی (Hashtagged Rhythms)، بازگویی روایی، ساختار احساسات دیجیتال، کنش متصل (Connective Action).', '9746feac29bf1ca674d4429c4f12888132b139ce7f7b09a75a5a529681806251', 256, 'ch-doc-card-731-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9746feac29bf1ca674d4429c4f12888132b139ce7f7b09a75a5a529681806251', token_count=256, vector_point_id='ch-doc-card-731-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-731-6', 'doc-card-731', 'sec-card-731-4', 6, 'لید» می‌کند؛ «اعتبار» شخصی، «سرمایه» شبکه‌ای است. • بافت شبکه‌ای (Networked Context): «بافت» که در آن «رفتار» و «هویت» «بازتولید» می‌شوند؛ «بافت»، «ساختار» است. • جریان اطلاعات (Information Flow): «جریان» «محتوا» در شبکه: «مسیر»، «سرعت» و «حجم» «جریان»، «بازتولید» «معنا» است.  ۳. نمونه‌های تحلیلی «ساختار شبکه» در عمل: وقتی «خبر» در «شبکه‌ی اجتماعی» «گسترش» می‌یابد، «مسیر» آن از «گره»‌های «کلیدی» (تأثیرگرها) است: «ساختار»، «جریان» را «تعیین» می‌کند.  «سرمایه شبکه‌ای» در عمل: «اعتبار» یک «تأثیرگر» از «موقعیت» او در شبکه است: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت»، «ارزش» دارد.', 'b9bf8f7b0b6c176ceef33672b3086fbf3a571911a6bd861437a908f93a03d51a', 1065, 'ch-doc-card-731-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b9bf8f7b0b6c176ceef33672b3086fbf3a571911a6bd861437a908f93a03d51a', token_count=1065, vector_point_id='ch-doc-card-731-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-731-7', 'doc-card-731', 'sec-card-731-4', 7, 'عیت» او در شبکه است: «ارتباط» «اجتماعی»، «سرمایه» است و «موقعیت»، «ارزش» دارد.  «اثر شبکه‌ای» در «فیسبوک»: هر «عضو» جدیدی که «می‌آید»، «ارزش» شبکه را برای «همه» «بالاتر» می‌برد: «محصول» و «بازار» یکجا می‌شوند.  «حلقه اجتماعی» در عمل: «اشتراک‌گذاری» یک «خبر» در «حلقه» «دوستان»، «اعتبار» «اجتماعی» می‌سازد: «تایید» «اجتماعی»، «جریان» را «بازتولید» می‌کند.  «تأثیرگر» در «اینستاگرام»: «اعتبار» شخصی «تأثیرگر»، «سرمایه» شبکه‌ای است: «محتوا» او از «موقعیت» او در شبکه «جریان» می‌یابد.  «بافت شبکه‌ای» در عمل: «هویت» «دیجیتال» یک «کاربر» در «بافت» شبکه «بازتولید» می‌شود: «رفتار» و «هویت»، «محصول» «ساختار» است.  ۴. نقدها و چالش‌ها ۱.', '399c48d251f87ea37c6ae3f34383931c054216b738810f83e6b5bec01decfea5', 1143, 'ch-doc-card-731-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='399c48d251f87ea37c6ae3f34383931c054216b738810f83e6b5bec01decfea5', token_count=1143, vector_point_id='ch-doc-card-731-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-731-8', 'doc-card-731', 'sec-card-731-4', 8, 'ازتولید» می‌شود: «رفتار» و «هویت»، «محصول» «ساختار» است.  ۴. نقدها و چالش‌ها ۱. «شبکه» و «محتوا» از هم جدا نمی‌شوند: «تحلیل» صرف «ساختار»، «محتوا» را «محو» می‌کند: «محتوا» و «ساختار» در هم تنیده‌اند. ۲. «سرمایه شبکه‌ای» «سنجش‌پذیر» نیست: «ارزش» «موقعیت» در شبکه، «شاخص» واحد ندارد و «اندازه‌گیری» آن «دشواری» است. ۳. «اثر شبکه‌ای» «نامتقارن» است: «بزرگ‌تر» شدن شبکه، «ارزش» را «افزایش» می‌دهد اما «ارزش»، «توزیع» نمی‌شود: «مرک', '1a903c82e515afa2f3536ea9846aded6e7d45b0b8d6cb385641c1e85ec14daae', 774, 'ch-doc-card-731-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1a903c82e515afa2f3536ea9846aded6e7d45b0b8d6cb385641c1e85ec14daae', token_count=774, vector_point_id='ch-doc-card-731-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-731-9', 'doc-card-731', 'sec-card-731-5', 9, 'موج‌های اعتراضی توییتر پیرامون هشتگ‌هایی نظیر MeToo یا BlackLivesMatter که به سرعت هزاران کاربر را با بار هیجانی مشترک بسیج کردند.', '24b21ddb3b9e2491a2badcfd65ac3ab74f067f4de0f14845caa3d952a7dfcca2', 236, 'ch-doc-card-731-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='24b21ddb3b9e2491a2badcfd65ac3ab74f067f4de0f14845caa3d952a7dfcca2', token_count=236, vector_point_id='ch-doc-card-731-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-731-10', 'doc-card-731', 'sec-card-731-6', 10, 'سیال بودن و ماندگاری ضعیف این تشکل‌ها؛ پیوندهای عاطفی آنلاین اغلب توان تبدیل شدن به نهادهای سیاسی مانا و چانه‌زنی واقعی در قانون‌گذاری را ندارند.', '1e154ff619b3304672931f9cba853ad4097262da1790df33df2915ed2f948d3a', 263, 'ch-doc-card-731-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1e154ff619b3304672931f9cba853ad4097262da1790df33df2915ed2f948d3a', token_count=263, vector_point_id='ch-doc-card-731-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-731-11', 'doc-card-731', 'sec-card-731-10', 11, 'کتاب جریان‌ساز «عمومیت‌های عاطفی: احساسات، فناوری و سیاست» (زیزی پاپاچاریسی، ۲۰۱۵).', 'b0519247c9fda083d0157737469507937c5666f757341ccd041c63a0be60c66a', 150, 'ch-doc-card-731-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b0519247c9fda083d0157737469507937c5666f757341ccd041c63a0be60c66a', token_count=150, vector_point_id='ch-doc-card-731-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-74-0', 'doc-card-74', NULL, 0, 'زبان بخشی از کنش اجتماعی است و قدرت، ایدئولوژی و روابط نابرابر را بازتولید یا به چالش می‌کشد. فرکلاف تحلیل را در سه سطح پیش می‌برد: توصیف متن، تفسیر فرایند تولید و مصرف متن، و تبیین بافت اجتماعی گسترده‌تر. هدف آشکارسازی روابط قدرتِ پنهان در انتخاب واژه، ساخت جمله و چارچوب‌های …', 'fc37c0a4ff4dbe807045a72b05007daa014e294ec724e1dc609c7c48f744db6f', 505, 'ch-doc-card-74-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fc37c0a4ff4dbe807045a72b05007daa014e294ec724e1dc609c7c48f744db6f', token_count=505, vector_point_id='ch-doc-card-74-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-74-1', 'doc-card-74', 'sec-card-74-1', 1, 'زبان‌شناسی انتقادی / مطالعات رسانه  زبان بخشی از کنش اجتماعی است و قدرت، ایدئولوژی و روابط نابرابر را بازتولید یا به چالش می‌کشد. فرکلاف تحلیل را در سه سطح پیش می‌برد: توصیف متن، تفسیر فرایند تولید و مصرف متن، و تبیین بافت اجتماعی گسترده‌تر. هدف آشکارسازی روابط قدرتِ پنهان در انتخاب واژه، ساخت جمله و چارچوب‌های روایی است.', 'f0a18d253ccdb2cdc429625e264c2f2835b0fcf700833d220df9593f0ab1327e', 587, 'ch-doc-card-74-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f0a18d253ccdb2cdc429625e264c2f2835b0fcf700833d220df9593f0ab1327e', token_count=587, vector_point_id='ch-doc-card-74-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-74-2', 'doc-card-74', 'sec-card-74-2', 2, '۱. بنیان و منطق نظری تحلیل گفتمان انتقادی «روش» را «بافت» «معنا» می‌داند: نه «ابزار» «تحلیل» بلکه «بافت» «تحلیل». نورمن فرکلاف (۱۹۹۲) در این چارچوب، «روش» را «بافت» «معرفت» تعریف کرد: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش».  بر اساس تحلیل گفتمان انتقادی، «روش» «دیالکتیک» «نظریه» و «داده» است: «نظریه»، «بافت» «تحلیل» است و «داده»، «بافت» «نظریه». نورمن فرکلاف (۱۹۹۲) در این چارچوب، «روش» را «بافت» «اعتماد» تعریف کرد: «اعتماد» در «روش» «ساخته» می‌شود، نه در «نتیجه».  تحلیل گفتمان انتقادی را می‌توان پاسخی به شکاف میان «روش» «کمّی» (تعمیم) و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش».', '17640242bbb6b3deaf1fb05f11457dc147c6c491fe2f9229b75833ba13c0cc02', 1145, 'ch-doc-card-74-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='17640242bbb6b3deaf1fb05f11457dc147c6c491fe2f9229b75833ba13c0cc02', token_count=1145, vector_point_id='ch-doc-card-74-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-74-3', 'doc-card-74', 'sec-card-74-2', 3, 'و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش». نورمن فرکلاف (۱۹۹۲) در این چارچوب، «روش» را «بافت» «بازی» تعریف کرد: «تحلیل»، «بازی» با «داده» است.  ۲. ساختارهای مفهومی • روش کمّی (Quantitative Method): «اندازه‌گیری» و «تعمیم»: «داده» «عددی» و «تحلیل» «آمار». • روش کیفی (Qualitative Method): «فهم» و «عمق»: «داده» «کیفی» و «تحلیل» «تفسیر». • روش ترکیبی (Mixed Methods): «ترکیب» «کمّی» و «کیفی»: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • پیمایش (Survey): «اندازه‌گیری» «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته». • تحلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن».', 'd365d5c215512a2dc740070845e30e926e47359748467080665a4c2c69c73593', 1163, 'ch-doc-card-74-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d365d5c215512a2dc740070845e30e926e47359748467080665a4c2c69c73593', token_count=1163, vector_point_id='ch-doc-card-74-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-74-4', 'doc-card-74', 'sec-card-74-2', 4, 'حلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن». • نظریه داده بنیادین (Grounded Theory): «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود. • قوم‌نگاری (Ethnography): «فهم» «بافت»: «حضور» در «بافت» و', 'ffe287e340fcd832166c84e91c0ab0350d7cb7476e38468faeb5ce1e54aaf5c7', 430, 'ch-doc-card-74-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ffe287e340fcd832166c84e91c0ab0350d7cb7476e38468faeb5ce1e54aaf5c7', token_count=430, vector_point_id='ch-doc-card-74-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-74-5', 'doc-card-74', 'sec-card-74-3', 5, 'متن؛ رویه گفتمانی؛ کنش اجتماعی؛ ایدئولوژی؛ قدرت؛ بینامتنیت؛ سه سطح تحلیل.', 'e1102b2bcc23270a35f1603bec8a68e8b0b3461d8fcae365ae882c7edd94846e', 132, 'ch-doc-card-74-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e1102b2bcc23270a35f1603bec8a68e8b0b3461d8fcae365ae882c7edd94846e', token_count=132, vector_point_id='ch-doc-card-74-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-74-6', 'doc-card-74', 'sec-card-74-4', 6, '«فهم» «معنا» در «بافت». • اعتبار و قابلیت اطمینان (Validity and Reliability): «اعتماد» در «روش»: «اعتبار» و «قابلیت اطمینان»، «بافت» «اعتماد» است.  ۳. نمونه‌های تحلیلی «روش کمّی» در عمل: «نظرسنجی» از «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته»: «تعمیم» «نتیجه» به «دسته».  «روش کیفی» در عمل: «مصاحبه» «عمیق» از «دسته‌ی» «کوچک»: «فهم» «معنا» در «بافت» «مصاحبه»: «عمق» «تحلیل».  «پیمایش» در عمل: «پیمایش» «نظر» «مخاطب» از «محتوای» «رسانه»: «سؤال» و «پاسخ» در «بافت» «دسته»: «تعمیم» «نتیجه».  «تحلیل محتوا» در عمل: «تحلیل» «متن» «خبر» از «چارچوب» و «واژه»: «کد» و «فراوانی» در «بافت» «متن»: «تحلیل» «ساختار» «متن».', 'f5df66e6fa242493c80329a08a1ca853cd38299df8f3151d2515f87f6e2656e7', 1121, 'ch-doc-card-74-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f5df66e6fa242493c80329a08a1ca853cd38299df8f3151d2515f87f6e2656e7', token_count=1121, vector_point_id='ch-doc-card-74-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-74-7', 'doc-card-74', 'sec-card-74-4', 7, 'ز «چارچوب» و «واژه»: «کد» و «فراوانی» در «بافت» «متن»: «تحلیل» «ساختار» «متن».  «نظریه داده بنیادین» در عمل: «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود: «تحلیل»، «بازی» با «داده» است.  «قوم‌نگاری» در عمل: «حضور» در «بافت» «مخاطب»: «فهم» «معنا» در «بافت» «مخاطب»: «عمق» «تحلیل» در «بافت» «بومی».  ۴. نقدها و چالش‌ها ۱. «کمّی» و «کیفی» «دیالکتیک»‌اند: «کمّی» «تعمیم» دارد اما «عمق» ندارد و «کیفی» «عمق» دارد اما «تعمیم» ندارد: «روش» «ترکیبی»، «بافت» «دیالکتیک» است. ۲. «روش» و «نظریه» در هم تنیده‌اند: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش»: «روش» «خنثی» وجود ندارد. ۳.', '17842b057ad0f8425860f241c60fd05a93e47f100d43e207106133f550b126e1', 1076, 'ch-doc-card-74-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='17842b057ad0f8425860f241c60fd05a93e47f100d43e207106133f550b126e1', token_count=1076, vector_point_id='ch-doc-card-74-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-74-8', 'doc-card-74', 'sec-card-74-4', 8, '«روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش»: «روش» «خنثی» وجود ندارد. ۳. «اعتبار» در «روش» «کیفی» «سنجش‌پذیر» نیست: «اعتماد» در «بافت» «تحلیل» «ساخته» می‌شود و «اندازه‌گیری» آن «دشواری» است. ۴. «پیمایش» و «بافت»: «سؤال» در «پیمایش»، «بافت» «تحلیل» است: «سؤال» «بافت» «پاسخ» را «تعیین» می‌کند:', '280e67c4bbdb9012c36b674e708f8afa625998809e3cc47beeb1014dd38f5215', 541, 'ch-doc-card-74-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='280e67c4bbdb9012c36b674e708f8afa625998809e3cc47beeb1014dd38f5215', token_count=541, vector_point_id='ch-doc-card-74-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-74-9', 'doc-card-74', 'sec-card-74-5', 9, 'تحلیل واژگان به‌کاررفته در اخبار مربوط به اعتراض‌های اجتماعی، مثل تفاوت «ناآرامی» و «جنبش مدنی»، و نشان دادن اینکه این انتخاب‌ها چگونه مشروعیت کنشگران را تعیین می‌کند.', 'fb0d34944919396c3a4d79b55f40cc5ee9cbcdfb759a0c02ce63f49f373ae8f9', 303, 'ch-doc-card-74-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fb0d34944919396c3a4d79b55f40cc5ee9cbcdfb759a0c02ce63f49f373ae8f9', token_count=303, vector_point_id='ch-doc-card-74-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-74-10', 'doc-card-74', 'sec-card-74-6', 10, 'CDA ممکن است به تفسیر ایدئولوژیک پژوهشگر وابسته شود و یافته‌ها را به سختی بتوان تکرار کرد. همچنین تمرکز بر متن ممکن است از درک تجربه دریافت‌کنندگان دور بماند.', 'b698a8d8fb4b514bf6216f4b7fbaf6645ebe45a38aa413a40e5a41a1ff0f8404', 287, 'ch-doc-card-74-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b698a8d8fb4b514bf6216f4b7fbaf6645ebe45a38aa413a40e5a41a1ff0f8404', token_count=287, vector_point_id='ch-doc-card-74-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-74-11', 'doc-card-74', 'sec-card-74-10', 11, 'استناد علمی مبنا (APA 7): Fairclough (1989, 1995)', 'fcec7c35f555bf0cd974885402557cf43ec276879de5161170adddda7539a401', 89, 'ch-doc-card-74-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fcec7c35f555bf0cd974885402557cf43ec276879de5161170adddda7539a401', token_count=89, vector_point_id='ch-doc-card-74-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-75-0', 'doc-card-75', NULL, 0, 'هر پیام، از جمله تصویر و تبلیغ، نظامی از نشانه‌هاست که در دو سطح معنا می‌سازد: معنای صریح (دلالت) و معنای ضمنی (دلالت ضمنی یا اسطوره). بارت نشان داد که ایدئولوژی اغلب در لایه ضمنی و طبیعی‌نما عمل می‌کند و چنان ارائه می‌شود که گویی بدیهی و بی‌طرف است.', '060153c1afae71b2a786bfa47c40c1cf09b94cf5e3a00d0b3e52491f7f682add', 454, 'ch-doc-card-75-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='060153c1afae71b2a786bfa47c40c1cf09b94cf5e3a00d0b3e52491f7f682add', token_count=454, vector_point_id='ch-doc-card-75-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-75-1', 'doc-card-75', 'sec-card-75-1', 1, 'نشانه‌شناسی ساختارگرا / تحلیل فرهنگی  هر پیام، از جمله تصویر و تبلیغ، نظامی از نشانه‌هاست که در دو سطح معنا می‌سازد: معنای صریح (دلالت) و معنای ضمنی (دلالت ضمنی یا اسطوره). بارت نشان داد که ایدئولوژی اغلب در لایه ضمنی و طبیعی‌نما عمل می‌کند و چنان ارائه می‌شود که گویی بدیهی و بی‌طرف است.', '91537645a1579e3c9800232bae3e8177b3a21c8ef8d74eaecdf1392941090de7', 523, 'ch-doc-card-75-1', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='91537645a1579e3c9800232bae3e8177b3a21c8ef8d74eaecdf1392941090de7', token_count=523, vector_point_id='ch-doc-card-75-1', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-75-2', 'doc-card-75', 'sec-card-75-2', 2, '۱. بنیان و منطق نظری نشانه‌شناسی «روش» را «بافت» «معنا» می‌داند: نه «ابزار» «تحلیل» بلکه «بافت» «تحلیل». رولان بارت (۱۹۶۴) در این چارچوب، «روش» را «بافت» «معرفت» تعریف کرد: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش».  بر اساس نشانه‌شناسی، «روش» «دیالکتیک» «نظریه» و «داده» است: «نظریه»، «بافت» «تحلیل» است و «داده»، «بافت» «نظریه». رولان بارت (۱۹۶۴) در این چارچوب، «روش» را «بافت» «اعتماد» تعریف کرد: «اعتماد» در «روش» «ساخته» می‌شود، نه در «نتیجه».  نشانه‌شناسی را می‌توان پاسخی به شکاف میان «روش» «کمّی» (تعمیم) و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش».', 'd041e5d425a1bcedd55d0fcb8a55a4312d8cdf82f418dbae84fa55f76119fd1f', 1089, 'ch-doc-card-75-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d041e5d425a1bcedd55d0fcb8a55a4312d8cdf82f418dbae84fa55f76119fd1f', token_count=1089, vector_point_id='ch-doc-card-75-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-75-3', 'doc-card-75', 'sec-card-75-2', 3, 'و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش». رولان بارت (۱۹۶۴) در این چارچوب، «روش» را «بافت» «بازی» تعریف کرد: «تحلیل»، «بازی» با «داده» است.  ۲. ساختارهای مفهومی • روش کمّی (Quantitative Method): «اندازه‌گیری» و «تعمیم»: «داده» «عددی» و «تحلیل» «آمار». • روش کیفی (Qualitative Method): «فهم» و «عمق»: «داده» «کیفی» و «تحلیل» «تفسیر». • روش ترکیبی (Mixed Methods): «ترکیب» «کمّی» و «کیفی»: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند. • پیمایش (Survey): «اندازه‌گیری» «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته». • تحلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن».', 'f9237d6701313be76abd8f628e71125ce828847dee8be37d76114080d3bbf96c', 1160, 'ch-doc-card-75-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f9237d6701313be76abd8f628e71125ce828847dee8be37d76114080d3bbf96c', token_count=1160, vector_point_id='ch-doc-card-75-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO ai_chunks (id, document_id, section_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('ch-doc-card-75-4', 'doc-card-75', 'sec-card-75-2', 4, 'حلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن». • نظریه داده بنیادین (Grounded Theory): «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود. • قوم‌نگاری (Ethnography): «فهم» «بافت»: «حضور» در «بافت» و «فهم» «معنا» در «با', 'f5ec3dfde91245cfde4b52391156a02b34fd9ea61b6de4218a48f241719c1d92', 467, 'ch-doc-card-75-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f5ec3dfde91245cfde4b52391156a02b34fd9ea61b6de4218a48f241719c1d92', token_count=467, vector_point_id='ch-doc-card-75-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
